    private static class PressSlotAbnormalLockCycle {

        private final QmsFaiOrderDO abnormalFaiOrder;
        private final QmsFaiOrderDO latestReleaseFaiOrder;
        private final String motherBatchNo;
        private final LocalDateTime lockStartTime;
        private final LocalDateTime releaseTime;

        private PressSlotAbnormalLockCycle(QmsFaiOrderDO abnormalFaiOrder,
                                           QmsFaiOrderDO latestReleaseFaiOrder,
                                           String motherBatchNo,
                                           LocalDateTime lockStartTime,
                                           LocalDateTime releaseTime) {
            this.abnormalFaiOrder = abnormalFaiOrder;
            this.latestReleaseFaiOrder = latestReleaseFaiOrder;
            this.motherBatchNo = motherBatchNo;
            this.lockStartTime = lockStartTime;
            this.releaseTime = releaseTime;
        }

        private boolean released() {
            return releaseTime != null;
        }
    }

