    @Override
    public List<HcFormulaReportTaskRespVO> getFormulaTaskList(HcFormulaReportTaskPageReqVO reqVO) {
        String taskStatus = StrUtil.blankToDefault(reqVO.getTaskStatus(), "ALL");
        List<HcFormulaReportTaskRespVO> rows = hcProcessReportMapper.selectFormulaTaskList(
                taskStatus, reqVO.getTaskKeyword(), reqVO.getProductKeyword(),
                reqVO.getMotherMaterialKeyword(), reqVO.getMotherModelKeyword());
        fillFormulaTaskBatchPreview(rows);
        if (StrUtil.isNotBlank(reqVO.getTaskKeyword())) {
            rows.stream()
                    .filter(row -> StrUtil.contains(row.getPlanNo(), reqVO.getTaskKeyword()))
                    .forEach(row -> log.info(
                            "[MES报工时间加载][配料] planNo={} planOperationId={} operationReportId={} "
                                    + "loadTable=mes_sfc_operation_report loadFields=report_date,start_time,end_time "
                                    + "values reportDate={} startTime={} endTime={} sourceMenuCode={}",
                            row.getPlanNo(), row.getPlanOperationId(), row.getOperationReportId(),
                            row.getProductionDate(), row.getStartTime(), row.getEndTime(), SOURCE_MENU_CODE_FORMULA));
        }
        return rows;
    }

    /**
     * 计划阶段的批号仅为规则预览，不能写入计划批号字段或占用规则流水。
     * 配料待开工列表需展示该预览值，便于现场核对；配料开工后会由正式占号结果覆盖。
     */
    private void fillFormulaTaskBatchPreview(List<HcFormulaReportTaskRespVO> rows) {
        if (CollUtil.isEmpty(rows)) {
            return;
        }
        Set<Long> planIds = rows.stream()
                .filter(this::isFormulaPendingTaskWithoutBatch)
                .map(HcFormulaReportTaskRespVO::getPlanId)
                .filter(Objects::nonNull)
                .collect(Collectors.toSet());
        if (planIds.isEmpty()) {
            return;
        }
        Map<Long, HcPlanOrderDO> plans = hcPlanOrderMapper.selectBatchIds(planIds).stream()
                .collect(Collectors.toMap(HcPlanOrderDO::getId, plan -> plan));
        rows.stream()
                .filter(this::isFormulaPendingTaskWithoutBatch)
                .forEach(row -> fillFormulaTaskBatchPreview(row, plans.get(row.getPlanId())));
    }

    private boolean isFormulaPendingTaskWithoutBatch(HcFormulaReportTaskRespVO task) {
        return StrUtil.equalsIgnoreCase(task.getStatus(), "PENDING")
                && StrUtil.isBlank(task.getProductionBatchNo())
                && StrUtil.isBlank(task.getBatchNo());
    }

    private void fillFormulaTaskBatchPreview(HcFormulaReportTaskRespVO task, HcPlanOrderDO plan) {
        if (plan == null) {
            return;
        }
        HcPlanOrderBatchPreviewReqVO previewReq = new HcPlanOrderBatchPreviewReqVO();
        previewReq.setId(plan.getId());
        previewReq.setPlanDate(plan.getPlanDate());
        previewReq.setProductionStartDate(plan.getProductionStartDate());
        previewReq.setMaterialCode(plan.getMaterialCode());
        previewReq.setCategoryCode(plan.getCategoryCode());
        previewReq.setProdType(plan.getProdType());
        previewReq.setModelCode(plan.getModelCode());
        previewReq.setMotherModelCode(plan.getMotherModelCode());
        previewReq.setBatchRuleId(plan.getBatchRuleId());
        previewReq.setBatchRuleCode(plan.getBatchRuleCode());
        previewReq.setUseBoundRule(true);
        previewReq.setOpCode("FORMULA");
        previewReq.setOpName("配料");
        previewReq.setWorkCenterId(task.getWorkCenterId());
        try {
            HcPlanOrderBatchPreviewRespVO preview = hcPlanOrderService.previewRootBatchNo(previewReq);
            if (preview != null && StrUtil.isNotBlank(preview.getBatchNo())) {
                task.setBatchNo(preview.getBatchNo());
                task.setBatchNoPreview(true);
            }
        } catch (RuntimeException exception) {
            // 历史计划可能未绑定规则或规则已停用，不能因此阻断整个配料任务列表。
            log.warn("[配料任务母批预览失败] planNo={} planId={} planOperationId={}，保留空批号展示：{}",
                    task.getPlanNo(), task.getPlanId(), task.getPlanOperationId(), exception.getMessage());
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long startFormulaReport(HcFormulaReportStartReqVO reqVO) {
        // 与计划下发/编辑统一按计划、工序顺序加锁，避免占号与开工交叉等待。
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectByIdForUpdate(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectByIdForUpdate(reqVO.getPlanOperationId());
        validateLockedFormulaOperation(planOrder, operation);
        if (OP_STATUS_FINISHED.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序已完工，不能再开工");
        }
        if (OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序已开工");
        }
        hcFormulaStationRuntimeService.bind(planOrder, operation, resolveFormulaProductModelCode(planOrder, operation));
        log.info(
                "[MES报工时间开工-接收][配料] planNo={} planId={} planOperationId={} "
                        + "requestFields=reportDate,startTime values reportDate={} startTime={} sourceMenuCode={}",
                planOrder.getPlanNo(), planOrder.getId(), operation.getId(),
                reqVO.getReportDate(), reqVO.getStartTime(), SOURCE_MENU_CODE_FORMULA);
        LocalDate reportDate = reqVO.getReportDate() == null ? LocalDate.now() : reqVO.getReportDate();
        boolean placeholderStartTime = isPlaceholderDateTime(reqVO.getStartTime())
                || isDateOnlyRuntimeDateTime(reqVO.getStartTime(), reportDate);
        boolean placeholderRecorderTime = isPlaceholderDateTime(reqVO.getRecorderTime())
                || isDateOnlyRuntimeDateTime(reqVO.getRecorderTime(), reportDate);
        LocalDateTime normalizedStartTime = normalizeReportDateTime(reqVO.getStartTime(), reportDate);
        LocalDateTime normalizedRecorderTime = normalizeReportDateTime(reqVO.getRecorderTime(), reportDate);
        LocalDateTime now = LocalDateTime.now();
        if (normalizedStartTime == null || placeholderStartTime) {
            normalizedStartTime = now;
        }
        if (normalizedRecorderTime == null || placeholderRecorderTime) {
            normalizedRecorderTime = now;
        }
        Long operatorId = SecurityFrameworkUtils.getLoginUserId();
        String operatorName = firstNotBlank(reqVO.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        HcProductionBatchRequest batchRequest = new HcProductionBatchRequest();
        batchRequest.setPlanId(planOrder.getId());
        batchRequest.setPlanOperationId(operation.getId());
        batchRequest.setBizDate(reportDate);
        batchRequest.setGeneratedTime(normalizedStartTime);
        batchRequest.setOperatorId(operatorId);
        batchRequest.setOperatorName(operatorName);
        HcProductionBatchResult batchResult = hcProductionBatchService.generateRootBatchOnFormulaStart(batchRequest);
        HcProcessReportDO reportDO = HcProcessReportDO.builder()
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .operationStatus(operation.getOperationStatus())
                .operationSeq(operation.getOpSeq())
                .operationCode(operation.getOpCode())
                .operationName(operation.getOpName())
                .workCenterId(operation.getWorkCenterId())
                .workCenterCode(operation.getWorkCenterCode())
                .workCenterName(operation.getWorkCenterName())
                .equipmentId(reqVO.getMixerEquipmentId() != null ? reqVO.getMixerEquipmentId() : operation.getEquipmentId())
                .equipmentCode(firstNotBlank(reqVO.getMixerEquipmentCode(), operation.getEquipmentCode()))
                .equipmentName(firstNotBlank(reqVO.getMixerEquipmentName(), operation.getEquipmentName()))
                .materialId(planOrder.getMaterialId())
                .materialCode(planOrder.getMaterialCode())
                .materialName(planOrder.getMaterialName())
                .motherMaterialId(planOrder.getMotherMaterialId())
                .motherMaterialCode(firstNotBlank(operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode()))
                .motherMaterialName(firstNotBlank(operation.getMotherMaterialName(), planOrder.getMotherMaterialName()))
                .motherModelId(planOrder.getMotherModelId())
                .motherModelCode(firstNotBlank(operation.getMotherModelCode(), planOrder.getMotherModelCode()))
                .motherModelName(firstNotBlank(operation.getMotherModelName(), planOrder.getMotherModelName()))
                .batchNo(firstNotBlank(batchResult.getProductionBatchNo(), planOrder.getBatchNo(), operation.getBatchNo()))
                .productionBatchNo(batchResult.getProductionBatchNo())
                .parentProductionBatchNo(batchResult.getParentProductionBatchNo())
                .productionBatchRuleId(batchResult.getRuleId())
                .productionBatchRuleCode(batchResult.getRuleCode())
                .productionBatchContextJson(batchResult.getContextJson())
                .parentBatchNo(firstNotBlank(batchResult.getParentProductionBatchNo(), operation.getParentBatchNo(), planOrder.getBatchNo()))
                .sampleCode(batchResult.getSampleCode())
                .reportDate(reportDate)
                .startTime(normalizedStartTime)
                .goodQty(BigDecimal.ZERO)
                .scrapQty(BigDecimal.ZERO)
                .recorderName(reqVO.getRecorderName())
                .recorderTime(normalizedRecorderTime)
                .reportUom(firstNotBlank(operation.getUom(), operation.getUnitCode(), operation.getUnitName(), planOrder.getTargetUom()))
                .reportType("START")
                .sourceMenuCode(SOURCE_MENU_CODE_FORMULA)
                .mixerEquipmentId(reqVO.getMixerEquipmentId())
                .mixerEquipmentCode(reqVO.getMixerEquipmentCode())
                .mixerEquipmentName(reqVO.getMixerEquipmentName())
                .foamingEquipmentId(reqVO.getFoamingEquipmentId())
                .foamingEquipmentCode(reqVO.getFoamingEquipmentCode())
                .foamingEquipmentName(reqVO.getFoamingEquipmentName())
                .build();
        hcProcessReportMapper.insert(reportDO);
        log.info(
                "[MES报工时间开工-落库][配料] planNo={} planOperationId={} operationReportId={} "
                        + "saveTable=mes_sfc_operation_report saveFields=report_date,start_time "
                        + "values reportDate={} startTime={} reportType=START sourceMenuCode={}",
                planOrder.getPlanNo(), operation.getId(), reportDO.getId(),
                reportDO.getReportDate(), reportDO.getStartTime(), SOURCE_MENU_CODE_FORMULA);

        HcPlanOrderOperationDO updateObj = new HcPlanOrderOperationDO();
        updateObj.setId(operation.getId());
        updateObj.setOperationStatus(OP_STATUS_RUNNING);
        updateObj.setEquipmentId(reqVO.getMixerEquipmentId() != null ? reqVO.getMixerEquipmentId() : operation.getEquipmentId());
        updateObj.setEquipmentCode(firstNotBlank(reqVO.getMixerEquipmentCode(), operation.getEquipmentCode()));
        updateObj.setEquipmentName(firstNotBlank(reqVO.getMixerEquipmentName(), operation.getEquipmentName()));
        updateObj.setStatusOperatorId(operatorId);
        updateObj.setStatusOperatorName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "system"));
        updateObj.setStatusOperateTime(LocalDateTime.now());
        hcPlanOrderOperationMapper.updateById(updateObj);
        LocalDateTime recordTime = normalizedRecorderTime != null ? normalizedRecorderTime : now;
        hcEquipmentService.occupyEquipment(reqVO.getMixerEquipmentId(), planOrder.getPlanNo(), operation.getOpCode(),
                operation.getOpName(), normalizedStartTime, operatorName, recordTime);
        if (!Objects.equals(reqVO.getFoamingEquipmentId(), reqVO.getMixerEquipmentId())) {
            hcEquipmentService.occupyEquipment(reqVO.getFoamingEquipmentId(), planOrder.getPlanNo(), operation.getOpCode(),
                    operation.getOpName(), normalizedStartTime, operatorName, recordTime);
        }
        return reportDO.getId();
    }

    @Override
    public List<HcWetReportTaskRespVO> getWetTaskList(HcWetReportTaskPageReqVO reqVO) {
        String taskStatus = StrUtil.blankToDefault(reqVO.getTaskStatus(), "ALL");
        List<HcWetReportTaskRespVO> rows = hcProcessReportMapper.selectWetTaskList(
                taskStatus, reqVO.getTaskKeyword(), reqVO.getProductKeyword(),
                reqVO.getMotherMaterialKeyword(), reqVO.getMotherModelKeyword(), reqVO.getProductionDate(),
                reqVO.getEquipmentId(), reqVO.getEquipmentCode());
        rows = filterWetPendingRowsByPreviousReported(rows, taskStatus);
        rows.forEach(this::fillWetTaskQtime);
        rows.forEach(this::fillWetTaskPickQualification);
        if (StrUtil.isNotBlank(reqVO.getTaskKeyword())) {
            rows.stream()
                    .filter(row -> StrUtil.contains(row.getPlanNo(), reqVO.getTaskKeyword()))
                    .forEach(row -> log.info(
                            "[MES报工时间加载][湿法] planNo={} planOperationId={} operationReportId={} "
                                    + "loadTable=mes_sfc_operation_report loadFields=report_date,start_time,end_time "
                                    + "values reportDate={} startTime={} endTime={} sourceMenuCode={}",
                            row.getPlanNo(), row.getPlanOperationId(), row.getOperationReportId(),
                            row.getProductionDate(), row.getStartTime(), row.getEndTime(), SOURCE_MENU_CODE_WET));
        }
        return rows;
    }

    private void fillWetTaskPickQualification(HcWetReportTaskRespVO row) {
        if (!FAI_JUDGMENT_NG.equals(row.getFaiJudgment())) return;
        if (pickQualificationService.isQualified(row.getFaiId(),
                firstNotBlank(row.getProductionBatchNo(), row.getBatchNo()))) {
            row.setFaiJudgment(FAI_JUDGMENT_OK);
            row.setFaiStatus(FAI_STATUS_COMPLETED);
        }
    }

    private List<HcWetReportTaskRespVO> filterWetPendingRowsByPreviousReported(List<HcWetReportTaskRespVO> rows,
                                                                               String taskStatus) {
        if (CollUtil.isEmpty(rows) || !StrUtil.equalsAnyIgnoreCase(taskStatus, "ALL", "PENDING")) {
            return rows;
        }
        return rows.stream()
                .filter(row -> !StrUtil.equalsIgnoreCase(row.getStatus(), "PENDING")
                        || isWetPreviousOperationReported(row))
                .collect(Collectors.toList());
    }

    private boolean isWetPreviousOperationReported(HcWetReportTaskRespVO row) {
        if (row == null) {
            return false;
        }
        if (StrUtil.equalsAnyIgnoreCase(row.getPreviousOperationStatus(), "COMPLETED", "FINISHED")) {
            return true;
        }
        if (row.getPreviousEndTime() != null || row.getPreviousProductionDate() != null) {
            return true;
        }
        if (StrUtil.isNotBlank(row.getPreviousRecorderName())) {
            return true;
        }
        return row.getPreviousGoodQty() != null && row.getPreviousGoodQty().compareTo(BigDecimal.ZERO) > 0;
    }

    private void fillWetTaskQtime(HcWetReportTaskRespVO row) {
        if (row == null) {
            return;
        }
        row.setQtime(hcQtimeEvaluationService.evaluateFormulaToWet(
                row.getPreviousEndTime(),
                row.getStartTime(),
                row.getModelCode(),
                row.getMotherModelCode(),
                row.getProductionBatchNo(),
                row.getParentProductionBatchNo(),
                row.getBatchNo()));
    }

    @Override
    public HcWetWaterChangeApplyRespVO getActiveWetWaterChangeApply() {
        HcWetWaterChangeApplyDO apply = hcWetWaterChangeApplyMapper.selectLatestUnexpired(LocalDate.now());
        return buildWetWaterChangeApplyResp(apply);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcWetWaterChangeApplyRespVO saveWetWaterChangeApply(HcWetWaterChangeApplySaveReqVO reqVO) {
        if (reqVO.getChangeStartDate().isAfter(reqVO.getChangeEndDate())) {
            throw invalidParamException("换水开始日期不能晚于结束日期");
        }
        String status = StrUtil.trimToEmpty(reqVO.getStatus()).toUpperCase();
        if (!Set.of(WET_WATER_CHANGE_STATUS_APPLY, WET_WATER_CHANGE_STATUS_APPROVED).contains(status)) {
            throw invalidParamException("换水申请状态不正确");
        }
        LocalDateTime now = LocalDateTime.now();
        Long currentUserId = SecurityFrameworkUtils.getLoginUserId();
        String currentUserName = firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统");

        if (reqVO.getId() != null) {
            HcWetWaterChangeApplyDO apply = hcWetWaterChangeApplyMapper.selectById(reqVO.getId());
            if (apply == null) {
                throw invalidParamException("换水申请不存在");
            }
            apply.setChangeStartDate(reqVO.getChangeStartDate());
            apply.setChangeEndDate(reqVO.getChangeEndDate());
            apply.setAreaDesc(reqVO.getAreaDesc());
            apply.setStatus(status);
            apply.setApplicantId(firstNotNull(reqVO.getApplicantId(), apply.getApplicantId(), currentUserId));
            apply.setApplicantName(firstNotBlank(reqVO.getApplicantName(), apply.getApplicantName(), currentUserName));
            apply.setApplyTime(reqVO.getApplyTime() == null ? firstNonNullDateTime(apply.getApplyTime(), now) : reqVO.getApplyTime());
            apply.setRemark(reqVO.getRemark());
            apply.setTenantId(firstNotNull(apply.getTenantId(), TenantContextHolder.getTenantId()));
            fillWetWaterChangeConfirmInfo(apply, reqVO, status, now, currentUserId, currentUserName);
            hcWetWaterChangeApplyMapper.updateById(apply);
            return buildWetWaterChangeApplyResp(apply);
        }

        HcWetWaterChangeApplyDO apply = BeanUtil.copyProperties(reqVO, HcWetWaterChangeApplyDO.class);
        apply.setStatus(status);
        apply.setApplicantId(firstNotNull(reqVO.getApplicantId(), currentUserId));
        apply.setApplicantName(firstNotBlank(reqVO.getApplicantName(), currentUserName));
        apply.setApplyTime(reqVO.getApplyTime() == null ? now : reqVO.getApplyTime());
        apply.setTenantId(TenantContextHolder.getTenantId());
        fillWetWaterChangeConfirmInfo(apply, reqVO, status, now, currentUserId, currentUserName);
        hcWetWaterChangeApplyMapper.insert(apply);
        return buildWetWaterChangeApplyResp(apply);
    }

    private void fillWetWaterChangeConfirmInfo(HcWetWaterChangeApplyDO apply, HcWetWaterChangeApplySaveReqVO reqVO,
            String status, LocalDateTime now, Long currentUserId, String currentUserName) {
        if (WET_WATER_CHANGE_STATUS_APPROVED.equals(status)) {
            apply.setConfirmerId(firstNotNull(reqVO.getConfirmerId(), currentUserId));
            apply.setConfirmerName(firstNotBlank(reqVO.getConfirmerName(), currentUserName));
            apply.setConfirmTime(reqVO.getConfirmTime() == null ? now : reqVO.getConfirmTime());
        } else {
            apply.setConfirmerId(null);
            apply.setConfirmerName(null);
            apply.setConfirmTime(null);
        }
    }

    private HcWetWaterChangeApplyRespVO buildWetWaterChangeApplyResp(HcWetWaterChangeApplyDO apply) {
        if (apply == null) {
            return null;
        }
        return BeanUtil.copyProperties(apply, HcWetWaterChangeApplyRespVO.class);
    }

    @Override
    public HcWetFaiRespVO getWetFaiSummary(Long planId, Long planOperationId) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        HcPlanOrderOperationDO operation = validateWetOperation(planOrder, planOperationId);
        HcProcessReportDO latestStartReport = getLatestStartReport(planOperationId, SOURCE_MENU_CODE_WET);
        String taskNo = buildWetTaskNo(planOrder, operation);
        List<QmsFaiOrderDO> faiOrders = qmsFaiOrderMapper.selectAllBySourceReportNoAsc(taskNo, SOURCE_MENU_CODE_WET);
        QmsFaiOrderDO latestFai = faiOrders.isEmpty() ? null : faiOrders.get(faiOrders.size() - 1);
        if (latestFai == null && latestStartReport != null && latestStartReport.getFaiId() != null) {
            latestFai = qmsFaiOrderMapper.selectById(latestStartReport.getFaiId());
            if (latestFai != null) {
                faiOrders = Collections.singletonList(latestFai);
            }
        }
        if (latestFai != null) {
            syncWetReportFaiSummary(latestStartReport, latestFai);
            return buildWetFaiResp(latestFai, latestStartReport, faiOrders);
        }
        return buildWetFaiResp(null, latestStartReport);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcWetFaiRespVO applyWetFai(HcWetFaiApplyReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        HcPlanOrderOperationDO operation = validateWetOperation(planOrder, reqVO.getPlanOperationId());
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("请先完成进站并锁定机台");
        }
        HcProcessReportDO latestStartReport = getLatestStartReport(operation.getId(), SOURCE_MENU_CODE_WET);
        if (latestStartReport == null) {
            throw invalidParamException("当前工序未找到开工记录，不能提交首检申请");
        }
        if (latestStartReport.getEquipmentId() == null && StrUtil.isBlank(latestStartReport.getEquipmentCode())) {
            throw invalidParamException("请先选择并锁定湿法机台");
        }

        String standardMatchMode = FAI_STANDARD_MATCH_PRODUCT_MODEL_PROCESS;
        String motherMaterialCode = firstNotBlank(latestStartReport.getMotherMaterialCode(),
                operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode(),
                latestStartReport.getMaterialCode(), planOrder.getMaterialCode());
        String operationCode = firstNotBlank(latestStartReport.getOperationCode(), operation.getOpCode());
        String operationName = firstNotBlank(latestStartReport.getOperationName(), operation.getOpName());
        String productModel = resolveFaiProductModel(latestStartReport, operation, planOrder);
        if (StrUtil.isBlank(productModel)) {
            throw invalidParamException("当前湿法任务缺少产品型号，无法按产品型号与工段匹配 FAI 检验标准");
        }
        String productBatchNo = firstNotBlank(latestStartReport.getProductionBatchNo(), latestStartReport.getBatchNo(),
                operation.getProductionBatchNo(), planOrder.getProductionBatchNo(), operation.getBatchNo(), planOrder.getBatchNo());
        if (StrUtil.isBlank(productBatchNo)) {
            throw invalidParamException("请先确认批次号，批次号将写入首件检验的产品批次");
        }
        if (StrUtil.isBlank(operationCode) && StrUtil.isBlank(operationName)) {
            throw invalidParamException("当前任务缺少工段信息，无法按产品型号与工段匹配 FAI 检验标准");
        }
        BigDecimal napSampleLength = reqVO.getNapSampleLength();
        if (napSampleLength == null || napSampleLength.compareTo(BigDecimal.ZERO) <= 0) {
            throw invalidParamException("请填写湿法首检 NAP层送检(米)");
        }

        String taskNo = buildWetTaskNo(planOrder, operation);
        QmsFaiOrderDO latestFai = qmsFaiOrderMapper.selectLatestBySourceReportNo(taskNo, SOURCE_MENU_CODE_WET);
        if (latestFai == null && latestStartReport.getFaiId() != null) {
            latestFai = qmsFaiOrderMapper.selectById(latestStartReport.getFaiId());
        }
        if (latestFai != null && !isWetFaiReapplyAllowed(latestFai)) {
            if (FAI_STATUS_COMPLETED.equals(latestFai.getStatus())) {
                throw invalidParamException("当前任务首检已完成，不能重复提交首检申请");
            }
            throw invalidParamException("当前任务已有未完成首检单，请先处理后再提交");
        }
        String triggerReason = firstNotBlank(reqVO.getTriggerReason(),
                latestFai != null && isWetFaiReapplyAllowed(latestFai) ? FAI_TRIGGER_REWORK_RECHECK : FAI_TRIGGER_NEW_ORDER);
        if (latestFai != null && isWetFaiReapplyAllowed(latestFai) && !FAI_TRIGGER_REWORK_RECHECK.equals(triggerReason)) {
            triggerReason = FAI_TRIGGER_REWORK_RECHECK;
        }

        QmsFaiSaveReqVO faiReqVO = new QmsFaiSaveReqVO();
        faiReqVO.setWorkOrderNo(planOrder.getPlanNo());
        faiReqVO.setSourceReportId(latestStartReport.getId());
        faiReqVO.setSourceReportNo(taskNo);
        faiReqVO.setSourceModule(SOURCE_MENU_CODE_WET);
        faiReqVO.setSourceOperationCode(operationCode);
        faiReqVO.setSourceOperationName(operationName);
        faiReqVO.setPlanOrderId(planOrder.getId());
        faiReqVO.setStandardMatchMode(standardMatchMode);
        faiReqVO.setOperationCode(operationCode);
        faiReqVO.setOperationName(operationName);
        faiReqVO.setMachineId(latestStartReport.getEquipmentId());
        faiReqVO.setMachineCode(firstNotBlank(latestStartReport.getEquipmentCode(), operation.getEquipmentCode()));
        faiReqVO.setMachineName(firstNotBlank(latestStartReport.getEquipmentName(), operation.getEquipmentName()));
        faiReqVO.setMaterialId(firstNotNull(latestStartReport.getMotherMaterialId(), operation.getMotherMaterialId(),
                planOrder.getMotherMaterialId(), latestStartReport.getMaterialId(), planOrder.getMaterialId()));
        faiReqVO.setMaterialCode(motherMaterialCode);
        faiReqVO.setMaterialName(firstNotBlank(latestStartReport.getMotherMaterialName(), operation.getMotherMaterialName(), planOrder.getMotherMaterialName()));
        faiReqVO.setSpecification(planOrder.getSizeName());
        faiReqVO.setProductModel(productModel);
        faiReqVO.setProductBatchNo(productBatchNo);
        faiReqVO.setSampleLength(napSampleLength);
        faiReqVO.setProcessCategory(PROCESS_CODE_WET);
        faiReqVO.setSubmissionType(FAI_SUBMISSION_TYPE_MASS_SHIPMENT);
        faiReqVO.setWetSampleType("NAP层送样");
        faiReqVO.setTriggerReason(triggerReason);
        faiReqVO.setStatus(FAI_STATUS_PENDING);
        faiReqVO.setJudgment(FAI_JUDGMENT_PENDING);
        faiReqVO.setSubmissionTime(LocalDateTime.now());
        faiReqVO.setSubmitterName(firstNotBlank(reqVO.getSubmitterName(), SecurityFrameworkUtils.getLoginUserNickname(), latestStartReport.getRecorderName(), "系统"));
        faiReqVO.setRemark(firstNotBlank(reqVO.getRemark(), "湿法报工首检申请"));
        Long faiId = qmsFaiService.createFaiForInspectionPush(faiReqVO);
        QmsFaiOrderDO createdFai = qmsFaiOrderMapper.selectById(faiId);
        syncWetReportFaiSummary(latestStartReport, createdFai);
        List<QmsFaiOrderDO> faiOrders = qmsFaiOrderMapper.selectAllBySourceReportNoAsc(taskNo, SOURCE_MENU_CODE_WET);
        return buildWetFaiResp(createdFai, latestStartReport, faiOrders);
    }

    private void validateWetPoreSelfCheckRecorded(HcPlanOrderOperationDO operation) {
        HcStationRecordDO record = hcStationRecordMapper.selectOneByPlanOperationAndFormCode(
                operation.getId(), WET_PORE_SELF_CHECK_FORM_CODE);
        if (record == null || StrUtil.isBlank(record.getHeaderDataJson())) {
            throw invalidParamException("请先新增泡孔自检记录后再提交湿法报工");
        }
        String docStatus = record.getDocStatus();
        if (!RECORD_STATUS_RECORDED.equals(docStatus) && !RECORD_STATUS_CONFIRMED.equals(docStatus)) {
            throw invalidParamException("请先新增泡孔自检记录后再提交湿法报工");
        }
        try {
            JsonNode root = JsonUtils.parseTree(record.getHeaderDataJson());
            JsonNode records = root == null ? null : root.path("records");
            if (records == null || !records.isArray() || records.size() == 0) {
                throw invalidParamException("请先新增泡孔自检记录后再提交湿法报工");
            }
            for (JsonNode item : records) {
                if (hasWetPoreSelfCheckContent(item)) {
                    return;
                }
            }
        } catch (RuntimeException ex) {
            throw invalidParamException("请先新增泡孔自检记录后再提交湿法报工");
        }
        throw invalidParamException("请先新增泡孔自检记录后再提交湿法报工");
    }

    private boolean hasWetPoreSelfCheckContent(JsonNode item) {
        if (item == null || item.isMissingNode() || item.isNull()) {
            return false;
        }
        return StrUtil.isNotBlank(readJsonText(item, "selfCheckTime"))
                || StrUtil.isNotBlank(readJsonText(item, "selfCheckResult"))
                || StrUtil.isNotBlank(readJsonText(item, "inspector"))
                || StrUtil.isNotBlank(readJsonText(item, "remark"))
                || hasWetPoreSelfCheckPhotos(item);
    }

    private boolean hasWetPoreSelfCheckPhotos(JsonNode item) {
        if (StrUtil.isNotBlank(readJsonText(item, "photo"))) {
            return true;
        }
        JsonNode photos = item == null ? null : item.path("photos");
        if (photos == null || !photos.isArray()) {
            return false;
        }
        for (JsonNode photo : photos) {
            if (StrUtil.isNotBlank(photo.asText())) {
                return true;
            }
        }
        return false;
    }

    private void validateWetGuideClothRuntime(HcGuideClothRuntimeRespVO runtime,
                                               LocalDate reportDate,
                                               Integer effectiveUseCount) {
        if (effectiveUseCount != null && effectiveUseCount >= GUIDE_CLOTH_MAX_USE_COUNT) {
            throw invalidParamException("导布累计使用次数已达到28/28，请先更换导布");
        }
        if (runtime == null || runtime.getReplaceTime() == null || runtime.getReplaceTime().getYear() < 2000) {
            throw invalidParamException("未记录有效的导布更换时间，请先登记导布更换");
        }
        if (isWetGuideClothMonthlyReplacementDue(runtime, reportDate)) {
            throw invalidParamException("导布每月需更换一次，已进入提前3天提醒期，请先登记导布更换");
        }
    }

    private boolean isWetGuideClothMonthlyReplacementDue(HcGuideClothRuntimeRespVO runtime, LocalDate reportDate) {
        LocalDateTime replaceTime = runtime == null ? null : runtime.getReplaceTime();
        if (replaceTime == null || replaceTime.getYear() < 2000) {
            return true;
        }
        LocalDate effectiveReportDate = reportDate == null ? LocalDate.now() : reportDate;
        LocalDate reminderStartDate = replaceTime.toLocalDate().plusMonths(1)
                .minusDays(GUIDE_CLOTH_MONTH_REMIND_BEFORE_DAYS);
        return !effectiveReportDate.isBefore(reminderStartDate);
    }

    private String buildWetTaskNo(HcPlanOrderDO planOrder, HcPlanOrderOperationDO operation) {
        return planOrder.getPlanNo() + "-" + String.format("%02d", operation.getOpSeq() == null ? 0 : operation.getOpSeq());
    }

    private boolean isFaiReapplyAllowed(QmsFaiOrderDO faiOrder) {
        return faiOrder != null && (FAI_STATUS_REJECTED.equals(faiOrder.getStatus()) || FAI_STATUS_CANCELED.equals(faiOrder.getStatus()));
    }

    private boolean isWetFaiReapplyAllowed(QmsFaiOrderDO faiOrder) {
        return faiOrder != null && (FAI_JUDGMENT_NG.equals(faiOrder.getJudgment())
                || FAI_STATUS_CANCELED.equals(faiOrder.getStatus()));
    }

    private boolean isFaiReleased(QmsFaiOrderDO faiOrder) {
        return faiOrder != null && ((FAI_STATUS_COMPLETED.equals(faiOrder.getStatus()) && FAI_JUDGMENT_OK.equals(faiOrder.getJudgment()))
                || pickQualificationService.isQualified(faiOrder, faiOrder.getProductBatchNo()));
    }

    /**
     * 压槽报工只校验送检是否成功创建，不以 QMS 检验结论作为生产报工前置条件。
     * 已取消、已驳回的检验单视为无效，需重新送检。
     */
    private boolean isPressSlotFaiSubmitted(QmsFaiOrderDO faiOrder) {
        if (faiOrder == null) {
            return false;
        }
        String status = StrUtil.trimToEmpty(faiOrder.getStatus());
        return FAI_STATUS_PENDING.equals(status)
                || FAI_STATUS_INSPECTING.equals(status)
                || FAI_STATUS_WAITING_QA.equals(status)
                || FAI_STATUS_COMPLETED.equals(status);
    }

    private boolean isFaiRejectedNg(QmsFaiOrderDO faiOrder) {
        return faiOrder != null && FAI_STATUS_REJECTED.equals(faiOrder.getStatus())
                && FAI_JUDGMENT_NG.equals(faiOrder.getJudgment());
    }

    private void syncWetReportFaiSummary(HcProcessReportDO wetReport, QmsFaiOrderDO faiOrder) {
        if (wetReport == null || faiOrder == null || faiOrder.getId() == null) {
            return;
        }
        HcProcessReportDO updateObj = new HcProcessReportDO();
        updateObj.setId(wetReport.getId());
        updateObj.setFaiId(faiOrder.getId());
        updateObj.setFaiNo(faiOrder.getFaiNo());
        updateObj.setFaiStatus(faiOrder.getStatus());
        updateObj.setFaiJudgment(faiOrder.getJudgment());
        updateObj.setFaiStandardId(faiOrder.getStandardId());
        updateObj.setFaiStandardNo(faiOrder.getStandardNo());
        updateObj.setFaiApplyTime(firstNotNullDateTime(faiOrder.getSubmissionTime(), faiOrder.getCreateTime(), wetReport.getFaiApplyTime(), LocalDateTime.now()));
        updateObj.setFaiReturnTime(firstNotNullDateTime(faiOrder.getUpdateTime(), LocalDateTime.now()));
        // 首检切换后原因可能为空，必须显式写入 NULL，避免保留上一张首检的 NG 说明。
        hcProcessReportMapper.update(updateObj, new LambdaUpdateWrapper<HcProcessReportDO>()
                .eq(HcProcessReportDO::getId, wetReport.getId())
                .set(HcProcessReportDO::getFaiRejectReason, faiOrder.getLastReturnReason()));
        updateObj.setFaiRejectReason(faiOrder.getLastReturnReason());

        wetReport.setFaiId(updateObj.getFaiId());
        wetReport.setFaiNo(updateObj.getFaiNo());
        wetReport.setFaiStatus(updateObj.getFaiStatus());
        wetReport.setFaiJudgment(updateObj.getFaiJudgment());
        wetReport.setFaiStandardId(updateObj.getFaiStandardId());
        wetReport.setFaiStandardNo(updateObj.getFaiStandardNo());
        wetReport.setFaiApplyTime(updateObj.getFaiApplyTime());
        wetReport.setFaiReturnTime(updateObj.getFaiReturnTime());
        wetReport.setFaiRejectReason(updateObj.getFaiRejectReason());
    }

    private HcWetFaiRespVO buildWetFaiResp(QmsFaiOrderDO faiOrder, HcProcessReportDO wetReport) {
        return buildWetFaiResp(faiOrder, wetReport,
                faiOrder == null ? Collections.emptyList() : Collections.singletonList(faiOrder));
    }

    private HcWetFaiRespVO buildWetFaiResp(QmsFaiOrderDO faiOrder, HcProcessReportDO wetReport,
                                           List<QmsFaiOrderDO> faiOrders) {
        HcWetFaiRespVO respVO = new HcWetFaiRespVO();
        if (faiOrder != null) {
            respVO.setFaiId(faiOrder.getId());
            respVO.setFaiNo(faiOrder.getFaiNo());
            respVO.setFaiStatus(faiOrder.getStatus());
            respVO.setFaiJudgment(faiOrder.getJudgment());
            respVO.setTriggerReason(faiOrder.getTriggerReason());
            respVO.setFaiStandardId(faiOrder.getStandardId());
            respVO.setFaiStandardNo(faiOrder.getStandardNo());
            respVO.setFaiStandardVersion(faiOrder.getStandardVersion());
            respVO.setFaiApplyTime(firstNotNullDateTime(faiOrder.getSubmissionTime(), faiOrder.getCreateTime(), wetReport == null ? null : wetReport.getFaiApplyTime()));
            respVO.setFaiReturnTime(firstNotNullDateTime(faiOrder.getUpdateTime(), wetReport == null ? null : wetReport.getFaiReturnTime()));
            respVO.setProductBatchNo(firstNotBlank(faiOrder.getProductBatchNo(),
                    wetReport == null ? null : wetReport.getProductionBatchNo(),
                    wetReport == null ? null : wetReport.getBatchNo()));
            respVO.setNapSampleLength(faiOrder.getSampleLength());
            // 明确关联首检时，说明与状态必须来自同一张单据。
            respVO.setFaiRejectReason(faiOrder.getLastReturnReason());
            respVO.setAllowReportSubmit(isFaiReleased(faiOrder));
        } else if (wetReport != null) {
            respVO.setFaiId(wetReport.getFaiId());
            respVO.setFaiNo(wetReport.getFaiNo());
            respVO.setFaiStatus(wetReport.getFaiStatus());
            respVO.setFaiJudgment(wetReport.getFaiJudgment());
            respVO.setFaiStandardId(wetReport.getFaiStandardId());
            respVO.setFaiStandardNo(wetReport.getFaiStandardNo());
            respVO.setFaiApplyTime(wetReport.getFaiApplyTime());
            respVO.setFaiReturnTime(wetReport.getFaiReturnTime());
            respVO.setProductBatchNo(firstNotBlank(wetReport.getProductionBatchNo(), wetReport.getBatchNo()));
            respVO.setFaiRejectReason(wetReport.getFaiRejectReason());
            respVO.setAllowReportSubmit(FAI_STATUS_COMPLETED.equals(wetReport.getFaiStatus()) && FAI_JUDGMENT_OK.equals(wetReport.getFaiJudgment()));
        } else {
            respVO.setAllowReportSubmit(false);
        }
        respVO.setDisplayText(resolveWetReportFaiDisplayText(respVO.getFaiStatus(), respVO.getFaiJudgment()));
        var qualification = pickQualificationService.qualification(
                faiOrder == null ? null : faiOrder.getId(), respVO.getProductBatchNo());
        if (qualification == cn.iocoder.yudao.module.mes.service.qms.QmsNcPickQualificationService.Qualification.QUALIFIED) {
            respVO.setFaiJudgment("OK");
            respVO.setFaiStatus(FAI_STATUS_COMPLETED);
            respVO.setDisplayText("合格（处置后，原始检验NG）");
        } else if (qualification == cn.iocoder.yudao.module.mes.service.qms.QmsNcPickQualificationService.Qualification.PARTIAL) {
            respVO.setDisplayText("部分处置合格，未覆盖加工段仍为NG");
        }
        respVO.setRecords(buildWetFaiRecords(faiOrders, wetReport, respVO.getFaiId()));
        return respVO;
    }

    private List<HcWetFaiRecordRespVO> buildWetFaiRecords(List<QmsFaiOrderDO> faiOrders,
                                                          HcProcessReportDO wetReport,
                                                          Long currentFaiId) {
        if (faiOrders == null || faiOrders.isEmpty()) {
            return Collections.emptyList();
        }
        return faiOrders.stream()
                .map(faiOrder -> buildWetFaiRecord(faiOrder, wetReport, Objects.equals(faiOrder.getId(), currentFaiId)))
                .collect(Collectors.toList());
    }

    private HcWetFaiRecordRespVO buildWetFaiRecord(QmsFaiOrderDO faiOrder, HcProcessReportDO wetReport, boolean current) {
        HcWetFaiRecordRespVO respVO = new HcWetFaiRecordRespVO();
        respVO.setFaiId(faiOrder.getId());
        respVO.setFaiNo(faiOrder.getFaiNo());
        respVO.setFaiStatus(faiOrder.getStatus());
        respVO.setFaiJudgment(faiOrder.getJudgment());
        respVO.setFaiStandardId(faiOrder.getStandardId());
        respVO.setFaiStandardNo(faiOrder.getStandardNo());
        respVO.setFaiStandardVersion(faiOrder.getStandardVersion());
        respVO.setFaiApplyTime(firstNotNullDateTime(faiOrder.getSubmissionTime(), faiOrder.getCreateTime()));
        respVO.setFaiReturnTime(faiOrder.getUpdateTime());
        respVO.setProductBatchNo(faiOrder.getProductBatchNo());
        respVO.setNapSampleLength(faiOrder.getSampleLength());
        respVO.setFaiRejectReason(faiOrder.getLastReturnReason());
        respVO.setDisplayText(resolveWetReportFaiDisplayText(respVO.getFaiStatus(), respVO.getFaiJudgment()));
        respVO.setAllowReportSubmit(current && isFaiReleased(faiOrder));
        var qualification = pickQualificationService.qualification(
                faiOrder == null ? null : faiOrder.getId(), faiOrder.getProductBatchNo());
        if (qualification == cn.iocoder.yudao.module.mes.service.qms.QmsNcPickQualificationService.Qualification.QUALIFIED) {
            respVO.setFaiJudgment("OK");
            respVO.setFaiStatus(FAI_STATUS_COMPLETED);
            respVO.setDisplayText("合格（处置后，原始检验NG）");
        } else if (qualification == cn.iocoder.yudao.module.mes.service.qms.QmsNcPickQualificationService.Qualification.PARTIAL) {
            respVO.setDisplayText("部分处置合格，未覆盖加工段仍为NG");
        }
        respVO.setCurrent(current);
        return respVO;
    }

    private String resolveWetReportFaiDisplayText(String status, String judgment) {
        if (FAI_STATUS_REJECTED.equals(status) && FAI_JUDGMENT_NG.equals(judgment)) {
            return "首检不合格，需重新提交首件检验";
        }
        if (FAI_JUDGMENT_NG.equals(judgment)) {
            return "首检不合格，需重新提交首件检验";
        }
        return resolveWetFaiDisplayText(status, judgment);
    }

    private String resolveWetFaiDisplayText(String status, String judgment) {
        if (FAI_STATUS_COMPLETED.equals(status) && FAI_JUDGMENT_OK.equals(judgment)) {
            return "已完成";
        }
        if (FAI_STATUS_REJECTED.equals(status)) {
            return "已驳回";
        }
        if (FAI_STATUS_PENDING.equals(status)) {
            return "待检测";
        }
        if (FAI_STATUS_INSPECTING.equals(status)) {
            return "检测中";
        }
        if (FAI_STATUS_WAITING_QA.equals(status)) {
            return "待品质复核";
        }
        if (FAI_STATUS_SUSPENDED.equals(status)) {
            return "已挂起";
        }
        if (FAI_STATUS_REWORKING.equals(status)) {
            return "调机中";
        }
        if (FAI_STATUS_CANCELED.equals(status)) {
            return "已取消";
        }
        if (FAI_JUDGMENT_NG.equals(judgment)) {
            return "已驳回";
        }
        return "未提交";
    }

    @Override
    public List<HcWetPassWorkRespVO> getWetPassWorkList(Long planId, Long planOperationId) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        HcPlanOrderOperationDO operation = validateWetOperation(planOrder, planOperationId);
        String modelCode = resolveWetProductModelCode(planOrder, operation);
        List<HcStationFormDO> forms = selectWetStationFormsByModel(
                hcStationFormMapper.selectEnabledByProcess(PROCESS_CODE_WET), modelCode);
        if (forms.isEmpty()) {
            return Collections.emptyList();
        }
        Set<Long> formIds = forms.stream().map(HcStationFormDO::getId).collect(Collectors.toSet());
        Map<Long, List<HcStationFormItemDO>> templateItemMap = hcStationFormItemMapper.selectByFormIds(formIds).stream()
                .collect(Collectors.groupingBy(HcStationFormItemDO::getFormId, LinkedHashMap::new, Collectors.toList()));
        Map<Long, HcStationRecordDO> recordMap = new LinkedHashMap<>();
        for (HcStationRecordDO record : hcStationRecordMapper.selectByPlanOperationAndFormIds(planOperationId, formIds)) {
            recordMap.putIfAbsent(record.getFormId(), record);
        }
        Set<Long> recordIds = recordMap.values().stream().map(HcStationRecordDO::getId).collect(Collectors.toSet());
        Map<Long, List<HcStationRecordItemDO>> recordItemMap = hcStationRecordItemMapper.selectByRecordIds(recordIds).stream()
                .collect(Collectors.groupingBy(HcStationRecordItemDO::getRecordId, LinkedHashMap::new, Collectors.toList()));

        List<HcWetPassWorkRespVO> result = new ArrayList<>();
        for (HcStationFormDO form : forms) {
            HcStationRecordDO record = recordMap.get(form.getId());
            HcWetPassWorkRespVO respVO = new HcWetPassWorkRespVO();
            respVO.setRecordId(record != null ? record.getId() : null);
            respVO.setFormId(form.getId());
            respVO.setFormCode(form.getFormCode());
            respVO.setId(record != null ? String.valueOf(record.getId()) : form.getFormCode());
            respVO.setName(form.getFormName());
            respVO.setDisplayName(resolveWetPassWorkDisplayName(form));
            respVO.setTiming(form.getTriggerTimingName());
            respVO.setStatus(record != null ? record.getDocStatus() : "PENDING_CHECK");
            respVO.setResult(record != null ? record.getResultStatus() : "未执行");
            respVO.setInspectionResult(record != null ? record.getInspectionResult() : "OK");
            respVO.setRecorder(record != null ? record.getRecordUserName() : "");
            respVO.setRecorderTime(formatDateTime(record != null ? record.getRecordTime() : null));
            respVO.setConfirmer(record != null ? record.getConfirmUserName() : "");
            respVO.setConfirmerTime(formatDateTime(record != null ? record.getConfirmTime() : null));
            respVO.setFormRemark(record != null ? record.getFormRemark() : "");
            respVO.setConfirmRemark(record != null ? record.getConfirmRemark() : "");
            respVO.setPresetHeaderDataJson(buildWetPresetHeaderDataJson(form));
            respVO.setHeaderDataJson(record != null ? record.getHeaderDataJson() : null);
            respVO.setSchemaJson(form.getSchemaJson());
            respVO.setPresetDetails(buildWetPresetDetails(form));
            respVO.setDetails(buildWetPassWorkDetails(recordItemMap.get(record != null ? record.getId() : null), templateItemMap.get(form.getId())));
            result.add(respVO);
        }
        return result;
    }

    private String resolveWetPassWorkDisplayName(HcStationFormDO form) {
        String category = resolveWetStationFormCategory(form);
        if ("production-check".equals(category)) {
            return "湿法生产点检表";
        }
        if ("semi-finished".equals(category)) {
            String formName = StrUtil.trimToEmpty(form == null ? null : form.getFormName());
            if (formName.contains("凝固")) {
                return "凝固半成品记录表";
            }
            if (formName.contains("烘箱")) {
                return "烘箱半成品记录表";
            }
            String neutralName = stripWetModelPrefix(formName);
            return StrUtil.isNotBlank(neutralName) ? neutralName : "半成品记录单";
        }
        return stripWetModelPrefix(form == null ? "" : form.getFormName());
    }

    private String stripWetModelPrefix(String formName) {
        String normalized = StrUtil.trimToEmpty(formName);
        if (StrUtil.isBlank(normalized)) {
            return "";
        }
        String stripped = normalized.replaceFirst("^.*?[（(][^）)]*[）)]\\s*", "");
        return StrUtil.isBlank(stripped) ? normalized : stripped;
    }

    private String resolveWetProductModelCode(HcPlanOrderDO planOrder, HcPlanOrderOperationDO operation) {
        String modelCode = firstNotBlank(
                operation != null ? operation.getMotherModelCode() : null,
                planOrder != null ? planOrder.getMotherModelCode() : null,
                planOrder != null ? planOrder.getModelCode() : null);
        return StrUtil.trimToEmpty(modelCode).toUpperCase();
    }

    /**
     * 同一湿法业务槽位仅保留最高优先级的模板：指定型号优先于型号前缀，前缀优先于通用模板。
     * 凝固和烘箱是不同槽位，凝固存在指定型号时不得误删烘箱的前缀模板。
     */
    private List<HcStationFormDO> selectWetStationFormsByModel(List<HcStationFormDO> forms, String modelCode) {
        if (CollUtil.isEmpty(forms) || StrUtil.isBlank(modelCode)) {
            return forms == null ? Collections.emptyList() : forms;
        }
        Map<HcStationFormDO, Integer> matchScoreMap = new LinkedHashMap<>();
        Map<String, Integer> bestScoreBySlot = new HashMap<>();
        for (HcStationFormDO form : forms) {
            int matchScore = getWetStationFormModelMatchScore(form, modelCode);
            if (matchScore < 0) {
                continue;
            }
            matchScoreMap.put(form, matchScore);
            String slot = resolveWetStationFormRuntimeSlot(form);
            if (StrUtil.isNotBlank(slot)) {
                bestScoreBySlot.merge(slot, matchScore, Math::min);
            }
        }
        return forms.stream()
                .filter(matchScoreMap::containsKey)
                .filter(form -> {
                    String slot = resolveWetStationFormRuntimeSlot(form);
                    return StrUtil.isBlank(slot)
                            || Objects.equals(matchScoreMap.get(form), bestScoreBySlot.get(slot));
                })
                .collect(Collectors.toList());
    }

    /**
     * 0：指定型号；10：型号前缀；20：未配置型号的通用模板；-1：不适用。
     */
    private int getWetStationFormModelMatchScore(HcStationFormDO form, String modelCode) {
        if (form == null || StrUtil.isBlank(modelCode)) {
            return 20;
        }
        String category = resolveWetStationFormCategory(form);
        if (!"production-check".equals(category) && !"semi-finished".equals(category)) {
            return 20;
        }
        JsonNode schema = StrUtil.isBlank(form.getSchemaJson()) ? null : JsonUtils.parseTree(form.getSchemaJson());
        String schemaModelCode = normalizeWetStationFormModelSelector(
                schema == null ? "" : readJsonText(schema, "modelCode"));
        String schemaModelPrefix = normalizeWetStationFormModelSelector(
                schema == null ? "" : readJsonText(schema, "modelPrefix"));
        if (StrUtil.equalsIgnoreCase(modelCode, schemaModelCode)) {
            return 0;
        }
        if (StrUtil.isNotBlank(schemaModelPrefix) && modelCode.startsWith(schemaModelPrefix)) {
            return 10;
        }
        if (StrUtil.isNotBlank(schemaModelCode) || StrUtil.isNotBlank(schemaModelPrefix)) {
            return -1;
        }
        String legacyModelPrefix = modelCode.length() <= 4 ? modelCode : modelCode.substring(0, 4);
        String formCode = StrUtil.trimToEmpty(form.getFormCode()).toUpperCase();
        String formName = StrUtil.trimToEmpty(form.getFormName()).toUpperCase();
        if (formCode.contains(modelCode) || formName.contains(modelCode)) {
            return 0;
        }
        return formCode.contains(legacyModelPrefix) || formName.contains(legacyModelPrefix) ? 10 : 20;
    }

    private String normalizeWetStationFormModelSelector(String value) {
        String normalized = StrUtil.trimToEmpty(value).toUpperCase();
        return StrUtil.equalsAny(normalized, "COMMON", "ALL") ? "" : normalized;
    }

    private String resolveWetStationFormRuntimeSlot(HcStationFormDO form) {
        String category = resolveWetStationFormCategory(form);
        if ("production-check".equals(category)) {
            return "production-check";
        }
        if (!"semi-finished".equals(category)) {
            return "";
        }
        if (isWetSolidSemiForm(form)) {
            return "semi-finished:solid";
        }
        if (isWetOvenSemiForm(form)) {
            return "semi-finished:oven";
        }
        JsonNode schema = StrUtil.isBlank(form == null ? null : form.getSchemaJson())
                ? null : JsonUtils.parseTree(form.getSchemaJson());
        String semiType = StrUtil.trimToEmpty(schema == null ? "" : readJsonText(schema, "semiType"))
                .toLowerCase(Locale.ROOT);
        return StrUtil.isBlank(semiType) ? "semi-finished" : "semi-finished:" + semiType;
    }

    private String resolveWetStationFormCategory(HcStationFormDO form) {
        String schemaCategory = null;
        if (form != null && StrUtil.isNotBlank(form.getSchemaJson())) {
            JsonNode schema = JsonUtils.parseTree(form.getSchemaJson());
            schemaCategory = schema == null ? null : readJsonText(schema, "wetCategory");
        }
        if (StrUtil.equalsAny(schemaCategory, "prepare", "production-check", "semi-finished")) {
            return schemaCategory;
        }
        String formCode = StrUtil.trimToEmpty(form != null ? form.getFormCode() : "").toUpperCase();
        String formName = StrUtil.trimToEmpty(form != null ? form.getFormName() : "");
        if (formCode.startsWith("WET_PROCESS_CHECK") || formName.contains("湿法生产点检表")
                || formName.contains("湿法点检表") || formName.contains("工艺参数")) {
            return "production-check";
        }
        if (formCode.startsWith("WET_SOLID_SEMI") || formCode.startsWith("WET_OVEN_SEMI")
                || formName.contains("半成品记录")) {
            return "semi-finished";
        }
        if (formCode.startsWith("WET_STARTUP_CHECK") || formCode.startsWith("WET_CLEANING_CHECK")
                || formName.contains("开机点检") || formName.contains("清洁点检")) {
            return "prepare";
        }
        return "";
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long startWetReport(HcWetReportStartReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectByIdForUpdate(reqVO.getPlanId());
        assertPlanReleasedForStart(planOrder);
        HcPlanOrderOperationDO operation = validateWetOperation(planOrder, reqVO.getPlanOperationId());
        if (OP_STATUS_FINISHED.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序已完工，不能再开工");
        }
        if (OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序已开工");
        }
        validatePreviousOperationReported(planOrder.getId(), operation);
        log.info(
                "[MES报工时间开工-接收][湿法] planNo={} planId={} planOperationId={} "
                        + "requestFields=reportDate,startTime values reportDate={} startTime={} sourceMenuCode={}",
                planOrder.getPlanNo(), planOrder.getId(), operation.getId(),
                reqVO.getReportDate(), reqVO.getStartTime(), SOURCE_MENU_CODE_WET);
        LocalDate reportDate = reqVO.getReportDate() == null ? LocalDate.now() : reqVO.getReportDate();
        boolean placeholderStartTime = isPlaceholderDateTime(reqVO.getStartTime())
                || isDateOnlyRuntimeDateTime(reqVO.getStartTime(), reportDate);
        boolean placeholderRecorderTime = isPlaceholderDateTime(reqVO.getRecorderTime())
                || isDateOnlyRuntimeDateTime(reqVO.getRecorderTime(), reportDate);
        LocalDateTime normalizedStartTime = normalizeReportDateTime(reqVO.getStartTime(), reportDate);
        LocalDateTime normalizedRecorderTime = normalizeReportDateTime(reqVO.getRecorderTime(), reportDate);
        LocalDateTime now = LocalDateTime.now();
        if (normalizedStartTime == null || placeholderStartTime) {
            normalizedStartTime = now;
        }
        if (normalizedRecorderTime == null || placeholderRecorderTime) {
            normalizedRecorderTime = now;
        }
        String inheritedProductionBatchNo = firstNotBlank(operation.getProductionBatchNo(), planOrder.getProductionBatchNo(),
                operation.getBatchNo(), planOrder.getBatchNo());
        String inheritedParentProductionBatchNo = firstNotBlank(operation.getParentProductionBatchNo(), planOrder.getParentProductionBatchNo());
        Long inheritedBatchRuleId = firstNotNull(operation.getProductionBatchRuleId(), planOrder.getProductionBatchRuleId(), planOrder.getBatchRuleId());
        String inheritedBatchRuleCode = firstNotBlank(operation.getProductionBatchRuleCode(), planOrder.getProductionBatchRuleCode(), planOrder.getBatchRuleCode());
        String inheritedBatchContextJson = firstNotBlank(operation.getProductionBatchContextJson(), planOrder.getProductionBatchContextJson());
        HcProcessReportDO reportDO = HcProcessReportDO.builder()
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .operationStatus(operation.getOperationStatus())
                .operationSeq(operation.getOpSeq())
                .operationCode(operation.getOpCode())
                .operationName(operation.getOpName())
                .workCenterId(operation.getWorkCenterId())
                .workCenterCode(operation.getWorkCenterCode())
                .workCenterName(operation.getWorkCenterName())
                .equipmentId(reqVO.getEquipmentId())
                .equipmentCode(firstNotBlank(reqVO.getEquipmentCode(), operation.getEquipmentCode()))
                .equipmentName(firstNotBlank(reqVO.getEquipmentName(), operation.getEquipmentName()))
                .materialId(planOrder.getMaterialId())
                .materialCode(planOrder.getMaterialCode())
                .materialName(planOrder.getMaterialName())
                .motherMaterialId(planOrder.getMotherMaterialId())
                .motherMaterialCode(firstNotBlank(operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode()))
                .motherMaterialName(firstNotBlank(operation.getMotherMaterialName(), planOrder.getMotherMaterialName()))
                .motherModelId(planOrder.getMotherModelId())
                .motherModelCode(firstNotBlank(operation.getMotherModelCode(), planOrder.getMotherModelCode()))
                .motherModelName(firstNotBlank(operation.getMotherModelName(), planOrder.getMotherModelName()))
                .batchNo(inheritedProductionBatchNo)
                .productionBatchNo(inheritedProductionBatchNo)
                .parentProductionBatchNo(inheritedParentProductionBatchNo)
                .productionBatchRuleId(inheritedBatchRuleId)
                .productionBatchRuleCode(inheritedBatchRuleCode)
                .productionBatchContextJson(inheritedBatchContextJson)
                .parentBatchNo(firstNotBlank(inheritedParentProductionBatchNo, operation.getParentBatchNo()))
                .sampleCode(operation.getSampleCode())
                .reportDate(reportDate)
                .startTime(normalizedStartTime)
                .goodQty(BigDecimal.ZERO)
                .scrapQty(BigDecimal.ZERO)
                .recorderName(reqVO.getRecorderName())
                .recorderTime(normalizedRecorderTime)
                .reportUom(firstNotBlank(operation.getUom(), operation.getUnitCode(), operation.getUnitName(), planOrder.getTargetUom()))
                .reportType("START")
                .sourceMenuCode(SOURCE_MENU_CODE_WET)
                .build();
        hcProcessReportMapper.insert(reportDO);
        log.info(
                "[MES报工时间开工-落库][湿法] planNo={} planOperationId={} operationReportId={} "
                        + "saveTable=mes_sfc_operation_report saveFields=report_date,start_time "
                        + "values reportDate={} startTime={} reportType=START sourceMenuCode={}",
                planOrder.getPlanNo(), operation.getId(), reportDO.getId(),
                reportDO.getReportDate(), reportDO.getStartTime(), SOURCE_MENU_CODE_WET);

        HcPlanOrderOperationDO updateObj = new HcPlanOrderOperationDO();
        updateObj.setId(operation.getId());
        updateObj.setOperationStatus(OP_STATUS_RUNNING);
        updateObj.setEquipmentId(reqVO.getEquipmentId());
        updateObj.setEquipmentCode(firstNotBlank(reqVO.getEquipmentCode(), operation.getEquipmentCode()));
        updateObj.setEquipmentName(firstNotBlank(reqVO.getEquipmentName(), operation.getEquipmentName()));
        if (StrUtil.isBlank(operation.getProductionBatchNo())) {
            updateObj.setProductionBatchNo(inheritedProductionBatchNo);
            updateObj.setParentProductionBatchNo(inheritedParentProductionBatchNo);
            updateObj.setProductionBatchRuleId(inheritedBatchRuleId);
            updateObj.setProductionBatchRuleCode(inheritedBatchRuleCode);
            updateObj.setProductionBatchContextJson(inheritedBatchContextJson);
            updateObj.setBatchNo(inheritedProductionBatchNo);
            updateObj.setParentBatchNo(inheritedParentProductionBatchNo);
        }
        updateObj.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateObj.setStatusOperatorName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "system"));
        updateObj.setStatusOperateTime(LocalDateTime.now());
        hcPlanOrderOperationMapper.updateById(updateObj);
        String operatorName = firstNotBlank(reqVO.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        LocalDateTime recordTime = normalizedRecorderTime != null ? normalizedRecorderTime : now;
        hcEquipmentService.occupyEquipment(reqVO.getEquipmentId(), planOrder.getPlanNo(), operation.getOpCode(),
                operation.getOpName(), normalizedStartTime, operatorName, recordTime);
        return reportDO.getId();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void switchFormulaEquipment(HcFormulaReportSwitchEquipmentReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validateFormulaOperation(planOrder, reqVO.getPlanOperationId());
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序未开工，不能切换设备");
        }
        HcProcessReportDO latestReport = getLatestReport(operation.getId(), SOURCE_MENU_CODE_FORMULA);
        if (latestReport == null) {
            throw invalidParamException("当前工序未找到有效报工记录，不能切换设备");
        }
        Long oldMixerId = firstNotNull(latestReport.getMixerEquipmentId(), operation.getEquipmentId());
        String oldMixerCode = firstNotBlank(latestReport.getMixerEquipmentCode(), operation.getEquipmentCode());
        String oldMixerName = firstNotBlank(latestReport.getMixerEquipmentName(), operation.getEquipmentName());
        Long oldFoamingId = latestReport.getFoamingEquipmentId();
        String oldFoamingCode = latestReport.getFoamingEquipmentCode();
        String oldFoamingName = latestReport.getFoamingEquipmentName();

        Long newMixerId = firstNotNull(reqVO.getMixerEquipmentId(), oldMixerId);
        String newMixerCode = firstNotBlank(reqVO.getMixerEquipmentCode(), oldMixerCode);
        String newMixerName = firstNotBlank(reqVO.getMixerEquipmentName(), oldMixerName);
        Long newFoamingId = firstNotNull(reqVO.getFoamingEquipmentId(), oldFoamingId);
        String newFoamingCode = firstNotBlank(reqVO.getFoamingEquipmentCode(), oldFoamingCode);
        String newFoamingName = firstNotBlank(reqVO.getFoamingEquipmentName(), oldFoamingName);

        Set<Long> oldEquipmentIds = java.util.stream.Stream.of(oldMixerId, oldFoamingId)
                .filter(Objects::nonNull)
                .collect(Collectors.toSet());
        Set<Long> newEquipmentIds = java.util.stream.Stream.of(newMixerId, newFoamingId)
                .filter(Objects::nonNull)
                .collect(Collectors.toSet());
        String operatorName = firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        LocalDateTime recordTime = LocalDateTime.now();
        LocalDateTime startTime = latestReport.getStartTime() != null ? latestReport.getStartTime() : recordTime;

        for (Long equipmentId : oldEquipmentIds) {
            if (!newEquipmentIds.contains(equipmentId)) {
                hcEquipmentService.releaseEquipment(equipmentId, null, operatorName, recordTime);
            }
        }
        for (Long equipmentId : newEquipmentIds) {
            if (!oldEquipmentIds.contains(equipmentId)) {
                hcEquipmentService.occupyEquipment(equipmentId, planOrder.getPlanNo(), operation.getOpCode(),
                        operation.getOpName(), startTime, operatorName, recordTime);
            }
        }

        HcProcessReportDO updateReport = new HcProcessReportDO();
        updateReport.setId(latestReport.getId());
        updateReport.setEquipmentId(newMixerId);
        updateReport.setEquipmentCode(newMixerCode);
        updateReport.setEquipmentName(newMixerName);
        updateReport.setMixerEquipmentId(newMixerId);
        updateReport.setMixerEquipmentCode(newMixerCode);
        updateReport.setMixerEquipmentName(newMixerName);
        updateReport.setFoamingEquipmentId(newFoamingId);
        updateReport.setFoamingEquipmentCode(newFoamingCode);
        updateReport.setFoamingEquipmentName(newFoamingName);
        hcProcessReportMapper.updateById(updateReport);

        HcPlanOrderOperationDO updateOperation = new HcPlanOrderOperationDO();
        updateOperation.setId(operation.getId());
        updateOperation.setEquipmentId(newMixerId);
        updateOperation.setEquipmentCode(newMixerCode);
        updateOperation.setEquipmentName(newMixerName);
        updateOperation.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateOperation.setStatusOperatorName(operatorName);
        updateOperation.setStatusOperateTime(recordTime);
        hcPlanOrderOperationMapper.updateById(updateOperation);
    }

