    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long reviseFormulaReportStatisticsData(HcStatisticsDataReviseReqVO reqVO) {
        String reason = requireStatisticsRevisionReason(reqVO.getReason());
        HcProcessReportDO report = selectOperationReportForStatisticsRevision(
                reqVO.getId(), SOURCE_MENU_CODE_FORMULA, "配料");
        if (!REPORT_TYPE_END.equalsIgnoreCase(StrUtil.trimToEmpty(report.getReportType()))) {
            throw invalidParamException("只有配料完工报工允许修订统计数据");
        }

        BigDecimal nextFeedQty = statisticsValueOrCurrent(reqVO.getFeedQty(), report.getFeedQty());
        BigDecimal nextGoodQty = statisticsValueOrCurrent(reqVO.getGoodQty(), report.getGoodQty());
        BigDecimal nextScrapQty = statisticsValueOrCurrent(reqVO.getScrapQty(), report.getScrapQty());
        requireNonNegative(nextFeedQty, "配料统计实际配料量");
        requireNonNegative(nextGoodQty, "配料统计完工数");
        requireNonNegative(nextScrapQty, "配料统计损耗数");

        Map<String, Object> before = new LinkedHashMap<>();
        before.put("feedQty", zeroIfNull(report.getFeedQty()));
        before.put("goodQty", zeroIfNull(report.getGoodQty()));
        before.put("scrapQty", zeroIfNull(report.getScrapQty()));
        Map<String, Object> after = new LinkedHashMap<>();
        after.put("feedQty", nextFeedQty);
        after.put("goodQty", nextGoodQty);
        after.put("scrapQty", nextScrapQty);
        String revisionRemark = buildStatisticsRevisionRemark("配料", before, after, reason);

        HcProcessReportDO updateReport = new HcProcessReportDO();
        updateReport.setId(report.getId());
        updateReport.setFeedQty(nextFeedQty);
        updateReport.setGoodQty(nextGoodQty);
        updateReport.setScrapQty(nextScrapQty);
        updateReport.setExtraJson(appendStatisticsRevisionHistory(report.getExtraJson(), "配料", before, after, reason));
        updateReport.setRemark(appendQuantityRevisionRemark(report.getRemark(), revisionRemark));
        hcProcessReportMapper.updateById(updateReport);
        refreshOperationDispatchQty(report.getPlanOperationId(), SOURCE_MENU_CODE_FORMULA, "配料");
        return report.getId();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long reviseWetReportStatisticsData(HcStatisticsDataReviseReqVO reqVO) {
        String reason = requireStatisticsRevisionReason(reqVO.getReason());
        HcProcessReportDO report = selectOperationReportForStatisticsRevision(
                reqVO.getId(), SOURCE_MENU_CODE_WET, "湿法");
        if (!REPORT_TYPE_END.equalsIgnoreCase(StrUtil.trimToEmpty(report.getReportType()))) {
            throw invalidParamException("只有湿法完工报工允许修订统计数据");
        }

        BigDecimal nextFeedQty = statisticsValueOrCurrent(reqVO.getFeedQty(), report.getFeedQty());
        BigDecimal nextGoodQty = statisticsValueOrCurrent(reqVO.getGoodQty(), report.getGoodQty());
        BigDecimal nextScrapQty = statisticsValueOrCurrent(reqVO.getScrapQty(), report.getScrapQty());
        requireNonNegative(nextFeedQty, "湿法统计投入数");
        requireNonNegative(nextGoodQty, "湿法统计收卷米数");
        requireNonNegative(nextScrapQty, "湿法统计固定损耗");

        BigDecimal oldGoodQty = zeroIfNull(report.getGoodQty());
        BigDecimal goodDelta = nextGoodQty.subtract(oldGoodQty);
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectByIdForUpdate(report.getPlanOperationId());
        if (operation == null || Boolean.TRUE.equals(operation.getDeleted())) {
            throw invalidParamException("湿法报工对应工序不存在");
        }
        HcPlanOrderDO planOrder = null;
        if (!isZeroQuantityDelta(goodDelta)) {
            planOrder = hcPlanOrderMapper.selectById(report.getPlanId());
            if (planOrder == null || Boolean.TRUE.equals(planOrder.getDeleted())) {
                throw invalidParamException("湿法报工对应生产计划不存在");
            }
        }

        Map<String, Object> before = new LinkedHashMap<>();
        before.put("feedQty", zeroIfNull(report.getFeedQty()));
        before.put("goodQty", oldGoodQty);
        before.put("scrapQty", zeroIfNull(report.getScrapQty()));
        Map<String, Object> after = new LinkedHashMap<>();
        after.put("feedQty", nextFeedQty);
        after.put("goodQty", nextGoodQty);
        after.put("scrapQty", nextScrapQty);
        String revisionRemark = buildStatisticsRevisionRemark("湿法", before, after, reason);

        HcProcessReportDO updateReport = new HcProcessReportDO();
        updateReport.setId(report.getId());
        updateReport.setFeedQty(nextFeedQty);
        updateReport.setGoodQty(nextGoodQty);
        updateReport.setScrapQty(nextScrapQty);
        updateReport.setExtraJson(reviseWetReportStatisticsExtraJson(
                report.getExtraJson(), nextGoodQty, goodDelta, nextScrapQty, before, after, reason));
        updateReport.setRemark(appendQuantityRevisionRemark(report.getRemark(), revisionRemark));
        hcProcessReportMapper.updateById(updateReport);

        BigDecimal totalGoodQty = hcProcessReportMapper.selectTotalGoodQtyBySource(operation.getId(), SOURCE_MENU_CODE_WET);
        HcPlanOrderOperationDO updateOperation = new HcPlanOrderOperationDO();
        updateOperation.setId(operation.getId());
        updateOperation.setDispatchQty(zeroIfNull(totalGoodQty));
        updateOperation.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateOperation.setStatusOperatorName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统"));
        updateOperation.setStatusOperateTime(LocalDateTime.now());
        hcPlanOrderOperationMapper.updateById(updateOperation);

        if (!isZeroQuantityDelta(goodDelta)) {
            HcInvStockDO stock = selectWetOutputStockForUpdate(report);
            reviseWetOutputStock(stock, report, goodDelta, revisionRemark);
            reviseWetOutputWipInTxn(stock, report, goodDelta, revisionRemark);
            reviseWetOutputWipLocks(stock, goodDelta, revisionRemark);
            reviseConsumableUsageTotal(SOURCE_MENU_CODE_WET, report.getId(), CONSUMABLE_TYPE_GUIDE_CLOTH,
                    nextGoodQty, revisionRemark);
            reviseWetGrindingSourceBalance(report, nextGoodQty, goodDelta, revisionRemark);
            log.info("[湿法统计数据修订] reportId={}, planNo={}, batchNo={}, beforeQty={}, afterQty={}, delta={}",
                    report.getId(), report.getPlanNo(), report.getBatchNo(), oldGoodQty, nextGoodQty, goodDelta);
        }
        return report.getId();
    }

    private Long updateOperationReportTime(HcFormulaReportTimeUpdateReqVO reqVO,
                                           String sourceMenuCode,
                                           String processName) {
        HcProcessReportDO report = hcProcessReportMapper.selectById(reqVO.getId());
        if (report == null || Boolean.TRUE.equals(report.getDeleted())) {
            throw invalidParamException(processName + "报工记录不存在");
        }
        if (!sourceMenuCode.equals(report.getSourceMenuCode())) {
            throw invalidParamException("当前报工记录不是" + processName + "报工，不能在" + processName + "报工中修正");
        }
        log.info(
                "[MES报工时间修正-接收][{}] planNo={} planOperationId={} operationReportId={} "
                        + "requestFields=reportDate,startTime,endTime values reportDate={} startTime={} endTime={} sourceMenuCode={}",
                processName, report.getPlanNo(), report.getPlanOperationId(), report.getId(),
                reqVO.getReportDate(), reqVO.getStartTime(), reqVO.getEndTime(), sourceMenuCode);
        LocalDate reportDate = reqVO.getReportDate() != null
                ? reqVO.getReportDate()
                : firstNotNullDate(report.getReportDate(),
                        reqVO.getStartTime() == null ? null : reqVO.getStartTime().toLocalDate(),
                        reqVO.getEndTime() == null ? null : reqVO.getEndTime().toLocalDate());
        LocalDateTime startTime = normalizeReportDateTime(reqVO.getStartTime(), reportDate);
        LocalDateTime endTime = normalizeReportDateTime(reqVO.getEndTime(), reportDate);
        LocalDateTime effectiveStartTime = startTime == null ? report.getStartTime() : startTime;
        LocalDateTime effectiveEndTime = endTime == null ? report.getEndTime() : endTime;
        if (effectiveStartTime == null) {
            throw invalidParamException("开始时间不能为空");
        }
        if (effectiveEndTime != null && effectiveEndTime.isBefore(effectiveStartTime)) {
            throw invalidParamException("结束时间不能早于开始时间");
        }
        if (SOURCE_MENU_CODE_WET.equals(sourceMenuCode)
                && "END".equalsIgnoreCase(StrUtil.trimToEmpty(report.getReportType()))
                && report.getRecorderTime() != null
                && effectiveEndTime != null
                && effectiveEndTime.isAfter(report.getRecorderTime())) {
            throw invalidParamException("湿法完工时间不能晚于最终报工记录时间");
        }
        LocalDate effectiveReportDate = firstNotNullDate(reportDate, effectiveStartTime.toLocalDate());
        Integer afterReportMinutes = calculateMinutes(effectiveStartTime, effectiveEndTime);

        HcProcessReportDO updateObj = new HcProcessReportDO();
        updateObj.setId(report.getId());
        updateObj.setReportDate(effectiveReportDate);
        updateObj.setStartTime(effectiveStartTime);
        updateObj.setEndTime(effectiveEndTime);
        updateObj.setReportMinutes(afterReportMinutes);
        int affectedRows = hcProcessReportMapper.updateById(updateObj);
        HcProcessReportDO persistedReport = hcProcessReportMapper.selectById(report.getId());
        verifyOperationReportTimePersisted(processName, report.getId(), effectiveReportDate,
                effectiveStartTime, effectiveEndTime, persistedReport);
        log.info(
                "[MES报工时间修正-落库][{}] planNo={} planOperationId={} operationReportId={} affectedRows={} "
                        + "saveTable=mes_sfc_operation_report saveFields=report_date,start_time,end_time,report_minutes "
                        + "values reportDate={} startTime={} endTime={} reportMinutes={}",
                processName, report.getPlanNo(), report.getPlanOperationId(), report.getId(), affectedRows,
                persistedReport == null ? null : persistedReport.getReportDate(),
                persistedReport == null ? null : persistedReport.getStartTime(),
                persistedReport == null ? null : persistedReport.getEndTime(),
                persistedReport == null ? null : persistedReport.getReportMinutes());
        if (report.getPlanOperationId() != null
                && "END".equalsIgnoreCase(StrUtil.trimToEmpty(report.getReportType()))) {
            HcProcessReportDO latestStartReport = getLatestStartReport(report.getPlanOperationId(), sourceMenuCode);
            syncLatestStartReportTime(latestStartReport, effectiveReportDate, effectiveStartTime);
        }
        if (SOURCE_MENU_CODE_WET.equals(sourceMenuCode)) {
            syncWetPoreSelfCheckStartTime(report.getPlanOperationId(), effectiveStartTime);
        }

        LocalDateTime changeTime = LocalDateTime.now();
        Long operatorId = SecurityFrameworkUtils.getLoginUserId();
        String operatorName = firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        syncOperationReportTimeDerivedFields(report, effectiveEndTime, changeTime, operatorId, operatorName, sourceMenuCode);
        HcFormulaReportTimeLogDO log = HcFormulaReportTimeLogDO.builder()
                .tenantId(report.getTenantId())
                .operationReportId(report.getId())
                .planId(report.getPlanId())
                .planOperationId(report.getPlanOperationId())
                .planNo(report.getPlanNo())
                .sourceMenuCode(report.getSourceMenuCode())
                .beforeReportDate(report.getReportDate())
                .afterReportDate(effectiveReportDate)
                .beforeStartTime(report.getStartTime())
                .afterStartTime(effectiveStartTime)
                .beforeEndTime(report.getEndTime())
                .afterEndTime(effectiveEndTime)
                .beforeReportMinutes(report.getReportMinutes())
                .afterReportMinutes(afterReportMinutes)
                .operatorId(operatorId)
                .operatorName(operatorName)
                .changeTime(changeTime)
                .build();
        try {
            hcFormulaReportTimeLogMapper.insert(log);
        } catch (RuntimeException ex) {
            if (isFormulaReportTimeLogTableMissing(ex)) {
                throw invalidParamException("报工时间修改日志表未创建，请先执行 db/zhangjian_20260711111336.sql");
            }
            throw ex;
        }
        return report.getId();
    }

    private boolean isFormulaReportTimeLogTableMissing(RuntimeException ex) {
        Throwable cause = ex;
        while (cause != null) {
            String message = cause.getMessage();
            if (message != null
                    && message.contains("mes_sfc_operation_report_time_log")
                    && message.contains("doesn't exist")) {
                return true;
            }
            cause = cause.getCause();
        }
        return false;
    }

    private void syncOperationReportTimeDerivedFields(HcProcessReportDO report,
                                                      LocalDateTime effectiveEndTime,
                                                      LocalDateTime changeTime,
                                                      Long operatorId,
                                                      String operatorName,
                                                      String sourceMenuCode) {
        if (report.getPlanOperationId() == null || effectiveEndTime == null
                || !"END".equalsIgnoreCase(StrUtil.trimToEmpty(report.getReportType()))) {
            return;
        }
        HcProcessReportDO latestReport = getLatestReport(report.getPlanOperationId(), sourceMenuCode);
        if (latestReport == null || !Objects.equals(latestReport.getId(), report.getId())) {
            return;
        }
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(report.getPlanOperationId());
        if (operation == null || !OP_STATUS_FINISHED.equals(operation.getOperationStatus())) {
            return;
        }
        HcPlanOrderOperationDO updateOperation = new HcPlanOrderOperationDO();
        updateOperation.setId(operation.getId());
        updateOperation.setFinishTime(effectiveEndTime);
        updateOperation.setStatusOperatorId(operatorId);
        updateOperation.setStatusOperatorName(operatorName);
        updateOperation.setStatusOperateTime(changeTime);
        hcPlanOrderOperationMapper.updateById(updateOperation);
    }

