    private Long confirmOperationReport(HcOperationReportConfirmReqVO reqVO,
                                        String sourceMenuCode,
                                        String processName) {
        HcProcessReportDO report = hcProcessReportMapper.selectById(reqVO.getId());
        if (report == null || Boolean.TRUE.equals(report.getDeleted())) {
            throw invalidParamException(processName + "报工记录不存在");
        }
        if (!sourceMenuCode.equals(report.getSourceMenuCode())) {
            throw invalidParamException("当前报工记录不是" + processName + "报工，不能在" + processName + "报工中确认");
        }
        if (!"END".equalsIgnoreCase(StrUtil.trimToEmpty(report.getReportType()))) {
            throw invalidParamException("只有已提交的" + processName + "报工记录允许确认");
        }
        LocalDateTime confirmerTime = normalizeReportDateTime(reqVO.getConfirmerTime(), report.getReportDate());
        if (confirmerTime == null) {
            confirmerTime = LocalDateTime.now();
        }
        String confirmerName = firstNotBlank(reqVO.getConfirmerName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        HcProcessReportDO updateObj = new HcProcessReportDO();
        updateObj.setId(report.getId());
        updateObj.setConfirmerName(confirmerName);
        updateObj.setConfirmerTime(confirmerTime);
        hcProcessReportMapper.updateById(updateObj);
        return report.getId();
    }

