    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long submitWetReport(HcWetReportSaveReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        if (!PLAN_STATUS_RELEASED.equals(planOrder.getPlanStatus())) {
            throw invalidParamException("只有已下达的生产计划允许报工");
        }
        HcPlanOrderOperationDO operation = validateWetOperation(planOrder,
                hcPlanOrderOperationMapper.selectByIdForUpdate(reqVO.getPlanOperationId()), reqVO.getPlanOperationId());
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            if (OP_STATUS_FINISHED.equals(operation.getOperationStatus())) {
                throw invalidParamException("当前工序已完工，不能继续报工");
            }
            throw invalidParamException("当前工序状态不允许报工");
        }
        validateWetPoreSelfCheckRecorded(operation);
        validateWetAbnormalPositionOption(reqVO);
        validateWetAbnormalPositions(reqVO.getAbnormalPositions());
        log.info(
                "[MES报工时间提交-接收][湿法] planNo={} planId={} planOperationId={} "
                        + "requestFields=reportDate,startTime,endTime,recorderTime "
                        + "values reportDate={} startTime={} endTime={} recorderTime={} sourceMenuCode={}",
                planOrder.getPlanNo(), planOrder.getId(), operation.getId(),
                reqVO.getReportDate(), reqVO.getStartTime(), reqVO.getEndTime(), reqVO.getRecorderTime(), SOURCE_MENU_CODE_WET);
        LocalDate reportDate = reqVO.getReportDate() == null ? LocalDate.now() : reqVO.getReportDate();
        boolean placeholderStartTime = isPlaceholderDateTime(reqVO.getStartTime())
                || isDateOnlyRuntimeDateTime(reqVO.getStartTime(), reportDate);
        boolean placeholderEndTime = isPlaceholderDateTime(reqVO.getEndTime());
        boolean placeholderRecorderTime = isPlaceholderDateTime(reqVO.getRecorderTime());
        LocalDateTime normalizedStartTime = normalizeReportDateTime(reqVO.getStartTime(), reportDate);
        LocalDateTime normalizedEndTime = normalizeReportDateTime(reqVO.getEndTime(), reportDate);
        LocalDateTime normalizedRecorderTime = normalizeReportDateTime(reqVO.getRecorderTime(), reportDate);
        LocalDateTime normalizedInWashTime = normalizeReportDateTime(reqVO.getInWashTime(), reportDate);
        LocalDateTime normalizedOutWashTime = normalizeReportDateTime(reqVO.getOutWashTime(), reportDate);
        LocalDateTime normalizedInSolidifyTime = normalizeReportDateTime(reqVO.getInSolidifyTime(), reportDate);
        LocalDateTime normalizedOutSolidifyTime = normalizeReportDateTime(reqVO.getOutSolidifyTime(), reportDate);
        LocalDateTime normalizedInOvenTime = normalizeReportDateTime(reqVO.getInOvenTime(), reportDate);
        LocalDateTime normalizedOutOvenTime = normalizeReportDateTime(reqVO.getOutOvenTime(), reportDate);
        LocalDateTime now = LocalDateTime.now();
        Long effectiveEquipmentId = firstNotNull(reqVO.getEquipmentId(), operation.getEquipmentId());
        String effectiveEquipmentCode = firstNotBlank(reqVO.getEquipmentCode(), operation.getEquipmentCode());
        String effectiveEquipmentName = firstNotBlank(reqVO.getEquipmentName(), operation.getEquipmentName());
        HcGuideClothRuntimeRespVO guideClothRuntime = hcGuideClothRecordService.getRuntimeByMotherModelCode(
                firstNotBlank(operation.getMotherModelCode(), planOrder.getMotherModelCode()), effectiveEquipmentId);
        boolean guideClothChanged = "Y".equalsIgnoreCase(reqVO.getGuideClothChanged());
        int effectiveGuideClothUseCount = guideClothChanged
                ? 1
                : (reqVO.getGuideClothUseCount() != null
                        ? reqVO.getGuideClothUseCount()
                        : (guideClothRuntime == null || guideClothRuntime.getNextUseCount() == null
                                ? 1 : guideClothRuntime.getNextUseCount()));
        if (!guideClothChanged) {
            validateWetGuideClothRuntime(guideClothRuntime, reportDate, effectiveGuideClothUseCount);
        }
        HcProcessReportDO latestStartReport = getLatestStartReport(reqVO.getPlanOperationId(), SOURCE_MENU_CODE_WET);
        if ((normalizedStartTime == null || placeholderStartTime)
                && latestStartReport != null
                && latestStartReport.getStartTime() != null) {
            normalizedStartTime = latestStartReport.getStartTime();
        }
        if (normalizedStartTime == null) {
            normalizedStartTime = now;
        }
        if (normalizedRecorderTime == null || placeholderRecorderTime) {
            throw invalidParamException("最终报工记录时间不能为空");
        }
        if (placeholderEndTime) {
            normalizedEndTime = null;
        }
        LocalDateTime effectiveEndTime = resolveWetCompletionTime(
                normalizedStartTime, normalizedEndTime, normalizedRecorderTime);
        syncLatestStartReportTime(latestStartReport, reportDate, normalizedStartTime);
        syncWetPoreSelfCheckStartTime(operation.getId(), normalizedStartTime);

        BigDecimal reportGoodQty = reqVO.getReceiveLength() == null ? BigDecimal.ZERO : reqVO.getReceiveLength();
        BigDecimal reportScrapQty = reqVO.getPrintLossLength() == null ? BigDecimal.ZERO : reqVO.getPrintLossLength();
        BigDecimal guideClothUsedLength = guideClothChanged
                ? BigDecimal.ZERO
                : zeroIfNull(guideClothRuntime == null ? null : guideClothRuntime.getCurrentUsedLength()).add(reportGoodQty);
        BigDecimal guideClothLimitLength = zeroIfNull(guideClothRuntime == null ? null : guideClothRuntime.getLimitLength());
        Integer guideClothWarningFlag = guideClothChanged ? 0
                : (effectiveGuideClothUseCount >= GUIDE_CLOTH_MAX_USE_COUNT ? 1 : 0);
        LocalDateTime guideClothReplaceTime = guideClothChanged
                ? effectiveEndTime
                : (guideClothRuntime == null ? null : guideClothRuntime.getReplaceTime());
        HcProcessReportDO reportDO = HcProcessReportDO.builder()
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .operationStatus(operation.getOperationStatus())
                .operationSeq(operation.getOpSeq())
                .operationCode(operation.getOpCode())
                .operationName(operation.getOpName())
                .workCenterId(operation.getWorkCenterId())
                .workCenterCode(operation.getWorkCenterCode())
                .workCenterName(operation.getWorkCenterName())
                .equipmentId(effectiveEquipmentId)
                .equipmentCode(effectiveEquipmentCode)
                .equipmentName(effectiveEquipmentName)
                .materialId(planOrder.getMaterialId())
                .materialCode(planOrder.getMaterialCode())
                .materialName(planOrder.getMaterialName())
                .motherMaterialId(planOrder.getMotherMaterialId())
                .motherMaterialCode(firstNotBlank(operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode()))
                .motherMaterialName(firstNotBlank(operation.getMotherMaterialName(), planOrder.getMotherMaterialName()))
                .motherModelId(planOrder.getMotherModelId())
                .motherModelCode(firstNotBlank(operation.getMotherModelCode(), planOrder.getMotherModelCode()))
                .motherModelName(firstNotBlank(operation.getMotherModelName(), planOrder.getMotherModelName()))
                .batchNo(firstNotBlank(reqVO.getBatchNo(), planOrder.getBatchNo(), operation.getBatchNo()))
                .parentBatchNo(firstNotBlank(operation.getParentBatchNo(), planOrder.getBatchNo()))
                .sampleCode(operation.getSampleCode())
                .reportDate(reportDate)
                .startTime(normalizedStartTime)
                .endTime(effectiveEndTime)
                .goodQty(reportGoodQty)
                .scrapQty(reportScrapQty)
                .recorderName(reqVO.getRecorderName())
                .recorderTime(normalizedRecorderTime)
                .reportUom(firstNotBlank(operation.getUom(), operation.getUnitCode(), operation.getUnitName(), planOrder.getTargetUom()))
                .reportMinutes(calculateMinutes(normalizedStartTime, effectiveEndTime))
                .reportType("END")
                .sourceMenuCode(SOURCE_MENU_CODE_WET)
                .extraJson(buildWetExtraJson(reqVO, normalizedInWashTime, normalizedOutWashTime, normalizedInSolidifyTime,
                        normalizedOutSolidifyTime, normalizedInOvenTime, normalizedOutOvenTime,
                        guideClothRuntime, guideClothReplaceTime, effectiveGuideClothUseCount,
                        guideClothUsedLength, guideClothLimitLength, guideClothWarningFlag))
                .remark(reqVO.getRemark())
                .build();
        hcProcessReportMapper.insert(reportDO);
        HcProcessReportDO persistedReport = hcProcessReportMapper.selectById(reportDO.getId());
        verifyOperationReportTimePersisted("湿法", reportDO.getId(), reportDate,
                normalizedStartTime, effectiveEndTime, persistedReport);
        log.info(
                "[MES报工时间提交-落库][湿法] planNo={} planOperationId={} operationReportId={} "
                        + "saveTable=mes_sfc_operation_report saveFields=report_date,start_time,end_time,recorder_time "
                        + "values reportDate={} startTime={} endTime={} recorderTime={} reportType={} sourceMenuCode={}",
                planOrder.getPlanNo(), operation.getId(), reportDO.getId(),
                persistedReport == null ? null : persistedReport.getReportDate(),
                persistedReport == null ? null : persistedReport.getStartTime(),
                persistedReport == null ? null : persistedReport.getEndTime(),
                persistedReport == null ? null : persistedReport.getRecorderTime(),
                persistedReport == null ? null : persistedReport.getReportType(), SOURCE_MENU_CODE_WET);
        insertWetAbnormalPositions(reqVO.getAbnormalPositions(), reportDO, planOrder, operation);

        BigDecimal totalGoodQty = hcProcessReportMapper.selectTotalGoodQtyBySource(operation.getId(), SOURCE_MENU_CODE_WET);
        HcPlanOrderOperationDO updateObj = new HcPlanOrderOperationDO();
        updateObj.setId(operation.getId());
        updateObj.setDispatchQty(totalGoodQty == null ? BigDecimal.ZERO : totalGoodQty);
        updateObj.setOperationStatus(OP_STATUS_FINISHED);
        updateObj.setFinishTime(effectiveEndTime);
        updateObj.setFinishRemark(firstNotBlank(reqVO.getRemark(), "湿法过站报工完成"));
        updateObj.setEquipmentId(effectiveEquipmentId);
        updateObj.setEquipmentCode(effectiveEquipmentCode);
        updateObj.setEquipmentName(effectiveEquipmentName);
        updateObj.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateObj.setStatusOperatorName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "system"));
        updateObj.setStatusOperateTime(LocalDateTime.now());
        hcPlanOrderOperationMapper.updateById(updateObj);
        log.info(
                "[MES报工时间提交-联动][湿法] planNo={} planOperationId={} "
                        + "saveTable=mes_pp_plan_operation saveField=finish_time value={}",
                planOrder.getPlanNo(), operation.getId(), effectiveEndTime);
        String operatorName = firstNotBlank(reqVO.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        LocalDateTime recordTime = normalizedRecorderTime != null ? normalizedRecorderTime : now;
        postWetOutputWipIfNeeded(planOrder, operation, reportDO, reportGoodQty, effectiveEndTime, operatorName);
        hcEquipmentService.releaseEquipment(effectiveEquipmentId, effectiveEndTime, operatorName, recordTime);
        hcGuideClothRecordService.handleWetReport(
                firstNotBlank(operation.getMotherModelCode(), planOrder.getMotherModelCode()),
                planOrder.getPlanNo(),
                reqVO.getPetBatchNo(),
                reqVO.getGuideClothBatchNo(),
                reqVO.getPetModel(),
                reqVO.getGuideClothChangeReason(),
                effectiveGuideClothUseCount,
                guideClothChanged,
                reqVO.getRemark(),
                planOrder.getTenantId(),
                effectiveEndTime,
                effectiveEquipmentId,
                effectiveEquipmentCode,
                effectiveEquipmentName,
                operation.getWorkCenterId(),
                operation.getWorkCenterCode(),
                operation.getWorkCenterName(),
                planOrder.getId(),
                operation.getId(),
                operation.getOpCode(),
                operation.getOpName(),
                reportGoodQty,
                reportDO.getId(),
                SecurityFrameworkUtils.getLoginUserId(),
                operatorName);
        return reportDO.getId();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long reviseWetReportQuantity(HcWetReportQuantityReviseReqVO reqVO) {
        BigDecimal newQty = zeroIfNull(reqVO.getReceiveLength());
        if (newQty.compareTo(BigDecimal.ZERO) <= 0) {
            throw invalidParamException("修正后收卷米数必须大于0");
        }
        String reason = StrUtil.trim(reqVO.getReason());
        if (StrUtil.isBlank(reason)) {
            throw invalidParamException("修正原因不能为空");
        }
        HcProcessReportDO report = hcProcessReportMapper.selectOne(new LambdaQueryWrapperX<HcProcessReportDO>()
                .eq(HcProcessReportDO::getId, reqVO.getId())
                .eq(HcProcessReportDO::getDeleted, false)
                .last("FOR UPDATE"));
        if (report == null) {
            throw invalidParamException("湿法报工记录不存在");
        }
        if (!SOURCE_MENU_CODE_WET.equals(report.getSourceMenuCode())
                || !"END".equalsIgnoreCase(StrUtil.trimToEmpty(report.getReportType()))) {
            throw invalidParamException("只有湿法完工报工允许修正收卷米数");
        }
        BigDecimal oldQty = zeroIfNull(report.getGoodQty());
        BigDecimal delta = newQty.subtract(oldQty);
        if (isZeroQuantityDelta(delta)) {
            return report.getId();
        }
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectByIdForUpdate(report.getPlanOperationId());
        if (operation == null || Boolean.TRUE.equals(operation.getDeleted())) {
            throw invalidParamException("湿法报工对应工序不存在");
        }
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(report.getPlanId());
        if (planOrder == null || Boolean.TRUE.equals(planOrder.getDeleted())) {
            throw invalidParamException("湿法报工对应生产计划不存在");
        }
        String revisionRemark = buildQuantityRevisionRemark("湿法收卷米数", oldQty, newQty, reason);

        HcProcessReportDO updateReport = new HcProcessReportDO();
        updateReport.setId(report.getId());
        updateReport.setGoodQty(newQty);
        updateReport.setExtraJson(reviseWetReportExtraJson(report.getExtraJson(), newQty, delta));
        updateReport.setRemark(appendQuantityRevisionRemark(report.getRemark(), revisionRemark));
        hcProcessReportMapper.updateById(updateReport);

        BigDecimal totalGoodQty = hcProcessReportMapper.selectTotalGoodQtyBySource(operation.getId(), SOURCE_MENU_CODE_WET);
        HcPlanOrderOperationDO updateOperation = new HcPlanOrderOperationDO();
        updateOperation.setId(operation.getId());
        updateOperation.setDispatchQty(zeroIfNull(totalGoodQty));
        updateOperation.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateOperation.setStatusOperatorName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统"));
        updateOperation.setStatusOperateTime(LocalDateTime.now());
        hcPlanOrderOperationMapper.updateById(updateOperation);

        HcInvStockDO stock = selectWetOutputStockForUpdate(report);
        reviseWetOutputStock(stock, report, delta, revisionRemark);
        reviseWetOutputWipInTxn(stock, report, delta, revisionRemark);
        reviseWetOutputWipLocks(stock, delta, revisionRemark);
        reviseConsumableUsageTotal(SOURCE_MENU_CODE_WET, report.getId(), CONSUMABLE_TYPE_GUIDE_CLOTH,
                newQty, revisionRemark);
        reviseWetGrindingSourceBalance(report, newQty, delta, revisionRemark);

        log.info("[湿法报工米数修正] reportId={}, planNo={}, batchNo={}, beforeQty={}, afterQty={}, delta={}",
                report.getId(), report.getPlanNo(), report.getBatchNo(), oldQty, newQty, delta);
        return report.getId();
    }

    private HcInvStockDO selectWetOutputStockForUpdate(HcProcessReportDO report) {
        if (report == null) {
            return null;
        }
        HcInvStockDO stock = report.getOutputStockId() == null ? null
                : hcInvStockMapper.selectByIdForUpdate(report.getOutputStockId());
        if (stock != null && !Boolean.TRUE.equals(stock.getDeleted())) {
            return stock;
        }
        return hcInvStockMapper.selectOneBySourceForUpdate(SOURCE_TYPE_WET, SOURCE_TABLE_OPERATION_REPORT, report.getId());
    }

    private void reviseWetOutputStock(HcInvStockDO stock,
                                      HcProcessReportDO report,
                                      BigDecimal delta,
                                      String revisionRemark) {
        if (stock == null || Boolean.TRUE.equals(stock.getDeleted())) {
            return;
        }
        if (!SOURCE_TYPE_WET.equalsIgnoreCase(stock.getSourceType())
                || !SOURCE_TABLE_OPERATION_REPORT.equalsIgnoreCase(stock.getSourceTable())
                || !Objects.equals(stock.getSourceId(), report.getId())) {
            throw invalidParamException("湿法产出库存与报工记录来源不一致，不能自动修正库存");
        }
        List<HcPlanOrderInventoryLockDO> activeLocks = hcPlanOrderInventoryLockMapper.selectListByStockId(stock.getId())
                .stream().filter(this::isActivePlanWipLock).toList();
        BigDecimal nextOnHand = zeroIfNull(stock.getOnHandQty()).add(delta);
        BigDecimal nextAvailable = zeroIfNull(stock.getAvailableQty());
        BigDecimal nextShareable = zeroIfNull(stock.getShareableQty());
        BigDecimal nextFrozen = zeroIfNull(stock.getFrozenQty());
        BigDecimal nextPlanLocked = zeroIfNull(stock.getPlanLockedQty());
        if (!activeLocks.isEmpty() || nextPlanLocked.compareTo(BigDecimal.ZERO) > 0) {
            nextFrozen = nextFrozen.add(delta);
            nextPlanLocked = nextPlanLocked.add(delta);
        } else {
            nextAvailable = nextAvailable.add(delta);
            if (nextShareable.compareTo(BigDecimal.ZERO) > 0) {
                nextShareable = nextShareable.add(delta);
            }
        }
        requireNonNegative(nextOnHand, "湿法产出库存修正后在库量");
        requireNonNegative(nextAvailable, "湿法产出库存修正后可用量");
        requireNonNegative(nextShareable, "湿法产出库存修正后可利库量");
        requireNonNegative(nextFrozen, "湿法产出库存修正后冻结量");
        requireNonNegative(nextPlanLocked, "湿法产出库存修正后计划锁定量");

        HcInvStockDO update = new HcInvStockDO();
        update.setId(stock.getId());
        update.setOnHandQty(nextOnHand);
        update.setAvailableQty(nextAvailable);
        update.setShareableQty(nextShareable);
        update.setFrozenQty(nextFrozen);
        update.setPlanLockedQty(nextPlanLocked);
        update.setBusinessRemark(appendQuantityRevisionRemark(stock.getBusinessRemark(), revisionRemark));
        hcInvStockMapper.updateById(update);
    }

    private void reviseWetOutputWipInTxn(HcInvStockDO stock,
                                         HcProcessReportDO report,
                                         BigDecimal delta,
                                         String revisionRemark) {
        if (stock == null || stock.getId() == null || report == null || report.getId() == null) {
            return;
        }
        HcInvTxnLogDO txn = hcInvTxnLogMapper.selectOne(new LambdaQueryWrapperX<HcInvTxnLogDO>()
                .eq(HcInvTxnLogDO::getStockId, stock.getId())
                .eq(HcInvTxnLogDO::getTxnType, TXN_TYPE_WIP_IN)
                .eq(HcInvTxnLogDO::getSourceType, SOURCE_TYPE_WET)
                .eq(HcInvTxnLogDO::getSourceTable, SOURCE_TABLE_OPERATION_REPORT)
                .eq(HcInvTxnLogDO::getSourceId, report.getId())
                .eq(HcInvTxnLogDO::getDeleted, false)
                .orderByDesc(HcInvTxnLogDO::getId)
                .last("LIMIT 1"));
        if (txn == null) {
            return;
        }
        BigDecimal nextTxnQty = zeroIfNull(txn.getTxnQty()).add(delta);
        BigDecimal nextAfterQty = zeroIfNull(txn.getAfterQty()).add(delta);
        BigDecimal nextAfterAvailableQty = zeroIfNull(txn.getAfterAvailableQty()).add(delta);
        requireNonNegative(nextTxnQty, "湿法 WIP 入库流水修正后交易数量");
        requireNonNegative(nextAfterQty, "湿法 WIP 入库流水修正后在库数量");
        requireNonNegative(nextAfterAvailableQty, "湿法 WIP 入库流水修正后可用数量");

        HcInvTxnLogDO update = HcInvTxnLogDO.builder()
                .id(txn.getId())
                .txnQty(nextTxnQty)
                .afterQty(nextAfterQty)
                .afterAvailableQty(nextAfterAvailableQty)
                .remark(appendQuantityRevisionRemark(txn.getRemark(), revisionRemark))
                .build();
        hcInvTxnLogMapper.updateById(update);
    }

    private void reviseWetOutputWipLocks(HcInvStockDO stock,
                                         BigDecimal delta,
                                         String revisionRemark) {
        if (stock == null || stock.getId() == null) {
            return;
        }
        for (HcPlanOrderInventoryLockDO sourceLock : hcPlanOrderInventoryLockMapper.selectListByStockId(stock.getId())) {
            if (!isActivePlanWipLock(sourceLock)) {
                continue;
            }
            HcPlanOrderInventoryLockDO lock = hcPlanOrderInventoryLockMapper.selectByIdForUpdate(sourceLock.getId());
            if (!isActivePlanWipLock(lock)) {
                continue;
            }
            BigDecimal nextAvailableQty = zeroIfNull(lock.getAvailableQty()).add(delta);
            BigDecimal nextLockQty = zeroIfNull(lock.getLockQty()).add(delta);
            BigDecimal consumedAndReleased = zeroIfNull(lock.getConsumedQty()).add(zeroIfNull(lock.getReleasedQty()));
            if (nextLockQty.compareTo(consumedAndReleased) < 0) {
                throw invalidParamException("湿法 WIP 已存在下游消耗/释放，修正后锁定量不能小于已消耗释放量");
            }
            BigDecimal nextRemainingQty = nextLockQty.subtract(consumedAndReleased);
            requireNonNegative(nextAvailableQty, "湿法 WIP 锁修正后可用快照");
            requireNonNegative(nextRemainingQty, "湿法 WIP 锁修正后剩余量");

            HcPlanOrderInventoryLockDO update = new HcPlanOrderInventoryLockDO();
            update.setId(lock.getId());
            update.setAvailableQty(nextAvailableQty);
            update.setLockQty(nextLockQty);
            update.setRemainingQty(nextRemainingQty);
            update.setRemark(appendQuantityRevisionRemark(lock.getRemark(), revisionRemark));
            hcPlanOrderInventoryLockMapper.updateById(update);
            reviseWetOutputWipLockTxn(lock, delta, revisionRemark);
        }
    }

    private void reviseWetOutputWipLockTxn(HcPlanOrderInventoryLockDO lock,
                                           BigDecimal delta,
                                           String revisionRemark) {
        HcInvTxnLogDO txn = hcInvTxnLogMapper.selectOne(new LambdaQueryWrapperX<HcInvTxnLogDO>()
                .eq(HcInvTxnLogDO::getStockId, lock.getStockId())
                .eq(HcInvTxnLogDO::getTxnType, TXN_TYPE_WIP_LOCK)
                .eq(HcInvTxnLogDO::getRefDocType, REF_DOC_TYPE_PLAN_WIP_LOCK)
                .eq(HcInvTxnLogDO::getRefDocId, lock.getId())
                .eq(HcInvTxnLogDO::getDeleted, false)
                .orderByDesc(HcInvTxnLogDO::getId)
                .last("LIMIT 1"));
        if (txn == null) {
            return;
        }
        BigDecimal nextBeforeQty = zeroIfNull(txn.getBeforeQty()).add(delta);
        BigDecimal nextAfterQty = zeroIfNull(txn.getAfterQty()).add(delta);
        BigDecimal nextBeforeAvailableQty = zeroIfNull(txn.getBeforeAvailableQty()).add(delta);
        BigDecimal nextAfterPlanLockedQty = zeroIfNull(txn.getAfterPlanLockedQty()).add(delta);
        BigDecimal nextAfterFrozenQty = zeroIfNull(txn.getAfterFrozenQty()).add(delta);
        BigDecimal nextAfterAvailableQty = nextBeforeAvailableQty.subtract(nextAfterPlanLockedQty);
        requireNonNegative(nextBeforeQty, "湿法 WIP 锁库流水修正前在库量");
        requireNonNegative(nextAfterQty, "湿法 WIP 锁库流水修正后在库量");
        requireNonNegative(nextBeforeAvailableQty, "湿法 WIP 锁库流水修正前可用量");
        requireNonNegative(nextAfterFrozenQty, "湿法 WIP 锁库流水修正后冻结量");
        requireNonNegative(nextAfterPlanLockedQty, "湿法 WIP 锁库流水修正后计划锁定量");
        requireNonNegative(nextAfterAvailableQty, "湿法 WIP 锁库流水修正后可用量");

        HcInvTxnLogDO update = HcInvTxnLogDO.builder()
                .id(txn.getId())
                .beforeQty(nextBeforeQty)
                .afterQty(nextAfterQty)
                .beforeAvailableQty(nextBeforeAvailableQty)
                .afterAvailableQty(nextAfterAvailableQty)
                .afterFrozenQty(nextAfterFrozenQty)
                .afterPlanLockedQty(nextAfterPlanLockedQty)
                .remark(appendQuantityRevisionRemark(txn.getRemark(), revisionRemark))
                .build();
        hcInvTxnLogMapper.updateById(update);
    }

    private void reviseWetGrindingSourceBalance(HcProcessReportDO report,
                                                BigDecimal newQty,
                                                BigDecimal delta,
                                                String revisionRemark) {
        String batchNo = firstNotBlank(report.getProductionBatchNo(), report.getBatchNo());
        if (StrUtil.isBlank(batchNo)) {
            return;
        }
        HcGrindingSourceBalanceDO balance = hcGrindingSourceBalanceMapper.selectByBatchNoForUpdate(batchNo);
        BigDecimal usedFirstLength = balance == null ? BigDecimal.ZERO : zeroIfNull(balance.getUsedFirstLength());
        List<HcGrindingAllocationModeDO> modes = hcGrindingAllocationModeMapper.selectList(
                new LambdaQueryWrapperX<HcGrindingAllocationModeDO>()
                        .eq(HcGrindingAllocationModeDO::getMotherBatchNo, batchNo)
                        .eq(HcGrindingAllocationModeDO::getDeleted, false));
        BigDecimal allocatedLength = BigDecimal.ZERO;
        for (HcGrindingAllocationModeDO mode : modes) {
            HcGrindingAllocationModeDO lockedMode = hcGrindingAllocationModeMapper
                    .selectByMotherBatchForUpdate(mode.getPlanOperationId(), mode.getMotherBatchNo());
            if (lockedMode == null || !ALLOCATION_MODE_FIRST_ALLOCATED.equals(lockedMode.getAllocationMode())) {
                continue;
            }
            List<HcGrindingFirstAllocationDO> allocations = hcGrindingFirstAllocationMapper.selectListByModeId(lockedMode.getId());
            BigDecimal modeAllocatedLength = allocations.stream()
                    .map(HcGrindingFirstAllocationDO::getConfirmedLength)
                    .map(this::zeroIfNull)
                    .reduce(BigDecimal.ZERO, BigDecimal::add);
            if (newQty.subtract(modeAllocatedLength).compareTo(new BigDecimal("-0.0001")) < 0) {
                throw invalidParamException("湿法修正后米数小于已完成的一次磨皮分段累计米数，不能修正");
            }
            allocatedLength = allocatedLength.add(modeAllocatedLength);
            BigDecimal nextAvailableLengthAtLock = zeroIfNull(lockedMode.getAvailableLengthAtLock()).add(delta);
            if (nextAvailableLengthAtLock.compareTo(modeAllocatedLength) < 0) {
                nextAvailableLengthAtLock = modeAllocatedLength;
            }
            HcGrindingAllocationModeDO updateMode = HcGrindingAllocationModeDO.builder()
                    .id(lockedMode.getId())
                    .availableLengthAtLock(nextAvailableLengthAtLock)
                    .build();
            hcGrindingAllocationModeMapper.updateById(updateMode);
        }
        if (balance == null) {
            return;
        }
        if (allocatedLength.compareTo(BigDecimal.ZERO) > 0) {
            usedFirstLength = allocatedLength;
        }
        if (newQty.subtract(usedFirstLength).compareTo(new BigDecimal("-0.0001")) < 0) {
            throw invalidParamException("湿法修正后米数小于已占用的一次磨皮米数，不能修正");
        }
        BigDecimal reservedLength = zeroIfNull(balance.getReservedLength());
        BigDecimal nextAvailableLength = newQty.subtract(usedFirstLength).subtract(reservedLength);
        if (nextAvailableLength.compareTo(BigDecimal.ZERO) < 0) {
            nextAvailableLength = BigDecimal.ZERO;
        }
        HcGrindingSourceBalanceDO updateBalance = HcGrindingSourceBalanceDO.builder()
                .id(balance.getId())
                .totalLength(newQty)
                .usedFirstLength(usedFirstLength)
                .availableLength(nextAvailableLength)
                .lastReportTime(LocalDateTime.now())
                .status(nextAvailableLength.compareTo(BigDecimal.ZERO) > 0 ? "AVAILABLE" : "USED_UP")
                .remark(appendQuantityRevisionRemark(balance.getRemark(), revisionRemark))
                .build();
        hcGrindingSourceBalanceMapper.updateById(updateBalance);
    }

    private HcEquipmentConsumableEventDO reviseConsumableUsageTotal(String bizType,
                                                                    Long bizId,
                                                                    String consumableType,
                                                                    BigDecimal newTotalLength,
                                                                    String revisionRemark) {
        if (StrUtil.isBlank(bizType) || bizId == null || StrUtil.isBlank(consumableType)) {
            return null;
        }
        List<HcEquipmentConsumableEventDO> usageEvents = hcEquipmentConsumableEventMapper.selectList(
                new LambdaQueryWrapperX<HcEquipmentConsumableEventDO>()
                        .eq(HcEquipmentConsumableEventDO::getBizType, bizType)
                        .eq(HcEquipmentConsumableEventDO::getBizId, bizId)
                        .eq(HcEquipmentConsumableEventDO::getConsumableType, consumableType)
                        .eq(HcEquipmentConsumableEventDO::getEventType, CONSUMABLE_EVENT_USE)
                        .eq(HcEquipmentConsumableEventDO::getDeleted, false)
                        .orderByAsc(HcEquipmentConsumableEventDO::getEventTime)
                        .orderByAsc(HcEquipmentConsumableEventDO::getId));
        if (usageEvents.isEmpty()) {
            return null;
        }
        BigDecimal oldTotalLength = usageEvents.stream()
                .map(HcEquipmentConsumableEventDO::getChangeLength)
                .map(this::zeroIfNull)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal delta = zeroIfNull(newTotalLength).subtract(oldTotalLength);
        if (isZeroQuantityDelta(delta)) {
            return usageEvents.get(usageEvents.size() - 1);
        }
        HcEquipmentConsumableEventDO targetEvent = usageEvents.get(usageEvents.size() - 1);
        BigDecimal nextChangeLength = zeroIfNull(targetEvent.getChangeLength()).add(delta);
        BigDecimal nextAfterUsedLength = zeroIfNull(targetEvent.getAfterUsedLength()).add(delta);
        requireNonNegative(nextChangeLength, "耗材使用事件修正后用量");
        requireNonNegative(nextAfterUsedLength, "耗材使用事件修正后累计量");
        HcEquipmentConsumableEventDO updateEvent = HcEquipmentConsumableEventDO.builder()
                .id(targetEvent.getId())
                .changeLength(nextChangeLength)
                .afterUsedLength(nextAfterUsedLength)
                .remark(appendQuantityRevisionRemark(targetEvent.getRemark(), revisionRemark))
                .build();
        hcEquipmentConsumableEventMapper.updateById(updateEvent);
        targetEvent.setChangeLength(nextChangeLength);
        targetEvent.setAfterUsedLength(nextAfterUsedLength);
        shiftLaterConsumableLength(targetEvent, delta, revisionRemark);
        return targetEvent;
    }

    private void shiftLaterConsumableLength(HcEquipmentConsumableEventDO anchorEvent,
                                            BigDecimal delta,
                                            String revisionRemark) {
        if (anchorEvent == null || anchorEvent.getStateId() == null
                || anchorEvent.getEventTime() == null || anchorEvent.getId() == null
                || isZeroQuantityDelta(delta)) {
            return;
        }
        boolean replacedAfterAnchor = false;
        List<HcEquipmentConsumableEventDO> laterEvents = hcEquipmentConsumableEventMapper.selectList(
                new LambdaQueryWrapperX<HcEquipmentConsumableEventDO>()
                        .eq(HcEquipmentConsumableEventDO::getStateId, anchorEvent.getStateId())
                        .eq(HcEquipmentConsumableEventDO::getDeleted, false)
                        .and(wrapper -> wrapper
                                .gt(HcEquipmentConsumableEventDO::getEventTime, anchorEvent.getEventTime())
                                .or(nested -> nested
                                        .eq(HcEquipmentConsumableEventDO::getEventTime, anchorEvent.getEventTime())
                                        .gt(HcEquipmentConsumableEventDO::getId, anchorEvent.getId())))
                        .orderByAsc(HcEquipmentConsumableEventDO::getEventTime)
                        .orderByAsc(HcEquipmentConsumableEventDO::getId));
        for (HcEquipmentConsumableEventDO event : laterEvents) {
            BigDecimal nextBeforeUsed = event.getBeforeUsedLength() == null ? null : event.getBeforeUsedLength().add(delta);
            BigDecimal nextAfterUsed = event.getAfterUsedLength() == null ? null : event.getAfterUsedLength().add(delta);
            if (nextBeforeUsed != null) {
                requireNonNegative(nextBeforeUsed, "后续耗材事件修正后使用前累计量");
            }
            if (CONSUMABLE_EVENT_REPLACE.equalsIgnoreCase(event.getEventType())) {
                nextAfterUsed = event.getAfterUsedLength();
                replacedAfterAnchor = true;
            } else if (nextAfterUsed != null) {
                requireNonNegative(nextAfterUsed, "后续耗材事件修正后使用后累计量");
            }
            HcEquipmentConsumableEventDO update = HcEquipmentConsumableEventDO.builder()
                    .id(event.getId())
                    .beforeUsedLength(nextBeforeUsed)
                    .afterUsedLength(nextAfterUsed)
                    .remark(appendQuantityRevisionRemark(event.getRemark(), revisionRemark))
                    .build();
            hcEquipmentConsumableEventMapper.updateById(update);
            if (replacedAfterAnchor) {
                break;
            }
        }
        if (replacedAfterAnchor) {
            return;
        }
        HcEquipmentConsumableStateDO state = hcEquipmentConsumableStateMapper.selectById(anchorEvent.getStateId());
        if (state == null || Boolean.TRUE.equals(state.getDeleted())) {
            return;
        }
        BigDecimal nextUsedLength = zeroIfNull(state.getUsedLength()).add(delta);
        requireNonNegative(nextUsedLength, "耗材状态修正后累计米数");
        HcEquipmentConsumableStateDO updateState = HcEquipmentConsumableStateDO.builder()
                .id(state.getId())
                .usedLength(nextUsedLength)
                .warningFlag(calcConsumableLengthWarningFlag(nextUsedLength, state.getLimitLength()))
                .remark(appendQuantityRevisionRemark(state.getRemark(), revisionRemark))
                .build();
        hcEquipmentConsumableStateMapper.updateById(updateState);
    }

    private String reviseWetReportExtraJson(String extraJson, BigDecimal newQty, BigDecimal delta) {
        Map<String, Object> extra = StrUtil.isBlank(extraJson)
                ? new LinkedHashMap<>()
                : JsonUtils.parseObjectQuietly(extraJson, new TypeReference<Map<String, Object>>() {});
        if (extra == null) {
            extra = new LinkedHashMap<>();
        }
        extra.put("receiveLength", newQty);
        BigDecimal guideClothUsedLength = parseDecimalFromObject(extra.get("guideClothUsedLength"));
        if (guideClothUsedLength != null) {
            extra.put("guideClothUsedLength", guideClothUsedLength.add(delta));
        }
        return JsonUtils.toJsonString(extra);
    }

    private String reviseWetReportStatisticsExtraJson(String extraJson,
                                                      BigDecimal newGoodQty,
                                                      BigDecimal goodDelta,
                                                      BigDecimal newScrapQty,
                                                      Map<String, Object> before,
                                                      Map<String, Object> after,
                                                      String reason) {
        Map<String, Object> extra = StrUtil.isBlank(extraJson)
                ? new LinkedHashMap<>()
                : JsonUtils.parseObjectQuietly(extraJson, new TypeReference<Map<String, Object>>() {});
        if (extra == null) {
            extra = new LinkedHashMap<>();
        }
        extra.put("receiveLength", newGoodQty);
        extra.put("printLossLength", newScrapQty);
        BigDecimal guideClothUsedLength = parseDecimalFromObject(extra.get("guideClothUsedLength"));
        if (guideClothUsedLength != null && !isZeroQuantityDelta(goodDelta)) {
            extra.put("guideClothUsedLength", guideClothUsedLength.add(goodDelta));
        }
        appendStatisticsRevisionHistory(extra, "湿法", before, after, reason);
        return JsonUtils.toJsonString(extra);
    }

    private HcProcessReportDO selectOperationReportForStatisticsRevision(Long id,
                                                                         String sourceMenuCode,
                                                                         String processName) {
        if (id == null) {
            throw invalidParamException(processName + "报工记录不能为空");
        }
        HcProcessReportDO report = hcProcessReportMapper.selectOne(new LambdaQueryWrapperX<HcProcessReportDO>()
                .eq(HcProcessReportDO::getId, id)
                .eq(HcProcessReportDO::getDeleted, false)
                .last("FOR UPDATE"));
        if (report == null) {
            throw invalidParamException(processName + "报工记录不存在");
        }
        if (!sourceMenuCode.equals(report.getSourceMenuCode())) {
            throw invalidParamException("当前报工记录不是" + processName + "报工，不能修订" + processName + "统计数据");
        }
        return report;
    }

    private BigDecimal statisticsValueOrCurrent(BigDecimal requested, BigDecimal current) {
        return requested == null ? zeroIfNull(current) : requested;
    }

    private String requireStatisticsRevisionReason(String reason) {
        String normalized = StrUtil.trim(reason);
        if (StrUtil.isBlank(normalized)) {
            throw invalidParamException("修订原因不能为空");
        }
        return normalized;
    }

    private void refreshOperationDispatchQty(Long planOperationId, String sourceMenuCode, String processName) {
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectByIdForUpdate(planOperationId);
        if (operation == null || Boolean.TRUE.equals(operation.getDeleted())) {
            throw invalidParamException(processName + "报工对应工序不存在");
        }
        BigDecimal totalGoodQty = SOURCE_MENU_CODE_FORMULA.equals(sourceMenuCode)
                ? hcProcessReportMapper.selectFormulaTotalGoodQty(operation.getId())
                : hcProcessReportMapper.selectTotalGoodQtyBySource(operation.getId(), sourceMenuCode);
        HcPlanOrderOperationDO updateOperation = new HcPlanOrderOperationDO();
        updateOperation.setId(operation.getId());
        updateOperation.setDispatchQty(zeroIfNull(totalGoodQty));
        updateOperation.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateOperation.setStatusOperatorName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统"));
        updateOperation.setStatusOperateTime(LocalDateTime.now());
        hcPlanOrderOperationMapper.updateById(updateOperation);
    }

    private String appendStatisticsRevisionHistory(String extraJson,
                                                   String processName,
                                                   Map<String, Object> before,
                                                   Map<String, Object> after,
                                                   String reason) {
        Map<String, Object> extra = StrUtil.isBlank(extraJson)
                ? new LinkedHashMap<>()
                : JsonUtils.parseObjectQuietly(extraJson, new TypeReference<Map<String, Object>>() {});
        if (extra == null) {
            extra = new LinkedHashMap<>();
        }
        appendStatisticsRevisionHistory(extra, processName, before, after, reason);
        return JsonUtils.toJsonString(extra);
    }

    private void appendStatisticsRevisionHistory(Map<String, Object> extra,
                                                 String processName,
                                                 Map<String, Object> before,
                                                 Map<String, Object> after,
                                                 String reason) {
        List<Object> history = new ArrayList<>();
        Object existedHistory = extra.get("statisticsDataRevisionHistory");
        if (existedHistory instanceof List<?> list) {
            history.addAll(list);
        }
        Map<String, Object> revision = new LinkedHashMap<>();
        revision.put("processName", processName);
        revision.put("revisionTime", LocalDateTime.now().format(DATETIME_FORMATTER));
        revision.put("operatorId", SecurityFrameworkUtils.getLoginUserId());
        revision.put("operatorName", firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统"));
        revision.put("reason", reason);
        revision.put("before", before);
        revision.put("after", after);
        history.add(revision);
        extra.put("statisticsDataRevisionHistory", history);
    }

    private String buildStatisticsRevisionRemark(String processName,
                                                 Map<String, Object> before,
                                                 Map<String, Object> after,
                                                 String reason) {
        return processName + "母卷批次良品统计数据由[" + formatStatisticsRevisionFields(before)
                + "]调整为[" + formatStatisticsRevisionFields(after) + "]；原因：" + StrUtil.trim(reason)
                + "；时间：" + LocalDateTime.now().format(DATETIME_FORMATTER);
    }

    private String formatStatisticsRevisionFields(Map<String, Object> values) {
        if (values == null || values.isEmpty()) {
            return "-";
        }
        return values.entrySet().stream()
                .map(entry -> entry.getKey() + "=" + formatStatisticsRevisionValue(entry.getValue()))
                .collect(Collectors.joining(","));
    }

    private String formatStatisticsRevisionValue(Object value) {
        BigDecimal decimal = parseDecimalFromObject(value);
        if (decimal != null) {
            return formatDecimal(decimal);
        }
        return value == null ? "-" : String.valueOf(value);
    }

    private BigDecimal parseDecimalFromObject(Object value) {
        if (value instanceof BigDecimal decimal) {
            return decimal;
        }
        if (value instanceof Number number) {
            return new BigDecimal(number.toString());
        }
        return parseDecimalFromText(value == null ? null : String.valueOf(value));
    }

    private String buildQuantityRevisionRemark(String label, BigDecimal oldQty, BigDecimal newQty, String reason) {
        return label + "由" + formatDecimal(oldQty) + "m调整为" + formatDecimal(newQty) + "m；原因：" + StrUtil.trim(reason);
    }

    private String appendQuantityRevisionRemark(String currentRemark, String revisionRemark) {
        String remark = StrUtil.trim(currentRemark);
        String revision = StrUtil.trim(revisionRemark);
        if (StrUtil.isBlank(revision)) {
            return remark;
        }
        return StrUtil.isBlank(remark) ? "数据修正：" + revision : remark + "；数据修正：" + revision;
    }

    private boolean isZeroQuantityDelta(BigDecimal delta) {
        return delta == null || delta.abs().compareTo(new BigDecimal("0.0001")) <= 0;
    }

    private void requireNonNegative(BigDecimal value, String label) {
        if (value != null && value.compareTo(BigDecimal.ZERO) < 0) {
            throw invalidParamException(label + "不能为负数");
        }
    }

    private Integer calcConsumableLengthWarningFlag(BigDecimal usedLength, BigDecimal limitLength) {
        if (limitLength == null || limitLength.compareTo(BigDecimal.ZERO) <= 0) {
            return 0;
        }
        return zeroIfNull(usedLength).compareTo(limitLength) >= 0 ? 1 : 0;
    }

    private void postWetOutputWipIfNeeded(HcPlanOrderDO planOrder,
                                          HcPlanOrderOperationDO operation,
                                          HcProcessReportDO reportDO,
                                          BigDecimal outputQty,
                                          LocalDateTime postTime,
                                          String operatorName) {
        if (reportDO == null || reportDO.getId() == null || reportDO.getOutputStockId() != null) {
            return;
        }
        BigDecimal normalizedOutputQty = zeroIfNull(outputQty);
        if (normalizedOutputQty.compareTo(BigDecimal.ZERO) <= 0) {
            return;
        }
        HcInvStockDO stock = hcInvStockService.postProcessOutputWip(HcWipOutputPostReq.builder()
                .plan(planOrder)
                .operation(operation)
                .sourceType(SOURCE_TYPE_WET)
                .sourceTable(SOURCE_TABLE_OPERATION_REPORT)
                .sourceId(reportDO.getId())
                .sourceReportId(reportDO.getId())
                .batchNo(firstNotBlank(reportDO.getProductionBatchNo(), operation.getProductionBatchNo(),
                        planOrder.getProductionBatchNo(), planOrder.getBatchNo()))
                .parentBatchNo(firstNotBlank(reportDO.getParentProductionBatchNo(), reportDO.getParentBatchNo(),
                        operation.getParentProductionBatchNo(), planOrder.getParentProductionBatchNo(), planOrder.getBatchNo()))
                .outputQty(normalizedOutputQty)
                .uom(firstNotBlank(reportDO.getReportUom(), operation.getUom(), "m"))
                .modelNo(firstNotBlank(planOrder.getModelCode(), planOrder.getModelName()))
                .businessRemark("湿法确认产出入中间边库；来源计划：" + firstNotBlank(planOrder.getPlanNo(), "-"))
                .txnRemark("湿法完工确认自动入中间边库")
                .postTime(postTime)
                .operatorId(SecurityFrameworkUtils.getLoginUserId())
                .operatorName(firstNotBlank(operatorName, SecurityFrameworkUtils.getLoginUserNickname(), "系统"))
                .build());
        HcProcessReportDO stockUpdate = new HcProcessReportDO();
        stockUpdate.setId(reportDO.getId());
        stockUpdate.setOutputStockId(stock.getId());
        stockUpdate.setOutputStockPostStatus(STOCK_POST_STATUS_POSTED);
        stockUpdate.setOutputStockPostTime(stock.getLastTxnTime());
        stockUpdate.setOutputStockPostMessage("湿法完工确认自动入中间边库");
        hcProcessReportMapper.updateById(stockUpdate);
        reportDO.setOutputStockId(stock.getId());
        reportDO.setOutputStockPostStatus(STOCK_POST_STATUS_POSTED);
        reportDO.setOutputStockPostTime(stock.getLastTxnTime());
        reportDO.setOutputStockPostMessage(stockUpdate.getOutputStockPostMessage());
    }

    @Override
    public List<HcRoughReportTaskRespVO> getRoughTaskList(HcRoughReportTaskPageReqVO reqVO) {
        String taskStatus = StrUtil.blankToDefault(reqVO.getTaskStatus(), "ALL");
        List<HcRoughReportTaskRespVO> tasks = hcProcessReportMapper.selectRoughTaskList(
                taskStatus, reqVO.getTaskKeyword(), reqVO.getProductKeyword(),
                reqVO.getMotherMaterialKeyword(), reqVO.getMotherModelKeyword(), reqVO.getProductionDate(),
                reqVO.getEquipmentId(), reqVO.getEquipmentCode());
        for (HcRoughReportTaskRespVO task : tasks) {
            fillRoughTaskFromGrindingTables(task);
            fillRoughTaskQtime(task);
        }
        return tasks;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long startRoughReport(HcRoughReportStartReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectByIdForUpdate(reqVO.getPlanId());
        assertPlanReleasedForStart(planOrder);
        HcPlanOrderOperationDO operation = validateRoughOperation(planOrder, reqVO.getPlanOperationId());
        if (OP_STATUS_FINISHED.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序已完工，不能再开工");
        }
        if (OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序已开工");
        }
        validatePreviousOperationReported(planOrder.getId(), operation);
        LocalDate reportDate = reqVO.getReportDate() == null ? LocalDate.now() : reqVO.getReportDate();
        boolean placeholderStartTime = isPlaceholderDateTime(reqVO.getStartTime());
        boolean placeholderRecorderTime = isPlaceholderDateTime(reqVO.getRecorderTime());
        LocalDateTime normalizedStartTime = normalizeReportDateTime(reqVO.getStartTime(), reportDate);
        LocalDateTime normalizedRecorderTime = normalizeReportDateTime(reqVO.getRecorderTime(), reportDate);
        LocalDateTime now = LocalDateTime.now();
        if (normalizedStartTime == null || placeholderStartTime) {
            normalizedStartTime = now;
        }
        if (normalizedRecorderTime == null || placeholderRecorderTime) {
            normalizedRecorderTime = now;
        }
        HcProcessReportDO reportDO = HcProcessReportDO.builder()
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .operationStatus(operation.getOperationStatus())
                .operationSeq(operation.getOpSeq())
                .operationCode(operation.getOpCode())
                .operationName(operation.getOpName())
                .workCenterId(operation.getWorkCenterId())
                .workCenterCode(operation.getWorkCenterCode())
                .workCenterName(operation.getWorkCenterName())
                .equipmentId(reqVO.getEquipmentId())
                .equipmentCode(firstNotBlank(reqVO.getEquipmentCode(), operation.getEquipmentCode()))
                .equipmentName(firstNotBlank(reqVO.getEquipmentName(), operation.getEquipmentName()))
                .materialId(planOrder.getMaterialId())
                .materialCode(planOrder.getMaterialCode())
                .materialName(planOrder.getMaterialName())
                .motherMaterialId(planOrder.getMotherMaterialId())
                .motherMaterialCode(firstNotBlank(operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode()))
                .motherMaterialName(firstNotBlank(operation.getMotherMaterialName(), planOrder.getMotherMaterialName()))
                .motherModelId(planOrder.getMotherModelId())
                .motherModelCode(firstNotBlank(operation.getMotherModelCode(), planOrder.getMotherModelCode()))
                .motherModelName(firstNotBlank(operation.getMotherModelName(), planOrder.getMotherModelName()))
                .batchNo(firstNotBlank(planOrder.getBatchNo(), operation.getBatchNo()))
                .parentBatchNo(firstNotBlank(operation.getParentBatchNo(), planOrder.getBatchNo()))
                .sampleCode(operation.getSampleCode())
                .reportDate(reportDate)
                .startTime(normalizedStartTime)
                .goodQty(BigDecimal.ZERO)
                .scrapQty(BigDecimal.ZERO)
                .recorderName(reqVO.getRecorderName())
                .recorderTime(normalizedRecorderTime)
                .reportUom(firstNotBlank(operation.getUom(), operation.getUnitCode(), operation.getUnitName(), planOrder.getTargetUom()))
                .reportType(REPORT_TYPE_START)
                .sourceMenuCode(SOURCE_MENU_CODE_ROUGH)
                .build();
        hcProcessReportMapper.insert(reportDO);

        HcPlanOrderOperationDO updateObj = new HcPlanOrderOperationDO();
        updateObj.setId(operation.getId());
        updateObj.setOperationStatus(OP_STATUS_RUNNING);
        updateObj.setEquipmentId(reqVO.getEquipmentId());
        updateObj.setEquipmentCode(firstNotBlank(reqVO.getEquipmentCode(), operation.getEquipmentCode()));
        updateObj.setEquipmentName(firstNotBlank(reqVO.getEquipmentName(), operation.getEquipmentName()));
        updateObj.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateObj.setStatusOperatorName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "system"));
        updateObj.setStatusOperateTime(LocalDateTime.now());
        hcPlanOrderOperationMapper.updateById(updateObj);

        String operatorName = firstNotBlank(reqVO.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        ensureWetOutputWipLockedForRoughStart(planOrder, operation, operatorName);
        LocalDateTime recordTime = normalizedRecorderTime != null ? normalizedRecorderTime : now;
        hcEquipmentService.occupyEquipment(reqVO.getEquipmentId(), planOrder.getPlanNo(), operation.getOpCode(),
                operation.getOpName(), normalizedStartTime, operatorName, recordTime);
        return reportDO.getId();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void switchRoughEquipment(HcRoughReportSwitchEquipmentReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validateRoughOperation(planOrder, reqVO.getPlanOperationId());
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序未开工，不能切换设备");
        }
        HcProcessReportDO latestReport = getLatestReport(operation.getId(), SOURCE_MENU_CODE_ROUGH);
        if (latestReport == null) {
            throw invalidParamException("当前工序未找到有效报工记录，不能切换设备");
        }
        Long oldEquipmentId = firstNotNull(latestReport.getEquipmentId(), operation.getEquipmentId());
        String oldEquipmentCode = firstNotBlank(latestReport.getEquipmentCode(), operation.getEquipmentCode());
        String oldEquipmentName = firstNotBlank(latestReport.getEquipmentName(), operation.getEquipmentName());
        Long newEquipmentId = firstNotNull(reqVO.getEquipmentId(), oldEquipmentId);
        String newEquipmentCode = firstNotBlank(reqVO.getEquipmentCode(), oldEquipmentCode);
        String newEquipmentName = firstNotBlank(reqVO.getEquipmentName(), oldEquipmentName);

        String operatorName = firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        LocalDateTime recordTime = LocalDateTime.now();
        LocalDateTime startTime = latestReport.getStartTime() != null ? latestReport.getStartTime() : recordTime;
        if (!Objects.equals(oldEquipmentId, newEquipmentId)) {
            hcEquipmentService.releaseEquipment(oldEquipmentId, null, operatorName, recordTime);
            hcEquipmentService.occupyEquipment(newEquipmentId, planOrder.getPlanNo(), operation.getOpCode(),
                    operation.getOpName(), startTime, operatorName, recordTime);
        }

        HcProcessReportDO updateReport = new HcProcessReportDO();
        updateReport.setId(latestReport.getId());
        updateReport.setEquipmentId(newEquipmentId);
        updateReport.setEquipmentCode(newEquipmentCode);
        updateReport.setEquipmentName(newEquipmentName);
        hcProcessReportMapper.updateById(updateReport);

        HcPlanOrderOperationDO updateOperation = new HcPlanOrderOperationDO();
        updateOperation.setId(operation.getId());
        updateOperation.setEquipmentId(newEquipmentId);
        updateOperation.setEquipmentCode(newEquipmentCode);
        updateOperation.setEquipmentName(newEquipmentName);
        updateOperation.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateOperation.setStatusOperatorName(operatorName);
        updateOperation.setStatusOperateTime(recordTime);
        hcPlanOrderOperationMapper.updateById(updateOperation);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long saveRoughProgress(HcRoughReportSaveReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validateRoughOperation(planOrder, reqVO.getPlanOperationId());
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序未开工，不能保存磨皮过程记录");
        }
        ensureWetOutputWipLockedForRoughStart(planOrder, operation,
                firstNotBlank(reqVO.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统"));
        return insertRoughReportSnapshot(planOrder, operation, reqVO, "PROGRESS", false);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long submitRoughReport(HcRoughReportSaveReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        if (!PLAN_STATUS_RELEASED.equals(planOrder.getPlanStatus())) {
            throw invalidParamException("只有已下达的生产计划允许报工");
        }
        HcPlanOrderOperationDO operation = validateRoughOperation(planOrder, reqVO.getPlanOperationId());
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            if (OP_STATUS_FINISHED.equals(operation.getOperationStatus())) {
                throw invalidParamException("当前工序已完工，不能继续报工");
            }
            throw invalidParamException("当前工序状态不允许报工");
        }
        Long reportId = insertRoughReportSnapshot(planOrder, operation, reqVO, "END", true);
        JsonNode roughRoot = parseRoughExtraRoot(reqVO.getExtraJson());
        RoughGrindingAggregate firstAggregate = buildRoughAggregate(roughRoot, "materialUsageRows",
                reqVO.getFirstProcessLength(), reqVO.getFirstLossLength(), reqVO.getFirstOutputLength(),
                reqVO.getFirstNapSampleLength(), reqVO.getLastFirstSandpaperBatchNo(),
                reqVO.getLastFirstSandpaperLife(), reqVO.getLastFirstSandpaperLifeDays());
        RoughGrindingAggregate secondAggregate = buildRoughAggregate(roughRoot, "secondGrindingRows",
                reqVO.getSecondProcessLength(), reqVO.getSecondLossLength(), reqVO.getSecondOutputLength(),
                reqVO.getSecondNapSampleLength(), reqVO.getLastSecondSandpaperBatchNo(),
                reqVO.getLastSecondSandpaperLife(), reqVO.getLastSecondSandpaperLifeDays());
        BigDecimal totalGoodQty = hcProcessReportMapper.selectTotalGoodQtyBySource(operation.getId(), SOURCE_MENU_CODE_ROUGH);
        LocalDate reportDate = reqVO.getReportDate() == null ? LocalDate.now() : reqVO.getReportDate();
        LocalDateTime normalizedEndTime = normalizeReportDateTime(reqVO.getEndTime(), reportDate);
        LocalDateTime now = LocalDateTime.now();
        if (normalizedEndTime == null) {
            normalizedEndTime = now;
        }

        HcPlanOrderOperationDO updateObj = new HcPlanOrderOperationDO();
        updateObj.setId(operation.getId());
        updateObj.setDispatchQty(totalGoodQty == null ? BigDecimal.ZERO : totalGoodQty);
        updateObj.setOperationStatus(OP_STATUS_FINISHED);
        updateObj.setFinishTime(normalizedEndTime);
        updateObj.setFinishRemark(buildRoughFinishRemark(firstAggregate, secondAggregate, reqVO.getRemark()));
        updateObj.setEquipmentId(reqVO.getEquipmentId());
        updateObj.setEquipmentCode(firstNotBlank(reqVO.getEquipmentCode(), operation.getEquipmentCode()));
        updateObj.setEquipmentName(firstNotBlank(reqVO.getEquipmentName(), operation.getEquipmentName()));
        updateObj.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateObj.setStatusOperatorName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "system"));
        updateObj.setStatusOperateTime(LocalDateTime.now());
        hcPlanOrderOperationMapper.updateById(updateObj);

        String operatorName = firstNotBlank(reqVO.getConfirmerName(), reqVO.getRecorderName(),
                SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        LocalDate reportBizDate = reqVO.getReportDate() == null ? LocalDate.now() : reqVO.getReportDate();
        LocalDateTime normalizedRecorderTime = normalizeReportDateTime(reqVO.getRecorderTime(), reportBizDate);
        LocalDateTime normalizedConfirmerTime = normalizeReportDateTime(reqVO.getConfirmerTime(), reportBizDate);
        LocalDateTime recordTime = normalizedConfirmerTime != null
                ? normalizedConfirmerTime
                : (normalizedRecorderTime != null ? normalizedRecorderTime : now);
        if (hasConfirmedRoughSecondRows(reqVO)) {
            consumeRoughWetWipLockIfPresent(planOrder, operation, reportId, reqVO, recordTime, operatorName);
        }
        hcEquipmentService.releaseEquipment(reqVO.getEquipmentId(), normalizedEndTime, operatorName, recordTime);
        return reportId;
    }

    private boolean hasConfirmedRoughSecondRows(HcRoughReportSaveReqVO reqVO) {
        JsonNode roughRoot = reqVO == null ? null : parseRoughExtraRoot(reqVO.getExtraJson());
        JsonNode rows = roughRoot == null ? null : roughRoot.path("secondGrindingRows");
        if (rows == null || !rows.isArray()) {
            return false;
        }
        for (JsonNode row : rows) {
            if ("CONFIRMED".equalsIgnoreCase(normalizeRoughSecondConfirmStatus(readJsonText(row, "confirmStatus")))) {
                return true;
            }
        }
        return false;
    }

    private List<HcPlanOrderInventoryLockDO> ensureWetOutputWipLockedForRoughStart(HcPlanOrderDO planOrder,
                                                                                   HcPlanOrderOperationDO operation,
                                                                                   String operatorName) {
        List<HcPlanOrderInventoryLockDO> activeLocks = selectActiveWetOutputWipLocks(operation == null ? null : operation.getId());
        if (!activeLocks.isEmpty()) {
            return activeLocks;
        }
        List<HcInvStockDO> wetStocks = selectAvailableWetOutputWipStocks(planOrder, operation);
        if (wetStocks.isEmpty()) {
            return Collections.emptyList();
        }
        List<HcPlanOrderInventoryLockDO> locks = new ArrayList<>();
        for (HcInvStockDO stock : wetStocks) {
            Long sourceId = firstNonNullLong(stock.getSourceId(), stock.getSourceReportId());
            String sourceTable = firstNotBlank(stock.getSourceTable(), SOURCE_TABLE_OPERATION_REPORT);
            BigDecimal lockQty = zeroIfNull(stock.getAvailableQty());
            if (sourceId == null || lockQty.compareTo(BigDecimal.ZERO) <= 0) {
                continue;
            }
            HcPlanOrderInventoryLockDO lock = ensureSourceWipLockedForOperation(
                    planOrder,
                    operation,
                    firstNotBlank(stock.getSourceType(), SOURCE_TYPE_WET),
                    sourceTable,
                    sourceId,
                    lockQty,
                    operatorName,
                    "磨皮开工自动锁定湿法中间品；来源批号：" + firstNotBlank(stock.getBatchNo(), stock.getSourceBatchNo(), "-"));
            if (lock != null) {
                locks.add(lock);
            }
        }
        return locks;
    }

    private List<HcPlanOrderInventoryLockDO> selectActiveWetOutputWipLocks(Long planOperationId) {
        if (planOperationId == null) {
            return Collections.emptyList();
        }
        return hcPlanOrderInventoryLockMapper.selectListByPlanOperationId(planOperationId).stream()
                .filter(this::isActivePlanWipLock)
                .filter(lock -> SOURCE_TYPE_WET.equalsIgnoreCase(lock.getSourceType()))
                .toList();
    }

    private List<HcInvStockDO> selectAvailableWetOutputWipStocks(HcPlanOrderDO planOrder,
                                                                 HcPlanOrderOperationDO operation) {
        if (planOrder == null || planOrder.getId() == null) {
            return Collections.emptyList();
        }
        LambdaQueryWrapperX<HcInvStockDO> query = new LambdaQueryWrapperX<HcInvStockDO>()
                .eq(HcInvStockDO::getStockType, PLAN_LOCK_TYPE_WIP)
                .eq(HcInvStockDO::getSourceType, SOURCE_TYPE_WET)
                .eq(HcInvStockDO::getSourcePlanId, planOrder.getId())
                .eq(HcInvStockDO::getDeleted, false)
                .gtIfPresent(HcInvStockDO::getAvailableQty, BigDecimal.ZERO);
        String batchNo = firstNotBlank(
                operation == null ? null : operation.getProductionBatchNo(),
                planOrder.getProductionBatchNo(),
                operation == null ? null : operation.getBatchNo(),
                planOrder.getBatchNo());
        if (StrUtil.isNotBlank(batchNo)) {
            query.and(wrapper -> wrapper
                    .eq(HcInvStockDO::getBatchNo, batchNo)
                    .or()
                    .eq(HcInvStockDO::getSourceBatchNo, batchNo)
                    .or()
                    .eq(HcInvStockDO::getSourceParentBatchNo, batchNo));
        }
        query.orderByAsc(HcInvStockDO::getId);
        return hcInvStockMapper.selectList(query);
    }

    private void consumeRoughWetWipLockIfPresent(HcPlanOrderDO planOrder,
                                                 HcPlanOrderOperationDO operation,
                                                 Long reportId,
                                                 HcRoughReportSaveReqVO reqVO,
                                                 LocalDateTime consumeTime,
                                                 String operatorName) {
        List<HcPlanOrderInventoryLockDO> activeLocks = selectActiveWetOutputWipLocks(operation == null ? null : operation.getId());
        if (activeLocks.isEmpty()) {
            activeLocks = ensureWetOutputWipLockedForRoughStart(planOrder, operation, operatorName);
        }
        if (activeLocks.isEmpty()) {
            return;
        }
        BigDecimal alreadyConsumedQty = hcPlanOrderInventoryLockMapper
                .selectListByPlanOperationId(operation == null ? null : operation.getId()).stream()
                .filter(lock -> SOURCE_TYPE_WET.equalsIgnoreCase(lock.getSourceType()))
                .map(HcPlanOrderInventoryLockDO::getConsumedQty)
                .map(this::zeroIfNull)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal totalRemainingQty = activeLocks.stream()
                .map(this::calculateWipLockRemainingQty)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal requestedConsumeQty = calculateConfirmedRoughSecondConsumeQty(reqVO);
        if (requestedConsumeQty.compareTo(BigDecimal.ZERO) <= 0) {
            return;
        }
        BigDecimal needConsumeQty = requestedConsumeQty.subtract(alreadyConsumedQty).max(BigDecimal.ZERO);
        if (needConsumeQty.compareTo(BigDecimal.ZERO) <= 0) {
            return;
        }
        if (totalRemainingQty.compareTo(needConsumeQty) < 0) {
            throw invalidParamException("磨皮投入数量超过湿法中间品锁定余量，锁定余量 " + totalRemainingQty
                    + "，本次需 " + needConsumeQty);
        }
        BigDecimal leftConsumeQty = needConsumeQty;
        for (HcPlanOrderInventoryLockDO lock : activeLocks) {
            if (leftConsumeQty.compareTo(BigDecimal.ZERO) <= 0) {
                break;
            }
            BigDecimal lockRemainingQty = calculateWipLockRemainingQty(lock);
            if (lockRemainingQty.compareTo(BigDecimal.ZERO) <= 0) {
                continue;
            }
            BigDecimal consumeQty = lockRemainingQty.min(leftConsumeQty);
            consumeSourceWipLock(
                    lock,
                    consumeQty,
                    SOURCE_MENU_CODE_ROUGH,
                    reportId,
                    firstNotBlank(planOrder == null ? null : planOrder.getPlanNo(), lock.getTargetPlanNo()),
                    consumeTime,
                    operatorName,
                    "磨皮二磨确认消耗湿法中间品；来源批号："
                            + firstNotBlank(lock.getSourceBatchNo(), lock.getBatchNo(), lock.getLotNo(), "-"));
            leftConsumeQty = leftConsumeQty.subtract(consumeQty);
        }
    }

    private BigDecimal calculateConfirmedRoughSecondConsumeQty(HcRoughReportSaveReqVO reqVO) {
        JsonNode roughRoot = reqVO == null ? null : parseRoughExtraRoot(reqVO.getExtraJson());
        JsonNode rows = roughRoot == null ? null : roughRoot.path("secondGrindingRows");
        if (rows == null || !rows.isArray()) {
            return BigDecimal.ZERO;
        }
        BigDecimal consumeQty = BigDecimal.ZERO;
        for (JsonNode row : rows) {
            if (!"CONFIRMED".equalsIgnoreCase(normalizeRoughSecondConfirmStatus(readJsonText(row, "confirmStatus")))) {
                continue;
            }
            consumeQty = consumeQty.add(firstPositiveDecimal(readJsonDecimal(row, "processLength"),
                    readJsonDecimal(row, "outputLength")));
        }
        return consumeQty;
    }

    private BigDecimal firstPositiveDecimal(BigDecimal... values) {
        if (values == null) {
            return BigDecimal.ZERO;
        }
        for (BigDecimal value : values) {
            BigDecimal normalizedValue = zeroIfNull(value);
            if (normalizedValue.compareTo(BigDecimal.ZERO) > 0) {
                return normalizedValue;
            }
        }
        return BigDecimal.ZERO;
    }

    @Override
    public List<HcAdhesiveReportTaskRespVO> getAdhesiveTaskList(HcAdhesiveReportTaskPageReqVO reqVO) {
        String taskStatus = normalizeAdhesiveTaskStatus(reqVO.getTaskStatus());
        List<HcAdhesiveReportTaskRespVO> tasks = hcProcessReportMapper.selectAdhesiveTaskList(
                ADHESIVE_TASK_STATUS_ALL, reqVO.getTaskKeyword(), reqVO.getProductKeyword(),
                reqVO.getMotherMaterialKeyword(), reqVO.getMotherModelKeyword(), reqVO.getProductionDate(),
                reqVO.getEquipmentId(), reqVO.getEquipmentCode());
        return filterAdhesiveTaskRowsByStatus(buildAdhesiveTaskSourceRows(tasks, reqVO.getTaskKeyword()), taskStatus);
    }

    @Override
    public HcAdhesiveFaiRespVO getAdhesiveFaiSummary(Long planId, Long planOperationId, Long sourceGrindingSecondDetailId) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        HcPlanOrderOperationDO operation = validateAdhesiveOperation(planOrder, planOperationId);
        if (sourceGrindingSecondDetailId == null) {
            HcProcessReportDO latestStartReport = getLatestStartReport(operation.getId(), SOURCE_MENU_CODE_ADHESIVE);
            QmsFaiOrderDO latestFai = selectLatestAdhesiveMotherFai(planOrder, operation, latestStartReport);
            if (latestFai != null) {
                syncAdhesiveMotherFaiSummary(latestStartReport, latestFai);
                return buildAdhesiveMotherFaiResp(latestFai, latestStartReport, planOrder, operation);
            }
            return buildAdhesiveMotherFaiResp(null, latestStartReport, planOrder, operation);
        }
        HcGrindingSecondDetailDO sourceDetail = validateAdhesiveFaiSourceDetail(sourceGrindingSecondDetailId);
        HcAdhesiveReportDO adhesiveReport = findLatestAdhesiveReportBySourceDetail(sourceDetail.getId());
        QmsFaiOrderDO latestFai = selectLatestAdhesiveFai(planOrder, operation, sourceDetail, adhesiveReport);
        if (latestFai != null) {
            syncAdhesiveReportFaiSummary(adhesiveReport, latestFai);
            syncAdhesiveSegmentFaiSampleLength(adhesiveReport, latestFai);
            return buildAdhesiveFaiResp(latestFai, adhesiveReport, planOrder, operation, sourceDetail);
        }
        return buildAdhesiveFaiResp(null, adhesiveReport, planOrder, operation, sourceDetail);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcAdhesiveFaiRespVO applyAdhesiveFai(HcAdhesiveFaiApplyReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        HcPlanOrderOperationDO operation = validateAdhesiveOperation(planOrder, reqVO.getPlanOperationId());
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("请先完成粘胶1开工并锁定设备");
        }
        HcProcessReportDO latestStartReport = getLatestStartReport(operation.getId(), SOURCE_MENU_CODE_ADHESIVE);
        if (latestStartReport == null) {
            throw invalidParamException("当前粘胶1工序未找到开工记录，不能提交 FAI 首检申请");
        }
        if (latestStartReport.getEquipmentId() == null && StrUtil.isBlank(latestStartReport.getEquipmentCode())) {
            throw invalidParamException("请先选择并锁定粘胶1设备");
        }
        if (reqVO.getSourceGrindingSecondDetailId() == null) {
            return applyAdhesiveMotherFai(reqVO, planOrder, operation, latestStartReport);
        }
        HcGrindingSecondDetailDO sourceDetail = validateAdhesiveFaiSourceDetail(reqVO.getSourceGrindingSecondDetailId());
        if (!"CONFIRMED".equalsIgnoreCase(sourceDetail.getConfirmStatus())) {
            throw invalidParamException("来源二磨分段未扫码确认，不能提交粘胶1 FAI 首检申请");
        }
        HcAdhesiveReportDO adhesiveReport = findLatestAdhesiveReportBySourceDetail(sourceDetail.getId());
        QmsFaiOrderDO latestFai = selectLatestAdhesiveFai(planOrder, operation, sourceDetail, adhesiveReport);
        BigDecimal sampleLength = resolveAdhesiveSegmentFaiSampleLength(sourceDetail.getId(), adhesiveReport, latestFai, reqVO.getSampleLength());
        if (sampleLength.compareTo(BigDecimal.ZERO) <= 0) {
            throw invalidParamException("请填写粘胶1留样送检米数");
        }

        String motherMaterialCode = firstNotBlank(latestStartReport.getMotherMaterialCode(),
                operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode(),
                latestStartReport.getMaterialCode(), planOrder.getMaterialCode());
        String operationCode = firstNotBlank(latestStartReport.getOperationCode(), operation.getOpCode());
        String operationName = firstNotBlank(latestStartReport.getOperationName(), operation.getOpName());
        if (StrUtil.isBlank(operationCode) && StrUtil.isBlank(operationName)) {
            throw invalidParamException("当前粘胶1任务缺少工段信息，无法按产品型号与工段匹配 FAI 检验标准");
        }
        String productModel = resolveFaiProductModel(latestStartReport, operation, planOrder);
        if (StrUtil.isBlank(productModel)) {
            throw invalidParamException("当前粘胶1任务缺少产品型号，无法按产品型号与工段匹配 FAI 检验标准");
        }
        String productBatchNo = firstNotBlank(sourceDetail.getProductionBatchNo(), sourceDetail.getConfirmedBatchNo(),
                adhesiveReport == null ? null : adhesiveReport.getProductionBatchNo(),
                latestStartReport.getProductionBatchNo(), latestStartReport.getBatchNo(),
                operation.getProductionBatchNo(), planOrder.getProductionBatchNo(), operation.getBatchNo(), planOrder.getBatchNo());
        if (StrUtil.isBlank(productBatchNo)) {
            throw invalidParamException("请先确认来源二磨分段批次号，批次号将写入 FAI 首件检验的产品批次");
        }
        HcAdhesiveGlueBoardUsageDO glueBoardUsage = resolveAdhesiveFaiGlueBoardUsage(reqVO, operation);
        String glueBoardMaterialCode = resolveAdhesiveFaiGlueBoardMaterialCode(reqVO, adhesiveReport, glueBoardUsage);
        String glueBoardBatchNo = resolveAdhesiveFaiGlueBoardBatchNo(reqVO, adhesiveReport, glueBoardUsage);

        if (latestFai != null && !isAdhesiveFaiReapplyAllowed(latestFai)) {
            if (isFaiReleased(latestFai)) {
                throw invalidParamException("当前粘胶1首检已完成且判定OK，不能重复提交首检申请");
            }
            throw invalidParamException("当前粘胶1已有未完成首检单，请先在 FAI 工作台处理后再提交");
        }
        String triggerReason = firstNotBlank(reqVO.getTriggerReason(),
                latestFai != null && isAdhesiveFaiReapplyAllowed(latestFai) ? FAI_TRIGGER_REWORK_RECHECK : FAI_TRIGGER_NEW_ORDER);
        if (latestFai != null && isAdhesiveFaiReapplyAllowed(latestFai) && !FAI_TRIGGER_REWORK_RECHECK.equals(triggerReason)) {
            triggerReason = FAI_TRIGGER_REWORK_RECHECK;
        }

        QmsFaiSaveReqVO faiReqVO = new QmsFaiSaveReqVO();
        faiReqVO.setWorkOrderNo(planOrder.getPlanNo());
        faiReqVO.setSourceReportId(adhesiveReport == null ? sourceDetail.getId() : adhesiveReport.getId());
        faiReqVO.setSourceReportNo(buildAdhesiveFaiSourceReportNo(planOrder, operation, sourceDetail, adhesiveReport));
        faiReqVO.setSourceModule(SOURCE_MENU_CODE_ADHESIVE);
        faiReqVO.setSourceOperationCode(operationCode);
        faiReqVO.setSourceOperationName(operationName);
        faiReqVO.setPlanOrderId(planOrder.getId());
        faiReqVO.setStandardMatchMode(FAI_STANDARD_MATCH_PRODUCT_MODEL_PROCESS);
        faiReqVO.setOperationCode(operationCode);
        faiReqVO.setOperationName(operationName);
        faiReqVO.setMachineId(latestStartReport.getEquipmentId());
        faiReqVO.setMachineCode(firstNotBlank(latestStartReport.getEquipmentCode(), operation.getEquipmentCode()));
        faiReqVO.setMachineName(firstNotBlank(latestStartReport.getEquipmentName(), operation.getEquipmentName()));
        faiReqVO.setMaterialId(firstNotNull(latestStartReport.getMotherMaterialId(), operation.getMotherMaterialId(),
                planOrder.getMotherMaterialId(), latestStartReport.getMaterialId(), planOrder.getMaterialId()));
        faiReqVO.setMaterialCode(motherMaterialCode);
        faiReqVO.setMaterialName(firstNotBlank(latestStartReport.getMotherMaterialName(),
                operation.getMotherMaterialName(), planOrder.getMotherMaterialName(), latestStartReport.getMaterialName(), planOrder.getMaterialName()));
        faiReqVO.setSpecification(planOrder.getSizeName());
        faiReqVO.setProductModel(productModel);
        faiReqVO.setProductBatchNo(productBatchNo);
        applyFaiGlueBoardSnapshot(faiReqVO, glueBoardMaterialCode, glueBoardBatchNo, glueBoardUsage);
        faiReqVO.setSampleLength(sampleLength);
        faiReqVO.setProcessCategory(PROCESS_CODE_ADHESIVE);
        faiReqVO.setSubmissionType(FAI_SUBMISSION_TYPE_MASS_SHIPMENT);
        faiReqVO.setTriggerReason(triggerReason);
        faiReqVO.setStatus(FAI_STATUS_PENDING);
        faiReqVO.setJudgment(FAI_JUDGMENT_PENDING);
        faiReqVO.setSubmissionTime(LocalDateTime.now());
        faiReqVO.setSubmitterName(firstNotBlank(reqVO.getSubmitterName(), SecurityFrameworkUtils.getLoginUserNickname(),
                latestStartReport.getRecorderName(), "系统"));
        faiReqVO.setRemark(buildAdhesiveSegmentFaiRemark(sampleLength, reqVO.getRemark()));
        Long faiId = qmsFaiService.createFaiForInspectionPush(faiReqVO);
        QmsFaiOrderDO createdFai = qmsFaiOrderMapper.selectById(faiId);
        syncAdhesiveReportFaiSummary(adhesiveReport, createdFai);
        return buildAdhesiveFaiResp(createdFai, adhesiveReport, planOrder, operation, sourceDetail);
    }

    private HcAdhesiveFaiRespVO applyAdhesiveMotherFai(HcAdhesiveFaiApplyReqVO reqVO,
                                                       HcPlanOrderDO planOrder,
                                                       HcPlanOrderOperationDO operation,
                                                       HcProcessReportDO latestStartReport) {
        BigDecimal sampleLength = reqVO.getSampleLength();
        if (sampleLength == null || sampleLength.compareTo(BigDecimal.ZERO) <= 0) {
            throw invalidParamException("请填写粘胶1母卷首检送检米数");
        }
        String motherMaterialCode = firstNotBlank(latestStartReport.getMotherMaterialCode(),
                operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode(),
                latestStartReport.getMaterialCode(), planOrder.getMaterialCode());
        if (StrUtil.isBlank(motherMaterialCode)) {
            throw invalidParamException("当前粘胶1任务缺少母料料号，无法按物料编码与工段匹配整体母卷 FAI 检验标准");
        }
        String operationCode = firstNotBlank(latestStartReport.getOperationCode(), operation.getOpCode());
        String operationName = firstNotBlank(latestStartReport.getOperationName(), operation.getOpName());
        if (StrUtil.isBlank(operationCode) && StrUtil.isBlank(operationName)) {
            throw invalidParamException("当前粘胶1任务缺少工段信息，无法按物料编码与工段匹配整体母卷 FAI 检验标准");
        }
        String productBatchNo = firstNotBlank(latestStartReport.getParentProductionBatchNo(), latestStartReport.getParentBatchNo(),
                latestStartReport.getProductionBatchNo(), latestStartReport.getBatchNo(),
                operation.getProductionBatchNo(), planOrder.getProductionBatchNo(), operation.getBatchNo(), planOrder.getBatchNo());
        if (StrUtil.isBlank(productBatchNo)) {
            throw invalidParamException("当前粘胶1任务缺少母卷批次，批次号将写入 FAI 首件检验的产品批次");
        }

        QmsFaiOrderDO latestFai = selectLatestAdhesiveMotherFai(planOrder, operation, latestStartReport);
        if (latestFai != null && !isAdhesiveFaiReapplyAllowed(latestFai)) {
            if (isFaiReleased(latestFai)) {
                throw invalidParamException("当前粘胶1整体母卷首检已完成且判定OK，不能重复提交首检申请");
            }
            throw invalidParamException("当前粘胶1整体母卷已有未完成首检单，请先在 FAI 工作台处理后再提交");
        }
        String triggerReason = firstNotBlank(reqVO.getTriggerReason(),
                latestFai != null && isAdhesiveFaiReapplyAllowed(latestFai) ? FAI_TRIGGER_REWORK_RECHECK : FAI_TRIGGER_NEW_ORDER);
        if (latestFai != null && isAdhesiveFaiReapplyAllowed(latestFai) && !FAI_TRIGGER_REWORK_RECHECK.equals(triggerReason)) {
            triggerReason = FAI_TRIGGER_REWORK_RECHECK;
        }

        QmsFaiSaveReqVO faiReqVO = new QmsFaiSaveReqVO();
        faiReqVO.setWorkOrderNo(planOrder.getPlanNo());
        faiReqVO.setSourceReportId(latestStartReport.getId());
        faiReqVO.setSourceReportNo(buildAdhesiveMotherFaiSourceReportNo(planOrder, operation, latestStartReport));
        faiReqVO.setSourceModule(SOURCE_MENU_CODE_ADHESIVE);
        faiReqVO.setSourceOperationCode(operationCode);
        faiReqVO.setSourceOperationName(operationName);
        faiReqVO.setPlanOrderId(planOrder.getId());
        faiReqVO.setStandardMatchMode(FAI_STANDARD_MATCH_MATERIAL_PROCESS);
        faiReqVO.setOperationCode(operationCode);
        faiReqVO.setOperationName(operationName);
        faiReqVO.setMachineId(latestStartReport.getEquipmentId());
        faiReqVO.setMachineCode(firstNotBlank(latestStartReport.getEquipmentCode(), operation.getEquipmentCode()));
        faiReqVO.setMachineName(firstNotBlank(latestStartReport.getEquipmentName(), operation.getEquipmentName()));
        faiReqVO.setMaterialId(firstNotNull(latestStartReport.getMotherMaterialId(), operation.getMotherMaterialId(),
                planOrder.getMotherMaterialId(), latestStartReport.getMaterialId(), planOrder.getMaterialId()));
        faiReqVO.setMaterialCode(motherMaterialCode);
        faiReqVO.setMaterialName(firstNotBlank(latestStartReport.getMotherMaterialName(),
                operation.getMotherMaterialName(), planOrder.getMotherMaterialName(), latestStartReport.getMaterialName(), planOrder.getMaterialName()));
        faiReqVO.setSpecification(planOrder.getSizeName());
        faiReqVO.setProductModel(resolveFaiProductModel(latestStartReport, operation, planOrder));
        faiReqVO.setProductBatchNo(productBatchNo);
        faiReqVO.setProcessCategory(PROCESS_CODE_ADHESIVE);
        faiReqVO.setSubmissionType(FAI_SUBMISSION_TYPE_MASS_SHIPMENT);
        faiReqVO.setTriggerReason(triggerReason);
        faiReqVO.setStatus(FAI_STATUS_PENDING);
        faiReqVO.setJudgment(FAI_JUDGMENT_PENDING);
        faiReqVO.setSubmissionTime(LocalDateTime.now());
        faiReqVO.setSubmitterName(firstNotBlank(reqVO.getSubmitterName(), SecurityFrameworkUtils.getLoginUserNickname(),
                latestStartReport.getRecorderName(), "系统"));
        faiReqVO.setRemark(buildAdhesiveMotherFaiRemark(sampleLength, reqVO.getRemark()));
        Long faiId = qmsFaiService.createFaiForInspectionPush(faiReqVO);
        HcAdhesiveGlueBoardUsageDO glueBoardUsage = deductAdhesiveMotherFaiGlueBoardUsage(operation, sampleLength);
        updateFaiGlueBoardSnapshot(faiId,
                firstNotBlank(reqVO.getGlueBoardMaterialCode(), glueBoardUsage == null ? null : glueBoardUsage.getGlueBoardMaterialCode()),
                firstNotBlank(reqVO.getGlueBoardBatchNo(), glueBoardUsage == null ? null : glueBoardUsage.getGlueBoardBatchNo()),
                glueBoardUsage);
        QmsFaiOrderDO createdFai = qmsFaiOrderMapper.selectById(faiId);
        syncAdhesiveMotherFaiSummary(latestStartReport, createdFai);
        return buildAdhesiveMotherFaiResp(createdFai, latestStartReport, planOrder, operation);
    }

    private HcAdhesiveGlueBoardUsageDO deductAdhesiveMotherFaiGlueBoardUsage(HcPlanOrderOperationDO operation, BigDecimal sampleLength) {
        if (sampleLength == null || sampleLength.compareTo(BigDecimal.ZERO) <= 0) {
            throw invalidParamException("整体母卷 FAI 首检送检米数必须大于0");
        }
        HcAdhesiveGlueBoardUsageDO usage = hcAdhesiveGlueBoardUsageMapper.selectActiveByPlanOperationId(operation.getId());
        if (usage == null || Boolean.TRUE.equals(usage.getDeleted())
                || !GLUE_BOARD_STOCK_ACTIVE.equalsIgnoreCase(StrUtil.blankToDefault(usage.getUsageStatus(), ""))) {
            throw invalidParamException("请先登记胶板领用后再提交整体母卷 FAI 首检");
        }
        String stockMeasureMode = normalizeStockMeasureMode(usage.getStockMeasureMode(), AUXILIARY_CATEGORY_GLUE_BOARD);
        if (STOCK_MEASURE_COUNT.equals(stockMeasureMode)) {
            throw invalidParamException("按数量管理的辅料不支持整体母卷 FAI 米数扣减");
        }
        BigDecimal currentAvailableLength = resolveGlueBoardAvailableLength(usage);
        if (currentAvailableLength.compareTo(sampleLength) < 0) {
            throw invalidParamException("胶板边库余量不足，当前可用" + formatDecimal(currentAvailableLength) + "m");
        }
        BigDecimal currentAvailableStart = resolveGlueBoardAvailableStartPosition(usage);
        BigDecimal nextAvailableStart = currentAvailableStart.add(sampleLength);
        BigDecimal nextAvailableLength = currentAvailableLength.subtract(sampleLength);
        hcAdhesiveGlueBoardUsageMapper.updateById(HcAdhesiveGlueBoardUsageDO.builder()
                .id(usage.getId())
                .aqcSampleLength(zeroIfNull(usage.getAqcSampleLength()).add(sampleLength))
                .availableStartPosition(nextAvailableStart)
                .availableLength(nextAvailableLength)
                .returnedStartPosition(nextAvailableStart)
                .returnedLength(nextAvailableLength)
                .build());
        return usage;
    }

    private String buildAdhesiveMotherFaiRemark(BigDecimal sampleLength, String userRemark) {
        List<String> parts = new ArrayList<>();
        parts.add("粘胶1整体母卷 FAI 首检申请");
        parts.add("送检米数：" + formatDecimal(sampleLength) + "m");
        if (StrUtil.isNotBlank(userRemark)) {
            parts.add("备注：" + userRemark.trim());
        }
        return String.join("；", parts);
    }

    private HcGrindingSecondDetailDO validateAdhesiveFaiSourceDetail(Long sourceGrindingSecondDetailId) {
        HcGrindingSecondDetailDO sourceDetail = hcGrindingSecondDetailMapper.selectById(sourceGrindingSecondDetailId);
        if (sourceDetail == null || Boolean.TRUE.equals(sourceDetail.getDeleted())) {
            throw invalidParamException("来源二磨分段不存在");
        }
        return sourceDetail;
    }

    private HcAdhesiveReportDO findLatestAdhesiveReportBySourceDetail(Long sourceGrindingSecondDetailId) {
        if (sourceGrindingSecondDetailId == null) {
            return null;
        }
        return hcAdhesiveReportMapper.selectListBySourceDetailId(sourceGrindingSecondDetailId).stream()
                .max(Comparator.comparing(HcAdhesiveReportDO::getId))
                .orElse(null);
    }

    private HcAdhesiveReportDO findFirstAdhesiveReportBySourceDetail(Long sourceGrindingSecondDetailId) {
        if (sourceGrindingSecondDetailId == null) {
            return null;
        }
        return hcAdhesiveReportMapper.selectListBySourceDetailId(sourceGrindingSecondDetailId).stream()
                .findFirst()
                .orElse(null);
    }

    private BigDecimal resolveAdhesiveSegmentFaiSampleLength(Long sourceGrindingSecondDetailId,
                                                             HcAdhesiveReportDO adhesiveReport,
                                                             QmsFaiOrderDO faiOrder,
                                                             BigDecimal requestedSampleLength) {
        BigDecimal reportSampleLength = sumAdhesiveReportNapSampleLength(sourceGrindingSecondDetailId);
        if (reportSampleLength.compareTo(BigDecimal.ZERO) <= 0) {
            reportSampleLength = adhesiveReport == null ? BigDecimal.ZERO : zeroIfNull(adhesiveReport.getNapSampleLength());
        }
        if (reportSampleLength.compareTo(BigDecimal.ZERO) > 0) {
            return reportSampleLength;
        }
        BigDecimal requested = zeroIfNull(requestedSampleLength);
        if (requested.compareTo(BigDecimal.ZERO) > 0) {
            return requested;
        }
        return faiOrder == null ? BigDecimal.ZERO : zeroIfNull(faiOrder.getSampleLength());
    }

    private void syncAdhesiveSegmentFaiSampleLength(HcAdhesiveReportDO adhesiveReport, QmsFaiOrderDO faiOrder) {
        if (adhesiveReport == null || faiOrder == null || faiOrder.getId() == null) {
            return;
        }
        BigDecimal reportSampleLength = sumAdhesiveReportNapSampleLength(adhesiveReport.getSourceGrindingSecondDetailId());
        if (reportSampleLength.compareTo(BigDecimal.ZERO) <= 0) {
            reportSampleLength = zeroIfNull(adhesiveReport.getNapSampleLength());
        }
        BigDecimal faiSampleLength = zeroIfNull(faiOrder.getSampleLength());
        if (reportSampleLength.compareTo(BigDecimal.ZERO) > 0) {
            if (reportSampleLength.compareTo(faiSampleLength) != 0) {
                qmsFaiOrderMapper.updateById(QmsFaiOrderDO.builder()
                        .id(faiOrder.getId())
                        .sampleLength(reportSampleLength)
                        .build());
                faiOrder.setSampleLength(reportSampleLength);
            }
            return;
        }
        if (faiSampleLength.compareTo(BigDecimal.ZERO) > 0) {
            syncAdhesiveFirstReportNapSampleLength(adhesiveReport.getSourceGrindingSecondDetailId(), faiSampleLength);
        }
    }

    private BigDecimal sumAdhesiveReportNapSampleLength(Long sourceGrindingSecondDetailId) {
        if (sourceGrindingSecondDetailId == null) {
            return BigDecimal.ZERO;
        }
        return hcAdhesiveReportMapper.selectListBySourceDetailId(sourceGrindingSecondDetailId)
                .stream()
                .map(HcAdhesiveReportDO::getNapSampleLength)
                .filter(Objects::nonNull)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    private BigDecimal resolveAdhesiveReportNapSampleLengthForSave(Long sourceGrindingSecondDetailId,
                                                                    HcAdhesiveReportDO existedReport,
                                                                    BigDecimal requestedNapSampleLength,
                                                                    QmsFaiOrderDO faiOrder) {
        BigDecimal requested = zeroIfNull(requestedNapSampleLength);
        if (requested.compareTo(BigDecimal.ZERO) > 0) {
            return requested;
        }
        BigDecimal faiSampleLength = faiOrder == null ? BigDecimal.ZERO : zeroIfNull(faiOrder.getSampleLength());
        if (faiSampleLength.compareTo(BigDecimal.ZERO) <= 0) {
            return BigDecimal.ZERO;
        }
        if (shouldFillCurrentAdhesiveReportNapSampleLength(sourceGrindingSecondDetailId, existedReport)) {
            return faiSampleLength;
        }
        syncAdhesiveFirstReportNapSampleLength(sourceGrindingSecondDetailId, faiSampleLength);
        return BigDecimal.ZERO;
    }

    private boolean shouldFillCurrentAdhesiveReportNapSampleLength(Long sourceGrindingSecondDetailId,
                                                                   HcAdhesiveReportDO existedReport) {
        if (sourceGrindingSecondDetailId == null || sumAdhesiveReportNapSampleLength(sourceGrindingSecondDetailId).compareTo(BigDecimal.ZERO) > 0) {
            return false;
        }
        List<HcAdhesiveReportDO> segmentReports = hcAdhesiveReportMapper.selectListBySourceDetailId(sourceGrindingSecondDetailId);
        if (segmentReports.isEmpty()) {
            return existedReport == null;
        }
        HcAdhesiveReportDO firstReport = segmentReports.get(0);
        return existedReport != null && Objects.equals(firstReport.getId(), existedReport.getId());
    }

    private void syncAdhesiveFirstReportNapSampleLength(Long sourceGrindingSecondDetailId, BigDecimal sampleLength) {
        BigDecimal safeSampleLength = zeroIfNull(sampleLength);
        if (sourceGrindingSecondDetailId == null || safeSampleLength.compareTo(BigDecimal.ZERO) <= 0
                || sumAdhesiveReportNapSampleLength(sourceGrindingSecondDetailId).compareTo(BigDecimal.ZERO) > 0) {
            return;
        }
        HcAdhesiveReportDO firstReport = findFirstAdhesiveReportBySourceDetail(sourceGrindingSecondDetailId);
        if (firstReport == null || firstReport.getId() == null) {
            return;
        }
        HcAdhesiveReportDO updateReport = new HcAdhesiveReportDO();
        updateReport.setId(firstReport.getId());
        updateReport.setNapSampleLength(safeSampleLength);
        BigDecimal inputLength = zeroIfNull(firstReport.getInputLength());
        if (inputLength.compareTo(BigDecimal.ZERO) > 0) {
            BigDecimal outputLength = inputLength.subtract(zeroIfNull(firstReport.getLossLength())).subtract(safeSampleLength).max(BigDecimal.ZERO);
            updateReport.setOutputLength(outputLength);
        }
        hcAdhesiveReportMapper.updateById(updateReport);
    }

    private String buildAdhesiveSegmentFaiRemark(BigDecimal sampleLength, String userRemark) {
        List<String> parts = new ArrayList<>();
        parts.add("粘胶1分段留样 FAI 首检申请");
        parts.add("送检米数：" + formatDecimal(sampleLength) + "m");
        if (StrUtil.isNotBlank(userRemark)) {
            parts.add("备注：" + userRemark.trim());
        }
        return String.join("；", parts);
    }

    private HcAdhesiveGlueBoardUsageDO resolveAdhesiveFaiGlueBoardUsage(HcAdhesiveFaiApplyReqVO reqVO,
                                                                         HcPlanOrderOperationDO operation) {
        if (reqVO != null && reqVO.getGlueBoardUsageId() != null) {
            HcAdhesiveGlueBoardUsageDO usage = hcAdhesiveGlueBoardUsageMapper.selectById(reqVO.getGlueBoardUsageId());
            if (usage != null && !Boolean.TRUE.equals(usage.getDeleted())
                    && (operation == null || operation.getId() == null || Objects.equals(usage.getPlanOperationId(), operation.getId()))) {
                return usage;
            }
        }
        if (operation == null || operation.getId() == null) {
            return null;
        }
        return hcAdhesiveGlueBoardUsageMapper.selectActiveByPlanOperationId(operation.getId());
    }

