    private String buildAdhesiveMotherFaiSourceReportNo(HcPlanOrderDO planOrder,
                                                        HcPlanOrderOperationDO operation,
                                                        HcProcessReportDO latestStartReport) {
        String motherBatchNo = firstNotBlank(latestStartReport == null ? null : latestStartReport.getParentProductionBatchNo(),
                latestStartReport == null ? null : latestStartReport.getParentBatchNo(),
                latestStartReport == null ? null : latestStartReport.getProductionBatchNo(),
                latestStartReport == null ? null : latestStartReport.getBatchNo(),
                operation == null ? null : operation.getProductionBatchNo(),
                planOrder == null ? null : planOrder.getProductionBatchNo(),
                operation == null ? null : operation.getBatchNo(),
                planOrder == null ? null : planOrder.getBatchNo());
        String sourceAnchor = StrUtil.isBlank(motherBatchNo) ? "MOTHER" : motherBatchNo;
        return firstNotBlank(planOrder == null ? null : planOrder.getPlanNo(), "PLAN")
                + "-" + String.format("%02d", operation == null || operation.getOpSeq() == null ? 0 : operation.getOpSeq())
                + "-ADH-MOTHER-" + sourceAnchor;
    }

    private String buildAdhesiveFaiSourceReportNo(HcPlanOrderDO planOrder,
                                                  HcPlanOrderOperationDO operation,
                                                  HcGrindingSecondDetailDO sourceDetail,
                                                  HcAdhesiveReportDO adhesiveReport) {
        String segmentBatchNo = firstNotBlank(sourceDetail == null ? null : sourceDetail.getProductionBatchNo(),
                sourceDetail == null ? null : sourceDetail.getConfirmedBatchNo(),
                adhesiveReport == null ? null : adhesiveReport.getSourceProductionBatchNo(),
                adhesiveReport == null ? null : adhesiveReport.getProductionBatchNo(),
                sourceDetail == null ? null : sourceDetail.getMotherBatchNo());
        String sourceAnchor = StrUtil.isBlank(segmentBatchNo) ? "SRC" + (sourceDetail == null ? "" : sourceDetail.getId()) : segmentBatchNo;
        return firstNotBlank(planOrder == null ? null : planOrder.getPlanNo(), "PLAN")
                + "-" + String.format("%02d", operation == null || operation.getOpSeq() == null ? 0 : operation.getOpSeq())
                + "-ADH-" + sourceAnchor
                + "-" + (sourceDetail == null || sourceDetail.getId() == null ? "NA" : sourceDetail.getId());
    }

