    @Override
    public HcAdhesiveSourceRespVO scanAdhesiveSource(String batchNo, Long planOperationId,
                                                     String sourceMode, String sourcePlanNo,
                                                     String sourceMotherBatchNo) {
        String normalizedBatchNo = StrUtil.trimToEmpty(batchNo);
        if (StrUtil.isBlank(normalizedBatchNo)) {
            throw invalidParamException("请扫描或输入第二次磨皮确认批次号");
        }
        HcGrindingSecondDetailDO detail = hcGrindingSecondDetailMapper.selectConfirmedByBatchNo(normalizedBatchNo);
        if (detail == null) {
            throw invalidParamException("未找到已确认的第二次磨皮批次，不能进入粘双面胶报工");
        }
        if (planOperationId != null) {
            List<HcPlanOrderInventoryLockDO> wipLocks = selectActiveAdhesiveWipLocks(planOperationId);
            HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(planOperationId);
            HcPlanOrderInventoryLockDO sourceLock = resolveAdhesiveWipLock(wipLocks, detail);
            boolean selfSource = isSelfAdhesiveSource(operation, detail);
            if (ADHESIVE_SOURCE_MODE_LOCKED_WIP.equalsIgnoreCase(sourceMode)) {
                validateAdhesiveSourceScope(sourceMode, sourcePlanNo, sourceMotherBatchNo, detail, sourceLock, false);
                return buildAdhesiveSourceResp(detail, sourceLock);
            }
            if (ADHESIVE_SOURCE_MODE_SELF.equalsIgnoreCase(sourceMode)) {
                validateAdhesiveSourceScope(sourceMode, sourcePlanNo, sourceMotherBatchNo, detail, null, selfSource);
                return buildAdhesiveSourceResp(detail);
            }
            if (sourceLock != null && matchesAdhesiveSourceScope(sourcePlanNo, sourceMotherBatchNo, detail, sourceLock)) {
                return buildAdhesiveSourceResp(detail, sourceLock);
            }
            if (selfSource && matchesAdhesiveSourceScope(sourcePlanNo, sourceMotherBatchNo, detail, null)) {
                return buildAdhesiveSourceResp(detail);
            }
            throw invalidParamException("扫描来源不属于当前粘胶1待加工行，请确认选择的来源计划和母卷批次");
        }
        return buildAdhesiveSourceResp(detail);
    }

    @Override
    public List<HcAdhesiveSourceRespVO> getAdhesiveSourceList(Long planId, Long planOperationId) {
        if (planId == null || planOperationId == null) {
            return Collections.emptyList();
        }
        List<HcAdhesiveSourceRespVO> result = new ArrayList<>();
        Set<Long> lockedSourceDetailIds = new LinkedHashSet<>();
        List<HcAdhesiveReportDO> adhesiveReports = hcAdhesiveReportMapper.selectListByPlanOperationId(planOperationId);
        for (HcPlanOrderInventoryLockDO wipLock : selectDisplayAdhesiveWipLocks(planOperationId, adhesiveReports)) {
            HcGrindingSecondDetailDO detail = selectGrindingSecondDetailByWipLock(wipLock);
            Long sourceDetailId = resolveAdhesiveWipLockSourceDetailId(wipLock, detail);
            if (sourceDetailId != null) {
                lockedSourceDetailIds.add(sourceDetailId);
            }
            if (detail != null && "CONFIRMED".equalsIgnoreCase(detail.getConfirmStatus())) {
                result.add(buildAdhesiveSourceResp(detail, wipLock));
            }
        }
        for (HcGrindingSecondDetailDO detail : hcGrindingSecondDetailMapper.selectConfirmedListByPlanId(planId, planOperationId)) {
            if (detail.getId() != null && lockedSourceDetailIds.contains(detail.getId())) {
                continue;
            }
            result.add(buildAdhesiveSourceResp(detail));
        }
        applyAdhesiveSegmentTimings(result, planOperationId);
        return result;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long stampAdhesiveSegmentTiming(HcAdhesiveSegmentTimingStampReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validateAdhesiveOperation(planOrder, reqVO.getPlanOperationId());
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("请先完成粘胶1工序开工，再记录分段时间");
        }
        HcGrindingSecondDetailDO sourceDetail = hcGrindingSecondDetailMapper
                .selectById(reqVO.getSourceGrindingSecondDetailId());
        if (sourceDetail == null || Boolean.TRUE.equals(sourceDetail.getDeleted())
                || !"CONFIRMED".equalsIgnoreCase(sourceDetail.getConfirmStatus())) {
            throw invalidParamException("来源二磨分段不存在或尚未扫码确认");
        }
        String segmentMark = StrUtil.trimToEmpty(sourceDetail.getSegmentMark()).toUpperCase();
        if (!ADHESIVE_SEGMENT_MARKS.contains(segmentMark)) {
            throw invalidParamException("仅支持记录 P/Q/R/S 四段的开工和完工时间");
        }
        boolean sourceInScope = getAdhesiveSourceList(planOrder.getId(), operation.getId()).stream()
                .anyMatch(source -> Objects.equals(source.getGrindingSecondDetailId(), sourceDetail.getId()));
        if (!sourceInScope) {
            throw invalidParamException("当前二磨分段不属于本粘胶1待加工范围");
        }

        String action = StrUtil.trimToEmpty(reqVO.getAction()).toUpperCase();
        LocalDateTime now = LocalDateTime.now();
        Long operatorId = firstNonNull(reqVO.getOperatorId(), SecurityFrameworkUtils.getLoginUserId());
        String operatorName = firstNotBlank(reqVO.getOperatorName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        HcAdhesiveSegmentTimingDO timing = hcAdhesiveSegmentTimingMapper.selectBySegment(
                operation.getId(), sourceDetail.getId());
        String segmentDisplayName = firstNotBlank(sourceDetail.getProductionBatchNo(),
                sourceDetail.getConfirmedBatchNo(), sourceDetail.getMotherBatchNo(), "当前分段")
                + "（" + segmentMark + "段）";
        if (ADHESIVE_SEGMENT_TIMING_ACTION_START.equals(action)) {
            if (timing != null && timing.getStartTime() != null) {
                throw invalidParamException(segmentDisplayName + "已记录开工时间，不能重复点击");
            }
            HcAdhesiveSegmentTimingDO newTiming = HcAdhesiveSegmentTimingDO.builder()
                    .planId(planOrder.getId())
                    .planNo(planOrder.getPlanNo())
                    .planOperationId(operation.getId())
                    .sourceGrindingSecondDetailId(sourceDetail.getId())
                    .motherBatchNo(firstNotBlank(sourceDetail.getMotherBatchNo(), sourceDetail.getParentProductionBatchNo()))
                    .segmentBatchNo(firstNotBlank(sourceDetail.getProductionBatchNo(), sourceDetail.getConfirmedBatchNo()))
                    .segmentMark(segmentMark)
                    .startTime(now)
                    .startOperatorId(operatorId)
                    .startOperatorName(operatorName)
                    .tenantId(planOrder.getTenantId())
                    .build();
            try {
                hcAdhesiveSegmentTimingMapper.insert(newTiming);
            } catch (DuplicateKeyException exception) {
                throw invalidParamException(segmentDisplayName + "已记录开工时间，不能重复点击");
            }
            syncAdhesiveSegmentTimingToReports(operation.getId(), sourceDetail.getId(), now, null);
            return newTiming.getId();
        }
        if (!ADHESIVE_SEGMENT_TIMING_ACTION_END.equals(action)) {
            throw invalidParamException("分段时间动作只能是 START 或 END");
        }
        if (timing == null || timing.getStartTime() == null) {
            throw invalidParamException(segmentDisplayName + "尚未开工，不能记录完工时间");
        }
        if (timing.getEndTime() != null) {
            throw invalidParamException(segmentDisplayName + "已记录完工时间，不能重复点击");
        }
        int updated = hcAdhesiveSegmentTimingMapper.markEndOnce(timing.getId(), now, operatorId, operatorName,
                planOrder.getTenantId());
        if (updated <= 0) {
            throw invalidParamException(segmentDisplayName + "已记录完工时间，不能重复点击");
        }
        syncAdhesiveSegmentTimingToReports(operation.getId(), sourceDetail.getId(), timing.getStartTime(), now);
        return timing.getId();
    }

