    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcAdhesiveGlueBoardStockImportRespVO importAdhesiveGlueBoardStockExcel(MultipartFile file,
                                                                                  Boolean confirmClear)
            throws IOException {
        rejectLegacyGlueBoardStockMaintenance();
        if (!Boolean.TRUE.equals(confirmClear)) {
            throw invalidParamException("导入初始化前必须确认清空当前胶板边库库存数据");
        }
        HcAdhesiveGlueBoardStockImportRespVO respVO = new HcAdhesiveGlueBoardStockImportRespVO();
        if (file == null || file.isEmpty()) {
            addGlueBoardStockImportFailure(respVO, "导入文件为空");
            return respVO;
        }

        List<HcAdhesiveGlueBoardStockImportExcelVO> excelRows =
                ExcelUtils.read(file, HcAdhesiveGlueBoardStockImportExcelVO.class);
        List<HcAdhesiveGlueBoardStockDO> importStocks = new ArrayList<>();
        Set<String> importBatchNos = new LinkedHashSet<>();
        for (int index = 0; index < excelRows.size(); index++) {
            HcAdhesiveGlueBoardStockImportExcelVO excelRow = excelRows.get(index);
            if (isBlankGlueBoardStockImportRow(excelRow)) {
                respVO.setSkippedRows(respVO.getSkippedRows() + 1);
                continue;
            }
            int rowNo = index + 2;
            respVO.setTotalRows(respVO.getTotalRows() + 1);
            HcAdhesiveGlueBoardStockDO stock = normalizeGlueBoardStockImportRow(excelRow, rowNo, respVO);
            if (stock == null) {
                continue;
            }
            String batchNo = StrUtil.trim(stock.getGlueBoardBatchNo());
            if (!importBatchNos.add(batchNo)) {
                addGlueBoardStockImportFailure(respVO, String.format("第%d行：胶板批号在导入文件内重复：%s", rowNo, batchNo));
                continue;
            }
            importStocks.add(stock);
        }
        if (!respVO.getFailures().isEmpty()) {
            respVO.setFailureCount(respVO.getFailures().size());
            respVO.getMessages().add("导入校验未通过，未清空也未写入任何数据");
            return respVO;
        }
        if (importStocks.isEmpty()) {
            addGlueBoardStockImportFailure(respVO, "导入文件没有有效数据行");
            return respVO;
        }

        Long tenantId = TenantContextHolder.getRequiredTenantId();
        respVO.setClearedStockCount(hcAdhesiveGlueBoardStockMapper
                .physicalDeleteByTenantIdAndCategory(tenantId, AUXILIARY_CATEGORY_GLUE_BOARD));
        for (HcAdhesiveGlueBoardStockDO stock : importStocks) {
            stock.setTenantId(tenantId);
            hcAdhesiveGlueBoardStockMapper.insert(stock);
            respVO.setSuccessCount(respVO.getSuccessCount() + 1);
        }
        respVO.getMessages().add(String.format("导入初始化完成：物理删除胶板边库库存 %d 条，初始化库存 %d 条",
                respVO.getClearedStockCount(), respVO.getSuccessCount()));
        return respVO;
    }

