    @Override
    @Transactional(rollbackFor = Exception.class)
    public void removeAdhesiveReport(Long id) {
        HcAdhesiveReportDO report = hcAdhesiveReportMapper.selectById(id);
        if (report == null || Boolean.TRUE.equals(report.getDeleted())) {
            throw invalidParamException("粘双面胶报工记录不存在");
        }
        if (!"DRAFT".equalsIgnoreCase(StrUtil.blankToDefault(report.getReportStatus(), "DRAFT"))) {
            throw invalidParamException("当前报工记录已提交或确认，不能删除");
        }
        hcAdhesiveCheckDetailMapper.deleteByReportId(report.getId());
        hcAdhesiveReportMapper.deleteById(report.getId());
        refreshAdhesiveSourceDownstreamState(report.getSourceGrindingSecondDetailId());
        recalculateGlueBoardUsage(report.getGlueBoardUsageId());
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long submitAdhesiveReport(HcAdhesiveReportSubmitReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        if (!PLAN_STATUS_RELEASED.equals(planOrder.getPlanStatus())) {
            throw invalidParamException("只有已下达的生产计划允许报工");
        }
        HcPlanOrderOperationDO operation = validateAdhesiveOperation(planOrder, reqVO.getPlanOperationId());
        if (OP_STATUS_FINISHED.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序已完工，不能继续报工");
        }
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序未开工，不能过站提交");
        }
        List<HcAdhesiveReportDO> adhesiveReports = hcAdhesiveReportMapper.selectListByPlanOperationId(operation.getId());
        if (adhesiveReports.isEmpty()) {
            throw invalidParamException("请先至少保存一条粘双面胶报工记录");
        }
        boolean hasUnconfirmed = adhesiveReports.stream()
                .anyMatch(report -> !"CONFIRMED".equalsIgnoreCase(report.getReportStatus())
                        && !"SUBMITTED".equalsIgnoreCase(report.getReportStatus()));
        if (hasUnconfirmed) {
            throw invalidParamException("存在未扫码确认的粘双面胶报工记录，不能过站提交");
        }
        boolean hasUncompletedSegment = adhesiveReports.stream()
                .anyMatch(report -> !"SUBMITTED".equalsIgnoreCase(report.getReportStatus()));
        if (hasUncompletedSegment) {
            throw invalidParamException("存在尚未点击本段完工的粘胶1分段，不能过站提交");
        }
        LocalDate reportDate = reqVO.getReportDate();
        LocalDateTime startTime = null;
        LocalDateTime endTime = normalizeReportDateTime(reqVO.getEndTime(), reportDate == null ? LocalDate.now() : reportDate);
        BigDecimal totalInputLength = BigDecimal.ZERO;
        BigDecimal totalLossLength = BigDecimal.ZERO;
        BigDecimal totalOutputLength = BigDecimal.ZERO;
        BigDecimal totalNapSampleLength = BigDecimal.ZERO;
        HcAdhesiveReportDO latestReport = adhesiveReports.get(0);
        for (HcAdhesiveReportDO report : adhesiveReports) {
            if (reportDate == null && report.getReportDate() != null) {
                reportDate = report.getReportDate();
            }
            if (report.getStartTime() != null && (startTime == null || report.getStartTime().isBefore(startTime))) {
                startTime = report.getStartTime();
            }
            if (report.getEndTime() != null && (endTime == null || report.getEndTime().isAfter(endTime))) {
                endTime = report.getEndTime();
            }
            totalInputLength = totalInputLength.add(zeroIfNull(report.getInputLength()));
            totalLossLength = totalLossLength.add(zeroIfNull(report.getLossLength()));
            totalOutputLength = totalOutputLength.add(zeroIfNull(report.getOutputLength()));
            totalNapSampleLength = totalNapSampleLength.add(zeroIfNull(report.getNapSampleLength()));
        }
        LocalDateTime now = LocalDateTime.now();
        if (reportDate == null) {
            reportDate = LocalDate.now();
        }
        if (startTime == null) {
            startTime = now;
        }
        if (endTime == null) {
            endTime = now;
        }
        LocalDateTime recorderTime = normalizeReportDateTime(reqVO.getRecorderTime(), reportDate);
        LocalDateTime confirmerTime = normalizeReportDateTime(reqVO.getConfirmerTime(), reportDate);
        if (recorderTime == null) {
            recorderTime = latestReport.getRecorderTime() == null ? now : latestReport.getRecorderTime();
        }
        if (confirmerTime == null) {
            confirmerTime = now;
        }
        // 本段完工按钮的确认时刻是 QTIME 上道完工的唯一时间事实。
        endTime = confirmerTime;
        String recorderName = firstNotBlank(reqVO.getRecorderName(), latestReport.getRecorderName(),
                SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        String confirmerName = firstNotBlank(reqVO.getConfirmerName(), SecurityFrameworkUtils.getLoginUserNickname(), recorderName, "系统");
        String finishRemark = buildAdhesiveFinishRemark(adhesiveReports.size(), totalInputLength,
                totalLossLength, totalOutputLength, totalNapSampleLength, reqVO.getRemark());

        HcProcessReportDO reportDO = HcProcessReportDO.builder()
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .operationStatus(operation.getOperationStatus())
                .operationSeq(operation.getOpSeq())
                .operationCode(operation.getOpCode())
                .operationName(operation.getOpName())
                .workCenterId(operation.getWorkCenterId())
                .workCenterCode(operation.getWorkCenterCode())
                .workCenterName(operation.getWorkCenterName())
                .equipmentId(operation.getEquipmentId())
                .equipmentCode(operation.getEquipmentCode())
                .equipmentName(operation.getEquipmentName())
                .materialId(planOrder.getMaterialId())
                .materialCode(firstNotBlank(latestReport.getMaterialCode(), planOrder.getMaterialCode()))
                .materialName(firstNotBlank(latestReport.getMaterialName(), planOrder.getMaterialName()))
                .motherMaterialId(planOrder.getMotherMaterialId())
                .motherMaterialCode(firstNotBlank(operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode()))
                .motherMaterialName(firstNotBlank(operation.getMotherMaterialName(), planOrder.getMotherMaterialName()))
                .motherModelId(planOrder.getMotherModelId())
                .motherModelCode(firstNotBlank(operation.getMotherModelCode(), planOrder.getMotherModelCode()))
                .motherModelName(firstNotBlank(operation.getMotherModelName(), planOrder.getMotherModelName()))
                .batchNo(firstNotBlank(latestReport.getProductionBatchNo(), operation.getBatchNo(), planOrder.getBatchNo()))
                .productionBatchNo(firstNotBlank(latestReport.getProductionBatchNo(), operation.getProductionBatchNo(), planOrder.getProductionBatchNo()))
                .parentProductionBatchNo(firstNotBlank(latestReport.getParentProductionBatchNo(), operation.getParentProductionBatchNo(), planOrder.getParentProductionBatchNo()))
                .parentBatchNo(firstNotBlank(latestReport.getParentProductionBatchNo(), latestReport.getSourceProductionBatchNo(), operation.getParentBatchNo(), planOrder.getBatchNo()))
                .sampleCode(operation.getSampleCode())
                .reportDate(reportDate)
                .startTime(startTime)
                .endTime(endTime)
                .goodQty(totalOutputLength)
                .scrapQty(totalLossLength)
                .recorderName(recorderName)
                .recorderTime(recorderTime)
                .confirmerName(confirmerName)
                .confirmerTime(confirmerTime)
                .reportUom(firstNotBlank(operation.getUom(), operation.getUnitCode(), operation.getUnitName(), planOrder.getTargetUom()))
                .reportMinutes(calculateMinutes(startTime, endTime))
                .reportType("END")
                .sourceMenuCode(SOURCE_MENU_CODE_ADHESIVE)
                .extraJson(buildAdhesiveExtraJson(adhesiveReports.size(), totalInputLength,
                        totalLossLength, totalOutputLength, totalNapSampleLength))
                .remark(reqVO.getRemark())
                .build();
        hcProcessReportMapper.insert(reportDO);

        for (HcAdhesiveReportDO adhesiveReport : adhesiveReports) {
            HcAdhesiveReportDO updateReport = new HcAdhesiveReportDO();
            updateReport.setId(adhesiveReport.getId());
            updateReport.setReportStatus("SUBMITTED");
            updateReport.setConfirmerName(confirmerName);
            updateReport.setConfirmerTime(confirmerTime);
            hcAdhesiveReportMapper.updateById(updateReport);
            refreshAdhesiveSourceDownstreamState(adhesiveReport.getSourceGrindingSecondDetailId());
        }

        BigDecimal totalGoodQty = hcProcessReportMapper.selectTotalGoodQtyBySource(operation.getId(), SOURCE_MENU_CODE_ADHESIVE);
        HcPlanOrderOperationDO updateOperation = new HcPlanOrderOperationDO();
        updateOperation.setId(operation.getId());
        updateOperation.setDispatchQty(totalGoodQty == null ? BigDecimal.ZERO : totalGoodQty);
        updateOperation.setOperationStatus(OP_STATUS_FINISHED);
        updateOperation.setFinishTime(endTime);
        updateOperation.setFinishRemark(finishRemark);
        updateOperation.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateOperation.setStatusOperatorName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "system"));
        updateOperation.setStatusOperateTime(LocalDateTime.now());
        hcPlanOrderOperationMapper.updateById(updateOperation);
        return reportDO.getId();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long completeAdhesiveSegment(HcAdhesiveSegmentCompleteReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        if (!PLAN_STATUS_RELEASED.equals(planOrder.getPlanStatus())) {
            throw invalidParamException("只有已下达的生产计划允许标记本段完成");
        }
        HcPlanOrderOperationDO operation = validateAdhesiveOperation(planOrder, reqVO.getPlanOperationId());
        if (OP_STATUS_FINISHED.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序已完工，不能继续标记分段完成");
        }
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序未开工，不能标记本段完成");
        }

        HcGrindingSecondDetailDO sourceDetail = null;
        if (reqVO.getSourceGrindingSecondDetailId() != null) {
            sourceDetail = hcGrindingSecondDetailMapper.selectById(reqVO.getSourceGrindingSecondDetailId());
            if (sourceDetail == null || Boolean.TRUE.equals(sourceDetail.getDeleted())) {
                throw invalidParamException("当前分段批次不存在");
            }
        } else if (StrUtil.isNotBlank(reqVO.getSourceProductionBatchNo())) {
            sourceDetail = hcGrindingSecondDetailMapper.selectConfirmedByBatchNo(reqVO.getSourceProductionBatchNo());
        }
        String sourceProductionBatchNo = firstNotBlank(reqVO.getSourceProductionBatchNo(),
                sourceDetail == null ? null : sourceDetail.getProductionBatchNo(),
                sourceDetail == null ? null : sourceDetail.getConfirmedBatchNo());
        if (sourceDetail == null && StrUtil.isBlank(sourceProductionBatchNo)) {
            throw invalidParamException("请选择当前分段批次后再执行本段完成");
        }

        final HcGrindingSecondDetailDO segmentSourceDetail = sourceDetail;
        final String segmentSourceProductionBatchNo = sourceProductionBatchNo;
        List<HcAdhesiveReportDO> segmentReports = hcAdhesiveReportMapper.selectListByPlanOperationId(operation.getId())
                .stream()
                .filter(report -> isSameAdhesiveSegmentCompleteSource(report, segmentSourceDetail, segmentSourceProductionBatchNo))
                .toList();
        if (segmentReports.isEmpty()) {
            throw invalidParamException("当前分段批次暂无粘胶报工记录，不能标记完成");
        }
        boolean hasUnconfirmed = segmentReports.stream()
                .anyMatch(report -> {
                    String status = StrUtil.blankToDefault(report.getReportStatus(), "DRAFT");
                    return !"CONFIRMED".equalsIgnoreCase(status) && !"SUBMITTED".equalsIgnoreCase(status);
                });
        if (hasUnconfirmed) {
            throw invalidParamException("当前分段批次存在未扫码确认的粘胶报工记录，不能本段完成");
        }
        boolean allSubmitted = segmentReports.stream()
                .allMatch(report -> "SUBMITTED".equalsIgnoreCase(StrUtil.blankToDefault(report.getReportStatus(), "")));
        if (allSubmitted) {
            throw invalidParamException("当前分段批次已完成");
        }

        LocalDate reportDate = reqVO.getReportDate() == null ? LocalDate.now() : reqVO.getReportDate();
        LocalDateTime confirmerTime = normalizeReportDateTime(reqVO.getConfirmerTime(), reportDate);
        if (confirmerTime == null) {
            confirmerTime = LocalDateTime.now();
        }
        String confirmerName = firstNotBlank(reqVO.getConfirmerName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        for (HcAdhesiveReportDO report : segmentReports) {
            HcAdhesiveReportDO updateReport = new HcAdhesiveReportDO();
            updateReport.setId(report.getId());
            if (segmentSourceDetail != null) {
                updateReport.setSourceGrindingSecondDetailId(segmentSourceDetail.getId());
                updateReport.setSourceGrindingPlanId(segmentSourceDetail.getPlanId());
                updateReport.setSourceGrindingPlanNo(segmentSourceDetail.getPlanNo());
                updateReport.setSourceGrindingPlanOperationId(segmentSourceDetail.getPlanOperationId());
                updateReport.setSourceBatchNo(firstNotBlank(report.getSourceBatchNo(),
                        segmentSourceDetail.getMotherBatchNo(), segmentSourceProductionBatchNo));
            }
            updateReport.setSourceProductionBatchNo(firstNotBlank(segmentSourceProductionBatchNo,
                    report.getSourceProductionBatchNo()));
            updateReport.setReportStatus("SUBMITTED");
            updateReport.setConfirmerName(confirmerName);
            updateReport.setConfirmerTime(confirmerTime);
            hcAdhesiveReportMapper.updateById(updateReport);
        }
        HcAdhesiveReportDO firstReport = segmentReports.get(0);
        HcProcessReportDO segmentCompleteReport = buildBatchSegmentCompleteReport(
                planOrder, operation, segmentSourceProductionBatchNo, reportDate, confirmerTime, confirmerName,
                firstNotBlank(firstReport.getMaterialCode(), planOrder.getMaterialCode()),
                firstNotBlank(firstReport.getMaterialName(), planOrder.getMaterialName()),
                segmentReports.stream().map(HcAdhesiveReportDO::getOutputLength)
                        .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add),
                segmentReports.stream().map(HcAdhesiveReportDO::getLossLength)
                        .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add),
                segmentReports.size(), SOURCE_MENU_CODE_ADHESIVE_SEGMENT_COMPLETE, "粘胶1本段完工");
        hcProcessReportMapper.insert(segmentCompleteReport);
        return segmentCompleteReport.getId();
    }

    /**
     * 分段批次的完工事实只记录一条，避免把同一个 QTIME 上道完工时刻复制到每一片报工记录。
     */
    private HcProcessReportDO buildBatchSegmentCompleteReport(HcPlanOrderDO planOrder,
                                                               HcPlanOrderOperationDO operation,
                                                               String segmentBatchNo,
                                                               LocalDate reportDate,
                                                               LocalDateTime confirmerTime,
                                                               String confirmerName,
                                                               String materialCode,
                                                               String materialName,
                                                               BigDecimal goodQty,
                                                               BigDecimal scrapQty,
                                                               int reportCount,
                                                               String sourceMenuCode,
                                                               String remark) {
        Map<String, Object> extra = new LinkedHashMap<>();
        extra.put("segmentComplete", true);
        extra.put("qtimeScope", "BATCH");
        extra.put("reportCount", reportCount);
        return HcProcessReportDO.builder()
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .operationStatus(OP_STATUS_FINISHED)
                .operationSeq(operation.getOpSeq())
                .operationCode(operation.getOpCode())
                .operationName(operation.getOpName())
                .workCenterId(operation.getWorkCenterId())
                .workCenterCode(operation.getWorkCenterCode())
                .workCenterName(operation.getWorkCenterName())
                .equipmentId(operation.getEquipmentId())
                .equipmentCode(operation.getEquipmentCode())
                .equipmentName(operation.getEquipmentName())
                .materialId(planOrder.getMaterialId())
                .materialCode(materialCode)
                .materialName(materialName)
                .motherMaterialId(planOrder.getMotherMaterialId())
                .motherMaterialCode(firstNotBlank(operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode()))
                .motherMaterialName(firstNotBlank(operation.getMotherMaterialName(), planOrder.getMotherMaterialName()))
                .motherModelId(planOrder.getMotherModelId())
                .motherModelCode(firstNotBlank(operation.getMotherModelCode(), planOrder.getMotherModelCode()))
                .motherModelName(firstNotBlank(operation.getMotherModelName(), planOrder.getMotherModelName()))
                .batchNo(segmentBatchNo)
                .productionBatchNo(segmentBatchNo)
                .parentProductionBatchNo(segmentBatchNo)
                .parentBatchNo(segmentBatchNo)
                .sampleCode(operation.getSampleCode())
                .reportDate(reportDate)
                .startTime(confirmerTime)
                .endTime(confirmerTime)
                .goodQty(goodQty)
                .scrapQty(scrapQty)
                .recorderName(confirmerName)
                .recorderTime(confirmerTime)
                .confirmerName(confirmerName)
                .confirmerTime(confirmerTime)
                .reportUom(firstNotBlank(operation.getUom(), operation.getUnitCode(), operation.getUnitName(),
                        planOrder.getTargetUom(), "片"))
                .reportMinutes(0)
                .reportType(PRESS_SLOT_SEGMENT_COMPLETE_REPORT_TYPE)
                .sourceMenuCode(sourceMenuCode)
                .extraJson(JsonUtils.toJsonString(extra))
                .remark(remark)
                .build();
    }

    private boolean isSameAdhesiveSegmentCompleteSource(HcAdhesiveReportDO report,
                                                        HcGrindingSecondDetailDO sourceDetail,
                                                        String sourceProductionBatchNo) {
        if (report == null) {
            return false;
        }
        if (sourceDetail != null && Objects.equals(report.getSourceGrindingSecondDetailId(), sourceDetail.getId())) {
            return true;
        }
        return isSameBatch(report.getSourceProductionBatchNo(), sourceProductionBatchNo)
                || isSameBatch(report.getProductionBatchNo(), sourceProductionBatchNo);
    }

    @Override
    public HcAdhesiveIntermediateRespVO getAdhesiveIntermediate(Long planId, Long planOperationId, Long adhesiveReportId, String batchNo) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        HcPlanOrderOperationDO operation = validateAdhesiveOperation(planOrder, planOperationId);
        HcAdhesiveReportDO adhesiveReport = validateAdhesiveReportForIntermediate(adhesiveReportId, operation);
        HcAdhesiveIntermediateRecordDO record = adhesiveReportId != null
                ? hcAdhesiveIntermediateRecordMapper.selectByAdhesiveReportId(adhesiveReportId)
                : (StrUtil.isNotBlank(batchNo)
                ? hcAdhesiveIntermediateRecordMapper.selectByPlanOperationIdAndBatchNo(operation.getId(), batchNo)
                : hcAdhesiveIntermediateRecordMapper.selectByPlanOperationId(operation.getId()));
        if (record == null) {
            HcAdhesiveIntermediateRespVO resp = new HcAdhesiveIntermediateRespVO();
            resp.setPlanId(planOrder.getId());
            resp.setPlanNo(planOrder.getPlanNo());
            resp.setPlanOperationId(operation.getId());
            resp.setAdhesiveReportId(adhesiveReportId);
            resp.setProductionDate(adhesiveReport != null && adhesiveReport.getReportDate() != null
                    ? adhesiveReport.getReportDate().atStartOfDay() : LocalDateTime.now());
            resp.setModelCode(firstNotBlank(adhesiveReport == null ? null : adhesiveReport.getModelCode(),
                    planOrder.getModelCode(), planOrder.getModelName()));
            resp.setMaterialCode(firstNotBlank(adhesiveReport == null ? null : adhesiveReport.getMaterialCode(),
                    planOrder.getMaterialCode()));
            resp.setBatchNo(firstNotBlank(batchNo,
                    adhesiveReport == null ? null : adhesiveReport.getSourceProductionBatchNo(),
                    adhesiveReport == null ? null : adhesiveReport.getProductionBatchNo(),
                    operation.getProductionBatchNo(), planOrder.getProductionBatchNo(), operation.getBatchNo(), planOrder.getBatchNo()));
            resp.setProcessLength(adhesiveReport == null ? null
                    : firstNonNullDecimal(adhesiveReport.getOutputLength(), adhesiveReport.getInputLength()));
            resp.setRecordStatus("DRAFT");
            applyAdhesiveIntermediateTemplate(resp);
            resp.setDetails(buildDefaultAdhesiveIntermediateDetails(resp.getProcessLength()));
            return resp;
        }
        List<HcAdhesiveIntermediateDetailRespVO> details = hcAdhesiveIntermediateDetailMapper.selectListByRecordId(record.getId())
                .stream()
                .map(this::buildAdhesiveIntermediateDetailResp)
                .toList();
        HcAdhesiveIntermediateRespVO resp = buildAdhesiveIntermediateResp(record);
        resp.setDetails(details.isEmpty() ? buildDefaultAdhesiveIntermediateDetails(resp.getProcessLength()) : details);
        return resp;
    }

    @Override
    public HcAdhesiveIntermediateRespVO getAdhesiveIntermediateById(Long recordId) {
        HcAdhesiveIntermediateRecordDO record = validateAdhesiveIntermediateRecord(recordId);
        HcAdhesiveIntermediateRespVO resp = buildAdhesiveIntermediateResp(record);
        List<HcAdhesiveIntermediateDetailRespVO> details = hcAdhesiveIntermediateDetailMapper.selectListByRecordId(record.getId())
                .stream()
                .map(this::buildAdhesiveIntermediateDetailResp)
                .toList();
        resp.setDetails(details.isEmpty() ? buildDefaultAdhesiveIntermediateDetails(resp.getProcessLength()) : details);
        return resp;
    }

    @Override
    public PageResult<HcStationRecordRespVO> getAdhesiveIntermediateRecordPage(HcStationRecordPageReqVO reqVO) {
        HcStationRecordPageReqVO effectiveReqVO = reqVO == null ? new HcStationRecordPageReqVO() : reqVO;
        if (!matchesAdhesiveIntermediateStaticFilters(effectiveReqVO)) {
            return new PageResult<>(Collections.emptyList(), 0L);
        }
        HcStationRecordPageReqVO queryReqVO = isAdhesiveIntermediateStaticKeyword(effectiveReqVO.getKeyword())
                ? copyAdhesiveIntermediatePageReqWithoutKeyword(effectiveReqVO) : effectiveReqVO;
        PageResult<HcAdhesiveIntermediateRecordDO> page = hcAdhesiveIntermediateRecordMapper.selectPage(queryReqVO);
        List<HcStationRecordRespVO> records = page.getList().stream()
                .map(this::toAdhesiveIntermediateRecordListResp)
                .filter(record -> matchesAdhesiveIntermediateEquipmentFilters(record, effectiveReqVO))
                .toList();
        long total = hasAdhesiveIntermediateEquipmentFilter(effectiveReqVO) ? records.size() : page.getTotal();
        return new PageResult<>(records, total);
    }

    private boolean matchesAdhesiveIntermediateStaticFilters(HcStationRecordPageReqVO reqVO) {
        if (reqVO == null) {
            return true;
        }
        String formCode = StrUtil.trimToEmpty(reqVO.getFormCode());
        if (StrUtil.isNotBlank(formCode) && !isAdhesiveIntermediateFormCode(formCode)) {
            return false;
        }
        String formName = StrUtil.trimToEmpty(reqVO.getFormName());
        if (StrUtil.isNotBlank(formName) && !isAdhesiveIntermediateFormName(formName)) {
            return false;
        }
        String operationName = StrUtil.trimToEmpty(reqVO.getOperationName());
        if (StrUtil.isNotBlank(operationName) && !containsIgnoreCase("粘胶1 粘双面胶", operationName)) {
            return false;
        }
        String recordScope = StrUtil.trimToEmpty(reqVO.getRecordScope());
        if (StrUtil.isNotBlank(recordScope) && !"BUSINESS_RECORD".equalsIgnoreCase(recordScope)) {
            return false;
        }
        return reqVO.getConfirmTimeStart() == null
                && reqVO.getConfirmTimeEnd() == null;
    }

    private boolean isAdhesiveIntermediateFormCode(String formCode) {
        String normalized = StrUtil.trimToEmpty(formCode).toUpperCase();
        return ADHESIVE_INTERMEDIATE_FORM_CODE.equalsIgnoreCase(normalized)
                || (normalized.contains("ADHESIVE1") && normalized.contains("INTERMEDIATE"))
                || (normalized.startsWith(PROCESS_CODE_ADHESIVE + "_") && normalized.contains("INTERMEDIATE"));
    }

    private boolean isAdhesiveIntermediateFormName(String formName) {
        String text = StrUtil.trimToEmpty(formName);
        return containsIgnoreCase(ADHESIVE_INTERMEDIATE_FORM_NAME, text)
                || containsIgnoreCase(text, ADHESIVE_INTERMEDIATE_FORM_NAME)
                || (containsIgnoreCase(text, "粘胶1") && containsIgnoreCase(text, "中间品"));
    }

    private boolean hasAdhesiveIntermediateEquipmentFilter(HcStationRecordPageReqVO reqVO) {
        return reqVO != null && (StrUtil.isNotBlank(reqVO.getEquipmentCode())
                || StrUtil.isNotBlank(reqVO.getEquipmentName()));
    }

    private boolean matchesAdhesiveIntermediateEquipmentFilters(HcStationRecordRespVO record,
                                                               HcStationRecordPageReqVO reqVO) {
        if (record == null || reqVO == null) {
            return true;
        }
        String equipmentCode = StrUtil.trimToEmpty(reqVO.getEquipmentCode());
        if (StrUtil.isNotBlank(equipmentCode) && !containsIgnoreCase(record.getEquipmentCode(), equipmentCode)) {
            return false;
        }
        String equipmentName = StrUtil.trimToEmpty(reqVO.getEquipmentName());
        return StrUtil.isBlank(equipmentName)
                || containsIgnoreCase(record.getEquipmentName(), equipmentName)
                || containsIgnoreCase(record.getEquipmentCode(), equipmentName);
    }

    private boolean isAdhesiveIntermediateStaticKeyword(String keyword) {
        String text = StrUtil.trimToEmpty(keyword);
        return StrUtil.isNotBlank(text)
                && (isAdhesiveIntermediateFormName(text)
                || containsIgnoreCase("粘胶1 粘双面胶", text)
                || containsIgnoreCase("业务记录 BUSINESS_RECORD", text));
    }

    private HcStationFormDO resolveAdhesiveIntermediateStationFormConfig(String modelCode) {
        String normalizedModel = normalizePressSlotModelCode(modelCode);
        List<HcStationFormDO> forms = hcStationFormMapper.selectEnabledByProcess(PROCESS_CODE_ADHESIVE).stream()
                .filter(form -> PRESS_SLOT_INTERMEDIATE_FORM_TYPE.equalsIgnoreCase(
                        resolveAdhesiveIntermediateStationProcessFormType(form)))
                .filter(form -> getAdhesiveIntermediateModelMatchScore(form, normalizedModel) >= 0)
                .sorted(Comparator.comparingInt((HcStationFormDO form) -> getAdhesiveIntermediateModelMatchScore(form, normalizedModel))
                        .thenComparing(form -> form.getSortNo() == null ? Integer.MAX_VALUE : form.getSortNo())
                        .thenComparing(form -> form.getId() == null ? Long.MAX_VALUE : form.getId()))
                .toList();
        return forms.isEmpty() ? null : forms.get(0);
    }

    /** 粘胶1中间品严格遵守适用范围，不使用其他工序的0100系列回退。 */
    private int getAdhesiveIntermediateModelMatchScore(HcStationFormDO form, String model) {
        Map<String, Object> schema = parsePressSlotStationFormSchema(form);
        String exact = normalizePressSlotModelCode(toStringValue(schema.get("modelCode")));
        String prefix = normalizePressSlotModelCode(toStringValue(schema.get("modelPrefix")));
        String scope = normalizePressSlotModelCode(toStringValue(schema.get("modelScope")));
        if (StrUtil.isBlank(scope)) {
            scope = StrUtil.isNotBlank(prefix) ? "PREFIX"
                    : StrUtil.isNotBlank(exact) && !"COMMON".equals(exact) && !"ALL".equals(exact) ? "MODEL" : "COMMON";
        }
        if ("MODEL".equals(scope)) {
            return StrUtil.isNotBlank(exact) && exact.equals(model) ? 0 : -1;
        }
        if ("PREFIX".equals(scope)) {
            return StrUtil.isNotBlank(prefix) && StrUtil.isNotBlank(model) && model.startsWith(prefix) ? 10 : -1;
        }
        return "COMMON".equals(scope) ? 20 : -1;
    }

    private String resolveAdhesiveIntermediateStationProcessFormType(HcStationFormDO form) {
        Map<String, Object> schema = parsePressSlotStationFormSchema(form);
        String explicitType = firstNotBlank(
                toStringValue(schema.get("adhesive1FormType")),
                toStringValue(schema.get("adhesiveFormType")),
                toStringValue(schema.get("processFormType")),
                toStringValue(schema.get("formType")),
                toStringValue(schema.get("type")));
        String normalizedType = StrUtil.trimToEmpty(explicitType).toUpperCase();
        String formCode = form == null ? "" : StrUtil.blankToDefault(form.getFormCode(), "").toUpperCase();
        String formName = form == null ? "" : StrUtil.blankToDefault(form.getFormName(), "");
        String displayName = toStringValue(schema.get("displayName"));
        String combined = normalizedType + " " + formCode + " " + formName + " " + StrUtil.blankToDefault(displayName, "");
        if (combined.contains(PRESS_SLOT_INTERMEDIATE_FORM_TYPE)
                || combined.contains("INTERMEDIATE")
                || combined.contains("中间品")) {
            return PRESS_SLOT_INTERMEDIATE_FORM_TYPE;
        }
        return normalizedType;
    }

    private String resolveAdhesiveIntermediateStationDisplayName(HcStationFormDO form) {
        if (form == null) {
            return ADHESIVE_INTERMEDIATE_FORM_NAME;
        }
        Map<String, Object> schema = parsePressSlotStationFormSchema(form);
        return firstNotBlank(
                form.getFormName(),
                toStringValue(schema.get("formDisplayName")),
                toStringValue(schema.get("displayName")),
                ADHESIVE_INTERMEDIATE_FORM_NAME);
    }

    private HcStationRecordPageReqVO copyAdhesiveIntermediatePageReqWithoutKeyword(HcStationRecordPageReqVO source) {
        HcStationRecordPageReqVO target = new HcStationRecordPageReqVO();
        target.setPageNo(source.getPageNo());
        target.setPageSize(source.getPageSize());
        target.setPlanNo(source.getPlanNo());
        target.setOperationName(source.getOperationName());
        target.setFormName(source.getFormName());
        target.setFormCode(source.getFormCode());
        target.setExcludeFormCode(source.getExcludeFormCode());
        target.setFormCodePrefix(source.getFormCodePrefix());
        target.setEquipmentCode(source.getEquipmentCode());
        target.setEquipmentName(source.getEquipmentName());
        target.setRecordScope(source.getRecordScope());
        target.setCreateTimeStart(source.getCreateTimeStart());
        target.setCreateTimeEnd(source.getCreateTimeEnd());
        target.setCreateUserName(source.getCreateUserName());
        target.setConfirmUserName(source.getConfirmUserName());
        target.setConfirmTimeStart(source.getConfirmTimeStart());
        target.setConfirmTimeEnd(source.getConfirmTimeEnd());
        return target;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long saveAdhesiveIntermediate(HcAdhesiveIntermediateSaveReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validateAdhesiveOperation(planOrder, reqVO.getPlanOperationId());
        HcAdhesiveReportDO adhesiveReport = validateAdhesiveReportForIntermediate(reqVO.getAdhesiveReportId(), operation);
        HcAdhesiveIntermediateRecordDO record = reqVO.getId() == null
                ? (reqVO.getAdhesiveReportId() != null
                ? hcAdhesiveIntermediateRecordMapper.selectByAdhesiveReportId(reqVO.getAdhesiveReportId())
                : (StrUtil.isNotBlank(reqVO.getBatchNo())
                ? hcAdhesiveIntermediateRecordMapper.selectByPlanOperationIdAndBatchNo(operation.getId(), reqVO.getBatchNo())
                : hcAdhesiveIntermediateRecordMapper.selectByPlanOperationId(operation.getId())))
                : hcAdhesiveIntermediateRecordMapper.selectById(reqVO.getId());
        if (record == null || Boolean.TRUE.equals(record.getDeleted())) {
            record = HcAdhesiveIntermediateRecordDO.builder()
                    .tenantId(planOrder.getTenantId())
                    .planId(planOrder.getId())
                    .planNo(planOrder.getPlanNo())
                    .planOperationId(operation.getId())
                    .adhesiveReportId(reqVO.getAdhesiveReportId())
                    .recordStatus("DRAFT")
                    .build();
            fillAdhesiveIntermediateRecord(record, reqVO, planOrder, operation, adhesiveReport);
            hcAdhesiveIntermediateRecordMapper.insert(record);
        } else {
            fillAdhesiveIntermediateRecord(record, reqVO, planOrder, operation, adhesiveReport);
            hcAdhesiveIntermediateRecordMapper.updateById(record);
            hcAdhesiveIntermediateDetailMapper.deleteByRecordId(record.getId());
        }

        List<HcAdhesiveIntermediateDetailReqVO> details = reqVO.getDetails() == null ? Collections.emptyList() : reqVO.getDetails();
        if (!details.isEmpty()) {
            List<HcAdhesiveIntermediateDetailDO> detailList = new ArrayList<>();
            int index = 0;
            for (HcAdhesiveIntermediateDetailReqVO item : details) {
                index++;
                detailList.add(HcAdhesiveIntermediateDetailDO.builder()
                        .tenantId(planOrder.getTenantId())
                        .intermediateRecordId(record.getId())
                        .planId(planOrder.getId())
                        .planNo(planOrder.getPlanNo())
                        .planOperationId(operation.getId())
                        .lengthMark(item.getLengthMark())
                        .leftThickness(item.getLeftThickness())
                        .rightThickness(item.getRightThickness())
                        .remark(item.getRemark())
                        .sortNo(item.getSortNo() == null ? index : item.getSortNo())
                        .build());
            }
            hcAdhesiveIntermediateDetailMapper.insertBatch(detailList);
        }
        return record.getId();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long confirmAdhesiveIntermediate(HcAdhesiveIntermediateSaveReqVO reqVO) {
        if (reqVO.getId() == null) {
            throw invalidParamException("请先保存中间品记录单后再确认");
        }
        if (CollUtil.isEmpty(reqVO.getDetails())) {
            throw invalidParamException("中间品记录单明细不能为空");
        }
        HcAdhesiveIntermediateRecordDO existingRecord = validateAdhesiveIntermediateRecord(reqVO.getId());
        LocalDateTime confirmTime = LocalDateTime.now();
        String confirmerName = firstNotBlank(reqVO.getConfirmerName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        reqVO.setConfirmerName(confirmerName);
        reqVO.setRecordStatus("CONFIRMED");
        reqVO.setExtraJson(buildAdhesiveIntermediateConfirmExtra(
                firstNotBlank(reqVO.getExtraJson(), existingRecord.getExtraJson()), confirmerName, confirmTime));
        Long recordId = saveAdhesiveIntermediate(reqVO);

        HcAdhesiveIntermediateRecordDO confirmedRecord = validateAdhesiveIntermediateRecord(recordId);
        confirmedRecord.setRecordStatus("CONFIRMED");
        confirmedRecord.setConfirmerName(confirmerName);
        confirmedRecord.setExtraJson(buildAdhesiveIntermediateConfirmExtra(
                confirmedRecord.getExtraJson(), confirmerName, confirmTime));
        hcAdhesiveIntermediateRecordMapper.updateById(confirmedRecord);
        return recordId;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Integer importAdhesiveIntermediate(Long recordId, MultipartFile file) throws Exception {
        HcAdhesiveIntermediateRecordDO record = validateAdhesiveIntermediateRecord(recordId);
        List<HcAdhesiveIntermediateDetailDO> details = new ArrayList<>();
        DataFormatter formatter = new DataFormatter();
        try (InputStream inputStream = file.getInputStream(); Workbook workbook = WorkbookFactory.create(inputStream)) {
            Sheet sheet = workbook.getSheetAt(0);
            readAdhesiveIntermediateHeader(record, sheet, formatter);
            int seq = 1;
            for (int rowIndex = 6; rowIndex <= sheet.getLastRowNum(); rowIndex += 1) {
                Row row = sheet.getRow(rowIndex);
                HcAdhesiveIntermediateDetailDO detail = readAdhesiveIntermediateDetail(row, formatter, seq);
                if (detail != null) {
                    detail.setTenantId(record.getTenantId());
                    detail.setIntermediateRecordId(record.getId());
                    detail.setPlanId(record.getPlanId());
                    detail.setPlanNo(record.getPlanNo());
                    detail.setPlanOperationId(record.getPlanOperationId());
                    detail.setSortNo(seq);
                    details.add(detail);
                    seq += 1;
                }
            }
        }
        if (details.isEmpty()) {
            throw invalidParamException("导入数据不能为空");
        }
        hcAdhesiveIntermediateRecordMapper.updateById(record);
        hcAdhesiveIntermediateDetailMapper.deleteByRecordId(record.getId());
        hcAdhesiveIntermediateDetailMapper.insertBatch(details);
        return details.size();
    }

    @Override
    public void exportAdhesiveIntermediate(Long recordId, HttpServletResponse response) throws Exception {
        HcAdhesiveIntermediateRecordDO record = validateAdhesiveIntermediateRecord(recordId);
        List<HcAdhesiveIntermediateDetailDO> details = hcAdhesiveIntermediateDetailMapper.selectListByRecordId(record.getId());
        String fileName = URLEncoder.encode("CMP软垫（W26P0100）粘胶1中间品记录表.xlsx", StandardCharsets.UTF_8).replaceAll("\\+", "%20");
        response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;charset=UTF-8");
        response.setHeader("Content-Disposition", "attachment; filename*=UTF-8''" + fileName);
        try (Workbook workbook = createAdhesiveIntermediateWorkbook()) {
            writeAdhesiveIntermediateTemplate(workbook, record, details);
            workbook.write(response.getOutputStream());
        }
    }

    private Workbook createAdhesiveIntermediateWorkbook() throws Exception {
        InputStream inputStream = HcProcessReportServiceImpl.class.getResourceAsStream(ADHESIVE_INTERMEDIATE_TEMPLATE_RESOURCE);
        if (inputStream == null) {
            return new XSSFWorkbook();
        }
        try (InputStream templateStream = inputStream) {
            return WorkbookFactory.create(templateStream);
        }
    }

