    @Override
    public List<HcSlittingSourceRespVO> getSlittingSourceList(Long planId, Long planOperationId, String productionBatchNo) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        HcPlanOrderOperationDO operation = validateSlittingOperation(planOrder, planOperationId);
        Map<Long, List<HcSlittingSliceRecordDO>> sliceMap = hcSlittingSliceRecordMapper
                .selectListByPlanOperationId(planOperationId)
                .stream()
                .collect(Collectors.groupingBy(HcSlittingSliceRecordDO::getSourceAdhesiveReportId));
        List<HcPlanOrderInventoryLockDO> activeSourceLocks = selectActiveSlittingSourceWipLocks(planOperationId);
        Map<Long, HcPlanOrderInventoryLockDO> activeSourceLockMap = buildSlittingSourceLockMap(activeSourceLocks);
        Map<Long, HcAdhesiveReportDO> sourceReportMap = new LinkedHashMap<>();
        List<HcAdhesiveReportDO> currentPlanReports = hcAdhesiveReportMapper.selectSubmittedListByPlanId(planId,
                        StrUtil.isBlank(productionBatchNo) ? null : productionBatchNo)
                .stream()
                .filter(report -> !isAbnormalAdhesiveProduct(report))
                .toList();
        currentPlanReports.forEach(report -> sourceReportMap.put(report.getId(), report));
        Set<Long> lockedSourceReportIds = activeSourceLockMap.keySet().stream()
                .filter(Objects::nonNull)
                .filter(id -> !sourceReportMap.containsKey(id))
                .collect(Collectors.toCollection(LinkedHashSet::new));
        if (!lockedSourceReportIds.isEmpty()) {
            hcAdhesiveReportMapper.selectBatchIds(lockedSourceReportIds).stream()
                    .filter(report -> report != null && !Boolean.TRUE.equals(report.getDeleted()))
                    .filter(report -> "CONFIRMED".equalsIgnoreCase(StrUtil.blankToDefault(report.getReportStatus(), ""))
                            || "SUBMITTED".equalsIgnoreCase(StrUtil.blankToDefault(report.getReportStatus(), "")))
                    .filter(report -> isSlittingSourceProductionBatchMatched(report, productionBatchNo))
                    .filter(report -> !isAbnormalAdhesiveProduct(report))
                    .forEach(report -> sourceReportMap.put(report.getId(), report));
        }
        List<HcAdhesiveReportDO> sourceReports = new ArrayList<>(sourceReportMap.values());
        Map<Long, HcGrindingSecondDetailDO> sourceDetailMap = loadSlittingSourceDetailMap(sourceReports);
        return sourceReports.stream()
                .map(report -> {
                    HcGrindingSecondDetailDO sourceDetail = sourceDetailMap.get(report.getSourceGrindingSecondDetailId());
                    List<HcSlittingSliceRecordDO> slices = sliceMap.getOrDefault(report.getId(), Collections.emptyList());
                    HcPlanOrderInventoryLockDO sourceLock = activeSourceLockMap.get(report.getId());
                    boolean restrictToLockQty = sourceLock != null && !Objects.equals(report.getPlanId(), planOrder.getId());
                    return buildSlittingSourceResp(report, sourceDetail, slices, sourceLock, restrictToLockQty, operation);
                })
                .toList();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcSlittingSourceRespVO completeSlittingSource(HcSlittingSourceCompleteReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectByIdForUpdate(reqVO.getPlanId());
        assertPlanReleasedForStart(planOrder);
        HcPlanOrderOperationDO operation = validateSlittingOperation(planOrder, reqVO.getPlanOperationId());
        validateSlittingOperationMutable(operation, "标记切片完成");
        HcAdhesiveReportDO sourceReport = hcAdhesiveReportMapper.selectById(reqVO.getSourceAdhesiveReportId());
        if (sourceReport == null || Boolean.TRUE.equals(sourceReport.getDeleted())) {
            throw invalidParamException("来源粘胶报工记录不存在");
        }
        validateSlittingSourceMutable(sourceReport, "标记切片完成");
        HcPlanOrderInventoryLockDO sourceLock = resolveActiveSourceWipLock(operation.getId(),
                SOURCE_TABLE_ADHESIVE_REPORT, sourceReport.getId());
        validateSlittingSourceBelongsToPlanOrLock(sourceReport, planOrder, sourceLock);
        if (!"CONFIRMED".equalsIgnoreCase(StrUtil.blankToDefault(sourceReport.getReportStatus(), ""))
                && !"SUBMITTED".equalsIgnoreCase(StrUtil.blankToDefault(sourceReport.getReportStatus(), ""))) {
            throw invalidParamException("来源粘胶报工未扫码确认，不能标记分切完成");
        }

        List<HcSlittingSliceRecordDO> slices = hcSlittingSliceRecordMapper
                .selectListBySourceId(operation.getId(), sourceReport.getId());
        adminUserApi.validateUser(reqVO.getConfirmerUserId());
        AdminUserRespDTO confirmer = adminUserApi.getUser(reqVO.getConfirmerUserId());
        if (confirmer == null) {
            throw invalidParamException("确认人不存在或已禁用");
        }
        LocalDateTime completeTime = LocalDateTime.now();
        String confirmerName = firstNotBlank(confirmer.getNickname(), "系统");
        BigDecimal disposedTailLength = disposeSlittingSourceTailIfNeeded(planOrder, operation,
                sourceReport, sourceLock, slices, reqVO, confirmerName);
        Map<String, Object> extra = new LinkedHashMap<>(parseRoughExtraMap(sourceReport.getExtraJson()));
        extra.put(SLITTING_SOURCE_STATUS_KEY, SLITTING_SOURCE_COMPLETED);
        extra.put("slittingSourceCompleted", true);
        extra.put("slittingSourceCompleteTime", completeTime.format(DATETIME_FORMATTER));
        extra.put("slittingSourceCompleteOperatorId", confirmer.getId());
        extra.put("slittingSourceCompleteOperatorName", confirmerName);
        if (disposedTailLength.compareTo(BigDecimal.ZERO) > 0) {
            extra.put("slittingTailDisposed", true);
            extra.put("slittingTailDisposeLength", disposedTailLength);
            extra.put("slittingTailDisposeReason",
                    firstNotBlank(reqVO.getTailDisposalReason(), "分切完成尾料消耗"));
        }
        HcAdhesiveReportDO updateObj = new HcAdhesiveReportDO();
        updateObj.setId(sourceReport.getId());
        updateObj.setExtraJson(JsonUtils.toJsonString(extra));
        hcAdhesiveReportMapper.updateById(updateObj);
        sourceReport.setExtraJson(updateObj.getExtraJson());

        HcGrindingSecondDetailDO sourceDetail = sourceReport.getSourceGrindingSecondDetailId() == null
                ? null
                : hcGrindingSecondDetailMapper.selectById(sourceReport.getSourceGrindingSecondDetailId());
        return buildSlittingSourceResp(sourceReport, sourceDetail, slices, sourceLock,
                !Objects.equals(sourceReport.getPlanId(), planOrder.getId()), operation);
    }

    private BigDecimal disposeSlittingSourceTailIfNeeded(HcPlanOrderDO planOrder,
                                                         HcPlanOrderOperationDO operation,
                                                         HcAdhesiveReportDO sourceReport,
                                                         HcPlanOrderInventoryLockDO sourceLock,
                                                         List<HcSlittingSliceRecordDO> slices,
                                                         HcSlittingSourceCompleteReqVO reqVO,
                                                         String operatorName) {
        if (!Boolean.TRUE.equals(reqVO.getDisposeRemainingTail())) {
            return BigDecimal.ZERO;
        }
        long unconfirmedCount = slices == null ? 0 : slices.stream()
                .filter(item -> !"CONFIRMED".equalsIgnoreCase(StrUtil.blankToDefault(item.getScanStatus(), "")))
                .count();
        if (unconfirmedCount > 0) {
            throw invalidParamException("当前段仍有 {} 片未扫码确认，不能处置分切尾料", unconfirmedCount);
        }
        BigDecimal outputLength = firstNonNullDecimal(sourceReport.getOutputLength(), sourceReport.getInputLength());
        BigDecimal availableLength = resolveSlittingAvailableSourceLength(sourceReport, outputLength, slices);
        if (sourceLock != null) {
            availableLength = availableLength.min(calculateWipLockRemainingQty(sourceLock)).max(BigDecimal.ZERO);
        }
        BigDecimal disposeLength = firstNonNullDecimal(reqVO.getTailDisposalLength(), availableLength);
        disposeLength = zeroIfNull(disposeLength);
        if (disposeLength.compareTo(BigDecimal.ZERO) <= 0) {
            return BigDecimal.ZERO;
        }
        if (disposeLength.compareTo(availableLength) > 0) {
            throw invalidParamException("尾料处置长度不能大于当前剩余可加工长度 {}m", formatDecimal(availableLength));
        }
        HcPlanOrderInventoryLockDO effectiveLock = sourceLock;
        if (effectiveLock == null) {
            effectiveLock = ensureSourceWipLockedForOperation(planOrder, operation,
                    SOURCE_TYPE_ADHESIVE1, SOURCE_TABLE_ADHESIVE_REPORT, sourceReport.getId(),
                    disposeLength, operatorName, "分切完成尾料处置自动锁定粘胶1中间品");
        }
        if (effectiveLock == null) {
            throw invalidParamException("来源粘胶1中间品没有可消耗的WIP库存，不能处置分切尾料");
        }
        LocalDateTime disposeTime = LocalDateTime.now();
        consumeSourceWipLock(effectiveLock, disposeLength, SOURCE_MENU_CODE_SLITTING_TAIL_LOSS,
                sourceReport.getId(),
                firstNotBlank(sourceReport.getProductionBatchNo(), sourceReport.getSourceProductionBatchNo(),
                        sourceReport.getSourceBatchNo()),
                disposeTime, operatorName,
                "分切来源完成尾料处置；原因："
                        + firstNotBlank(reqVO.getTailDisposalReason(), "分切完成尾料消耗"));
        hcAdhesiveReportMapper.deductSlittingRemainingLength(sourceReport.getId(), disposeLength);
        BigDecimal currentRemaining = firstNonNullDecimal(sourceReport.getSlittingRemainingLength(), availableLength);
        sourceReport.setSlittingRemainingLength(zeroIfNull(currentRemaining).subtract(disposeLength).max(BigDecimal.ZERO));
        return disposeLength;
    }

    @Override
    public List<HcSlittingSliceRespVO> getSlittingSliceList(Long planOperationId, LocalDate scanConfirmDate) {
        LocalDateTime scanTimeStart = scanConfirmDate == null ? null : scanConfirmDate.atStartOfDay();
        LocalDateTime scanTimeEndExclusive = scanConfirmDate == null ? null : scanConfirmDate.plusDays(1).atStartOfDay();
        List<HcSlittingSliceRecordDO> records = hcSlittingSliceRecordMapper.selectListByPlanOperationId(
                planOperationId, scanTimeStart, scanTimeEndExclusive);
        Map<Long, HcPressSlotReportDO> feedbackMap = loadSlittingDownstreamFeedbackMap(records);
        Map<Long, String> editBlockedReasonMap = loadSlittingEditBlockedReasonMap(records);
        return records
                .stream()
                .map(record -> {
                    HcSlittingSliceRespVO resp = buildSlittingSliceResp(record);
                    applySlittingDownstreamFeedback(resp, feedbackMap.get(record.getId()));
                    resp.setEditBlockedReason(editBlockedReasonMap.get(record.getId()));
                    return resp;
                })
                .toList();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public List<HcSlittingSliceRespVO> generateSlittingSlices(HcSlittingSliceGenerateReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectByIdForUpdate(reqVO.getPlanId());
        assertPlanReleasedForStart(planOrder);
        HcPlanOrderOperationDO operation = validateSlittingOperation(planOrder, reqVO.getPlanOperationId());
        validateSlittingOperationMutable(operation, "初始化切片");
        HcAdhesiveReportDO sourceReport = hcAdhesiveReportMapper.selectById(reqVO.getSourceAdhesiveReportId());
        if (sourceReport == null || Boolean.TRUE.equals(sourceReport.getDeleted())) {
            throw invalidParamException("来源粘胶报工记录不存在");
        }
        validateSlittingSourceMutable(sourceReport, "初始化切片");
        HcPlanOrderInventoryLockDO sourceLock = resolveActiveSourceWipLock(operation.getId(),
                SOURCE_TABLE_ADHESIVE_REPORT, sourceReport.getId());
        validateSlittingSourceBelongsToPlanOrLock(sourceReport, planOrder, sourceLock);
        String sourceStatus = StrUtil.blankToDefault(sourceReport.getReportStatus(), "DRAFT");
        if (!"CONFIRMED".equalsIgnoreCase(sourceStatus) && !"SUBMITTED".equalsIgnoreCase(sourceStatus)) {
            throw invalidParamException("来源粘胶报工未扫码确认，不能初始化分切切片");
        }
        if (isAbnormalAdhesiveProduct(sourceReport)) {
            throw invalidParamException("来源粘胶批次存在质量异常锁定，不能进入分切");
        }

        List<HcSlittingSliceRecordDO> allOperationRecords = hcSlittingSliceRecordMapper
                .selectListByPlanOperationId(operation.getId());

        int sliceCount = reqVO.getSliceCount() == null ? 1 : reqVO.getSliceCount();
        if (sliceCount > 200) {
            throw invalidParamException("本次切片数量不能超过200");
        }
        String cutMode = StrUtil.blankToDefault(reqVO.getCutMode(), "AUTO").toUpperCase();
        boolean manualCut = "MANUAL".equals(cutMode);
        SlittingSliceSizeRule sizeRule = resolveSlittingGenerateSliceSizeRule(reqVO, planOrder);
        HcGrindingSecondDetailDO sourceDetail = sourceReport.getSourceGrindingSecondDetailId() == null
                ? null
                : hcGrindingSecondDetailMapper.selectById(sourceReport.getSourceGrindingSecondDetailId());
        String segmentBatchNo = resolveSlittingSegmentBatchNo(sourceReport, sourceDetail);
        if (StrUtil.isBlank(segmentBatchNo)) {
            throw invalidParamException("来源粘胶报工缺少批次号，不能初始化切片流水号");
        }
        BigDecimal sourceLength = firstNonNullDecimal(sourceReport.getOutputLength(), sourceReport.getInputLength());
        if (sourceLength == null || sourceLength.compareTo(BigDecimal.ZERO) <= 0) {
            throw invalidParamException("来源粘胶报工缺少可分切长度，不能初始化切片");
        }
        boolean externalLockedSource = sourceLock != null && !Objects.equals(sourceReport.getPlanId(), planOrder.getId());
        if (externalLockedSource && !manualCut) {
            BigDecimal lockRemainingQty = calculateWipLockRemainingQty(sourceLock);
            if (lockRemainingQty.compareTo(BigDecimal.ZERO) <= 0) {
                throw invalidParamException("当前分切计划挂接的来源中间品剩余量不足，不能初始化切片");
            }
            sourceLength = sourceLength.min(lockRemainingQty);
        }
        BigDecimal startPosition = BigDecimal.ZERO;
        BigDecimal sliceLength = reqVO.getSliceLength();
        if (manualCut) {
            sliceLength = null;
        } else {
            if (sliceLength == null || sliceLength.compareTo(BigDecimal.ZERO) <= 0) {
                sliceLength = sourceLength.divide(BigDecimal.valueOf(sliceCount), 3, java.math.RoundingMode.HALF_UP);
            }
            if (sliceLength.compareTo(BigDecimal.ZERO) <= 0) {
                throw invalidParamException("单片占用长度必须大于0");
            }
            BigDecimal requestedLength = sliceLength.multiply(BigDecimal.valueOf(sliceCount));
            BigDecimal existingReservedLength = allOperationRecords.stream()
                    .filter(record -> Objects.equals(record.getSourceAdhesiveReportId(), sourceReport.getId()))
                    .filter(record -> !externalLockedSource
                            || !"CONFIRMED".equalsIgnoreCase(StrUtil.blankToDefault(record.getScanStatus(), "")))
                    .map(this::resolveSlittingSliceUsedLength)
                    .reduce(BigDecimal.ZERO, BigDecimal::add);
            BigDecimal remainingForGenerate = sourceLength.subtract(existingReservedLength).max(BigDecimal.ZERO);
            if (requestedLength.compareTo(remainingForGenerate) > 0) {
                throw invalidParamException("本次切片总占用长度超过来源可分切长度，来源可用 "
                        + remainingForGenerate.stripTrailingZeros().toPlainString()
                        + "，本次需要 " + requestedLength.stripTrailingZeros().toPlainString());
            }
        }
        if (!manualCut) {
            sourceLock = ensureSourceWipLockedForOperation(planOrder, operation,
                    SOURCE_TYPE_ADHESIVE1, SOURCE_TABLE_ADHESIVE_REPORT, sourceReport.getId(),
                    sourceLength, firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统"),
                    "分切入站自动锁定粘胶1中间品");
        }
        String motherBatchNo = resolveSlittingMotherBatch(sourceReport);
        // 删除切片不再占用后续人工/自动切片的流水号；有效片仍保持同母批流水号唯一。
        int startSerialNo = resolveSlittingStartSerialNo(allOperationRecords, motherBatchNo, reqVO.getStartSerialNo());
        Set<Integer> usedMotherSerialNos = allOperationRecords.stream()
                .filter(record -> isSameSlittingMother(motherBatchNo, record))
                .map(record -> extractSlittingSliceSerialNo(record.getSliceSerialNo()))
                .filter(Objects::nonNull)
                .collect(Collectors.toSet());
        Set<String> usedSliceSerialNos = allOperationRecords.stream()
                .map(HcSlittingSliceRecordDO::getSliceSerialNo)
                .filter(StrUtil::isNotBlank)
                .map(String::toUpperCase)
                .collect(Collectors.toSet());
        List<HcSlittingSliceRecordDO> insertList = new ArrayList<>();
        for (int index = 1; index <= sliceCount; index++) {
            int sliceIndex = startSerialNo + index - 1;
            BigDecimal itemStart = manualCut ? null : startPosition.add(sliceLength.multiply(BigDecimal.valueOf(index - 1L)));
            BigDecimal itemEnd = manualCut ? null : itemStart.add(sliceLength);
            String sliceSerialNo = buildSlittingSliceSerialNo(segmentBatchNo + String.format("%03d", sliceIndex), sizeRule);
            if (usedMotherSerialNos.contains(sliceIndex) || usedSliceSerialNos.contains(sliceSerialNo.toUpperCase())) {
                throw invalidParamException("切片流水号" + sliceSerialNo + "已存在，请调整起始流水号");
            }
            usedMotherSerialNos.add(sliceIndex);
            usedSliceSerialNos.add(sliceSerialNo.toUpperCase());
            insertList.add(HcSlittingSliceRecordDO.builder()
                    .tenantId(planOrder.getTenantId())
                    .planId(planOrder.getId())
                    .planNo(planOrder.getPlanNo())
                    .planOperationId(operation.getId())
                    .operationCode(operation.getOpCode())
                    .operationName(operation.getOpName())
                    .sourceAdhesiveReportId(sourceReport.getId())
                    .sourceStockId(sourceLock == null ? null : sourceLock.getStockId())
                    .sourcePlanLockId(sourceLock == null ? null : sourceLock.getId())
                    .sourceStockBatchNo(sourceLock == null ? null : firstNotBlank(sourceLock.getSourceBatchNo(), sourceLock.getBatchNo()))
                    .sourceLockQty(sourceLock == null || manualCut ? null : sliceLength)
                    .sourceBatchNo(segmentBatchNo)
                    .sourceProductionBatchNo(firstNotBlank(sourceReport.getProductionBatchNo(), sourceReport.getSourceProductionBatchNo()))
                    .sourceLength(sourceLength)
                    .startPosition(itemStart)
                    .endPosition(itemEnd)
                    .sliceLength(sliceLength)
                    .cutMode(cutMode)
                    .sliceSerialNo(sliceSerialNo)
                    .sliceIndex(sliceIndex)
                    .sizeCode(sizeRule.sizeCode())
                    .sizeName(sizeRule.sizeName())
                    .printStatus("UNPRINTED")
                    .printCount(0)
                    .scanStatus("UNCONFIRMED")
                    .build());
        }
        if (!insertList.isEmpty()) {
            hcSlittingSliceRecordMapper.insertBatch(insertList);
        }
        return hcSlittingSliceRecordMapper.selectListBySourceId(operation.getId(), sourceReport.getId())
                .stream()
                .map(this::buildSlittingSliceResp)
                .toList();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void deleteSlittingSlice(Long id) {
        HcSlittingSliceRecordDO record = hcSlittingSliceRecordMapper.selectByIdForUpdate(id);
        if (record == null) {
            throw invalidParamException("切片记录不存在或已删除");
        }
        if ("CONFIRMED".equalsIgnoreCase(StrUtil.blankToDefault(record.getScanStatus(), ""))) {
            throw invalidParamException("切片已确认入账，不能删除");
        }
        validateSlittingSliceMutable(record, "删除切片");
        validateSlittingOverwriteAllowed(record);
        if (record.getOutputStockId() != null
                || StrUtil.isNotBlank(record.getSourceConsumeTxnNo())
                || record.getSourceConsumeTime() != null) {
            throw invalidParamException("切片已产生库存或来源消耗记录，不能删除");
        }
        if (hcSlittingSliceRecordMapper.deleteById(record.getId()) <= 0) {
            throw invalidParamException("切片状态已变化，删除失败，请刷新后重试");
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void markSlittingSlicesPrinted(HcSlittingSlicePrintReqVO reqVO) {
        LocalDateTime now = LocalDateTime.now();
        for (Long id : reqVO.getIds()) {
            HcSlittingSliceRecordDO record = hcSlittingSliceRecordMapper.selectById(id);
            if (record == null || Boolean.TRUE.equals(record.getDeleted())) {
                continue;
            }
            validateSlittingSlicePrintable(record);
            HcSlittingSliceRecordDO updateObj = new HcSlittingSliceRecordDO();
            updateObj.setId(record.getId());
            updateObj.setPrintStatus("PRINTED");
            updateObj.setPrintCount((record.getPrintCount() == null ? 0 : record.getPrintCount()) + 1);
            updateObj.setLastPrintTime(now);
            hcSlittingSliceRecordMapper.updateById(updateObj);
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcSlittingSliceRespVO updateSlittingSliceContent(HcSlittingSliceConfirmReqVO reqVO) {
        HcSlittingSliceRecordDO record = hcSlittingSliceRecordMapper.selectById(reqVO.getId());
        if (record == null || Boolean.TRUE.equals(record.getDeleted())) {
            throw invalidParamException("切片记录不存在");
        }
        validateSlittingSliceMutable(record, "修改切片内容");
        validateSlittingOverwriteAllowed(record);
        HcSlittingSliceRecordDO updateObj = new HcSlittingSliceRecordDO();
        updateObj.setId(record.getId());
        updateObj.setVisualResultJson(JsonUtils.toJsonString(
                reqVO.getVisualItems() == null ? Collections.emptyList() : reqVO.getVisualItems()));
        updateObj.setSelfCheck(StrUtil.blankToDefault(reqVO.getSelfCheck(), "OK"));
        updateObj.setRemark(reqVO.getRemark());
        hcSlittingSliceRecordMapper.updateById(updateObj);
        clearSlittingWaitShelfNgPieceIfChangedToOk(record);
        return buildSlittingSliceResp(hcSlittingSliceRecordMapper.selectById(record.getId()));
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcSlittingSliceRespVO confirmSlittingSlice(HcSlittingSliceConfirmReqVO reqVO) {
        HcSlittingSliceRecordDO record = hcSlittingSliceRecordMapper.selectByIdForUpdate(reqVO.getId());
        if (record == null || Boolean.TRUE.equals(record.getDeleted())) {
            throw invalidParamException("切片记录不存在");
        }
        validateSlittingSliceMutable(record, "扫码确认");
        validateSlittingOverwriteAllowed(record);
        boolean firstConfirm = !"CONFIRMED".equalsIgnoreCase(StrUtil.blankToDefault(record.getScanStatus(), ""));
        SlittingSliceSizeRule sizeRule = resolveSlittingConfirmSliceSizeRule(reqVO, record);
        String originalSliceSerialNo = record.getSliceSerialNo();
        String targetSliceSerialNo = buildSlittingSliceSerialNo(originalSliceSerialNo, sizeRule);
        if (StrUtil.isNotBlank(reqVO.getScannedSliceNo())
                && !StrUtil.equalsIgnoreCase(stripSlittingSizeSuffix(originalSliceSerialNo),
                stripSlittingSizeSuffix(reqVO.getScannedSliceNo()))) {
            throw invalidParamException("扫码切片流水号与当前记录不一致");
        }
        if (!StrUtil.equalsIgnoreCase(originalSliceSerialNo, targetSliceSerialNo)) {
            if (!firstConfirm) {
                throw invalidParamException("切片已确认入账，不能再次调整片号尾号A/B");
            }
            HcSlittingSliceRecordDO sameSerialNoRecord = hcSlittingSliceRecordMapper.selectBySerialNo(targetSliceSerialNo);
            if (sameSerialNoRecord != null && !Objects.equals(sameSerialNoRecord.getId(), record.getId())) {
                throw invalidParamException("切片流水号" + targetSliceSerialNo + "已存在，不能调整片号");
            }
        }
        HcAdhesiveReportDO sourceReport = null;
        if (firstConfirm) {
            sourceReport = record.getSourceAdhesiveReportId() == null
                    ? null
                    : hcAdhesiveReportMapper.selectById(record.getSourceAdhesiveReportId());
            if (sourceReport == null || Boolean.TRUE.equals(sourceReport.getDeleted())) {
                throw invalidParamException("来源粘胶报工记录不存在，不能确认分切");
            }
            validateSlittingSampleAbnormalUnlocked(sourceReport, "扫码确认分切");
            initializeSlittingSourceRemainingLengthIfAbsent(sourceReport);
        }
        LocalDateTime confirmTime = LocalDateTime.now();
        String scannerName = recorderNameResolver.resolveForSave(
                firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统"));
        HcSlittingSliceRecordDO updateObj = new HcSlittingSliceRecordDO();
        updateObj.setId(record.getId());
        updateObj.setScanStatus("CONFIRMED");
        updateObj.setScanTime(confirmTime);
        updateObj.setScannerId(SecurityFrameworkUtils.getLoginUserId());
        updateObj.setScannerName(scannerName);
        updateObj.setSliceSerialNo(targetSliceSerialNo);
        updateObj.setSizeCode(sizeRule.sizeCode());
        updateObj.setSizeName(sizeRule.sizeName());
        updateObj.setVisualResultJson(JsonUtils.toJsonString(
                reqVO.getVisualItems() == null ? Collections.emptyList() : reqVO.getVisualItems()));
        updateObj.setSelfCheck(StrUtil.blankToDefault(reqVO.getSelfCheck(), "OK"));
        updateObj.setRemark(mergeSlittingSliceAdjustRemark(reqVO.getRemark(), originalSliceSerialNo, targetSliceSerialNo));
        hcSlittingSliceRecordMapper.updateById(updateObj);
        record.setSliceSerialNo(targetSliceSerialNo);
        record.setSizeCode(sizeRule.sizeCode());
        record.setSizeName(sizeRule.sizeName());
        record.setRemark(updateObj.getRemark());
        clearSlittingWaitShelfNgPieceIfChangedToOk(record);
        if (firstConfirm) {
            BigDecimal deductLength = resolveSlittingSliceUsedLength(record);
            if (deductLength.compareTo(BigDecimal.ZERO) > 0) {
                hcAdhesiveReportMapper.deductSlittingRemainingLength(sourceReport.getId(), deductLength);
            }
            consumeSlittingSourceWipIfPresent(record, sourceReport, deductLength, confirmTime, scannerName);
            // 重新读取已确认切片，确保 NG 分流使用本次确认提交的自检与目视结果。
            HcSlittingSliceRecordDO confirmedRecord = hcSlittingSliceRecordMapper.selectById(record.getId());
            postSlittingSliceOutputWipIfNeeded(confirmedRecord, confirmTime, scannerName);
        }
        return buildSlittingSliceResp(hcSlittingSliceRecordMapper.selectById(record.getId()));
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcSlittingSliceRespVO correctSlittingSliceAbnormalCategory(HcVisualAbnormalCategoryCorrectReqVO reqVO) {
        String category = StrUtil.trimToEmpty(reqVO.getCategory());
        String reason = StrUtil.trimToEmpty(reqVO.getReason());
        validateVisualAbnormalCategory(category, reason);
        HcSlittingSliceRecordDO record = hcSlittingSliceRecordMapper.selectByIdForUpdate(reqVO.getId());
        if (record == null || Boolean.TRUE.equals(record.getDeleted())) {
            throw invalidParamException("切片记录不存在");
        }
        List<String> beforeCategories = resolveAdhesive2ActiveVisualCategories(record.getVisualResultJson());
        if (!isNgResultValue(record.getSelfCheck()) && beforeCategories.isEmpty()) {
            throw invalidParamException("当前分切切片没有外观异常类别，不能修正");
        }

        List<Map<String, Object>> correctedVisualItems = buildAdhesive2CorrectedVisualItems(
                record.getVisualResultJson(), category);
        String correctedAt = LocalDateTime.now().format(DATETIME_FORMATTER);
        Long correctedById = SecurityFrameworkUtils.getLoginUserId();
        String correctedByName = firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        correctedVisualItems.stream()
                .filter(item -> StrUtil.equals(category, toStringValue(item.get("itemName"))))
                .findFirst()
                .ifPresent(item -> {
                    item.put("abnormalCategoryCorrected", true);
                    item.put("abnormalCategoryCorrectionReason", reason);
                    item.put("abnormalCategoryCorrectionTime", correctedAt);
                    item.put("abnormalCategoryCorrectionUserId", correctedById);
                    item.put("abnormalCategoryCorrectionUserName", correctedByName);
                });
        HcSlittingSliceRecordDO updateObj = new HcSlittingSliceRecordDO();
        updateObj.setId(record.getId());
        updateObj.setSelfCheck("NG");
        updateObj.setVisualResultJson(JsonUtils.toJsonString(correctedVisualItems));
        updateObj.setRemark(buildVisualAbnormalCategoryCorrectionRemark(
                record.getRemark(), beforeCategories, category, correctedAt, correctedByName));
        hcSlittingSliceRecordMapper.updateById(updateObj);
        return buildSlittingSliceResp(hcSlittingSliceRecordMapper.selectById(record.getId()));
    }

    private void consumeSlittingSourceWipIfPresent(HcSlittingSliceRecordDO record,
                                                   HcAdhesiveReportDO sourceReport,
                                                   BigDecimal consumeQty,
                                                   LocalDateTime consumeTime,
                                                   String operatorName) {
        if (record == null || sourceReport == null || record.getId() == null || sourceReport.getId() == null) {
            return;
        }
        BigDecimal normalizedConsumeQty = zeroIfNull(consumeQty);
        if (normalizedConsumeQty.compareTo(BigDecimal.ZERO) <= 0) {
            return;
        }
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(record.getPlanId());
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(record.getPlanOperationId());
        HcPlanOrderInventoryLockDO sourceLock = record.getSourcePlanLockId() == null
                ? null
                : hcPlanOrderInventoryLockMapper.selectById(record.getSourcePlanLockId());
        if (!isActivePlanWipLock(sourceLock)) {
            sourceLock = resolveActiveSourceWipLock(record.getPlanOperationId(), SOURCE_TABLE_ADHESIVE_REPORT, sourceReport.getId());
        }
        if (sourceLock == null) {
            BigDecimal sourceLength = firstNonNullDecimal(sourceReport.getOutputLength(), sourceReport.getInputLength());
            sourceLock = ensureSourceWipLockedForOperation(planOrder, operation,
                    SOURCE_TYPE_ADHESIVE1, SOURCE_TABLE_ADHESIVE_REPORT, sourceReport.getId(),
                    sourceLength, operatorName, "分切确认补锁粘胶1中间品");
        }
        HcInvStockDO consumedStock = consumeSourceWipLock(sourceLock, normalizedConsumeQty,
                SOURCE_TYPE_SLITTING, record.getId(), record.getSliceSerialNo(), consumeTime, operatorName,
                "分切确认消耗粘胶1中间品；来源批号：" + firstNotBlank(sourceReport.getProductionBatchNo(), sourceReport.getSourceProductionBatchNo(), "-"));
        if (sourceLock == null || consumedStock == null) {
            return;
        }
        HcSlittingSliceRecordDO consumeUpdate = new HcSlittingSliceRecordDO();
        consumeUpdate.setId(record.getId());
        consumeUpdate.setSourceStockId(sourceLock.getStockId());
        consumeUpdate.setSourcePlanLockId(sourceLock.getId());
        consumeUpdate.setSourceStockBatchNo(firstNotBlank(sourceLock.getSourceBatchNo(), sourceLock.getBatchNo()));
        consumeUpdate.setSourceLockQty(normalizedConsumeQty);
        consumeUpdate.setSourceConsumeQty(normalizedConsumeQty);
        consumeUpdate.setSourceConsumeTxnNo(consumedStock.getLastTxnNo());
        consumeUpdate.setSourceConsumeTime(consumedStock.getLastTxnTime());
        hcSlittingSliceRecordMapper.updateById(consumeUpdate);
        record.setSourceStockId(sourceLock.getStockId());
        record.setSourcePlanLockId(sourceLock.getId());
        record.setSourceStockBatchNo(consumeUpdate.getSourceStockBatchNo());
        record.setSourceLockQty(normalizedConsumeQty);
        record.setSourceConsumeQty(normalizedConsumeQty);
        record.setSourceConsumeTxnNo(consumedStock.getLastTxnNo());
        record.setSourceConsumeTime(consumedStock.getLastTxnTime());
    }

    private void postSlittingSliceOutputWipIfNeeded(HcSlittingSliceRecordDO record,
                                                    LocalDateTime postTime,
                                                    String operatorName) {
        if (record == null || record.getId() == null || record.getOutputStockId() != null) {
            return;
        }
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(record.getPlanId());
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(record.getPlanOperationId());
        if (planOrder == null || operation == null) {
            throw invalidParamException("分切片缺少计划或工序信息，无法入中间边库");
        }
        HcProductionInstructionDO freezeInstruction = hcNgInventoryService
                .getEffectiveFreezeInstruction(planOrder.getId(), operation.getId());
        if (freezeInstruction != null) {
            hcNgInventoryService.registerSlittingFrozenPiece(record, planOrder, operation, freezeInstruction);
            HcSlittingSliceRecordDO stockUpdate = new HcSlittingSliceRecordDO();
            stockUpdate.setId(record.getId());
            stockUpdate.setOutputStockPostStatus("NG_FROZEN");
            stockUpdate.setOutputStockPostTime(postTime);
            stockUpdate.setOutputStockPostMessage("冻结指令 " + freezeInstruction.getInstructionNo() + " 生效，已自动入冻结库");
            hcSlittingSliceRecordMapper.updateById(stockUpdate);
            record.setOutputStockPostStatus(stockUpdate.getOutputStockPostStatus());
            record.setOutputStockPostTime(postTime);
            record.setOutputStockPostMessage(stockUpdate.getOutputStockPostMessage());
            return;
        }
        if (isSlittingSliceNg(record)) {
            hcNgInventoryService.registerSlittingNgPiece(record, planOrder, operation);
            HcSlittingSliceRecordDO stockUpdate = new HcSlittingSliceRecordDO();
            stockUpdate.setId(record.getId());
            stockUpdate.setOutputStockPostStatus("NG_STORED");
            stockUpdate.setOutputStockPostTime(postTime);
            stockUpdate.setOutputStockPostMessage("分切 NG 已自动入分切库");
            hcSlittingSliceRecordMapper.updateById(stockUpdate);
            record.setOutputStockPostStatus(stockUpdate.getOutputStockPostStatus());
            record.setOutputStockPostTime(postTime);
            record.setOutputStockPostMessage(stockUpdate.getOutputStockPostMessage());
            return;
        }
        String motherRollBatchNo = resolveSlittingMotherRollBatchNo(record);
        HcInvStockDO stock = hcInvStockService.postProcessOutputWip(HcWipOutputPostReq.builder()
                .plan(planOrder)
                .operation(operation)
                .sourceType(SOURCE_TYPE_SLITTING)
                .sourceTable(SOURCE_TABLE_SLITTING_SLICE)
                .sourceId(record.getId())
                .sourceReportId(record.getSourceAdhesiveReportId())
                .batchNo(record.getSliceSerialNo())
                .parentBatchNo(motherRollBatchNo)
                .outputQty(BigDecimal.ONE)
                .uom("pcs")
                .modelNo(firstNotBlank(planOrder.getModelCode(), planOrder.getModelName()))
                .businessRemark("分切扫码确认产出入中间边库；来源计划：" + firstNotBlank(planOrder.getPlanNo(), "-")
                        + "；母卷批次号：" + firstNotBlank(motherRollBatchNo, "-")
                        + "；来源批号：" + firstNotBlank(record.getSourceProductionBatchNo(), record.getSourceBatchNo(), "-"))
                .txnRemark("分切扫码确认自动入中间边库")
                .postTime(postTime)
                .operatorId(SecurityFrameworkUtils.getLoginUserId())
                .operatorName(firstNotBlank(operatorName, SecurityFrameworkUtils.getLoginUserNickname(), "系统"))
                .build());
        HcSlittingSliceRecordDO stockUpdate = new HcSlittingSliceRecordDO();
        stockUpdate.setId(record.getId());
        stockUpdate.setOutputStockId(stock.getId());
        stockUpdate.setOutputStockPostStatus(STOCK_POST_STATUS_POSTED);
        stockUpdate.setOutputStockPostTime(stock.getLastTxnTime());
        stockUpdate.setOutputStockPostMessage("分切扫码确认自动入中间边库");
        hcSlittingSliceRecordMapper.updateById(stockUpdate);
        record.setOutputStockId(stock.getId());
        record.setOutputStockPostStatus(STOCK_POST_STATUS_POSTED);
        record.setOutputStockPostTime(stock.getLastTxnTime());
        record.setOutputStockPostMessage(stockUpdate.getOutputStockPostMessage());
    }

    @Override
    public PageResult<HcPressSlotFormRecordRespVO> getPressSlotFormRecordPage(HcPressSlotFormRecordPageReqVO reqVO) {
        List<HcPressSlotFormRecordRespVO> rows = new ArrayList<>();
        Map<Long, HcPlanOrderDO> planCache = new HashMap<>();
        Map<Long, HcPlanOrderOperationDO> operationCache = new HashMap<>();

        appendPressSlotStationFormRows(rows, reqVO, planCache, operationCache);
        appendPressSlotChangeoverFormRows(rows, operationCache);
        appendPressSlotReportFormRows(rows, operationCache);
        appendPressSlotIntermediateFormRows(rows, operationCache);

        List<HcPressSlotFormRecordRespVO> filtered = rows.stream()
                .filter(row -> matchPressSlotFormRecord(row, reqVO))
                .collect(Collectors.toCollection(ArrayList::new));
        Comparator<LocalDateTime> dateTimeComparator = Comparator.nullsLast(Comparator.naturalOrder());
        filtered.sort((left, right) -> {
            int timeCompare = dateTimeComparator.compare(right.getCreateTime(), left.getCreateTime());
            if (timeCompare != 0) {
                return timeCompare;
            }
            long rightId = right.getSourceId() == null ? 0L : right.getSourceId();
            long leftId = left.getSourceId() == null ? 0L : left.getSourceId();
            return Long.compare(rightId, leftId);
        });

        int pageNo = Math.max(reqVO.getPageNo() == null ? 1 : reqVO.getPageNo(), 1);
        int pageSize = Math.max(reqVO.getPageSize() == null ? 10 : reqVO.getPageSize(), 1);
        int fromIndex = Math.min((pageNo - 1) * pageSize, filtered.size());
        int toIndex = Math.min(fromIndex + pageSize, filtered.size());
        return new PageResult<>(filtered.subList(fromIndex, toIndex), (long) filtered.size());
    }

    private void appendPressSlotStationFormRows(List<HcPressSlotFormRecordRespVO> rows,
                                                HcPressSlotFormRecordPageReqVO reqVO,
                                                Map<Long, HcPlanOrderDO> planCache,
                                                Map<Long, HcPlanOrderOperationDO> operationCache) {
        List<HcStationFormDO> forms = hcStationFormMapper.selectEnabledByProcess(PROCESS_CODE_PRESS_SLOT)
                .stream()
                .filter(form -> !PRESS_SLOT_PROCESS_CHECK_FORM_CODE.equalsIgnoreCase(StrUtil.trimToEmpty(form.getFormCode())))
                .filter(form -> !"IN_PROCESS".equalsIgnoreCase(StrUtil.trimToEmpty(form.getTriggerTimingCode())))
                .toList();
        if (CollUtil.isEmpty(forms)) {
            return;
        }
        Set<Long> formIds = forms.stream().map(HcStationFormDO::getId).filter(Objects::nonNull).collect(Collectors.toSet());
        Set<String> formCodes = forms.stream().map(HcStationFormDO::getFormCode).filter(StrUtil::isNotBlank).collect(Collectors.toSet());
        LambdaQueryWrapperX<HcStationRecordDO> query = new LambdaQueryWrapperX<HcStationRecordDO>()
                .eq(HcStationRecordDO::getDeleted, false)
                .orderByDesc(HcStationRecordDO::getCreateTime)
                .orderByDesc(HcStationRecordDO::getId);
        if (CollUtil.isNotEmpty(formIds) && CollUtil.isNotEmpty(formCodes)) {
            query.and(wrapper -> wrapper.in(HcStationRecordDO::getFormId, formIds)
                    .or().in(HcStationRecordDO::getFormCode, formCodes));
        } else if (CollUtil.isNotEmpty(formIds)) {
            query.in(HcStationRecordDO::getFormId, formIds);
        } else if (CollUtil.isNotEmpty(formCodes)) {
            query.in(HcStationRecordDO::getFormCode, formCodes);
        }
        List<HcStationRecordDO> records = hcStationRecordMapper.selectList(query);
        if (CollUtil.isEmpty(records)) {
            return;
        }
        Map<Long, List<HcStationRecordItemDO>> itemMap = hcStationRecordItemMapper.selectByRecordIds(records.stream()
                        .map(HcStationRecordDO::getId)
                        .filter(Objects::nonNull)
                        .toList())
                .stream()
                .collect(Collectors.groupingBy(HcStationRecordItemDO::getRecordId, LinkedHashMap::new, Collectors.toList()));
        for (HcStationRecordDO record : records) {
            HcPlanOrderDO planOrder = getCachedPlanOrder(planCache, record.getPlanId());
            HcPlanOrderOperationDO operation = getCachedOperation(operationCache, record.getPlanOperationId());
            Map<String, Object> header = parseRoughExtraMap(record.getHeaderDataJson());
            HcPressSlotFormRecordRespVO row = new HcPressSlotFormRecordRespVO();
            row.setId("STATION-" + record.getId());
            row.setSourceType("STATION_RECORD");
            row.setSourceId(record.getId());
            row.setFormName(stripPressSlotDisplayName(firstNotBlank(record.getFormName(), readPressSlotText(header, "formName"))));
            row.setPlanNo(firstNotBlank(record.getPlanNo(), planOrder == null ? null : planOrder.getPlanNo()));
            row.setPressSlotSliceNo(firstNotBlank(readPressSlotText(header, "pressSlotSliceNo"),
                    readPressSlotText(header, "productionBatchNo"), readPressSlotText(header, "sliceBatchNo"),
                    readPressSlotText(header, "batchNo")));
            row.setModelCode(firstNotBlank(readPressSlotText(header, "modelCode"),
                    planOrder == null ? null : planOrder.getModelCode(),
                    planOrder == null ? null : planOrder.getModelName()));
            row.setType("STATION_RECORD");
            row.setTypeName(resolvePressSlotStationTypeName(record));
            row.setEquipmentId(firstNotNull(record.getEquipmentId(), operation == null ? null : operation.getEquipmentId()));
            row.setEquipmentCode(firstNotBlank(record.getEquipmentCode(), operation == null ? null : operation.getEquipmentCode()));
            row.setEquipmentName(firstNotBlank(record.getEquipmentName(), operation == null ? null : operation.getEquipmentName()));
            row.setRecordDate(firstNotNullDate(record.getRecordDate(),
                    record.getRecordTime() == null ? null : record.getRecordTime().toLocalDate(),
                    record.getCreateTime() == null ? null : record.getCreateTime().toLocalDate()));
            row.setStatus(firstNotBlank(record.getDocStatus(), record.getResultStatus(), record.getInspectionResult()));
            row.setStatusName(resolvePressSlotFormStatusName(row.getStatus()));
            row.setFillUserName(record.getRecordUserName());
            row.setConfirmUserName(record.getConfirmUserName());
            row.setFillTime(record.getRecordTime());
            row.setConfirmTime(record.getConfirmTime());
            row.setCreateTime(record.getCreateTime());
            Map<String, Object> payload = new LinkedHashMap<>();
            payload.put("stationRecord", record);
            payload.put("stationItems", itemMap.getOrDefault(record.getId(), Collections.emptyList()));
            payload.put("header", header);
            row.setPayload(payload);
            rows.add(row);
        }
    }

