    private void appendPressSlotReportFormRows(List<HcPressSlotFormRecordRespVO> rows,
                                               Map<Long, HcPlanOrderOperationDO> operationCache) {
        List<HcProcessFormRecordDO> records = hcProcessFormRecordMapper.selectList(new LambdaQueryWrapperX<HcProcessFormRecordDO>()
                .eq(HcProcessFormRecordDO::getProcessCode, PROCESS_CODE_PRESS_SLOT)
                .in(HcProcessFormRecordDO::getFormType, List.of(PRESS_SLOT_PROCESS_PARAM_FORM_TYPE,
                        PRESS_SLOT_PRODUCTION_CHECK_FORM_TYPE, PRESS_SLOT_INTERMEDIATE_FORM_TYPE))
                .orderByDesc(HcProcessFormRecordDO::getRecordDate)
                .orderByDesc(HcProcessFormRecordDO::getId));
        for (HcProcessFormRecordDO record : records) {
            HcPlanOrderOperationDO operation = getCachedOperation(operationCache, record.getPlanOperationId());
            if (PRESS_SLOT_INTERMEDIATE_FORM_TYPE.equalsIgnoreCase(record.getFormType())) {
                if (isPressSlotRuntimeDevProcessForm(record)) {
                    rows.add(buildPressSlotRuntimeIntermediateFormRow(record, operation));
                }
                continue;
            }
            HcPressSlotProcessParamRespVO detail = buildPressSlotProcessParamResp(record);
            boolean productionCheck = PRESS_SLOT_PRODUCTION_CHECK_FORM_TYPE.equalsIgnoreCase(record.getFormType());
            HcPressSlotFormRecordRespVO row = new HcPressSlotFormRecordRespVO();
            row.setId((productionCheck ? "PRODUCTION-CHECK-FORM-" : "PROCESS-PARAM-FORM-") + record.getId());
            row.setSourceType(productionCheck ? PRESS_SLOT_PRODUCTION_CHECK_FORM_TYPE : PRESS_SLOT_PROCESS_PARAM_FORM_TYPE);
            row.setSourceId(record.getId());
            row.setFormName(firstNotBlank(record.getTemplateName(), productionCheck ? "压槽生产点检表" : "CMP压槽工艺参数表"));
            row.setPlanNo(record.getPlanNo());
            List<String> processParamSliceNos = detail.getItems().stream()
                    .map(HcPressSlotProcessParamRespVO.Item::getProductionBatchNo)
                    .filter(StrUtil::isNotBlank)
                    .toList();
            row.setPressSlotSliceNo(productionCheck
                    ? firstNotBlank(detail.getFirstInspectionSliceNo(), detail.getProductionBatchNo())
                    : buildPressSlotSliceRangeText(processParamSliceNos));
            row.setModelCode(record.getModelCode());
            row.setType(productionCheck ? PRESS_SLOT_PRODUCTION_CHECK_FORM_TYPE : PRESS_SLOT_PROCESS_PARAM_FORM_TYPE);
            row.setTypeName(productionCheck ? "生产点检" : "工艺参数");
            row.setEquipmentId(firstNotNull(record.getEquipmentId(), operation == null ? null : operation.getEquipmentId()));
            row.setEquipmentCode(firstNotBlank(record.getEquipmentCode(), operation == null ? null : operation.getEquipmentCode()));
            row.setEquipmentName(firstNotBlank(record.getEquipmentName(), operation == null ? null : operation.getEquipmentName()));
            row.setRecordDate(record.getRecordDate());
            row.setStatus(record.getRecordStatus());
            row.setStatusName(resolvePressSlotFormStatusName(record.getRecordStatus()));
            row.setFillUserName(record.getFillUserName());
            row.setConfirmUserName(record.getConfirmUserName());
            row.setFillTime(record.getFillTime());
            row.setConfirmTime(record.getConfirmTime());
            row.setCreateTime(record.getCreateTime());
            Map<String, Object> payload = new LinkedHashMap<>();
            payload.put("processParam", detail);
            payload.put("processParamItems", detail.getItems());
            payload.put("record", record);
            row.setPayload(payload);
            rows.add(row);
        }
    }

    private boolean isPressSlotRuntimeDevProcessForm(HcProcessFormRecordDO record) {
        if (record == null || !PRESS_SLOT_INTERMEDIATE_FORM_TYPE.equalsIgnoreCase(record.getFormType())) {
            return false;
        }
        if (StrUtil.endWithIgnoreCase(StrUtil.trimToEmpty(record.getTemplateCode()), "_DEV")) {
            return true;
        }
        Map<String, Object> context = parseRoughExtraMap(record.getContextJson());
        return "station-form-dev-runtime".equalsIgnoreCase(toStringValue(context.get("source")));
    }

    private HcPressSlotFormRecordRespVO buildPressSlotRuntimeIntermediateFormRow(HcProcessFormRecordDO record,
                                                                                 HcPlanOrderOperationDO operation) {
        Map<String, Object> header = parseRoughExtraMap(record.getHeaderDataJson());
        Map<String, Object> context = parseRoughExtraMap(record.getContextJson());
        List<HcProcessFormRecordItemDO> items = hcProcessFormRecordItemMapper.selectListByRecordId(record.getId());
        HcPressSlotFormRecordRespVO row = new HcPressSlotFormRecordRespVO();
        row.setId("RUNTIME-INTERMEDIATE-FORM-" + record.getId());
        row.setSourceType(PRESS_SLOT_INTERMEDIATE_FORM_TYPE);
        row.setSourceId(record.getId());
        row.setFormName(firstNotBlank(record.getTemplateName(), toStringValue(header.get("formName")), "压槽中间品记录表"));
        row.setPlanNo(firstNotBlank(record.getPlanNo(), toStringValue(header.get("planNo"))));
        row.setPressSlotSliceNo(firstNotBlank(toStringValue(header.get("pressSlotSliceNo")),
                toStringValue(header.get("sliceBatchNo")), toStringValue(header.get("batchNo")), record.getBatchNo()));
        row.setModelCode(firstNotBlank(record.getModelCode(), toStringValue(header.get("modelCode"))));
        row.setType(PRESS_SLOT_INTERMEDIATE_FORM_TYPE);
        row.setTypeName("中间品记录");
        row.setEquipmentId(firstNotNull(record.getEquipmentId(), operation == null ? null : operation.getEquipmentId()));
        row.setEquipmentCode(firstNotBlank(record.getEquipmentCode(), operation == null ? null : operation.getEquipmentCode(),
                toStringValue(header.get("equipmentCode"))));
        row.setEquipmentName(firstNotBlank(record.getEquipmentName(), operation == null ? null : operation.getEquipmentName(),
                toStringValue(header.get("equipmentName"))));
        row.setRecordDate(record.getRecordDate());
        row.setStatus(record.getRecordStatus());
        row.setStatusName(resolvePressSlotFormStatusName(record.getRecordStatus()));
        row.setFillUserName(record.getFillUserName());
        row.setConfirmUserName(record.getConfirmUserName());
        row.setFillTime(record.getFillTime());
        row.setConfirmTime(record.getConfirmTime());
        row.setCreateTime(record.getCreateTime());
        Map<String, Object> payload = new LinkedHashMap<>();
        payload.put("runtimeRecord", record);
        payload.put("runtimeItems", items);
        payload.put("runtimeHeader", header);
        payload.put("runtimeContext", context);
        payload.put("runtimeSchema", context.get("runtimeSchema"));
        payload.put("header", header);
        row.setPayload(payload);
        return row;
    }
    private String buildPressSlotSliceRangeText(List<String> sliceNos) {
        if (sliceNos == null || sliceNos.isEmpty()) {
            return "";
        }
        String first = StrUtil.trimToEmpty(sliceNos.get(0));
        String last = StrUtil.trimToEmpty(sliceNos.get(sliceNos.size() - 1));
        if (sliceNos.size() == 1 || StrUtil.equals(first, last)) {
            return first;
        }
        return first + "~" + last;
    }

