    private void appendPressSlotIntermediateFormRows(List<HcPressSlotFormRecordRespVO> rows,
                                                     Map<Long, HcPlanOrderOperationDO> operationCache) {
        List<HcPressSlotIntermediateRecordDO> records = hcPressSlotIntermediateRecordMapper.selectList(
                new LambdaQueryWrapperX<HcPressSlotIntermediateRecordDO>()
                        .eq(HcPressSlotIntermediateRecordDO::getDeleted, false)
                        .orderByDesc(HcPressSlotIntermediateRecordDO::getCreateTime)
                        .orderByDesc(HcPressSlotIntermediateRecordDO::getId));
        for (HcPressSlotIntermediateRecordDO record : records) {
            HcPlanOrderOperationDO operation = getCachedOperation(operationCache, record.getPlanOperationId());
            HcPressSlotIntermediateRespVO detail = buildPressSlotIntermediateResp(record);
            detail.setDetails(hcPressSlotIntermediateDetailMapper.selectListByRecordId(record.getId()).stream()
                    .map(this::buildPressSlotIntermediateDetailResp)
                    .toList());
            HcPressSlotFormRecordRespVO row = new HcPressSlotFormRecordRespVO();
            row.setId("INTERMEDIATE-" + record.getId());
            row.setSourceType("INTERMEDIATE_RECORD");
            row.setSourceId(record.getId());
            row.setFormName("压槽中间品记录表");
            row.setPlanNo(record.getPlanNo());
            row.setPressSlotSliceNo(buildPressSlotIntermediateSliceText(detail));
            row.setModelCode(record.getModelCode());
            row.setType("INTERMEDIATE_RECORD");
            row.setTypeName("中间品记录");
            row.setEquipmentId(operation == null ? null : operation.getEquipmentId());
            row.setEquipmentCode(operation == null ? null : operation.getEquipmentCode());
            row.setEquipmentName(operation == null ? null : operation.getEquipmentName());
            row.setRecordDate(record.getRecordDate());
            row.setStatus(record.getRecordStatus());
            row.setStatusName(resolvePressSlotFormStatusName(record.getRecordStatus()));
            row.setFillUserName(record.getRecorderName());
            row.setConfirmUserName(record.getConfirmerName());
            row.setFillTime(firstNotNullDateTime(record.getUpdateTime(), record.getCreateTime()));
            row.setConfirmTime("CONFIRMED".equalsIgnoreCase(record.getRecordStatus()) ? record.getUpdateTime() : null);
            row.setCreateTime(record.getCreateTime());
            Map<String, Object> payload = new LinkedHashMap<>();
            payload.put("intermediate", detail);
            row.setPayload(payload);
            rows.add(row);
        }
    }

    private boolean matchPressSlotFormRecord(HcPressSlotFormRecordRespVO row, HcPressSlotFormRecordPageReqVO reqVO) {
        return containsPressSlotFilter(row.getFormName(), reqVO.getFormName())
                && containsPressSlotFilter(row.getPlanNo(), reqVO.getPlanNo())
                && containsPressSlotFilter(row.getPressSlotSliceNo(), reqVO.getPressSlotSliceNo())
                && containsPressSlotFilter(row.getModelCode(), reqVO.getModelCode())
                && (StrUtil.isBlank(reqVO.getType())
                || containsPressSlotFilter(row.getType(), reqVO.getType())
                || containsPressSlotFilter(row.getTypeName(), reqVO.getType()))
                && (StrUtil.isBlank(reqVO.getStatus())
                || containsPressSlotFilter(row.getStatus(), reqVO.getStatus())
                || containsPressSlotFilter(row.getStatusName(), reqVO.getStatus()));
    }

    private boolean containsPressSlotFilter(String value, String keyword) {
        if (StrUtil.isBlank(keyword)) {
            return true;
        }
        return StrUtil.containsIgnoreCase(StrUtil.nullToEmpty(value), StrUtil.trim(keyword));
    }

    private String readPressSlotText(Map<String, Object> map, String key) {
        if (map == null || StrUtil.isBlank(key)) {
            return null;
        }
        return toStringValue(map.get(key));
    }

    private HcPlanOrderDO getCachedPlanOrder(Map<Long, HcPlanOrderDO> cache, Long planId) {
        if (planId == null) {
            return null;
        }
        if (!cache.containsKey(planId)) {
            cache.put(planId, hcPlanOrderMapper.selectById(planId));
        }
        return cache.get(planId);
    }

    private HcPlanOrderOperationDO getCachedOperation(Map<Long, HcPlanOrderOperationDO> cache, Long planOperationId) {
        if (planOperationId == null) {
            return null;
        }
        if (!cache.containsKey(planOperationId)) {
            cache.put(planOperationId, hcPlanOrderOperationMapper.selectById(planOperationId));
        }
        return cache.get(planOperationId);
    }

    private String resolvePressSlotStationTypeName(HcStationRecordDO record) {
        String text = StrUtil.trimToEmpty(firstNotBlank(record.getFormName(), record.getFormCode(), record.getTriggerTimingName()));
        if (StrUtil.contains(text, "清洁")) {
            return "点检清洁";
        }
        if (StrUtil.contains(text, "开机")) {
            return "开机点检";
        }
        if (StrUtil.contains(text, "首检")) {
            return "首检";
        }
        return firstNotBlank(record.getTriggerTimingName(), "点检清洁");
    }

    private String resolvePressSlotFormStatusName(String status) {
        String normalized = StrUtil.trimToEmpty(status).toUpperCase();
        return switch (normalized) {
            case "CONFIRMED" -> "已确认";
            case "SUBMITTED" -> "已填写";
            case "RECORDED", "FINISHED", "DONE" -> "已记录";
            case "DRAFT" -> "草稿";
            case "PENDING", "WAITING_QA" -> "待处理";
            case "QUALIFIED" -> "已检";
            case "ABNORMAL", "NG", "FAILED", "REJECTED" -> "异常";
            case "OK" -> "OK";
            default -> StrUtil.blankToDefault(status, "-");
        };
    }

    private String stripPressSlotDisplayName(String formName) {
        String value = StrUtil.trimToEmpty(formName);
        if (StrUtil.isBlank(value)) {
            return value;
        }
        return value.replaceAll("^(CMP软垫|CMP白垫|CMP黑垫|CMP抛光垫)[（(][^）)]*[）)]", "");
    }

    private String buildPressSlotIntermediateSliceText(HcPressSlotIntermediateRespVO detail) {
        List<String> sliceNos = new ArrayList<>();
        sliceNos.add(detail.getFirstSampleSliceNo());
        sliceNos.add(detail.getFrontSliceNo());
        sliceNos.add(detail.getMiddleSliceNo());
        sliceNos.add(detail.getEndSliceNo());
        String joined = sliceNos.stream()
                .filter(StrUtil::isNotBlank)
                .distinct()
                .collect(Collectors.joining(" / "));
        return firstNotBlank(joined, detail.getBatchNo());
    }

