    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcWetFaiRespVO applyPressSlotFai(HcWetFaiApplyReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        HcPlanOrderOperationDO operation = validatePressSlotOperation(planOrder, reqVO.getPlanOperationId());
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("请先完成压槽开工并锁定设备");
        }
        HcProcessReportDO latestStartReport = getLatestStartReport(operation.getId(), SOURCE_MENU_CODE_PRESS_SLOT);
        if (latestStartReport == null) {
            throw invalidParamException("当前压槽工序未找到开工记录，不能提交首检申请");
        }
        if (latestStartReport.getEquipmentId() == null && StrUtil.isBlank(latestStartReport.getEquipmentCode())) {
            throw invalidParamException("请先选择并锁定压槽设备");
        }
        if (isPressSlotProcessCheckFai(reqVO)) {
            return applyPressSlotProcessCheckFai(reqVO, planOrder, operation, latestStartReport);
        }
        if (isPressSlotAbnormalReleaseFai(reqVO)) {
            throw invalidParamException("压槽风险复测已停用，NG后请使用新片重新首检");
        }
        String scannedSliceNo = StrUtil.trimToEmpty(reqVO.getProductBatchNo());
        HcSlittingSliceRecordDO faiSourceSlice = StrUtil.isBlank(scannedSliceNo)
                ? null
                : hcSlittingSliceRecordMapper.selectConfirmedBySerialNo(scannedSliceNo);
        if (faiSourceSlice == null || Boolean.TRUE.equals(faiSourceSlice.getDeleted())) {
            throw invalidParamException("请先扫码压槽批号，首检申请必须带入分切片号对应的批号");
        }
        if (!Objects.equals(faiSourceSlice.getPlanId(), planOrder.getId())) {
            throw invalidParamException("首检批号不属于当前压槽计划，请重新扫码");
        }
        if (!"CONFIRMED".equalsIgnoreCase(StrUtil.blankToDefault(faiSourceSlice.getScanStatus(), ""))) {
            throw invalidParamException("首检批号尚未完成分切扫码确认，不能提交压槽首检");
        }

        String standardMatchMode = FAI_STANDARD_MATCH_PRODUCT_MODEL_PROCESS;
        String motherMaterialCode = firstNotBlank(latestStartReport.getMotherMaterialCode(),
                operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode(),
                latestStartReport.getMaterialCode(), planOrder.getMaterialCode());
        String operationCode = firstNotBlank(latestStartReport.getOperationCode(), operation.getOpCode());
        String operationName = firstNotBlank(latestStartReport.getOperationName(), operation.getOpName());
        String productModel = resolveFaiProductModel(latestStartReport, operation, planOrder);
        if (StrUtil.isBlank(productModel)) {
            throw invalidParamException("当前压槽任务缺少产品型号，无法按产品型号与工段匹配 FAI 检验标准");
        }
        String productBatchNo = firstNotBlank(faiSourceSlice.getSliceSerialNo(), scannedSliceNo);
        if (StrUtil.isBlank(productBatchNo)) {
            throw invalidParamException("请先扫码压槽批号，扫码批号将写入首件检验的产品批次");
        }
        validatePressSlotFirstInspectionSampleUnused(productBatchNo);
        String scopeMotherBatchNo = resolvePressSlotFaiMotherBatchNo(planOrder, operation, latestStartReport,
                firstNotBlank(productBatchNo, faiSourceSlice.getSourceProductionBatchNo(), faiSourceSlice.getSourceBatchNo()));
        if (StrUtil.isBlank(operationCode) && StrUtil.isBlank(operationName)) {
            throw invalidParamException("当前压槽任务缺少工段信息，无法按产品型号与工段匹配 FAI 检验标准");
        }

        String taskNo = buildPressSlotTaskNo(planOrder, operation);
        List<QmsFaiOrderDO> scopeFaiOrders = listPressSlotFirstInspectionOrdersForTaskScope(
                planOrder, operation, scopeMotherBatchNo);
        boolean processCheckNgRestart = findPressSlotPendingRestartNg(
                listPressSlotInspectionOrdersForTaskScope(planOrder, operation, scopeMotherBatchNo)) != null;
        if (isPressSlotProcessCheckNgRestartFai(reqVO) && !processCheckNgRestart) {
            throw invalidParamException("当前没有待重新首检的NG，请刷新检验状态后操作");
        }
        boolean requestedAdditionalFirstInspection = isPressSlotAdditionalFirstInspectionFai(reqVO);
        boolean additionalFirstInspection = !processCheckNgRestart
                && (requestedAdditionalFirstInspection
                || scopeFaiOrders.stream().anyMatch(this::isPressSlotFaiSubmitted));
        String triggerReason = processCheckNgRestart ? PRESS_SLOT_FAI_TRIGGER_PROCESS_CHECK_NG_RESTART
                : additionalFirstInspection ? PRESS_SLOT_FAI_TRIGGER_ADDITIONAL_FIRST_INSPECTION
                : FAI_TRIGGER_NEW_ORDER;
        String defaultRemark = processCheckNgRestart ? "压槽过程加检NG后重新首检申请"
                : additionalFirstInspection ? "压槽生产重新送样加检申请"
                : "压槽操作看板首检申请";

        QmsFaiSaveReqVO faiReqVO = new QmsFaiSaveReqVO();
        faiReqVO.setWorkOrderNo(planOrder.getPlanNo());
        faiReqVO.setSourceReportId(latestStartReport.getId());
        faiReqVO.setSourceReportNo(taskNo);
        faiReqVO.setSourceModule(SOURCE_MENU_CODE_PRESS_SLOT);
        faiReqVO.setSourceOperationCode(operationCode);
        faiReqVO.setSourceOperationName(operationName);
        faiReqVO.setPlanOrderId(planOrder.getId());
        faiReqVO.setStandardMatchMode(standardMatchMode);
        faiReqVO.setOperationCode(operationCode);
        faiReqVO.setOperationName(operationName);
        faiReqVO.setMachineId(latestStartReport.getEquipmentId());
        faiReqVO.setMachineCode(firstNotBlank(latestStartReport.getEquipmentCode(), operation.getEquipmentCode()));
        faiReqVO.setMachineName(firstNotBlank(latestStartReport.getEquipmentName(), operation.getEquipmentName()));
        faiReqVO.setMaterialId(firstNotNull(latestStartReport.getMotherMaterialId(), operation.getMotherMaterialId(), planOrder.getMotherMaterialId()));
        faiReqVO.setMaterialCode(motherMaterialCode);
        faiReqVO.setMaterialName(firstNotBlank(latestStartReport.getMotherMaterialName(), operation.getMotherMaterialName(), planOrder.getMotherMaterialName()));
        faiReqVO.setSpecification(planOrder.getSizeName());
        faiReqVO.setProductModel(productModel);
        faiReqVO.setProductBatchNo(productBatchNo);
        faiReqVO.setProcessCategory(PROCESS_CODE_PRESS_SLOT);
        faiReqVO.setSubmissionType(FAI_SUBMISSION_TYPE_MASS_SHIPMENT);
        faiReqVO.setTriggerReason(triggerReason);
        faiReqVO.setStatus(FAI_STATUS_PENDING);
        faiReqVO.setJudgment(FAI_JUDGMENT_PENDING);
        LocalDateTime submissionTime = LocalDateTime.now();
        String submitterName = firstNotBlank(reqVO.getSubmitterName(), SecurityFrameworkUtils.getLoginUserNickname(),
                latestStartReport.getRecorderName(), "系统");
        faiReqVO.setSubmissionTime(submissionTime);
        faiReqVO.setSubmitterName(submitterName);
        faiReqVO.setRemark(firstNotBlank(reqVO.getRemark(), defaultRemark));
        HcPressSlotFirstInspectionSampleClaimDO sampleClaim = reservePressSlotFirstInspectionSample(
                planOrder, operation, faiSourceSlice, productBatchNo);
        Long faiId = qmsFaiService.createFaiForInspectionPush(faiReqVO);
        sampleClaim.setFirstFaiId(faiId);
        hcPressSlotFirstInspectionSampleClaimMapper.updateById(sampleClaim);
        QmsFaiOrderDO createdFai = qmsFaiOrderMapper.selectById(faiId);
        syncPressSlotReportFaiSummary(latestStartReport, createdFai);
        scopeFaiOrders = listPressSlotFirstInspectionOrdersForTaskScope(planOrder, operation, scopeMotherBatchNo);
        HcWetFaiRespVO respVO = buildPressSlotFaiResp(createdFai, latestStartReport, scopeFaiOrders,
                scopeMotherBatchNo, resolvePressSlotFaiInspectionDate(createdFai));
        respVO.setOverallQualified(scopeFaiOrders.stream().anyMatch(this::isFaiReleased));
        boolean restartRequired = findPressSlotPendingRestartNg(
                listPressSlotInspectionOrdersForTaskScope(planOrder, operation, scopeMotherBatchNo)) != null;
        respVO.setRestartRequired(restartRequired);
        if (restartRequired) {
            respVO.setAllowReportSubmit(false);
        }
        return respVO;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void withdrawPressSlotFai(HcPressSlotFaiWithdrawReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validatePressSlotOperation(planOrder, reqVO.getPlanOperationId());
        QmsFaiOrderDO faiOrder = qmsFaiOrderMapper.selectById(reqVO.getFaiId());
        validatePressSlotFaiWithdrawable(faiOrder, planOrder, operation);

        String withdrawReason = StrUtil.trim(reqVO.getWithdrawReason());
        Long loginUserId = SecurityFrameworkUtils.getLoginUserId();
        String withdrawer = loginUserId == null ? "系统" : String.valueOf(loginUserId);
        boolean cancelled = qmsFaiOrderMapper.cancelUntouchedPendingById(
                faiOrder.getId(), withdrawReason, withdrawer);
        if (!cancelled) {
            throw invalidParamException("送检单状态已变化，无法撤回；请刷新后确认");
        }
        QmsFaiOrderDO cancelledFaiOrder = qmsFaiOrderMapper.selectById(faiOrder.getId());
        if (cancelledFaiOrder == null) {
            throw invalidParamException("送检单不存在或已删除，无法撤回");
        }

        if (isPressSlotProcessCheckFaiOrder(faiOrder)) {
            HcPressSlotReportDO sourceReport = hcPressSlotReportMapper.selectById(faiOrder.getSourceReportId());
            syncPressSlotProcessCheckFaiWithdrawn(sourceReport, cancelledFaiOrder, withdrawReason);
            return;
        }

        // 首检撤回同时释放样片占用；过程加检不走样片占用，且不回滚已确认压槽报工。
        hcPressSlotFirstInspectionSampleClaimMapper.selectListByFirstFaiId(faiOrder.getId())
                .forEach(sampleClaim -> hcPressSlotFirstInspectionSampleClaimMapper.deleteById(sampleClaim.getId()));
        HcProcessReportDO startReport = hcProcessReportMapper.selectById(faiOrder.getSourceReportId());
        syncPressSlotReportFaiSummary(startReport, cancelledFaiOrder);
    }

    private void validatePressSlotFaiWithdrawable(QmsFaiOrderDO faiOrder,
                                                   HcPlanOrderDO planOrder,
                                                   HcPlanOrderOperationDO operation) {
        if (faiOrder == null || Boolean.TRUE.equals(faiOrder.getDeleted())) {
            throw invalidParamException("送检单不存在或已删除，无法撤回");
        }
        if (!SOURCE_MENU_CODE_PRESS_SLOT.equalsIgnoreCase(StrUtil.trimToEmpty(faiOrder.getSourceModule()))
                || !PROCESS_CODE_PRESS_SLOT.equalsIgnoreCase(StrUtil.trimToEmpty(faiOrder.getProcessCategory()))
                || !Objects.equals(planOrder.getId(), faiOrder.getPlanOrderId())) {
            throw invalidParamException("只能撤回当前压槽计划的首检或过程加检送检单");
        }
        if (isPressSlotAbnormalReleaseFaiOrder(faiOrder)) {
            throw invalidParamException("异常放行送检单不支持从首检或过程加检列表撤回");
        }
        if (!FAI_STATUS_PENDING.equalsIgnoreCase(StrUtil.trimToEmpty(faiOrder.getStatus()))
                || faiOrder.getOperatorTime() != null
                || faiOrder.getQaTime() != null
                || faiOrder.getLastSaveTime() != null
                || faiOrder.getLastScanTime() != null) {
            throw invalidParamException("仅品质未扫码、未录入、未提交的待检送检单允许撤回");
        }
        if (isPressSlotProcessCheckFaiOrder(faiOrder)) {
            HcPressSlotReportDO sourceReport = hcPressSlotReportMapper.selectById(faiOrder.getSourceReportId());
            if (sourceReport == null
                    || !Objects.equals(sourceReport.getPlanId(), planOrder.getId())
                    || !Objects.equals(sourceReport.getPlanOperationId(), operation.getId())) {
                throw invalidParamException("过程加检送检单来源报工不属于当前压槽任务，无法撤回");
            }
            return;
        }
        if (!Objects.equals(buildPressSlotTaskNo(planOrder, operation), faiOrder.getSourceReportNo())) {
            throw invalidParamException("该送检单不是当前压槽首检单，无法撤回");
        }
        HcProcessReportDO sourceStartReport = hcProcessReportMapper.selectById(faiOrder.getSourceReportId());
        if (sourceStartReport == null
                || !Objects.equals(sourceStartReport.getPlanId(), planOrder.getId())
                || !Objects.equals(sourceStartReport.getPlanOperationId(), operation.getId())) {
            throw invalidParamException("首检送检单来源开工记录不属于当前压槽任务，无法撤回");
        }
    }

    private void syncPressSlotProcessCheckFaiWithdrawn(HcPressSlotReportDO sourceReport,
                                                       QmsFaiOrderDO faiOrder,
                                                       String withdrawReason) {
        if (sourceReport == null || sourceReport.getId() == null || faiOrder == null) {
            return;
        }
        Map<String, Object> extra = new LinkedHashMap<>(parseRoughExtraMap(sourceReport.getExtraJson()));
        extra.put("processCheckFaiId", faiOrder.getId());
        extra.put("processCheckFaiNo", faiOrder.getFaiNo());
        extra.put("processCheckFaiStatus", faiOrder.getStatus());
        extra.put("processCheckFaiJudgment", faiOrder.getJudgment());
        extra.put("processCheckFaiWithdrawReason", withdrawReason);
        extra.put("processCheckFaiWithdrawTime", LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));
        HcPressSlotReportDO updateReport = new HcPressSlotReportDO();
        updateReport.setId(sourceReport.getId());
        updateReport.setExtraJson(JsonUtils.toJsonString(extra));
        hcPressSlotReportMapper.updateById(updateReport);
    }

    /**
     * 压槽首检样片属于一次性送检样本；仅撤回尚未进入品质处理的待检单时才会释放。
     */
    private void validatePressSlotFirstInspectionSampleUnused(String productBatchNo) {
        QmsFaiOrderDO existedFai = qmsFaiOrderMapper.selectAnyPressSlotFirstInspectionByProductBatchNo(
                SOURCE_MENU_CODE_PRESS_SLOT, productBatchNo);
        if (existedFai == null) {
            return;
        }
        throw invalidParamException("分切片号 " + productBatchNo
                + " 已作为压槽首检样片送检（首检单号："
                + StrUtil.blankToDefault(existedFai.getFaiNo(), "-")
                + "），重新首检请扫描未送检的新片号");
    }

    /**
     * 通过数据库唯一键占用样片，防止同一片在并发请求中被重复送检。
     */
    private HcPressSlotFirstInspectionSampleClaimDO reservePressSlotFirstInspectionSample(
            HcPlanOrderDO planOrder, HcPlanOrderOperationDO operation,
            HcSlittingSliceRecordDO sourceSlice, String productBatchNo) {
        HcPressSlotFirstInspectionSampleClaimDO claim = HcPressSlotFirstInspectionSampleClaimDO.builder()
                .planId(planOrder.getId())
                .planOperationId(operation.getId())
                .sourceSlittingSliceId(sourceSlice.getId())
                .sampleBatchNo(productBatchNo)
                .tenantId(planOrder.getTenantId())
                .build();
        try {
            hcPressSlotFirstInspectionSampleClaimMapper.insert(claim);
            return claim;
        } catch (DuplicateKeyException exception) {
            throw invalidParamException("分切片号 " + productBatchNo + " 正在或已经作为压槽首检样片送检，请更换未送检的新片号");
        }
    }

    @Override
    public HcPressSlotScanGateRespVO validatePressSlotFaiScan(Long planId, Long planOperationId, String motherBatchNo,
                                                              String productionBatchNo, String reportType) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        HcPlanOrderOperationDO operation = validatePressSlotOperation(planOrder, planOperationId);
        Map<String, Object> extra = new LinkedHashMap<>();
        if (INSPECTION_SCENE_PROCESS_CHECK.equalsIgnoreCase(StrUtil.trimToEmpty(reportType))) {
            extra.put("inspectionScene", INSPECTION_SCENE_PROCESS_CHECK);
            extra.put("inspectionSampleCategory", PRESS_SLOT_INSPECTION_SAMPLE_CATEGORY_PROCESS_CHECK);
            extra.put("reportType", INSPECTION_SCENE_PROCESS_CHECK);
        }
        return validatePressSlotFaiSubmitted(planOrder, operation, firstNotBlank(motherBatchNo, productionBatchNo),
                productionBatchNo, extra.isEmpty() ? null : JsonUtils.toJsonString(extra), true);
    }

    private boolean isPressSlotProcessCheckFai(HcWetFaiApplyReqVO reqVO) {
        return reqVO != null
                && INSPECTION_SCENE_PROCESS_CHECK.equalsIgnoreCase(StrUtil.trimToEmpty(reqVO.getInspectionScene()));
    }

    private boolean isPressSlotProcessCheckNgRestartFai(HcWetFaiApplyReqVO reqVO) {
        return reqVO != null && PRESS_SLOT_FAI_TRIGGER_PROCESS_CHECK_NG_RESTART
                .equalsIgnoreCase(StrUtil.trimToEmpty(reqVO.getTriggerReason()));
    }

    private boolean isPressSlotAdditionalFirstInspectionFai(HcWetFaiApplyReqVO reqVO) {
        return reqVO != null && PRESS_SLOT_FAI_TRIGGER_ADDITIONAL_FIRST_INSPECTION
                .equalsIgnoreCase(StrUtil.trimToEmpty(reqVO.getTriggerReason()));
    }

    private HcWetFaiRespVO applyPressSlotProcessCheckFai(HcWetFaiApplyReqVO reqVO,
                                                         HcPlanOrderDO planOrder,
                                                         HcPlanOrderOperationDO operation,
                                                         HcProcessReportDO latestStartReport) {
        String scopeMotherBatchNo = resolvePressSlotFaiMotherBatchNo(planOrder, operation,
                latestStartReport, reqVO.getProductBatchNo());
        if (findPressSlotPendingRestartNg(listPressSlotInspectionOrdersForTaskScope(
                planOrder, operation, scopeMotherBatchNo)) != null) {
            throw invalidParamException("当前检验已返回NG，请使用新片重新首检，不能以过程加检替代");
        }
        HcPressSlotReportDO sourceReport = resolvePressSlotProcessCheckSourceReport(reqVO, planOrder, operation, latestStartReport);
        String operationCode = firstNotBlank(sourceReport.getOperationCode(), latestStartReport.getOperationCode(), operation.getOpCode());
        String operationName = firstNotBlank(sourceReport.getOperationName(), latestStartReport.getOperationName(), operation.getOpName());
        if (StrUtil.isBlank(operationCode) && StrUtil.isBlank(operationName)) {
            throw invalidParamException("当前压槽任务缺少工段信息，无法按产品型号与工段匹配 FAI 检验标准");
        }
        String productModel = firstNotBlank(sourceReport.getModelCode(), resolveFaiProductModel(latestStartReport, operation, planOrder));
        if (StrUtil.isBlank(productModel)) {
            throw invalidParamException("当前压槽任务缺少产品型号，无法按产品型号与工段匹配 FAI 检验标准");
        }
        String productBatchNo = firstNotBlank(reqVO.getProductBatchNo(), sourceReport.getProductionBatchNo(), sourceReport.getSourceProductionBatchNo());
        if (StrUtil.isBlank(productBatchNo)) {
            throw invalidParamException("过程加检缺少压槽片号，不能生成 FAI 首件检验单");
        }
        String sourceReportNo = buildPressSlotProcessCheckFaiSourceReportNo(planOrder, operation, productBatchNo);
        QmsFaiOrderDO latestFai = qmsFaiOrderMapper.selectLatestBySourceReportNo(sourceReportNo, SOURCE_MENU_CODE_PRESS_SLOT);
        if (latestFai != null && !isPressSlotFaiReapplyAllowed(latestFai)) {
            if (isFaiReleased(latestFai)) {
                throw invalidParamException("过程加检片号 " + productBatchNo + " 已完成检验OK，不能重复提交");
            }
            throw invalidParamException("过程加检片号 " + productBatchNo + " 已有未完成检验单，请先在 FAI 工作台处理后再提交");
        }
        String triggerReason = firstNotBlank(reqVO.getTriggerReason(),
                latestFai != null && isPressSlotFaiReapplyAllowed(latestFai) ? FAI_TRIGGER_REWORK_RECHECK : FAI_TRIGGER_NEW_ORDER);
        if (latestFai != null && isPressSlotFaiReapplyAllowed(latestFai) && !FAI_TRIGGER_REWORK_RECHECK.equals(triggerReason)) {
            triggerReason = FAI_TRIGGER_REWORK_RECHECK;
        }
        String motherBatchNo = firstNotBlank(normalizePressSlotMiddleBatchNo(reqVO.getInspectionScopeBatchNo()),
                resolvePressSlotReportMotherBatchNo(sourceReport));
        String motherMaterialCode = firstNotBlank(sourceReport.getMaterialCode(), latestStartReport.getMotherMaterialCode(),
                operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode(),
                latestStartReport.getMaterialCode(), planOrder.getMaterialCode());

        QmsFaiSaveReqVO faiReqVO = new QmsFaiSaveReqVO();
        faiReqVO.setWorkOrderNo(planOrder.getPlanNo());
        faiReqVO.setSourceReportId(sourceReport.getId());
        faiReqVO.setSourceReportNo(sourceReportNo);
        faiReqVO.setSourceModule(SOURCE_MENU_CODE_PRESS_SLOT);
        faiReqVO.setSourceOperationCode(operationCode);
        faiReqVO.setSourceOperationName(operationName);
        faiReqVO.setPlanOrderId(planOrder.getId());
        faiReqVO.setStandardMatchMode(FAI_STANDARD_MATCH_PRODUCT_MODEL_PROCESS);
        faiReqVO.setOperationCode(operationCode);
        faiReqVO.setOperationName(operationName);
        faiReqVO.setMachineId(latestStartReport.getEquipmentId());
        faiReqVO.setMachineCode(firstNotBlank(latestStartReport.getEquipmentCode(), operation.getEquipmentCode()));
        faiReqVO.setMachineName(firstNotBlank(latestStartReport.getEquipmentName(), operation.getEquipmentName()));
        faiReqVO.setMaterialId(firstNotNull(latestStartReport.getMotherMaterialId(), operation.getMotherMaterialId(),
                planOrder.getMotherMaterialId(), latestStartReport.getMaterialId(), planOrder.getMaterialId()));
        faiReqVO.setMaterialCode(motherMaterialCode);
        faiReqVO.setMaterialName(firstNotBlank(sourceReport.getMaterialName(), latestStartReport.getMotherMaterialName(),
                operation.getMotherMaterialName(), planOrder.getMotherMaterialName(),
                latestStartReport.getMaterialName(), planOrder.getMaterialName()));
        faiReqVO.setSpecification(planOrder.getSizeName());
        faiReqVO.setProductModel(productModel);
        faiReqVO.setProductBatchNo(productBatchNo);
        faiReqVO.setProcessCategory(PROCESS_CODE_PRESS_SLOT);
        faiReqVO.setSubmissionType(FAI_SUBMISSION_TYPE_MASS_SHIPMENT);
        faiReqVO.setTriggerReason(triggerReason);
        faiReqVO.setStatus(FAI_STATUS_PENDING);
        faiReqVO.setJudgment(FAI_JUDGMENT_PENDING);
        faiReqVO.setSubmissionTime(LocalDateTime.now());
        faiReqVO.setSubmitterName(firstNotBlank(reqVO.getSubmitterName(), SecurityFrameworkUtils.getLoginUserNickname(),
                sourceReport.getRecorderName(), latestStartReport.getRecorderName(), "系统"));
        faiReqVO.setRemark(buildPressSlotProcessCheckFaiRemark(reqVO, sourceReport, productBatchNo, motherBatchNo));
        Long faiId = qmsFaiService.createFaiForInspectionPush(faiReqVO);
        QmsFaiOrderDO createdFai = qmsFaiOrderMapper.selectById(faiId);
        storePressSlotProcessCheckFaiInfo(sourceReport, createdFai);
        HcWetFaiRespVO respVO = buildPressSlotProcessCheckFaiResp(createdFai, latestStartReport, planOrder, operation);
        respVO.setInspectionScopeBatchNo(motherBatchNo);
        return respVO;
    }

    private HcPressSlotReportDO resolvePressSlotProcessCheckSourceReport(HcWetFaiApplyReqVO reqVO,
                                                                         HcPlanOrderDO planOrder,
                                                                         HcPlanOrderOperationDO operation,
                                                                         HcProcessReportDO latestStartReport) {
        HcPressSlotReportDO sourceReport = findPressSlotProcessCheckSourceReport(reqVO, operation);
        if (sourceReport == null || Boolean.TRUE.equals(sourceReport.getDeleted())) {
            sourceReport = createPressSlotProcessCheckSourceReport(reqVO, planOrder, operation, latestStartReport);
        }
        if (!Objects.equals(sourceReport.getPlanOperationId(), operation.getId())) {
            throw invalidParamException("过程加检报工记录不属于当前压槽工序");
        }
        String status = StrUtil.blankToDefault(sourceReport.getReportStatus(), "DRAFT");
        if (!"CONFIRMED".equalsIgnoreCase(status) && !"SUBMITTED".equalsIgnoreCase(status)) {
            throw invalidParamException("请先保存并扫码确认当前压槽片号，再推送过程加检");
        }
        return sourceReport;
    }

    private HcPressSlotReportDO findPressSlotProcessCheckSourceReport(HcWetFaiApplyReqVO reqVO,
                                                                      HcPlanOrderOperationDO operation) {
        HcPressSlotReportDO sourceReport = null;
        if (reqVO.getSourceReportId() != null) {
            sourceReport = hcPressSlotReportMapper.selectById(reqVO.getSourceReportId());
        }
        if (sourceReport != null && !Objects.equals(sourceReport.getPlanOperationId(), operation.getId())) {
            return sourceReport;
        }
        if (sourceReport == null && StrUtil.isNotBlank(reqVO.getProductBatchNo())) {
            sourceReport = hcPressSlotReportMapper.selectByProductionBatchNo(StrUtil.trim(reqVO.getProductBatchNo()));
        }
        return sourceReport;
    }

    private HcPressSlotReportDO createPressSlotProcessCheckSourceReport(HcWetFaiApplyReqVO reqVO,
                                                                        HcPlanOrderDO planOrder,
                                                                        HcPlanOrderOperationDO operation,
                                                                        HcProcessReportDO latestStartReport) {
        String productBatchNo = StrUtil.trimToEmpty(reqVO.getProductBatchNo());
        if (StrUtil.isBlank(productBatchNo)) {
            throw invalidParamException("过程加检缺少压槽片号，不能后台生成压槽报工记录");
        }
        HcPressSlotReportDO existedReport = hcPressSlotReportMapper.selectByProductionBatchNo(productBatchNo);
        if (existedReport != null) {
            return existedReport;
        }
        HcSlittingSliceRecordDO sourceSlice = hcSlittingSliceRecordMapper.selectBySerialNo(productBatchNo);
        LocalDateTime now = LocalDateTime.now();
        String motherBatchNo = firstNotBlank(
                normalizePressSlotMiddleBatchNo(reqVO.getInspectionScopeBatchNo()),
                sourceSlice == null ? null : normalizePressSlotMiddleBatchNo(sourceSlice.getSourceProductionBatchNo()),
                sourceSlice == null ? null : normalizePressSlotMiddleBatchNo(sourceSlice.getSourceBatchNo()),
                resolvePressSlotFaiMotherBatchNo(planOrder, operation, latestStartReport, productBatchNo),
                resolvePressSlotOperationMotherBatchNo(operation));
        String operatorName = firstNotBlank(reqVO.getSubmitterName(), SecurityFrameworkUtils.getLoginUserNickname(),
                latestStartReport.getRecorderName(), "系统");
        Map<String, Object> extra = new LinkedHashMap<>();
        extra.put("reportType", PRESS_SLOT_INSPECTION_SAMPLE_CATEGORY_PROCESS_CHECK);
        extra.put("reportTypeName", "过程加检");
        extra.put("inspectionScene", INSPECTION_SCENE_PROCESS_CHECK);
        extra.put("inspectionSampleCategory", PRESS_SLOT_INSPECTION_SAMPLE_CATEGORY_PROCESS_CHECK);
        extra.put("inspectionSampleCategoryName", "加检送检");
        extra.put("autoCreatedForProcessCheck", true);
        extra.put("autoCreateReason", "过程加检扫码后台补建");
        extra.put("autoCreateTime", now.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));
        HcPressSlotReportDO report = HcPressSlotReportDO.builder()
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .operationCode(firstNotBlank(latestStartReport.getOperationCode(), operation.getOpCode()))
                .operationName(firstNotBlank(latestStartReport.getOperationName(), operation.getOpName()))
                .sourceSlittingSliceId(sourceSlice == null ? null : sourceSlice.getId())
                .sourceBatchNo(firstNotBlank(sourceSlice == null ? null : sourceSlice.getSourceBatchNo(), motherBatchNo))
                .sourceProductionBatchNo(firstNotBlank(sourceSlice == null ? null : sourceSlice.getSliceSerialNo(), productBatchNo))
                .productionBatchNo(productBatchNo)
                .parentProductionBatchNo(motherBatchNo)
                .materialCode(firstNotBlank(latestStartReport.getMaterialCode(), planOrder.getMaterialCode()))
                .materialName(firstNotBlank(latestStartReport.getMaterialName(), planOrder.getMaterialName()))
                .modelCode(firstNotBlank(resolveFaiProductModel(latestStartReport, operation, planOrder),
                        planOrder.getModelCode(), planOrder.getModelName()))
                .reportDate(now.toLocalDate())
                .startTime(now)
                .endTime(now)
                .inputLength(BigDecimal.ONE)
                .startPosition(sourceSlice == null ? null : sourceSlice.getStartPosition())
                .endPosition(sourceSlice == null ? null : sourceSlice.getEndPosition())
                .lossLength(BigDecimal.ZERO)
                .outputLength(BigDecimal.ZERO)
                .napSampleLength(BigDecimal.ONE)
                .selfCheck("OK")
                .reportStatus("CONFIRMED")
                .recorderName(operatorName)
                .recorderTime(now)
                .confirmerName(operatorName)
                .confirmerTime(now)
                .remark("过程加检后台补建压槽报工记录")
                .extraJson(JsonUtils.toJsonString(extra))
                .build();
        report.setRecorderName(recorderNameResolver.resolveForSave(report.getRecorderName()));
        hcPressSlotReportMapper.insert(report);
        return report;
    }

    private HcWetFaiRespVO buildPressSlotProcessCheckFaiResp(QmsFaiOrderDO faiOrder,
                                                             HcProcessReportDO latestStartReport,
                                                             HcPlanOrderDO planOrder,
                                                             HcPlanOrderOperationDO operation) {
        HcWetFaiRespVO respVO = buildWetFaiResp(faiOrder, latestStartReport,
                faiOrder == null ? Collections.emptyList() : Collections.singletonList(faiOrder));
        HcPressSlotReportDO sourceReport = faiOrder == null || faiOrder.getSourceReportId() == null
                ? null
                : hcPressSlotReportMapper.selectById(faiOrder.getSourceReportId());
        respVO.setInspectionScene(INSPECTION_SCENE_PROCESS_CHECK);
        respVO.setSourceReportNo(faiOrder == null ? buildPressSlotProcessCheckFaiSourceReportNoPrefix(planOrder, operation) : faiOrder.getSourceReportNo());
        respVO.setSourceReportId(faiOrder == null ? null : faiOrder.getSourceReportId());
        respVO.setProductBatchNo(firstNotBlank(faiOrder == null ? null : faiOrder.getProductBatchNo(),
                sourceReport == null ? null : sourceReport.getProductionBatchNo()));
        respVO.setInspectionScopeBatchNo(sourceReport == null ? null : resolvePressSlotReportMotherBatchNo(sourceReport));
        respVO.setInspectionDate(faiOrder != null && faiOrder.getSubmissionTime() != null
                ? faiOrder.getSubmissionTime().toLocalDate()
                : sourceReport == null ? LocalDate.now() : sourceReport.getReportDate());
        respVO.setTodayInspected(faiOrder != null);
        respVO.setRemark(faiOrder == null ? null : faiOrder.getRemark());
        respVO.setDisplayText("过程加检：" + resolveWetFaiDisplayText(respVO.getFaiStatus(), respVO.getFaiJudgment()));
        respVO.setAllowReportSubmit(isPressSlotFaiSubmitted(faiOrder));
        return respVO;
    }

    private String buildPressSlotProcessCheckFaiSourceReportNoPrefix(HcPlanOrderDO planOrder,
                                                                     HcPlanOrderOperationDO operation) {
        return buildPressSlotTaskNo(planOrder, operation) + "-PROCESS-CHECK-";
    }

    private String buildPressSlotProcessCheckFaiSourceReportNo(HcPlanOrderDO planOrder,
                                                               HcPlanOrderOperationDO operation,
                                                               String productBatchNo) {
        return buildPressSlotProcessCheckFaiSourceReportNoPrefix(planOrder, operation)
                + StrUtil.trimToEmpty(productBatchNo);
    }

    private String buildPressSlotProcessCheckFaiRemark(HcWetFaiApplyReqVO reqVO,
                                                       HcPressSlotReportDO sourceReport,
                                                       String productBatchNo,
                                                       String motherBatchNo) {
        return firstNotBlank(reqVO.getRemark(), "压槽过程加检 FAI 申请")
                + "；检验场景 " + INSPECTION_SCENE_PROCESS_CHECK
                + "；过程加检片号 " + StrUtil.blankToDefault(productBatchNo, "-")
                + "；母卷批号 " + StrUtil.blankToDefault(motherBatchNo, "-")
                + "；压槽报工ID " + (sourceReport == null ? "-" : sourceReport.getId());
    }

    private void storePressSlotProcessCheckFaiInfo(HcPressSlotReportDO sourceReport, QmsFaiOrderDO faiOrder) {
        if (sourceReport == null || sourceReport.getId() == null || faiOrder == null) {
            return;
        }
        Map<String, Object> extra = new LinkedHashMap<>(parseRoughExtraMap(sourceReport.getExtraJson()));
        extra.put("inspectionScene", INSPECTION_SCENE_PROCESS_CHECK);
        extra.put("inspectionSampleCategory", PRESS_SLOT_INSPECTION_SAMPLE_CATEGORY_PROCESS_CHECK);
        extra.put("inspectionSampleCategoryName", "加检送检");
        extra.put("processCheckFaiId", faiOrder.getId());
        extra.put("processCheckFaiNo", faiOrder.getFaiNo());
        extra.put("processCheckFaiStatus", faiOrder.getStatus());
        extra.put("processCheckFaiJudgment", faiOrder.getJudgment());
        extra.put("processCheckFaiApplyTime", LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));
        HcPressSlotReportDO updateReport = new HcPressSlotReportDO();
        updateReport.setId(sourceReport.getId());
        updateReport.setExtraJson(JsonUtils.toJsonString(extra));
        hcPressSlotReportMapper.updateById(updateReport);
        sourceReport.setExtraJson(updateReport.getExtraJson());
    }

    private boolean isPressSlotAbnormalReleaseFai(HcWetFaiApplyReqVO reqVO) {
        return reqVO != null
                && INSPECTION_SCENE_ABNORMAL_RELEASE.equalsIgnoreCase(StrUtil.trimToEmpty(reqVO.getInspectionScene()));
    }

    private HcWetFaiRespVO applyPressSlotAbnormalReleaseFai(HcWetFaiApplyReqVO reqVO,
                                                            HcPlanOrderDO planOrder,
                                                            HcPlanOrderOperationDO operation,
                                                            HcProcessReportDO latestStartReport) {
        HcPressSlotReportDO sourceReport = resolvePressSlotAbnormalReleaseSourceReport(reqVO, operation);
        String motherBatchNo = firstNotBlank(normalizePressSlotMiddleBatchNo(reqVO.getInspectionScopeBatchNo()),
                resolvePressSlotReportMotherBatchNo(sourceReport));
        syncPressSlotAbnormalLockLedger(planOrder, operation, motherBatchNo);
        PressSlotAbnormalLockCycle activeLock = findActivePressSlotAbnormalLockCycle(planOrder, operation, motherBatchNo);
        if (activeLock == null) {
            throw invalidParamException("当前母批暂无加检NG风险锁定记录，不需要提交风险片槽深复测");
        }
        LocalDateTime confirmTime = resolvePressSlotReportControlEventTime(sourceReport);
        if (!isPressSlotAbnormalReleaseSourceAllowed(sourceReport, activeLock, confirmTime)) {
            throw invalidParamException("片号 " + StrUtil.blankToDefault(sourceReport.getProductionBatchNo(), "-")
                    + " 不属于当前加检NG冻结风险区间，请从已锁定风险片中选择");
        }
        String operationCode = firstNotBlank(sourceReport.getOperationCode(), latestStartReport.getOperationCode(), operation.getOpCode());
        String operationName = firstNotBlank(sourceReport.getOperationName(), latestStartReport.getOperationName(), operation.getOpName());
        if (StrUtil.isBlank(operationCode) && StrUtil.isBlank(operationName)) {
            throw invalidParamException("当前压槽任务缺少工段信息，无法按产品型号与工段匹配 FAI 检验标准");
        }
        String productModel = firstNotBlank(sourceReport.getModelCode(), resolveFaiProductModel(latestStartReport, operation, planOrder));
        if (StrUtil.isBlank(productModel)) {
            throw invalidParamException("当前压槽任务缺少产品型号，无法按产品型号与工段匹配 FAI 检验标准");
        }
        String productBatchNo = firstNotBlank(reqVO.getProductBatchNo(), sourceReport.getProductionBatchNo(), sourceReport.getSourceProductionBatchNo());
        if (StrUtil.isBlank(productBatchNo)) {
            throw invalidParamException("风险片槽深复测缺少压槽片号，不能生成 FAI 检验单");
        }
        QmsFaiOrderDO latestReleaseFai = activeLock.latestReleaseFaiOrder;
        if (latestReleaseFai != null && !isPressSlotFaiReapplyAllowed(latestReleaseFai)) {
            if (isFaiReleased(latestReleaseFai)) {
                throw invalidParamException("当前风险锁定已复测OK并放行，不能重复提交风险片槽深复测");
            }
            throw invalidParamException("当前风险锁定已有未完成的槽深复测单，请先在 FAI 工作台处理后再提交");
        }
        String sourceReportNo = buildPressSlotAbnormalReleaseFaiSourceReportNo(planOrder, operation, productBatchNo);
        String triggerReason = firstNotBlank(reqVO.getTriggerReason(),
                latestReleaseFai != null && isPressSlotFaiReapplyAllowed(latestReleaseFai)
                        ? FAI_TRIGGER_REWORK_RECHECK : FAI_TRIGGER_NEW_ORDER);
        if (latestReleaseFai != null && isPressSlotFaiReapplyAllowed(latestReleaseFai)
                && !FAI_TRIGGER_REWORK_RECHECK.equals(triggerReason)) {
            triggerReason = FAI_TRIGGER_REWORK_RECHECK;
        }
        String motherMaterialCode = firstNotBlank(sourceReport.getMaterialCode(), latestStartReport.getMotherMaterialCode(),
                operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode(),
                latestStartReport.getMaterialCode(), planOrder.getMaterialCode());

        QmsFaiSaveReqVO faiReqVO = new QmsFaiSaveReqVO();
        faiReqVO.setWorkOrderNo(planOrder.getPlanNo());
        faiReqVO.setSourceReportId(sourceReport.getId());
        faiReqVO.setSourceReportNo(sourceReportNo);
        faiReqVO.setSourceModule(SOURCE_MENU_CODE_PRESS_SLOT);
        faiReqVO.setSourceOperationCode(operationCode);
        faiReqVO.setSourceOperationName(operationName);
        faiReqVO.setPlanOrderId(planOrder.getId());
        faiReqVO.setStandardMatchMode(FAI_STANDARD_MATCH_PRODUCT_MODEL_PROCESS);
        faiReqVO.setOperationCode(operationCode);
        faiReqVO.setOperationName(operationName);
        faiReqVO.setMachineId(latestStartReport.getEquipmentId());
        faiReqVO.setMachineCode(firstNotBlank(latestStartReport.getEquipmentCode(), operation.getEquipmentCode()));
        faiReqVO.setMachineName(firstNotBlank(latestStartReport.getEquipmentName(), operation.getEquipmentName()));
        faiReqVO.setMaterialId(firstNotNull(latestStartReport.getMotherMaterialId(), operation.getMotherMaterialId(),
                planOrder.getMotherMaterialId(), latestStartReport.getMaterialId(), planOrder.getMaterialId()));
        faiReqVO.setMaterialCode(motherMaterialCode);
        faiReqVO.setMaterialName(firstNotBlank(sourceReport.getMaterialName(), latestStartReport.getMotherMaterialName(),
                operation.getMotherMaterialName(), planOrder.getMotherMaterialName(),
                latestStartReport.getMaterialName(), planOrder.getMaterialName()));
        faiReqVO.setSpecification(planOrder.getSizeName());
        faiReqVO.setProductModel(productModel);
        faiReqVO.setProductBatchNo(productBatchNo);
        faiReqVO.setProcessCategory(PROCESS_CODE_PRESS_SLOT);
        faiReqVO.setSubmissionType(FAI_SUBMISSION_TYPE_MASS_SHIPMENT);
        faiReqVO.setTriggerReason(triggerReason);
        faiReqVO.setStatus(FAI_STATUS_PENDING);
        faiReqVO.setJudgment(FAI_JUDGMENT_PENDING);
        faiReqVO.setSubmissionTime(LocalDateTime.now());
        faiReqVO.setSubmitterName(firstNotBlank(reqVO.getSubmitterName(), SecurityFrameworkUtils.getLoginUserNickname(),
                sourceReport.getRecorderName(), latestStartReport.getRecorderName(), "系统"));
        faiReqVO.setRemark(buildPressSlotAbnormalReleaseFaiRemark(reqVO, sourceReport, productBatchNo, motherBatchNo, activeLock));
        Long faiId = qmsFaiService.createFaiForInspectionPush(faiReqVO);
        QmsFaiOrderDO createdFai = qmsFaiOrderMapper.selectById(faiId);
        storePressSlotAbnormalReleaseFaiInfo(sourceReport, createdFai, activeLock);
        syncPressSlotAbnormalLockLedger(planOrder, operation, motherBatchNo);
        HcWetFaiRespVO respVO = buildPressSlotAbnormalReleaseFaiResp(createdFai, latestStartReport, planOrder, operation);
        respVO.setInspectionScopeBatchNo(motherBatchNo);
        return respVO;
    }

    private HcPressSlotReportDO resolvePressSlotAbnormalReleaseSourceReport(HcWetFaiApplyReqVO reqVO,
                                                                            HcPlanOrderOperationDO operation) {
        HcPressSlotReportDO sourceReport = findPressSlotProcessCheckSourceReport(reqVO, operation);
        if (sourceReport == null || Boolean.TRUE.equals(sourceReport.getDeleted())) {
            throw invalidParamException("请先选择已扫码确认的压槽片号，再提交异常放行送检");
        }
        if (!Objects.equals(sourceReport.getPlanOperationId(), operation.getId())) {
            throw invalidParamException("异常放行送检片号不属于当前压槽工序");
        }
        if (!isPressSlotConfirmedReport(sourceReport)) {
            throw invalidParamException("异常放行送检片号尚未扫码确认，请先确认后再提交");
        }
        return sourceReport;
    }

    private HcWetFaiRespVO buildPressSlotAbnormalReleaseFaiResp(QmsFaiOrderDO faiOrder,
                                                                HcProcessReportDO latestStartReport,
                                                                HcPlanOrderDO planOrder,
                                                                HcPlanOrderOperationDO operation) {
        HcWetFaiRespVO respVO = buildWetFaiResp(faiOrder, latestStartReport,
                faiOrder == null ? Collections.emptyList() : Collections.singletonList(faiOrder));
        HcPressSlotReportDO sourceReport = faiOrder == null || faiOrder.getSourceReportId() == null
                ? null
                : hcPressSlotReportMapper.selectById(faiOrder.getSourceReportId());
        respVO.setInspectionScene(INSPECTION_SCENE_ABNORMAL_RELEASE);
        respVO.setSourceReportNo(faiOrder == null ? buildPressSlotAbnormalReleaseFaiSourceReportNoPrefix(planOrder, operation) : faiOrder.getSourceReportNo());
        respVO.setSourceReportId(faiOrder == null ? null : faiOrder.getSourceReportId());
        respVO.setProductBatchNo(firstNotBlank(faiOrder == null ? null : faiOrder.getProductBatchNo(),
                sourceReport == null ? null : sourceReport.getProductionBatchNo()));
        respVO.setInspectionScopeBatchNo(sourceReport == null ? null : resolvePressSlotReportMotherBatchNo(sourceReport));
        respVO.setInspectionDate(faiOrder != null && faiOrder.getSubmissionTime() != null
                ? faiOrder.getSubmissionTime().toLocalDate()
                : sourceReport == null ? LocalDate.now() : sourceReport.getReportDate());
        respVO.setTodayInspected(faiOrder != null);
        respVO.setRemark(faiOrder == null ? null : faiOrder.getRemark());
        respVO.setDisplayText("异常放行：" + resolveWetFaiDisplayText(respVO.getFaiStatus(), respVO.getFaiJudgment()));
        respVO.setAllowReportSubmit(isPressSlotFaiSubmitted(faiOrder));
        return respVO;
    }

    private String buildPressSlotAbnormalReleaseFaiSourceReportNoPrefix(HcPlanOrderDO planOrder,
                                                                        HcPlanOrderOperationDO operation) {
        return buildPressSlotTaskNo(planOrder, operation) + "-ABNORMAL-RELEASE-";
    }

    private String buildPressSlotAbnormalReleaseFaiSourceReportNo(HcPlanOrderDO planOrder,
                                                                  HcPlanOrderOperationDO operation,
                                                                  String productBatchNo) {
        return buildPressSlotAbnormalReleaseFaiSourceReportNoPrefix(planOrder, operation)
                + StrUtil.trimToEmpty(productBatchNo);
    }

    private String buildPressSlotAbnormalReleaseFaiRemark(HcWetFaiApplyReqVO reqVO,
                                                          HcPressSlotReportDO sourceReport,
                                                          String productBatchNo,
                                                          String motherBatchNo,
                                                          PressSlotAbnormalLockCycle activeLock) {
        QmsFaiOrderDO abnormal = activeLock == null ? null : activeLock.abnormalFaiOrder;
        return firstNotBlank(reqVO.getRemark(), "压槽异常放行送检")
                + "；检验场景 " + INSPECTION_SCENE_ABNORMAL_RELEASE
                + "；放行片号 " + StrUtil.blankToDefault(productBatchNo, "-")
                + "；母卷批号 " + StrUtil.blankToDefault(motherBatchNo, "-")
                + "；异常加检单 " + StrUtil.blankToDefault(abnormal == null ? null : abnormal.getFaiNo(), "-")
                + "；异常加检片号 " + StrUtil.blankToDefault(abnormal == null ? null : abnormal.getProductBatchNo(), "-")
                + "；锁定起点 " + (activeLock == null || activeLock.lockStartTime == null ? "-" : formatDateTime(activeLock.lockStartTime))
                + "；压槽报工ID " + (sourceReport == null ? "-" : sourceReport.getId());
    }

    private void storePressSlotAbnormalReleaseFaiInfo(HcPressSlotReportDO sourceReport,
                                                      QmsFaiOrderDO faiOrder,
                                                      PressSlotAbnormalLockCycle activeLock) {
        if (sourceReport == null || sourceReport.getId() == null || faiOrder == null) {
            return;
        }
        Map<String, Object> extra = new LinkedHashMap<>(parseRoughExtraMap(sourceReport.getExtraJson()));
        extra.put("inspectionScene", INSPECTION_SCENE_ABNORMAL_RELEASE);
        extra.put("inspectionSampleCategory", PRESS_SLOT_INSPECTION_SAMPLE_CATEGORY_ABNORMAL_RELEASE);
        extra.put("inspectionSampleCategoryName", "异常放行送检");
        extra.put("abnormalReleaseFaiId", faiOrder.getId());
        extra.put("abnormalReleaseFaiNo", faiOrder.getFaiNo());
        extra.put("abnormalReleaseFaiStatus", faiOrder.getStatus());
        extra.put("abnormalReleaseFaiJudgment", faiOrder.getJudgment());
        extra.put("abnormalReleaseFaiApplyTime", LocalDateTime.now().format(DATETIME_FORMATTER));
        if (activeLock != null && activeLock.abnormalFaiOrder != null) {
            extra.put("abnormalLockFaiId", activeLock.abnormalFaiOrder.getId());
            extra.put("abnormalLockFaiNo", activeLock.abnormalFaiOrder.getFaiNo());
            extra.put("abnormalLockStartTime", activeLock.lockStartTime == null ? null : activeLock.lockStartTime.format(DATETIME_FORMATTER));
        }
        HcPressSlotReportDO updateReport = new HcPressSlotReportDO();
        updateReport.setId(sourceReport.getId());
        updateReport.setExtraJson(JsonUtils.toJsonString(extra));
        hcPressSlotReportMapper.updateById(updateReport);
        sourceReport.setExtraJson(updateReport.getExtraJson());
    }

    private void syncPressSlotAbnormalLockLedger(HcPlanOrderDO planOrder,
                                                 HcPlanOrderOperationDO operation,
                                                 String motherBatchNo) {
        if (planOrder == null || operation == null) {
            return;
        }
        String scopeMotherBatchNo = normalizePressSlotMiddleBatchNo(motherBatchNo);
        List<PressSlotAbnormalLockCycle> cycles = buildPressSlotAbnormalLockCycles(planOrder, operation, scopeMotherBatchNo);
        if (cycles.isEmpty()) {
            return;
        }
        List<HcPressSlotReportDO> confirmedReports = hcPressSlotReportMapper.selectConfirmedListByPlanOperationId(operation.getId());
        for (PressSlotAbnormalLockCycle cycle : cycles) {
            syncPressSlotAbnormalLockCycle(planOrder, operation, cycle, confirmedReports);
        }
    }

    private void syncPressSlotAbnormalLockCycle(HcPlanOrderDO planOrder,
                                                HcPlanOrderOperationDO operation,
                                                PressSlotAbnormalLockCycle cycle,
                                                List<HcPressSlotReportDO> confirmedReports) {
        if (cycle == null || cycle.abnormalFaiOrder == null || cycle.abnormalFaiOrder.getId() == null) {
            return;
        }
        HcPressSlotAbnormalLockDO lock = hcPressSlotAbnormalLockMapper.selectByAbnormalFaiId(cycle.abnormalFaiOrder.getId());
        boolean create = lock == null;
        if (create) {
            lock = new HcPressSlotAbnormalLockDO();
        }
        fillPressSlotAbnormalLockDO(lock, planOrder, operation, cycle);
        savePressSlotAbnormalLock(lock, create);
        if (lock.getId() == null) {
            lock = hcPressSlotAbnormalLockMapper.selectByAbnormalFaiId(cycle.abnormalFaiOrder.getId());
            if (lock == null || lock.getId() == null) {
                return;
            }
        }

        List<HcPressSlotReportDO> matchedReports = (confirmedReports == null ? Collections.<HcPressSlotReportDO>emptyList() : confirmedReports).stream()
                .filter(report -> isPressSlotReportWithinLockCycle(report, cycle, resolvePressSlotReportControlEventTime(report)))
                .sorted(Comparator
                        .comparing((HcPressSlotReportDO report) -> firstNotNullDateTime(
                                resolvePressSlotReportControlEventTime(report), LocalDateTime.MIN))
                        .thenComparing(report -> report.getId() == null ? 0L : report.getId()))
                .toList();
        Set<Long> expectedReportIds = matchedReports.stream()
                .map(HcPressSlotReportDO::getId)
                .filter(Objects::nonNull)
                .collect(Collectors.toCollection(LinkedHashSet::new));
        Map<Long, HcPressSlotAbnormalLockItemDO> existedItemMap = hcPressSlotAbnormalLockItemMapper.selectListByLockId(lock.getId()).stream()
                .filter(item -> item.getReportId() != null)
                .collect(Collectors.toMap(HcPressSlotAbnormalLockItemDO::getReportId, item -> item, (a, b) -> a, LinkedHashMap::new));
        for (HcPressSlotAbnormalLockItemDO existedItem : existedItemMap.values()) {
            if (!expectedReportIds.contains(existedItem.getReportId())) {
                hcPressSlotAbnormalLockItemMapper.deleteById(existedItem.getId());
            }
        }
        for (HcPressSlotReportDO report : matchedReports) {
            HcPressSlotAbnormalLockItemDO item = existedItemMap.get(report.getId());
            boolean itemCreate = item == null;
            if (itemCreate) {
                item = new HcPressSlotAbnormalLockItemDO();
            }
            fillPressSlotAbnormalLockItemDO(item, lock, report);
            savePressSlotAbnormalLockItem(item, itemCreate);
        }
        HcPressSlotAbnormalLockDO countUpdate = new HcPressSlotAbnormalLockDO();
        countUpdate.setId(lock.getId());
        countUpdate.setLockedCount(expectedReportIds.size());
        countUpdate.setLastSyncTime(LocalDateTime.now());
        hcPressSlotAbnormalLockMapper.updateById(countUpdate);
    }

    private void savePressSlotAbnormalLock(HcPressSlotAbnormalLockDO lock, boolean create) {
        if (!create) {
            hcPressSlotAbnormalLockMapper.updateById(lock);
            return;
        }
        try {
            hcPressSlotAbnormalLockMapper.insert(lock);
            return;
        } catch (DuplicateKeyException ex) {
            HcPressSlotAbnormalLockDO existed = hcPressSlotAbnormalLockMapper
                    .selectByAbnormalFaiIdForUpdate(lock.getAbnormalFaiId());
            if (existed == null || existed.getId() == null) {
                throw ex;
            }
            lock.setId(existed.getId());
            hcPressSlotAbnormalLockMapper.updateById(lock);
        }
    }

    private void savePressSlotAbnormalLockItem(HcPressSlotAbnormalLockItemDO item, boolean create) {
        if (!create) {
            hcPressSlotAbnormalLockItemMapper.updateById(item);
            return;
        }
        HcPressSlotAbnormalLockItemDO existed = hcPressSlotAbnormalLockItemMapper.selectByLockIdAndReportId(
                item.getLockId(), item.getReportId());
        if (existed != null && existed.getId() != null) {
            item.setId(existed.getId());
            hcPressSlotAbnormalLockItemMapper.updateById(item);
            return;
        }
        try {
            hcPressSlotAbnormalLockItemMapper.insert(item);
            return;
        } catch (DuplicateKeyException ex) {
            existed = hcPressSlotAbnormalLockItemMapper
                    .selectByLockIdAndReportIdForUpdate(item.getLockId(), item.getReportId());
            if (existed == null || existed.getId() == null) {
                throw ex;
            }
            item.setId(existed.getId());
            hcPressSlotAbnormalLockItemMapper.updateById(item);
        }
    }

    private void fillPressSlotAbnormalLockDO(HcPressSlotAbnormalLockDO lock,
                                             HcPlanOrderDO planOrder,
                                             HcPlanOrderOperationDO operation,
                                             PressSlotAbnormalLockCycle cycle) {
        QmsFaiOrderDO abnormal = cycle.abnormalFaiOrder;
        QmsFaiOrderDO release = cycle.latestReleaseFaiOrder;
        boolean released = cycle.released();
        lock.setPlanId(planOrder.getId());
        lock.setPlanNo(planOrder.getPlanNo());
        lock.setPlanOperationId(operation.getId());
        lock.setOperationCode(operation.getOpCode());
        lock.setOperationName(operation.getOpName());
        lock.setMotherBatchNo(cycle.motherBatchNo);
        lock.setAbnormalFaiId(abnormal.getId());
        lock.setAbnormalFaiNo(abnormal.getFaiNo());
        lock.setAbnormalSampleBatchNo(abnormal.getProductBatchNo());
        lock.setAbnormalResult(resolvePressSlotFaiResultText(abnormal));
        lock.setAbnormalSubmitTime(resolvePressSlotInspectionSubmissionTime(abnormal));
        lock.setAbnormalFeedbackTime(resolvePressSlotFaiFeedbackTime(abnormal));
        lock.setAbnormalInspectorName(resolvePressSlotFaiInspectorName(abnormal));
        lock.setLockStartTime(cycle.lockStartTime);
        lock.setLockStatus(released ? PRESS_SLOT_ABNORMAL_LOCK_STATUS_RELEASED : PRESS_SLOT_ABNORMAL_LOCK_STATUS_LOCKED);
        lock.setLockReason("压槽过程加检NG后锁定后续扫码确认片");
        fillPressSlotAbnormalLockReleaseFields(lock, release, released);
        lock.setReleaseTime(cycle.releaseTime);
        lock.setLastSyncTime(LocalDateTime.now());
        lock.setTenantId(resolvePressSlotAbnormalLockTenantId(planOrder, operation));
    }

    private void fillPressSlotAbnormalLockReleaseFields(HcPressSlotAbnormalLockDO lock,
                                                        QmsFaiOrderDO release,
                                                        boolean released) {
        if (lock == null || release == null) {
            return;
        }
        lock.setReleaseFaiId(release.getId());
        lock.setReleaseFaiNo(release.getFaiNo());
        lock.setReleaseSampleBatchNo(release.getProductBatchNo());
        lock.setReleaseResult(resolvePressSlotFaiResultText(release));
        lock.setReleaseSubmitTime(resolvePressSlotInspectionSubmissionTime(release));
        lock.setReleaseFeedbackTime(resolvePressSlotFaiFeedbackTime(release));
        lock.setReleaseInspectorName(resolvePressSlotFaiInspectorName(release));
        lock.setReleaseOpinion(firstNotBlank(release.getReleaseResult(), release.getLastReturnReason(),
                released ? "风险片复测已送检，允许继续报工（待QMS结果）" : "风险片复测尚未送检，继续标记风险"));
    }

