    private List<PressSlotAbnormalLockCycle> buildPressSlotAbnormalLockCycles(HcPlanOrderDO planOrder,
                                                                               HcPlanOrderOperationDO operation,
                                                                               String motherBatchNo) {
        // 历史风险锁仅保留审计记录，不再生成或参与压槽报工控制。
        return Collections.emptyList();
    }

    private PressSlotAbnormalLockCycle findActivePressSlotAbnormalLockCycle(HcPlanOrderDO planOrder,
                                                                            HcPlanOrderOperationDO operation,
                                                                            String motherBatchNo) {
        return buildPressSlotAbnormalLockCycles(planOrder, operation, motherBatchNo).stream()
                .filter(item -> !item.released())
                .max(Comparator.comparing(item -> item.lockStartTime, Comparator.nullsFirst(Comparator.naturalOrder())))
                .orElse(null);
    }

    private PressSlotAbnormalLockCycle findPressSlotAbnormalLockCycleForReport(List<PressSlotAbnormalLockCycle> cycles,
                                                                               HcPressSlotReportDO report,
                                                                               LocalDateTime confirmTime) {
        if (cycles == null || cycles.isEmpty() || report == null || confirmTime == null) {
            return null;
        }
        return cycles.stream()
                .filter(cycle -> isPressSlotReportWithinLockCycle(report, cycle, confirmTime))
                .max(Comparator.comparing(cycle -> cycle.lockStartTime, Comparator.nullsFirst(Comparator.naturalOrder())))
                .orElse(null);
    }

    private boolean isPressSlotReportWithinLockCycle(HcPressSlotReportDO report,
                                                     PressSlotAbnormalLockCycle cycle,
                                                     LocalDateTime confirmTime) {
        if (report == null || cycle == null || confirmTime == null || cycle.lockStartTime == null) {
            return false;
        }
        if (!StrUtil.equalsIgnoreCase(resolvePressSlotReportMotherBatchNo(report), cycle.motherBatchNo)) {
            return false;
        }
        if (!confirmTime.isAfter(cycle.lockStartTime)) {
            return false;
        }
        LocalDateTime riskWindowEndTime = resolvePressSlotFaiFeedbackTime(cycle.abnormalFaiOrder);
        return riskWindowEndTime != null && !confirmTime.isAfter(riskWindowEndTime);
    }

    private boolean isPressSlotAbnormalReleaseSourceAllowed(HcPressSlotReportDO report,
                                                            PressSlotAbnormalLockCycle cycle,
                                                            LocalDateTime confirmTime) {
        return isPressSlotReportWithinLockCycle(report, cycle, confirmTime);
    }

    private HcPressSlotAbnormalLockRespVO buildPressSlotAbnormalLockResp(HcPressSlotReportDO report,
                                                                         PressSlotAbnormalLockCycle cycle) {
        HcPressSlotAbnormalLockRespVO respVO = new HcPressSlotAbnormalLockRespVO();
        respVO.setId(report.getId());
        respVO.setReportId(report.getId());
        respVO.setPlanId(report.getPlanId());
        respVO.setPlanNo(report.getPlanNo());
        respVO.setPlanOperationId(report.getPlanOperationId());
        respVO.setMotherBatchNo(resolvePressSlotReportMotherBatchNo(report));
        respVO.setProductionBatchNo(report.getProductionBatchNo());
        respVO.setConfirmTime(resolvePressSlotReportControlEventTime(report));
        respVO.setConfirmerName(report.getConfirmerName());
        respVO.setLocked(!cycle.released());
        respVO.setLockStatus(cycle.released() ? "RELEASED" : "LOCKED");
        fillPressSlotAbnormalInspectionInfo(respVO, cycle.abnormalFaiOrder);
        fillPressSlotReleaseInspectionInfo(respVO, cycle.latestReleaseFaiOrder, cycle.released());
        return respVO;
    }

    private void fillPressSlotAbnormalInspectionInfo(HcPressSlotAbnormalLockRespVO respVO,
                                                     QmsFaiOrderDO faiOrder) {
        if (respVO == null || faiOrder == null) {
            return;
        }
        respVO.setAbnormalFaiId(faiOrder.getId());
        respVO.setAbnormalFaiNo(faiOrder.getFaiNo());
        respVO.setAbnormalSampleBatchNo(faiOrder.getProductBatchNo());
        respVO.setAbnormalResult(resolvePressSlotFaiResultText(faiOrder));
        respVO.setAbnormalSubmitTime(resolvePressSlotInspectionSubmissionTime(faiOrder));
        respVO.setAbnormalFeedbackTime(resolvePressSlotFaiFeedbackTime(faiOrder));
        respVO.setAbnormalInspectorName(resolvePressSlotFaiInspectorName(faiOrder));
    }

    private void fillPressSlotReleaseInspectionInfo(HcPressSlotAbnormalLockRespVO respVO,
                                                    QmsFaiOrderDO faiOrder,
                                                    boolean released) {
        if (respVO == null || faiOrder == null) {
            return;
        }
        respVO.setReleaseFaiId(faiOrder.getId());
        respVO.setReleaseFaiNo(faiOrder.getFaiNo());
        respVO.setReleaseSampleBatchNo(faiOrder.getProductBatchNo());
        respVO.setReleaseResult(resolvePressSlotFaiResultText(faiOrder));
        respVO.setReleaseSubmitTime(resolvePressSlotInspectionSubmissionTime(faiOrder));
        respVO.setReleaseFeedbackTime(resolvePressSlotFaiFeedbackTime(faiOrder));
        respVO.setReleaseInspectorName(resolvePressSlotFaiInspectorName(faiOrder));
        respVO.setReleaseOpinion(firstNotBlank(faiOrder.getReleaseResult(), faiOrder.getLastReturnReason(),
                released ? "风险片复测已送检，允许继续报工（待QMS结果）" : "风险片复测尚未送检，继续标记风险"));
    }

    private List<QmsFaiOrderDO> listPressSlotProcessCheckFaiOrdersForTask(HcPlanOrderDO planOrder,
                                                                          HcPlanOrderOperationDO operation) {
        if (planOrder == null || operation == null) {
            return Collections.emptyList();
        }
        return qmsFaiOrderMapper.selectListBySourceReportNoPrefix(
                buildPressSlotProcessCheckFaiSourceReportNoPrefix(planOrder, operation), SOURCE_MENU_CODE_PRESS_SLOT);
    }

    private List<QmsFaiOrderDO> listPressSlotAbnormalReleaseFaiOrdersForTask(HcPlanOrderDO planOrder,
                                                                             HcPlanOrderOperationDO operation) {
        if (planOrder == null || operation == null) {
            return Collections.emptyList();
        }
        return qmsFaiOrderMapper.selectListBySourceReportNoPrefix(
                buildPressSlotAbnormalReleaseFaiSourceReportNoPrefix(planOrder, operation), SOURCE_MENU_CODE_PRESS_SLOT);
    }

    private boolean isPressSlotAbnormalProcessCheckFaiOrder(QmsFaiOrderDO faiOrder) {
        return isPressSlotProcessCheckFaiOrder(faiOrder)
                && (FAI_JUDGMENT_NG.equals(faiOrder.getJudgment()) || isFaiRejectedNg(faiOrder)
                || (FAI_STATUS_COMPLETED.equals(faiOrder.getStatus()) && FAI_JUDGMENT_NG.equals(faiOrder.getJudgment())));
    }

    private boolean isPressSlotAbnormalReleaseFaiOrder(QmsFaiOrderDO faiOrder) {
        return faiOrder != null
                && StrUtil.blankToDefault(faiOrder.getSourceReportNo(), "")
                .toUpperCase()
                .contains("-ABNORMAL-RELEASE-");
    }

    private LocalDateTime resolvePressSlotFaiFeedbackTime(QmsFaiOrderDO faiOrder) {
        if (!isPressSlotInspectionResultReturned(faiOrder)) {
            return null;
        }
        return firstNotNullDateTime(faiOrder == null ? null : faiOrder.getQaTime(),
                faiOrder == null ? null : faiOrder.getOperatorTime(),
                faiOrder == null ? null : faiOrder.getUpdateTime());
    }

    private String resolvePressSlotFaiInspectorName(QmsFaiOrderDO faiOrder) {
        return firstNotBlank(faiOrder == null ? null : faiOrder.getQaInspectorName(),
                faiOrder == null ? null : faiOrder.getOperatorName());
    }

    private String resolvePressSlotFaiResultText(QmsFaiOrderDO faiOrder) {
        if (faiOrder == null) {
            return "";
        }
        if (isFaiReleased(faiOrder)) {
            return "正常";
        }
        if (FAI_JUDGMENT_NG.equals(faiOrder.getJudgment()) || isFaiRejectedNg(faiOrder)) {
            return "NG";
        }
        return resolveWetFaiDisplayText(faiOrder.getStatus(), faiOrder.getJudgment());
    }

    private void validatePressSlotFaiSubmitted(HcPlanOrderDO planOrder, HcPlanOrderOperationDO operation,
                                              String motherBatchNo) {
        validatePressSlotFaiSubmitted(planOrder, operation, motherBatchNo, null, null, true);
    }

    private void validatePressSlotFaiSubmitted(HcPlanOrderDO planOrder, HcPlanOrderOperationDO operation,
                                              String motherBatchNo, HcPressSlotReportDO currentReport) {
        validatePressSlotFaiSubmitted(planOrder, operation, motherBatchNo,
                currentReport == null ? null : currentReport.getProductionBatchNo(),
                currentReport == null ? null : currentReport.getExtraJson(), true);
    }

    private void validatePressSlotFaiSubmitted(HcPlanOrderDO planOrder, HcPlanOrderOperationDO operation,
                                              String motherBatchNo, String currentBatchNo, String currentExtraJson) {
        validatePressSlotFaiSubmitted(planOrder, operation, motherBatchNo, currentBatchNo, currentExtraJson, true);
    }

    private HcPressSlotScanGateRespVO validatePressSlotFaiSubmitted(HcPlanOrderDO planOrder, HcPlanOrderOperationDO operation,
                                                                   String motherBatchNo, String currentBatchNo,
                                                                   String currentExtraJson,
                                                                   boolean enforceScanContinuity) {
        HcProcessReportDO latestStartReport = getLatestStartReport(operation.getId(), SOURCE_MENU_CODE_PRESS_SLOT);
        String scopeMotherBatchNo = resolvePressSlotFaiMotherBatchNo(planOrder, operation,
                latestStartReport, motherBatchNo);
        List<QmsFaiOrderDO> scopeInspectionOrders = listPressSlotInspectionOrdersForTaskScope(
                planOrder, operation, scopeMotherBatchNo);
        QmsFaiOrderDO latestScopeFirstInspection = scopeInspectionOrders.stream()
                .filter(item -> !isPressSlotProcessCheckFaiOrder(item))
                .filter(item -> isPressSlotFaiSubmitted(item))
                .findFirst()
                .orElse(null);
        if (latestScopeFirstInspection == null) {
            throw invalidParamException("当前分段批次 "
                    + StrUtil.blankToDefault(scopeMotherBatchNo, "-")
                    + " 尚未成功提交压槽首检，请先送检后再扫码确认");
        }
        syncPressSlotReportFaiSummary(latestStartReport, latestScopeFirstInspection);
        QmsFaiOrderDO pendingRestartNg = findPressSlotPendingRestartNg(scopeInspectionOrders);
        if (pendingRestartNg != null) {
            throw invalidParamException("检验单 " + pendingRestartNg.getFaiNo()
                    + " 已返回NG，请使用新片重新首检；送检成功即可继续报工");
        }
        if (!enforceScanContinuity) {
            return buildPressSlotScanGateResp(null, null, null);
        }
        if (isPressSlotProcessCheckSample(currentExtraJson)) {
            return buildPressSlotScanGateResp(null, null, null);
        }
        QmsFaiOrderDO latestScopeInspection = scopeInspectionOrders.stream()
                .filter(this::isPressSlotFaiSubmitted)
                .filter(item -> isPressSlotProcessCheckFaiOrder(item)
                        || !isPressSlotAdditionalFirstInspectionFaiOrder(item))
                .findFirst()
                .orElse(latestScopeFirstInspection);
        if (latestScopeInspection == null) {
            throw invalidParamException("当前分段批次未找到有效首检/过程加检送检单，请重新提交送检");
        }
        long confirmedAfterFaiCount = countPressSlotConfirmedReportsAfterFai(operation,
                scopeMotherBatchNo, latestScopeInspection, currentBatchNo);
        int blockThresholdCount = resolvePressSlotFaiBlockThreshold(planOrder);
        return buildPressSlotContinuousCheckReminder(confirmedAfterFaiCount, blockThresholdCount);
    }

    private HcPressSlotScanGateRespVO buildPressSlotContinuousCheckReminder(long confirmedAfterFaiCount,
                                                                           int blockThresholdCount) {
        if (confirmedAfterFaiCount >= blockThresholdCount) {
            return buildPressSlotScanGateResp(confirmedAfterFaiCount, blockThresholdCount,
                    "距最近一次首检/过程加检已扫码确认 " + confirmedAfterFaiCount
                            + " 片，达到当前BOM配置的压槽连续作业加检数 " + blockThresholdCount
                            + " 片，请及时提交过程加检；本次允许继续报工。");
        }
        if (confirmedAfterFaiCount >= PRESS_SLOT_FAI_WARNING_THRESHOLD) {
            return buildPressSlotScanGateResp(confirmedAfterFaiCount, blockThresholdCount,
                    "距最近一次首检/过程加检已扫码确认 " + confirmedAfterFaiCount
                            + " 片，已达到 20 片过程加检提醒；当前BOM配置加检提醒数为 "
                            + blockThresholdCount + " 片，本次不阻止继续扫码确认，请及时提交过程加检。");
        }
        return buildPressSlotScanGateResp(confirmedAfterFaiCount, blockThresholdCount, null);
    }

    private HcPressSlotScanGateRespVO buildPressSlotScanGateResp(Long confirmedAfterInspectionCount,
                                                                 Integer blockThresholdCount,
                                                                 String warningMessage) {
        HcPressSlotScanGateRespVO respVO = new HcPressSlotScanGateRespVO();
        respVO.setAllowScan(true);
        respVO.setWarningMessage(warningMessage);
        respVO.setConfirmedAfterInspectionCount(confirmedAfterInspectionCount);
        respVO.setWarningThresholdCount(PRESS_SLOT_FAI_WARNING_THRESHOLD);
        respVO.setBlockThresholdCount(blockThresholdCount);
        return respVO;
    }

    private int resolvePressSlotFaiBlockThreshold(HcPlanOrderDO planOrder) {
        if (planOrder == null || planOrder.getBomId() == null) {
            return PRESS_SLOT_FAI_BLOCK_DEFAULT_LIMIT;
        }
        HcBomDO bom = hcBomMapper.selectById(planOrder.getBomId());
        Integer configuredCount = bom == null ? null : bom.getPressSlotContinuousCheckCount();
        return configuredCount != null && configuredCount > 0
                ? configuredCount
                : PRESS_SLOT_FAI_BLOCK_DEFAULT_LIMIT;
    }

    private List<QmsFaiOrderDO> listPressSlotFirstInspectionOrdersForTaskScope(HcPlanOrderDO planOrder,
                                                                               HcPlanOrderOperationDO operation,
                                                                               String motherBatchNo) {
        if (planOrder == null || operation == null) {
            return Collections.emptyList();
        }
        return qmsFaiOrderMapper.selectListBySourceReportNo(
                        buildPressSlotTaskNo(planOrder, operation), SOURCE_MENU_CODE_PRESS_SLOT, null)
                .stream()
                .filter(item -> !isPressSlotProcessCheckFaiOrder(item))
                .filter(item -> StrUtil.isBlank(motherBatchNo)
                        || StrUtil.equalsIgnoreCase(resolvePressSlotFaiMotherBatchNo(item), motherBatchNo))
                .sorted(Comparator
                        .comparing((QmsFaiOrderDO item) -> firstNotNullDateTime(
                                item.getSubmissionTime(), item.getCreateTime(), LocalDateTime.MIN))
                        .thenComparing(item -> item.getId() == null ? 0L : item.getId())
                        .reversed())
                .toList();
    }

    /**
     * 首检和过程加检以计划工序、母批为有效范围，不能在自然日切换后自动失效。
     */
    private List<QmsFaiOrderDO> listPressSlotInspectionOrdersForTaskScope(HcPlanOrderDO planOrder,
                                                                            HcPlanOrderOperationDO operation,
                                                                            String motherBatchNo) {
        if (planOrder == null || operation == null) {
            return Collections.emptyList();
        }
        List<QmsFaiOrderDO> result = new ArrayList<>(listPressSlotFirstInspectionOrdersForTaskScope(
                planOrder, operation, motherBatchNo));
        String processCheckPrefix = buildPressSlotProcessCheckFaiSourceReportNoPrefix(planOrder, operation);
        qmsFaiOrderMapper.selectListBySourceReportNoPrefix(processCheckPrefix, SOURCE_MENU_CODE_PRESS_SLOT)
                .stream()
                .filter(item -> !isPressSlotAbnormalReleaseFaiOrder(item))
                .filter(item -> StrUtil.isBlank(motherBatchNo)
                        || StrUtil.equalsIgnoreCase(resolvePressSlotFaiMotherBatchNo(item), motherBatchNo))
                .forEach(result::add);
        return result.stream()
                .sorted(Comparator
                        .comparing((QmsFaiOrderDO item) -> firstNotNullDateTime(
                                item.getSubmissionTime(), item.getCreateTime(), LocalDateTime.MIN))
                        .thenComparing(item -> item.getId() == null ? 0L : item.getId())
                        .reversed())
                .toList();
    }

    private LocalDate resolvePressSlotFaiInspectionDate(QmsFaiOrderDO faiOrder) {
        LocalDateTime time = firstNotNullDateTime(
                faiOrder == null ? null : faiOrder.getSubmissionTime(),
                faiOrder == null ? null : faiOrder.getCreateTime(),
                faiOrder == null ? null : faiOrder.getUpdateTime());
        return time == null ? LocalDate.now() : time.toLocalDate();
    }

    private LocalDateTime resolvePressSlotReportControlEventTime(HcPressSlotReportDO report) {
        if (report == null) {
            return null;
        }
        return firstNotNullDateTime(report.getConfirmerTime(), report.getUpdateTime(), report.getCreateTime());
    }

    private boolean isPressSlotInspectionResultReturned(QmsFaiOrderDO faiOrder) {
        if (faiOrder == null) {
            return false;
        }
        String status = StrUtil.blankToDefault(faiOrder.getStatus(), "");
        String judgment = StrUtil.blankToDefault(faiOrder.getJudgment(), "");
        return FAI_STATUS_COMPLETED.equals(status)
                || FAI_STATUS_REJECTED.equals(status)
                || (StrUtil.isNotBlank(judgment) && !FAI_JUDGMENT_PENDING.equals(judgment));
    }

    private String resolvePressSlotFaiMotherBatchNo(QmsFaiOrderDO faiOrder) {
        if (faiOrder == null) {
            return "";
        }
        String productMotherBatchNo = normalizePressSlotMiddleBatchNo(faiOrder.getProductBatchNo());
        if (StrUtil.isNotBlank(productMotherBatchNo)) {
            return productMotherBatchNo;
        }
        if (faiOrder.getSourceReportId() == null) {
            return "";
        }
        HcPressSlotReportDO sourceReport = hcPressSlotReportMapper.selectById(faiOrder.getSourceReportId());
        return resolvePressSlotReportMotherBatchNo(sourceReport);
    }

    private boolean isPressSlotProcessCheckFaiOrder(QmsFaiOrderDO faiOrder) {
        return faiOrder != null
                && StrUtil.blankToDefault(faiOrder.getSourceReportNo(), "")
                .toUpperCase()
                .contains("-PROCESS-CHECK-");
    }

    /** NG 后只有新的首检送检可以恢复报工；再次 NG 再次要求首检。 */
    private QmsFaiOrderDO findPressSlotPendingRestartNg(List<QmsFaiOrderDO> orders) {
        return orders.stream()
                .filter(order -> !FAI_STATUS_CANCELED.equals(order.getStatus()))
                .filter(order -> isPressSlotProcessCheckFaiOrder(order)
                        || isPressSlotProcessCheckNgRestartFaiOrder(order))
                .filter(order -> FAI_JUDGMENT_NG.equals(order.getJudgment()))
                .filter(ng -> orders.stream().noneMatch(restart ->
                        !isPressSlotProcessCheckFaiOrder(restart)
                                && !isPressSlotAbnormalReleaseFaiOrder(restart)
                                && isPressSlotFaiSubmitted(restart)
                                && isPressSlotRestartSubmittedAfterNg(restart, ng)))
                .max(Comparator.comparing(this::resolvePressSlotInspectionSubmissionTime,
                        Comparator.nullsFirst(Comparator.naturalOrder()))
                        .thenComparing(QmsFaiOrderDO::getId, Comparator.nullsFirst(Comparator.naturalOrder())))
                .orElse(null);
    }

    private boolean isPressSlotRestartSubmittedAfterNg(QmsFaiOrderDO restart, QmsFaiOrderDO ng) {
        // 检验顺序以送检时间为准，旧样品晚反馈 NG 不应覆盖后续已送检的首检。
        LocalDateTime ngSubmissionTime = resolvePressSlotInspectionSubmissionTime(ng);
        LocalDateTime submissionTime = resolvePressSlotInspectionSubmissionTime(restart);
        return submissionTime != null && ngSubmissionTime != null
                && (submissionTime.isAfter(ngSubmissionTime)
                || (submissionTime.equals(ngSubmissionTime) && restart.getId() != null && ng.getId() != null
                && restart.getId() > ng.getId()));
    }

    private boolean isPressSlotProcessCheckNgRestartFaiOrder(QmsFaiOrderDO faiOrder) {
        return faiOrder != null && PRESS_SLOT_FAI_TRIGGER_PROCESS_CHECK_NG_RESTART
                .equalsIgnoreCase(StrUtil.trimToEmpty(faiOrder.getTriggerReason()));
    }

    private boolean isPressSlotAdditionalFirstInspectionFaiOrder(QmsFaiOrderDO faiOrder) {
        return faiOrder != null && PRESS_SLOT_FAI_TRIGGER_ADDITIONAL_FIRST_INSPECTION
                .equalsIgnoreCase(StrUtil.trimToEmpty(faiOrder.getTriggerReason()));
    }

    private boolean isPressSlotProcessCheckSample(String extraJson) {
        Map<String, Object> extra = parseRoughExtraMap(extraJson);
        return PRESS_SLOT_INSPECTION_SAMPLE_CATEGORY_PROCESS_CHECK.equalsIgnoreCase(
                StrUtil.trimToEmpty(String.valueOf(extra.get("inspectionSampleCategory"))))
                || INSPECTION_SCENE_PROCESS_CHECK.equalsIgnoreCase(
                StrUtil.trimToEmpty(String.valueOf(extra.get("inspectionScene"))))
                || INSPECTION_SCENE_PROCESS_CHECK.equalsIgnoreCase(
                StrUtil.trimToEmpty(String.valueOf(extra.get("reportType"))));
    }

    private long countPressSlotConfirmedReportsAfterFai(HcPlanOrderOperationDO operation,
                                                        String motherBatchNo,
                                                        QmsFaiOrderDO anchorFai,
                                                        String currentBatchNo) {
        if (operation == null || operation.getId() == null || StrUtil.isBlank(motherBatchNo) || anchorFai == null) {
            return 0L;
        }
        LocalDateTime anchorTime = firstNotNullDateTime(anchorFai.getSubmissionTime(), anchorFai.getCreateTime());
        String anchorBatchNo = StrUtil.trimToEmpty(anchorFai.getProductBatchNo());
        String currentNormalizedBatchNo = StrUtil.trimToEmpty(currentBatchNo);
        return hcPressSlotReportMapper.selectListByPlanOperationId(operation.getId()).stream()
                .filter(item -> isPressSlotConfirmedReport(item))
                .filter(item -> StrUtil.equalsIgnoreCase(resolvePressSlotReportMotherBatchNo(item), motherBatchNo))
                .filter(item -> isPressSlotReportConfirmedAfter(item, anchorTime))
                .filter(item -> !StrUtil.equalsIgnoreCase(StrUtil.trimToEmpty(item.getProductionBatchNo()), anchorBatchNo))
                .filter(item -> StrUtil.isBlank(currentNormalizedBatchNo)
                        || !StrUtil.equalsIgnoreCase(StrUtil.trimToEmpty(item.getProductionBatchNo()), currentNormalizedBatchNo))
                .count();
    }

    private boolean isPressSlotConfirmedReport(HcPressSlotReportDO report) {
        if (report == null || Boolean.TRUE.equals(report.getDeleted())) {
            return false;
        }
        String status = StrUtil.blankToDefault(report.getReportStatus(), "");
        return "CONFIRMED".equalsIgnoreCase(status) || "SUBMITTED".equalsIgnoreCase(status);
    }

    private boolean isPressSlotReportConfirmedAfter(HcPressSlotReportDO report, LocalDateTime anchorTime) {
        if (report == null) {
            return false;
        }
        if (anchorTime == null) {
            return true;
        }
        LocalDateTime confirmTime = firstNotNullDateTime(report.getConfirmerTime(), report.getUpdateTime(), report.getCreateTime());
        return confirmTime != null && confirmTime.isAfter(anchorTime);
    }

    private String resolvePressSlotFaiMotherBatchNo(HcPlanOrderDO planOrder, HcPlanOrderOperationDO operation,
                                                    HcProcessReportDO latestStartReport, String explicitBatchNo) {
        return normalizePressSlotMiddleBatchNo(firstNotBlank(explicitBatchNo,
                latestStartReport == null ? null : latestStartReport.getProductionBatchNo(),
                latestStartReport == null ? null : latestStartReport.getBatchNo(),
                latestStartReport == null ? null : latestStartReport.getParentProductionBatchNo(),
                latestStartReport == null ? null : latestStartReport.getParentBatchNo(),
                operation == null ? null : operation.getProductionBatchNo(),
                operation == null ? null : operation.getBatchNo(),
                operation == null ? null : operation.getParentProductionBatchNo(),
                planOrder == null ? null : planOrder.getProductionBatchNo(),
                planOrder == null ? null : planOrder.getBatchNo(),
                planOrder == null ? null : planOrder.getParentProductionBatchNo()));
    }

    private HcWetFaiRespVO buildPressSlotFaiResp(QmsFaiOrderDO faiOrder, HcProcessReportDO pressSlotReport,
                                                 List<QmsFaiOrderDO> sameScopeFaiOrders,
                                                 String motherBatchNo, LocalDate inspectionDate) {
        List<QmsFaiOrderDO> recordOrders = sameScopeFaiOrders == null ? Collections.emptyList() : sameScopeFaiOrders.stream()
                .sorted(Comparator.comparing(QmsFaiOrderDO::getId))
                .toList();
        HcWetFaiRespVO respVO = buildWetFaiResp(faiOrder, faiOrder == null ? null : pressSlotReport,
                recordOrders);
        LocalDate effectiveInspectionDate = inspectionDate == null
                ? resolvePressSlotFaiInspectionDate(faiOrder) : inspectionDate;
        respVO.setInspectionDate(effectiveInspectionDate);
        respVO.setInspectionScopeBatchNo(motherBatchNo);
        respVO.setTodayInspected(faiOrder != null && LocalDate.now().equals(effectiveInspectionDate));
        respVO.setAllowReportSubmit(isPressSlotFaiSubmitted(faiOrder));
        return respVO;
    }

    private LocalDateTime resolvePressSlotInspectionSubmissionTime(QmsFaiOrderDO faiOrder) {
        return firstNotNullDateTime(faiOrder == null ? null : faiOrder.getSubmissionTime(),
                faiOrder == null ? null : faiOrder.getCreateTime(),
                faiOrder == null ? null : faiOrder.getUpdateTime());
    }

    private boolean isPressSlotFaiReapplyAllowed(QmsFaiOrderDO faiOrder) {
        return isFaiReapplyAllowed(faiOrder)
                || (faiOrder != null && FAI_STATUS_COMPLETED.equals(faiOrder.getStatus())
                && FAI_JUDGMENT_NG.equals(faiOrder.getJudgment()));
    }

    private String resolvePressSlotReportMotherBatchNo(HcPressSlotReportDO report) {
        if (report == null) {
            return "";
        }
        return normalizePressSlotMiddleBatchNo(firstNotBlank(report.getSourceProductionBatchNo(),
                report.getProductionBatchNo(), report.getParentProductionBatchNo(), report.getSourceBatchNo()));
    }

    private String buildPressSlotTaskNo(HcPlanOrderDO planOrder, HcPlanOrderOperationDO operation) {
        return planOrder.getPlanNo() + "-" + String.format("%02d", operation.getOpSeq() == null ? 0 : operation.getOpSeq());
    }

    private void syncPressSlotReportFaiSummary(HcProcessReportDO pressSlotStartReport, QmsFaiOrderDO faiOrder) {
        syncWetReportFaiSummary(pressSlotStartReport, faiOrder);
        syncPressSlotFirstInspectionSampleReport(pressSlotStartReport, faiOrder);
    }

    private void syncPressSlotFirstInspectionSampleReport(HcProcessReportDO pressSlotStartReport, QmsFaiOrderDO faiOrder) {
        if (pressSlotStartReport == null || !isTerminalPressSlotFirstInspectionFai(faiOrder)) {
            return;
        }
        String sampleBatchNo = StrUtil.trimToEmpty(faiOrder.getProductBatchNo());
        if (StrUtil.isBlank(sampleBatchNo)) {
            return;
        }
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(pressSlotStartReport.getPlanId());
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(pressSlotStartReport.getPlanOperationId());
        if (planOrder == null || operation == null) {
            return;
        }
        HcSlittingSliceRecordDO sourceSlice = hcSlittingSliceRecordMapper.selectBySerialNo(sampleBatchNo);
        HcPressSlotReportDO existedReport = hcPressSlotReportMapper.selectByProductionBatchNo(sampleBatchNo);
        if (existedReport == null && sourceSlice != null && sourceSlice.getId() != null) {
            existedReport = hcPressSlotReportMapper.selectListBySourceSliceId(sourceSlice.getId()).stream()
                    .filter(item -> sampleBatchNo.equalsIgnoreCase(StrUtil.trimToEmpty(item.getProductionBatchNo())))
                    .findFirst()
                    .orElse(null);
        }
        if (existedReport != null && (!Objects.equals(existedReport.getPlanId(), planOrder.getId())
                || !Objects.equals(existedReport.getPlanOperationId(), operation.getId()))) {
            return;
        }

        String judgment = FAI_JUDGMENT_NG.equalsIgnoreCase(StrUtil.blankToDefault(faiOrder.getJudgment(), ""))
                ? FAI_JUDGMENT_NG : FAI_JUDGMENT_OK;
        LocalDateTime confirmTime = firstNotNullDateTime(faiOrder.getQaTime(), faiOrder.getOperatorTime(),
                faiOrder.getUpdateTime(), LocalDateTime.now());
        LocalDateTime recordTime = firstNotNullDateTime(faiOrder.getSubmissionTime(), faiOrder.getCreateTime(), confirmTime);
        LocalDate reportDate = recordTime.toLocalDate();
        String operatorName = firstNotBlank(faiOrder.getQaInspectorName(), faiOrder.getOperatorName(),
                faiOrder.getSubmitterName(), pressSlotStartReport.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        String remark = buildPressSlotFirstInspectionSampleRemark(faiOrder, judgment);
        String extraJson = buildPressSlotFirstInspectionSampleExtra(existedReport, faiOrder, judgment);

        if (existedReport == null) {
            HcPressSlotReportDO report = HcPressSlotReportDO.builder()
                    .tenantId(planOrder.getTenantId())
                    .planId(planOrder.getId())
                    .planNo(planOrder.getPlanNo())
                    .planOperationId(operation.getId())
                    .operationCode(firstNotBlank(operation.getOpCode(), faiOrder.getOperationCode()))
                    .operationName(firstNotBlank(operation.getOpName(), faiOrder.getOperationName()))
                    .sourceSlittingSliceId(sourceSlice == null ? null : sourceSlice.getId())
                    .sourceBatchNo(sourceSlice == null ? null : sourceSlice.getSourceBatchNo())
                    .sourceProductionBatchNo(firstNotBlank(sourceSlice == null ? null : sourceSlice.getSliceSerialNo(), sampleBatchNo))
                    .productionBatchNo(sampleBatchNo)
                    .parentProductionBatchNo(resolvePressSlotFaiMotherBatchNo(planOrder, operation, pressSlotStartReport, sampleBatchNo))
                    .materialCode(firstNotBlank(pressSlotStartReport.getMaterialCode(), planOrder.getMaterialCode()))
                    .materialName(firstNotBlank(pressSlotStartReport.getMaterialName(), planOrder.getMaterialName()))
                    .modelCode(firstNotBlank(faiOrder.getProductModel(), planOrder.getModelCode(), planOrder.getModelName()))
                    .reportDate(reportDate)
                    .startTime(recordTime)
                    .endTime(confirmTime)
                    .inputLength(BigDecimal.ONE)
                    .startPosition(sourceSlice == null ? null : sourceSlice.getStartPosition())
                    .endPosition(sourceSlice == null ? null : sourceSlice.getEndPosition())
                    .lossLength(BigDecimal.ZERO)
                    .outputLength(BigDecimal.ZERO)
                    .napSampleLength(BigDecimal.ONE)
                    .selfCheck(judgment)
                    .reportStatus("CONFIRMED")
                    .recorderName(firstNotBlank(faiOrder.getSubmitterName(), operatorName))
                    .recorderTime(recordTime)
                    .confirmerName(operatorName)
                    .confirmerTime(confirmTime)
                    .remark(remark)
                    .extraJson(extraJson)
                    .build();
            report.setRecorderName(recorderNameResolver.resolveForSave(report.getRecorderName()));
            hcPressSlotReportMapper.insert(report);
            syncPressSlotChangeoverInspectionFeedback(operation.getId(), sampleBatchNo, faiOrder, judgment, confirmTime);
            return;
        }

        HcPressSlotReportDO updateReport = new HcPressSlotReportDO();
        updateReport.setId(existedReport.getId());
        if (!"SUBMITTED".equalsIgnoreCase(StrUtil.blankToDefault(existedReport.getReportStatus(), "DRAFT"))) {
            updateReport.setReportStatus("CONFIRMED");
            updateReport.setConfirmerName(firstNotBlank(existedReport.getConfirmerName(), operatorName));
            updateReport.setConfirmerTime(firstNotNullDateTime(existedReport.getConfirmerTime(), confirmTime));
        }
        updateReport.setSelfCheck(judgment);
        updateReport.setRemark(firstNotBlank(existedReport.getRemark(), remark));
        updateReport.setExtraJson(extraJson);
        hcPressSlotReportMapper.updateById(updateReport);
        syncPressSlotChangeoverInspectionFeedback(operation.getId(), sampleBatchNo, faiOrder, judgment, confirmTime);
    }

    private boolean isTerminalPressSlotFirstInspectionFai(QmsFaiOrderDO faiOrder) {
        if (faiOrder == null || !SOURCE_MENU_CODE_PRESS_SLOT.equalsIgnoreCase(StrUtil.blankToDefault(faiOrder.getSourceModule(), ""))
                || !PROCESS_CODE_PRESS_SLOT.equalsIgnoreCase(StrUtil.blankToDefault(faiOrder.getProcessCategory(), ""))) {
            return false;
        }
        String sourceReportNo = StrUtil.trimToEmpty(faiOrder.getSourceReportNo()).toUpperCase();
        if (sourceReportNo.contains("-PROCESS-CHECK-") || sourceReportNo.contains("-ABNORMAL-RELEASE-")) {
            return false;
        }
        String status = StrUtil.blankToDefault(faiOrder.getStatus(), "");
        String judgment = StrUtil.blankToDefault(faiOrder.getJudgment(), "");
        return (FAI_STATUS_COMPLETED.equals(status) || FAI_STATUS_REJECTED.equals(status))
                && (FAI_JUDGMENT_OK.equals(judgment) || FAI_JUDGMENT_NG.equals(judgment));
    }

    private String buildPressSlotFirstInspectionSampleRemark(QmsFaiOrderDO faiOrder, String judgment) {
        return "压槽首检样片已确认；首检结果：" + judgment
                + "；首检单号：" + StrUtil.blankToDefault(faiOrder == null ? null : faiOrder.getFaiNo(), "-");
    }

    private String buildPressSlotFirstInspectionSampleExtra(HcPressSlotReportDO existedReport,
                                                            QmsFaiOrderDO faiOrder,
                                                            String judgment) {
        Map<String, Object> extra = new LinkedHashMap<>(parseRoughExtraMap(existedReport == null ? null : existedReport.getExtraJson()));
        extra.put("reportType", "CHANGEOVER");
        extra.put("reportTypeName", "首检");
        extra.put("faiFirstInspectionSample", true);
        extra.put("inspectionScene", PRESS_SLOT_INSPECTION_SAMPLE_CATEGORY_FIRST);
        extra.put("inspectionSampleCategory", PRESS_SLOT_INSPECTION_SAMPLE_CATEGORY_FIRST);
        extra.put("inspectionSampleCategoryName", "首检送检");
        extra.put("sourceMenuCode", SOURCE_MENU_CODE_PRESS_SLOT_FAI);
        extra.put("faiId", faiOrder.getId());
        extra.put("faiNo", faiOrder.getFaiNo());
        extra.put("faiStatus", faiOrder.getStatus());
        extra.put("faiJudgment", faiOrder.getJudgment());
        extra.put("visualInspectionResult", judgment);
        extra.put("visualInspectionRemark", firstNotBlank(faiOrder.getLastReturnReason(), buildPressSlotFirstInspectionSampleRemark(faiOrder, judgment)));
        return JsonUtils.toJsonString(extra);
    }

    private void syncPressSlotChangeoverInspectionFeedback(Long planOperationId,
                                                           String sampleBatchNo,
                                                           QmsFaiOrderDO faiOrder,
                                                           String judgment,
                                                           LocalDateTime feedbackTime) {
        if (planOperationId == null || StrUtil.isBlank(sampleBatchNo)) {
            return;
        }
        HcPressSlotChangeoverInspectionDO record = hcPressSlotChangeoverInspectionMapper
                .selectListByPlanOperation(planOperationId, null)
                .stream()
                .filter(item -> sampleBatchNo.equalsIgnoreCase(StrUtil.trimToEmpty(item.getPressSlotSliceNo())))
                .findFirst()
                .orElse(null);
        if (record == null) {
            return;
        }
        HcPressSlotChangeoverInspectionDO updateRecord = new HcPressSlotChangeoverInspectionDO();
        updateRecord.setId(record.getId());
        updateRecord.setInspectionStatus(FAI_JUDGMENT_NG.equals(judgment) ? "ABNORMAL" : "QUALIFIED");
        updateRecord.setFeedbackResult(judgment);
        updateRecord.setFeedbackRemark(firstNotBlank(faiOrder.getLastReturnReason(), buildPressSlotFirstInspectionSampleRemark(faiOrder, judgment)));
        updateRecord.setFeedbackTime(firstNotNullDateTime(feedbackTime, faiOrder.getUpdateTime(), LocalDateTime.now()));
        hcPressSlotChangeoverInspectionMapper.updateById(updateRecord);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long startPressSlotReport(HcAdhesiveReportStartReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectByIdForUpdate(reqVO.getPlanId());
        assertPlanReleasedForStart(planOrder);
        HcPlanOrderOperationDO operation = validatePressSlotOperation(planOrder, reqVO.getPlanOperationId());
        if (OP_STATUS_FINISHED.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序已完工，不能再开工");
        }
        if (OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前工序已开工");
        }
        LocalDate reportDate = reqVO.getReportDate() == null ? LocalDate.now() : reqVO.getReportDate();
        boolean placeholderStartTime = isPlaceholderDateTime(reqVO.getStartTime())
                || isDateOnlyRuntimeDateTime(reqVO.getStartTime(), reportDate);
        boolean placeholderRecorderTime = isPlaceholderDateTime(reqVO.getRecorderTime())
                || isDateOnlyRuntimeDateTime(reqVO.getRecorderTime(), reportDate);
        LocalDateTime normalizedStartTime = normalizeReportDateTime(reqVO.getStartTime(), reportDate);
        LocalDateTime normalizedRecorderTime = normalizeReportDateTime(reqVO.getRecorderTime(), reportDate);
        LocalDateTime now = LocalDateTime.now();
        if (normalizedStartTime == null || placeholderStartTime) {
            normalizedStartTime = now;
        }
        if (normalizedRecorderTime == null || placeholderRecorderTime) {
            normalizedRecorderTime = now;
        }
        Long effectiveEquipmentId = firstNotNull(reqVO.getEquipmentId(), operation.getEquipmentId());
        String effectiveEquipmentCode = firstNotBlank(reqVO.getEquipmentCode(), operation.getEquipmentCode());
        String effectiveEquipmentName = firstNotBlank(reqVO.getEquipmentName(), operation.getEquipmentName());
        if (effectiveEquipmentId == null && StrUtil.isBlank(effectiveEquipmentCode)) {
            throw invalidParamException("请先选择压槽设备，再执行开工");
        }

        HcProcessReportDO reportDO = HcProcessReportDO.builder()
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .operationStatus(operation.getOperationStatus())
                .operationSeq(operation.getOpSeq())
                .operationCode(operation.getOpCode())
                .operationName(operation.getOpName())
                .workCenterId(operation.getWorkCenterId())
                .workCenterCode(operation.getWorkCenterCode())
                .workCenterName(operation.getWorkCenterName())
                .equipmentId(effectiveEquipmentId)
                .equipmentCode(effectiveEquipmentCode)
                .equipmentName(effectiveEquipmentName)
                .materialId(planOrder.getMaterialId())
                .materialCode(planOrder.getMaterialCode())
                .materialName(planOrder.getMaterialName())
                .motherMaterialId(planOrder.getMotherMaterialId())
                .motherMaterialCode(firstNotBlank(operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode()))
                .motherMaterialName(firstNotBlank(operation.getMotherMaterialName(), planOrder.getMotherMaterialName()))
                .motherModelId(planOrder.getMotherModelId())
                .motherModelCode(firstNotBlank(operation.getMotherModelCode(), planOrder.getMotherModelCode()))
                .motherModelName(firstNotBlank(operation.getMotherModelName(), planOrder.getMotherModelName()))
                .batchNo(firstNotBlank(operation.getProductionBatchNo(), planOrder.getProductionBatchNo(), planOrder.getBatchNo(), operation.getBatchNo()))
                .productionBatchNo(firstNotBlank(operation.getProductionBatchNo(), planOrder.getProductionBatchNo()))
                .parentProductionBatchNo(firstNotBlank(operation.getParentProductionBatchNo(), operation.getParentBatchNo(), planOrder.getProductionBatchNo(), planOrder.getBatchNo()))
                .parentBatchNo(firstNotBlank(operation.getParentBatchNo(), planOrder.getBatchNo()))
                .sampleCode(operation.getSampleCode())
                .reportDate(reportDate)
                .startTime(normalizedStartTime)
                .goodQty(BigDecimal.ZERO)
                .scrapQty(BigDecimal.ZERO)
                .recorderName(reqVO.getRecorderName())
                .recorderTime(normalizedRecorderTime)
                .reportUom(firstNotBlank(operation.getUom(), operation.getUnitCode(), operation.getUnitName(), planOrder.getTargetUom()))
                .reportType(REPORT_TYPE_START)
                .sourceMenuCode(SOURCE_MENU_CODE_PRESS_SLOT)
                .build();
        hcProcessReportMapper.insert(reportDO);

        HcPlanOrderOperationDO updateObj = new HcPlanOrderOperationDO();
        updateObj.setId(operation.getId());
        updateObj.setOperationStatus(OP_STATUS_RUNNING);
        updateObj.setEquipmentId(effectiveEquipmentId);
        updateObj.setEquipmentCode(effectiveEquipmentCode);
        updateObj.setEquipmentName(effectiveEquipmentName);
        updateObj.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateObj.setStatusOperatorName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "system"));
        updateObj.setStatusOperateTime(LocalDateTime.now());
        hcPlanOrderOperationMapper.updateById(updateObj);

        String operatorName = firstNotBlank(reqVO.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        if (effectiveEquipmentId != null) {
            hcEquipmentService.occupyEquipment(effectiveEquipmentId, planOrder.getPlanNo(), operation.getOpCode(),
                    operation.getOpName(), normalizedStartTime, operatorName, normalizedRecorderTime);
        }
        return reportDO.getId();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void switchPressSlotEquipment(HcAdhesiveReportSwitchEquipmentReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validatePressSlotOperation(planOrder, reqVO.getPlanOperationId());
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前压槽工序未开工，不能切换设备");
        }
        HcProcessReportDO latestReport = getLatestStartReport(operation.getId(), SOURCE_MENU_CODE_PRESS_SLOT);
        if (latestReport == null) {
            throw invalidParamException("当前压槽工序未找到开工记录，不能切换设备");
        }
        Long oldEquipmentId = firstNotNull(latestReport.getEquipmentId(), operation.getEquipmentId());
        String oldEquipmentCode = firstNotBlank(latestReport.getEquipmentCode(), operation.getEquipmentCode());
        String oldEquipmentName = firstNotBlank(latestReport.getEquipmentName(), operation.getEquipmentName());
        Long newEquipmentId = firstNotNull(reqVO.getEquipmentId(), oldEquipmentId);
        String newEquipmentCode = firstNotBlank(reqVO.getEquipmentCode(), oldEquipmentCode);
        String newEquipmentName = firstNotBlank(reqVO.getEquipmentName(), oldEquipmentName);
        if (newEquipmentId == null && StrUtil.isBlank(newEquipmentCode)) {
            throw invalidParamException("请选择新的压槽设备");
        }

        String operatorName = firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        LocalDateTime recordTime = LocalDateTime.now();
        LocalDateTime startTime = latestReport.getStartTime() != null ? latestReport.getStartTime() : recordTime;
        if (!Objects.equals(oldEquipmentId, newEquipmentId)) {
            if (oldEquipmentId != null) {
                hcEquipmentService.releaseEquipment(oldEquipmentId, null, operatorName, recordTime);
            }
            if (newEquipmentId != null) {
                hcEquipmentService.occupyEquipment(newEquipmentId, planOrder.getPlanNo(), operation.getOpCode(),
                        operation.getOpName(), startTime, operatorName, recordTime);
            }
        }

        HcProcessReportDO updateReport = new HcProcessReportDO();
        updateReport.setId(latestReport.getId());
        updateReport.setEquipmentId(newEquipmentId);
        updateReport.setEquipmentCode(newEquipmentCode);
        updateReport.setEquipmentName(newEquipmentName);
        hcProcessReportMapper.updateById(updateReport);

        HcPlanOrderOperationDO updateOperation = new HcPlanOrderOperationDO();
        updateOperation.setId(operation.getId());
        updateOperation.setEquipmentId(newEquipmentId);
        updateOperation.setEquipmentCode(newEquipmentCode);
        updateOperation.setEquipmentName(newEquipmentName);
        updateOperation.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateOperation.setStatusOperatorName(operatorName);
        updateOperation.setStatusOperateTime(recordTime);
        hcPlanOrderOperationMapper.updateById(updateOperation);
    }

    @Override
    public List<HcWetPassWorkRespVO> getPressSlotPassWorkList(Long planId, Long planOperationId,
                                                              Long equipmentId, LocalDate requestRecordDate) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        HcPlanOrderOperationDO operation = validatePressSlotOperation(planOrder, planOperationId);
        LocalDate recordDate = requestRecordDate == null ? LocalDate.now() : requestRecordDate;
        Long effectiveEquipmentId = equipmentId != null ? equipmentId : operation.getEquipmentId();
        List<HcStationFormDO> forms = hcStationFormMapper.selectEnabledByProcess(PROCESS_CODE_PRESS_SLOT).stream()
                .filter(form -> !"IN_PROCESS".equalsIgnoreCase(StrUtil.blankToDefault(form.getTriggerTimingCode(), ""))
                        && !PRESS_SLOT_PROCESS_CHECK_FORM_CODE.equals(form.getFormCode()))
                .toList();
        if (forms.isEmpty()) {
            return Collections.emptyList();
        }
        Set<Long> formIds = forms.stream().map(HcStationFormDO::getId).collect(Collectors.toSet());
        Map<Long, List<HcStationFormItemDO>> templateItemMap = hcStationFormItemMapper.selectByFormIds(formIds).stream()
                .collect(Collectors.groupingBy(HcStationFormItemDO::getFormId, LinkedHashMap::new, Collectors.toList()));
        Map<Long, HcStationRecordDO> recordMap = new LinkedHashMap<>();
        if (effectiveEquipmentId != null) {
            Set<String> formCodes = forms.stream().map(HcStationFormDO::getFormCode).collect(Collectors.toSet());
            for (HcStationRecordDO record : hcStationRecordMapper.selectListByEquipmentDaily(effectiveEquipmentId, recordDate, formCodes)) {
                recordMap.putIfAbsent(record.getFormId(), record);
            }
        }
        if (recordMap.isEmpty()) {
            for (HcStationRecordDO record : hcStationRecordMapper.selectByPlanOperationAndFormIds(planOperationId, formIds)) {
                recordMap.putIfAbsent(record.getFormId(), record);
            }
        }
        Set<Long> recordIds = recordMap.values().stream().map(HcStationRecordDO::getId).collect(Collectors.toSet());
        Map<Long, List<HcStationRecordItemDO>> recordItemMap = hcStationRecordItemMapper.selectByRecordIds(recordIds).stream()
                .collect(Collectors.groupingBy(HcStationRecordItemDO::getRecordId, LinkedHashMap::new, Collectors.toList()));

        List<HcWetPassWorkRespVO> result = new ArrayList<>();
        for (HcStationFormDO form : forms) {
            HcStationRecordDO record = recordMap.get(form.getId());
            HcWetPassWorkRespVO respVO = new HcWetPassWorkRespVO();
            respVO.setRecordId(record != null ? record.getId() : null);
            respVO.setFormId(form.getId());
            respVO.setFormCode(form.getFormCode());
            respVO.setName(form.getFormName());
            respVO.setTiming(form.getTriggerTimingName());
            respVO.setStatus(record == null ? "NOT_FILLED" : record.getDocStatus());
            respVO.setResult(record == null ? null : record.getResultStatus());
            respVO.setRecordDate(record == null || record.getRecordDate() == null ? null : record.getRecordDate().toString());
            respVO.setRecorder(record == null ? null : record.getRecordUserName());
            respVO.setRecorderTime(formatDateTime(record == null ? null : record.getRecordTime()));
            respVO.setConfirmer(record == null ? null : record.getConfirmUserName());
            respVO.setConfirmerTime(formatDateTime(record == null ? null : record.getConfirmTime()));
            respVO.setFormRemark(record == null ? form.getRemark() : record.getFormRemark());
            respVO.setConfirmRemark(record == null ? null : record.getConfirmRemark());
            respVO.setInspectionResult(record == null ? null : record.getInspectionResult());
            respVO.setHeaderDataJson(record == null ? form.getPresetHeaderDataJson() : record.getHeaderDataJson());
            respVO.setSchemaJson(form.getSchemaJson());
            respVO.setPresetHeaderDataJson(form.getPresetHeaderDataJson());
            respVO.setCanFill(true);
            respVO.setCanConfirm(true);
            respVO.setCanView(record != null);
            respVO.setDetails(buildWetPassWorkDetails(recordItemMap.get(record != null ? record.getId() : null), templateItemMap.get(form.getId())));
            result.add(respVO);
        }
        return result;
    }

    private void validatePressSlotDailyPreparationRecorded(HcPlanOrderOperationDO operation) {
        List<HcStationFormDO> forms = hcStationFormMapper.selectEnabledByProcess(PROCESS_CODE_PRESS_SLOT).stream()
                .filter(form -> !"IN_PROCESS".equalsIgnoreCase(StrUtil.blankToDefault(form.getTriggerTimingCode(), ""))
                        && !PRESS_SLOT_PROCESS_CHECK_FORM_CODE.equals(form.getFormCode()))
                .toList();
        if (forms.isEmpty()) {
            return;
        }
        if (operation == null || operation.getEquipmentId() == null) {
            throw invalidParamException("当前压槽工序未绑定设备，不能校验今日点检/清洁记录");
        }
        Set<String> formCodes = forms.stream().map(HcStationFormDO::getFormCode).collect(Collectors.toSet());
        boolean recorded = hcStationRecordMapper.selectListByEquipmentDaily(operation.getEquipmentId(), LocalDate.now(), formCodes)
                .stream()
                .anyMatch(this::isPressSlotDailyPreparationRecordRecorded);
        if (!recorded) {
            throw invalidParamException("请先填写今日点检/清洁记录，保存任一点检/清洁记录后即可继续报工");
        }
    }

    private boolean isPressSlotDailyPreparationRecordRecorded(HcStationRecordDO record) {
        if (record == null || Boolean.TRUE.equals(record.getDeleted())) {
            return false;
        }
        String status = StrUtil.blankToDefault(record.getDocStatus(), "");
        return RECORD_STATUS_RECORDED.equalsIgnoreCase(status)
                || RECORD_STATUS_CONFIRMED.equalsIgnoreCase(status)
                || "FILLED".equalsIgnoreCase(status)
                || "COMPLETED".equalsIgnoreCase(status)
                || "WAITING".equalsIgnoreCase(status);
    }

