    @Override
    public HcAdhesiveSourceRespVO scanPressSlotSource(String batchNo, Boolean includeAbnormal) {
        String normalizedBatchNo = StrUtil.trimToEmpty(batchNo);
        if (StrUtil.isBlank(normalizedBatchNo)) {
            throw invalidParamException("请扫描或输入分切已确认片号");
        }
        HcSlittingSliceRecordDO slice = hcSlittingSliceRecordMapper.selectConfirmedBySerialNo(normalizedBatchNo);
        if (slice == null) {
            throw invalidParamException("未找到已确认的分切片号，不能进入压槽报工");
        }
        if (!Boolean.TRUE.equals(includeAbnormal) && (isSlittingSliceNg(slice)
                || hcNgInventoryService.isNgPieceManaged(SOURCE_TYPE_SLITTING, slice.getId()))) {
            throw invalidParamException("该分切片号为不合格品或已进入隔离管理，不能进入压槽报工；如需首检复判，请在首检区域扫码");
        }
        return buildPressSlotSourceResp(slice);
    }

    @Override
    public List<HcAdhesiveSourceRespVO> getPressSlotSourceList(Long planId, Long planOperationId) {
        if (planId == null || planOperationId == null) {
            return Collections.emptyList();
        }
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        validatePressSlotOperation(planOrder, planOperationId);
        Set<Long> sampleSourceIds = new LinkedHashSet<>(hcPressSlotFirstInspectionSampleClaimMapper.selectOccupiedSourceIds(planId));
        return hcSlittingSliceRecordMapper.selectConfirmedListByPlanId(planId)
                .stream()
                // 保留首检片和 NG 片展示，是否可加工由统一的首检占用标识决定。
                .map(slice -> buildPressSlotSourceResp(slice, sampleSourceIds.contains(slice.getId())))
                .toList();
    }

    @Override
    public List<HcAdhesiveReportRespVO> getPressSlotReportList(Long planOperationId) {
        return getPressSlotReportList(planOperationId, null);
    }

    @Override
    public List<HcAdhesiveReportRespVO> getPressSlotReportList(Long planOperationId, LocalDate scanConfirmDate) {
        if (planOperationId == null) {
            return Collections.emptyList();
        }
        LocalDateTime scanConfirmStart = scanConfirmDate == null ? null : scanConfirmDate.atStartOfDay();
        LocalDateTime scanConfirmEndExclusive = scanConfirmStart == null ? null : scanConfirmStart.plusDays(1);
        List<HcPressSlotReportDO> reports = hcPressSlotReportMapper.selectListByPlanOperationId(
                planOperationId, scanConfirmStart, scanConfirmEndExclusive);
        Map<Long, HcAdhesive2ReportDO> feedbackMap = loadPressSlotDownstreamFeedbackMap(reports);
        Map<Long, String> editBlockedReasonMap = loadPressSlotEditBlockedReasonMap(reports);
        List<HcAdhesiveReportRespVO> result = new ArrayList<>();
        for (HcPressSlotReportDO report : reports) {
            HcAdhesiveReportRespVO resp = buildPressSlotReportResp(report);
            applyReportDownstreamFeedback(resp, feedbackMap.get(report.getId()), PROCESS_CODE_ADHESIVE2,
                    "粘胶2", "压槽");
            resp.setEditBlockedReason(editBlockedReasonMap.get(report.getId()));
            resp.setCheckItems(hcPressSlotCheckDetailMapper.selectListByReportId(report.getId()).stream()
                    .map(this::buildPressSlotCheckItemResp)
                    .toList());
            result.add(resp);
        }
        return result;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcAdhesiveReportRespVO correctPressSlotReportAbnormalCategory(HcVisualAbnormalCategoryCorrectReqVO reqVO) {
        String category = StrUtil.trimToEmpty(reqVO.getCategory());
        String reason = StrUtil.trimToEmpty(reqVO.getReason());
        validateVisualAbnormalCategory(category, reason);
        HcPressSlotReportDO report = hcPressSlotReportMapper.selectById(reqVO.getId());
        if (report == null || Boolean.TRUE.equals(report.getDeleted())) {
            throw invalidParamException("压槽报工记录不存在");
        }
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(report.getPlanId());
        validatePressSlotOperation(planOrder, report.getPlanOperationId());
        Map<String, Object> extra = new LinkedHashMap<>(parseRoughExtraMap(report.getExtraJson()));
        List<String> beforeCategories = new ArrayList<>(resolveAdhesive2ActiveVisualCategories(extra));
        String currentDefectCode = StrUtil.trimToEmpty(report.getDefectCode());
        if (ADHESIVE2_VISUAL_CATEGORY_NAMES.contains(currentDefectCode) && !beforeCategories.contains(currentDefectCode)) {
            beforeCategories.add(currentDefectCode);
        }
        if (!isNgResultValue(report.getSelfCheck()) && StrUtil.isBlank(currentDefectCode) && beforeCategories.isEmpty()) {
            throw invalidParamException("当前压槽报工记录没有外观异常类别，不能修正");
        }

        String correctedAt = LocalDateTime.now().format(DATETIME_FORMATTER);
        Long correctedById = SecurityFrameworkUtils.getLoginUserId();
        String correctedByName = firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        applyVisualAbnormalCategoryCorrectionExtra(extra, beforeCategories, category, reason,
                correctedAt, correctedById, correctedByName);
        HcPressSlotReportDO updateReport = new HcPressSlotReportDO();
        updateReport.setId(report.getId());
        updateReport.setSelfCheck("NG");
        updateReport.setDefectCode(category);
        updateReport.setExtraJson(JsonUtils.toJsonString(extra));
        updateReport.setRemark(buildVisualAbnormalCategoryCorrectionRemark(
                report.getRemark(), beforeCategories, category, correctedAt, correctedByName));
        hcPressSlotReportMapper.updateById(updateReport);

        report.setSelfCheck(updateReport.getSelfCheck());
        report.setDefectCode(updateReport.getDefectCode());
        report.setExtraJson(updateReport.getExtraJson());
        report.setRemark(updateReport.getRemark());
        return buildPressSlotReportResp(report);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcPressSlotIntermediateRespVO getPressSlotIntermediate(Long planId, Long planOperationId,
                                                                  LocalDate recordDate, Long id, String batchNo) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        HcPlanOrderOperationDO operation = validatePressSlotOperation(planOrder, planOperationId);
        LocalDate effectiveDate = recordDate == null ? LocalDate.now() : recordDate;
        String normalizedBatchNo = normalizePressSlotMiddleBatchNo(batchNo);
        boolean hasRequestedBatchNo = StrUtil.isNotBlank(normalizedBatchNo);
        HcPressSlotIntermediateRecordDO record = id == null ? null : hcPressSlotIntermediateRecordMapper.selectById(id);
        if (record != null && (Boolean.TRUE.equals(record.getDeleted())
                || !Objects.equals(record.getPlanOperationId(), operation.getId()))) {
            record = null;
        }
        if (record != null && hasRequestedBatchNo
                && !StrUtil.equalsIgnoreCase(normalizePressSlotMiddleBatchNo(record.getBatchNo()), normalizedBatchNo)) {
            record = null;
        }
        if (record == null && hasRequestedBatchNo) {
            record = hcPressSlotIntermediateRecordMapper.selectByPlanOperationIdAndBatchNo(operation.getId(), normalizedBatchNo);
        }
        if (record == null && !hasRequestedBatchNo) {
            record = hcPressSlotIntermediateRecordMapper.selectByPlanOperationIdAndDate(operation.getId(), effectiveDate);
        }
        List<HcPressSlotReportDO> operationReports = getPressSlotOperationReports(operation.getId());
        String effectiveBatchNo = firstNotBlank(record == null ? null : normalizePressSlotMiddleBatchNo(record.getBatchNo()),
                normalizedBatchNo, resolvePressSlotIntermediateBatchNo(operationReports, operation, planOrder));
        List<HcPressSlotReportDO> scopedOperationReports = filterPressSlotReportsByMotherBatchNo(operationReports, effectiveBatchNo);
        PressSlotIntermediateCounter counter = calculatePressSlotIntermediateCounter(scopedOperationReports);
        if (record == null) {
            HcPressSlotIntermediateRespVO resp = new HcPressSlotIntermediateRespVO();
            resp.setPlanId(planOrder.getId());
            resp.setPlanNo(planOrder.getPlanNo());
            resp.setPlanOperationId(operation.getId());
            resp.setRecordDate(effectiveDate);
            resp.setModelCode(firstNotBlank(planOrder.getModelCode(), planOrder.getModelName()));
            resp.setMaterialCode(planOrder.getMaterialCode());
            resp.setBatchNo(effectiveBatchNo);
            resp.setInputQty(counter.inputQty());
            resp.setOutputQty(counter.outputQty());
            resp.setRecorderName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), ""));
            resp.setRecordStatus("DRAFT");
            resp.setDetails(buildPressSlotIntermediateDetailsFromMiddleReports(scopedOperationReports));
            applyPressSlotIntermediateTemplateMeta(resp, resolvePressSlotIntermediateTemplateMeta(resp.getModelCode()));
            return resp;
        }
        HcPressSlotIntermediateRespVO resp = buildPressSlotIntermediateResp(record);
        resp.setInputQty(counter.inputQty());
        resp.setOutputQty(counter.outputQty());
        if (StrUtil.isBlank(resp.getBatchNo())) {
            resp.setBatchNo(effectiveBatchNo);
        }
        List<HcPressSlotIntermediateDetailRespVO> details = hcPressSlotIntermediateDetailMapper
                .selectListByRecordId(record.getId())
                .stream()
                .map(this::buildPressSlotIntermediateDetailResp)
                .toList();
        resp.setDetails(details.isEmpty() ? buildPressSlotIntermediateDetailsFromMiddleReports(scopedOperationReports) : details);
        return resp;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long savePressSlotIntermediate(HcPressSlotIntermediateSaveReqVO reqVO) {
        return savePressSlotIntermediateRecord(reqVO, false);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long confirmPressSlotIntermediate(HcPressSlotIntermediateSaveReqVO reqVO) {
        return savePressSlotIntermediateRecord(reqVO, true);
    }

    private Long savePressSlotIntermediateRecord(HcPressSlotIntermediateSaveReqVO reqVO, boolean confirm) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validatePressSlotOperation(planOrder, reqVO.getPlanOperationId());
        LocalDate effectiveDate = reqVO.getRecordDate() == null ? LocalDate.now() : reqVO.getRecordDate();
        String operatorName = firstNotBlank(confirm ? reqVO.getConfirmerName() : reqVO.getRecorderName(),
                SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        if (confirm) {
            reqVO.setRecorderName(firstNotBlank(reqVO.getRecorderName(), operatorName));
            reqVO.setConfirmerName(operatorName);
            reqVO.setRecordStatus("CONFIRMED");
        } else {
            reqVO.setRecorderName(operatorName);
            reqVO.setRecordStatus(firstNotBlank(reqVO.getRecordStatus(), "RECORDED"));
        }
        List<HcPressSlotReportDO> operationReports = getPressSlotOperationReports(operation.getId());
        String effectiveBatchNo = firstNotBlank(normalizePressSlotMiddleBatchNo(reqVO.getBatchNo()),
                resolvePressSlotIntermediateBatchNo(operationReports, operation, planOrder));
        List<HcPressSlotReportDO> scopedOperationReports = filterPressSlotReportsByMotherBatchNo(operationReports, effectiveBatchNo);
        PressSlotIntermediateCounter counter = calculatePressSlotIntermediateCounter(scopedOperationReports);
        HcPressSlotIntermediateRecordDO record = reqVO.getId() == null ? null : hcPressSlotIntermediateRecordMapper.selectById(reqVO.getId());
        if (record != null && !Objects.equals(record.getPlanOperationId(), operation.getId())) {
            throw invalidParamException("中间品记录不属于当前压槽计划");
        }
        if (record != null && StrUtil.isNotBlank(effectiveBatchNo) && StrUtil.isNotBlank(record.getBatchNo())
                && !StrUtil.equalsIgnoreCase(normalizePressSlotMiddleBatchNo(record.getBatchNo()), effectiveBatchNo)) {
            throw invalidParamException("中间品记录批号与当前母卷批号不一致");
        }
        if (record == null && StrUtil.isNotBlank(effectiveBatchNo)) {
            record = hcPressSlotIntermediateRecordMapper.selectByPlanOperationIdAndBatchNo(operation.getId(), effectiveBatchNo);
        }
        if (record == null && StrUtil.isBlank(effectiveBatchNo)) {
            record = hcPressSlotIntermediateRecordMapper.selectByPlanOperationIdAndDate(operation.getId(), effectiveDate);
        }
        reqVO.setBatchNo(effectiveBatchNo);
        if (record == null || Boolean.TRUE.equals(record.getDeleted())) {
            record = HcPressSlotIntermediateRecordDO.builder()
                    .tenantId(planOrder.getTenantId())
                    .planId(planOrder.getId())
                    .planNo(planOrder.getPlanNo())
                    .planOperationId(operation.getId())
                    .recordDate(effectiveDate)
                    .recordStatus("DRAFT")
                    .build();
            fillPressSlotIntermediateRecord(record, reqVO, planOrder, operation, scopedOperationReports, counter);
            hcPressSlotIntermediateRecordMapper.insert(record);
        } else {
            fillPressSlotIntermediateRecord(record, reqVO, planOrder, operation, scopedOperationReports, counter);
            hcPressSlotIntermediateRecordMapper.updateById(record);
            hcPressSlotIntermediateDetailMapper.deleteByRecordId(record.getId());
        }

        List<HcPressSlotIntermediateDetailReqVO> details = reqVO.getDetails() == null
                ? Collections.emptyList() : reqVO.getDetails();
        if (details.isEmpty()) {
            details = buildDefaultPressSlotIntermediateDetails().stream()
                    .map(this::buildPressSlotIntermediateDetailReq)
                    .toList();
        }
        List<HcPressSlotIntermediateDetailDO> detailList = new ArrayList<>();
        int index = 0;
        for (HcPressSlotIntermediateDetailReqVO item : details) {
            if ("FIRST".equalsIgnoreCase(item.getSamplePosition())) {
                continue;
            }
            index++;
            detailList.add(HcPressSlotIntermediateDetailDO.builder()
                    .tenantId(planOrder.getTenantId())
                    .intermediateRecordId(record.getId())
                    .planId(planOrder.getId())
                    .planNo(planOrder.getPlanNo())
                    .planOperationId(operation.getId())
                    .pressSlotReportId(item.getPressSlotReportId())
                    .sourceSlittingSliceId(item.getSourceSlittingSliceId())
                    .samplePosition(StrUtil.blankToDefault(item.getSamplePosition(), "ROW" + index))
                    .samplePositionName(StrUtil.blankToDefault(item.getSamplePositionName(), item.getSamplePosition()))
                    .sliceBatchNo(item.getSliceBatchNo())
                    .widthMm(item.getWidthMm())
                    .thickness1(item.getThickness1())
                    .thickness2(item.getThickness2())
                    .thickness3(item.getThickness3())
                    .thickness4(item.getThickness4())
                    .thickness5(item.getThickness5())
                    .thickness6(item.getThickness6())
                    .thickness7(item.getThickness7())
                    .thickness8(item.getThickness8())
                    .thickness9(item.getThickness9())
                    .thickness10(item.getThickness10())
                    .remark(item.getRemark())
                    .sortNo(item.getSortNo() == null ? index : item.getSortNo())
                    .build());
        }
        hcPressSlotIntermediateDetailMapper.insertBatch(detailList);
        syncPressSlotIntermediateProcessFormRecord(record, detailList, null);
        return record.getId();
    }

