    private List<HcPressSlotMiddleLedgerRespVO> getPressSlotMiddleLedgerRows(Long planOperationId, Long recordId,
                                                                             String batchNo) {
        return getPressSlotIntermediateRecords(planOperationId, recordId, batchNo).stream()
                .flatMap(record -> hcPressSlotIntermediateDetailMapper.selectListByRecordId(record.getId()).stream()
                        .map(detail -> buildPressSlotMiddleLedgerResp(record, detail)))
                .toList();
    }

    private List<HcPressSlotIntermediateRecordDO> getPressSlotIntermediateRecords(Long planOperationId, Long recordId,
                                                                                  String batchNo) {
        if (planOperationId == null) {
            return Collections.emptyList();
        }
        String normalizedBatchNo = normalizePressSlotMiddleBatchNo(batchNo);
        if (recordId != null) {
            HcPressSlotIntermediateRecordDO selected = hcPressSlotIntermediateRecordMapper.selectById(recordId);
            if (selected != null && (Boolean.TRUE.equals(selected.getDeleted())
                    || !Objects.equals(selected.getPlanOperationId(), planOperationId))) {
                selected = null;
            }
            if (selected != null && StrUtil.isNotBlank(normalizedBatchNo)
                    && !StrUtil.equalsIgnoreCase(normalizePressSlotMiddleBatchNo(selected.getBatchNo()), normalizedBatchNo)) {
                selected = null;
            }
            return selected == null ? Collections.emptyList() : List.of(selected);
        }
        if (StrUtil.isNotBlank(normalizedBatchNo)) {
            return hcPressSlotIntermediateRecordMapper.selectListByPlanOperationIdAndBatchNo(planOperationId,
                    normalizedBatchNo);
        }
        return hcPressSlotIntermediateRecordMapper.selectListByPlanOperationId(planOperationId);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Integer importPressSlotMiddleLedger(Long planId, Long planOperationId, MultipartFile file,
                                               String importAttachmentJson, Long recordId, String batchNo,
                                               LocalDate recordDate) throws Exception {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        HcPlanOrderOperationDO operation = validatePressSlotOperation(planOrder, planOperationId);
        Map<String, Object> importAttachment = parseImportAttachmentJson(importAttachmentJson);
        int updated = 0;
        DataFormatter formatter = new DataFormatter();
        String requestBatchNo = normalizePressSlotMiddleBatchNo(batchNo);
        Map<String, List<HcPressSlotIntermediateDetailReqVO>> detailsByBatch = new LinkedHashMap<>();
        Map<String, LocalDate> recordDateByBatch = new LinkedHashMap<>();
        try (InputStream inputStream = file.getInputStream(); Workbook workbook = WorkbookFactory.create(inputStream)) {
            Sheet sheet = workbook.getSheetAt(0);
            int headerRowIndex = findPressSlotMiddleLedgerHeaderRow(sheet, formatter);
            if (headerRowIndex < 0) {
                throw invalidParamException("导入模板未找到片号表头");
            }
            for (int i = headerRowIndex + 1; i <= sheet.getLastRowNum(); i++) {
                Row row = sheet.getRow(i);
                if (row == null) {
                    continue;
                }
                String sliceNo = readCellString(row, 1, formatter);
                if (StrUtil.isBlank(sliceNo)) {
                    continue;
                }
                String reportType = resolvePressSlotMiddleLedgerType(readCellString(row, 2, formatter));
                LocalDate rowRecordDate = parsePressSlotProcessParamDate(readCellString(row, 0, formatter));
                LocalDate effectiveDate = firstNotNullDate(rowRecordDate, LocalDate.now());
                String effectiveBatchNo = firstNotBlank(requestBatchNo, normalizePressSlotMiddleBatchNo(sliceNo));
                if (StrUtil.isBlank(effectiveBatchNo)) {
                    continue;
                }
                List<HcPressSlotIntermediateDetailReqVO> detailList = detailsByBatch.computeIfAbsent(effectiveBatchNo,
                        key -> new ArrayList<>());
                recordDateByBatch.putIfAbsent(effectiveBatchNo, firstNotNullDate(rowRecordDate, effectiveDate));
                detailList.add(buildPressSlotIntermediateDetailReqFromImportRow(row, formatter, reportType, sliceNo,
                        detailList.size() + 1));
                updated++;
            }
        }
        for (Map.Entry<String, List<HcPressSlotIntermediateDetailReqVO>> entry : detailsByBatch.entrySet()) {
            saveImportedPressSlotIntermediate(planOrder, operation,
                    firstNotNullDate(recordDate, recordDateByBatch.get(entry.getKey()), LocalDate.now()),
                    entry.getValue(), importAttachment, recordId, entry.getKey());
        }
        return updated;
    }

    @Override
    public void exportPressSlotMiddleLedger(Long planOperationId, Long recordId, String batchNo,
                                            HttpServletResponse response) throws Exception {
        List<HcPressSlotIntermediateRecordDO> records = getPressSlotIntermediateRecords(planOperationId, recordId, batchNo);
        String fileName = URLEncoder.encode("CMP压槽中间品记录表.xlsx", StandardCharsets.UTF_8).replaceAll("\\+", "%20");
        response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
        response.setHeader("Content-Disposition", "attachment; filename*=UTF-8''" + fileName);
        try (Workbook workbook = new XSSFWorkbook()) {
            Sheet sheet = workbook.createSheet("压槽中间品记录表");
            writePressSlotIntermediateRecordSheet(sheet, records);
            workbook.write(response.getOutputStream());
        }
    }

