    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long savePressSlotChangeoverInspection(HcPressSlotChangeoverInspectionSaveReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validatePressSlotOperation(planOrder, reqVO.getPlanOperationId());
        HcSlittingSliceRecordDO sourceSlice = null;
        if (reqVO.getSourceSlittingSliceId() != null) {
            sourceSlice = hcSlittingSliceRecordMapper.selectById(reqVO.getSourceSlittingSliceId());
        }
        if (sourceSlice == null && StrUtil.isNotBlank(reqVO.getPressSlotSliceNo())) {
            sourceSlice = hcSlittingSliceRecordMapper.selectBySerialNo(reqVO.getPressSlotSliceNo());
        }
        LocalDateTime now = LocalDateTime.now();
        LocalDateTime submitTime = normalizeValidLocalDateTime(reqVO.getSubmitTime(), now);
        LocalDateTime recordTime = normalizeValidLocalDateTime(reqVO.getRecordTime(), submitTime);
        String sliceNo = firstNotBlank(reqVO.getPressSlotSliceNo(),
                sourceSlice == null ? null : sourceSlice.getSliceSerialNo());
        String motherSegmentBatchNo = normalizePressSlotMiddleBatchNo(firstNotBlank(reqVO.getMotherSegmentBatchNo(),
                sourceSlice == null ? null : sourceSlice.getSourceProductionBatchNo(),
                sourceSlice == null ? null : sourceSlice.getSourceBatchNo(),
                sliceNo));
        HcPressSlotChangeoverInspectionDO record = reqVO.getId() == null
                ? null
                : hcPressSlotChangeoverInspectionMapper.selectById(reqVO.getId());
        if (record == null) {
            HcPressSlotChangeoverInspectionDO existedRecord = hcPressSlotChangeoverInspectionMapper
                    .selectActiveBySourceSlice(operation.getId(),
                            sourceSlice == null ? reqVO.getSourceSlittingSliceId() : sourceSlice.getId(), sliceNo);
            if (existedRecord != null) {
                throw invalidParamException("分切片号 " + StrUtil.blankToDefault(sliceNo, "-")
                        + " 已存在压槽首检记录，不能重复新增");
            }
            record = new HcPressSlotChangeoverInspectionDO();
        }
        record.setPlanId(planOrder.getId());
        record.setPlanNo(planOrder.getPlanNo());
        record.setPlanOperationId(operation.getId());
        record.setOperationCode(operation.getOpCode());
        record.setOperationName(operation.getOpName());
        record.setSourceSlittingSliceId(sourceSlice == null ? reqVO.getSourceSlittingSliceId() : sourceSlice.getId());
        record.setPressSlotSliceNo(sliceNo);
        record.setMotherSegmentBatchNo(motherSegmentBatchNo);
        record.setProductionModelCode(firstNotBlank(reqVO.getProductionModelCode(), planOrder.getModelCode(), planOrder.getModelName()));
        record.setProductionMaterialCode(firstNotBlank(reqVO.getProductionMaterialCode(), planOrder.getMaterialCode()));
        record.setPreviousModelCode(reqVO.getPreviousModelCode());
        record.setCurrentPlanNo(firstNotBlank(reqVO.getCurrentPlanNo(), planOrder.getPlanNo()));
        record.setInspectionStatus(firstNotBlank(reqVO.getInspectionStatus(), "DRAFT"));
        record.setSubmitTime(submitTime);
        record.setHeaderDataJson(reqVO.getHeaderDataJson());
        record.setDetailItemsJson(StrUtil.isNotBlank(reqVO.getDetailItemsJson())
                ? reqVO.getDetailItemsJson()
                : JsonUtils.toJsonString(reqVO.getCheckItems() == null ? Collections.emptyList() : reqVO.getCheckItems()));
        record.setRecorderName(firstNotBlank(reqVO.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统"));
        record.setRecordTime(recordTime);
        record.setRemark(reqVO.getRemark());
        record.setExtraJson(reqVO.getExtraJson());
        record.setTenantId(planOrder.getTenantId());
        if (record.getId() == null) {
            hcPressSlotChangeoverInspectionMapper.insert(record);
        } else {
            hcPressSlotChangeoverInspectionMapper.updateById(record);
        }
        return record.getId();
    }

