    private void validateAdhesive2SourcePressSlotFaiScope(Long planId, Long planOperationId,
                                                          Long sourcePlanId, Long sourcePlanOperationId,
                                                          String motherBatchNo) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        validateAdhesive2Operation(planOrder, planOperationId);
        HcPlanOrderDO sourcePlanOrder = hcPlanOrderMapper.selectById(sourcePlanId);
        HcPlanOrderOperationDO sourceOperation = validatePressSlotOperation(sourcePlanOrder, sourcePlanOperationId);
        if (!Objects.equals(planOrder.getId(), sourcePlanOrder.getId())) {
            throw invalidParamException("来源压槽计划不属于当前粘胶2计划");
        }
        String scopeMotherBatchNo = normalizePressSlotMiddleBatchNo(motherBatchNo);
        if (StrUtil.isBlank(scopeMotherBatchNo)) {
            throw invalidParamException("来源压槽母卷批号不能为空");
        }
        boolean inSourceScope = hcPressSlotReportMapper.selectListByPlanOperationId(sourceOperation.getId())
                .stream()
                .filter(source -> Objects.equals(source.getPlanId(), sourcePlanOrder.getId()))
                .filter(source -> !isPressSlotFirstInspectionSampleTerminal(source))
                .filter(source -> !isPressSlotProcessCheckReport(source))
                .map(this::buildAdhesive2SourceResp)
                .anyMatch(source -> matchesAdhesive2SourceSegment(source, scopeMotherBatchNo));
        if (!inSourceScope) {
            throw invalidParamException("来源压槽数据不属于当前粘胶2来源范围");
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcAdhesive2FaiRespVO applyAdhesive2Fai(HcAdhesive2FaiApplyReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, reqVO.getPlanOperationId());
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("请先完成粘胶2开工并锁定设备");
        }
        HcProcessReportDO latestStartReport = getLatestStartReport(operation.getId(), SOURCE_MENU_CODE_ADHESIVE2);
        if (latestStartReport == null) {
            throw invalidParamException("当前粘胶2工序未找到开工记录，不能提交 FAI 工艺参数点检申请");
        }
        if (latestStartReport.getEquipmentId() == null && StrUtil.isBlank(latestStartReport.getEquipmentCode())) {
            throw invalidParamException("请先选择并锁定粘胶2设备");
        }
        if (isAdhesive2ProcessCheckFai(reqVO)) {
            return applyAdhesive2ProcessCheckFai(reqVO, planOrder, operation, latestStartReport);
        }
        if (isAdhesive2CoaFai(reqVO)) {
            return applyAdhesive2CoaFai(reqVO, planOrder, operation, latestStartReport);
        }

        String motherMaterialCode = firstNotBlank(latestStartReport.getMotherMaterialCode(),
                operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode(),
                latestStartReport.getMaterialCode(), planOrder.getMaterialCode());
        if (StrUtil.isBlank(motherMaterialCode)) {
            throw invalidParamException("当前粘胶2任务缺少母料料号，无法按物料编码与工段匹配 FAI 检验标准");
        }
        String operationCode = firstNotBlank(latestStartReport.getOperationCode(), operation.getOpCode());
        String operationName = firstNotBlank(latestStartReport.getOperationName(), operation.getOpName());
        if (StrUtil.isBlank(operationCode) && StrUtil.isBlank(operationName)) {
            throw invalidParamException("当前粘胶2任务缺少工段信息，无法按物料编码与工段匹配 FAI 检验标准");
        }
        String productBatchNo = firstNotBlank(latestStartReport.getProductionBatchNo(), latestStartReport.getBatchNo(),
                operation.getProductionBatchNo(), planOrder.getProductionBatchNo(),
                operation.getBatchNo(), planOrder.getBatchNo());
        if (StrUtil.isBlank(productBatchNo)) {
            throw invalidParamException("当前粘胶2任务缺少生产批次，批次号将写入 FAI 首件检验的产品批次");
        }

        QmsFaiOrderDO latestFai = selectLatestAdhesive2Fai(planOrder, operation, latestStartReport);
        if (latestFai != null && !isAdhesive2FaiReapplyAllowed(latestFai)) {
            if (isFaiReleased(latestFai)) {
                throw invalidParamException("当前粘胶2工艺参数点检已完成且判定OK，不能重复提交");
            }
            if (FAI_STATUS_PENDING.equals(latestFai.getStatus())) {
                throw invalidParamException("当前粘胶2工艺参数点检已送检待检测，不能重复提交");
            }
            if (FAI_STATUS_INSPECTING.equals(latestFai.getStatus())) {
                throw invalidParamException("当前粘胶2工艺参数点检检测中，不能重复提交");
            }
            if (FAI_STATUS_WAITING_QA.equals(latestFai.getStatus())) {
                throw invalidParamException("当前粘胶2工艺参数点检待品质复核，不能重复提交");
            }
            throw invalidParamException("当前粘胶2已有未完成工艺参数点检单，请先在 FAI 工作台处理后再提交");
        }
        HcAdhesiveGlueBoardUsageDO glueBoardUsage = applyAdhesive2FaiGlueBoardSample(reqVO, operation, latestStartReport);
        String triggerReason = firstNotBlank(reqVO.getTriggerReason(),
                latestFai != null && isAdhesive2FaiReapplyAllowed(latestFai) ? FAI_TRIGGER_REWORK_RECHECK : FAI_TRIGGER_NEW_ORDER);
        if (latestFai != null && isAdhesive2FaiReapplyAllowed(latestFai) && !FAI_TRIGGER_REWORK_RECHECK.equals(triggerReason)) {
            triggerReason = FAI_TRIGGER_REWORK_RECHECK;
        }

        QmsFaiSaveReqVO faiReqVO = new QmsFaiSaveReqVO();
        faiReqVO.setWorkOrderNo(planOrder.getPlanNo());
        faiReqVO.setSourceReportId(latestStartReport.getId());
        faiReqVO.setSourceReportNo(buildAdhesive2FaiSourceReportNo(planOrder, operation));
        faiReqVO.setSourceModule(SOURCE_MENU_CODE_ADHESIVE2);
        faiReqVO.setSourceOperationCode(operationCode);
        faiReqVO.setSourceOperationName(operationName);
        faiReqVO.setPlanOrderId(planOrder.getId());
        faiReqVO.setStandardMatchMode(FAI_STANDARD_MATCH_MATERIAL_PROCESS);
        faiReqVO.setOperationCode(operationCode);
        faiReqVO.setOperationName(operationName);
        faiReqVO.setMachineId(latestStartReport.getEquipmentId());
        faiReqVO.setMachineCode(firstNotBlank(latestStartReport.getEquipmentCode(), operation.getEquipmentCode()));
        faiReqVO.setMachineName(firstNotBlank(latestStartReport.getEquipmentName(), operation.getEquipmentName()));
        faiReqVO.setMaterialId(firstNotNull(latestStartReport.getMotherMaterialId(), operation.getMotherMaterialId(),
                planOrder.getMotherMaterialId(), latestStartReport.getMaterialId(), planOrder.getMaterialId()));
        faiReqVO.setMaterialCode(motherMaterialCode);
        faiReqVO.setMaterialName(firstNotBlank(latestStartReport.getMotherMaterialName(),
                operation.getMotherMaterialName(), planOrder.getMotherMaterialName(), latestStartReport.getMaterialName(), planOrder.getMaterialName()));
        faiReqVO.setSpecification(planOrder.getSizeName());
        faiReqVO.setProductModel(resolveFaiProductModel(latestStartReport, operation, planOrder));
        faiReqVO.setProductBatchNo(productBatchNo);
        applyFaiGlueBoardSnapshot(faiReqVO,
                firstNotBlank(reqVO.getGlueBoardMaterialCode(), glueBoardUsage.getGlueBoardMaterialCode()),
                firstNotBlank(reqVO.getGlueBoardBatchNo(), glueBoardUsage.getGlueBoardBatchNo()),
                glueBoardUsage);
        faiReqVO.setProcessCategory(PROCESS_CODE_ADHESIVE2);
        faiReqVO.setSubmissionType(FAI_SUBMISSION_TYPE_MASS_SHIPMENT);
        faiReqVO.setTriggerReason(triggerReason);
        faiReqVO.setStatus(FAI_STATUS_PENDING);
        faiReqVO.setJudgment(FAI_JUDGMENT_PENDING);
        faiReqVO.setSubmissionTime(LocalDateTime.now());
        faiReqVO.setSubmitterName(firstNotBlank(reqVO.getSubmitterName(), SecurityFrameworkUtils.getLoginUserNickname(),
                latestStartReport.getRecorderName(), "系统"));
        faiReqVO.setRemark(buildAdhesive2FaiRemark(reqVO, glueBoardUsage));
        Long faiId = qmsFaiService.createFaiForInspectionPush(faiReqVO);
        QmsFaiOrderDO createdFai = qmsFaiOrderMapper.selectById(faiId);
        syncAdhesive2ReportFaiSummary(latestStartReport, createdFai);
        return buildAdhesive2FaiResp(createdFai, latestStartReport, planOrder, operation);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcAdhesive2FaiRespVO applyAdhesive2PostConfirmCoa(HcAdhesiveReportConfirmReqVO reqVO) {
        HcAdhesive2ReportDO sourceReport = hcAdhesive2ReportMapper.selectById(reqVO.getId());
        if (sourceReport == null || Boolean.TRUE.equals(sourceReport.getDeleted())) {
            throw invalidParamException("粘胶2报工记录不存在");
        }
        String expectedBatchNo = StrUtil.trim(sourceReport.getProductionBatchNo());
        String scannedBatchNo = StrUtil.trim(reqVO.getScannedBatchNo());
        if (StrUtil.isBlank(expectedBatchNo) || !Objects.equals(scannedBatchNo, expectedBatchNo)) {
            throw invalidParamException("扫码片号与粘胶2成品片号不一致");
        }
        String reportStatus = StrUtil.blankToDefault(sourceReport.getReportStatus(), "DRAFT");
        boolean confirmedBeforeSubmit = "CONFIRMED".equalsIgnoreCase(reportStatus)
                || "SUBMITTED".equalsIgnoreCase(reportStatus);
        if (!confirmedBeforeSubmit) {
            // 该调用与 COA 建单处于同一事务，COA 创建失败时不保留扫码确认结果。
            confirmAdhesive2Report(reqVO);
            sourceReport = hcAdhesive2ReportMapper.selectById(reqVO.getId());
        }
        if (sourceReport == null || !isAdhesiveRecordConfirmedForCoa(sourceReport.getReportStatus())) {
            throw invalidParamException("粘胶2报工未完成扫码确认，不能提交 COA 送检");
        }
        return applyAdhesive2PostConfirmCoaFai(sourceReport, confirmedBeforeSubmit);
    }

    private boolean isAdhesive2CoaFai(HcAdhesive2FaiApplyReqVO reqVO) {
        return reqVO != null
                && (ADHESIVE2_INSPECTION_SCENE_COA.equalsIgnoreCase(StrUtil.trimToEmpty(reqVO.getInspectionScene()))
                || (FAI_STANDARD_MATCH_PRODUCT_MODEL_PROCESS.equalsIgnoreCase(StrUtil.trimToEmpty(reqVO.getStandardMatchMode()))
                && StrUtil.isNotBlank(reqVO.getProductBatchNo())));
    }

    private boolean isAdhesive2ProcessCheckFai(HcAdhesive2FaiApplyReqVO reqVO) {
        return reqVO != null
                && ADHESIVE2_INSPECTION_SCENE_PROCESS_CHECK.equalsIgnoreCase(StrUtil.trimToEmpty(reqVO.getInspectionScene()));
    }

    private HcAdhesive2FaiRespVO applyAdhesive2ProcessCheckFai(HcAdhesive2FaiApplyReqVO reqVO,
                                                                HcPlanOrderDO planOrder,
                                                                HcPlanOrderOperationDO operation,
                                                                HcProcessReportDO latestStartReport) {
        HcAdhesive2ReportDO sourceReport = validateAdhesive2ProcessCheckSourceReport(reqVO, operation);
        String operationCode = firstNotBlank(sourceReport.getOperationCode(), latestStartReport.getOperationCode(), operation.getOpCode());
        String operationName = firstNotBlank(sourceReport.getOperationName(), latestStartReport.getOperationName(), operation.getOpName());
        if (StrUtil.isBlank(operationCode) && StrUtil.isBlank(operationName)) {
            throw invalidParamException("当前粘胶2任务缺少工段信息，无法按产品型号与工段匹配 FAI 检验标准");
        }
        String productModel = firstNotBlank(sourceReport.getModelCode(), resolveAdhesive2CoaFaiProductModel(latestStartReport, operation, planOrder));
        if (StrUtil.isBlank(productModel)) {
            throw invalidParamException("当前粘胶2任务缺少产品型号，无法按产品型号与工段匹配 FAI 检验标准");
        }
        String productBatchNo = firstNotBlank(reqVO.getProductBatchNo(), sourceReport.getProductionBatchNo(), sourceReport.getSourceProductionBatchNo());
        if (StrUtil.isBlank(productBatchNo)) {
            throw invalidParamException("过程加检缺少粘胶2片号，不能生成 FAI 首件检验单");
        }
        String sourceReportNo = buildAdhesive2ProcessCheckFaiSourceReportNo(planOrder, operation, productBatchNo);
        QmsFaiOrderDO latestFai = qmsFaiOrderMapper.selectLatestBySourceReportNo(sourceReportNo, SOURCE_MENU_CODE_ADHESIVE2);
        if (latestFai != null && !isAdhesive2FaiReapplyAllowed(latestFai)) {
            if (isFaiReleased(latestFai)) {
                throw invalidParamException("过程加检片号 " + productBatchNo + " 已完成检验OK，不能重复提交");
            }
            throw invalidParamException("过程加检片号 " + productBatchNo + " 已有未完成检验单，请先在 FAI 工作台处理后再提交");
        }
        String triggerReason = firstNotBlank(reqVO.getTriggerReason(),
                latestFai != null && isAdhesive2FaiReapplyAllowed(latestFai) ? FAI_TRIGGER_REWORK_RECHECK : FAI_TRIGGER_NEW_ORDER);
        if (latestFai != null && isAdhesive2FaiReapplyAllowed(latestFai) && !FAI_TRIGGER_REWORK_RECHECK.equals(triggerReason)) {
            triggerReason = FAI_TRIGGER_REWORK_RECHECK;
        }
        String motherBatchNo = resolveAdhesive2MotherSegmentBatchNo(sourceReport);
        String motherMaterialCode = firstNotBlank(sourceReport.getMaterialCode(), latestStartReport.getMotherMaterialCode(),
                operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode(),
                latestStartReport.getMaterialCode(), planOrder.getMaterialCode());

        QmsFaiSaveReqVO faiReqVO = new QmsFaiSaveReqVO();
        faiReqVO.setWorkOrderNo(planOrder.getPlanNo());
        faiReqVO.setSourceReportId(sourceReport.getId());
        faiReqVO.setSourceReportNo(sourceReportNo);
        faiReqVO.setSourceModule(SOURCE_MENU_CODE_ADHESIVE2);
        faiReqVO.setSourceOperationCode(operationCode);
        faiReqVO.setSourceOperationName(operationName);
        faiReqVO.setPlanOrderId(planOrder.getId());
        faiReqVO.setStandardMatchMode(FAI_STANDARD_MATCH_PRODUCT_MODEL_PROCESS);
        faiReqVO.setOperationCode(operationCode);
        faiReqVO.setOperationName(operationName);
        faiReqVO.setMachineId(latestStartReport.getEquipmentId());
        faiReqVO.setMachineCode(firstNotBlank(latestStartReport.getEquipmentCode(), operation.getEquipmentCode()));
        faiReqVO.setMachineName(firstNotBlank(latestStartReport.getEquipmentName(), operation.getEquipmentName()));
        faiReqVO.setMaterialId(firstNotNull(latestStartReport.getMotherMaterialId(), operation.getMotherMaterialId(),
                planOrder.getMotherMaterialId(), latestStartReport.getMaterialId(), planOrder.getMaterialId()));
        faiReqVO.setMaterialCode(motherMaterialCode);
        faiReqVO.setMaterialName(firstNotBlank(sourceReport.getMaterialName(), latestStartReport.getMotherMaterialName(),
                operation.getMotherMaterialName(), planOrder.getMotherMaterialName(),
                latestStartReport.getMaterialName(), planOrder.getMaterialName()));
        faiReqVO.setSpecification(planOrder.getSizeName());
        faiReqVO.setProductModel(productModel);
        faiReqVO.setProductBatchNo(productBatchNo);
        applyFaiGlueBoardSnapshot(faiReqVO, sourceReport.getGlueBoardMaterialCode(), sourceReport.getGlueBoardBatchNo(), null);
        faiReqVO.setProcessCategory(PROCESS_CODE_ADHESIVE2);
        faiReqVO.setSubmissionType(FAI_SUBMISSION_TYPE_MASS_SHIPMENT);
        faiReqVO.setTriggerReason(triggerReason);
        faiReqVO.setStatus(FAI_STATUS_PENDING);
        faiReqVO.setJudgment(FAI_JUDGMENT_PENDING);
        faiReqVO.setSubmissionTime(LocalDateTime.now());
        faiReqVO.setSubmitterName(firstNotBlank(reqVO.getSubmitterName(), SecurityFrameworkUtils.getLoginUserNickname(),
                sourceReport.getRecorderName(), latestStartReport.getRecorderName(), "系统"));
        faiReqVO.setRemark(buildAdhesive2ProcessCheckFaiRemark(reqVO, sourceReport, productBatchNo, motherBatchNo));
        Long faiId = qmsFaiService.createFaiForInspectionPush(faiReqVO);
        QmsFaiOrderDO createdFai = qmsFaiOrderMapper.selectById(faiId);
        storeAdhesive2ProcessCheckFaiInfo(sourceReport, createdFai);
        HcAdhesive2FaiRespVO respVO = buildAdhesive2ProcessCheckFaiResp(createdFai, latestStartReport, planOrder, operation);
        respVO.setInspectionScopeBatchNo(motherBatchNo);
        return respVO;
    }

    private HcAdhesive2FaiRespVO applyAdhesive2CoaFai(HcAdhesive2FaiApplyReqVO reqVO,
                                                       HcPlanOrderDO planOrder,
                                                       HcPlanOrderOperationDO operation,
                                                       HcProcessReportDO latestStartReport) {
        String operationCode = firstNotBlank(latestStartReport.getOperationCode(), operation.getOpCode());
        String operationName = firstNotBlank(latestStartReport.getOperationName(), operation.getOpName());
        if (StrUtil.isBlank(operationCode) && StrUtil.isBlank(operationName)) {
            throw invalidParamException("当前粘胶2任务缺少工段信息，无法按产品型号与工段匹配 FAI 检验标准");
        }
        String scopeMotherBatchNo = normalizePressSlotMiddleBatchNo(reqVO.getInspectionScopeBatchNo());
        List<HcPressSlotReportDO> confirmedPressSlotSources = hcPressSlotReportMapper.selectConfirmedListByPlanId(planOrder.getId());
        List<HcPressSlotReportDO> coaSources = filterAdhesive2CoaPressSlotReports(confirmedPressSlotSources,
                scopeMotherBatchNo, reqVO.getCoaSliceNos());
        HcPressSlotReportDO selectedSource = selectAdhesive2CoaSource(confirmedPressSlotSources, coaSources, reqVO, scopeMotherBatchNo);
        if (selectedSource == null) {
            throw invalidParamException("未找到当前母卷已确认压槽片号，请在粘胶2 COA送检中选择、输入或扫码后重试");
        }
        selectedSource = ensureAdhesive2CoaPressSlotFlag(selectedSource);
        Long selectedSourceId = selectedSource.getId();
        if (coaSources.stream().noneMatch(source -> Objects.equals(source.getId(), selectedSourceId))) {
            List<HcPressSlotReportDO> nextCoaSources = new ArrayList<>(coaSources);
            nextCoaSources.add(selectedSource);
            nextCoaSources.sort(Comparator.comparing(HcPressSlotReportDO::getProductionBatchNo, Comparator.nullsLast(String::compareTo)));
            coaSources = nextCoaSources;
        }
        String productBatchNo = firstNotBlank(selectedSource.getProductionBatchNo(), reqVO.getProductBatchNo());
        if (StrUtil.isBlank(productBatchNo)) {
            throw invalidParamException("COA送检缺少压槽片号，不能生成 FAI 首件检验单");
        }
        String selectedMotherBatchNo = resolveAdhesive2MotherSegmentBatchNo(selectedSource);
        if (StrUtil.isBlank(scopeMotherBatchNo)) {
            scopeMotherBatchNo = selectedMotherBatchNo;
        } else if (StrUtil.isNotBlank(selectedMotherBatchNo) && !scopeMotherBatchNo.equalsIgnoreCase(selectedMotherBatchNo)) {
            throw invalidParamException("所选COA送检片号不属于当前母卷批号，请重新选择");
        }

        String sourceReportNo = buildAdhesive2CoaFaiSourceReportNo(planOrder, operation, productBatchNo);
        QmsFaiOrderDO latestFai = qmsFaiOrderMapper.selectLatestBySourceReportNo(sourceReportNo, SOURCE_MENU_CODE_ADHESIVE2);
        if (latestFai != null && !isAdhesive2FaiReapplyAllowed(latestFai)) {
            if (isFaiReleased(latestFai)) {
                throw invalidParamException("COA送检片号 " + productBatchNo + " 已完成检验OK，不能重复提交");
            }
            throw invalidParamException("COA送检片号 " + productBatchNo + " 已有未完成检验单，请先在 FAI 工作台处理后再提交");
        }
        String triggerReason = firstNotBlank(reqVO.getTriggerReason(),
                latestFai != null && isAdhesive2FaiReapplyAllowed(latestFai) ? FAI_TRIGGER_REWORK_RECHECK : FAI_TRIGGER_NEW_ORDER);
        if (latestFai != null && isAdhesive2FaiReapplyAllowed(latestFai) && !FAI_TRIGGER_REWORK_RECHECK.equals(triggerReason)) {
            triggerReason = FAI_TRIGGER_REWORK_RECHECK;
        }

        Adhesive2RuntimeProductContext runtimeProduct = resolveAdhesive2RuntimeProductContext(
                planOrder, operation, latestStartReport, scopeMotherBatchNo, productBatchNo,
                resolveAdhesive2RequestRuntimeProductContext(reqVO, planOrder));
        QmsFaiSaveReqVO faiReqVO = new QmsFaiSaveReqVO();
        faiReqVO.setWorkOrderNo(planOrder.getPlanNo());
        faiReqVO.setSourceReportId(selectedSource.getId());
        faiReqVO.setSourceReportNo(sourceReportNo);
        faiReqVO.setSourceModule(SOURCE_MENU_CODE_ADHESIVE2);
        faiReqVO.setSourceOperationCode(operationCode);
        faiReqVO.setSourceOperationName(operationName);
        faiReqVO.setPlanOrderId(planOrder.getId());
        faiReqVO.setStandardMatchMode(FAI_STANDARD_MATCH_PRODUCT_MODEL_PROCESS);
        faiReqVO.setOperationCode(operationCode);
        faiReqVO.setOperationName(operationName);
        faiReqVO.setMachineId(latestStartReport.getEquipmentId());
        faiReqVO.setMachineCode(firstNotBlank(latestStartReport.getEquipmentCode(), operation.getEquipmentCode()));
        faiReqVO.setMachineName(firstNotBlank(latestStartReport.getEquipmentName(), operation.getEquipmentName()));
        faiReqVO.setMaterialId(runtimeProduct.materialId());
        faiReqVO.setMaterialCode(runtimeProduct.materialCode());
        faiReqVO.setMaterialName(runtimeProduct.materialName());
        faiReqVO.setSpecification(runtimeProduct.specification());
        faiReqVO.setProductModel(runtimeProduct.productModel());
        faiReqVO.setProductBatchNo(productBatchNo);
        HcAdhesiveGlueBoardUsageDO glueBoardUsage = resolveAdhesive2FaiGlueBoardUsageForSnapshot(reqVO, operation);
        applyFaiGlueBoardSnapshot(faiReqVO,
                firstNotBlank(reqVO.getGlueBoardMaterialCode(), glueBoardUsage == null ? null : glueBoardUsage.getGlueBoardMaterialCode()),
                firstNotBlank(reqVO.getGlueBoardBatchNo(), glueBoardUsage == null ? null : glueBoardUsage.getGlueBoardBatchNo()),
                glueBoardUsage);
        faiReqVO.setProcessCategory(PROCESS_CODE_ADHESIVE2);
        faiReqVO.setSubmissionType(FAI_SUBMISSION_TYPE_MASS_SHIPMENT);
        faiReqVO.setTriggerReason(triggerReason);
        faiReqVO.setStatus(FAI_STATUS_PENDING);
        faiReqVO.setJudgment(FAI_JUDGMENT_PENDING);
        faiReqVO.setSubmissionTime(LocalDateTime.now());
        faiReqVO.setSubmitterName(firstNotBlank(reqVO.getSubmitterName(), SecurityFrameworkUtils.getLoginUserNickname(),
                latestStartReport.getRecorderName(), "系统"));
        faiReqVO.setRemark(buildAdhesive2CoaFaiRemark(reqVO, productBatchNo, scopeMotherBatchNo, coaSources));
        Long faiId = qmsFaiService.createFaiForInspectionPush(faiReqVO);
        QmsFaiOrderDO createdFai = qmsFaiOrderMapper.selectById(faiId);
        HcAdhesive2FaiRespVO respVO = buildAdhesive2FaiResp(createdFai, latestStartReport, planOrder, operation);
        respVO.setSourceReportNo(sourceReportNo);
        respVO.setSourceReportId(selectedSource.getId());
        respVO.setProductBatchNo(productBatchNo);
        respVO.setInspectionScopeBatchNo(scopeMotherBatchNo);
        respVO.setInspectionScene(ADHESIVE2_INSPECTION_SCENE_COA);
        respVO.setDisplayText("COA送检已提交：" + productBatchNo);
        return respVO;
    }

    /**
     * 新 COA 口径：来源必须是已经产出的粘胶2成品报工，而不是前序压槽片。
     */
    private HcAdhesive2FaiRespVO applyAdhesive2PostConfirmCoaFai(HcAdhesive2ReportDO sourceReport,
                                                                   boolean confirmedBeforeSubmit) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(sourceReport.getPlanId());
        if (planOrder == null) {
            throw invalidParamException("粘胶2成品所属生产计划不存在");
        }
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, sourceReport.getPlanOperationId());
        HcProcessReportDO latestStartReport = getLatestStartReport(operation.getId(), SOURCE_MENU_CODE_ADHESIVE2);
        if (latestStartReport == null) {
            throw invalidParamException("当前粘胶2工序未找到开工记录，不能提交成品 COA 送检");
        }
        if (isAdhesive2PostConfirmCoaSourceAbnormal(sourceReport)) {
            throw invalidParamException("当前粘胶2成品存在自检异常或质量锁定，不能提交 COA 送检");
        }
        if (!hcCutRoundReportMapper.selectListBySourceAdhesive2ReportId(sourceReport.getId()).isEmpty()) {
            throw invalidParamException("该粘胶2成品已进入裁切报工，不能补建 COA 送检");
        }

        String productBatchNo = StrUtil.trim(sourceReport.getProductionBatchNo());
        if (StrUtil.isBlank(productBatchNo)) {
            throw invalidParamException("粘胶2成品缺少片号，不能提交 COA 送检");
        }
        String operationCode = firstNotBlank(sourceReport.getOperationCode(), latestStartReport.getOperationCode(), operation.getOpCode());
        String operationName = firstNotBlank(sourceReport.getOperationName(), latestStartReport.getOperationName(), operation.getOpName());
        if (StrUtil.isBlank(operationCode) && StrUtil.isBlank(operationName)) {
            throw invalidParamException("当前粘胶2任务缺少工段信息，无法匹配 COA 检验标准");
        }
        String productModel = firstNotBlank(sourceReport.getModelCode(),
                resolveAdhesive2CoaFaiProductModel(latestStartReport, operation, planOrder));
        if (StrUtil.isBlank(productModel)) {
            throw invalidParamException("粘胶2成品缺少产品型号，无法匹配 COA 检验标准");
        }
        String materialCode = firstNotBlank(sourceReport.getMaterialCode(), latestStartReport.getMaterialCode(),
                operation.getMotherMaterialCode(), planOrder.getMaterialCode(), planOrder.getMotherMaterialCode());
        if (StrUtil.isBlank(materialCode)) {
            throw invalidParamException("粘胶2成品缺少产品料号，无法匹配 COA 检验标准");
        }
        String motherBatchNo = resolveAdhesive2MotherSegmentBatchNo(sourceReport);
        String sourceReportNo = buildAdhesive2PostConfirmCoaFaiSourceReportNo(planOrder, operation, sourceReport.getId());
        QmsFaiOrderDO latestFai = qmsFaiOrderMapper.selectLatestBySourceReportNo(sourceReportNo,
                SOURCE_MENU_CODE_ADHESIVE2);
        if (latestFai != null && !isAdhesive2FaiReapplyAllowed(latestFai)) {
            if (isFaiReleased(latestFai)) {
                throw invalidParamException("粘胶2成品片号 " + productBatchNo + " 已完成 COA 检验OK，不能重复提交");
            }
            throw invalidParamException("粘胶2成品片号 " + productBatchNo + " 已有未完成 COA 检验单，请先在 FAI 工作台处理后再提交");
        }
        String triggerReason = latestFai != null && isAdhesive2FaiReapplyAllowed(latestFai)
                ? FAI_TRIGGER_REWORK_RECHECK : FAI_TRIGGER_NEW_ORDER;

        QmsFaiSaveReqVO faiReqVO = new QmsFaiSaveReqVO();
        faiReqVO.setWorkOrderNo(planOrder.getPlanNo());
        faiReqVO.setSourceReportId(sourceReport.getId());
        faiReqVO.setSourceReportNo(sourceReportNo);
        faiReqVO.setSourceModule(SOURCE_MENU_CODE_ADHESIVE2);
        faiReqVO.setSourceOperationCode(operationCode);
        faiReqVO.setSourceOperationName(operationName);
        faiReqVO.setPlanOrderId(planOrder.getId());
        faiReqVO.setStandardMatchMode(FAI_STANDARD_MATCH_PRODUCT_MODEL_PROCESS);
        faiReqVO.setOperationCode(operationCode);
        faiReqVO.setOperationName(operationName);
        faiReqVO.setMachineId(latestStartReport.getEquipmentId());
        faiReqVO.setMachineCode(firstNotBlank(latestStartReport.getEquipmentCode(), operation.getEquipmentCode()));
        faiReqVO.setMachineName(firstNotBlank(latestStartReport.getEquipmentName(), operation.getEquipmentName()));
        faiReqVO.setMaterialId(firstNotNull(latestStartReport.getMaterialId(), planOrder.getMaterialId(),
                latestStartReport.getMotherMaterialId(), operation.getMotherMaterialId(), planOrder.getMotherMaterialId()));
        faiReqVO.setMaterialCode(materialCode);
        faiReqVO.setMaterialName(firstNotBlank(sourceReport.getMaterialName(), latestStartReport.getMaterialName(),
                operation.getMotherMaterialName(), planOrder.getMaterialName(), planOrder.getMotherMaterialName()));
        faiReqVO.setSpecification(firstNotBlank(planOrder.getSizeName(), planOrder.getSizeSpec()));
        faiReqVO.setProductModel(productModel);
        faiReqVO.setProductBatchNo(productBatchNo);
        HcAdhesiveGlueBoardUsageDO glueBoardUsage = sourceReport.getGlueBoardUsageId() == null ? null
                : hcAdhesiveGlueBoardUsageMapper.selectById(sourceReport.getGlueBoardUsageId());
        applyFaiGlueBoardSnapshot(faiReqVO, sourceReport.getGlueBoardMaterialCode(),
                sourceReport.getGlueBoardBatchNo(), glueBoardUsage);
        faiReqVO.setProcessCategory(PROCESS_CODE_ADHESIVE2);
        faiReqVO.setSubmissionType(FAI_SUBMISSION_TYPE_MASS_SHIPMENT);
        faiReqVO.setTriggerReason(triggerReason);
        faiReqVO.setStatus(FAI_STATUS_PENDING);
        faiReqVO.setJudgment(FAI_JUDGMENT_PENDING);
        faiReqVO.setSubmissionTime(LocalDateTime.now());
        faiReqVO.setSubmitterName(firstNotBlank(sourceReport.getConfirmerName(),
                SecurityFrameworkUtils.getLoginUserNickname(), sourceReport.getRecorderName(), "系统"));
        faiReqVO.setRemark(buildAdhesive2PostConfirmCoaFaiRemark(sourceReport, productBatchNo, motherBatchNo,
                confirmedBeforeSubmit));
        Long faiId = qmsFaiService.createFaiForInspectionPush(faiReqVO);
        QmsFaiOrderDO createdFai = qmsFaiOrderMapper.selectById(faiId);
        return buildAdhesive2PostConfirmCoaFaiResp(createdFai, latestStartReport, planOrder, operation);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void withdrawAdhesive2Coa(HcAdhesive2CoaWithdrawReqVO reqVO) {
        HcPlanOrderDO plan = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(plan, reqVO.getPlanOperationId());
        QmsFaiOrderDO fai = qmsFaiOrderMapper.selectById(reqVO.getFaiId());
        if (fai == null || Boolean.TRUE.equals(fai.getDeleted())
                || !SOURCE_MENU_CODE_ADHESIVE2.equals(fai.getSourceModule())
                || !PROCESS_CODE_ADHESIVE2.equals(fai.getProcessCategory())
                || !Objects.equals(plan.getId(), fai.getPlanOrderId())
                || fai.getSourceReportId() == null
                || !Objects.equals(buildAdhesive2PostConfirmCoaFaiSourceReportNo(plan, operation,
                        fai.getSourceReportId()), fai.getSourceReportNo())) {
            throw invalidParamException("只能撤回当前粘胶2任务的成品COA送检单");
        }
        HcAdhesive2ReportDO source = hcAdhesive2ReportMapper.selectByIdForUpdate(fai.getSourceReportId());
        if (source == null || Boolean.TRUE.equals(source.getDeleted())
                || !Objects.equals(source.getPlanId(), plan.getId())
                || !Objects.equals(source.getPlanOperationId(), operation.getId())
                || !Objects.equals(source.getProductionBatchNo(), fai.getProductBatchNo())) {
            throw invalidParamException("COA来源报工或片号与当前任务不一致，无法撤回");
        }
        String reason = resolveAdhesive2CoaWithdrawBlockedReason(fai);
        if (StrUtil.isNotBlank(reason)) throw invalidParamException(reason);
        if (!hcCutRoundReportMapper.selectListBySourceAdhesive2ReportId(source.getId()).isEmpty()) {
            throw invalidParamException("该片已进入裁切报工，不能撤回COA送检");
        }
        Long userId = SecurityFrameworkUtils.getLoginUserId();
        if (!qmsFaiOrderMapper.cancelUntouchedPendingById(fai.getId(), StrUtil.trim(reqVO.getWithdrawReason()),
                userId == null ? "系统" : String.valueOf(userId))) {
            throw invalidParamException("送检单状态已变化，无法撤回；请刷新后确认");
        }
        // 保留已确认报工及耗用；裁切查询按 CANCELED 排除本单，不释放其他送检单。
    }

    private String resolveAdhesive2CoaWithdrawBlockedReason(QmsFaiOrderDO fai) {
        if (fai == null || Boolean.TRUE.equals(fai.getDeleted())) return "送检单不存在或已删除";
        if (!FAI_STATUS_PENDING.equals(fai.getStatus())) return "仅待检单允许撤回";
        if (fai.getOperatorTime() != null || fai.getQaTime() != null
                || fai.getLastSaveTime() != null || fai.getLastScanTime() != null) {
            return "品质已扫码、录入或提交，不能撤回";
        }
        return null;
    }

    private boolean isAdhesiveRecordConfirmedForCoa(String reportStatus) {
        return "CONFIRMED".equalsIgnoreCase(StrUtil.trim(reportStatus))
                || "SUBMITTED".equalsIgnoreCase(StrUtil.trim(reportStatus));
    }

    private boolean isAdhesive2PostConfirmCoaSourceAbnormal(HcAdhesive2ReportDO sourceReport) {
        if (sourceReport == null) {
            return true;
        }
        String qualityStatus = StrUtil.trimToEmpty(sourceReport.getProductQualityStatus()).toUpperCase();
        return isNgText(sourceReport.getSelfCheck())
                || "QUALITY_ABNORMAL".equals(qualityStatus)
                || PRODUCT_QUALITY_LOCKED.equalsIgnoreCase(qualityStatus)
                || "ABNORMAL".equals(qualityStatus)
                || "NG".equals(qualityStatus)
                || StrUtil.isNotBlank(sourceReport.getDefectCode())
                || StrUtil.isNotBlank(sourceReport.getQualityLockReason());
    }

    private HcAdhesive2FaiRespVO buildAdhesive2PostConfirmCoaFaiResp(QmsFaiOrderDO faiOrder,
                                                                      HcProcessReportDO latestStartReport,
                                                                      HcPlanOrderDO planOrder,
                                                                      HcPlanOrderOperationDO operation) {
        HcAdhesive2FaiRespVO respVO = buildAdhesive2FaiResp(faiOrder, latestStartReport, planOrder, operation);
        HcAdhesive2ReportDO sourceReport = faiOrder == null || faiOrder.getSourceReportId() == null ? null
                : hcAdhesive2ReportMapper.selectById(faiOrder.getSourceReportId());
        respVO.setInspectionScene(ADHESIVE2_INSPECTION_SCENE_POST_CONFIRM_COA);
        String withdrawBlockedReason = resolveAdhesive2CoaWithdrawBlockedReason(faiOrder);
        if (StrUtil.isBlank(withdrawBlockedReason) && (sourceReport == null
                || !hcCutRoundReportMapper.selectListBySourceAdhesive2ReportId(sourceReport.getId()).isEmpty())) {
            withdrawBlockedReason = "来源报工不存在或已进入裁切";
        }
        respVO.setCanWithdraw(StrUtil.isBlank(withdrawBlockedReason));
        respVO.setWithdrawBlockedReason(withdrawBlockedReason);
        respVO.setWithdrawReason(faiOrder == null ? null : faiOrder.getLastReturnReason());
        respVO.setSourceReportNo(faiOrder == null
                ? buildAdhesive2PostConfirmCoaFaiSourceReportNoPrefix(planOrder, operation)
                : faiOrder.getSourceReportNo());
        respVO.setSourceReportId(faiOrder == null ? null : faiOrder.getSourceReportId());
        respVO.setProductBatchNo(firstNotBlank(faiOrder == null ? null : faiOrder.getProductBatchNo(),
                sourceReport == null ? null : sourceReport.getProductionBatchNo()));
        respVO.setInspectionScopeBatchNo(sourceReport == null ? null : resolveAdhesive2MotherSegmentBatchNo(sourceReport));
        if (sourceReport != null) {
            if (StrUtil.isBlank(respVO.getGlueBoardMaterialCode())) {
                respVO.setGlueBoardMaterialCode(sourceReport.getGlueBoardMaterialCode());
            }
            if (StrUtil.isBlank(respVO.getGlueBoardBatchNo())) {
                respVO.setGlueBoardBatchNo(sourceReport.getGlueBoardBatchNo());
            }
        }
        if (faiOrder != null) {
            respVO.setFaiApplyTime(firstNotNullDateTime(faiOrder.getSubmissionTime(), faiOrder.getCreateTime()));
            respVO.setFaiReturnTime(faiOrder.getUpdateTime());
            respVO.setDisplayText("粘胶2成品COA：" + resolveWetFaiDisplayText(faiOrder.getStatus(), faiOrder.getJudgment()));
        } else {
            respVO.setDisplayText("未提交");
            respVO.setAllowReportSubmit(false);
        }
        return respVO;
    }

    private String buildAdhesive2PostConfirmCoaFaiSourceReportNo(HcPlanOrderDO planOrder,
                                                                   HcPlanOrderOperationDO operation,
                                                                   Long adhesive2ReportId) {
        return buildAdhesive2PostConfirmCoaFaiSourceReportNoPrefix(planOrder, operation)
                + StrUtil.blankToDefault(adhesive2ReportId == null ? null : String.valueOf(adhesive2ReportId), "UNKNOWN");
    }

    private String buildAdhesive2PostConfirmCoaFaiSourceReportNoPrefix(HcPlanOrderDO planOrder,
                                                                         HcPlanOrderOperationDO operation) {
        return buildAdhesive2FaiSourceReportNo(planOrder, operation) + "-COA-POST-";
    }

    private String buildAdhesive2PostConfirmCoaFaiRemark(HcAdhesive2ReportDO sourceReport,
                                                           String productBatchNo,
                                                           String motherBatchNo,
                                                           boolean confirmedBeforeSubmit) {
        return "粘胶2成品COA送检"
                + "；送检方式 " + (confirmedBeforeSubmit ? "已确认后直接送检" : "送检前自动扫码确认")
                + "；粘胶2成品片号 " + StrUtil.blankToDefault(productBatchNo, "-")
                + "；粘胶2报工ID " + StrUtil.blankToDefault(sourceReport == null || sourceReport.getId() == null
                ? null : String.valueOf(sourceReport.getId()), "-")
                + "；分段批号 " + StrUtil.blankToDefault(motherBatchNo, "-");
    }

    private HcAdhesive2FaiRespVO buildAdhesive2CoaFaiResp(HcPlanOrderDO planOrder,
                                                           HcPlanOrderOperationDO operation,
                                                           HcProcessReportDO latestStartReport,
                                                           HcPressSlotReportDO source) {
        String productBatchNo = source == null ? "" : StrUtil.trimToEmpty(source.getProductionBatchNo());
        String sourceReportNo = buildAdhesive2CoaFaiSourceReportNo(planOrder, operation, productBatchNo);
        QmsFaiOrderDO latestFai = qmsFaiOrderMapper.selectLatestBySourceReportNo(sourceReportNo, SOURCE_MENU_CODE_ADHESIVE2);
        HcAdhesive2FaiRespVO respVO = latestFai == null
                ? new HcAdhesive2FaiRespVO()
                : buildAdhesive2FaiResp(latestFai, latestStartReport, planOrder, operation);
        respVO.setSourceReportId(source == null ? null : source.getId());
        respVO.setSourceReportNo(sourceReportNo);
        respVO.setProductBatchNo(productBatchNo);
        respVO.setInspectionScopeBatchNo(source == null ? null : resolveAdhesive2MotherSegmentBatchNo(source));
        respVO.setInspectionScene(ADHESIVE2_INSPECTION_SCENE_COA);
        if (latestFai != null) {
            respVO.setRemark(latestFai.getRemark());
        } else {
            respVO.setDisplayText("未提交");
            respVO.setAllowReportSubmit(false);
        }
        return respVO;
    }

    private HcAdhesive2ReportDO validateAdhesive2ProcessCheckSourceReport(HcAdhesive2FaiApplyReqVO reqVO,
                                                                          HcPlanOrderOperationDO operation) {
        HcAdhesive2ReportDO sourceReport = null;
        if (reqVO.getSourceReportId() != null) {
            sourceReport = hcAdhesive2ReportMapper.selectById(reqVO.getSourceReportId());
        }
        if (sourceReport == null && StrUtil.isNotBlank(reqVO.getProductBatchNo())) {
            sourceReport = hcAdhesive2ReportMapper.selectConfirmedByProductionBatchNo(StrUtil.trim(reqVO.getProductBatchNo()));
        }
        if (sourceReport == null || Boolean.TRUE.equals(sourceReport.getDeleted())) {
            throw invalidParamException("过程加检缺少已保存的粘胶2报工记录，请先完成扫码确认与外观检验保存");
        }
        if (!Objects.equals(sourceReport.getPlanOperationId(), operation.getId())) {
            throw invalidParamException("过程加检报工记录不属于当前粘胶2工序");
        }
        String status = StrUtil.blankToDefault(sourceReport.getReportStatus(), "DRAFT");
        if (!"CONFIRMED".equalsIgnoreCase(status) && !"SUBMITTED".equalsIgnoreCase(status)) {
            throw invalidParamException("请先保存并扫码确认当前片号，再推送过程加检");
        }
        return sourceReport;
    }

    private HcAdhesive2FaiRespVO buildAdhesive2ProcessCheckFaiResp(QmsFaiOrderDO faiOrder,
                                                                    HcProcessReportDO latestStartReport,
                                                                    HcPlanOrderDO planOrder,
                                                                    HcPlanOrderOperationDO operation) {
        HcAdhesive2FaiRespVO respVO = buildAdhesive2FaiResp(faiOrder, latestStartReport, planOrder, operation);
        HcAdhesive2ReportDO sourceReport = faiOrder == null || faiOrder.getSourceReportId() == null
                ? null
                : hcAdhesive2ReportMapper.selectById(faiOrder.getSourceReportId());
        respVO.setInspectionScene(ADHESIVE2_INSPECTION_SCENE_PROCESS_CHECK);
        respVO.setSourceReportNo(faiOrder == null ? buildAdhesive2ProcessCheckFaiSourceReportNoPrefix(planOrder, operation) : faiOrder.getSourceReportNo());
        respVO.setSourceReportId(faiOrder == null ? null : faiOrder.getSourceReportId());
        respVO.setProductBatchNo(firstNotBlank(faiOrder == null ? null : faiOrder.getProductBatchNo(),
                sourceReport == null ? null : sourceReport.getProductionBatchNo()));
        respVO.setInspectionScopeBatchNo(sourceReport == null ? null : resolveAdhesive2MotherSegmentBatchNo(sourceReport));
        respVO.setRemark(faiOrder == null ? null : faiOrder.getRemark());
        if (StrUtil.isBlank(respVO.getGlueBoardMaterialCode()) && sourceReport != null) {
            respVO.setGlueBoardMaterialCode(sourceReport.getGlueBoardMaterialCode());
        }
        if (StrUtil.isBlank(respVO.getGlueBoardBatchNo()) && sourceReport != null) {
            respVO.setGlueBoardBatchNo(sourceReport.getGlueBoardBatchNo());
        }
        respVO.setDisplayText("过程加检：" + resolveWetFaiDisplayText(respVO.getFaiStatus(), respVO.getFaiJudgment()));
        return respVO;
    }

    private String buildAdhesive2ProcessCheckFaiSourceReportNoPrefix(HcPlanOrderDO planOrder,
                                                                     HcPlanOrderOperationDO operation) {
        return buildAdhesive2FaiSourceReportNo(planOrder, operation) + "-PROCESS-CHECK-";
    }

    private String buildAdhesive2ProcessCheckFaiSourceReportNo(HcPlanOrderDO planOrder,
                                                               HcPlanOrderOperationDO operation,
                                                               String productBatchNo) {
        return buildAdhesive2ProcessCheckFaiSourceReportNoPrefix(planOrder, operation)
                + StrUtil.trimToEmpty(productBatchNo);
    }

    private String buildAdhesive2ProcessCheckFaiRemark(HcAdhesive2FaiApplyReqVO reqVO,
                                                       HcAdhesive2ReportDO sourceReport,
                                                       String productBatchNo,
                                                       String motherBatchNo) {
        return firstNotBlank(reqVO.getRemark(), "粘胶2过程加检 FAI 申请")
                + "；检验场景 " + ADHESIVE2_INSPECTION_SCENE_PROCESS_CHECK
                + "；过程加检片号 " + StrUtil.blankToDefault(productBatchNo, "-")
                + "；母卷批号 " + StrUtil.blankToDefault(motherBatchNo, "-")
                + "；粘胶2报工ID " + (sourceReport == null ? "-" : sourceReport.getId());
    }

    private void storeAdhesive2ProcessCheckFaiInfo(HcAdhesive2ReportDO sourceReport, QmsFaiOrderDO faiOrder) {
        if (sourceReport == null || sourceReport.getId() == null || faiOrder == null) {
            return;
        }
        Map<String, Object> extra = new LinkedHashMap<>(parseRoughExtraMap(sourceReport.getExtraJson()));
        extra.put("inspectionScene", ADHESIVE2_INSPECTION_SCENE_PROCESS_CHECK);
        extra.put("processCheckFaiId", faiOrder.getId());
        extra.put("processCheckFaiNo", faiOrder.getFaiNo());
        extra.put("processCheckFaiStatus", faiOrder.getStatus());
        extra.put("processCheckFaiJudgment", faiOrder.getJudgment());
        extra.put("processCheckFaiApplyTime", LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));
        HcAdhesive2ReportDO updateReport = new HcAdhesive2ReportDO();
        updateReport.setId(sourceReport.getId());
        updateReport.setExtraJson(JsonUtils.toJsonString(extra));
        hcAdhesive2ReportMapper.updateById(updateReport);
        sourceReport.setExtraJson(updateReport.getExtraJson());
    }

