    @Override
    public HcAdhesive2RuntimeProductRespVO getAdhesive2RuntimeProductSnapshot(Long planId, Long planOperationId,
                                                                                String segmentBatchNo) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, planOperationId);
        HcProcessReportDO latestStartReport = getLatestStartReport(operation.getId(), SOURCE_MENU_CODE_ADHESIVE2);
        Adhesive2RuntimeProductContext context = resolveAdhesive2RuntimeProductContext(planOrder, operation,
                latestStartReport, normalizePressSlotMiddleBatchNo(segmentBatchNo), null, null);
        HcAdhesive2RuntimeProductRespVO respVO = new HcAdhesive2RuntimeProductRespVO();
        respVO.setProductModel(context.productModel());
        respVO.setMaterialId(context.materialId());
        respVO.setMaterialCode(context.materialCode());
        respVO.setMaterialName(context.materialName());
        respVO.setSpecification(context.specification());
        respVO.setSourceType(context.sourceType());
        respVO.setChangeoverInstructionId(context.changeoverInstructionId());
        respVO.setChangeoverInstructionNo(context.changeoverInstructionNo());
        return respVO;
    }

    private Adhesive2RuntimeProductContext resolveAdhesive2RuntimeProductContext(HcPlanOrderDO planOrder,
                                                                                    HcPlanOrderOperationDO operation,
                                                                                    HcProcessReportDO latestStartReport,
                                                                                    String segmentBatchNo,
                                                                                    String productBatchNo,
                                                                                    Adhesive2RuntimeProductContext requestRuntimeProduct) {
        if (StrUtil.isNotBlank(productBatchNo)) {
            HcProductionInstructionChangeoverPieceDO piece =
                    hcProductionInstructionChangeoverPieceMapper.selectLatestByPlanOperationAndPieceNo(
                            planOrder.getId(), operation.getId(), productBatchNo);
            if (piece != null && StrUtil.isNotBlank(piece.getActualModelCode())) {
                HcProductionInstructionDO instruction = hcProductionInstructionMapper.selectById(piece.getInstructionId());
                return resolveRuntimeProductByModel(piece.getActualModelCode(),
                        instruction == null ? null : instruction.getTargetMaterialCode(), "CHANGEOVER_PIECE",
                        instruction == null ? null : instruction.getId(),
                        instruction == null ? null : instruction.getInstructionNo());
            }
        }
        if (StrUtil.isNotBlank(segmentBatchNo)) {
            HcProductionInstructionDO instruction = hcProductionInstructionMapper.selectLatestEffectiveChangeover(
                    planOrder.getId(), operation.getId(), segmentBatchNo);
            if (instruction != null && StrUtil.isNotBlank(instruction.getTargetModelCode())) {
                return resolveRuntimeProductByModel(instruction.getTargetModelCode(), instruction.getTargetMaterialCode(),
                        "CHANGEOVER_INSTRUCTION", instruction.getId(), instruction.getInstructionNo());
            }
        }
        if (requestRuntimeProduct != null) {
            return requestRuntimeProduct;
        }
        return new Adhesive2RuntimeProductContext(
                resolveAdhesive2CoaFaiProductModel(latestStartReport, operation, planOrder),
                firstNotNull(latestStartReport == null ? null : latestStartReport.getMotherMaterialId(),
                        operation.getMotherMaterialId(), planOrder.getMotherMaterialId(),
                        latestStartReport == null ? null : latestStartReport.getMaterialId(), planOrder.getMaterialId()),
                firstNotBlank(latestStartReport == null ? null : latestStartReport.getMotherMaterialCode(),
                        operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode(),
                        latestStartReport == null ? null : latestStartReport.getMaterialCode(), planOrder.getMaterialCode()),
                firstNotBlank(latestStartReport == null ? null : latestStartReport.getMotherMaterialName(),
                        operation.getMotherMaterialName(), planOrder.getMotherMaterialName(),
                        latestStartReport == null ? null : latestStartReport.getMaterialName(), planOrder.getMaterialName()),
                firstNotBlank(planOrder.getSizeName(), planOrder.getSizeSpec()), "PLAN", null, null);
    }

    private Adhesive2RuntimeProductContext resolveAdhesive2RequestRuntimeProductContext(HcAdhesive2FaiApplyReqVO reqVO,
                                                                                        HcPlanOrderDO planOrder) {
        String productModel = StrUtil.trimToNull(reqVO == null ? null : reqVO.getProductModel());
        if (StrUtil.isBlank(productModel)) {
            return null;
        }
        String materialCode = StrUtil.trimToNull(reqVO.getMaterialCode());
        String planModel = firstNotBlank(planOrder == null ? null : planOrder.getModelCode(),
                planOrder == null ? null : planOrder.getModelName());
        String planMaterialCode = planOrder == null ? null : planOrder.getMaterialCode();
        if (StrUtil.equalsIgnoreCase(productModel, planModel)
                && (StrUtil.isBlank(materialCode) || StrUtil.equalsIgnoreCase(materialCode, planMaterialCode))) {
            return null;
        }
        return resolveRuntimeProductByModel(productModel, materialCode, "REQUEST", null, null);
    }

    private Adhesive2RuntimeProductContext resolveRuntimeProductByModel(String productModel, String targetMaterialCode,
                                                                          String sourceType, Long instructionId,
                                                                          String instructionNo) {
        List<HcProductModelMaterialDO> mappings = hcProductModelMaterialMapper.selectListByModelCode(productModel);
        HcProductModelMaterialDO mapping;
        if (StrUtil.isNotBlank(targetMaterialCode)) {
            List<HcProductModelMaterialDO> matchedMappings = mappings.stream()
                    .filter(item -> StrUtil.equalsIgnoreCase(targetMaterialCode, item.getMaterialCode()))
                    .toList();
            if (matchedMappings.size() != 1) {
                throw invalidParamException("换型目标料号未关联目标产品型号，请维护型号-物料映射后重试");
            }
            mapping = matchedMappings.get(0);
        } else {
            List<HcProductModelMaterialDO> defaultMappings = mappings.stream()
                    .filter(item -> Boolean.TRUE.equals(item.getIsDefault()))
                    .toList();
            if (defaultMappings.size() != 1) {
                throw invalidParamException("换型目标型号缺少唯一默认料号，请维护型号-物料映射后重试");
            }
            mapping = defaultMappings.get(0);
        }
        HcMaterialDO material = hcMaterialMapper.selectById(mapping.getMaterialId());
        if (material == null || !StrUtil.equalsIgnoreCase(mapping.getMaterialCode(), material.getMaterialCode())) {
            throw invalidParamException("换型目标料号主数据不存在或与型号映射不一致，请先维护主数据");
        }
        if (StrUtil.isBlank(material.getSpecModel())) {
            throw invalidParamException("换型目标料号缺少规格，请先维护物料主数据规格");
        }
        return new Adhesive2RuntimeProductContext(productModel, material.getId(), material.getMaterialCode(),
                material.getMaterialName(), material.getSpecModel(), sourceType, instructionId, instructionNo);
    }

    private record Adhesive2RuntimeProductContext(String productModel, Long materialId, String materialCode,
                                                  String materialName, String specification, String sourceType,
                                                  Long changeoverInstructionId, String changeoverInstructionNo) {
    }

    private List<HcPressSlotReportDO> findAdhesive2CoaPressSlotReports(Long planId,
                                                                        String motherBatchNo,
                                                                        List<String> requestedSliceNos) {
        return filterAdhesive2CoaPressSlotReports(hcPressSlotReportMapper.selectConfirmedListByPlanId(planId),
                motherBatchNo, requestedSliceNos);
    }

    private List<HcPressSlotReportDO> filterAdhesive2CoaPressSlotReports(List<HcPressSlotReportDO> sources,
                                                                         String motherBatchNo,
                                                                         List<String> requestedSliceNos) {
        Set<String> requestedSliceNoSet = requestedSliceNos == null ? Collections.emptySet()
                : requestedSliceNos.stream()
                .map(value -> StrUtil.trimToEmpty(value).toUpperCase())
                .filter(StrUtil::isNotBlank)
                .collect(Collectors.toSet());
        return (sources == null ? Collections.<HcPressSlotReportDO>emptyList() : sources)
                .stream()
                .filter(this::isPressSlotCoaFlag)
                .filter(source -> StrUtil.isBlank(motherBatchNo)
                        || motherBatchNo.equalsIgnoreCase(resolveAdhesive2MotherSegmentBatchNo(source)))
                .filter(source -> requestedSliceNoSet.isEmpty()
                        || requestedSliceNoSet.contains(StrUtil.trimToEmpty(source.getProductionBatchNo()).toUpperCase()))
                .sorted(Comparator.comparing(HcPressSlotReportDO::getProductionBatchNo, Comparator.nullsLast(String::compareTo)))
                .toList();
    }

    private HcPressSlotReportDO selectAdhesive2CoaSource(List<HcPressSlotReportDO> confirmedSources,
                                                         List<HcPressSlotReportDO> coaSources,
                                                         HcAdhesive2FaiApplyReqVO reqVO,
                                                         String motherBatchNo) {
        String productBatchNo = StrUtil.trimToEmpty(reqVO.getProductBatchNo());
        if (StrUtil.isNotBlank(productBatchNo)) {
            HcPressSlotReportDO matched = (confirmedSources == null ? Collections.<HcPressSlotReportDO>emptyList() : confirmedSources).stream()
                    .filter(source -> productBatchNo.equalsIgnoreCase(StrUtil.trimToEmpty(source.getProductionBatchNo())))
                    .filter(source -> StrUtil.isBlank(motherBatchNo)
                            || motherBatchNo.equalsIgnoreCase(resolveAdhesive2MotherSegmentBatchNo(source)))
                    .findFirst()
                    .orElse(null);
            if (matched == null) {
                throw invalidParamException("COA送检片号 " + productBatchNo + " 不属于当前母卷已确认压槽报工，请重新选择或扫码");
            }
            return matched;
        }
        if (coaSources == null || coaSources.isEmpty()) {
            return null;
        }
        if (reqVO.getSourceReportId() != null) {
            HcPressSlotReportDO matched = coaSources.stream()
                    .filter(source -> Objects.equals(source.getId(), reqVO.getSourceReportId()))
                    .findFirst()
                    .orElse(null);
            if (matched != null) {
                return matched;
            }
        }
        return coaSources.get(0);
    }

    private HcPressSlotReportDO ensureAdhesive2CoaPressSlotFlag(HcPressSlotReportDO source) {
        if (source == null || isPressSlotCoaFlag(source)) {
            return source;
        }
        Map<String, Object> extra = new LinkedHashMap<>(parseRoughExtraMap(source.getExtraJson()));
        extra.put("coaFlag", true);
        extra.put("coaFlagName", "COA送检片");
        extra.put("coaMarkedBy", "ADHESIVE2_COA_INSPECTION");
        extra.put("coaMarkedTime", LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));
        HcPressSlotReportDO updateObj = new HcPressSlotReportDO();
        updateObj.setId(source.getId());
        updateObj.setExtraJson(JsonUtils.toJsonString(extra));
        hcPressSlotReportMapper.updateById(updateObj);
        source.setExtraJson(updateObj.getExtraJson());
        return source;
    }

