    private QmsFaiOrderDO validateAdhesive2FaiReleased(HcPlanOrderDO planOrder,
                                                       HcPlanOrderOperationDO operation) {
        HcProcessReportDO latestStartReport = getLatestStartReport(operation.getId(), SOURCE_MENU_CODE_ADHESIVE2);
        QmsFaiOrderDO latestFai = selectLatestAdhesive2Fai(planOrder, operation, latestStartReport);
        if (latestFai == null) {
            throw invalidParamException("粘胶2 FAI 工艺参数点检未生成，不能保存、扫码确认或工单完工");
        }
        syncAdhesive2ReportFaiSummary(latestStartReport, latestFai);
        if (FAI_STATUS_REJECTED.equals(latestFai.getStatus())) {
            throw invalidParamException("粘胶2 FAI 工艺参数点检已驳回，需重新提交并完成OK放行后再报工");
        }
        if (FAI_STATUS_CANCELED.equals(latestFai.getStatus())) {
            throw invalidParamException("粘胶2 FAI 工艺参数点检已取消，需重新提交并完成OK放行后再报工");
        }
        if (FAI_STATUS_COMPLETED.equals(latestFai.getStatus()) && FAI_JUDGMENT_NG.equals(latestFai.getJudgment())) {
            throw invalidParamException("粘胶2 FAI 工艺参数点检判定NG，需重新提交并完成OK放行后再报工");
        }
        if (FAI_STATUS_PENDING.equals(latestFai.getStatus())) {
            throw invalidParamException("粘胶2 FAI 工艺参数点检待检测，不能保存、扫码确认或工单完工");
        }
        if (FAI_STATUS_INSPECTING.equals(latestFai.getStatus())) {
            throw invalidParamException("粘胶2 FAI 工艺参数点检检测中，不能保存、扫码确认或工单完工");
        }
        if (FAI_STATUS_WAITING_QA.equals(latestFai.getStatus())) {
            throw invalidParamException("粘胶2 FAI 工艺参数点检待品质复核，不能保存、扫码确认或工单完工");
        }
        if (!FAI_STATUS_COMPLETED.equals(latestFai.getStatus()) || !FAI_JUDGMENT_OK.equals(latestFai.getJudgment())) {
            throw invalidParamException("粘胶2 FAI 工艺参数点检未完成或未OK放行，不能保存、扫码确认或工单完工");
        }
        return latestFai;
    }

    private QmsFaiOrderDO selectLatestAdhesive2Fai(HcPlanOrderDO planOrder,
                                                   HcPlanOrderOperationDO operation,
                                                   HcProcessReportDO latestStartReport) {
        QmsFaiOrderDO latestFai = qmsFaiOrderMapper.selectLatestBySourceReportNo(
                buildAdhesive2FaiSourceReportNo(planOrder, operation), SOURCE_MENU_CODE_ADHESIVE2);
        if (latestFai == null && latestStartReport != null && latestStartReport.getFaiId() != null) {
            latestFai = qmsFaiOrderMapper.selectById(latestStartReport.getFaiId());
        }
        return latestFai;
    }

    private String buildAdhesive2FaiSourceReportNo(HcPlanOrderDO planOrder, HcPlanOrderOperationDO operation) {
        return firstNotBlank(planOrder == null ? null : planOrder.getPlanNo(), "PLAN")
                + "-" + String.format("%02d", operation == null || operation.getOpSeq() == null ? 0 : operation.getOpSeq())
                + "-ADHESIVE2";
    }

    private boolean isAdhesive2FaiReapplyAllowed(QmsFaiOrderDO faiOrder) {
        return faiOrder != null && (FAI_STATUS_REJECTED.equals(faiOrder.getStatus())
                || FAI_STATUS_CANCELED.equals(faiOrder.getStatus())
                || (FAI_STATUS_COMPLETED.equals(faiOrder.getStatus()) && FAI_JUDGMENT_NG.equals(faiOrder.getJudgment())));
    }

    private HcAdhesiveGlueBoardUsageDO resolveAdhesive2FaiGlueBoardUsageForSnapshot(HcAdhesive2FaiApplyReqVO reqVO,
                                                                                     HcPlanOrderOperationDO operation) {
        if (operation == null) {
            return null;
        }
        if (reqVO != null && reqVO.getGlueBoardUsageId() != null) {
            HcAdhesiveGlueBoardUsageDO usage = hcAdhesiveGlueBoardUsageMapper.selectById(reqVO.getGlueBoardUsageId());
            // 粘胶2胶板按机台复用，COA 送检与扫码报工使用相同的有效性校验。
            if (usage == null || Boolean.TRUE.equals(usage.getDeleted())
                    || !isGlueBoardUsageAllowedForReport(usage, operation, PROCESS_CODE_ADHESIVE2)) {
                throw invalidParamException("胶板领用记录不存在或不属于当前粘胶2工序");
            }
            return usage;
        }
        return hcAdhesiveGlueBoardUsageMapper.selectActiveByPlanOperationId(operation.getId());
    }

    private HcAdhesiveGlueBoardUsageDO applyAdhesive2FaiGlueBoardSample(HcAdhesive2FaiApplyReqVO reqVO,
                                                                        HcPlanOrderOperationDO operation,
                                                                        HcProcessReportDO latestStartReport) {
        if (reqVO.getGlueBoardUsageId() == null) {
            throw invalidParamException("请先登记胶板领用信息，再提交胶板送检");
        }
        HcAdhesiveGlueBoardUsageDO usage = hcAdhesiveGlueBoardUsageMapper.selectById(reqVO.getGlueBoardUsageId());
        if (usage == null || Boolean.TRUE.equals(usage.getDeleted())
                || !Objects.equals(usage.getPlanOperationId(), operation.getId())) {
            throw invalidParamException("胶板领用记录不存在或不属于当前粘胶2工序");
        }
        if (!"ACTIVE".equalsIgnoreCase(StrUtil.blankToDefault(usage.getUsageStatus(), "ACTIVE"))) {
            throw invalidParamException("当前胶板领用记录已关闭，不能提交胶板送检");
        }
        if (StrUtil.isNotBlank(reqVO.getGlueBoardMaterialCode())
                && StrUtil.isNotBlank(usage.getGlueBoardMaterialCode())
                && !StrUtil.trim(reqVO.getGlueBoardMaterialCode()).equalsIgnoreCase(StrUtil.trim(usage.getGlueBoardMaterialCode()))) {
            throw invalidParamException("送检胶板料号与当前胶板领用记录不一致");
        }
        if (StrUtil.isNotBlank(reqVO.getGlueBoardBatchNo())
                && StrUtil.isNotBlank(usage.getGlueBoardBatchNo())
                && !StrUtil.trim(reqVO.getGlueBoardBatchNo()).equalsIgnoreCase(StrUtil.trim(usage.getGlueBoardBatchNo()))) {
            throw invalidParamException("送检胶板批号与当前胶板领用记录不一致");
        }
        BigDecimal sampleLength = zeroIfNull(reqVO.getSampleLength());
        if (sampleLength.compareTo(BigDecimal.ZERO) <= 0) {
            throw invalidParamException("送检长度必须大于0");
        }
        if (STOCK_MEASURE_COUNT.equals(normalizeStockMeasureMode(usage.getStockMeasureMode(), null))) {
            throw invalidParamException("当前胶板按数量管理，不能按长度提交胶板送检");
        }
        BigDecimal currentAvailableStart = resolveGlueBoardAvailableStartPosition(usage);
        BigDecimal sampleStart = firstNonNullDecimal(reqVO.getSampleStartPosition(), currentAvailableStart);
        BigDecimal currentAvailableLength = resolveGlueBoardAvailableLength(usage);
        if (currentAvailableLength.compareTo(sampleLength) < 0) {
            throw invalidParamException("胶板剩余长度不足，当前可用" + formatDecimal(currentAvailableLength) + "m");
        }
        BigDecimal currentAvailableEnd = currentAvailableStart.add(currentAvailableLength);
        if (sampleStart.compareTo(currentAvailableStart) < 0 || sampleStart.add(sampleLength).compareTo(currentAvailableEnd) > 0) {
            throw invalidParamException("送检取样范围超出当前胶板可用范围");
        }

        BigDecimal nextAqcSampleLength = zeroIfNull(usage.getAqcSampleLength()).add(sampleLength);
        BigDecimal nextAvailableLength = currentAvailableLength.subtract(sampleLength);
        HcAdhesiveGlueBoardUsageDO updateUsage = HcAdhesiveGlueBoardUsageDO.builder()
                .id(usage.getId())
                .aqcSampleLength(nextAqcSampleLength)
                .availableStartPosition(currentAvailableStart)
                .availableLength(nextAvailableLength)
                .returnedStartPosition(currentAvailableStart)
                .returnedLength(nextAvailableLength)
                .qualityStatus(QUALITY_STATUS_WAITING)
                .build();
        hcAdhesiveGlueBoardUsageMapper.updateById(updateUsage);
        updateGlueBoardStockQuality(usage.getGlueBoardStockId(), QUALITY_STATUS_WAITING, LocalDateTime.now());

        usage.setAqcSampleLength(nextAqcSampleLength);
        usage.setAvailableStartPosition(currentAvailableStart);
        usage.setAvailableLength(nextAvailableLength);
        usage.setReturnedStartPosition(currentAvailableStart);
        usage.setReturnedLength(nextAvailableLength);
        usage.setQualityStatus(QUALITY_STATUS_WAITING);
        storeAdhesive2FaiSampleInfo(latestStartReport, usage, sampleStart, sampleLength);
        return usage;
    }

    private void storeAdhesive2FaiSampleInfo(HcProcessReportDO startReport,
                                             HcAdhesiveGlueBoardUsageDO usage,
                                             BigDecimal sampleStart,
                                             BigDecimal sampleLength) {
        if (startReport == null || startReport.getId() == null) {
            return;
        }
        Map<String, Object> extra = parseRoughExtraMap(startReport.getExtraJson());
        Map<String, Object> sampleInfo = new LinkedHashMap<>();
        sampleInfo.put("glueBoardUsageId", usage.getId());
        sampleInfo.put("glueBoardMaterialCode", usage.getGlueBoardMaterialCode());
        sampleInfo.put("glueBoardBatchNo", usage.getGlueBoardBatchNo());
        sampleInfo.put("sampleStartPosition", sampleStart);
        sampleInfo.put("sampleLength", sampleLength);
        extra.put("adhesive2FaiSample", sampleInfo);
        String extraJson = JsonUtils.toJsonString(extra);
        HcProcessReportDO updateReport = new HcProcessReportDO();
        updateReport.setId(startReport.getId());
        updateReport.setExtraJson(extraJson);
        hcProcessReportMapper.updateById(updateReport);
        startReport.setExtraJson(extraJson);
    }

    private Map<String, Object> getAdhesive2FaiSampleInfo(HcProcessReportDO startReport) {
        if (startReport == null) {
            return Collections.emptyMap();
        }
        Object raw = parseRoughExtraMap(startReport.getExtraJson()).get("adhesive2FaiSample");
        if (raw instanceof Map<?, ?> map) {
            Map<String, Object> result = new LinkedHashMap<>();
            map.forEach((key, value) -> result.put(String.valueOf(key), value));
            return result;
        }
        return Collections.emptyMap();
    }

    private String buildAdhesive2FaiRemark(HcAdhesive2FaiApplyReqVO reqVO, HcAdhesiveGlueBoardUsageDO usage) {
        String baseRemark = firstNotBlank(reqVO.getRemark(), "粘胶2 FAI 工艺参数点检申请");
        return baseRemark + "；胶板批号 " + StrUtil.blankToDefault(usage.getGlueBoardBatchNo(), "-")
                + "；取样起点 " + formatDecimal(reqVO.getSampleStartPosition()) + "m"
                + "；送检长度 " + formatDecimal(reqVO.getSampleLength()) + "m";
    }

    private void syncAdhesive2ReportFaiSummary(HcProcessReportDO startReport, QmsFaiOrderDO faiOrder) {
        if (startReport == null || faiOrder == null || faiOrder.getId() == null) {
            return;
        }
        HcProcessReportDO updateObj = new HcProcessReportDO();
        updateObj.setId(startReport.getId());
        updateObj.setFaiId(faiOrder.getId());
        updateObj.setFaiNo(faiOrder.getFaiNo());
        updateObj.setFaiStatus(faiOrder.getStatus());
        updateObj.setFaiJudgment(faiOrder.getJudgment());
        updateObj.setFaiStandardId(faiOrder.getStandardId());
        updateObj.setFaiStandardNo(faiOrder.getStandardNo());
        updateObj.setFaiApplyTime(firstNotNullDateTime(startReport.getFaiApplyTime(), faiOrder.getSubmissionTime(), faiOrder.getCreateTime(), LocalDateTime.now()));
        updateObj.setFaiReturnTime(firstNotNullDateTime(faiOrder.getUpdateTime(), LocalDateTime.now()));
        updateObj.setFaiRejectReason(faiOrder.getLastReturnReason());
        hcProcessReportMapper.updateById(updateObj);

        startReport.setFaiId(updateObj.getFaiId());
        startReport.setFaiNo(updateObj.getFaiNo());
        startReport.setFaiStatus(updateObj.getFaiStatus());
        startReport.setFaiJudgment(updateObj.getFaiJudgment());
        startReport.setFaiStandardId(updateObj.getFaiStandardId());
        startReport.setFaiStandardNo(updateObj.getFaiStandardNo());
        startReport.setFaiApplyTime(updateObj.getFaiApplyTime());
        startReport.setFaiReturnTime(updateObj.getFaiReturnTime());
        startReport.setFaiRejectReason(updateObj.getFaiRejectReason());
    }

    private HcAdhesive2FaiRespVO buildAdhesive2FaiResp(QmsFaiOrderDO faiOrder,
                                                       HcProcessReportDO startReport,
                                                       HcPlanOrderDO planOrder,
                                                       HcPlanOrderOperationDO operation) {
        HcAdhesive2FaiRespVO respVO = new HcAdhesive2FaiRespVO();
        respVO.setSourceReportNo(buildAdhesive2FaiSourceReportNo(planOrder, operation));
        Map<String, Object> sampleInfo = getAdhesive2FaiSampleInfo(startReport);
        BigDecimal glueBoardUsageId = decimalFromObject(sampleInfo.get("glueBoardUsageId"));
        respVO.setGlueBoardUsageId(glueBoardUsageId == null ? null : glueBoardUsageId.longValue());
        respVO.setGlueBoardMaterialCode(sampleInfo.get("glueBoardMaterialCode") == null ? null : String.valueOf(sampleInfo.get("glueBoardMaterialCode")));
        respVO.setGlueBoardBatchNo(sampleInfo.get("glueBoardBatchNo") == null ? null : String.valueOf(sampleInfo.get("glueBoardBatchNo")));
        respVO.setSampleStartPosition(decimalFromObject(sampleInfo.get("sampleStartPosition")));
        respVO.setSampleLength(decimalFromObject(sampleInfo.get("sampleLength")));
        if (faiOrder != null) {
            respVO.setFaiId(faiOrder.getId());
            respVO.setFaiNo(faiOrder.getFaiNo());
            respVO.setSourceReportId(faiOrder.getSourceReportId());
            respVO.setProductBatchNo(faiOrder.getProductBatchNo());
            respVO.setMaterialCode(faiOrder.getMaterialCode());
            respVO.setMaterialName(faiOrder.getMaterialName());
            respVO.setSpecification(faiOrder.getSpecification());
            respVO.setProductModel(faiOrder.getProductModel());
            respVO.setRemark(faiOrder.getRemark());
            respVO.setFaiStatus(faiOrder.getStatus());
            respVO.setFaiJudgment(faiOrder.getJudgment());
            respVO.setFaiStandardId(faiOrder.getStandardId());
            respVO.setFaiStandardNo(faiOrder.getStandardNo());
            respVO.setFaiStandardVersion(faiOrder.getStandardVersion());
            respVO.setFaiApplyTime(firstNotNullDateTime(startReport == null ? null : startReport.getFaiApplyTime(),
                    faiOrder.getSubmissionTime(), faiOrder.getCreateTime()));
            respVO.setFaiReturnTime(firstNotNullDateTime(faiOrder.getUpdateTime(),
                    startReport == null ? null : startReport.getFaiReturnTime()));
            respVO.setFaiRejectReason(firstNotBlank(faiOrder.getLastReturnReason(),
                    startReport == null ? null : startReport.getFaiRejectReason()));
            if (StrUtil.isBlank(respVO.getGlueBoardMaterialCode())) {
                respVO.setGlueBoardMaterialCode(faiOrder.getGlueBoardMaterialCode());
            }
            if (StrUtil.isBlank(respVO.getGlueBoardBatchNo())) {
                respVO.setGlueBoardBatchNo(faiOrder.getGluePlateBatchNo());
            }
            respVO.setAllowReportSubmit(isFaiReleased(faiOrder));
        } else if (startReport != null) {
            respVO.setFaiId(startReport.getFaiId());
            respVO.setFaiNo(startReport.getFaiNo());
            respVO.setFaiStatus(startReport.getFaiStatus());
            respVO.setFaiJudgment(startReport.getFaiJudgment());
            respVO.setFaiStandardId(startReport.getFaiStandardId());
            respVO.setFaiStandardNo(startReport.getFaiStandardNo());
            respVO.setFaiApplyTime(startReport.getFaiApplyTime());
            respVO.setFaiReturnTime(startReport.getFaiReturnTime());
            respVO.setFaiRejectReason(startReport.getFaiRejectReason());
            respVO.setAllowReportSubmit(FAI_STATUS_COMPLETED.equals(startReport.getFaiStatus())
                    && FAI_JUDGMENT_OK.equals(startReport.getFaiJudgment()));
        } else {
            respVO.setAllowReportSubmit(false);
        }
        respVO.setDisplayText(resolveWetFaiDisplayText(respVO.getFaiStatus(), respVO.getFaiJudgment()));
        return respVO;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long startAdhesive2Report(HcAdhesiveReportStartReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectByIdForUpdate(reqVO.getPlanId());
        assertPlanReleasedForStart(planOrder);
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, reqVO.getPlanOperationId());
        if (OP_STATUS_FINISHED.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前粘胶2工序已完工，不能再开工");
        }
        if (OP_STATUS_PAUSED.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前粘胶2工序已暂停，请先复工后再开工");
        }
        if (OP_STATUS_CANCELLED.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前粘胶2工序已作废取消，不能再开工");
        }
        if (OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前粘胶2工序已开工");
        }
        LocalDate reportDate = reqVO.getReportDate() == null ? LocalDate.now() : reqVO.getReportDate();
        LocalDateTime now = LocalDateTime.now();
        LocalDateTime normalizedStartTime = normalizeReportDateTime(reqVO.getStartTime(), reportDate);
        LocalDateTime normalizedRecorderTime = normalizeReportDateTime(reqVO.getRecorderTime(), reportDate);
        if (normalizedStartTime == null || isPlaceholderDateTime(reqVO.getStartTime())
                || isDateOnlyRuntimeDateTime(reqVO.getStartTime(), reportDate)) {
            normalizedStartTime = now;
        }
        if (normalizedRecorderTime == null || isPlaceholderDateTime(reqVO.getRecorderTime())
                || isDateOnlyRuntimeDateTime(reqVO.getRecorderTime(), reportDate)) {
            normalizedRecorderTime = now;
        }
        HcEquipmentDO equipment = validateAdhesive2Equipment(planOrder, operation, reqVO.getEquipmentId());
        String operatorName = firstNotBlank(reqVO.getRecorderName(),
                SecurityFrameworkUtils.getLoginUserNickname(), "系统");

        HcProcessReportDO reportDO = HcProcessReportDO.builder()
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .operationStatus(operation.getOperationStatus())
                .operationSeq(operation.getOpSeq())
                .operationCode(operation.getOpCode())
                .operationName(operation.getOpName())
                .workCenterId(operation.getWorkCenterId())
                .workCenterCode(operation.getWorkCenterCode())
                .workCenterName(operation.getWorkCenterName())
                .equipmentId(equipment.getId())
                .equipmentCode(equipment.getEquipmentCode())
                .equipmentName(equipment.getEquipmentName())
                .materialId(planOrder.getMaterialId())
                .materialCode(planOrder.getMaterialCode())
                .materialName(planOrder.getMaterialName())
                .motherMaterialId(planOrder.getMotherMaterialId())
                .motherMaterialCode(firstNotBlank(operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode()))
                .motherMaterialName(firstNotBlank(operation.getMotherMaterialName(), planOrder.getMotherMaterialName()))
                .motherModelId(planOrder.getMotherModelId())
                .motherModelCode(firstNotBlank(operation.getMotherModelCode(), planOrder.getMotherModelCode()))
                .motherModelName(firstNotBlank(operation.getMotherModelName(), planOrder.getMotherModelName()))
                .batchNo(firstNotBlank(operation.getProductionBatchNo(), planOrder.getProductionBatchNo(), planOrder.getBatchNo(), operation.getBatchNo()))
                .productionBatchNo(firstNotBlank(operation.getProductionBatchNo(), planOrder.getProductionBatchNo()))
                .parentProductionBatchNo(firstNotBlank(operation.getParentProductionBatchNo(), operation.getParentBatchNo(), planOrder.getProductionBatchNo(), planOrder.getBatchNo()))
                .parentBatchNo(firstNotBlank(operation.getParentBatchNo(), planOrder.getBatchNo()))
                .sampleCode(operation.getSampleCode())
                .reportDate(reportDate)
                .startTime(normalizedStartTime)
                .goodQty(BigDecimal.ZERO)
                .scrapQty(BigDecimal.ZERO)
                .recorderName(operatorName)
                .recorderTime(normalizedRecorderTime)
                .reportUom(firstNotBlank(operation.getUom(), operation.getUnitCode(), operation.getUnitName(), planOrder.getTargetUom(), "片"))
                .reportType(REPORT_TYPE_START)
                .sourceMenuCode(SOURCE_MENU_CODE_ADHESIVE2)
                .build();
        hcProcessReportMapper.insert(reportDO);

        HcPlanOrderOperationDO updateObj = new HcPlanOrderOperationDO();
        updateObj.setId(operation.getId());
        updateObj.setOperationStatus(OP_STATUS_RUNNING);
        updateObj.setEquipmentId(equipment.getId());
        updateObj.setEquipmentCode(equipment.getEquipmentCode());
        updateObj.setEquipmentName(equipment.getEquipmentName());
        updateObj.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateObj.setStatusOperatorName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "system"));
        updateObj.setStatusOperateTime(LocalDateTime.now());
        hcPlanOrderOperationMapper.updateById(updateObj);
        // 与粘胶1一致：同一设备可挂接多个生产中计划，设备台账展示最后一次开工计划。
        hcEquipmentService.occupyEquipment(equipment.getId(), planOrder.getPlanNo(), operation.getOpCode(),
                operation.getOpName(), normalizedStartTime, operatorName, normalizedRecorderTime);

        return reportDO.getId();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void switchAdhesive2Equipment(HcAdhesiveReportSwitchEquipmentReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, reqVO.getPlanOperationId());
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前粘胶2工序未开工，不能切换设备");
        }
        HcProcessReportDO latestStartReport = getLatestStartReport(operation.getId(), SOURCE_MENU_CODE_ADHESIVE2);
        if (latestStartReport == null) {
            throw invalidParamException("当前粘胶2工序未找到开工记录，不能切换设备");
        }
        Long oldEquipmentId = firstNotNull(operation.getEquipmentId(), latestStartReport.getEquipmentId());
        String oldEquipmentCode = firstNotBlank(operation.getEquipmentCode(), latestStartReport.getEquipmentCode());
        String oldEquipmentName = firstNotBlank(operation.getEquipmentName(), latestStartReport.getEquipmentName());
        HcEquipmentDO newEquipment = validateAdhesive2Equipment(planOrder, operation, reqVO.getEquipmentId());
        Long newEquipmentId = newEquipment.getId();
        String newEquipmentCode = newEquipment.getEquipmentCode();
        String newEquipmentName = newEquipment.getEquipmentName();
        String operatorName = firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        LocalDateTime recordTime = LocalDateTime.now();
        LocalDateTime startTime = latestStartReport.getStartTime() != null
                ? latestStartReport.getStartTime() : recordTime;
        if (!Objects.equals(oldEquipmentId, newEquipmentId)) {
            // 同机多计划模式下，新计划可覆盖设备台账中的当前展示计划。
            hcEquipmentService.occupyEquipment(newEquipmentId, planOrder.getPlanNo(), operation.getOpCode(),
                    operation.getOpName(), startTime, operatorName, recordTime);
            // 旧设备可能仍被其他计划使用，只在仍展示本计划时才清空。
            releaseAdhesive2EquipmentIfOwnedByPlan(oldEquipmentId, planOrder.getPlanNo(), operatorName, recordTime);
        }

        if (!Objects.equals(oldEquipmentId, newEquipmentId)) {
            HcProcessReportDO switchReport = HcProcessReportDO.builder()
                    .tenantId(planOrder.getTenantId())
                    .planId(planOrder.getId())
                    .planNo(planOrder.getPlanNo())
                    .planOperationId(operation.getId())
                    .operationStatus(OP_STATUS_RUNNING)
                    .operationSeq(operation.getOpSeq())
                    .operationCode(operation.getOpCode())
                    .operationName(operation.getOpName())
                    .workCenterId(operation.getWorkCenterId())
                    .workCenterCode(operation.getWorkCenterCode())
                    .workCenterName(operation.getWorkCenterName())
                    .equipmentId(newEquipmentId)
                    .equipmentCode(newEquipmentCode)
                    .equipmentName(newEquipmentName)
                    .materialId(planOrder.getMaterialId())
                    .materialCode(planOrder.getMaterialCode())
                    .materialName(planOrder.getMaterialName())
                    .motherMaterialId(planOrder.getMotherMaterialId())
                    .motherMaterialCode(firstNotBlank(operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode()))
                    .motherMaterialName(firstNotBlank(operation.getMotherMaterialName(), planOrder.getMotherMaterialName()))
                    .motherModelId(planOrder.getMotherModelId())
                    .motherModelCode(firstNotBlank(operation.getMotherModelCode(), planOrder.getMotherModelCode()))
                    .motherModelName(firstNotBlank(operation.getMotherModelName(), planOrder.getMotherModelName()))
                    .batchNo(firstNotBlank(operation.getProductionBatchNo(), planOrder.getProductionBatchNo(),
                            planOrder.getBatchNo(), operation.getBatchNo()))
                    .productionBatchNo(firstNotBlank(operation.getProductionBatchNo(), planOrder.getProductionBatchNo()))
                    .parentProductionBatchNo(firstNotBlank(operation.getParentProductionBatchNo(),
                            operation.getParentBatchNo(), planOrder.getProductionBatchNo(), planOrder.getBatchNo()))
                    .parentBatchNo(firstNotBlank(operation.getParentBatchNo(), planOrder.getBatchNo()))
                    .sampleCode(operation.getSampleCode())
                    .reportDate(latestStartReport.getReportDate() == null ? LocalDate.now() : latestStartReport.getReportDate())
                    .startTime(startTime)
                    .goodQty(BigDecimal.ZERO)
                    .scrapQty(BigDecimal.ZERO)
                    .recorderName(operatorName)
                    .recorderTime(recordTime)
                    .reportUom(firstNotBlank(operation.getUom(), operation.getUnitCode(),
                            operation.getUnitName(), planOrder.getTargetUom(), "片"))
                    .reportType(ADHESIVE2_REPORT_TYPE_EQUIPMENT_SWITCH)
                    .sourceMenuCode(SOURCE_MENU_CODE_ADHESIVE2)
                    .remark(firstNotBlank(reqVO.getSwitchReason(), "粘胶2工单切换机台"))
                    .extraJson(buildAdhesive2EquipmentSwitchExtra(oldEquipmentId, oldEquipmentCode,
                            oldEquipmentName, newEquipment, reqVO.getSwitchReason(), operatorName, recordTime))
                    .build();
            hcProcessReportMapper.insert(switchReport);
        }

        HcPlanOrderOperationDO updateOperation = new HcPlanOrderOperationDO();
        updateOperation.setId(operation.getId());
        updateOperation.setEquipmentId(newEquipmentId);
        updateOperation.setEquipmentCode(newEquipmentCode);
        updateOperation.setEquipmentName(newEquipmentName);
        updateOperation.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateOperation.setStatusOperatorName(operatorName);
        updateOperation.setStatusOperateTime(recordTime);
        hcPlanOrderOperationMapper.updateById(updateOperation);
    }

    private void releaseAdhesive2EquipmentIfOwnedByPlan(Long equipmentId, String planNo,
                                                         String operatorName, LocalDateTime recordTime) {
        if (equipmentId == null) {
            return;
        }
        HcEquipmentDO oldEquipment = hcEquipmentService.getHcEquipment(equipmentId);
        if (oldEquipment != null && Objects.equals(StrUtil.trimToEmpty(oldEquipment.getCurrentPlanNo()),
                StrUtil.trimToEmpty(planNo))) {
            hcEquipmentService.clearEquipmentBinding(equipmentId, "IDLE", operatorName, recordTime);
        }
    }

    private String buildAdhesive2EquipmentSwitchExtra(Long oldEquipmentId, String oldEquipmentCode,
                                                       String oldEquipmentName, HcEquipmentDO newEquipment,
                                                       String switchReason, String operatorName,
                                                       LocalDateTime recordTime) {
        Map<String, Object> extra = new LinkedHashMap<>();
        extra.put("oldEquipmentId", oldEquipmentId);
        extra.put("oldEquipmentCode", oldEquipmentCode);
        extra.put("oldEquipmentName", oldEquipmentName);
        extra.put("newEquipmentId", newEquipment.getId());
        extra.put("newEquipmentCode", newEquipment.getEquipmentCode());
        extra.put("newEquipmentName", newEquipment.getEquipmentName());
        extra.put("switchReason", StrUtil.trimToEmpty(switchReason));
        extra.put("operatorName", operatorName);
        extra.put("switchTime", recordTime.format(DATETIME_FORMATTER));
        return JsonUtils.toJsonString(extra);
    }

    @Override
    public List<HcWetPassWorkRespVO> getAdhesive2PassWorkList(Long planId, Long planOperationId,
                                                              Long equipmentId, LocalDate requestRecordDate) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, planOperationId);
        Long originalEquipmentId = operation.getEquipmentId();
        if (equipmentId != null) {
            operation.setEquipmentId(equipmentId);
        }
        try {
            return buildEquipmentDailyPassWorkList(operation, PROCESS_CODE_ADHESIVE2,
                    requestRecordDate == null ? LocalDate.now() : requestRecordDate);
        } finally {
            operation.setEquipmentId(originalEquipmentId);
        }
    }

