    @Override
    public List<HcAdhesiveCheckItemRespVO> getAdhesive2CheckTemplate(String modelCode) {
        if (StrUtil.isBlank(normalizePressSlotModelCode(modelCode))) {
            return Collections.emptyList();
        }
        HcStationFormDO form = requireAdhesive2StationFormConfig(PRESS_SLOT_PRODUCTION_CHECK_FORM_TYPE, modelCode);
        return getAdhesive2StationFormItems(form, PRESS_SLOT_PRODUCTION_CHECK_FORM_TYPE).stream()
                .map(item -> {
                    HcAdhesiveCheckItemRespVO resp = new HcAdhesiveCheckItemRespVO();
                    resp.setId(item.getId());
                    resp.setItemCategory(StrUtil.blankToDefault(item.getItemCategory(), "其他"));
                    resp.setItemName(item.getItemName());
                    resp.setStandardValue(item.getStandardText());
                    resp.setActualValue("");
                    resp.setCheckResult(StrUtil.blankToDefault(item.getDefaultResult(), "OK"));
                    resp.setAbnormalRemark("");
                    resp.setSortNo(item.getItemSeq());
                    return resp;
                })
                .toList();
    }

    private boolean isPressSlotFirstInspectionSampleTerminal(HcPressSlotReportDO source) {
        return findTerminalPressSlotFirstInspectionSample(source) != null;
    }

    private void validateAdhesive2SourceNotPressSlotFirstInspectionSample(HcPressSlotReportDO source) {
        QmsFaiOrderDO faiOrder = findTerminalPressSlotFirstInspectionSample(source);
        if (faiOrder == null) {
            return;
        }
        String resultText = isFaiReleased(faiOrder) ? "OK" : "NG";
        throw invalidParamException("压槽片号 "
                + StrUtil.blankToDefault(source == null ? null : source.getProductionBatchNo(), "-")
                + " 已作为压槽首检样片，首检结果为 " + resultText + "，不进入粘胶2待加工");
    }

    private QmsFaiOrderDO findTerminalPressSlotFirstInspectionSample(HcPressSlotReportDO source) {
        if (source == null) {
            return null;
        }
        String productionBatchNo = firstNotBlank(source.getProductionBatchNo(), source.getSourceProductionBatchNo());
        if (StrUtil.isBlank(productionBatchNo)) {
            return null;
        }
        QmsFaiOrderDO faiOrder = qmsFaiOrderMapper.selectLatestTerminalPressSlotFirstInspection(
                SOURCE_MENU_CODE_PRESS_SLOT, source.getPlanId(), productionBatchNo);
        return isTerminalPressSlotFirstInspectionFai(faiOrder) ? faiOrder : null;
    }

    @Override
    public HcAdhesiveSourceRespVO scanAdhesive2Source(String batchNo) {
        String normalizedBatchNo = StrUtil.trimToEmpty(batchNo);
        if (StrUtil.isBlank(normalizedBatchNo)) {
            throw invalidParamException("请扫描或输入压槽已确认片号");
        }
        HcPressSlotReportDO source = hcPressSlotReportMapper.selectConfirmedByProductionBatchNo(normalizedBatchNo);
        if (source == null) {
            throw invalidParamException("未找到已确认的压槽片号，不能进入粘胶2报工");
        }
        validateAdhesive2SourceNotPressSlotFirstInspectionSample(source);
        validateAdhesive2SourceNotPressSlotProcessCheck(source);
        if (isPressSlotSourceNg(source)
                || hcNgInventoryService.isNgPieceManaged(SOURCE_TYPE_PRESS_SLOT, source.getId())) {
            throw invalidParamException("该压槽片号为不合格品，不能进入粘胶2报工");
        }
        return buildAdhesive2SourceResp(source);
    }

    @Override
    public List<HcAdhesiveSourceRespVO> getAdhesive2SourceList(Long planId, Long planOperationId, String sourceBatchNo) {
        if (planId == null || planOperationId == null) {
            return Collections.emptyList();
        }
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        validateAdhesive2Operation(planOrder, planOperationId);
        String targetSegmentBatchNo = normalizePressSlotMiddleBatchNo(sourceBatchNo);
        Map<String, HcAdhesiveSourceRespVO> sourceMap = new LinkedHashMap<>();
        hcPressSlotReportMapper.selectConfirmedListByPlanId(planId)
                .stream()
                .filter(source -> !isPressSlotFirstInspectionSampleTerminal(source))
                .filter(source -> !isPressSlotProcessCheckReport(source))
                .map(this::buildAdhesive2SourceResp)
                .filter(source -> matchesAdhesive2SourceSegment(source, targetSegmentBatchNo))
                .forEach(source -> putAdhesive2Source(sourceMap, source, true));
        // 粘胶2工作台需要展示尚未进入压槽的分切 NG；压槽记录优先，避免同片重复显示。
        hcSlittingSliceRecordMapper.selectConfirmedListByPlanId(planId)
                .stream()
                .filter(this::isSlittingSliceNg)
                .map(this::buildAdhesive2SlittingAbnormalSourceResp)
                .filter(source -> matchesAdhesive2SourceSegment(source, targetSegmentBatchNo))
                .forEach(source -> putAdhesive2Source(sourceMap, source, false));
        List<HcAdhesiveSourceRespVO> sources = new ArrayList<>(sourceMap.values());
        applyAdhesive2TailSelections(planOperationId, sources);
        return sources;
    }

    private void applyAdhesive2TailSelections(Long planOperationId, List<HcAdhesiveSourceRespVO> sources) {
        if (planOperationId == null || CollUtil.isEmpty(sources)) {
            return;
        }
        Map<String, HcAdhesive2TailSelectionDO> selectionMap = hcAdhesive2TailSelectionMapper
                .selectListByPlanOperationId(planOperationId).stream()
                .collect(Collectors.toMap(
                        item -> normalizeAdhesive2TailSourceBatchNo(item.getSourceProductionBatchNo()),
                        item -> item,
                        (left, right) -> right,
                        LinkedHashMap::new));
        for (HcAdhesiveSourceRespVO source : sources) {
            HcAdhesive2TailSelectionDO selection = selectionMap.get(
                    normalizeAdhesive2TailSourceBatchNo(source.getProductionBatchNo()));
            if (selection == null) {
                continue;
            }
            source.setActualSizeRule(selection.getActualSizeRule());
            source.setActualSizeSuffix(selection.getActualSizeSuffix());
        }
    }

    private String normalizeAdhesive2TailSourceBatchNo(String sourceProductionBatchNo) {
        return StrUtil.trimToEmpty(sourceProductionBatchNo).toUpperCase();
    }

    @Override
    public List<HcAdhesiveReportRespVO> getAdhesive2ReportList(Long planOperationId) {
        return getAdhesive2ReportList(planOperationId, null);
    }

    @Override
    public List<HcAdhesiveReportRespVO> getAdhesive2ReportList(Long planOperationId, LocalDate scanConfirmDate) {
        if (planOperationId == null) {
            return Collections.emptyList();
        }
        LocalDateTime scanConfirmStart = scanConfirmDate == null ? null : scanConfirmDate.atStartOfDay();
        LocalDateTime scanConfirmEndExclusive = scanConfirmStart == null ? null : scanConfirmStart.plusDays(1);
        List<HcAdhesive2ReportDO> reports = hcAdhesive2ReportMapper.selectListByPlanOperationId(
                planOperationId, scanConfirmStart, scanConfirmEndExclusive);
        Map<Long, HcCutRoundReportDO> feedbackMap = loadAdhesive2DownstreamFeedbackMap(reports);
        Map<Long, String> editBlockedReasonMap = loadAdhesive2EditBlockedReasonMap(reports);
        List<HcAdhesiveReportRespVO> result = new ArrayList<>();
        for (HcAdhesive2ReportDO report : reports) {
            HcAdhesiveReportRespVO resp = buildAdhesive2ReportResp(report);
            applyReportDownstreamFeedback(resp, feedbackMap.get(report.getId()), PROCESS_CODE_CUT_ROUND,
                    "裁切", "粘胶2");
            resp.setEditBlockedReason(editBlockedReasonMap.get(report.getId()));
            resp.setCheckItems(hcAdhesive2CheckDetailMapper.selectListByReportId(report.getId()).stream()
                    .map(this::buildAdhesive2CheckItemResp)
                    .toList());
            result.add(resp);
        }
        return result;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long saveAdhesive2Report(HcAdhesiveReportSaveReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, reqVO.getPlanOperationId());
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            if (OP_STATUS_FINISHED.equals(operation.getOperationStatus())) {
                throw invalidParamException("当前工单此工序已完工，不能再报工！");
            }
            throw invalidParamException("当前工单此工序未开工，请先执行开工确认");
        }
        HcPressSlotReportDO source = hcPressSlotReportMapper.selectById(reqVO.getSourceGrindingSecondDetailId());
        if (source == null || Boolean.TRUE.equals(source.getDeleted())) {
            throw invalidParamException("来源压槽片号不存在");
        }
        if (!isPressSlotConfirmedReport(source)) {
            throw invalidParamException("来源压槽片号未扫码确认，不能粘胶2报工");
        }
        validateAdhesive2SourceNotPressSlotFirstInspectionSample(source);
        validateAdhesive2SourceNotPressSlotProcessCheck(source);
        HcAdhesive2ReportDO existedReport = null;
        boolean overwriteConfirmed = false;
        if (reqVO.getId() != null) {
            existedReport = hcAdhesive2ReportMapper.selectById(reqVO.getId());
            if (existedReport == null || Boolean.TRUE.equals(existedReport.getDeleted())) {
                throw invalidParamException("粘胶2报工记录不存在");
            }
            String existedStatus = StrUtil.blankToDefault(existedReport.getReportStatus(), "DRAFT");
            if ("SUBMITTED".equalsIgnoreCase(existedStatus)) {
                throw invalidParamException("当前粘胶2报工记录已过站提交，不能修改");
            }
            overwriteConfirmed = "CONFIRMED".equalsIgnoreCase(existedStatus);
            if (overwriteConfirmed) {
                validateAdhesive2OverwriteAllowed(existedReport);
                if (!Objects.equals(existedReport.getPlanId(), reqVO.getPlanId())
                        || !Objects.equals(existedReport.getPlanOperationId(), reqVO.getPlanOperationId())
                        || !Objects.equals(existedReport.getSourcePressSlotReportId(), source.getId())) {
                    throw invalidParamException("已确认粘胶2覆盖修改时不能变更计划、工序或来源压槽片号");
                }
            } else if (!"DRAFT".equalsIgnoreCase(existedStatus)) {
                throw invalidParamException("当前粘胶2报工记录已提交或确认，不能修改");
            }
        }
        if (!overwriteConfirmed && (isPressSlotSourceNg(source)
                || hcNgInventoryService.isNgPieceManaged(SOURCE_TYPE_PRESS_SLOT, source.getId()))) {
            throw invalidParamException("来源压槽片号为不合格品或已进入隔离管理，不能粘胶2报工");
        }
        List<HcAdhesive2ReportDO> occupiedReports = hcAdhesive2ReportMapper.selectListBySourcePressSlotReportId(source.getId());
        Long existedReportId = existedReport == null ? null : existedReport.getId();
        boolean occupied = occupiedReports.stream()
                .anyMatch(item -> existedReportId == null || !Objects.equals(item.getId(), existedReportId));
        if (occupied) {
            throw invalidParamException("来源压槽片号已存在粘胶2报工记录，不能重复报工");
        }
        LocalDate reportDate = reqVO.getReportDate() == null ? LocalDate.now() : reqVO.getReportDate();
        LocalDateTime normalizedStartTime = normalizeReportDateTime(reqVO.getStartTime(), reportDate);
        LocalDateTime normalizedEndTime = normalizeReportDateTime(reqVO.getEndTime(), reportDate);
        LocalDateTime normalizedRecorderTime = normalizeReportDateTime(reqVO.getRecorderTime(), reportDate);
        LocalDateTime now = LocalDateTime.now();
        if (normalizedStartTime == null) {
            normalizedStartTime = now;
        }
        if (normalizedEndTime == null) {
            normalizedEndTime = now;
        }
        if (normalizedRecorderTime == null) {
            normalizedRecorderTime = now;
        }
        BigDecimal inputQty = firstNonNullDecimal(reqVO.getInputLength(), BigDecimal.ONE);
        BigDecimal lossQty = zeroIfNull(reqVO.getLossLength());
        BigDecimal napQty = zeroIfNull(reqVO.getNapSampleLength());
        BigDecimal outputQty = firstNonNullDecimal(reqVO.getOutputLength(), inputQty.subtract(lossQty).subtract(napQty));
        if (outputQty.compareTo(BigDecimal.ZERO) < 0) {
            throw invalidParamException("粘胶2合格数量不能小于0");
        }
        Map<String, Object> extra = new LinkedHashMap<>(parseRoughExtraMap(reqVO.getExtraJson()));
        boolean preProcessSelfCheckAbnormal = normalizeAdhesive2PreProcessSelfCheckAttribution(reqVO, source, extra);
        String glueBoardModel = overwriteConfirmed ? existedReport.getGlueBoardModel()
                : firstNotBlank((String) extra.get("glueBoardModel"), reqVO.getGlueBoardMaterialCode());
        HcAdhesiveGlueBoardUsageDO glueBoardUsage = overwriteConfirmed
                ? (existedReport.getGlueBoardUsageId() == null ? null
                        : hcAdhesiveGlueBoardUsageMapper.selectById(existedReport.getGlueBoardUsageId()))
                : validateAdhesive2GlueBoardUsageForReport(reqVO, operation, new BigDecimal("1.2"));
        if (!overwriteConfirmed) {
            Adhesive2RuntimeProductContext runtime = resolveAdhesive2RuntimeProductContext(planOrder, operation,
                    getLatestStartReport(operation.getId(), SOURCE_MENU_CODE_ADHESIVE2),
                    resolveAdhesive2MotherSegmentBatchNo(source), null, null);
            validateReportProductModel(runtime.productModel(), reqVO.getModelCode());
            HcAdhesiveGlueBoardStockDO matchedStock = validateStrictGlueBoardMatch("ADHESIVE2", runtime.productModel(),
                    reqVO.getGlueBoardUsageId(), reqVO.getGlueBoardMaterialCode(), reqVO.getGlueBoardBatchNo(),
                    toStringValue(extra.get("glueBoardModel")), true);
            glueBoardModel = matchedStock.getGlueBoardModel();
            extra.put("glueBoardModel", glueBoardModel);
            extra.put("runtimeGlueBoardModel", glueBoardModel);
            extra.put("glueBoardMaterialCode", matchedStock.getGlueBoardMaterialCode());
            extra.put("glueBoardBatchNo", matchedStock.getGlueBoardBatchNo());
        }
        BigDecimal glueBoardUseLength = overwriteConfirmed ? existedReport.getGlueBoardUseLength()
                : firstNonNullDecimal(reqVO.getGlueBoardUseLength(), new BigDecimal("1.2"));
        GlueBoardInspectionAbnormalMeta glueBoardInspectionAbnormal = overwriteConfirmed
                ? null : resolveGlueBoardInspectionAbnormalMeta(glueBoardUsage, normalizedEndTime);
        String glueBoardMaterialCode = overwriteConfirmed ? existedReport.getGlueBoardMaterialCode()
                : firstNotBlank(reqVO.getGlueBoardMaterialCode(), glueBoardUsage.getGlueBoardMaterialCode());
        String glueBoardBatchNo = overwriteConfirmed ? existedReport.getGlueBoardBatchNo()
                : firstNotBlank(reqVO.getGlueBoardBatchNo(), glueBoardUsage.getGlueBoardBatchNo());
        String productQualityStatus = overwriteConfirmed ? existedReport.getProductQualityStatus()
                : glueBoardInspectionAbnormal.abnormal
                        ? PRODUCT_QUALITY_ABNORMAL
                        : StrUtil.blankToDefault(reqVO.getProductQualityStatus(), QUALITY_STATUS_NORMAL);
        String qualityLockReason = overwriteConfirmed ? existedReport.getQualityLockReason()
                : glueBoardInspectionAbnormal.abnormal
                        ? firstNotBlank(reqVO.getQualityLockReason(), glueBoardInspectionAbnormal.reason)
                        : reqVO.getQualityLockReason();
        Long oldGlueBoardUsageId = existedReport == null ? null : existedReport.getGlueBoardUsageId();
        HcPlanOrderInventoryLockDO sourceLock = overwriteConfirmed
                ? (existedReport.getSourcePlanLockId() == null ? null
                        : hcPlanOrderInventoryLockMapper.selectById(existedReport.getSourcePlanLockId()))
                : ensureSourceWipLockedForOperation(planOrder, operation,
                        SOURCE_TYPE_PRESS_SLOT, SOURCE_TABLE_PRESS_SLOT_REPORT, source.getId(),
                        inputQty, firstNotBlank(reqVO.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统"),
                        "粘胶2入站自动锁定压槽中间品");
        String sourceProductionBatchNo = overwriteConfirmed
                ? existedReport.getSourceProductionBatchNo()
                : firstNotBlank(reqVO.getSourceProductionBatchNo(), source.getProductionBatchNo());
        HcAdhesive2TailSelectionDO tailSelection = hcAdhesive2TailSelectionMapper
                .selectByPlanOperationIdAndSourceBatchNo(operation.getId(), sourceProductionBatchNo);
        String selectedActualSizeRule = tailSelection == null ? null : tailSelection.getActualSizeRule();
        String selectedProductionBatchNo = StrUtil.isBlank(selectedActualSizeRule) ? null
                : buildAdhesive2TailBatchNo(sourceProductionBatchNo, selectedActualSizeRule);
        HcAdhesive2ReportDO report = HcAdhesive2ReportDO.builder()
                .id(existedReport == null ? null : existedReport.getId())
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .operationCode(operation.getOpCode())
                .operationName(operation.getOpName())
                .sourcePressSlotReportId(overwriteConfirmed ? existedReport.getSourcePressSlotReportId() : source.getId())
                .sourceStockId(overwriteConfirmed ? existedReport.getSourceStockId()
                        : sourceLock == null ? null : sourceLock.getStockId())
                .sourcePlanLockId(overwriteConfirmed ? existedReport.getSourcePlanLockId()
                        : sourceLock == null ? null : sourceLock.getId())
                .sourceStockBatchNo(overwriteConfirmed ? existedReport.getSourceStockBatchNo()
                        : sourceLock == null ? null : firstNotBlank(sourceLock.getSourceBatchNo(), sourceLock.getBatchNo()))
                .sourceLockQty(overwriteConfirmed ? existedReport.getSourceLockQty()
                        : sourceLock == null ? null : inputQty)
                .sourceSlittingSliceId(overwriteConfirmed ? existedReport.getSourceSlittingSliceId() : source.getSourceSlittingSliceId())
                .sourceBatchNo(overwriteConfirmed ? existedReport.getSourceBatchNo()
                        : firstNotBlank(reqVO.getSourceBatchNo(), resolveAdhesive2MotherSegmentBatchNo(source)))
                .sourceProductionBatchNo(sourceProductionBatchNo)
                .productionBatchNo(overwriteConfirmed || hasAdhesive2TailSelection(existedReport)
                        ? existedReport.getProductionBatchNo()
                        : firstNotBlank(selectedProductionBatchNo, reqVO.getProductionBatchNo(), source.getProductionBatchNo()))
                .actualSizeRule(overwriteConfirmed ? existedReport.getActualSizeRule()
                        : firstNotBlank(selectedActualSizeRule, existedReport == null ? null : existedReport.getActualSizeRule()))
                .actualSizeSuffix(overwriteConfirmed ? existedReport.getActualSizeSuffix()
                        : firstNotBlank(tailSelection == null ? null : tailSelection.getActualSizeSuffix(),
                                existedReport == null ? null : existedReport.getActualSizeSuffix()))
                .parentProductionBatchNo(overwriteConfirmed ? existedReport.getParentProductionBatchNo()
                        : firstNotBlank(reqVO.getParentProductionBatchNo(), resolveAdhesive2MotherSegmentBatchNo(source)))
                .materialCode(preProcessSelfCheckAbnormal
                        ? firstNotBlank(source.getMaterialCode(), planOrder.getMaterialCode())
                        : overwriteConfirmed ? existedReport.getMaterialCode()
                        : firstNotBlank(reqVO.getMaterialCode(), planOrder.getMaterialCode()))
                .materialName(preProcessSelfCheckAbnormal
                        ? firstNotBlank(source.getMaterialName(), planOrder.getMaterialName())
                        : overwriteConfirmed ? existedReport.getMaterialName()
                        : firstNotBlank(reqVO.getMaterialName(), planOrder.getMaterialName()))
                .modelCode(preProcessSelfCheckAbnormal
                        ? firstNotBlank(source.getModelCode(), planOrder.getModelCode(), planOrder.getModelName())
                        : overwriteConfirmed ? existedReport.getModelCode()
                        : firstNotBlank(reqVO.getModelCode(), planOrder.getModelCode(), planOrder.getModelName()))
                .reportDate(overwriteConfirmed ? existedReport.getReportDate() : reportDate)
                .startTime(overwriteConfirmed ? existedReport.getStartTime() : normalizedStartTime)
                .endTime(overwriteConfirmed ? existedReport.getEndTime() : normalizedEndTime)
                .inputLength(overwriteConfirmed ? existedReport.getInputLength() : inputQty)
                .startPosition(overwriteConfirmed ? existedReport.getStartPosition()
                        : firstNonNullDecimal(reqVO.getStartPosition(), source.getStartPosition()))
                .endPosition(overwriteConfirmed ? existedReport.getEndPosition()
                        : firstNonNullDecimal(reqVO.getEndPosition(), source.getEndPosition()))
                .lossLength(overwriteConfirmed ? existedReport.getLossLength() : lossQty)
                .outputLength(overwriteConfirmed ? existedReport.getOutputLength() : outputQty)
                .napSampleLength(overwriteConfirmed ? existedReport.getNapSampleLength() : napQty)
                .glueBoardModel(glueBoardModel)
                .glueBoardMaterialCode(glueBoardMaterialCode)
                .glueBoardBatchNo(glueBoardBatchNo)
                .glueBoardUsageId(overwriteConfirmed ? existedReport.getGlueBoardUsageId() : glueBoardUsage.getId())
                .glueBoardStartPosition(overwriteConfirmed ? existedReport.getGlueBoardStartPosition() : null)
                .glueBoardUseLength(glueBoardUseLength)
                .productQualityStatus(productQualityStatus)
                .qualityLockReason(qualityLockReason)
                .selfCheck(firstNotBlank(reqVO.getSelfCheck(), "OK"))
                .defectCode(reqVO.getDefectCode())
                .reportStatus(existedReport == null ? "DRAFT" : StrUtil.blankToDefault(existedReport.getReportStatus(), "DRAFT"))
                .recorderName(overwriteConfirmed ? existedReport.getRecorderName()
                        : firstNotBlank(reqVO.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统"))
                .recorderTime(overwriteConfirmed ? existedReport.getRecorderTime() : normalizedRecorderTime)
                .remark(reqVO.getRemark())
                .extraJson(JsonUtils.toJsonString(extra))
                .build();
        if (existedReport == null) {
            hcAdhesive2ReportMapper.insert(report);
        } else {
            hcAdhesive2ReportMapper.updateById(report);
            hcAdhesive2CheckDetailMapper.deleteByReportId(report.getId());
        }
        saveAdhesive2CheckDetails(reqVO, planOrder, operation, report.getId());
        if (!overwriteConfirmed) {
            if (oldGlueBoardUsageId != null && !Objects.equals(oldGlueBoardUsageId, report.getGlueBoardUsageId())) {
                recalculateGlueBoardUsage(oldGlueBoardUsageId);
            }
            recalculateGlueBoardUsage(report.getGlueBoardUsageId());
        }
        return report.getId();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public List<Long> assignAdhesive2ReportTails(HcAdhesive2TailAssignReqVO reqVO) {
        Map<Long, HcAdhesive2ReportDO> reports = new LinkedHashMap<>();
        Map<Long, String> actualSizeRules = new LinkedHashMap<>();
        Map<Long, String> productionBatchNos = new LinkedHashMap<>();
        Set<String> selectedBatchNos = new LinkedHashSet<>();
        for (HcAdhesive2TailAssignReqVO.Item item : reqVO.getItems()) {
            if (reports.containsKey(item.getId())) {
                throw invalidParamException("一键选择尾号中存在重复的粘胶2报工记录");
            }
            HcAdhesive2ReportDO report = hcAdhesive2ReportMapper.selectById(item.getId());
            if (report == null || Boolean.TRUE.equals(report.getDeleted())) {
                throw invalidParamException("粘胶2报工记录不存在");
            }
            if (!"DRAFT".equalsIgnoreCase(StrUtil.blankToDefault(report.getReportStatus(), "DRAFT"))) {
                throw invalidParamException("粘胶2报工记录已扫码确认或过站，不能再选择尾号");
            }
            String actualSizeRule = normalizeAdhesive2ActualSizeRule(item.getActualSizeRule());
            if (StrUtil.isBlank(actualSizeRule)) {
                throw invalidParamException("实际尺寸仅支持 775mm（尾号A）或 740mm（尾号B）");
            }
            if (isAdhesive2ReportPrinted(report) && !Objects.equals(actualSizeRule, report.getActualSizeRule())) {
                throw invalidParamException("粘胶2流转单已打印，不能再调整尾号；如需变更请先按现场作废流程处理旧流转单");
            }
            String sourceProductionBatchNo = firstNotBlank(report.getSourceProductionBatchNo(), report.getProductionBatchNo());
            String finalProductionBatchNo = buildAdhesive2TailBatchNo(sourceProductionBatchNo, actualSizeRule);
            if (StrUtil.isBlank(finalProductionBatchNo)) {
                throw invalidParamException("缺少来源片号，不能选择尾号");
            }
            if (!selectedBatchNos.add(finalProductionBatchNo)) {
                throw invalidParamException("一键选择尾号后存在重复片号：" + finalProductionBatchNo);
            }
            HcAdhesive2ReportDO duplicated = hcAdhesive2ReportMapper.selectByProductionBatchNo(finalProductionBatchNo);
            if (duplicated != null && !Objects.equals(duplicated.getId(), report.getId())) {
                throw invalidParamException("片号尾号已被其他粘胶2报工记录占用：" + finalProductionBatchNo);
            }
            reports.put(report.getId(), report);
            actualSizeRules.put(report.getId(), actualSizeRule);
            productionBatchNos.put(report.getId(), finalProductionBatchNo);
        }
        for (HcAdhesive2ReportDO report : reports.values()) {
            String actualSizeRule = actualSizeRules.get(report.getId());
            HcAdhesive2ReportDO update = new HcAdhesive2ReportDO();
            update.setId(report.getId());
            update.setProductionBatchNo(productionBatchNos.get(report.getId()));
            update.setActualSizeRule(actualSizeRule);
            update.setActualSizeSuffix(getAdhesive2TailSuffix(actualSizeRule));
            hcAdhesive2ReportMapper.updateById(update);
        }
        return new ArrayList<>(reports.keySet());
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public int assignAdhesive2TailForSelectedSources(HcAdhesive2TailSelectedAssignReqVO reqVO) {
        // 与扫码确认共用工序锁，避免校验草稿后被并发确认。
        if (hcPlanOrderOperationMapper.selectByIdForUpdate(reqVO.getPlanOperationId()) == null) {
            throw invalidParamException("粘胶2计划工序不存在");
        }
        HcPlanOrderDO plan = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(plan, reqVO.getPlanOperationId());
        Set<String> sources = getAdhesive2SourceList(plan.getId(), operation.getId(), null).stream()
                .map(item -> normalizeAdhesive2TailSourceBatchNo(item.getProductionBatchNo()))
                .collect(Collectors.toSet());
        Map<String, String> rules = new LinkedHashMap<>();
        Set<String> targets = new LinkedHashSet<>();
        for (HcAdhesive2TailSelectedAssignReqVO.Item item : reqVO.getItems()) {
            String source = normalizeAdhesive2TailSourceBatchNo(item.getSourceProductionBatchNo());
            String rule = normalizeAdhesive2ActualSizeRule(item.getActualSizeRule());
            if (!sources.contains(source) || StrUtil.isBlank(rule)) {
                throw invalidParamException("来源片不属于当前工序，或实际尺寸不是775mm/740mm");
            }
            if (rules.putIfAbsent(source, rule) != null
                    || !targets.add(buildAdhesive2TailBatchNo(source, rule))) {
                throw invalidParamException("所选来源片或目标片号重复");
            }
        }
        if (rules.isEmpty()) {
            throw invalidParamException("请至少选择一个来源片");
        }
        List<HcAdhesive2ReportDO> reports = hcAdhesive2ReportMapper.selectListByPlanOperationId(operation.getId());
        for (Map.Entry<String, String> entry : rules.entrySet()) {
            List<HcAdhesive2ReportDO> matched = reports.stream().filter(report -> Objects.equals(entry.getKey(),
                    normalizeAdhesive2TailSourceBatchNo(firstNotBlank(report.getSourceProductionBatchNo(), report.getProductionBatchNo())))).toList();
            for (HcAdhesive2ReportDO report : matched) {
                if (!"DRAFT".equalsIgnoreCase(report.getReportStatus()) || report.getOutputStockId() != null
                        || isAdhesive2ReportPrinted(report)) {
                    throw invalidParamException("片号已确认、已入库或已打印，不能按片调整尾号：" + entry.getKey());
                }
            }
            HcAdhesive2ReportDO duplicate = hcAdhesive2ReportMapper.selectByProductionBatchNo(
                    buildAdhesive2TailBatchNo(entry.getKey(), entry.getValue()));
            if (matched.size() > 1 || (duplicate != null && matched.stream().noneMatch(report -> Objects.equals(report.getId(), duplicate.getId())))) {
                throw invalidParamException("目标片号已被其他报工占用：" + entry.getKey());
            }
        }
        Map<String, HcAdhesive2TailSelectionDO> selections = hcAdhesive2TailSelectionMapper
                .selectListByPlanOperationId(operation.getId()).stream().collect(Collectors.toMap(
                        item -> normalizeAdhesive2TailSourceBatchNo(item.getSourceProductionBatchNo()),
                        item -> item, (left, right) -> right));
        for (Map.Entry<String, String> entry : rules.entrySet()) {
            HcAdhesive2TailSelectionDO selection = selections.get(entry.getKey());
            HcAdhesive2TailSelectionDO update = HcAdhesive2TailSelectionDO.builder()
                    .tenantId(plan.getTenantId()).planId(plan.getId()).planOperationId(operation.getId())
                    .sourceProductionBatchNo(entry.getKey()).actualSizeRule(entry.getValue())
                    .actualSizeSuffix(getAdhesive2TailSuffix(entry.getValue())).build();
            if (selection == null) {
                hcAdhesive2TailSelectionMapper.insert(update);
            } else {
                update.setId(selection.getId());
                hcAdhesive2TailSelectionMapper.updateById(update);
            }
        }
        for (HcAdhesive2ReportDO report : reports) {
            String source = normalizeAdhesive2TailSourceBatchNo(firstNotBlank(report.getSourceProductionBatchNo(), report.getProductionBatchNo()));
            if (!rules.containsKey(source)) continue;
            HcAdhesive2ReportDO update = new HcAdhesive2ReportDO();
            update.setId(report.getId());
            update.setActualSizeRule(rules.get(source));
            update.setActualSizeSuffix(getAdhesive2TailSuffix(rules.get(source)));
            update.setProductionBatchNo(buildAdhesive2TailBatchNo(source, rules.get(source)));
            hcAdhesive2ReportMapper.updateById(update);
        }
        return rules.size();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public int assignAdhesive2TailForAllSources(HcAdhesive2TailBatchAssignReqVO reqVO) {
        if (hcPlanOrderOperationMapper.selectByIdForUpdate(reqVO.getPlanOperationId()) == null) {
            throw invalidParamException("粘胶2计划工序不存在");
        }
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, reqVO.getPlanOperationId());
        String actualSizeRule = normalizeAdhesive2ActualSizeRule(reqVO.getActualSizeRule());
        if (StrUtil.isBlank(actualSizeRule)) {
            throw invalidParamException("实际尺寸仅支持 775mm（尾号A）或 740mm（尾号B）");
        }
        List<HcAdhesiveSourceRespVO> sources = getAdhesive2SourceList(planOrder.getId(), operation.getId(), null);
        Map<String, HcAdhesiveSourceRespVO> sourceMap = new LinkedHashMap<>();
        Set<String> targetBatchNos = new LinkedHashSet<>();
        for (HcAdhesiveSourceRespVO source : sources) {
            String sourceBatchNo = normalizeAdhesive2TailSourceBatchNo(source.getProductionBatchNo());
            String targetBatchNo = buildAdhesive2TailBatchNo(sourceBatchNo, actualSizeRule);
            if (StrUtil.isBlank(sourceBatchNo) || StrUtil.isBlank(targetBatchNo)) {
                continue;
            }
            if (!targetBatchNos.add(targetBatchNo)) {
                throw invalidParamException("统一选择尾号后存在重复片号：" + targetBatchNo);
            }
            sourceMap.put(sourceBatchNo, source);
        }
        if (sourceMap.isEmpty()) {
            throw invalidParamException("当前粘胶2工作台没有可修改尾号的来源片号");
        }

        Map<String, HcAdhesive2TailSelectionDO> existedSelections = hcAdhesive2TailSelectionMapper
                .selectListByPlanOperationId(operation.getId()).stream()
                .collect(Collectors.toMap(
                        item -> normalizeAdhesive2TailSourceBatchNo(item.getSourceProductionBatchNo()),
                        item -> item,
                        (left, right) -> right,
                        LinkedHashMap::new));
        String suffix = getAdhesive2TailSuffix(actualSizeRule);
        for (String sourceBatchNo : sourceMap.keySet()) {
            HcAdhesive2TailSelectionDO selection = existedSelections.get(sourceBatchNo);
            if (selection == null) {
                hcAdhesive2TailSelectionMapper.insert(HcAdhesive2TailSelectionDO.builder()
                        .tenantId(planOrder.getTenantId())
                        .planId(planOrder.getId())
                        .planOperationId(operation.getId())
                        .sourceProductionBatchNo(sourceBatchNo)
                        .actualSizeRule(actualSizeRule)
                        .actualSizeSuffix(suffix)
                        .build());
                continue;
            }
            HcAdhesive2TailSelectionDO update = new HcAdhesive2TailSelectionDO();
            update.setId(selection.getId());
            update.setActualSizeRule(actualSizeRule);
            update.setActualSizeSuffix(suffix);
            hcAdhesive2TailSelectionMapper.updateById(update);
        }

        List<HcAdhesive2ReportDO> reports = hcAdhesive2ReportMapper.selectListByPlanOperationId(operation.getId())
                .stream()
                .filter(report -> sourceMap.containsKey(
                        normalizeAdhesive2TailSourceBatchNo(report.getSourceProductionBatchNo())))
                .toList();
        Set<Long> targetReportIds = reports.stream().map(HcAdhesive2ReportDO::getId).collect(Collectors.toSet());
        Set<String> reportBatchNos = new LinkedHashSet<>();
        for (HcAdhesive2ReportDO report : reports) {
            String targetBatchNo = buildAdhesive2TailBatchNo(report.getSourceProductionBatchNo(), actualSizeRule);
            if (!reportBatchNos.add(targetBatchNo)) {
                throw invalidParamException("统一选择尾号后存在重复粘胶2报工片号：" + targetBatchNo);
            }
            HcAdhesive2ReportDO duplicated = hcAdhesive2ReportMapper.selectByProductionBatchNo(targetBatchNo);
            if (duplicated != null && !targetReportIds.contains(duplicated.getId())) {
                throw invalidParamException("片号尾号已被其他粘胶2报工记录占用：" + targetBatchNo);
            }
        }
        for (HcAdhesive2ReportDO report : reports) {
            String targetBatchNo = buildAdhesive2TailBatchNo(report.getSourceProductionBatchNo(), actualSizeRule);
            HcAdhesive2ReportDO update = new HcAdhesive2ReportDO();
            update.setId(report.getId());
            update.setProductionBatchNo(targetBatchNo);
            update.setActualSizeRule(actualSizeRule);
            update.setActualSizeSuffix(suffix);
            hcAdhesive2ReportMapper.updateById(update);
            syncAdhesive2OutputStockBatchNo(report, targetBatchNo);
        }
        return sourceMap.size();
    }

    private void syncAdhesive2OutputStockBatchNo(HcAdhesive2ReportDO report, String targetBatchNo) {
        if (report == null || report.getId() == null || StrUtil.isBlank(targetBatchNo)) {
            return;
        }
        HcInvStockDO stock = report.getOutputStockId() == null ? null
                : hcInvStockMapper.selectByIdForUpdate(report.getOutputStockId());
        if (stock == null || Boolean.TRUE.equals(stock.getDeleted())) {
            stock = hcInvStockMapper.selectOneBySourceForUpdate(
                    SOURCE_TYPE_ADHESIVE2, SOURCE_TABLE_ADHESIVE2_REPORT, report.getId());
        }
        if (stock == null || Boolean.TRUE.equals(stock.getDeleted())
                || Objects.equals(stock.getBatchNo(), targetBatchNo)) {
            return;
        }
        HcInvStockDO update = new HcInvStockDO();
        update.setId(stock.getId());
        update.setBatchNo(targetBatchNo);
        hcInvStockMapper.updateById(update);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long saveAndConfirmAdhesive2Report(HcAdhesiveReportSaveConfirmReqVO reqVO) {
        // 必须在保存报工、尾号和库存写入前锁工序，与直接确认和换型启动保持同一锁序。
        if (hcPlanOrderOperationMapper.selectByIdForUpdate(reqVO.getPlanOperationId()) == null) {
            throw invalidParamException("粘胶2报工关联的计划工序不存在");
        }
        if (Boolean.TRUE.equals(reqVO.getOneClickBatchConfirm())) {
            HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
            HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, reqVO.getPlanOperationId());
            HcPressSlotReportDO source = hcPressSlotReportMapper.selectById(reqVO.getSourceGrindingSecondDetailId());
            if (source != null && !Boolean.TRUE.equals(source.getDeleted())) {
                validateAdhesive2OneClickConfirmRuntime(planOrder, operation,
                        resolveAdhesive2MotherSegmentBatchNo(source), reqVO.getExpectedRuntimeModelCode(),
                        reqVO.getModelCode());
            }
        }
        Long reportId = saveAdhesive2Report(reqVO);
        HcAdhesive2TailAssignReqVO tailAssignReqVO = new HcAdhesive2TailAssignReqVO();
        HcAdhesive2TailAssignReqVO.Item tailAssignItem = new HcAdhesive2TailAssignReqVO.Item();
        tailAssignItem.setId(reportId);
        tailAssignItem.setActualSizeRule(reqVO.getActualSizeRule());
        tailAssignReqVO.setItems(List.of(tailAssignItem));
        assignAdhesive2ReportTails(tailAssignReqVO);
        HcAdhesive2ReportDO report = hcAdhesive2ReportMapper.selectById(reportId);
        HcAdhesiveReportConfirmReqVO confirmReqVO = new HcAdhesiveReportConfirmReqVO();
        confirmReqVO.setId(reportId);
        confirmReqVO.setScannedBatchNo(firstNotBlank(reqVO.getScannedBatchNo(),
                report == null ? null : report.getProductionBatchNo(), reqVO.getProductionBatchNo(), reqVO.getSourceProductionBatchNo()));
        confirmReqVO.setOneClickBatchConfirm(reqVO.getOneClickBatchConfirm());
        confirmReqVO.setExpectedRuntimeModelCode(reqVO.getExpectedRuntimeModelCode());
        confirmReqVO.setConfirmerName(reqVO.getConfirmerName());
        confirmReqVO.setConfirmerTime(reqVO.getConfirmerTime());
        confirmReqVO.setActualSizeRule(reqVO.getActualSizeRule());
        confirmReqVO.setGlueBoardModel(reqVO.getGlueBoardModel());
        confirmReqVO.setGlueBoardMaterialCode(reqVO.getGlueBoardMaterialCode());
        confirmReqVO.setGlueBoardBatchNo(reqVO.getGlueBoardBatchNo());
        confirmReqVO.setGlueBoardUsageId(reqVO.getGlueBoardUsageId());
        return confirmAdhesive2Report(confirmReqVO);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long confirmAdhesive2Report(HcAdhesiveReportConfirmReqVO reqVO) {
        HcAdhesive2ReportDO report = hcAdhesive2ReportMapper.selectById(reqVO.getId());
        if (report == null || Boolean.TRUE.equals(report.getDeleted())) {
            throw invalidParamException("粘胶2报工记录不存在");
        }
        if (hcPlanOrderOperationMapper.selectByIdForUpdate(report.getPlanOperationId()) == null) {
            throw invalidParamException("粘胶2报工关联的计划工序不存在");
        }
        // 等待工序锁时，其他请求可能已经确认该片；必须当前读后再判断是否首次确认。
        report = hcAdhesive2ReportMapper.selectByIdForUpdate(reqVO.getId());
        if (report == null || Boolean.TRUE.equals(report.getDeleted())) {
            throw invalidParamException("粘胶2报工记录不存在");
        }
        String reportStatus = StrUtil.blankToDefault(report.getReportStatus(), "DRAFT");
        if ("SUBMITTED".equalsIgnoreCase(reportStatus)) {
            throw invalidParamException("粘胶2报工记录已过站提交，不能重复扫码确认");
        }
        boolean firstConfirm = !"CONFIRMED".equalsIgnoreCase(reportStatus);
        if (!firstConfirm) {
            validateAdhesive2OverwriteAllowed(report);
        } else if (!hasAdhesive2TailSelection(report)) {
            throw invalidParamException("请先选择实际尺寸和片号尾号，再进行扫码确认");
        }
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(report.getPlanId());
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, report.getPlanOperationId());
        if (Boolean.TRUE.equals(reqVO.getOneClickBatchConfirm())) {
            validateAdhesive2OneClickConfirmRuntime(planOrder, operation,
                    resolveAdhesive2MotherSegmentBatchNo(report), reqVO.getExpectedRuntimeModelCode(),
                    report.getModelCode());
        }
        String scannedBatchNo = StrUtil.trim(reqVO.getScannedBatchNo());
        String expectedBatchNo = StrUtil.trim(report.getProductionBatchNo());
        if (StrUtil.isBlank(expectedBatchNo) || !Objects.equals(scannedBatchNo, expectedBatchNo)) {
            throw invalidParamException("扫码片号与粘胶2片号不一致");
        }
        HcProductionInstructionDO changeover = firstConfirm
                ? validateAdhesive2ConfirmChangeover(report) : null;
        HcAdhesive2ReportDO updateReport = new HcAdhesive2ReportDO();
        updateReport.setId(report.getId());
        updateReport.setReportStatus("CONFIRMED");
        Map<String, Object> confirmExtra = new LinkedHashMap<>(parseRoughExtraMap(report.getExtraJson()));
        if (changeover != null) {
            confirmExtra.put("changeoverInstructionId", changeover.getId());
            confirmExtra.put("changeoverInstructionNo", changeover.getInstructionNo());
            confirmExtra.put("changeoverInstructionTargetQty", changeover.getTargetQty());
        }
        String glueBoardModel = firstConfirm ? StrUtil.trim(reqVO.getGlueBoardModel()) : null;
        HcAdhesiveGlueBoardUsageDO glueBoardUsage = firstConfirm
                ? validateAdhesive2GlueBoardUsageForConfirm(reqVO, operation) : null;
        if (firstConfirm) {
            Adhesive2RuntimeProductContext runtime = resolveAdhesive2RuntimeProductContext(planOrder, operation,
                    getLatestStartReport(operation.getId(), SOURCE_MENU_CODE_ADHESIVE2),
                    resolveAdhesive2MotherSegmentBatchNo(report), null, null);
            validateReportProductModel(runtime.productModel(), report.getModelCode());
            // 已登记耗用的草稿不得在确认时悄悄改挂另一卷胶板。
            if (!Objects.equals(report.getGlueBoardUsageId(), reqVO.getGlueBoardUsageId())) {
                throw invalidParamException("扫码胶板与报工登记的胶板领用不一致，请先核实并修改未确认报工用料");
            }
            validateStrictGlueBoardMatch("ADHESIVE2", runtime.productModel(), report.getGlueBoardUsageId(),
                    report.getGlueBoardMaterialCode(), report.getGlueBoardBatchNo(), report.getGlueBoardModel(), true);
            HcAdhesiveGlueBoardStockDO matchedStock = validateStrictGlueBoardMatch("ADHESIVE2", runtime.productModel(),
                    reqVO.getGlueBoardUsageId(), reqVO.getGlueBoardMaterialCode(), reqVO.getGlueBoardBatchNo(), glueBoardModel, true);
            glueBoardModel = matchedStock.getGlueBoardModel();
            confirmExtra.put("runtimeGlueBoardModel", glueBoardModel);
            confirmExtra.put("glueBoardMaterialCode", matchedStock.getGlueBoardMaterialCode());
            confirmExtra.put("glueBoardBatchNo", matchedStock.getGlueBoardBatchNo());
        }
        if (firstConfirm && StrUtil.isNotBlank(glueBoardModel)) {
            confirmExtra.put("glueBoardModel", glueBoardModel);
            updateReport.setGlueBoardModel(glueBoardModel);
        }
        if (changeover != null || (firstConfirm && StrUtil.isNotBlank(glueBoardModel))) {
            updateReport.setExtraJson(JsonUtils.toJsonString(confirmExtra));
        }
        if (firstConfirm && glueBoardUsage != null) {
            updateReport.setGlueBoardUsageId(glueBoardUsage.getId());
            updateReport.setGlueBoardBatchNo(firstNotBlank(reqVO.getGlueBoardBatchNo(), glueBoardUsage.getGlueBoardBatchNo()));
            updateReport.setGlueBoardMaterialCode(firstNotBlank(reqVO.getGlueBoardMaterialCode(), glueBoardUsage.getGlueBoardMaterialCode()));
        } else if (firstConfirm) {
            updateReport.setGlueBoardBatchNo(firstNotBlank(reqVO.getGlueBoardBatchNo(), report.getGlueBoardBatchNo()));
            updateReport.setGlueBoardMaterialCode(firstNotBlank(reqVO.getGlueBoardMaterialCode(), report.getGlueBoardMaterialCode()));
        }
        LocalDateTime confirmerTime = normalizeReportDateTime(reqVO.getConfirmerTime(), report.getReportDate());
        if (confirmerTime == null) {
            confirmerTime = LocalDateTime.now();
        }
        updateReport.setConfirmerName(firstNotBlank(reqVO.getConfirmerName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统"));
        updateReport.setConfirmerTime(confirmerTime);
        hcAdhesive2ReportMapper.updateById(updateReport);
        if (firstConfirm && glueBoardUsage != null && !Objects.equals(report.getGlueBoardUsageId(), glueBoardUsage.getId())) {
            recalculateGlueBoardUsage(report.getGlueBoardUsageId());
            recalculateGlueBoardUsage(glueBoardUsage.getId());
        }
        if (firstConfirm) {
            consumeAdhesive2SourceWipIfPresent(planOrder, operation, report, confirmerTime, updateReport.getConfirmerName());
            postAdhesive2OutputWipIfNeeded(planOrder, operation, report, confirmerTime, updateReport.getConfirmerName());
            if (changeover != null && "EXECUTING".equalsIgnoreCase(changeover.getExecuteStatus())) {
                HcProductionInstructionChangeoverPieceReqVO pieceReq = new HcProductionInstructionChangeoverPieceReqVO();
                pieceReq.setId(changeover.getId());
                pieceReq.setAdhesive2ReportId(report.getId());
                pieceReq.setPieceNo(report.getProductionBatchNo());
                // 与报工确认、库存处理共用事务；记片失败必须回滚本次报工。
                hcProductionInstructionService.recordChangeoverPiece(pieceReq);
            }
        }
        return report.getId();
    }

    HcProductionInstructionDO validateAdhesive2ConfirmChangeover(HcAdhesive2ReportDO report) {
        if (isAdhesive2PreProcessPressSlotNg(report)) {
            return null;
        }
        String segmentBatchNo = resolveAdhesive2MotherSegmentBatchNo(report);
        Map<String, Object> extra = parseRoughExtraMap(report.getExtraJson());
        Long submittedInstructionId = parseLong(toStringValue(extra.get("changeoverInstructionId")));
        if (hcPlanOrderOperationMapper.selectByIdForUpdate(report.getPlanOperationId()) == null) {
            throw invalidParamException("粘胶2报工关联的计划工序不存在");
        }
        HcProductionInstructionDO current = hcProductionInstructionMapper.selectLatestEffectiveChangeoverForUpdate(
                report.getPlanId(), report.getPlanOperationId(), segmentBatchNo);
        if (current == null) {
            if (submittedInstructionId != null) {
                throw invalidParamException("当前分段换型指令已变化，请刷新页面后重新报工");
            }
            return null;
        }
        if (current == null || Boolean.TRUE.equals(current.getDeleted())
                || "REVOKED".equalsIgnoreCase(current.getStatus())
                || !List.of("EXECUTING", "COMPLETED").contains(current.getExecuteStatus())
                || !Objects.equals(current.getPlanId(), report.getPlanId())
                || !Objects.equals(current.getPlanOperationId(), report.getPlanOperationId())
                || !StrUtil.equalsIgnoreCase(current.getSegmentBatchNo(), segmentBatchNo)) {
            throw invalidParamException("当前分段换型指令已变化，请刷新页面后重新报工");
        }
        if (submittedInstructionId != null && !Objects.equals(submittedInstructionId, current.getId())) {
            throw invalidParamException("报工关联的换型指令已变化，请刷新页面并重新核实当前型号及点检");
        }
        if (!StrUtil.equalsIgnoreCase(StrUtil.trim(report.getModelCode()), StrUtil.trim(current.getTargetModelCode()))
                || (StrUtil.isNotBlank(current.getTargetMaterialCode())
                    && !StrUtil.equalsIgnoreCase(StrUtil.trim(report.getMaterialCode()),
                            StrUtil.trim(current.getTargetMaterialCode())))) {
            throw invalidParamException("报工型号或料号与当前换型目标 " + current.getTargetModelCode()
                    + " / " + firstNotBlank(current.getTargetMaterialCode(), "-")
                    + " 不一致，请刷新页面并核实后重新报工");
        }
        validateAdhesive2ChangeoverInspection(current, segmentBatchNo);
        return current;
    }

    private void validateAdhesive2OneClickConfirmRuntime(HcPlanOrderDO planOrder,
                                                           HcPlanOrderOperationDO operation,
                                                           String motherSegmentBatchNo,
                                                           String expectedRuntimeModelCode,
                                                           String reportModelCode) {
        String normalizedMotherBatchNo = normalizePressSlotMiddleBatchNo(motherSegmentBatchNo);
        HcProductionInstructionDO openChangeover = hcProductionInstructionMapper.selectLatestOpenChangeover(
                planOrder.getId(), operation.getId(), normalizedMotherBatchNo);
        if (openChangeover != null) {
            if (!"EXECUTING".equalsIgnoreCase(openChangeover.getExecuteStatus())) {
                throw invalidParamException("当前分段存在待执行的换型指令 "
                        + firstNotBlank(openChangeover.getInstructionNo(), "-")
                        + "，请先执行换型后再一键扫码确认");
            }
        }
        HcProcessReportDO latestStartReport = getLatestStartReport(operation.getId(), SOURCE_MENU_CODE_ADHESIVE2);
        Adhesive2RuntimeProductContext runtimeProduct = resolveAdhesive2RuntimeProductContext(planOrder, operation,
                latestStartReport, normalizedMotherBatchNo, null, null);
        String runtimeModelCode = StrUtil.trim(runtimeProduct.productModel());
        String expectedModelCode = StrUtil.trim(expectedRuntimeModelCode);
        if (StrUtil.isBlank(expectedModelCode) || !StrUtil.equalsIgnoreCase(expectedModelCode, runtimeModelCode)) {
            throw invalidParamException("当前实际生产型号已变化为 " + firstNotBlank(runtimeModelCode, "-")
                    + "，请刷新页面后重新发起一键扫码确认");
        }
        String savedModelCode = StrUtil.trim(reportModelCode);
        if (StrUtil.isBlank(savedModelCode) || !StrUtil.equalsIgnoreCase(savedModelCode, runtimeModelCode)) {
            throw invalidParamException("待确认片的报工型号 " + firstNotBlank(savedModelCode, "-")
                    + " 与当前实际生产型号 " + firstNotBlank(runtimeModelCode, "-")
                    + " 不一致，不能一键确认，请逐片核实后处理");
        }
    }

    private void consumeAdhesive2SourceWipIfPresent(HcPlanOrderDO planOrder,
                                                    HcPlanOrderOperationDO operation,
                                                    HcAdhesive2ReportDO report,
                                                    LocalDateTime consumeTime,
                                                    String operatorName) {
        if (report == null || report.getId() == null || report.getSourcePressSlotReportId() == null) {
            return;
        }
        BigDecimal consumeQty = firstNonNullDecimal(report.getInputLength(), BigDecimal.ONE);
        HcPlanOrderInventoryLockDO sourceLock = report.getSourcePlanLockId() == null
                ? null
                : hcPlanOrderInventoryLockMapper.selectById(report.getSourcePlanLockId());
        if (!isActivePlanWipLock(sourceLock)) {
            sourceLock = resolveActiveSourceWipLock(report.getPlanOperationId(), SOURCE_TABLE_PRESS_SLOT_REPORT, report.getSourcePressSlotReportId());
        }
        if (sourceLock == null) {
            sourceLock = ensureSourceWipLockedForOperation(planOrder, operation,
                    SOURCE_TYPE_PRESS_SLOT, SOURCE_TABLE_PRESS_SLOT_REPORT, report.getSourcePressSlotReportId(),
                    consumeQty, operatorName, "粘胶2确认补锁压槽中间品");
        }
        HcInvStockDO consumedStock = consumeSourceWipLock(sourceLock, consumeQty,
                SOURCE_TYPE_ADHESIVE2, report.getId(), report.getProductionBatchNo(), consumeTime, operatorName,
                "粘胶2确认消耗压槽中间品；来源片号：" + firstNotBlank(report.getSourceProductionBatchNo(), report.getSourceBatchNo(), "-"));
        if (sourceLock == null || consumedStock == null) {
            return;
        }
        HcAdhesive2ReportDO consumeUpdate = new HcAdhesive2ReportDO();
        consumeUpdate.setId(report.getId());
        consumeUpdate.setSourceStockId(sourceLock.getStockId());
        consumeUpdate.setSourcePlanLockId(sourceLock.getId());
        consumeUpdate.setSourceStockBatchNo(firstNotBlank(sourceLock.getSourceBatchNo(), sourceLock.getBatchNo()));
        consumeUpdate.setSourceLockQty(consumeQty);
        consumeUpdate.setSourceConsumeQty(consumeQty);
        consumeUpdate.setSourceConsumeTxnNo(consumedStock.getLastTxnNo());
        consumeUpdate.setSourceConsumeTime(consumedStock.getLastTxnTime());
        hcAdhesive2ReportMapper.updateById(consumeUpdate);
        report.setSourceStockId(sourceLock.getStockId());
        report.setSourcePlanLockId(sourceLock.getId());
        report.setSourceStockBatchNo(consumeUpdate.getSourceStockBatchNo());
        report.setSourceLockQty(consumeQty);
        report.setSourceConsumeQty(consumeQty);
        report.setSourceConsumeTxnNo(consumedStock.getLastTxnNo());
        report.setSourceConsumeTime(consumedStock.getLastTxnTime());
    }

    private void postAdhesive2OutputWipIfNeeded(HcPlanOrderDO planOrder,
                                                HcPlanOrderOperationDO operation,
                                                HcAdhesive2ReportDO report,
                                                LocalDateTime postTime,
                                                String operatorName) {
        if (report == null || report.getId() == null || report.getOutputStockId() != null) {
            return;
        }
        BigDecimal outputQty = firstNonNullDecimal(report.getOutputLength(), BigDecimal.ONE);
        if (outputQty.compareTo(BigDecimal.ZERO) <= 0) {
            return;
        }
        if (isAdhesive2PreProcessPressSlotNg(report)) {
            HcPressSlotReportDO sourceReport = hcPressSlotReportMapper.selectById(report.getSourcePressSlotReportId());
            if (sourceReport == null || Boolean.TRUE.equals(sourceReport.getDeleted())) {
                throw invalidParamException("粘胶2报工缺少有效的来源压槽报工，不能按压槽归属登记不合格品");
            }
            hcNgInventoryService.registerPressSlotNgPieceAttributedByAdhesive2(sourceReport, report, planOrder, operation);
            HcAdhesive2ReportDO stockUpdate = new HcAdhesive2ReportDO();
            stockUpdate.setId(report.getId());
            stockUpdate.setOutputStockPostStatus("NG_STORED");
            stockUpdate.setOutputStockPostTime(postTime);
            stockUpdate.setOutputStockPostMessage("粘胶2发现加工前压槽自检异常，已自动入压槽库");
            hcAdhesive2ReportMapper.updateById(stockUpdate);
            report.setOutputStockPostStatus(stockUpdate.getOutputStockPostStatus());
            report.setOutputStockPostTime(postTime);
            report.setOutputStockPostMessage(stockUpdate.getOutputStockPostMessage());
            return;
        }
        HcInvStockDO stock = hcInvStockService.postProcessOutputWip(HcWipOutputPostReq.builder()
                .plan(planOrder)
                .operation(operation)
                .sourceType(SOURCE_TYPE_ADHESIVE2)
                .sourceTable(SOURCE_TABLE_ADHESIVE2_REPORT)
                .sourceId(report.getId())
                .sourceReportId(report.getId())
                .batchNo(report.getProductionBatchNo())
                .parentBatchNo(firstNotBlank(report.getParentProductionBatchNo(), report.getSourceBatchNo()))
                .outputQty(outputQty)
                .uom("pcs")
                .modelNo(firstNotBlank(report.getModelCode(), planOrder.getModelCode(), planOrder.getModelName()))
                .businessRemark("粘胶2扫码确认产出入中间边库；来源计划：" + firstNotBlank(planOrder.getPlanNo(), "-")
                        + "；来源批号：" + firstNotBlank(report.getSourceProductionBatchNo(), report.getSourceBatchNo(), "-"))
                .txnRemark("粘胶2扫码确认自动入中间边库")
                .postTime(postTime)
                .operatorId(SecurityFrameworkUtils.getLoginUserId())
                .operatorName(firstNotBlank(operatorName, SecurityFrameworkUtils.getLoginUserNickname(), "系统"))
                .build());
        HcAdhesive2ReportDO stockUpdate = new HcAdhesive2ReportDO();
        stockUpdate.setId(report.getId());
        stockUpdate.setOutputStockId(stock.getId());
        stockUpdate.setOutputStockPostStatus(STOCK_POST_STATUS_POSTED);
        stockUpdate.setOutputStockPostTime(stock.getLastTxnTime());
        stockUpdate.setOutputStockPostMessage("粘胶2扫码确认自动入中间边库");
        hcAdhesive2ReportMapper.updateById(stockUpdate);
        report.setOutputStockId(stock.getId());
        report.setOutputStockPostStatus(STOCK_POST_STATUS_POSTED);
        report.setOutputStockPostTime(stock.getLastTxnTime());
        report.setOutputStockPostMessage(stockUpdate.getOutputStockPostMessage());
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void markAdhesive2ReportPrinted(HcAdhesiveReportPrintReqVO reqVO) {
        HcAdhesive2ReportDO report = hcAdhesive2ReportMapper.selectById(reqVO.getId());
        if (report == null || Boolean.TRUE.equals(report.getDeleted())) {
            throw invalidParamException("粘胶2报工记录不存在");
        }
        if (!hasAdhesive2TailSelection(report)) {
            throw invalidParamException("请先选择实际尺寸和片号尾号后再打印流转单");
        }
        LocalDateTime printTime = reqVO.getPrintTime() == null ? LocalDateTime.now() : reqVO.getPrintTime();
        Map<String, Object> extra = new LinkedHashMap<>(parseRoughExtraMap(report.getExtraJson()));
        extra.put("printStatus", firstNotBlank(reqVO.getPrintStatus(), "已打印"));
        extra.put("printTime", printTime.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));
        extra.put("printCount", reqVO.getPrintCount() == null ? 1 : Math.max(reqVO.getPrintCount(), 1));
        HcAdhesive2ReportDO updateReport = new HcAdhesive2ReportDO();
        updateReport.setId(report.getId());
        updateReport.setExtraJson(JsonUtils.toJsonString(extra));
        hcAdhesive2ReportMapper.updateById(updateReport);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long submitAdhesive2Report(HcAdhesiveReportSubmitReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, reqVO.getPlanOperationId());
        if (OP_STATUS_FINISHED.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前粘胶2工序已完工，不能继续报工");
        }
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            throw invalidParamException("当前粘胶2工序未开工，不能过站提交");
        }
        List<HcAdhesive2ReportDO> reports = hcAdhesive2ReportMapper.selectListByPlanOperationId(operation.getId());
        if (reports.isEmpty()) {
            throw invalidParamException("请先至少保存一条粘胶2报工记录");
        }
        boolean hasUnconfirmed = reports.stream()
                .anyMatch(report -> !"CONFIRMED".equalsIgnoreCase(report.getReportStatus())
                        && !"SUBMITTED".equalsIgnoreCase(report.getReportStatus()));
        if (hasUnconfirmed) {
            throw invalidParamException("存在未扫码确认的粘胶2报工记录，不能工单完工");
        }
        boolean hasUncompletedSegment = reports.stream()
                .anyMatch(report -> !"SUBMITTED".equalsIgnoreCase(report.getReportStatus()));
        if (hasUncompletedSegment) {
            throw invalidParamException("存在尚未点击本段完工的粘胶2分段，不能工单完工");
        }
        LocalDate reportDate = reqVO.getReportDate();
        LocalDateTime startTime = null;
        LocalDateTime endTime = normalizeReportDateTime(reqVO.getEndTime(), reportDate == null ? LocalDate.now() : reportDate);
        BigDecimal totalInputQty = BigDecimal.ZERO;
        BigDecimal totalLossQty = BigDecimal.ZERO;
        BigDecimal totalOutputQty = BigDecimal.ZERO;
        HcAdhesive2ReportDO latestReport = reports.get(0);
        for (HcAdhesive2ReportDO report : reports) {
            if (reportDate == null && report.getReportDate() != null) {
                reportDate = report.getReportDate();
            }
            if (report.getStartTime() != null && (startTime == null || report.getStartTime().isBefore(startTime))) {
                startTime = report.getStartTime();
            }
            if (report.getEndTime() != null && (endTime == null || report.getEndTime().isAfter(endTime))) {
                endTime = report.getEndTime();
            }
            totalInputQty = totalInputQty.add(zeroIfNull(report.getInputLength()));
            totalLossQty = totalLossQty.add(zeroIfNull(report.getLossLength()));
            totalOutputQty = totalOutputQty.add(zeroIfNull(report.getOutputLength()));
        }
        LocalDateTime now = LocalDateTime.now();
        if (reportDate == null) {
            reportDate = LocalDate.now();
        }
        if (startTime == null) {
            startTime = now;
        }
        if (endTime == null) {
            endTime = now;
        }
        LocalDateTime recorderTime = normalizeReportDateTime(reqVO.getRecorderTime(), reportDate);
        LocalDateTime confirmerTime = normalizeReportDateTime(reqVO.getConfirmerTime(), reportDate);
        if (recorderTime == null) {
            recorderTime = latestReport.getRecorderTime() == null ? now : latestReport.getRecorderTime();
        }
        if (confirmerTime == null) {
            confirmerTime = now;
        }
        String recorderName = firstNotBlank(reqVO.getRecorderName(), latestReport.getRecorderName(),
                SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        String confirmerName = firstNotBlank(reqVO.getConfirmerName(), SecurityFrameworkUtils.getLoginUserNickname(), recorderName, "系统");
        String finishRemark = "粘胶2报工：" + reports.size() + "片；加工" + formatDecimal(totalInputQty)
                + "片，合格" + formatDecimal(totalOutputQty) + "片，异常/损耗" + formatDecimal(totalLossQty) + "片"
                + (StrUtil.isBlank(reqVO.getRemark()) ? "" : "；备注：" + reqVO.getRemark());

        HcProcessReportDO reportDO = HcProcessReportDO.builder()
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .operationStatus(operation.getOperationStatus())
                .operationSeq(operation.getOpSeq())
                .operationCode(operation.getOpCode())
                .operationName(operation.getOpName())
                .workCenterId(operation.getWorkCenterId())
                .workCenterCode(operation.getWorkCenterCode())
                .workCenterName(operation.getWorkCenterName())
                .equipmentId(operation.getEquipmentId())
                .equipmentCode(operation.getEquipmentCode())
                .equipmentName(operation.getEquipmentName())
                .materialId(planOrder.getMaterialId())
                .materialCode(firstNotBlank(latestReport.getMaterialCode(), planOrder.getMaterialCode()))
                .materialName(firstNotBlank(latestReport.getMaterialName(), planOrder.getMaterialName()))
                .motherMaterialId(planOrder.getMotherMaterialId())
                .motherMaterialCode(firstNotBlank(operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode()))
                .motherMaterialName(firstNotBlank(operation.getMotherMaterialName(), planOrder.getMotherMaterialName()))
                .motherModelId(planOrder.getMotherModelId())
                .motherModelCode(firstNotBlank(operation.getMotherModelCode(), planOrder.getMotherModelCode()))
                .motherModelName(firstNotBlank(operation.getMotherModelName(), planOrder.getMotherModelName()))
                .batchNo(firstNotBlank(latestReport.getProductionBatchNo(), operation.getBatchNo(), planOrder.getBatchNo()))
                .productionBatchNo(firstNotBlank(latestReport.getProductionBatchNo(), operation.getProductionBatchNo(), planOrder.getProductionBatchNo()))
                .parentProductionBatchNo(firstNotBlank(latestReport.getParentProductionBatchNo(), operation.getParentProductionBatchNo(), planOrder.getParentProductionBatchNo()))
                .parentBatchNo(firstNotBlank(latestReport.getParentProductionBatchNo(), latestReport.getSourceProductionBatchNo(), operation.getParentBatchNo(), planOrder.getBatchNo()))
                .sampleCode(operation.getSampleCode())
                .reportDate(reportDate)
                .startTime(startTime)
                .endTime(endTime)
                .goodQty(totalOutputQty)
                .scrapQty(totalLossQty)
                .recorderName(recorderName)
                .recorderTime(recorderTime)
                .confirmerName(confirmerName)
                .confirmerTime(confirmerTime)
                .reportUom(firstNotBlank(operation.getUom(), operation.getUnitCode(), operation.getUnitName(), planOrder.getTargetUom(), "片"))
                .reportMinutes(calculateMinutes(startTime, endTime))
                .reportType("END")
                .sourceMenuCode(SOURCE_MENU_CODE_ADHESIVE2)
                .extraJson(JsonUtils.toJsonString(Map.of("reportCount", reports.size(), "inputQty", totalInputQty,
                        "outputQty", totalOutputQty, "lossQty", totalLossQty)))
                .remark(reqVO.getRemark())
                .build();
        hcProcessReportMapper.insert(reportDO);

        for (HcAdhesive2ReportDO report : reports) {
            HcAdhesive2ReportDO updateReport = new HcAdhesive2ReportDO();
            updateReport.setId(report.getId());
            updateReport.setReportStatus("SUBMITTED");
            updateReport.setConfirmerName(confirmerName);
            updateReport.setConfirmerTime(confirmerTime);
            hcAdhesive2ReportMapper.updateById(updateReport);
        }
        BigDecimal totalGoodQty = hcProcessReportMapper.selectTotalGoodQtyBySource(operation.getId(), SOURCE_MENU_CODE_ADHESIVE2);
        HcPlanOrderOperationDO updateOperation = new HcPlanOrderOperationDO();
        updateOperation.setId(operation.getId());
        updateOperation.setDispatchQty(totalGoodQty);
        updateOperation.setOperationStatus(OP_STATUS_FINISHED);
        updateOperation.setFinishTime(endTime);
        updateOperation.setFinishRemark(finishRemark);
        updateOperation.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateOperation.setStatusOperatorName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "system"));
        updateOperation.setStatusOperateTime(LocalDateTime.now());
        hcPlanOrderOperationMapper.updateById(updateOperation);
        // 与粘胶1一致：同机可挂接多个生产中计划，工单完工不清空设备实时展示绑定。
        return reportDO.getId();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long completeAdhesive2Segment(HcAdhesiveSegmentCompleteReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        if (!PLAN_STATUS_RELEASED.equals(planOrder.getPlanStatus())) {
            throw invalidParamException("只有已下达的生产计划允许标记本段完成");
        }
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, reqVO.getPlanOperationId());

        String segmentBatchNo = normalizePressSlotMiddleBatchNo(reqVO.getSourceProductionBatchNo());
        if (StrUtil.isBlank(segmentBatchNo)) {
            throw invalidParamException("请选择当前分段批次后再执行本段完成");
        }
        List<HcAdhesive2ReportDO> segmentReports = filterAdhesive2ReportsByMotherBatchNo(
                hcAdhesive2ReportMapper.selectListByPlanOperationId(operation.getId()), segmentBatchNo);
        if (segmentReports.isEmpty()) {
            throw invalidParamException("当前分段批次暂无粘胶2报工记录，不能标记完成");
        }
        boolean hasUnconfirmed = segmentReports.stream()
                .anyMatch(report -> {
                    String status = StrUtil.blankToDefault(report.getReportStatus(), "DRAFT");
                    return !"CONFIRMED".equalsIgnoreCase(status) && !"SUBMITTED".equalsIgnoreCase(status);
                });
        if (hasUnconfirmed) {
            throw invalidParamException("当前分段批次存在未扫码确认的粘胶2报工记录，不能本段完成");
        }
        boolean allSubmitted = segmentReports.stream()
                .allMatch(report -> "SUBMITTED".equalsIgnoreCase(StrUtil.blankToDefault(report.getReportStatus(), "")));
        if (allSubmitted) {
            throw invalidParamException("当前分段批次已完成");
        }

        LocalDate reportDate = reqVO.getReportDate() == null ? LocalDate.now() : reqVO.getReportDate();
        LocalDateTime confirmerTime = normalizeReportDateTime(reqVO.getConfirmerTime(), reportDate);
        if (confirmerTime == null) {
            confirmerTime = LocalDateTime.now();
        }
        String confirmerName = firstNotBlank(reqVO.getConfirmerName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        for (HcAdhesive2ReportDO report : segmentReports) {
            HcAdhesive2ReportDO updateReport = new HcAdhesive2ReportDO();
            updateReport.setId(report.getId());
            updateReport.setReportStatus("SUBMITTED");
            updateReport.setConfirmerName(confirmerName);
            updateReport.setConfirmerTime(confirmerTime);
            hcAdhesive2ReportMapper.updateById(updateReport);
        }
        HcAdhesive2ReportDO firstReport = segmentReports.get(0);
        HcProcessReportDO segmentCompleteReport = buildBatchSegmentCompleteReport(
                planOrder, operation, segmentBatchNo, reportDate, confirmerTime, confirmerName,
                firstNotBlank(firstReport.getMaterialCode(), planOrder.getMaterialCode()),
                firstNotBlank(firstReport.getMaterialName(), planOrder.getMaterialName()),
                segmentReports.stream().map(HcAdhesive2ReportDO::getOutputLength)
                        .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add),
                segmentReports.stream().map(HcAdhesive2ReportDO::getLossLength)
                        .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add),
                segmentReports.size(), SOURCE_MENU_CODE_ADHESIVE2_SEGMENT_COMPLETE, "粘胶2本段完工");
        hcProcessReportMapper.insert(segmentCompleteReport);
        return segmentCompleteReport.getId();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcAdhesive2IntermediateRespVO getAdhesive2Intermediate(Long planId, Long planOperationId, LocalDateTime recordDate,
                                                                  Long recordId, String batchNo) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, planOperationId);
        LocalDateTime effectiveDateTime = recordDate == null ? LocalDateTime.now() : recordDate;
        LocalDate effectiveDate = effectiveDateTime.toLocalDate();
        String normalizedBatchNo = normalizePressSlotMiddleBatchNo(batchNo);
        HcAdhesive2IntermediateRecordDO record = selectAdhesive2IntermediateRecord(operation.getId(), effectiveDate, recordId, batchNo);
        List<HcAdhesive2ReportDO> operationReports = getAdhesive2OperationReports(operation.getId());
        String effectiveBatchNo = firstNotBlank(record == null ? null : normalizePressSlotMiddleBatchNo(record.getBatchNo()),
                normalizedBatchNo, resolveAdhesive2IntermediateBatchNo(operationReports, operation, planOrder));
        List<HcAdhesive2ReportDO> scopedReports = filterAdhesive2ReportsByMotherBatchNo(operationReports, effectiveBatchNo);
        PressSlotIntermediateCounter counter = calculateAdhesive2IntermediateCounter(scopedReports);
        if (record == null) {
            HcAdhesive2IntermediateRespVO resp = new HcAdhesive2IntermediateRespVO();
            resp.setPlanId(planOrder.getId());
            resp.setPlanNo(planOrder.getPlanNo());
            resp.setPlanOperationId(operation.getId());
            resp.setRecordDate(effectiveDateTime);
            resp.setModelCode(firstNotBlank(planOrder.getModelCode(), planOrder.getModelName()));
            resp.setMaterialCode(planOrder.getMaterialCode());
            resp.setBatchNo(effectiveBatchNo);
            resp.setInputQty(counter.inputQty());
            resp.setOutputQty(counter.outputQty());
            resp.setRecorderName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), ""));
            resp.setRecordStatus("DRAFT");
            applyAdhesive2IntermediateStationFormMeta(resp, resp.getModelCode());
            resp.setDetails(buildAdhesive2IntermediateDetailsFromMiddleReports(scopedReports));
            return resp;
        }
        HcAdhesive2IntermediateRespVO resp = buildAdhesive2IntermediateResp(record);
        resp.setInputQty(counter.inputQty());
        resp.setOutputQty(counter.outputQty());
        if (StrUtil.isBlank(resp.getBatchNo())) {
            resp.setBatchNo(effectiveBatchNo);
        }
        List<HcPressSlotIntermediateDetailRespVO> details = hcAdhesive2IntermediateDetailMapper
                .selectListByRecordId(record.getId())
                .stream()
                .map(this::buildAdhesive2IntermediateDetailResp)
                .toList();
        List<HcPressSlotIntermediateDetailRespVO> markedDetails = buildAdhesive2IntermediateDetailsFromMiddleReports(scopedReports);
        resp.setDetails(details.isEmpty()
                ? markedDetails
                : mergeAdhesive2IntermediateDetails(details, markedDetails));
        return resp;
    }

    @Override
    public HcAdhesive2IntermediateRespVO getAdhesive2IntermediateById(Long recordId) {
        HcAdhesive2IntermediateRecordDO record = validateAdhesive2IntermediateRecord(recordId);
        HcAdhesive2IntermediateRespVO resp = buildAdhesive2IntermediateResp(record);
        List<HcAdhesive2ReportDO> operationReports = getAdhesive2OperationReports(record.getPlanOperationId());
        List<HcAdhesive2ReportDO> scopedReports = filterAdhesive2ReportsByMotherBatchNo(operationReports, record.getBatchNo());
        PressSlotIntermediateCounter counter = calculateAdhesive2IntermediateCounter(scopedReports);
        resp.setInputQty(counter.inputQty());
        resp.setOutputQty(counter.outputQty());
        List<HcPressSlotIntermediateDetailRespVO> details = hcAdhesive2IntermediateDetailMapper
                .selectListByRecordId(record.getId())
                .stream()
                .map(this::buildAdhesive2IntermediateDetailResp)
                .toList();
        List<HcPressSlotIntermediateDetailRespVO> markedDetails = buildAdhesive2IntermediateDetailsFromMiddleReports(scopedReports);
        resp.setDetails(details.isEmpty()
                ? markedDetails
                : mergeAdhesive2IntermediateDetails(details, markedDetails));
        return resp;
    }

    @Override
    public PageResult<HcStationRecordRespVO> getAdhesive2IntermediateRecordPage(HcStationRecordPageReqVO reqVO) {
        HcStationRecordPageReqVO effectiveReqVO = reqVO == null ? new HcStationRecordPageReqVO() : reqVO;
        if (!matchesAdhesive2IntermediateStaticFilters(effectiveReqVO)) {
            return new PageResult<>(Collections.emptyList(), 0L);
        }
        HcStationRecordPageReqVO queryReqVO = isAdhesive2IntermediateStaticKeyword(effectiveReqVO.getKeyword())
                ? copyAdhesive2IntermediatePageReqWithoutKeyword(effectiveReqVO) : effectiveReqVO;
        PageResult<HcAdhesive2IntermediateRecordDO> page = hcAdhesive2IntermediateRecordMapper.selectPage(queryReqVO);
        List<HcStationRecordRespVO> records = page.getList().stream()
                .map(this::toAdhesive2IntermediateRecordListResp)
                .filter(record -> matchesAdhesive2IntermediateEquipmentFilters(record, effectiveReqVO))
                .toList();
        long total = hasAdhesive2IntermediateEquipmentFilter(effectiveReqVO) ? records.size() : page.getTotal();
        return new PageResult<>(records, total);
    }

    private HcAdhesive2IntermediateRecordDO validateAdhesive2IntermediateRecord(Long recordId) {
        HcAdhesive2IntermediateRecordDO record = recordId == null ? null : hcAdhesive2IntermediateRecordMapper.selectById(recordId);
        if (record == null || Boolean.TRUE.equals(record.getDeleted())) {
            throw invalidParamException("粘胶2中间品记录不存在");
        }
        return record;
    }

    private boolean matchesAdhesive2IntermediateStaticFilters(HcStationRecordPageReqVO reqVO) {
        if (reqVO == null) {
            return true;
        }
        String formCode = StrUtil.trimToEmpty(reqVO.getFormCode());
        if (StrUtil.isNotBlank(formCode) && !isAdhesive2IntermediateFormCode(formCode)) {
            return false;
        }
        String formName = StrUtil.trimToEmpty(reqVO.getFormName());
        if (StrUtil.isNotBlank(formName) && !isAdhesive2IntermediateFormName(formName)) {
            return false;
        }
        String operationName = StrUtil.trimToEmpty(reqVO.getOperationName());
        if (StrUtil.isNotBlank(operationName) && !containsIgnoreCase("粘胶2", operationName)) {
            return false;
        }
        String recordScope = StrUtil.trimToEmpty(reqVO.getRecordScope());
        if (StrUtil.isNotBlank(recordScope) && !"BUSINESS_RECORD".equalsIgnoreCase(recordScope)) {
            return false;
        }
        return reqVO.getConfirmTimeStart() == null
                && reqVO.getConfirmTimeEnd() == null;
    }

    private boolean isAdhesive2IntermediateFormCode(String formCode) {
        String normalized = StrUtil.trimToEmpty(formCode).toUpperCase();
        return ADHESIVE2_INTERMEDIATE_FORM_CODE.equalsIgnoreCase(normalized)
                || (normalized.contains("ADHESIVE2") && normalized.contains("INTERMEDIATE"));
    }

    private boolean isAdhesive2IntermediateFormName(String formName) {
        String text = StrUtil.trimToEmpty(formName);
        return containsIgnoreCase(ADHESIVE2_INTERMEDIATE_FORM_NAME, text)
                || containsIgnoreCase(text, ADHESIVE2_INTERMEDIATE_FORM_NAME)
                || (containsIgnoreCase(text, "粘胶2") && containsIgnoreCase(text, "中间品"));
    }

    private boolean hasAdhesive2IntermediateEquipmentFilter(HcStationRecordPageReqVO reqVO) {
        return reqVO != null && (StrUtil.isNotBlank(reqVO.getEquipmentCode())
                || StrUtil.isNotBlank(reqVO.getEquipmentName()));
    }

    private boolean matchesAdhesive2IntermediateEquipmentFilters(HcStationRecordRespVO record,
                                                                HcStationRecordPageReqVO reqVO) {
        if (record == null || reqVO == null) {
            return true;
        }
        String equipmentCode = StrUtil.trimToEmpty(reqVO.getEquipmentCode());
        if (StrUtil.isNotBlank(equipmentCode) && !containsIgnoreCase(record.getEquipmentCode(), equipmentCode)) {
            return false;
        }
        String equipmentName = StrUtil.trimToEmpty(reqVO.getEquipmentName());
        return StrUtil.isBlank(equipmentName)
                || containsIgnoreCase(record.getEquipmentName(), equipmentName)
                || containsIgnoreCase(record.getEquipmentCode(), equipmentName);
    }

    private boolean isAdhesive2IntermediateStaticKeyword(String keyword) {
        String text = StrUtil.trimToEmpty(keyword);
        return StrUtil.isNotBlank(text)
                && (isAdhesive2IntermediateFormName(text)
                || containsIgnoreCase("粘胶2", text)
                || containsIgnoreCase("业务记录 BUSINESS_RECORD", text));
    }

    private HcStationRecordPageReqVO copyAdhesive2IntermediatePageReqWithoutKeyword(HcStationRecordPageReqVO source) {
        HcStationRecordPageReqVO target = new HcStationRecordPageReqVO();
        target.setPageNo(source.getPageNo());
        target.setPageSize(source.getPageSize());
        target.setPlanNo(source.getPlanNo());
        target.setOperationName(source.getOperationName());
        target.setFormName(source.getFormName());
        target.setFormCode(source.getFormCode());
        target.setExcludeFormCode(source.getExcludeFormCode());
        target.setFormCodePrefix(source.getFormCodePrefix());
        target.setEquipmentCode(source.getEquipmentCode());
        target.setEquipmentName(source.getEquipmentName());
        target.setRecordScope(source.getRecordScope());
        target.setCreateTimeStart(source.getCreateTimeStart());
        target.setCreateTimeEnd(source.getCreateTimeEnd());
        target.setCreateUserName(source.getCreateUserName());
        target.setConfirmUserName(source.getConfirmUserName());
        target.setConfirmTimeStart(source.getConfirmTimeStart());
        target.setConfirmTimeEnd(source.getConfirmTimeEnd());
        return target;
    }

    private HcAdhesive2IntermediateRecordDO selectAdhesive2IntermediateRecord(Long planOperationId, LocalDate recordDate,
                                                                              Long recordId, String batchNo) {
        HcAdhesive2IntermediateRecordDO record = null;
        if (recordId != null) {
            record = hcAdhesive2IntermediateRecordMapper.selectById(recordId);
            if (record != null && (Boolean.TRUE.equals(record.getDeleted())
                    || !Objects.equals(record.getPlanOperationId(), planOperationId))) {
                record = null;
            }
        }
        String normalizedBatchNo = normalizePressSlotMiddleBatchNo(batchNo);
        if (record != null && StrUtil.isNotBlank(normalizedBatchNo)
                && !StrUtil.equalsIgnoreCase(normalizePressSlotMiddleBatchNo(record.getBatchNo()), normalizedBatchNo)) {
            record = null;
        }
        if (record == null && StrUtil.isNotBlank(normalizedBatchNo)) {
            record = hcAdhesive2IntermediateRecordMapper.selectByPlanOperationIdAndBatchNo(planOperationId, normalizedBatchNo);
        }
        if (record != null) {
            return record;
        }
        return StrUtil.isBlank(normalizedBatchNo)
                ? hcAdhesive2IntermediateRecordMapper.selectByPlanOperationIdAndDate(planOperationId, recordDate)
                : null;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long saveAdhesive2Intermediate(HcAdhesive2IntermediateSaveReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, reqVO.getPlanOperationId());
        LocalDateTime effectiveDateTime = reqVO.getRecordDate() == null ? LocalDateTime.now() : reqVO.getRecordDate();
        LocalDate effectiveDate = effectiveDateTime.toLocalDate();
        List<HcAdhesive2ReportDO> operationReports = getAdhesive2OperationReports(operation.getId());
        String effectiveBatchNo = firstNotBlank(normalizePressSlotMiddleBatchNo(reqVO.getBatchNo()),
                resolveAdhesive2IntermediateBatchNo(operationReports, operation, planOrder));
        List<HcAdhesive2ReportDO> scopedReports = filterAdhesive2ReportsByMotherBatchNo(operationReports, effectiveBatchNo);
        PressSlotIntermediateCounter counter = calculateAdhesive2IntermediateCounter(scopedReports);
        HcAdhesive2IntermediateRecordDO record = reqVO.getId() == null ? null : hcAdhesive2IntermediateRecordMapper.selectById(reqVO.getId());
        if (record != null && (Boolean.TRUE.equals(record.getDeleted())
                || !Objects.equals(record.getPlanOperationId(), operation.getId()))) {
            record = null;
        }
        if (record != null && StrUtil.isNotBlank(effectiveBatchNo)
                && !StrUtil.equalsIgnoreCase(normalizePressSlotMiddleBatchNo(record.getBatchNo()), effectiveBatchNo)) {
            throw invalidParamException("当前粘胶2中间品记录批号与页面批号不一致，请关闭后重新打开");
        }
        if (record == null && StrUtil.isNotBlank(effectiveBatchNo)) {
            record = hcAdhesive2IntermediateRecordMapper.selectByPlanOperationIdAndBatchNo(operation.getId(), effectiveBatchNo);
        }
        if (record == null && StrUtil.isBlank(effectiveBatchNo)) {
            record = hcAdhesive2IntermediateRecordMapper.selectByPlanOperationIdAndDate(operation.getId(), effectiveDate);
        }
        if (record != null && "CONFIRMED".equalsIgnoreCase(StrUtil.blankToDefault(record.getRecordStatus(), ""))) {
            throw invalidParamException("粘胶2中间品记录已确认，不能修改");
        }
        reqVO.setBatchNo(effectiveBatchNo);
        if (record == null || Boolean.TRUE.equals(record.getDeleted())) {
            record = HcAdhesive2IntermediateRecordDO.builder()
                    .tenantId(planOrder.getTenantId())
                    .planId(planOrder.getId())
                    .planNo(planOrder.getPlanNo())
                    .planOperationId(operation.getId())
                    .recordDate(effectiveDateTime)
                    .recordStatus("DRAFT")
                    .build();
            fillAdhesive2IntermediateRecord(record, reqVO, planOrder, operation, scopedReports, counter);
            hcAdhesive2IntermediateRecordMapper.insert(record);
        } else {
            fillAdhesive2IntermediateRecord(record, reqVO, planOrder, operation, scopedReports, counter);
            hcAdhesive2IntermediateRecordMapper.updateById(record);
            hcAdhesive2IntermediateDetailMapper.deleteByRecordId(record.getId());
        }
        List<HcPressSlotIntermediateDetailReqVO> details = reqVO.getDetails() == null
                ? Collections.emptyList() : reqVO.getDetails();
        if (details.isEmpty()) {
            details = buildDefaultAdhesive2IntermediateDetails().stream()
                    .map(this::buildPressSlotIntermediateDetailReq)
                    .toList();
        }
        List<HcAdhesive2IntermediateDetailDO> detailList = new ArrayList<>();
        int index = 0;
        for (HcPressSlotIntermediateDetailReqVO item : details) {
            index++;
            detailList.add(HcAdhesive2IntermediateDetailDO.builder()
                    .tenantId(planOrder.getTenantId())
                    .intermediateRecordId(record.getId())
                    .planId(planOrder.getId())
                    .planNo(planOrder.getPlanNo())
                    .planOperationId(operation.getId())
                    .adhesive2ReportId(item.getPressSlotReportId())
                    .sourcePressSlotReportId(item.getSourceSlittingSliceId())
                    .samplePosition(item.getSamplePosition())
                    .samplePositionName(item.getSamplePositionName())
                    .sliceBatchNo(item.getSliceBatchNo())
                    .widthMm(item.getWidthMm())
                    .thickness1(item.getThickness1())
                    .thickness2(item.getThickness2())
                    .thickness3(item.getThickness3())
                    .thickness4(item.getThickness4())
                    .thickness5(item.getThickness5())
                    .thickness6(item.getThickness6())
                    .thickness7(item.getThickness7())
                    .thickness8(item.getThickness8())
                    .thickness9(item.getThickness9())
                    .thickness10(item.getThickness10())
                    .remark(item.getRemark())
                    .sortNo(item.getSortNo() == null ? index : item.getSortNo())
                    .build());
        }
        hcAdhesive2IntermediateDetailMapper.insertBatch(detailList);
        Map<String, Object> importAttachment = reqVO.getImportAttachment() == null
                ? Collections.emptyMap() : new LinkedHashMap<>(reqVO.getImportAttachment());
        syncAdhesive2IntermediateProcessFormRecord(record, detailList, importAttachment);
        return record.getId();
    }

    @Override
    public List<HcAdhesive2IntermediateRespVO> getAdhesive2IntermediateList(Long planOperationId, String batchNo) {
        if (planOperationId == null) {
            return Collections.emptyList();
        }
        return getAdhesive2IntermediateRecords(planOperationId, null, batchNo).stream()
                .map(this::buildAdhesive2IntermediateResp)
                .toList();
    }

    @Override
    public List<HcPressSlotMiddleLedgerRespVO> getAdhesive2MiddleLedgerList(Long planOperationId) {
        if (planOperationId == null) {
            return Collections.emptyList();
        }
        return hcAdhesive2ReportMapper.selectListByPlanOperationId(planOperationId)
                .stream()
                .filter(report -> isPressSlotMiddleLedgerType(resolveAdhesive2ReportType(report)))
                .map(this::buildAdhesive2MiddleLedgerResp)
                .toList();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void setAdhesive2ReportMiddleType(Long reportId, String reportType) {
        String normalizedReportType = StrUtil.trimToEmpty(reportType).toUpperCase();
        if (!isPressSlotMiddleLedgerType(normalizedReportType)) {
            throw invalidParamException("中间品段位只能设置为前段、中段或后段");
        }
        HcAdhesive2ReportDO targetReport = hcAdhesive2ReportMapper.selectById(reportId);
        if (targetReport == null || Boolean.TRUE.equals(targetReport.getDeleted())) {
            throw invalidParamException("粘胶2报工记录不存在");
        }
        String targetStatus = StrUtil.blankToDefault(targetReport.getReportStatus(), "");
        if (!"CONFIRMED".equalsIgnoreCase(targetStatus) && !"SUBMITTED".equalsIgnoreCase(targetStatus)) {
            throw invalidParamException("只有已扫码确认的粘胶2报工记录才能设置中间品段位");
        }
        String targetMotherBatchNo = resolveAdhesive2MotherSegmentBatchNo(targetReport);
        if (StrUtil.isBlank(targetMotherBatchNo)) {
            throw invalidParamException("当前粘胶2报工记录缺少母批次，不能设置中间品段位");
        }
        List<HcAdhesive2ReportDO> sameOperationReports = hcAdhesive2ReportMapper.selectListByPlanOperationId(targetReport.getPlanOperationId());
        for (HcAdhesive2ReportDO report : sameOperationReports) {
            if (Objects.equals(report.getId(), targetReport.getId())) {
                continue;
            }
            if (!StrUtil.equalsIgnoreCase(resolveAdhesive2MotherSegmentBatchNo(report), targetMotherBatchNo)) {
                continue;
            }
            if (!StrUtil.equalsIgnoreCase(resolveAdhesive2ReportType(report), normalizedReportType)) {
                continue;
            }
            HcAdhesive2ReportDO resetReport = new HcAdhesive2ReportDO();
            resetReport.setId(report.getId());
            resetReport.setExtraJson(buildAdhesive2MiddleLedgerExtra(report.getExtraJson(), "PRODUCT"));
            hcAdhesive2ReportMapper.updateById(resetReport);
        }
        HcAdhesive2ReportDO updateReport = new HcAdhesive2ReportDO();
        updateReport.setId(targetReport.getId());
        updateReport.setExtraJson(buildAdhesive2MiddleLedgerExtra(targetReport.getExtraJson(), normalizedReportType));
        hcAdhesive2ReportMapper.updateById(updateReport);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public HcAdhesiveReportRespVO correctAdhesive2ReportAbnormalCategory(HcAdhesive2AbnormalCategoryCorrectReqVO reqVO) {
        String category = StrUtil.trimToEmpty(reqVO.getCategory());
        String reason = StrUtil.trimToEmpty(reqVO.getReason());
        if (!ADHESIVE2_VISUAL_CATEGORY_NAMES.contains(category)) {
            throw invalidParamException("异常类别只能选择黑点、蓝点、黄点、红点、针孔、条纹、褶皱、波浪纹或其他");
        }
        if (StrUtil.isBlank(reason)) {
            throw invalidParamException("修正原因不能为空");
        }
        HcAdhesive2ReportDO report = hcAdhesive2ReportMapper.selectById(reqVO.getId());
        if (report == null || Boolean.TRUE.equals(report.getDeleted())) {
            throw invalidParamException("粘胶2报工记录不存在");
        }
        if (!isAdhesive2UsageScope(report.getOperationCode(), report.getOperationName())) {
            throw invalidParamException("当前报工记录不是粘胶2报工，不能修正异常类别");
        }
        if (!isNgResultValue(report.getSelfCheck())
                && StrUtil.isBlank(report.getDefectCode())
                && resolveAdhesive2ActiveVisualCategories(report.getExtraJson()).isEmpty()) {
            throw invalidParamException("当前粘胶2报工记录没有外观异常类别，不能修正");
        }

        Map<String, Object> extra = new LinkedHashMap<>(parseRoughExtraMap(report.getExtraJson()));
        List<String> beforeCategories = new ArrayList<>(resolveAdhesive2ActiveVisualCategories(extra));
        String currentDefectCode = StrUtil.trimToEmpty(report.getDefectCode());
        if (ADHESIVE2_VISUAL_CATEGORY_NAMES.contains(currentDefectCode) && !beforeCategories.contains(currentDefectCode)) {
            beforeCategories.add(currentDefectCode);
        }
        List<Map<String, Object>> correctedVisualItems = buildAdhesive2CorrectedVisualItems(extra, category);
        String correctedAt = LocalDateTime.now().format(DATETIME_FORMATTER);
        Long correctedById = SecurityFrameworkUtils.getLoginUserId();
        String correctedByName = firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统");

        Map<String, Object> correction = new LinkedHashMap<>();
        correction.put("beforeCategories", beforeCategories);
        correction.put("afterCategory", category);
        correction.put("reason", reason);
        correction.put("correctedAt", correctedAt);
        correction.put("correctedById", correctedById);
        correction.put("correctedByName", correctedByName);

        List<Object> history = new ArrayList<>();
        Object rawHistory = extra.get("abnormalCategoryCorrectionHistory");
        if (rawHistory instanceof List<?> rawList) {
            history.addAll(rawList);
        } else if (rawHistory != null) {
            history.add(rawHistory);
        }
        history.add(correction);

        extra.put("visualItems", correctedVisualItems);
        extra.put("visualInspectionResult", "NG");
        extra.put("selfCheck", "NG");
        extra.put("defectCode", category);
        extra.put("abnormalCategoryCorrected", true);
        extra.put("correctedVisualCategory", category);
        extra.put("abnormalCategoryCorrectionReason", reason);
        extra.put("abnormalCategoryCorrectionTime", correctedAt);
        extra.put("abnormalCategoryCorrectionUserId", correctedById);
        extra.put("abnormalCategoryCorrectionUserName", correctedByName);
        extra.put("abnormalCategoryCorrectionHistory", history);

        HcAdhesive2ReportDO updateReport = new HcAdhesive2ReportDO();
        updateReport.setId(report.getId());
        updateReport.setSelfCheck("NG");
        updateReport.setDefectCode(category);
        updateReport.setQualityLockReason(correctAdhesive2QualityLockReason(report.getQualityLockReason(), beforeCategories, category));
        updateReport.setExtraJson(JsonUtils.toJsonString(extra));
        hcAdhesive2ReportMapper.updateById(updateReport);

        report.setSelfCheck(updateReport.getSelfCheck());
        report.setDefectCode(updateReport.getDefectCode());
        report.setQualityLockReason(updateReport.getQualityLockReason());
        report.setExtraJson(updateReport.getExtraJson());
        return buildAdhesive2ReportResp(report);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Integer importAdhesive2MiddleLedger(Long planId, Long planOperationId, MultipartFile file,
                                               String importAttachmentJson, Long recordId, String batchNo,
                                               LocalDateTime recordDate) throws Exception {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(planId);
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, planOperationId);
        Map<String, Object> importAttachment = parseImportAttachmentJson(importAttachmentJson);
        List<HcPressSlotIntermediateDetailReqVO> details = new ArrayList<>();
        DataFormatter formatter = new DataFormatter();
        LocalDateTime effectiveDate = recordDate;
        String productModel = null;
        String productBatchNo = normalizePressSlotMiddleBatchNo(batchNo);
        String glueBoardWidthMm = null;
        String glueBoardModel = null;
        String glueBoardAdhesionGf = null;
        try (InputStream inputStream = file.getInputStream(); Workbook workbook = WorkbookFactory.create(inputStream)) {
            Sheet sheet = workbook.getSheetAt(0);
            if (effectiveDate == null) {
                LocalDateTime importedDateTime = parseIntermediateRecordDateTime(sheet, formatter);
                effectiveDate = importedDateTime == null ? LocalDateTime.now() : importedDateTime;
            }
            productModel = firstNotBlank(
                    readAdhesive2IntermediateHeaderValue(sheet, "型号", formatter),
                    readAdhesive2IntermediateHeaderValue(sheet, "产品型号", formatter));
            productBatchNo = firstNotBlank(productBatchNo,
                    normalizePressSlotMiddleBatchNo(readAdhesive2IntermediateHeaderValue(sheet, "批号", formatter)),
                    normalizePressSlotMiddleBatchNo(readAdhesive2IntermediateHeaderValue(sheet, "产品批号", formatter)));
            glueBoardWidthMm = firstNotBlank(
                    readAdhesive2IntermediateHeaderValue(sheet, "宽幅/MM", formatter),
                    readAdhesive2IntermediateHeaderValue(sheet, "宽幅", formatter));
            glueBoardModel = readAdhesive2IntermediateHeaderValue(sheet, "胶板型号", formatter);
            glueBoardAdhesionGf = readAdhesive2IntermediateHeaderValue(sheet, "使用面粘性", formatter);
            int headerRowIndex = findAdhesive2IntermediateHeaderRow(sheet, formatter);
            if (headerRowIndex < 0) {
                throw invalidParamException("导入模板未找到片号表头");
            }
            int detailIndex = 0;
            for (int i = headerRowIndex + 1; i <= sheet.getLastRowNum(); i++) {
                Row row = sheet.getRow(i);
                if (row == null) {
                    continue;
                }
                String firstCell = readCellString(row, 0, formatter);
                if (isAdhesive2IntermediateStopRow(firstCell)) {
                    break;
                }
                String sliceNo = stripAdhesive2IntermediateSliceNo(firstCell);
                List<BigDecimal> thicknessValues = new ArrayList<>();
                for (int col = 1; col <= 10; col++) {
                    thicknessValues.add(parseDecimalFromText(readCellString(row, col, formatter)));
                }
                String remark = firstNotBlank(readCellString(row, 11, formatter),
                        readCellString(row, 12, formatter), readCellString(row, 13, formatter));
                if (StrUtil.isBlank(sliceNo) && thicknessValues.stream().allMatch(Objects::isNull) && StrUtil.isBlank(remark)) {
                    continue;
                }
                String samplePosition = resolveAdhesive2IntermediatePosition(firstCell, detailIndex);
                HcPressSlotIntermediateDetailReqVO detail = new HcPressSlotIntermediateDetailReqVO();
                detail.setSamplePosition(samplePosition);
                detail.setSamplePositionName(getPressSlotIntermediatePositionName(samplePosition));
                detail.setSliceBatchNo(sliceNo);
                setAdhesive2IntermediateThickness(detail, thicknessValues);
                detail.setRemark(remark);
                detail.setSortNo(++detailIndex);
                details.add(detail);
            }
        }
        HcAdhesive2IntermediateSaveReqVO saveReq = new HcAdhesive2IntermediateSaveReqVO();
        saveReq.setId(recordId);
        saveReq.setPlanId(planOrder.getId());
        saveReq.setPlanNo(planOrder.getPlanNo());
        saveReq.setPlanOperationId(operation.getId());
        saveReq.setRecordDate(effectiveDate == null ? LocalDateTime.now() : effectiveDate);
        saveReq.setModelCode(firstNotBlank(productModel, planOrder.getModelCode(), planOrder.getModelName()));
        saveReq.setMaterialCode(planOrder.getMaterialCode());
        saveReq.setBatchNo(firstNotBlank(productBatchNo, resolveAdhesive2IntermediateBatchNo(
                getAdhesive2OperationReports(operation.getId()), operation, planOrder)));
        saveReq.setGlueBoardWidthMm(glueBoardWidthMm);
        saveReq.setGlueBoardModel(glueBoardModel);
        saveReq.setGlueBoardAdhesionGf(glueBoardAdhesionGf);
        saveReq.setRecorderName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), ""));
        saveReq.setRecordStatus("RECORDED");
        saveReq.setImportAttachment(importAttachment);
        saveReq.setDetails(details);
        saveAdhesive2Intermediate(saveReq);
        return details.size();
    }

    @Override
    public void exportAdhesive2MiddleLedger(Long planOperationId, Long recordId, String batchNo,
                                            HttpServletResponse response) throws Exception {
        List<HcAdhesive2IntermediateRecordDO> records = getAdhesive2IntermediateRecords(planOperationId, recordId, batchNo);
        String fileName = URLEncoder.encode("CMP粘胶2中间品记录表.xlsx", StandardCharsets.UTF_8).replaceAll("\\+", "%20");
        response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
        response.setHeader("Content-Disposition", "attachment; filename*=UTF-8''" + fileName);
        try (Workbook workbook = new XSSFWorkbook()) {
            Sheet sheet = workbook.createSheet("粘胶2中间品记录表");
            writeAdhesive2IntermediateRecordSheet(sheet, records);
            workbook.write(response.getOutputStream());
        }
    }

    private List<HcAdhesive2IntermediateRecordDO> getAdhesive2IntermediateRecords(Long planOperationId,
                                                                                  Long recordId,
                                                                                  String batchNo) {
        if (planOperationId == null) {
            return Collections.emptyList();
        }
        HcAdhesive2IntermediateRecordDO selected = null;
        if (recordId != null) {
            selected = hcAdhesive2IntermediateRecordMapper.selectById(recordId);
            if (selected != null && (Boolean.TRUE.equals(selected.getDeleted())
                    || !Objects.equals(selected.getPlanOperationId(), planOperationId))) {
                selected = null;
            }
        }
        String normalizedBatchNo = normalizePressSlotMiddleBatchNo(batchNo);
        if (selected != null && StrUtil.isNotBlank(normalizedBatchNo)
                && !StrUtil.equalsIgnoreCase(normalizePressSlotMiddleBatchNo(selected.getBatchNo()), normalizedBatchNo)) {
            selected = null;
        }
        if (selected == null && StrUtil.isNotBlank(normalizedBatchNo)) {
            return hcAdhesive2IntermediateRecordMapper.selectListByPlanOperationIdAndBatchNo(planOperationId, normalizedBatchNo);
        }
        if (selected != null) {
            return List.of(selected);
        }
        return hcAdhesive2IntermediateRecordMapper.selectListByPlanOperationId(planOperationId);
    }

    @Override
    public List<HcPressSlotProcessParamRespVO> getAdhesive2ProcessParamList(Long planOperationId,
                                                                            LocalDate reportDate,
                                                                            String productionBatchNo,
                                                                            String motherBatchNo,
                                                                            String formType) {
        if (planOperationId == null) {
            return Collections.emptyList();
        }
        String normalizedMotherBatchNo = normalizePressSlotMiddleBatchNo(motherBatchNo);
        String effectiveFormType = normalizeAdhesive2ProcessRecordFormType(formType);
        List<HcProcessFormRecordDO> records = hcProcessFormRecordMapper.selectList(new LambdaQueryWrapperX<HcProcessFormRecordDO>()
                .eq(HcProcessFormRecordDO::getProcessCode, PROCESS_CODE_ADHESIVE2)
                .eq(HcProcessFormRecordDO::getFormType, effectiveFormType)
                .eq(HcProcessFormRecordDO::getPlanOperationId, planOperationId)
                .eqIfPresent(HcProcessFormRecordDO::getRecordDate, reportDate)
                .eqIfPresent(HcProcessFormRecordDO::getBatchNo, normalizedMotherBatchNo)
                .orderByDesc(HcProcessFormRecordDO::getRecordDate)
                .orderByDesc(HcProcessFormRecordDO::getId));
        String keyword = StrUtil.trim(productionBatchNo);
        return records.stream()
                .map(this::buildPressSlotProcessParamResp)
                .filter(resp -> StrUtil.isBlank(keyword)
                        || containsIgnoreCase(resp.getProductionBatchNo(), keyword)
                        || containsIgnoreCase(resp.getFirstInspectionSliceNo(), keyword)
                        || resp.getItems().stream().anyMatch(item -> containsIgnoreCase(item.getProductionBatchNo(), keyword)))
                .toList();
    }

