    private String resolveFormulaProductModelCode(HcPlanOrderDO planOrder, HcPlanOrderOperationDO operation) {
        String modelCode = firstNotBlank(
                operation != null ? operation.getMotherModelCode() : null,
                planOrder != null ? planOrder.getMotherModelCode() : null,
                planOrder != null ? planOrder.getModelCode() : null);
        return StrUtil.trimToEmpty(modelCode).toUpperCase();
    }

    private boolean matchFormulaStationFormModelPrefix(HcStationFormDO form, String modelCode) {
        if (form == null || StrUtil.isBlank(modelCode)) {
            return true;
        }
        String category = resolveFormulaStationFormCategory(form);
        if (!"production-check".equals(category)) {
            return true;
        }
        String formModelPrefix = resolveFormulaStationFormModelPrefix(form);
        if (StrUtil.isNotBlank(formModelPrefix)) {
            return modelCode.startsWith(formModelPrefix);
        }
        String legacyModelPrefix = modelCode.length() <= 4 ? modelCode : modelCode.substring(0, 4);
        String formCode = StrUtil.trimToEmpty(form.getFormCode()).toUpperCase();
        if (formCode.contains(legacyModelPrefix)) {
            return true;
        }
        String formName = StrUtil.trimToEmpty(form.getFormName()).toUpperCase();
        return formName.contains(legacyModelPrefix);
    }

    private String resolveFormulaPassWorkDisplayName(HcStationFormDO form) {
        if ("production-check".equals(resolveFormulaStationFormCategory(form))) {
            return "配料生产点检表";
        }
        return form == null ? "" : form.getFormName();
    }

    private Map<String, Object> readFormulaPassWorkImportAttachment(String headerDataJson) {
        Object raw = parseStationRecordHeaderDataMap(headerDataJson).get(FORMULA_PASS_WORK_IMPORT_ATTACHMENT_KEY);
        if (raw instanceof Map<?, ?> map && !map.isEmpty()) {
            Map<String, Object> attachment = new LinkedHashMap<>();
            map.forEach((key, value) -> {
                if (key != null) {
                    attachment.put(String.valueOf(key), value);
                }
            });
            return attachment;
        }
        return null;
    }

    private String writeFormulaPassWorkImportAttachment(String headerDataJson, Map<String, Object> importAttachment) {
        Map<String, Object> headerData = parseStationRecordHeaderDataMap(headerDataJson);
        headerData.put(FORMULA_PASS_WORK_IMPORT_ATTACHMENT_KEY, new LinkedHashMap<>(importAttachment));
        return JsonUtils.toJsonString(headerData);
    }

    private Map<String, Object> parseStationRecordHeaderDataMap(String headerDataJson) {
        if (StrUtil.isBlank(headerDataJson)) {
            return new LinkedHashMap<>();
        }
        Map<String, Object> parsed = JsonUtils.parseObjectQuietly(headerDataJson, new TypeReference<Map<String, Object>>() {});
        return parsed == null ? new LinkedHashMap<>() : new LinkedHashMap<>(parsed);
    }

    private String resolveFormulaStationFormModelPrefix(HcStationFormDO form) {
        if (form == null) {
            return "";
        }
        if (StrUtil.isNotBlank(form.getSchemaJson())) {
            JsonNode schema = JsonUtils.parseTree(form.getSchemaJson());
            if (schema != null) {
                String schemaModelPrefix = normalizeFormulaModelPrefix(readJsonText(schema, "modelPrefix"));
                if (StrUtil.isNotBlank(schemaModelPrefix)) {
                    return schemaModelPrefix;
                }
                String schemaModelCodePrefix = normalizeFormulaModelPrefix(readJsonText(schema, "modelCode"));
                if (StrUtil.isNotBlank(schemaModelCodePrefix)) {
                    return schemaModelCodePrefix;
                }
            }
        }
        return firstNotBlank(
                extractFormulaModelPrefix(form.getFormCode()),
                extractFormulaModelPrefix(form.getFormName()),
                "");
    }

    private String extractFormulaModelPrefix(String text) {
        String normalized = StrUtil.trimToEmpty(text).toUpperCase();
        Matcher matcher = MODEL_CODE_PATTERN.matcher(normalized);
        return matcher.find() ? normalizeFormulaModelPrefix(matcher.group()) : "";
    }

    private String normalizeFormulaModelPrefix(String modelCode) {
        String normalized = StrUtil.trimToEmpty(modelCode).toUpperCase();
        if (StrUtil.isBlank(normalized) || "COMMON".equals(normalized)) {
            return "";
        }
        return normalized;
    }

    private String resolveFormulaStationFormCategory(HcStationFormDO form) {
        String schemaCategory = null;
        if (form != null && StrUtil.isNotBlank(form.getSchemaJson())) {
            JsonNode schema = JsonUtils.parseTree(form.getSchemaJson());
            schemaCategory = schema == null ? null : readJsonText(schema, "formulaCategory");
        }
        if (StrUtil.equalsAny(schemaCategory, "prepare", "production-check")) {
            return schemaCategory;
        }
        String formCode = StrUtil.trimToEmpty(form != null ? form.getFormCode() : "").toUpperCase();
        String formName = StrUtil.trimToEmpty(form != null ? form.getFormName() : "");
        if (formCode.startsWith("FORMULA_PROCESS_CHECK") || formName.contains("配料生产点检表")) {
            return "production-check";
        }
        if (formCode.startsWith("FORMULA_STARTUP_CHECK") || formCode.startsWith("FORMULA_CLEANING_CHECK")
                || formName.contains("开机点检") || formName.contains("清洁保养") || formName.contains("清洁点检")) {
            return "prepare";
        }
        return "";
    }

