    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long submitFormulaReport(HcFormulaReportSaveReqVO reqVO) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectByIdForUpdate(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectByIdForUpdate(reqVO.getPlanOperationId());
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        if (!PLAN_STATUS_RELEASED.equals(planOrder.getPlanStatus())) {
            throw invalidParamException("只有已下达的生产计划允许报工");
        }
        if (operation == null || !Objects.equals(operation.getPlanId(), planOrder.getId())) {
            throw invalidParamException("计划工序不存在");
        }
        if (!"配料".equals(operation.getOpName())) {
            throw invalidParamException("当前仅允许通过配料报工菜单提交配料工序");
        }
        if (!OP_STATUS_RUNNING.equals(operation.getOperationStatus())) {
            if (OP_STATUS_FINISHED.equals(operation.getOperationStatus())) {
                throw invalidParamException("当前工序已完工，不能继续报工");
            }
            throw invalidParamException("当前工序状态不允许报工");
        }
        hcFormulaStationRuntimeService.assertFinished(planOrder, operation, resolveFormulaProductModelCode(planOrder, operation));
        if (StrUtil.isBlank(reqVO.getFilterBatchNo())) {
            throw invalidParamException("滤网批号不能为空");
        }
        if (reqVO.getInputWeight() == null || reqVO.getInputWeight().compareTo(BigDecimal.ZERO) <= 0) {
            throw invalidParamException("投料重量必须大于0");
        }
        if (StrUtil.isBlank(reqVO.getBatchingTankNo())) {
            throw invalidParamException("配料罐罐号不能为空");
        }
        if (StrUtil.isBlank(reqVO.getDefoamingTankNo())) {
            throw invalidParamException("脱泡罐罐号不能为空");
        }
        log.info(
                "[MES报工时间提交-接收][配料] planNo={} planId={} planOperationId={} "
                        + "requestFields=reportDate,startTime,endTime values reportDate={} startTime={} endTime={} sourceMenuCode={}",
                planOrder.getPlanNo(), planOrder.getId(), operation.getId(),
                reqVO.getReportDate(), reqVO.getStartTime(), reqVO.getEndTime(), SOURCE_MENU_CODE_FORMULA);
        if (reqVO.getFeedQty() != null && reqVO.getFeedQty().compareTo(BigDecimal.ZERO) < 0) {
            throw invalidParamException("配料重量不能为负数");
        }
        if (reqVO.getStirStartTime() != null
                && reqVO.getStirEndTime() != null
                && reqVO.getStirEndTime().isBefore(reqVO.getStirStartTime())) {
            throw invalidParamException("搅拌结束时间不能早于开始时间");
        }
        BigDecimal requestScrapQty = reqVO.getScrapQty() == null ? BigDecimal.ZERO : reqVO.getScrapQty();
        if (requestScrapQty.compareTo(BigDecimal.ZERO) > 0
                && (reqVO.getDefects() == null || reqVO.getDefects().isEmpty())
                && StrUtil.isBlank(reqVO.getScrapReason())) {
            throw invalidParamException("存在不良数量时，必须提供不良原因");
        }

        BigDecimal reportGoodQty = reqVO.getFeedQty() != null ? reqVO.getFeedQty() : reqVO.getGoodQty();
        if (reportGoodQty == null) {
            reportGoodQty = BigDecimal.ZERO;
        }
        BigDecimal reportScrapQty = BigDecimal.ZERO;

        LocalDate reportDate = reqVO.getReportDate() == null ? LocalDate.now() : reqVO.getReportDate();
        boolean placeholderStartTime = isPlaceholderDateTime(reqVO.getStartTime())
                || isDateOnlyRuntimeDateTime(reqVO.getStartTime(), reportDate);
        boolean placeholderEndTime = isPlaceholderDateTime(reqVO.getEndTime())
                || isDateOnlyRuntimeDateTime(reqVO.getEndTime(), reportDate);
        boolean placeholderRecorderTime = isPlaceholderDateTime(reqVO.getRecorderTime())
                || isDateOnlyRuntimeDateTime(reqVO.getRecorderTime(), reportDate);
        LocalDateTime normalizedStartTime = normalizeReportDateTime(reqVO.getStartTime(), reportDate);
        LocalDateTime normalizedEndTime = normalizeReportDateTime(reqVO.getEndTime(), reportDate);
        LocalDateTime normalizedStirStartTime = normalizeReportDateTime(reqVO.getStirStartTime(), reportDate);
        LocalDateTime normalizedStirEndTime = normalizeReportDateTime(reqVO.getStirEndTime(), reportDate);
        LocalDateTime normalizedRecorderTime = normalizeReportDateTime(reqVO.getRecorderTime(), reportDate);
        LocalDateTime now = LocalDateTime.now();
        HcProcessReportDO latestStartReport = getLatestStartReport(reqVO.getPlanOperationId(), SOURCE_MENU_CODE_FORMULA);
        if ((normalizedStartTime == null || placeholderStartTime)
                && latestStartReport != null
                && latestStartReport.getStartTime() != null) {
            normalizedStartTime = latestStartReport.getStartTime();
        }
        if (normalizedStartTime == null) {
            normalizedStartTime = now;
        }
        if (normalizedRecorderTime == null || placeholderRecorderTime) {
            normalizedRecorderTime = now;
        }
        if (normalizedEndTime == null || placeholderEndTime) {
            normalizedEndTime = now;
        }
        LocalDateTime effectiveEndTime = normalizedEndTime;
        syncLatestStartReportTime(latestStartReport, reportDate, normalizedStartTime);
        String effectiveProductionBatchNo = firstNotBlank(
                latestStartReport == null ? null : latestStartReport.getProductionBatchNo(),
                latestStartReport == null ? null : latestStartReport.getBatchNo(),
                operation.getProductionBatchNo(),
                planOrder.getProductionBatchNo(),
                reqVO.getBatchNo(),
                operation.getBatchNo(),
                planOrder.getBatchNo());
        String effectiveParentProductionBatchNo = firstNotBlank(
                latestStartReport == null ? null : latestStartReport.getParentProductionBatchNo(),
                operation.getParentProductionBatchNo(),
                planOrder.getParentProductionBatchNo());
        Long effectiveBatchRuleId = firstNotNull(
                latestStartReport == null ? null : latestStartReport.getProductionBatchRuleId(),
                operation.getProductionBatchRuleId(),
                planOrder.getProductionBatchRuleId());
        String effectiveBatchRuleCode = firstNotBlank(
                latestStartReport == null ? null : latestStartReport.getProductionBatchRuleCode(),
                operation.getProductionBatchRuleCode(),
                planOrder.getProductionBatchRuleCode());
        String effectiveBatchContextJson = firstNotBlank(
                latestStartReport == null ? null : latestStartReport.getProductionBatchContextJson(),
                operation.getProductionBatchContextJson(),
                planOrder.getProductionBatchContextJson());
        HcProcessReportDO reportDO = HcProcessReportDO.builder()
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .operationStatus(operation.getOperationStatus())
                .operationSeq(operation.getOpSeq())
                .operationCode(operation.getOpCode())
                .operationName(operation.getOpName())
                .workCenterId(operation.getWorkCenterId())
                .workCenterCode(operation.getWorkCenterCode())
                .workCenterName(operation.getWorkCenterName())
                .equipmentId(operation.getEquipmentId())
                .equipmentCode(operation.getEquipmentCode())
                .equipmentName(operation.getEquipmentName())
                .materialId(planOrder.getMaterialId())
                .materialCode(planOrder.getMaterialCode())
                .materialName(planOrder.getMaterialName())
                .motherMaterialId(planOrder.getMotherMaterialId())
                .motherMaterialCode(firstNotBlank(operation.getMotherMaterialCode(), planOrder.getMotherMaterialCode()))
                .motherMaterialName(firstNotBlank(operation.getMotherMaterialName(), planOrder.getMotherMaterialName()))
                .motherModelId(planOrder.getMotherModelId())
                .motherModelCode(firstNotBlank(operation.getMotherModelCode(), planOrder.getMotherModelCode()))
                .motherModelName(firstNotBlank(operation.getMotherModelName(), planOrder.getMotherModelName()))
                .batchingNo(reqVO.getBatchingNo())
                .feedBatchNo(reqVO.getFeedBatchNo())
                .recipeId(reqVO.getRecipeId())
                .recipeCode(firstNotBlank(reqVO.getRecipeCode(), planOrder.getRecipeCode()))
                .recipeName(firstNotBlank(reqVO.getRecipeName(), planOrder.getRecipeName()))
                .batchNo(effectiveProductionBatchNo)
                .productionBatchNo(effectiveProductionBatchNo)
                .parentProductionBatchNo(effectiveParentProductionBatchNo)
                .productionBatchRuleId(effectiveBatchRuleId)
                .productionBatchRuleCode(effectiveBatchRuleCode)
                .productionBatchContextJson(effectiveBatchContextJson)
                .parentBatchNo(firstNotBlank(effectiveParentProductionBatchNo,
                        operation.getParentBatchNo(), planOrder.getBatchNo()))
                .sampleCode(operation.getSampleCode())
                .reportDate(reportDate)
                .startTime(normalizedStartTime)
                .endTime(effectiveEndTime)
                .goodQty(reportGoodQty)
                .scrapQty(reportScrapQty)
                .feedQty(reqVO.getFeedQty())
                .stirStartTime(normalizedStirStartTime)
                .stirEndTime(normalizedStirEndTime)
                .recorderName(reqVO.getRecorderName())
                .recorderTime(normalizedRecorderTime)
                .mixerEquipmentId(reqVO.getMixerEquipmentId())
                .mixerEquipmentCode(reqVO.getMixerEquipmentCode())
                .mixerEquipmentName(reqVO.getMixerEquipmentName())
                .foamingEquipmentId(reqVO.getFoamingEquipmentId())
                .foamingEquipmentCode(reqVO.getFoamingEquipmentCode())
                .foamingEquipmentName(reqVO.getFoamingEquipmentName())
                .viscosity(reqVO.getViscosity())
                .slurryTemperature(reqVO.getSlurryTemperature())
                .filterBatchNo(StrUtil.trim(reqVO.getFilterBatchNo()))
                .inputWeight(reqVO.getInputWeight())
                .batchingTankNo(StrUtil.trim(reqVO.getBatchingTankNo()))
                .defoamingTankNo(StrUtil.trim(reqVO.getDefoamingTankNo()))
                .reportUom(firstNotBlank(operation.getUom(), operation.getUnitCode(), operation.getUnitName(), planOrder.getTargetUom()))
                .reportMinutes(calculateMinutes(normalizedStartTime, effectiveEndTime))
                .laborHours(reqVO.getLaborHours())
                .reportType(StrUtil.blankToDefault(reqVO.getReportType(), "END"))
                .sourceMenuCode(SOURCE_MENU_CODE_FORMULA)
                .remark(reqVO.getRemark())
                .build();
        hcProcessReportMapper.insert(reportDO);
        HcProcessReportDO persistedReport = hcProcessReportMapper.selectById(reportDO.getId());
        verifyOperationReportTimePersisted("配料", reportDO.getId(), reportDate,
                normalizedStartTime, effectiveEndTime, persistedReport);
        log.info(
                "[MES报工时间提交-落库][配料] planNo={} planOperationId={} operationReportId={} "
                        + "saveTable=mes_sfc_operation_report saveFields=report_date,start_time,end_time "
                        + "values reportDate={} startTime={} endTime={} reportType={} sourceMenuCode={}",
                planOrder.getPlanNo(), operation.getId(), reportDO.getId(),
                persistedReport == null ? null : persistedReport.getReportDate(),
                persistedReport == null ? null : persistedReport.getStartTime(),
                persistedReport == null ? null : persistedReport.getEndTime(),
                persistedReport == null ? null : persistedReport.getReportType(), SOURCE_MENU_CODE_FORMULA);

        List<HcProcessReportDefectDO> defectList = buildDefectList(
                reqVO, reportDO.getId(), planOrder.getTenantId(), planOrder.getId(), operation.getId());
        if (!defectList.isEmpty()) {
            hcProcessReportDefectMapper.insertBatch(defectList);
        }

        BigDecimal totalGoodQty = hcProcessReportMapper.selectFormulaTotalGoodQty(operation.getId());
        HcPlanOrderOperationDO updateObj = new HcPlanOrderOperationDO();
        updateObj.setId(operation.getId());
        updateObj.setDispatchQty(totalGoodQty == null ? BigDecimal.ZERO : totalGoodQty);
        updateObj.setOperationStatus(OP_STATUS_FINISHED);
        updateObj.setFinishTime(effectiveEndTime);
        updateObj.setFinishRemark(firstNotBlank(reqVO.getRemark(), "配料过站报工完成"));
        updateObj.setStatusOperatorId(SecurityFrameworkUtils.getLoginUserId());
        updateObj.setStatusOperatorName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "system"));
        updateObj.setStatusOperateTime(LocalDateTime.now());
        hcPlanOrderOperationMapper.updateById(updateObj);
        log.info(
                "[MES报工时间提交-联动][配料] planNo={} planOperationId={} "
                        + "saveTable=mes_pp_plan_operation saveField=finish_time value={}",
                planOrder.getPlanNo(), operation.getId(), effectiveEndTime);
        String operatorName = firstNotBlank(reqVO.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        LocalDateTime recordTime = normalizedRecorderTime != null ? normalizedRecorderTime : now;
        hcEquipmentService.releaseEquipment(reqVO.getMixerEquipmentId(), effectiveEndTime, operatorName, recordTime);
        if (!Objects.equals(reqVO.getFoamingEquipmentId(), reqVO.getMixerEquipmentId())) {
            hcEquipmentService.releaseEquipment(reqVO.getFoamingEquipmentId(), effectiveEndTime, operatorName, recordTime);
        }
        return reportDO.getId();
    }

    private List<HcProcessReportDefectDO> buildDefectList(HcFormulaReportSaveReqVO reqVO, Long reportId,
                                                          Long tenantId, Long planId, Long planOperationId) {
        List<HcFormulaReportDefectReqVO> reqDefects = reqVO.getDefects();
        BigDecimal requestScrapQty = reqVO.getScrapQty() == null ? BigDecimal.ZERO : reqVO.getScrapQty();
        if ((reqDefects == null || reqDefects.isEmpty()) && requestScrapQty.compareTo(BigDecimal.ZERO) > 0) {
            reqDefects = new ArrayList<>();
            HcFormulaReportDefectReqVO defectReqVO = new HcFormulaReportDefectReqVO();
            defectReqVO.setDefectCode(reqVO.getScrapReason());
            defectReqVO.setDefectQty(requestScrapQty);
            defectReqVO.setRemark(reqVO.getRemark());
            reqDefects.add(defectReqVO);
        }
        if (reqDefects == null || reqDefects.isEmpty()) {
            return List.of();
        }
        return reqDefects.stream()
                .filter(item -> item.getDefectQty() != null && item.getDefectQty().compareTo(BigDecimal.ZERO) > 0)
                .map(item -> HcProcessReportDefectDO.builder()
                        .tenantId(tenantId)
                        .reportId(reportId)
                        .planId(planId)
                        .planOperationId(planOperationId)
                        .defectCode(item.getDefectCode())
                        .defectName(resolveDefectName(item))
                        .defectQty(item.getDefectQty())
                        .remark(item.getRemark())
                        .build())
                .toList();
    }

    private String resolveDefectName(HcFormulaReportDefectReqVO item) {
        if (StrUtil.isNotBlank(item.getDefectName())) {
            return item.getDefectName();
        }
        return DEFECT_NAME_MAP.getOrDefault(item.getDefectCode(), "其他异常");
    }

    private Integer calculateMinutes(LocalDateTime startTime, LocalDateTime endTime) {
        if (startTime == null || endTime == null || endTime.isBefore(startTime)) {
            return null;
        }
        return Math.toIntExact(Duration.between(startTime, endTime).toMinutes());
    }

    LocalDateTime resolveWetCompletionTime(LocalDateTime startTime,
                                           LocalDateTime endTime,
                                           LocalDateTime recorderTime) {
        if (endTime == null) {
            throw invalidParamException("湿法完工时间不能为空");
        }
        if (recorderTime == null) {
            throw invalidParamException("最终报工记录时间不能为空");
        }
        if (startTime != null && endTime.isBefore(startTime)) {
            throw invalidParamException("湿法完工时间不能早于开工时间");
        }
        if (endTime.isAfter(recorderTime)) {
            throw invalidParamException("湿法完工时间不能晚于最终报工记录时间");
        }
        return endTime;
    }

    private boolean isPlaceholderDateTime(LocalDateTime value) {
        return value != null && (value.getYear() == 1970 || value.getYear() == 1900);
    }

    private boolean isDateOnlyRuntimeDateTime(LocalDateTime value, LocalDate reportDate) {
        if (value == null || !LocalTime.MIDNIGHT.equals(value.toLocalTime())) {
            return false;
        }
        return reportDate == null || reportDate.equals(value.toLocalDate());
    }

    private LocalDate parseReportDateText(String text) {
        if (StrUtil.isBlank(text)) {
            return null;
        }
        try {
            return LocalDate.parse(StrUtil.trim(text));
        } catch (RuntimeException ex) {
            throw invalidParamException("报工日期格式不正确，请使用 yyyy-MM-dd");
        }
    }

    private LocalDateTime normalizeReportDateTime(String text, LocalDate reportDate) {
        if (StrUtil.isBlank(text)) {
            return null;
        }
        String value = StrUtil.trim(text);
        try {
            if (value.matches("^\\d{2}:\\d{2}(:\\d{2})?$")) {
                if (reportDate == null) {
                    return null;
                }
                LocalTime time = LocalTime.parse(value.length() == 5 ? value + ":00" : value);
                return normalizeReportDateTime(LocalDateTime.of(reportDate, time), reportDate);
            }
            String normalized = value.replace('T', ' ');
            if (normalized.matches("^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}$")) {
                normalized = normalized + ":00";
            }
            return normalizeReportDateTime(LocalDateTime.parse(normalized, DATETIME_FORMATTER), reportDate);
        } catch (RuntimeException ex) {
            try {
                return normalizeReportDateTime(LocalDateTime.parse(value), reportDate);
            } catch (RuntimeException ignored) {
                throw invalidParamException("报工时间格式不正确，请使用 yyyy-MM-dd HH:mm:ss");
            }
        }
    }

    private LocalDateTime normalizeReportDateTime(LocalDateTime value, LocalDate reportDate) {
        if (value == null) {
            return null;
        }
        if (isPlaceholderDateTime(value)) {
            return null;
        }
        return value;
    }

    private HcProcessReportDO getLatestStartReport(Long planOperationId, String sourceMenuCode) {
        return hcProcessReportMapper.selectOne(new LambdaQueryWrapper<HcProcessReportDO>()
                .eq(HcProcessReportDO::getDeleted, false)
                .eq(HcProcessReportDO::getPlanOperationId, planOperationId)
                .eq(HcProcessReportDO::getSourceMenuCode, sourceMenuCode)
                .eq(HcProcessReportDO::getReportType, REPORT_TYPE_START)
                .orderByDesc(HcProcessReportDO::getId)
                .last("LIMIT 1"));
    }

    private void syncLatestStartReportTime(HcProcessReportDO latestStartReport,
                                           LocalDate reportDate,
                                           LocalDateTime startTime) {
        if (latestStartReport == null || startTime == null) {
            return;
        }
        if (Objects.equals(latestStartReport.getReportDate(), reportDate)
                && Objects.equals(latestStartReport.getStartTime(), startTime)) {
            return;
        }
        HcProcessReportDO updateObj = new HcProcessReportDO();
        updateObj.setId(latestStartReport.getId());
        updateObj.setReportDate(reportDate);
        updateObj.setStartTime(startTime);
        int affectedRows = hcProcessReportMapper.updateById(updateObj);
        HcProcessReportDO persistedStartReport = hcProcessReportMapper.selectById(latestStartReport.getId());
        log.info(
                "[MES报工时间提交-同步开工记录] planNo={} planOperationId={} operationReportId={} affectedRows={} "
                        + "saveTable=mes_sfc_operation_report saveFields=report_date,start_time "
                        + "values reportDate={} startTime={} reportType=START sourceMenuCode={}",
                latestStartReport.getPlanNo(), latestStartReport.getPlanOperationId(), latestStartReport.getId(), affectedRows,
                persistedStartReport == null ? null : persistedStartReport.getReportDate(),
                persistedStartReport == null ? null : persistedStartReport.getStartTime(),
                latestStartReport.getSourceMenuCode());
    }

    private void syncWetPoreSelfCheckStartTime(Long planOperationId, LocalDateTime startTime) {
        if (planOperationId == null || startTime == null) {
            return;
        }
        HcStationRecordDO stationRecord = hcStationRecordMapper.selectOneByPlanOperationAndFormCode(
                planOperationId, WET_PORE_SELF_CHECK_FORM_CODE);
        if (stationRecord == null || StrUtil.isBlank(stationRecord.getHeaderDataJson())) {
            return;
        }
        String expectedStartTime = startTime.format(DATETIME_FORMATTER);
        String updatedHeaderDataJson = replaceFirstWetPoreSelfCheckTime(
                stationRecord.getHeaderDataJson(), expectedStartTime);
        if (Objects.equals(stationRecord.getHeaderDataJson(), updatedHeaderDataJson)) {
            return;
        }
        HcStationRecordDO updateObj = new HcStationRecordDO();
        updateObj.setId(stationRecord.getId());
        updateObj.setHeaderDataJson(updatedHeaderDataJson);
        int affectedRows = hcStationRecordMapper.updateById(updateObj);
        HcStationRecordDO persistedRecord = hcStationRecordMapper.selectById(stationRecord.getId());
        String persistedStartTime = readFirstWetPoreSelfCheckTime(
                persistedRecord == null ? null : persistedRecord.getHeaderDataJson());
        if (affectedRows <= 0 || !Objects.equals(expectedStartTime, persistedStartTime)) {
            log.error(
                    "[MES湿法时间联动失败] planOperationId={} stationRecordId={} affectedRows={} "
                            + "saveTable=mes_sfc_station_record saveField=header_data_json.records[0].selfCheckTime "
                            + "expected={} actual={}",
                    planOperationId, stationRecord.getId(), affectedRows, expectedStartTime, persistedStartTime);
            throw invalidParamException("湿法开始时间与泡孔自检时间联动保存失败");
        }
        log.info(
                "[MES湿法时间联动][泡孔自检] planOperationId={} stationRecordId={} affectedRows={} "
                        + "saveTable=mes_sfc_station_record saveField=header_data_json.records[0].selfCheckTime value={}",
                planOperationId, stationRecord.getId(), affectedRows, persistedStartTime);
    }

    String replaceFirstWetPoreSelfCheckTime(String headerDataJson, String startTime) {
        if (StrUtil.isBlank(headerDataJson) || StrUtil.isBlank(startTime)) {
            return headerDataJson;
        }
        JsonNode root = JsonUtils.parseTree(headerDataJson);
        if (root == null || !root.isObject()) {
            throw invalidParamException("泡孔自检记录数据格式不正确");
        }
        ObjectNode target = findFirstWetPoreSelfCheckRecord(root.path("records"));
        if (target == null || Objects.equals(startTime, readJsonText(target, "selfCheckTime"))) {
            return headerDataJson;
        }
        target.put("selfCheckTime", startTime);
        return JsonUtils.toJsonString(root);
    }

    private String readFirstWetPoreSelfCheckTime(String headerDataJson) {
        if (StrUtil.isBlank(headerDataJson)) {
            return null;
        }
        JsonNode root = JsonUtils.parseTree(headerDataJson);
        ObjectNode target = root == null ? null : findFirstWetPoreSelfCheckRecord(root.path("records"));
        return target == null ? null : readJsonText(target, "selfCheckTime");
    }

    private ObjectNode findFirstWetPoreSelfCheckRecord(JsonNode records) {
        if (records == null || !records.isArray()) {
            return null;
        }
        ObjectNode firstContentRecord = null;
        for (JsonNode item : records) {
            if (!item.isObject()) {
                continue;
            }
            ObjectNode objectItem = (ObjectNode) item;
            if (StrUtil.isNotBlank(readJsonText(objectItem, "selfCheckTime"))) {
                return objectItem;
            }
            if (firstContentRecord == null && hasWetPoreSelfCheckContent(objectItem)) {
                firstContentRecord = objectItem;
            }
        }
        return firstContentRecord;
    }

    private void verifyOperationReportTimePersisted(String processName,
                                                    Long operationReportId,
                                                    LocalDate expectedReportDate,
                                                    LocalDateTime expectedStartTime,
                                                    LocalDateTime expectedEndTime,
                                                    HcProcessReportDO persistedReport) {
        if (persistedReport != null
                && Objects.equals(expectedReportDate, persistedReport.getReportDate())
                && Objects.equals(expectedStartTime, persistedReport.getStartTime())
                && Objects.equals(expectedEndTime, persistedReport.getEndTime())) {
            return;
        }
        log.error(
                "[MES报工时间落库校验失败][{}] operationReportId={} saveTable=mes_sfc_operation_report "
                        + "expected reportDate={} startTime={} endTime={}, actual reportDate={} startTime={} endTime={}",
                processName, operationReportId, expectedReportDate, expectedStartTime, expectedEndTime,
                persistedReport == null ? null : persistedReport.getReportDate(),
                persistedReport == null ? null : persistedReport.getStartTime(),
                persistedReport == null ? null : persistedReport.getEndTime());
        throw invalidParamException(processName + "报工时间落库校验失败，请查看后台 MES 报工时间日志");
    }

    private String firstNotBlank(String... values) {
        if (values == null) {
            return null;
        }
        for (String value : values) {
            if (StrUtil.isNotBlank(value)) {
                return value;
            }
        }
        return null;
    }

