    private void validateWetAbnormalPositions(List<HcWetReportAbnormalPositionSaveReqVO> positions) {
        if (positions == null || positions.isEmpty()) {
            return;
        }
        for (HcWetReportAbnormalPositionSaveReqVO position : positions) {
            if (position == null) {
                continue;
            }
            if (StrUtil.isBlank(position.getPositionText())) {
                throw invalidParamException("异常位置不能为空");
            }
            if (position.getAbnormalLength() != null
                    && position.getAbnormalLength().compareTo(BigDecimal.ZERO) < 0) {
                throw invalidParamException("异常位置米数不能为负数");
            }
        }
    }

    private void validateWetAbnormalPositionOption(HcWetReportSaveReqVO reqVO) {
        String option = StrUtil.trimToEmpty(reqVO.getAbnormalPositionOption()).toUpperCase();
        if (!"NONE".equals(option) && !"DETAIL".equals(option)) {
            throw invalidParamException("请选择异常位置选项：无或填写异常位置");
        }
        reqVO.setAbnormalPositionOption(option);
        if ("NONE".equals(option)) {
            reqVO.setAbnormalPositions(Collections.emptyList());
            return;
        }
        if (reqVO.getAbnormalPositions() == null || reqVO.getAbnormalPositions().isEmpty()) {
            throw invalidParamException("请选择“无”，或填写至少一条异常位置");
        }
    }

    private void insertWetAbnormalPositions(List<HcWetReportAbnormalPositionSaveReqVO> positions,
                                            HcProcessReportDO reportDO,
                                            HcPlanOrderDO planOrder,
                                            HcPlanOrderOperationDO operation) {
        if (positions == null || positions.isEmpty()) {
            return;
        }
        List<HcWetReportAbnormalPositionDO> rows = new ArrayList<>();
        for (int i = 0; i < positions.size(); i++) {
            HcWetReportAbnormalPositionSaveReqVO position = positions.get(i);
            if (position == null) {
                continue;
            }
            rows.add(HcWetReportAbnormalPositionDO.builder()
                    .operationReportId(reportDO.getId())
                    .planId(planOrder.getId())
                    .planOperationId(operation.getId())
                    .planNo(planOrder.getPlanNo())
                    .sourceMenuCode(SOURCE_MENU_CODE_WET)
                    .processStage("WET")
                    .operationCode(operation.getOpCode())
                    .operationName(operation.getOpName())
                    .batchNo(firstNotBlank(reportDO.getBatchNo(), planOrder.getBatchNo(), operation.getBatchNo()))
                    .productionBatchNo(firstNotBlank(operation.getProductionBatchNo(), planOrder.getProductionBatchNo()))
                    .positionText(StrUtil.trim(position.getPositionText()))
                    .abnormalLength(position.getAbnormalLength())
                    .remark(StrUtil.trim(position.getRemark()))
                    .sortOrder(position.getSortOrder() == null ? i + 1 : position.getSortOrder())
                    .tenantId(planOrder.getTenantId())
                    .build());
        }
        if (!rows.isEmpty()) {
            hcWetReportAbnormalPositionMapper.insertBatch(rows);
        }
    }

