    private String normalizeWetPoreSelfCheckPhotoHeaderData(String headerDataJson, String formCode) {
        if (!WET_PORE_SELF_CHECK_FORM_CODE.equals(formCode) || StrUtil.isBlank(headerDataJson)) {
            return headerDataJson;
        }
        JsonNode root = JsonUtils.parseTree(headerDataJson);
        if (root == null || !root.isObject()) {
            throw invalidParamException("泡孔自检记录数据格式不正确");
        }
        JsonNode recordsNode = root.path("records");
        if (!recordsNode.isArray()) {
            throw invalidParamException("泡孔自检记录数据不完整");
        }
        for (JsonNode item : recordsNode) {
            if (!item.isObject()) {
                throw invalidParamException("泡孔自检记录数据格式不正确");
            }
            ObjectNode record = (ObjectNode) item;
            LinkedHashSet<String> photos = new LinkedHashSet<>();
            JsonNode photosNode = record.path("photos");
            if (photosNode.isArray()) {
                photosNode.forEach(photo -> addWetPoreSelfCheckPhotoUrl(photos, photo.asText()));
            } else if (!photosNode.isMissingNode() && !photosNode.isNull()) {
                addWetPoreSelfCheckPhotoUrl(photos, photosNode.asText());
            }
            addWetPoreSelfCheckPhotoUrl(photos, readJsonText(record, "photo"));
            if (photos.size() > WET_PORE_SELF_CHECK_MAX_PHOTO_COUNT) {
                throw invalidParamException("每条泡孔自检记录最多上传 "
                        + WET_PORE_SELF_CHECK_MAX_PHOTO_COUNT + " 张照片");
            }
            ArrayNode normalizedPhotos = record.putArray("photos");
            photos.forEach(normalizedPhotos::add);
            // 新数据统一写入 photos，历史 photo 在读取时仍然兼容。
            record.remove("photo");
        }
        return JsonUtils.toJsonString(root);
    }

    /**
     * 湿法生产点检表的物料、型号、机台和批号是报工上下文快照，不信任页面传入值。
     * 点检时间仅属于该张记录，统一写入标准日期时间字符串，不能反写湿法主报工时间。
     */
    private String normalizeWetPassWorkHeaderData(String headerDataJson,
                                                  HcStationFormDO form,
                                                  HcPlanOrderDO planOrder,
                                                  HcPlanOrderOperationDO operation,
                                                  HcStationRecordDO record,
                                                  HcWetPassWorkSaveReqVO reqVO) {
        String normalized = normalizeWetPoreSelfCheckPhotoHeaderData(headerDataJson, form.getFormCode());
        if (!"production-check".equals(resolveWetStationFormCategory(form))) {
            return normalized;
        }
        JsonNode root = StrUtil.isBlank(normalized) ? JsonUtils.parseTree("{}") : JsonUtils.parseTree(normalized);
        if (root == null || !root.isObject()) {
            throw invalidParamException("湿法生产点检表头数据格式不正确");
        }
        ObjectNode header = (ObjectNode) root;
        header.put("materialCode", firstNotBlank(operation.getMotherMaterialCode(),
                planOrder.getMotherMaterialCode(), planOrder.getMaterialCode()));
        header.put("modelCode", firstNotBlank(operation.getMotherModelCode(),
                planOrder.getMotherModelCode(), planOrder.getModelCode()));
        header.put("machine", firstNotBlank(reqVO.getEquipmentCode(), record.getEquipmentCode(),
                operation.getEquipmentCode()));
        header.put("batchNo", firstNotBlank(operation.getProductionBatchNo(), planOrder.getProductionBatchNo(),
                operation.getBatchNo(), planOrder.getBatchNo()));

        LocalDate headerDate = reqVO.getRecordDate();
        if (headerDate == null && reqVO.getRecorderTime() != null) {
            headerDate = reqVO.getRecorderTime().toLocalDate();
        }
        if (headerDate == null && record.getRecordTime() != null) {
            headerDate = record.getRecordTime().toLocalDate();
        }
        if (headerDate == null) {
            headerDate = LocalDate.now();
        }
        LocalDateTime startTime = null;
        LocalDateTime endTime = null;
        for (String field : WET_PRODUCTION_CHECK_HEADER_TIME_FIELDS) {
            String value = readJsonText(header, field);
            if (StrUtil.isBlank(value)) {
                continue;
            }
            LocalDateTime dateTime = normalizeReportDateTime(value, headerDate);
            if (dateTime == null) {
                throw invalidParamException("湿法生产点检表头时间不能为空：" + field);
            }
            if ("startTime".equals(field)) {
                startTime = dateTime;
            } else if ("endTime".equals(field)) {
                endTime = dateTime;
            }
            header.put(field, formatDateTimeWithSeconds(dateTime));
        }
        if (startTime != null && endTime != null && endTime.isBefore(startTime)) {
            throw invalidParamException("湿法生产点检表投料结束时间不能早于投料开始时间");
        }
        return JsonUtils.toJsonString(header);
    }

    private void addWetPoreSelfCheckPhotoUrl(LinkedHashSet<String> photos, String photo) {
        String normalized = StrUtil.trimToNull(photo);
        if (normalized != null) {
            photos.add(normalized);
        }
    }

    private void syncWetThicknessProcessParam(HcPlanOrderDO planOrder,
                                              HcPlanOrderOperationDO operation,
                                              HcStationFormDO form,
                                              HcStationRecordDO record,
                                              List<HcWetPassWorkItemReqVO> detailReqList) {
        if (!isWetSolidSemiForm(form) && !isWetOvenSemiForm(form)) {
            return;
        }
        BigDecimal thickness = calculateWetSemiThickness(detailReqList);
        if (thickness == null) {
            return;
        }
        String batchNo = firstNotBlank(readHeaderJsonText(record.getHeaderDataJson(), "batchNo"),
                operation.getProductionBatchNo(), operation.getBatchNo(),
                planOrder.getProductionBatchNo(), planOrder.getBatchNo());
        String processCode = firstNotBlank(operation.getOpCode(), form.getProcessCode(), PROCESS_CODE_WET);
        if (StrUtil.isBlank(batchNo) || StrUtil.isBlank(processCode)) {
            return;
        }
        LocalDateTime recordTime = firstNonNullDateTime(record.getConfirmTime(), record.getRecordTime(), LocalDateTime.now());
        String recorderName = firstNotBlank(record.getConfirmUserName(), record.getRecordUserName(),
                SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        hcProcessParamRecordService.upsertProcessParam(HcProcessParamRecordUpsertReq.builder()
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .batchNo(batchNo)
                .processCode(processCode)
                .processName(firstNotBlank(operation.getOpName(), form.getProcessName(), "湿法"))
                .paramCode(HcProcessParamRecordService.PARAM_CODE_THICKNESS)
                .paramName(HcProcessParamRecordService.PARAM_NAME_THICKNESS)
                .paramValue(thickness.toPlainString())
                .paramValueNum(thickness)
                .uom("mm")
                .recordTime(recordTime)
                .recorderId(SecurityFrameworkUtils.getLoginUserId())
                .recorderName(recorderName)
                .sourceType(SOURCE_TYPE_WET)
                .sourceTable(SOURCE_TABLE_STATION_RECORD)
                .sourceId(record.getId())
                .sourceFormCode(form.getFormCode())
                .sourceFormName(form.getFormName())
                .remark("湿法半成品厚度自动同步")
                .build());
    }

    private BigDecimal calculateWetSemiThickness(List<HcWetPassWorkItemReqVO> detailReqList) {
        if (detailReqList == null || detailReqList.isEmpty()) {
            return null;
        }
        List<BigDecimal> values = new ArrayList<>();
        for (HcWetPassWorkItemReqVO item : detailReqList) {
            addWetThicknessValue(values, item.getItem());
            addWetThicknessValue(values, item.getStandard());
            addWetThicknessValue(values, item.getActualValue());
            addWetThicknessValue(values, item.getNode());
            if (!WET_SEMI_LENGTH_VALUE_LABEL.equalsIgnoreCase(StrUtil.trim(item.getDualLabel2()))) {
                addWetThicknessValue(values, item.getActualValue2());
            }
        }
        if (values.isEmpty()) {
            return null;
        }
        BigDecimal total = values.stream().reduce(BigDecimal.ZERO, BigDecimal::add);
        return total.divide(BigDecimal.valueOf(values.size()), 4, RoundingMode.HALF_UP).stripTrailingZeros();
    }

    private void addWetThicknessValue(List<BigDecimal> values, String text) {
        BigDecimal value = parseDecimalFromText(text);
        if (value != null) {
            values.add(value);
        }
    }

    private BigDecimal parseDecimalFromText(String text) {
        if (StrUtil.isBlank(text)) {
            return null;
        }
        Matcher matcher = DECIMAL_TEXT_PATTERN.matcher(text.trim());
        if (!matcher.find()) {
            return null;
        }
        try {
            return new BigDecimal(matcher.group());
        } catch (NumberFormatException ex) {
            return null;
        }
    }

    private String readHeaderJsonText(String headerDataJson, String fieldName) {
        if (StrUtil.isBlank(headerDataJson)) {
            return null;
        }
        try {
            JsonNode root = JsonUtils.parseTree(headerDataJson);
            return root == null ? null : StrUtil.trimToNull(readJsonText(root, fieldName));
        } catch (RuntimeException ex) {
            return null;
        }
    }

