    private HcProcessFormRecordDO buildPressSlotBaseProcessFormRecord(String recordNo,
                                                                      HcStationFormDO form,
                                                                      HcPlanOrderDO planOrder,
                                                                      HcPlanOrderOperationDO operation,
                                                                      String batchNo,
                                                                      LocalDate recordDate,
                                                                      LocalDateTime fillTime,
                                                                      String fillUserName,
                                                                      LocalDateTime confirmTime,
                                                                      String confirmUserName,
                                                                      String formType,
                                                                      String formTypeName,
                                                                      String templateName,
                                                                      Map<String, Object> headerData,
                                                                      Map<String, Object> contextData,
                                                                      String resultStatus,
                                                                      String recordStatus,
                                                                      String remark) {
        HcProcessFormRecordDO existed = findPressSlotProcessFormRecord(recordNo, formType, batchNo);
        HcProcessFormRecordDO record = existed == null ? new HcProcessFormRecordDO() : existed;
        record.setRecordNo(recordNo);
        if (form != null) {
            record.setTemplateId(form.getId());
            record.setVersionId(resolvePressSlotStationFormVersionId(form));
            record.setTemplateCode(form.getFormCode());
        }
        record.setTemplateName(firstNotBlank(templateName,
                form == null ? null : stripPressSlotDisplayName(firstNotBlank(resolvePressSlotStationDisplayName(form), form.getFormName()))));
        record.setProcessCode(PROCESS_CODE_PRESS_SLOT);
        record.setProcessName(firstNotBlank(operation.getOpName(), "压槽"));
        record.setModelCode(firstNotBlank(planOrder.getModelCode(), planOrder.getModelName()));
        record.setModelName(firstNotBlank(planOrder.getModelName(), planOrder.getModelCode()));
        record.setFormType(formType);
        record.setFormTypeName(formTypeName);
        record.setRecordDate(recordDate == null ? LocalDate.now() : recordDate);
        record.setPlanId(planOrder.getId());
        record.setPlanNo(planOrder.getPlanNo());
        record.setPlanOperationId(operation.getId());
        record.setBatchNo(firstNotBlank(batchNo, operation.getProductionBatchNo(), operation.getBatchNo(),
                planOrder.getProductionBatchNo(), planOrder.getBatchNo()));
        record.setEquipmentId(operation.getEquipmentId());
        record.setEquipmentCode(operation.getEquipmentCode());
        record.setEquipmentName(operation.getEquipmentName());
        record.setRecordStatus(normalizeProcessFormRecordStatus(recordStatus, confirmTime));
        record.setResultStatus(StrUtil.blankToDefault(resultStatus, "OK"));
        record.setFillUserName(firstNotBlank(fillUserName, SecurityFrameworkUtils.getLoginUserNickname(), "系统"));
        record.setFillTime(firstNotNullDateTime(fillTime, LocalDateTime.now()));
        record.setConfirmUserName(confirmUserName);
        record.setConfirmTime(confirmTime);
        record.setHeaderDataJson(JsonUtils.toJsonString(headerData == null ? Collections.emptyMap() : headerData));
        record.setContextJson(JsonUtils.toJsonString(contextData == null ? Collections.emptyMap() : contextData));
        record.setRemark(remark);
        record.setTenantId(planOrder.getTenantId());
        return record;
    }

    private HcProcessFormRecordDO findPressSlotProcessFormRecord(String recordNo, String formType, String batchNo) {
        HcProcessFormRecordDO record = hcProcessFormRecordMapper.selectOneByRecordNo(recordNo);
        if (record != null) {
            return record;
        }
        if (StrUtil.isBlank(batchNo)) {
            return null;
        }
        return hcProcessFormRecordMapper.selectOne(new LambdaQueryWrapperX<HcProcessFormRecordDO>()
                .eq(HcProcessFormRecordDO::getProcessCode, PROCESS_CODE_PRESS_SLOT)
                .eq(HcProcessFormRecordDO::getFormType, formType)
                .eq(HcProcessFormRecordDO::getBatchNo, batchNo)
                .orderByDesc(HcProcessFormRecordDO::getId)
                .last("LIMIT 1"));
    }

    private void upsertPressSlotProcessFormRecord(HcProcessFormRecordDO record,
                                                  List<HcProcessFormRecordItemDO> items) {
        if (record.getTemplateId() == null) {
            throw invalidParamException(buildPressSlotMissingStationFormMessage(record.getFormType()));
        }
        if (record.getId() == null) {
            hcProcessFormRecordMapper.insert(record);
        } else {
            hcProcessFormRecordMapper.updateById(record);
            hcProcessFormRecordItemMapper.deleteByRecordId(record.getId());
        }
        if (items == null || items.isEmpty()) {
            return;
        }
        final Long recordId = record.getId();
        final Long tenantId = record.getTenantId();
        items.forEach(item -> {
            item.setId(null);
            item.setRecordId(recordId);
            item.setTenantId(tenantId);
        });
        hcProcessFormRecordItemMapper.insertBatch(items);
    }

