    private String buildPressSlotMissingStationFormMessage(String formType) {
        return resolvePressSlotStationFormConfigName(formType) + "模板配置没有找到配置，请联系管理员！";
    }

    private String resolvePressSlotStationFormConfigName(String formType) {
        if (PRESS_SLOT_PRODUCTION_CHECK_FORM_TYPE.equalsIgnoreCase(formType)) {
            return "压槽生产点检表";
        }
        if (PRESS_SLOT_PROCESS_PARAM_FORM_TYPE.equalsIgnoreCase(formType)) {
            return "CMP压槽工艺参数表";
        }
        if (PRESS_SLOT_INTERMEDIATE_FORM_TYPE.equalsIgnoreCase(formType)) {
            return "压槽中间品记录表";
        }
        if ("CLEANING_CHECK".equalsIgnoreCase(formType)) {
            return "压槽清洁保养记录";
        }
        return "压槽表单";
    }

