    private PressSlotIntermediateTemplateMeta buildPressSlotIntermediateTemplateMeta(HcStationFormDO form) {
        Map<String, Object> schema = parsePressSlotStationFormSchema(form);
        String slotDepthStandard = firstNotBlank(
                toStringValue(schema.get("slotDepthStandard")),
                toStringValue(schema.get("firstSlotDepthStandard")),
                toStringValue(schema.get("firstSlotDepthStandardText")),
                PRESS_SLOT_INTERMEDIATE_DEFAULT_SLOT_DEPTH_STANDARD);
        String thicknessStandard = firstNotBlank(
                toStringValue(schema.get("thicknessStandard")),
                toStringValue(schema.get("intermediateThicknessStandard")),
                PRESS_SLOT_INTERMEDIATE_DEFAULT_THICKNESS_STANDARD);
        Integer thicknessColumnCount = firstNotNullInteger(
                parseInteger(toStringValue(schema.get("thicknessColumnCount"))),
                parseInteger(toStringValue(schema.get("thicknessColumns"))),
                PRESS_SLOT_INTERMEDIATE_DEFAULT_THICKNESS_COLUMN_COUNT);
        Integer thicknessIntervalCm = firstNotNullInteger(
                parseInteger(toStringValue(schema.get("thicknessIntervalCm"))),
                parseInteger(toStringValue(schema.get("thicknessMeasureIntervalCm"))),
                PRESS_SLOT_INTERMEDIATE_DEFAULT_THICKNESS_INTERVAL_CM);
        return new PressSlotIntermediateTemplateMeta(
                form == null ? null : form.getId(),
                form == null ? "" : form.getFormCode(),
                form == null ? null : form.getFormName(),
                firstNotBlank(form == null ? null : resolvePressSlotStationDisplayName(form),
                        form == null ? null : form.getFormName(), "压槽中间品记录表"),
                form == null ? null : form.getSchemaJson(),
                form == null ? null : form.getProcessCode(),
                toStringValue(schema.get("sourceExcel")),
                toStringValue(schema.get("sourceSheet")),
                slotDepthStandard,
                thicknessStandard,
                thicknessColumnCount,
                thicknessIntervalCm);
    }

