    private List<HcProcessFormRecordItemDO> buildPressSlotProcessParamRecordItems(HcPressSlotReportDO report,
                                                                                  HcStationFormDO form) {
        List<HcPressSlotCheckDetailDO> details = hcPressSlotCheckDetailMapper.selectListByReportId(report.getId());
        List<String> temperatures = new ArrayList<>();
        for (int i = 1; i <= 5; i++) {
            temperatures.add(resolvePressSlotTemperature(details, i));
        }
        List<HcStationFormItemDO> templateItems = getPressSlotStationFormItems(form, PRESS_SLOT_PROCESS_PARAM_FORM_TYPE);
        List<HcProcessFormRecordItemDO> items = new ArrayList<>();
        int tempIndex = 0;
        for (HcStationFormItemDO item : templateItems) {
            String value = resolvePressSlotProcessParamTemplateValue(report, item, temperatures, tempIndex);
            if (StrUtil.contains(firstNotBlank(item.getItemName(), ""), "温度")) {
                tempIndex++;
            }
            items.add(HcProcessFormRecordItemDO.builder()
                    .templateItemId(item.getId())
                    .itemSeq(item.getItemSeq())
                    .fieldKey("station_item_" + StrUtil.blankToDefault(String.valueOf(item.getItemSeq()), String.valueOf(items.size() + 1)))
                    .fieldLabel(item.getItemName())
                    .itemCategory(item.getItemCategory())
                    .stepNode(item.getStepNode())
                    .standardText(item.getStandardText())
                    .valueMode(item.getValueMode())
                    .actualValue(value)
                    .actualNumber(parseDecimalFromText(value))
                    .resultFlag(StrUtil.blankToDefault(item.getDefaultResult(), "OK"))
                    .abnormalRemark(item.getRemark())
                    .sourceRowJson(JsonUtils.toJsonString(item))
                    .tenantId(report.getTenantId())
                    .build());
        }
        return items;
    }

    private String resolvePressSlotProcessParamTemplateValue(HcPressSlotReportDO report,
                                                             HcStationFormItemDO item,
                                                             List<String> temperatures,
                                                             int tempIndex) {
        String text = firstNotBlank(item.getItemName(), "");
        if (StrUtil.contains(text, "型号")) {
            return report.getModelCode();
        }
        if (StrUtil.contains(text, "批号") && !StrUtil.contains(text, "片号")) {
            return firstNotBlank(report.getParentProductionBatchNo(), report.getSourceBatchNo());
        }
        if (StrUtil.contains(text, "片号")) {
            return report.getProductionBatchNo();
        }
        if (StrUtil.contains(text, "日期")) {
            return report.getReportDate() == null ? "" : report.getReportDate().toString();
        }
        if (StrUtil.contains(text, "记录人")) {
            return report.getRecorderName();
        }
        if (StrUtil.contains(text, "结果")) {
            return report.getSelfCheck();
        }
        if (StrUtil.contains(text, "检验时间") || StrUtil.contains(text, "反馈时间")) {
            LocalDateTime time = firstNotNullDateTime(report.getConfirmerTime(), report.getEndTime(), report.getRecorderTime());
            return time == null ? "" : time.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));
        }
        if (StrUtil.contains(text, "温度")) {
            return tempIndex >= 0 && tempIndex < temperatures.size() ? temperatures.get(tempIndex) : "";
        }
        return "";
    }
