    private Map<String, Object> buildPressSlotProcessFormContext(String bindType,
                                                                 Long sourceId,
                                                                 Map<String, Object> importAttachment) {
        Map<String, Object> contextData = new LinkedHashMap<>();
        contextData.put("bindType", bindType);
        contextData.put("sourceId", sourceId);
        contextData.put("sourceProcess", PROCESS_CODE_PRESS_SLOT);
        if (importAttachment != null && !importAttachment.isEmpty()) {
            contextData.put(PRESS_SLOT_IMPORT_ATTACHMENT_KEY, importAttachment);
            contextData.put("processFormExcelAttachments", List.of(importAttachment));
            contextData.put("importTime", importAttachment.get("uploadTime"));
        }
        return contextData;
    }

    private void writeImportAttachment(Map<String, Object> target, Map<String, Object> importAttachment) {
        if (target == null || importAttachment == null || importAttachment.isEmpty()) {
            return;
        }
        target.put(PRESS_SLOT_IMPORT_ATTACHMENT_KEY, importAttachment);
        target.put("attachments", List.of(importAttachment));
        target.put("importTime", importAttachment.get("uploadTime"));
    }

    private Map<String, Object> parseImportAttachmentJson(String importAttachmentJson) {
        if (StrUtil.isBlank(importAttachmentJson)) {
            return Collections.emptyMap();
        }
        Map<String, Object> map = JsonUtils.parseObjectQuietly(importAttachmentJson,
                new TypeReference<Map<String, Object>>() {});
        return map == null ? Collections.emptyMap() : new LinkedHashMap<>(map);
    }

    private String resolvePressSlotStationProcessFormType(HcStationFormDO form) {
        Map<String, Object> schema = parsePressSlotStationFormSchema(form);
        String explicitType = firstNotBlank(
                toStringValue(schema.get("pressSlotFormType")),
                toStringValue(schema.get("processFormType")),
                toStringValue(schema.get("formType")),
                toStringValue(schema.get("type")));
        String normalizedType = StrUtil.trimToEmpty(explicitType).toUpperCase();
        String formCode = form == null ? "" : StrUtil.blankToDefault(form.getFormCode(), "").toUpperCase();
        String formName = form == null ? "" : StrUtil.blankToDefault(form.getFormName(), "");
        String combined = normalizedType + " " + formCode + " " + formName;
        if (combined.contains(PRESS_SLOT_PROCESS_PARAM_FORM_TYPE)
                || (combined.contains("PROCESS") && combined.contains("PARAM"))
                || combined.contains("工艺参数")) {
            return PRESS_SLOT_PROCESS_PARAM_FORM_TYPE;
        }
        if (combined.contains(PRESS_SLOT_PRODUCTION_CHECK_FORM_TYPE)
                || (combined.contains("PRODUCTION") && combined.contains("CHECK"))
                || combined.contains("生产点检")) {
            return PRESS_SLOT_PRODUCTION_CHECK_FORM_TYPE;
        }
        if (combined.contains(PRESS_SLOT_INTERMEDIATE_FORM_TYPE)
                || combined.contains("INTERMEDIATE")
                || combined.contains("中间品")) {
            return PRESS_SLOT_INTERMEDIATE_FORM_TYPE;
        }
        if (combined.contains("CLEAN") || combined.contains("清洁")) {
            return "CLEANING_CHECK";
        }
        if (combined.contains("HOIST") || combined.contains("电葫芦")) {
            return "ELECTRIC_HOIST_CHECK";
        }
        if (combined.contains("STARTUP") || combined.contains("开机")) {
            return "STARTUP_CHECK";
        }
        return "MAINTENANCE_CHECK";
    }

    private String resolvePressSlotStationProcessFormTypeName(String formType, HcStationFormDO form) {
        if (PRESS_SLOT_PROCESS_PARAM_FORM_TYPE.equals(formType)) {
            return "工艺参数";
        }
        if (PRESS_SLOT_PRODUCTION_CHECK_FORM_TYPE.equals(formType)) {
            return "生产点检";
        }
        if (PRESS_SLOT_INTERMEDIATE_FORM_TYPE.equals(formType)) {
            return "中间品记录";
        }
        if ("CLEANING_CHECK".equals(formType)) {
            return "清洁保养";
        }
        if ("ELECTRIC_HOIST_CHECK".equals(formType)) {
            return "电葫芦点检";
        }
        if ("STARTUP_CHECK".equals(formType)) {
            return "开机点检";
        }
        return firstNotBlank(form == null ? null : form.getTriggerTimingName(), "点检保养");
    }

    private String resolvePressSlotStationDisplayName(HcStationFormDO form) {
        if (form == null) {
            return "压槽表单";
        }
        Map<String, Object> schema = parsePressSlotStationFormSchema(form);
        return firstNotBlank(
                toStringValue(schema.get("displayName")),
                toStringValue(schema.get("formDisplayName")),
                form.getFormName());
    }

    private String normalizeProcessFormRecordStatus(String status, LocalDateTime confirmTime) {
        if (confirmTime != null || RECORD_STATUS_CONFIRMED.equalsIgnoreCase(StrUtil.blankToDefault(status, ""))) {
            return "CONFIRMED";
        }
        String normalized = StrUtil.blankToDefault(status, "SUBMITTED").toUpperCase();
        if (RECORD_STATUS_RECORDED.equalsIgnoreCase(normalized) || "DRAFT".equalsIgnoreCase(normalized)) {
            return "SUBMITTED";
        }
        return normalized;
    }

    private boolean reusablePressSlotPassWorkRecord(HcStationRecordDO record, Long equipmentId, LocalDate recordDate,
                                                    String formCode, Long planOperationId) {
        if (record == null || Boolean.TRUE.equals(record.getDeleted()) || !Objects.equals(record.getFormCode(), formCode)) {
            return false;
        }
        if ("EQUIPMENT_DAILY".equalsIgnoreCase(StrUtil.blankToDefault(record.getRecordScope(), ""))) {
            return Objects.equals(record.getEquipmentId(), equipmentId)
                    && Objects.equals(record.getRecordDate(), recordDate);
        }
        return Objects.equals(record.getPlanOperationId(), planOperationId);
    }

    private boolean reusableEquipmentDailyPassWorkRecord(HcStationRecordDO record, Long equipmentId, LocalDate recordDate,
                                                         String formCode) {
        if (record == null || Boolean.TRUE.equals(record.getDeleted()) || !Objects.equals(record.getFormCode(), formCode)) {
            return false;
        }
        return "EQUIPMENT_DAILY".equalsIgnoreCase(StrUtil.blankToDefault(record.getRecordScope(), ""))
                && Objects.equals(record.getEquipmentId(), equipmentId)
                && Objects.equals(record.getRecordDate(), recordDate);
    }

    private List<HcWetPassWorkRespVO> buildEquipmentDailyPassWorkList(HcPlanOrderOperationDO operation,
                                                                      String processCode,
                                                                      LocalDate recordDate) {
        Long equipmentId = operation.getEquipmentId();
        List<HcStationFormDO> forms = hcStationFormMapper.selectEnabledByProcess(processCode).stream()
                .filter(form -> !"IN_PROCESS".equalsIgnoreCase(StrUtil.blankToDefault(form.getTriggerTimingCode(), "")))
                .toList();
        if (forms.isEmpty()) {
            return Collections.emptyList();
        }
        Set<Long> formIds = forms.stream().map(HcStationFormDO::getId).collect(Collectors.toSet());
        Map<Long, List<HcStationFormItemDO>> templateItemMap = hcStationFormItemMapper.selectByFormIds(formIds).stream()
                .collect(Collectors.groupingBy(HcStationFormItemDO::getFormId, LinkedHashMap::new, Collectors.toList()));
        Map<Long, HcStationRecordDO> recordMap = new LinkedHashMap<>();
        if (equipmentId != null) {
            Set<String> formCodes = forms.stream().map(HcStationFormDO::getFormCode).collect(Collectors.toSet());
            for (HcStationRecordDO record : hcStationRecordMapper.selectListByEquipmentDaily(equipmentId, recordDate, formCodes)) {
                recordMap.putIfAbsent(record.getFormId(), record);
            }
        }
        Set<Long> recordIds = recordMap.values().stream().map(HcStationRecordDO::getId).collect(Collectors.toSet());
        Map<Long, List<HcStationRecordItemDO>> recordItemMap = hcStationRecordItemMapper.selectByRecordIds(recordIds).stream()
                .collect(Collectors.groupingBy(HcStationRecordItemDO::getRecordId, LinkedHashMap::new, Collectors.toList()));
        List<HcWetPassWorkRespVO> result = new ArrayList<>();
        for (HcStationFormDO form : forms) {
            HcStationRecordDO record = recordMap.get(form.getId());
            HcWetPassWorkRespVO respVO = new HcWetPassWorkRespVO();
            respVO.setRecordId(record != null ? record.getId() : null);
            respVO.setFormId(form.getId());
            respVO.setFormCode(form.getFormCode());
            respVO.setId(record != null ? String.valueOf(record.getId()) : form.getFormCode());
            respVO.setName(form.getFormName());
            respVO.setTiming(form.getTriggerTimingName());
            respVO.setStatus(record == null ? "NOT_FILLED" : record.getDocStatus());
            respVO.setResult(record == null ? null : record.getResultStatus());
            respVO.setRecorder(record == null ? null : record.getRecordUserName());
            respVO.setRecorderTime(formatDateTime(record == null ? null : record.getRecordTime()));
            respVO.setConfirmer(record == null ? null : record.getConfirmUserName());
            respVO.setConfirmerTime(formatDateTime(record == null ? null : record.getConfirmTime()));
            respVO.setFormRemark(record == null ? form.getRemark() : record.getFormRemark());
            respVO.setConfirmRemark(record == null ? null : record.getConfirmRemark());
            respVO.setInspectionResult(record == null ? null : record.getInspectionResult());
            respVO.setHeaderDataJson(record == null ? form.getPresetHeaderDataJson() : record.getHeaderDataJson());
            respVO.setSchemaJson(form.getSchemaJson());
            respVO.setPresetHeaderDataJson(form.getPresetHeaderDataJson());
            respVO.setCanFill(true);
            respVO.setCanConfirm(true);
            respVO.setCanView(record != null);
            respVO.setDetails(buildWetPassWorkDetails(recordItemMap.get(record != null ? record.getId() : null), templateItemMap.get(form.getId())));
            result.add(respVO);
        }
        return result;
    }

    private Long upsertAdhesive2PassWork(HcWetPassWorkSaveReqVO reqVO, boolean confirm) {
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(reqVO.getPlanId());
        HcPlanOrderOperationDO operation = validateAdhesive2Operation(planOrder, reqVO.getPlanOperationId());
        LocalDate recordDate = reqVO.getRecordDate() == null ? LocalDate.now() : reqVO.getRecordDate();
        Long equipmentId = reqVO.getEquipmentId() != null ? reqVO.getEquipmentId() : operation.getEquipmentId();
        if (equipmentId == null) {
            throw invalidParamException("请先选择粘胶2设备，再保存今日点检/清洁记录");
        }
        HcStationFormDO form = hcStationFormMapper.selectEnabledByCode(reqVO.getFormCode());
        if (form == null || !PROCESS_CODE_ADHESIVE2.equals(form.getProcessCode())) {
            throw invalidParamException("粘胶2加工前点检清洁模板不存在");
        }
        HcStationRecordDO requestRecord = reqVO.getRecordId() != null ? hcStationRecordMapper.selectById(reqVO.getRecordId()) : null;
        HcStationRecordDO record = hcStationRecordMapper.selectOneByEquipmentDaily(equipmentId, recordDate, reqVO.getFormCode());
        if (record == null) {
            record = reusableEquipmentDailyPassWorkRecord(requestRecord, equipmentId, recordDate, reqVO.getFormCode())
                    ? requestRecord : null;
        }
        boolean newRecord = record == null;
        if (newRecord) {
            record = HcStationRecordDO.builder()
                    .planId(planOrder.getId())
                    .planNo(planOrder.getPlanNo())
                    .planOperationId(operation.getId())
                    .operationName(operation.getOpName())
                    .formId(form.getId())
                    .formCode(form.getFormCode())
                    .formName(form.getFormName())
                    .triggerTimingCode(form.getTriggerTimingCode())
                    .triggerTimingName(form.getTriggerTimingName())
                    .recordScope("EQUIPMENT_DAILY")
                    .recordDate(recordDate)
                    .equipmentId(equipmentId)
                    .equipmentCode(firstNotBlank(reqVO.getEquipmentCode(), operation.getEquipmentCode()))
                    .equipmentName(firstNotBlank(reqVO.getEquipmentName(), operation.getEquipmentName()))
                    .operationCode(operation.getOpCode())
                    .workCenterId(operation.getWorkCenterId())
                    .workCenterCode(operation.getWorkCenterCode())
                    .workCenterName(operation.getWorkCenterName())
                    .tenantId(planOrder.getTenantId())
                    .build();
        }
        LocalDateTime now = LocalDateTime.now();
        String currentNickname = firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统");
        record.setDocStatus(confirm ? RECORD_STATUS_CONFIRMED : RECORD_STATUS_RECORDED);
        record.setResultStatus(StrUtil.blankToDefault(reqVO.getResult(), "OK"));
        record.setInspectionResult(StrUtil.blankToDefault(reqVO.getInspectionResult(), record.getResultStatus()));
        record.setRecordScope("EQUIPMENT_DAILY");
        record.setRecordDate(recordDate);
        record.setPlanId(planOrder.getId());
        record.setPlanNo(planOrder.getPlanNo());
        record.setPlanOperationId(operation.getId());
        record.setOperationName(operation.getOpName());
        record.setOperationCode(operation.getOpCode());
        record.setEquipmentId(equipmentId);
        record.setEquipmentCode(firstNotBlank(reqVO.getEquipmentCode(), record.getEquipmentCode(), operation.getEquipmentCode()));
        record.setEquipmentName(firstNotBlank(reqVO.getEquipmentName(), record.getEquipmentName(), operation.getEquipmentName()));
        record.setWorkCenterId(operation.getWorkCenterId());
        record.setWorkCenterCode(operation.getWorkCenterCode());
        record.setWorkCenterName(operation.getWorkCenterName());
        if (confirm) {
            record.setRecordUserName(firstNotBlank(reqVO.getRecorder(), record.getRecordUserName(), currentNickname));
            record.setRecordTime(record.getRecordTime() != null ? record.getRecordTime() : now);
            record.setConfirmUserName(firstNotBlank(reqVO.getConfirmer(), currentNickname));
            record.setConfirmTime(now);
        } else {
            record.setRecordUserName(firstNotBlank(reqVO.getRecorder(), currentNickname));
            record.setRecordTime(now);
        }
        record.setHeaderDataJson(reqVO.getHeaderDataJson());
        record.setFormRemark(reqVO.getFormRemark());
        record.setConfirmRemark(reqVO.getConfirmRemark());
        if (newRecord) {
            hcStationRecordMapper.insert(record);
        } else {
            hcStationRecordMapper.updateById(record);
        }
        hcStationRecordItemMapper.deleteByRecordId(record.getId());
        List<HcWetPassWorkItemReqVO> detailReqList = reqVO.getDetails();
        if (detailReqList != null && !detailReqList.isEmpty()) {
            final Long recordId = record.getId();
            final Long tenantId = planOrder.getTenantId();
            List<HcStationRecordItemDO> items = detailReqList.stream()
                    .map(item -> HcStationRecordItemDO.builder()
                            .recordId(recordId)
                            .itemSeq(item.getItemSeq())
                            .itemCategory(item.getCategory())
                            .stepNode(item.getNode())
                            .itemName(item.getItem())
                            .standardText(item.getStandard())
                            .valueMode(item.getValueMode())
                            .dualLabel1(item.getDualLabel1())
                            .dualLabel2(item.getDualLabel2())
                            .actualValue(item.getActualValue())
                            .actualValue2(item.getActualValue2())
                            .resultFlag(StrUtil.blankToDefault(item.getStatus(), "OK"))
                            .abnormalRemark(item.getRemark())
                            .tenantId(tenantId)
                            .build())
                    .toList();
            hcStationRecordItemMapper.insertBatch(items);
        }
        return record.getId();
    }

    private void assertPlanReleasedForStart(HcPlanOrderDO plan) {
        if (plan == null || !PLAN_STATUS_RELEASED.equals(plan.getPlanStatus())) {
            throw invalidParamException("只有已下发计划允许开工，计划可能已撤回，请刷新任务");
        }
    }

    private void validateLockedFormulaOperation(HcPlanOrderDO plan, HcPlanOrderOperationDO operation) {
        if (plan == null) throw invalidParamException("生产计划不存在");
        if (operation == null || !Objects.equals(operation.getPlanId(), plan.getId()) || !"配料".equals(operation.getOpName())) {
            throw invalidParamException("计划配料工序不存在");
        }
    }

    private HcPlanOrderOperationDO validateFormulaOperation(HcPlanOrderDO planOrder, Long planOperationId) {
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(planOperationId);
        if (operation == null || !Objects.equals(operation.getPlanId(), planOrder.getId())) {
            throw invalidParamException("计划工序不存在");
        }
        if (!"配料".equals(operation.getOpName())) {
            throw invalidParamException("当前仅允许配料工序使用该功能");
        }
        return operation;
    }

    private HcPlanOrderOperationDO validateWetOperation(HcPlanOrderDO planOrder, Long planOperationId) {
        return validateWetOperation(planOrder, hcPlanOrderOperationMapper.selectById(planOperationId), planOperationId);
    }

    private HcPlanOrderOperationDO validateWetOperation(HcPlanOrderDO planOrder,
                                                         HcPlanOrderOperationDO operation,
                                                         Long planOperationId) {
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        if (operation == null || !Objects.equals(operation.getPlanId(), planOrder.getId())) {
            throw invalidParamException("计划工序不存在");
        }
        if (StrUtil.isBlank(operation.getOpName()) || !operation.getOpName().startsWith("湿法")) {
            throw invalidParamException("当前仅允许湿法工序使用该功能");
        }
        return operation;
    }

    private HcPlanOrderOperationDO validateRoughOperation(HcPlanOrderDO planOrder, Long planOperationId) {
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(planOperationId);
        if (operation == null || !Objects.equals(operation.getPlanId(), planOrder.getId())) {
            throw invalidParamException("计划工序不存在");
        }
        if (StrUtil.isBlank(operation.getOpName())
                || (!operation.getOpName().contains("磨皮") && !operation.getOpName().contains("粗磨"))) {
            throw invalidParamException("当前仅允许磨皮工序使用该功能");
        }
        return operation;
    }

    private HcPlanOrderOperationDO validateAdhesiveOperation(HcPlanOrderDO planOrder, Long planOperationId) {
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(planOperationId);
        if (operation == null || !Objects.equals(operation.getPlanId(), planOrder.getId())) {
            throw invalidParamException("计划工序不存在");
        }
        String opName = StrUtil.trimToEmpty(operation.getOpName());
        if (StrUtil.isBlank(opName)
                || (!opName.contains("粘双面胶") && !opName.contains("粘胶1") && !opName.contains("粘胶一"))
                || opName.contains("粘胶2")
                || opName.contains("背胶")) {
            throw invalidParamException("当前仅允许粘双面胶/粘胶1工序使用该功能");
        }
        return operation;
    }

    private HcPlanOrderOperationDO validateAdhesiveGlueBoardOperation(HcPlanOrderDO planOrder, Long planOperationId) {
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(planOperationId);
        if (operation == null || !Objects.equals(operation.getPlanId(), planOrder.getId())) {
            throw invalidParamException("计划工序不存在");
        }
        String opCode = StrUtil.trimToEmpty(operation.getOpCode());
        String opName = StrUtil.trimToEmpty(operation.getOpName());
        boolean adhesive1 = opName.contains("粘双面胶")
                || opName.contains("粘胶1")
                || opName.contains("粘胶一");
        boolean adhesive2 = "OP-ADHESIVE2".equalsIgnoreCase(opCode)
                || opName.contains("粘胶2")
                || opName.contains("背胶");
        if (!adhesive1 && !adhesive2) {
            throw invalidParamException("当前仅允许粘双面胶/粘胶1/粘胶2工序使用该功能胶板领用登记");
        }
        return operation;
    }

    private HcPlanOrderOperationDO validateAdhesive2Operation(HcPlanOrderDO planOrder, Long planOperationId) {
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(planOperationId);
        if (operation == null || !Objects.equals(operation.getPlanId(), planOrder.getId())) {
            throw invalidParamException("计划工序不存在");
        }
        String opCode = StrUtil.trimToEmpty(operation.getOpCode());
        String opName = StrUtil.trimToEmpty(operation.getOpName());
        if (!"OP-ADHESIVE2".equalsIgnoreCase(opCode)
                && !opName.contains("粘胶2")
                && !opName.contains("背胶")) {
            throw invalidParamException("当前仅允许粘胶2/单片背胶工序使用该功能");
        }
        return operation;
    }

    private boolean isAdhesive2Operation(HcPlanOrderOperationDO operation) {
        if (operation == null) {
            return false;
        }
        String opCode = StrUtil.trimToEmpty(operation.getOpCode());
        String opName = StrUtil.trimToEmpty(operation.getOpName());
        return "OP-ADHESIVE2".equalsIgnoreCase(opCode)
                || opName.contains("粘胶2")
                || opName.contains("背胶");
    }

    private boolean hasBoundEquipment(HcPlanOrderOperationDO operation) {
        return operation != null
                && (normalizePositiveId(operation.getEquipmentId()) != null
                || StrUtil.isNotBlank(operation.getEquipmentCode()));
    }

    private boolean hasEquipmentIdentity(Long equipmentId, String equipmentCode) {
        return normalizePositiveId(equipmentId) != null || StrUtil.isNotBlank(equipmentCode);
    }

    private boolean isSameEquipmentIdentity(Long leftEquipmentId, String leftEquipmentCode,
                                            Long rightEquipmentId, String rightEquipmentCode) {
        Long normalizedLeftId = normalizePositiveId(leftEquipmentId);
        Long normalizedRightId = normalizePositiveId(rightEquipmentId);
        if (normalizedLeftId != null && normalizedRightId != null) {
            return Objects.equals(normalizedLeftId, normalizedRightId);
        }
        String normalizedLeftCode = StrUtil.trimToNull(leftEquipmentCode);
        String normalizedRightCode = StrUtil.trimToNull(rightEquipmentCode);
        return normalizedLeftCode != null && normalizedRightCode != null
                && StrUtil.equalsIgnoreCase(normalizedLeftCode, normalizedRightCode);
    }

    List<HcAdhesiveGlueBoardUsageDO> selectActiveAdhesive2GlueBoardUsagesForEquipment(
            HcPlanOrderOperationDO operation) {
        if (!hasBoundEquipment(operation)) {
            return Collections.emptyList();
        }
        return hcAdhesiveGlueBoardUsageMapper.selectActiveAdhesive2ListByEquipment(
                operation.getEquipmentId(), operation.getEquipmentCode());
    }

    private HcPlanOrderOperationDO validateSlittingOperation(HcPlanOrderDO planOrder, Long planOperationId) {
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(planOperationId);
        if (operation == null || !Objects.equals(operation.getPlanId(), planOrder.getId())) {
            throw invalidParamException("计划工序不存在");
        }
        String opCode = StrUtil.trimToEmpty(operation.getOpCode());
        String opName = StrUtil.trimToEmpty(operation.getOpName());
        if (!"OP-SLIT".equalsIgnoreCase(opCode) && !opName.contains("分切")) {
            throw invalidParamException("当前仅允许分切工序使用该功能");
        }
        return operation;
    }

    private void validateSlittingOperationMutable(HcPlanOrderOperationDO operation, String actionName) {
        if (operation == null) {
            throw invalidParamException("计划工序不存在");
        }
        String operationStatus = StrUtil.trimToEmpty(operation.getOperationStatus()).toUpperCase();
        if (OP_STATUS_FINISHED.equals(operationStatus)) {
            throw invalidParamException("当前分切工序已完工，仅可查看，不能{}", actionName);
        }
        if (OP_STATUS_PAUSED.equals(operationStatus)) {
            throw invalidParamException("当前分切工序已暂停，请等待生产计划复工后再{}", actionName);
        }
        if (OP_STATUS_CANCELLED.equals(operationStatus) || "CANCELED".equals(operationStatus)) {
            throw invalidParamException("当前分切工序已作废取消，不能{}", actionName);
        }
    }

    private boolean isSlittingSourceCompleted(HcAdhesiveReportDO sourceReport) {
        Map<String, Object> extra = parseRoughExtraMap(sourceReport == null ? null : sourceReport.getExtraJson());
        Object status = extra.get(SLITTING_SOURCE_STATUS_KEY);
        return status != null && SLITTING_SOURCE_COMPLETED.equalsIgnoreCase(String.valueOf(status));
    }

    private void validateSlittingSourceMutable(HcAdhesiveReportDO sourceReport, String actionName) {
        if (isSlittingSourceCompleted(sourceReport)) {
            throw invalidParamException("当前分切段已完工，仅可查看，不能{}", actionName);
        }
    }

    private void validateSlittingSliceMutable(HcSlittingSliceRecordDO record, String actionName) {
        if (record == null) {
            throw invalidParamException("切片记录不存在");
        }
        assertPlanReleasedForStart(hcPlanOrderMapper.selectByIdForUpdate(record.getPlanId()));
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(record.getPlanOperationId());
        validateSlittingOperationMutable(operation, actionName);
        HcAdhesiveReportDO sourceReport = record.getSourceAdhesiveReportId() == null
                ? null
                : hcAdhesiveReportMapper.selectById(record.getSourceAdhesiveReportId());
        validateSlittingSourceMutable(sourceReport, actionName);
    }

    private void validateSlittingSampleAbnormalUnlocked(HcAdhesiveReportDO sourceReport, String actionName) {
        if (sourceReport == null) {
            return;
        }
        HcGrindingSecondDetailDO sourceDetail = sourceReport.getSourceGrindingSecondDetailId() == null
                ? null : hcGrindingSecondDetailMapper.selectById(sourceReport.getSourceGrindingSecondDetailId());
        String segmentBatchNo = normalizeSlittingSegmentBatchNo(resolveSlittingSegmentBatchNo(sourceReport, sourceDetail));
        Long tenantId = firstNonNull(sourceReport.getTenantId(), TenantContextHolder.getTenantId());
        for (SlittingSampleAbnormalLockCandidate candidate
                : buildSlittingSampleAbnormalLockCandidates(segmentBatchNo)) {
            QmsSampleAbnormalLockDO lock = qmsSampleAbnormalLockMapper.selectLatestEffectiveLocked(
                    candidate.sourceProcessCode(), candidate.objectType(), candidate.objectNo(), tenantId);
            if (lock != null) {
                throw invalidParamException(buildSlittingSampleAbnormalLockMessage(lock, candidate, actionName));
            }
        }
    }

    private List<SlittingSampleAbnormalLockCandidate> buildSlittingSampleAbnormalLockCandidates(
            String segmentBatchNo) {
        List<SlittingSampleAbnormalLockCandidate> candidates = new ArrayList<>();
        Set<String> seen = new LinkedHashSet<>();
        // 湿法、二磨留样异常后移到裁切报检/完工门禁；粘胶1仍在分切拦截。
        addSlittingSampleAbnormalLockCandidate(candidates, seen, SAMPLE_ABNORMAL_PROCESS_ADHESIVE1,
                SAMPLE_ABNORMAL_OBJECT_SEGMENT, segmentBatchNo, "分段", "粘胶1");
        return candidates;
    }

    private void addSlittingSampleAbnormalLockCandidate(List<SlittingSampleAbnormalLockCandidate> candidates,
                                                       Set<String> seen, String sourceProcessCode, String objectType,
                                                       String objectNo, String objectLabel, String processName) {
        String normalizedObjectNo = normalizeSlittingSegmentBatchNo(objectNo);
        if (StrUtil.isBlank(sourceProcessCode) || StrUtil.isBlank(objectType) || StrUtil.isBlank(normalizedObjectNo)) {
            return;
        }
        String key = sourceProcessCode + "|" + objectType + "|" + normalizedObjectNo;
        if (!seen.add(key)) {
            return;
        }
        candidates.add(new SlittingSampleAbnormalLockCandidate(sourceProcessCode, objectType, normalizedObjectNo,
                objectLabel, processName));
    }

    private String buildSlittingSampleAbnormalLockMessage(QmsSampleAbnormalLockDO lock,
                                                          SlittingSampleAbnormalLockCandidate candidate,
                                                          String actionName) {
        if (StrUtil.isNotBlank(lock.getLockReason())) {
            return lock.getLockReason();
        }
        String objectType = firstNotBlank(lock.getObjectType(), candidate.objectType());
        String objectLabel = SAMPLE_ABNORMAL_OBJECT_MOTHER_ROLL.equalsIgnoreCase(objectType) ? "母卷" : candidate.objectLabel();
        String objectNo = firstNotBlank(lock.getObjectNo(), candidate.objectNo());
        String processName = firstNotBlank(lock.getSourceProcessName(), candidate.processName());
        String timeText = lock.getAbnormalFeedbackTime() == null ? "-" : formatDateTimeWithSeconds(lock.getAbnormalFeedbackTime());
        return "当前" + objectLabel + " " + objectNo + " 因" + timeText + "，" + processName
                + " 留样送检NG异常，锁定不允许继续" + actionName + "，等待复检确认后继续。";
    }

    private void validateSlittingSlicePrintable(HcSlittingSliceRecordDO record) {
        if (record == null) {
            throw invalidParamException("切片记录不存在");
        }
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(record.getPlanOperationId());
        if (operation == null) {
            throw invalidParamException("计划工序不存在");
        }
        String operationStatus = StrUtil.trimToEmpty(operation.getOperationStatus()).toUpperCase();
        if (OP_STATUS_PAUSED.equals(operationStatus)) {
            throw invalidParamException("当前分切工序已暂停，请等待生产计划复工后再打印流转单");
        }
        if (OP_STATUS_CANCELLED.equals(operationStatus) || "CANCELED".equals(operationStatus)) {
            throw invalidParamException("当前分切工序已作废取消，不能打印流转单");
        }
    }

    private HcPlanOrderOperationDO validatePressSlotOperation(HcPlanOrderDO planOrder, Long planOperationId) {
        if (planOrder == null) {
            throw invalidParamException("生产计划不存在");
        }
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(planOperationId);
        if (operation == null || !Objects.equals(operation.getPlanId(), planOrder.getId())) {
            throw invalidParamException("计划工序不存在");
        }
        String opCode = StrUtil.trimToEmpty(operation.getOpCode());
        String opName = StrUtil.trimToEmpty(operation.getOpName());
        if (!"OP-PRESS-SLOT".equalsIgnoreCase(opCode) && !opName.contains("压槽")) {
            throw invalidParamException("当前仅允许压槽工序使用该功能");
        }
        return operation;
    }

    private HcPlanOrderOperationDO getPressSlotOperation(Long planOperationId) {
        if (planOperationId == null) {
            throw invalidParamException("计划工序ID不能为空");
        }
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(planOperationId);
        if (operation == null) {
            throw invalidParamException("计划工序不存在");
        }
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(operation.getPlanId());
        return validatePressSlotOperation(planOrder, planOperationId);
    }

    private HcPlanOrderOperationDO getAdhesive2Operation(Long planOperationId) {
        if (planOperationId == null) {
            throw invalidParamException("计划工序ID不能为空");
        }
        HcPlanOrderOperationDO operation = hcPlanOrderOperationMapper.selectById(planOperationId);
        if (operation == null) {
            throw invalidParamException("计划工序不存在");
        }
        HcPlanOrderDO planOrder = hcPlanOrderMapper.selectById(operation.getPlanId());
        return validateAdhesive2Operation(planOrder, planOperationId);
    }

    private String normalizePressSlotConsumableType(String consumableType) {
        String type = StrUtil.trimToEmpty(consumableType).toUpperCase();
        if (AUXILIARY_CATEGORY_PRESS_ROLLER.equals(type) || "ROLLER".equals(type) || "压辊".equals(consumableType)) {
            return AUXILIARY_CATEGORY_PRESS_ROLLER;
        }
        if (AUXILIARY_CATEGORY_BEARING.equals(type) || "轴承".equals(consumableType)) {
            return AUXILIARY_CATEGORY_BEARING;
        }
        throw invalidParamException("压槽耗材类型只允许压辊或轴承");
    }

    private int resolvePressSlotInitialUseCount(Integer initialUseCount) {
        int value = initialUseCount == null ? 0 : initialUseCount;
        if (value < 0) {
            throw invalidParamException("初始化片数不能小于0");
        }
        return value;
    }

