    private String normalizePressSlotConsumableMaterialKeyword(String type, String keyword) {
        String text = StrUtil.trimToEmpty(keyword);
        if (StrUtil.isBlank(text)) {
            return "";
        }
        String upperText = text.toUpperCase();
        if (AUXILIARY_CATEGORY_BEARING.equals(type) && (text.contains("轴承") || upperText.contains("BEARING"))) {
            return "";
        }
        if (AUXILIARY_CATEGORY_PRESS_ROLLER.equals(type)
                && (text.contains("压槽辊") || text.contains("压辊") || text.contains("压槽"))) {
            return "";
        }
        return text;
    }

    private HcPressSlotConsumableRespVO buildPressSlotConsumableResp(HcPlanOrderOperationDO operation,
                                                                    Long equipmentId,
                                                                    HcPressSlotSpareDO state,
                                                                    String type) {
        if (state == null) {
            HcPressSlotConsumableRespVO resp = buildEmptyPressSlotConsumableResp(operation, type,
                    getAccessoryCategoryName(type) + "未挂接，请先更换");
            resp.setEquipmentId(equipmentId);
            return resp;
        }
        HcPressSlotConsumableRespVO resp = new HcPressSlotConsumableRespVO();
        resp.setStateId(state.getId());
        resp.setEquipmentId(state.getEquipmentId());
        resp.setEquipmentCode(state.getEquipmentCode());
        resp.setEquipmentName(state.getEquipmentName());
        resp.setWorkCenterId(state.getWorkCenterId());
        resp.setWorkCenterCode(state.getWorkCenterCode());
        resp.setWorkCenterName(state.getWorkCenterName());
        resp.setProcessCode(PROCESS_CODE_PRESS_SLOT);
        resp.setProcessName(firstNotBlank(operation.getOpName(), "压槽"));
        resp.setConsumableType(type);
        resp.setConsumableTypeName(getAccessoryCategoryName(type));
        resp.setMaterialCode(state.getMaterialCode());
        resp.setMaterialName(state.getMaterialName());
        resp.setBatchNo(state.getBatchNo());
        resp.setOnlineQuantity(zeroIfNull(state.getOnlineQuantity()));
        resp.setAvailableCount(zeroIfNull(state.getAvailableQuantity()));
        int useCount = state.getUseCount() == null ? 0 : state.getUseCount();
        int limitCount = resolvePressSlotConsumableLimitCount(type, state);
        int limitDays = resolvePressSlotConsumableLimitDays(type, state);
        LocalDateTime baseTime = resolvePressSlotConsumableBaseTime(type, state);
        int useDays = calculateUseDays(baseTime);
        resp.setUseCount(useCount);
        resp.setLimitCount(limitCount);
        resp.setLimitDays(limitDays);
        resp.setUseDays(useDays);
        if (AUXILIARY_CATEGORY_PRESS_ROLLER.equals(type)) {
            resp.setLastCleanTime(resolvePressSlotRollerLastCleanTime(state));
        }
        boolean blocked = isPressSlotConsumableBlocked(state);
        boolean warning = blocked || isPressSlotConsumableWarning(state);
        resp.setWarningFlag(warning ? 1 : 0);
        resp.setStatus(blocked
                ? (AUXILIARY_CATEGORY_PRESS_ROLLER.equals(type) ? "NEED_CLEAN" : "NEED_REPLACE")
                : StrUtil.blankToDefault(state.getStatus(), CONSUMABLE_STATUS_ACTIVE));
        resp.setMessage(buildPressSlotConsumableMessage(type, blocked, warning, useCount, limitCount, useDays, limitDays));
        resp.setLastOperatorId(state.getLastOperatorId());
        resp.setLastOperatorName(state.getLastOperatorName());
        resp.setLastReplaceTime(state.getLastReplaceTime());
        resp.setLastEventTime(state.getLastEventTime());
        return resp;
    }

    private boolean isPressSlotConsumableBlocked(HcPressSlotSpareDO state) {
        if (state == null) {
            return true;
        }
        String type = normalizePressSlotConsumableType(state.getSpareType());
        if (StrUtil.isBlank(state.getBatchNo())) {
            return true;
        }
        if (AUXILIARY_CATEGORY_BEARING.equals(type) && StrUtil.isBlank(state.getMaterialCode())) {
            return true;
        }
        int limitCount = resolvePressSlotConsumableLimitCount(type, state);
        int limitDays = resolvePressSlotConsumableLimitDays(type, state);
        int useCount = state.getUseCount() == null ? 0 : state.getUseCount();
        int useDays = calculateUseDays(resolvePressSlotConsumableBaseTime(type, state));
        return (limitCount > 0 && useCount >= limitCount) || (limitDays > 0 && useDays >= limitDays);
    }

    private boolean isPressSlotConsumableWarning(HcPressSlotSpareDO state) {
        if (state == null) {
            return true;
        }
        String type = normalizePressSlotConsumableType(state.getSpareType());
        int limitCount = resolvePressSlotConsumableLimitCount(type, state);
        int limitDays = resolvePressSlotConsumableLimitDays(type, state);
        int useCount = state.getUseCount() == null ? 0 : state.getUseCount();
        int useDays = calculateUseDays(resolvePressSlotConsumableBaseTime(type, state));
        return reachesPercent(useCount, limitCount, 95) || reachesPercent(useDays, limitDays, 95);
    }

    private boolean reachesPercent(int used, int limit, int percent) {
        return limit > 0 && used * 100 >= limit * percent;
    }

    private int resolvePressSlotConsumableLimitCount(String type, HcPressSlotSpareDO state) {
        Integer configured = state == null ? null : state.getLimitCount();
        if (configured != null && configured > 0) {
            return configured;
        }
        return AUXILIARY_CATEGORY_PRESS_ROLLER.equals(type)
                ? PRESS_SLOT_ROLLER_CLEAN_LIMIT_COUNT
                : PRESS_SLOT_BEARING_REPLACE_LIMIT_COUNT;
    }

    private int resolvePressSlotConsumableLimitDays(String type, HcPressSlotSpareDO state) {
        Integer configured = state == null ? null : state.getLimitDays();
        if (configured != null && configured > 0) {
            return configured;
        }
        return AUXILIARY_CATEGORY_PRESS_ROLLER.equals(type)
                ? PRESS_SLOT_ROLLER_CLEAN_LIMIT_DAYS
                : PRESS_SLOT_BEARING_REPLACE_LIMIT_DAYS;
    }

    private LocalDateTime resolvePressSlotConsumableBaseTime(String type, HcPressSlotSpareDO state) {
        if (state == null) {
            return null;
        }
        if (AUXILIARY_CATEGORY_PRESS_ROLLER.equals(type)) {
            LocalDateTime lastCleanTime = resolvePressSlotRollerLastCleanTime(state);
            if (lastCleanTime != null) {
                return lastCleanTime;
            }
        }
        return firstNonNullDateTime(state.getLastReplaceTime(), state.getLastEventTime(), state.getCreateTime());
    }

    private LocalDateTime resolvePressSlotRollerLastCleanTime(HcPressSlotSpareDO state) {
        if (state == null || state.getId() == null) {
            return null;
        }
        if (state.getLastCleanTime() != null) {
            return state.getLastCleanTime();
        }
        HcPressSlotSpareRecordDO cleanEvent = hcPressSlotSpareRecordMapper
                .selectLatestBySpareIdAndEventType(state.getId(), CONSUMABLE_EVENT_CLEAN_RESET);
        if (cleanEvent == null || cleanEvent.getEventTime() == null) {
            return null;
        }
        LocalDateTime lastReplaceTime = state.getLastReplaceTime();
        if (lastReplaceTime != null && cleanEvent.getEventTime().isBefore(lastReplaceTime)) {
            return null;
        }
        return cleanEvent.getEventTime();
    }

    private int calculateUseDays(LocalDateTime baseTime) {
        if (baseTime == null) {
            return 0;
        }
        long days = ChronoUnit.DAYS.between(baseTime.toLocalDate(), LocalDate.now());
        return (int) Math.max(days, 0);
    }

    private String buildPressSlotConsumableMessage(String type, boolean blocked, boolean warning, int useCount, int limitCount, int useDays, int limitDays) {
        String name = getAccessoryCategoryName(type);
        if (!warning) {
            return name + "状态正常";
        }
        if (!blocked) {
            return name + "接近寿命阈值：累计" + useCount + "/" + limitCount + "片，使用" + useDays + "/" + limitDays + "天";
        }
        if (AUXILIARY_CATEGORY_PRESS_ROLLER.equals(type)) {
            return name + "已达到清洗上限：累计" + useCount + "/" + limitCount + "片，使用" + useDays + "/" + limitDays + "天，请先清洗复位";
        }
        return name + "已达到更换上限：累计" + useCount + "/" + limitCount + "片，使用" + useDays + "/" + limitDays + "天，请先更换";
    }

    private void validatePressSlotConsumableStock(HcAdhesiveGlueBoardStockDO stock, String type, BigDecimal quantity) {
        String stockType = StrUtil.blankToDefault(stock.getAccessoryCategory(), "");
        if (!type.equalsIgnoreCase(stockType)) {
            throw invalidParamException("该辅料批次分类为" + getAccessoryCategoryName(stockType) + "，不能作为" + getAccessoryCategoryName(type) + "更换");
        }
        String stockMeasureMode = normalizeStockMeasureMode(stock.getStockMeasureMode(), type);
        if (!STOCK_MEASURE_COUNT.equals(stockMeasureMode)) {
            throw invalidParamException(getAccessoryCategoryName(type) + "必须按数量管理，请检查辅料边库计量口径");
        }
        if (GLUE_BOARD_STOCK_LOCKED.equalsIgnoreCase(StrUtil.blankToDefault(stock.getStockStatus(), ""))) {
            throw invalidParamException("该辅料批次已锁定，不能更换");
        }
        BigDecimal availableCount = zeroIfNull(stock.getAvailableCount());
        if (availableCount.compareTo(zeroIfNull(quantity)) < 0) {
            throw invalidParamException(getAccessoryCategoryName(type) + "边库可用数量不足，当前可用" + formatDecimal(availableCount) + "个");
        }
    }

    private Map<String, HcPressSlotSpareDO> validatePressSlotConsumablesReady(HcPlanOrderOperationDO operation) {
        if (operation.getEquipmentId() == null) {
            throw invalidParamException("当前压槽工序未绑定设备，不能压槽报工");
        }
        Map<String, HcPressSlotSpareDO> result = new LinkedHashMap<>();
        for (String type : List.of(AUXILIARY_CATEGORY_PRESS_ROLLER, AUXILIARY_CATEGORY_BEARING)) {
            HcPressSlotSpareDO state = hcPressSlotSpareMapper.selectOneByEquipmentAndType(operation.getEquipmentId(), type);
            if (state == null || StrUtil.isBlank(state.getBatchNo())) {
                throw invalidParamException(getAccessoryCategoryName(type) + "未挂接，请先在当前看板选择 ERP 相似物料完成挂接");
            }
            if (AUXILIARY_CATEGORY_BEARING.equals(type) && StrUtil.isBlank(state.getMaterialCode())) {
                throw invalidParamException("轴承料号未维护，请先在当前看板选择 ERP 相似物料完成挂接");
            }
            if (isPressSlotConsumableBlocked(state)) {
                throw invalidParamException(AUXILIARY_CATEGORY_PRESS_ROLLER.equals(type)
                        ? "压槽辊已达到清洗上限，请先清洗复位"
                        : "轴承已达到更换上限，请先更换");
            }
            result.put(type, state);
        }
        return result;
    }

    private int toPositiveIntCount(BigDecimal quantity, String label) {
        BigDecimal normalized = zeroIfNull(quantity);
        if (normalized.compareTo(BigDecimal.ZERO) <= 0) {
            throw invalidParamException(label + "必须大于0");
        }
        return normalized.setScale(0, java.math.RoundingMode.CEILING).intValue();
    }

    private void deductPressSlotConsumableStock(HcAdhesiveGlueBoardStockDO stock, BigDecimal quantity) {
        BigDecimal nextAvailableCount = zeroIfNull(stock.getAvailableCount()).subtract(zeroIfNull(quantity));
        BigDecimal nextUsedCount = zeroIfNull(stock.getUsedCount()).add(zeroIfNull(quantity));
        if (nextAvailableCount.compareTo(BigDecimal.ZERO) < 0) {
            throw invalidParamException("辅料边库可用数量不足");
        }
        updateGlueBoardStockBalance(stock.getId(), stock.getAvailableStartPosition(), stock.getAvailableLength(),
                stock.getUsedLength(), nextAvailableCount, nextUsedCount);
    }

    private Map<String, Integer> increasePressSlotConsumablesOnConfirm(HcPressSlotReportDO report,
                                                                       HcPlanOrderOperationDO operation,
                                                                       String operatorName,
                                                                       LocalDateTime eventTime) {
        int useCount = toPositiveIntCount(firstNonNullDecimal(report.getInputLength(), report.getOutputLength(), BigDecimal.ONE), "压槽报工数量");
        Map<String, Integer> afterCounts = new LinkedHashMap<>();
        for (String type : List.of(AUXILIARY_CATEGORY_PRESS_ROLLER, AUXILIARY_CATEGORY_BEARING)) {
            HcPressSlotSpareDO state = hcPressSlotSpareMapper.selectOneByEquipmentAndType(operation.getEquipmentId(), type);
            if (state == null || StrUtil.isBlank(state.getBatchNo())) {
                throw invalidParamException(getAccessoryCategoryName(type) + "未挂接，请先更换");
            }
            int beforeCount = state.getUseCount() == null ? 0 : state.getUseCount();
            int afterCount = beforeCount + useCount;
            state.setUseCount(afterCount);
            state.setWarningFlag(isPressSlotConsumableWarning(state) ? 1 : 0);
            state.setLastOperatorId(SecurityFrameworkUtils.getLoginUserId());
            state.setLastOperatorName(operatorName);
            state.setLastEventTime(eventTime);
            hcPressSlotSpareMapper.updateById(state);
            hcPressSlotSpareRecordMapper.insert(HcPressSlotSpareRecordDO.builder()
                    .tenantId(operation.getTenantId())
                    .spareId(state.getId())
                    .equipmentId(state.getEquipmentId())
                    .equipmentCode(state.getEquipmentCode())
                    .equipmentName(state.getEquipmentName())
                    .workCenterId(state.getWorkCenterId())
                    .workCenterCode(state.getWorkCenterCode())
                    .workCenterName(state.getWorkCenterName())
                    .spareType(type)
                    .eventType(CONSUMABLE_EVENT_USE)
                    .planId(report.getPlanId())
                    .planNo(report.getPlanNo())
                    .planOperationId(operation.getId())
                    .operationCode(operation.getOpCode())
                    .operationName(operation.getOpName())
                    .bizType("PRESS_SLOT_REPORT")
                    .bizId(report.getId())
                    .beforeMaterialCode(state.getMaterialCode())
                    .beforeBatchNo(state.getBatchNo())
                    .afterMaterialCode(state.getMaterialCode())
                    .afterBatchNo(state.getBatchNo())
                    .beforeUseCount(beforeCount)
                    .afterUseCount(afterCount)
                    .changeUseCount(useCount)
                    .onlineQuantity(state.getOnlineQuantity())
                    .offlineQuantity(BigDecimal.ZERO)
                    .finalUseCount(afterCount)
                    .beforeAvailableQuantity(zeroIfNull(state.getAvailableQuantity()))
                    .afterAvailableQuantity(zeroIfNull(state.getAvailableQuantity()))
                    .changeQuantity(BigDecimal.ZERO)
                    .operatorId(SecurityFrameworkUtils.getLoginUserId())
                    .operatorName(operatorName)
                    .eventTime(eventTime)
                    .remark("压槽扫码确认累计")
                    .build());
            afterCounts.put(type, afterCount);
        }
        return afterCounts;
    }

