    private String getPressSlotInspectionStatusName(String status) {
        return switch (StrUtil.blankToDefault(status, "DRAFT")) {
            case "DRAFT" -> "草稿";
            case "QUALIFIED", "ABNORMAL" -> "已检";
            case "CANCELLED" -> "已取消";
            default -> "待检";
        };
    }

    private LocalDateTime normalizeValidLocalDateTime(LocalDateTime value, LocalDateTime fallback) {
        if (value == null || value.getYear() < 2000) {
            return fallback == null ? LocalDateTime.now() : fallback;
        }
        return value;
    }

    private boolean isPressSlotMiddleLedgerType(String reportType) {
        return "FRONT".equalsIgnoreCase(reportType)
                || "MIDDLE".equalsIgnoreCase(reportType)
                || "END".equalsIgnoreCase(reportType);
    }

    private String resolvePressSlotReportType(HcPressSlotReportDO report) {
        Map<String, Object> extra = parseRoughExtraMap(report == null ? null : report.getExtraJson());
        Object reportType = extra.get("reportType");
        return reportType == null ? "" : String.valueOf(reportType);
    }

    private boolean isPressSlotProcessCheckReport(HcPressSlotReportDO report) {
        Map<String, Object> extra = parseRoughExtraMap(report == null ? null : report.getExtraJson());
        return INSPECTION_SCENE_PROCESS_CHECK.equalsIgnoreCase(StrUtil.trimToEmpty(toStringValue(extra.get("reportType"))))
                || INSPECTION_SCENE_PROCESS_CHECK.equalsIgnoreCase(StrUtil.trimToEmpty(toStringValue(extra.get("inspectionScene"))))
                || INSPECTION_SCENE_PROCESS_CHECK.equalsIgnoreCase(StrUtil.trimToEmpty(toStringValue(extra.get("inspectionSampleCategory"))));
    }

    private void validateAdhesive2SourceNotPressSlotProcessCheck(HcPressSlotReportDO source) {
        if (isPressSlotProcessCheckReport(source)) {
            throw invalidParamException("压槽过程加检片不进入粘胶2/裁切工序");
        }
    }

    private String getPressSlotReportTypeName(String reportType) {
        return switch (StrUtil.blankToDefault(reportType, "PRODUCT")) {
            case "CHANGEOVER" -> "首检";
            case "FRONT" -> "中间品-前段";
            case "MIDDLE" -> "中间品-中段";
            case "END" -> "中间品-后段";
            case "PROCESS_CHECK" -> "过程加检";
            default -> "成品加工";
        };
    }

