    private int writeIntermediateThicknessDetailTable(Sheet sheet,
                                                      int rowIndex,
                                                      LocalDate recordDate,
                                                      List<IntermediateExportDetail> details,
                                                      String sectionTitle,
                                                      String emptyText,
                                                      String thicknessStandard,
                                                      boolean includeWidthColumn,
                                                      CellStyle sectionStyle,
                                                      CellStyle headerStyle,
                                                      CellStyle detailStyle) {
        int lastCol = includeWidthColumn ? 14 : 11;
        Row section = sheet.createRow(rowIndex++);
        mergeRegionIfAbsent(sheet, section.getRowNum(), section.getRowNum(), 0, lastCol);
        setExcelCell(section, 0, sectionTitle, sectionStyle);

        Row row = sheet.createRow(rowIndex++);
        if (includeWidthColumn) {
            String thicknessSuffix = StrUtil.isBlank(thicknessStandard) ? "" : "(" + thicknessStandard + ")";
            String[] headers = {"生产日期", "片号", "类型", "宽幅/mm", "厚度1/mm" + thicknessSuffix, "厚度2/mm" + thicknessSuffix,
                    "厚度3/mm" + thicknessSuffix, "厚度4/mm" + thicknessSuffix, "厚度5/mm" + thicknessSuffix,
                    "厚度6/mm" + thicknessSuffix, "厚度7/mm" + thicknessSuffix, "厚度8/mm" + thicknessSuffix,
                    "厚度9/mm" + thicknessSuffix, "厚度10/mm" + thicknessSuffix, "备注"};
            for (int i = 0; i < headers.length; i++) {
                setExcelCell(row, i, headers[i], headerStyle);
            }
        } else {
            setExcelCell(row, 0, "片号", headerStyle);
            for (int i = 1; i <= 10; i++) {
                setExcelCell(row, i, "厚度/㎜\n(" + thicknessStandard + "mm)", headerStyle);
            }
            setExcelCell(row, 11, "备注", headerStyle);
        }

        List<IntermediateExportDetail> effectiveDetails = details == null ? Collections.emptyList() : details;
        for (IntermediateExportDetail detail : effectiveDetails) {
            row = sheet.createRow(rowIndex++);
            if (includeWidthColumn) {
                setExcelCell(row, 0, recordDate == null ? "" : recordDate.toString(), detailStyle);
                setExcelCell(row, 1, firstNotBlank(detail.sliceBatchNo(), ""), detailStyle);
                setExcelCell(row, 2, firstNotBlank(detail.samplePositionName(),
                        getPressSlotIntermediatePositionName(detail.samplePosition())), detailStyle);
                setExcelCell(row, 3, toExcelText(detail.widthMm()), detailStyle);
                setExcelCell(row, 4, toExcelText(detail.thickness1()), detailStyle);
                setExcelCell(row, 5, toExcelText(detail.thickness2()), detailStyle);
                setExcelCell(row, 6, toExcelText(detail.thickness3()), detailStyle);
                setExcelCell(row, 7, toExcelText(detail.thickness4()), detailStyle);
                setExcelCell(row, 8, toExcelText(detail.thickness5()), detailStyle);
                setExcelCell(row, 9, toExcelText(detail.thickness6()), detailStyle);
                setExcelCell(row, 10, toExcelText(detail.thickness7()), detailStyle);
                setExcelCell(row, 11, toExcelText(detail.thickness8()), detailStyle);
                setExcelCell(row, 12, toExcelText(detail.thickness9()), detailStyle);
                setExcelCell(row, 13, toExcelText(detail.thickness10()), detailStyle);
                setExcelCell(row, 14, firstNotBlank(detail.remark(), ""), detailStyle);
            } else {
                String samplePositionName = firstNotBlank(detail.samplePositionName(),
                        getPressSlotIntermediatePositionName(detail.samplePosition()));
                setExcelCell(row, 0, samplePositionName + "：" + firstNotBlank(detail.sliceBatchNo(), ""), detailStyle);
                setExcelCell(row, 1, toExcelText(detail.thickness1()), detailStyle);
                setExcelCell(row, 2, toExcelText(detail.thickness2()), detailStyle);
                setExcelCell(row, 3, toExcelText(detail.thickness3()), detailStyle);
                setExcelCell(row, 4, toExcelText(detail.thickness4()), detailStyle);
                setExcelCell(row, 5, toExcelText(detail.thickness5()), detailStyle);
                setExcelCell(row, 6, toExcelText(detail.thickness6()), detailStyle);
                setExcelCell(row, 7, toExcelText(detail.thickness7()), detailStyle);
                setExcelCell(row, 8, toExcelText(detail.thickness8()), detailStyle);
                setExcelCell(row, 9, toExcelText(detail.thickness9()), detailStyle);
                setExcelCell(row, 10, toExcelText(detail.thickness10()), detailStyle);
                setExcelCell(row, 11, firstNotBlank(detail.remark(), ""), detailStyle);
            }
        }
        if (effectiveDetails.isEmpty()) {
            row = sheet.createRow(rowIndex++);
            mergeRegionIfAbsent(sheet, row.getRowNum(), row.getRowNum(), 0, lastCol);
            setExcelCell(row, 0, emptyText, detailStyle);
        }
        return rowIndex;
    }

