    private int findAdhesive2IntermediateHeaderRow(Sheet sheet, DataFormatter formatter) {
        for (int i = sheet.getFirstRowNum(); i <= sheet.getLastRowNum(); i++) {
            Row row = sheet.getRow(i);
            if (row == null) {
                continue;
            }
            boolean hasSliceNo = false;
            boolean hasThickness = false;
            for (int col = 0; col < Math.max(row.getLastCellNum(), 0); col++) {
                String text = normalizeExcelHeaderText(readCellString(row, col, formatter));
                if (text.contains("片号")) {
                    hasSliceNo = true;
                }
                if (text.contains("厚度")) {
                    hasThickness = true;
                }
            }
            if (hasSliceNo && hasThickness) {
                return i;
            }
        }
        return -1;
    }

    private String normalizeExcelHeaderText(String text) {
        return StrUtil.trimToEmpty(text)
                .replace("：", "")
                .replace(":", "")
                .replace("（", "(")
                .replace("）", ")")
                .replace(" ", "")
                .replace("\n", "")
                .replace("\r", "");
    }

    private LocalDateTime parseIntermediateRecordDateTime(Sheet sheet, DataFormatter formatter) {
        String value = readAdhesive2IntermediateHeaderValue(sheet, "生产日期", formatter);
        LocalDateTime parsed = parseIntermediateRecordDateTime(value);
        if (parsed != null) {
            return parsed;
        }
        for (int i = sheet.getFirstRowNum(); i <= Math.min(sheet.getLastRowNum(), sheet.getFirstRowNum() + 10); i++) {
            Row row = sheet.getRow(i);
            if (row == null) {
                continue;
            }
            for (int col = 0; col < Math.max(row.getLastCellNum(), 0); col++) {
                String text = readCellString(row, col, formatter);
                if (StrUtil.contains(text, "生产日期")) {
                    parsed = parseIntermediateRecordDateTime(text);
                    if (parsed != null) {
                        return parsed;
                    }
                }
            }
        }
        return null;
    }

    private LocalDateTime parseIntermediateRecordDateTime(String text) {
        if (StrUtil.isBlank(text)) {
            return null;
        }
        Matcher dateTimeMatcher = Pattern.compile("(\\d{4})\\s*(?:[-/]|年)\\s*(\\d{1,2})\\s*(?:[-/]|月)\\s*(\\d{1,2})\\s*日?\\s*[T ]\\s*(\\d{1,2}):(\\d{2})(?::(\\d{2}))?")
                .matcher(text);
        if (dateTimeMatcher.find()) {
            try {
                return LocalDateTime.of(
                        Integer.parseInt(dateTimeMatcher.group(1)),
                        Integer.parseInt(dateTimeMatcher.group(2)),
                        Integer.parseInt(dateTimeMatcher.group(3)),
                        Integer.parseInt(dateTimeMatcher.group(4)),
                        Integer.parseInt(dateTimeMatcher.group(5)),
                        dateTimeMatcher.group(6) == null ? 0 : Integer.parseInt(dateTimeMatcher.group(6)));
            } catch (RuntimeException ignored) {
                return null;
            }
        }
        Matcher dateMatcher = Pattern.compile("(\\d{4})\\s*(?:[-/]|年)\\s*(\\d{1,2})\\s*(?:[-/]|月)\\s*(\\d{1,2})\\s*日?")
                .matcher(text);
        if (dateMatcher.find()) {
            try {
                return LocalDate.of(
                        Integer.parseInt(dateMatcher.group(1)),
                        Integer.parseInt(dateMatcher.group(2)),
                        Integer.parseInt(dateMatcher.group(3))).atStartOfDay();
            } catch (RuntimeException ignored) {
                return null;
            }
        }
        LocalDate monthDay = parseAdhesive2ChineseMonthDay(text);
        return monthDay == null ? null : monthDay.atStartOfDay();
    }

    private LocalDate parseAdhesive2ChineseMonthDay(String text) {
        if (StrUtil.isBlank(text)) {
            return null;
        }
        Matcher matcher = Pattern.compile("(\\d{1,2})\\s*月\\s*(\\d{1,2})\\s*日").matcher(text);
        if (!matcher.find()) {
            return null;
        }
        try {
            int month = Integer.parseInt(matcher.group(1));
            int day = Integer.parseInt(matcher.group(2));
            return LocalDate.of(LocalDate.now().getYear(), month, day);
        } catch (Exception ignored) {
            return null;
        }
    }

    private String readAdhesive2IntermediateHeaderValue(Sheet sheet, String label, DataFormatter formatter) {
        for (int i = sheet.getFirstRowNum(); i <= Math.min(sheet.getLastRowNum(), sheet.getFirstRowNum() + 10); i++) {
            Row row = sheet.getRow(i);
            if (row == null) {
                continue;
            }
            int lastCell = Math.max(row.getLastCellNum(), 0);
            for (int col = 0; col < lastCell; col++) {
                String text = readCellString(row, col, formatter);
                if (!matchesAdhesive2IntermediateHeaderLabel(text, label)) {
                    continue;
                }
                for (int nextCol = col + 1; nextCol < lastCell; nextCol++) {
                    String value = readCellString(row, nextCol, formatter);
                    if (StrUtil.isBlank(value)) {
                        continue;
                    }
                    if (isAdhesive2IntermediateHeaderLabel(value)) {
                        break;
                    }
                    return value;
                }
                return "";
            }
        }
        return "";
    }

    private boolean matchesAdhesive2IntermediateHeaderLabel(String text, String label) {
        String normalizedText = normalizeExcelHeaderText(text);
        String normalizedLabel = normalizeExcelHeaderText(label);
        if (StrUtil.isBlank(normalizedText) || StrUtil.isBlank(normalizedLabel)) {
            return false;
        }
        if (StrUtil.equals(normalizedText, normalizedLabel)) {
            return true;
        }
        if (Set.of("型号", "料号", "批号").contains(normalizedLabel)) {
            return false;
        }
        return normalizedText.contains(normalizedLabel);
    }

    private boolean isAdhesive2IntermediateHeaderLabel(String text) {
        String normalized = normalizeExcelHeaderText(text);
        return normalized.equals("型号")
                || normalized.equals("料号")
                || normalized.equals("批号")
                || normalized.contains("产品型号")
                || normalized.contains("产品批号")
                || normalized.contains("产品总数")
                || normalized.contains("宽幅")
                || normalized.contains("胶板型号")
                || normalized.contains("使用面粘性")
                || normalized.contains("生产日期")
                || normalized.contains("填写人")
                || normalized.contains("填写时间")
                || normalized.contains("担当")
                || normalized.contains("确认人")
                || normalized.contains("确认时间")
                || normalized.contains("确认");
    }

    private boolean isAdhesive2IntermediateStopRow(String firstCell) {
        String normalized = normalizeExcelHeaderText(firstCell);
        return normalized.contains("注")
                || normalized.contains("制定")
                || normalized.contains("修订")
                || normalized.contains("本资料");
    }

    private String stripAdhesive2IntermediateSliceNo(String firstCell) {
        String text = StrUtil.trimToEmpty(firstCell);
        text = text.replace("前段", "")
                .replace("中段", "")
                .replace("后段", "")
                .replace("首件", "")
                .replace("：", "")
                .replace(":", "")
                .trim();
        return text;
    }

    private String resolveAdhesive2IntermediatePosition(String firstCell, int detailIndex) {
        String text = StrUtil.trimToEmpty(firstCell);
        if (text.contains("前段")) {
            return "FRONT";
        }
        if (text.contains("中段")) {
            return "MIDDLE";
        }
        if (text.contains("后段")) {
            return "END";
        }
        return switch (detailIndex) {
            case 0 -> "FRONT";
            case 1 -> "MIDDLE";
            case 2 -> "END";
            default -> "ROW" + (detailIndex + 1);
        };
    }

    private void setAdhesive2IntermediateThickness(HcPressSlotIntermediateDetailReqVO detail,
                                                   List<BigDecimal> values) {
        detail.setThickness1(getDecimalAt(values, 0));
        detail.setThickness2(getDecimalAt(values, 1));
        detail.setThickness3(getDecimalAt(values, 2));
        detail.setThickness4(getDecimalAt(values, 3));
        detail.setThickness5(getDecimalAt(values, 4));
        detail.setThickness6(getDecimalAt(values, 5));
        detail.setThickness7(getDecimalAt(values, 6));
        detail.setThickness8(getDecimalAt(values, 7));
        detail.setThickness9(getDecimalAt(values, 8));
        detail.setThickness10(getDecimalAt(values, 9));
    }

    private BigDecimal getDecimalAt(List<BigDecimal> values, int index) {
        return values == null || values.size() <= index ? null : values.get(index);
    }

    private void writeAdhesive2IntermediateRecordSheet(Sheet sheet, List<HcAdhesive2IntermediateRecordDO> records) {
        Workbook workbook = sheet.getWorkbook();
        CellStyle titleStyle = adhesiveIntermediateCellStyle(workbook, true, HorizontalAlignment.CENTER, true, false);
        CellStyle sectionStyle = adhesiveIntermediateCellStyle(workbook, true, HorizontalAlignment.LEFT, true, true);
        CellStyle labelStyle = adhesiveIntermediateCellStyle(workbook, true, HorizontalAlignment.CENTER, true, true);
        CellStyle valueStyle = adhesiveIntermediateCellStyle(workbook, false, HorizontalAlignment.LEFT, true, false);
        CellStyle headerStyle = adhesiveIntermediateCellStyle(workbook, true, HorizontalAlignment.CENTER, true, true);
        CellStyle detailStyle = adhesiveIntermediateCellStyle(workbook, false, HorizontalAlignment.CENTER, true, false);
        for (int i = 0; i <= 11; i++) {
            sheet.setColumnWidth(i, i == 0 ? 24 * 256 : 18 * 256);
        }
        if (records == null || records.isEmpty()) {
            Row title = sheet.createRow(0);
            mergeRegionIfAbsent(sheet, 0, 0, 0, 11);
            setExcelCell(title, 0, "粘胶2中间品记录表", titleStyle);
            int rowIndex = 1;
            Row section = sheet.createRow(rowIndex++);
            mergeRegionIfAbsent(sheet, section.getRowNum(), section.getRowNum(), 0, 11);
            setExcelCell(section, 0, "主表信息", sectionStyle);
            rowIndex = writeIntermediateThicknessDetailTable(sheet, rowIndex, null, Collections.emptyList(),
                    "前段 / 中段 / 后段厚度测量",
                    "暂无前段 / 中段 / 后段厚度测量数据",
                    "1.500±0.050",
                    false,
                    sectionStyle,
                    headerStyle,
                    detailStyle);
            return;
        }
        int rowIndex = 0;
        for (HcAdhesive2IntermediateRecordDO record : records) {
            List<HcAdhesive2IntermediateDetailDO> details = hcAdhesive2IntermediateDetailMapper.selectListByRecordId(record.getId());
            rowIndex = writeAdhesive2IntermediateRecordBlock(sheet, rowIndex, record, details,
                    titleStyle, sectionStyle, labelStyle, valueStyle, headerStyle, detailStyle);
            rowIndex += 2;
        }
    }

    private int writeAdhesive2IntermediateRecordBlock(Sheet sheet,
                                                      int startRow,
                                                      HcAdhesive2IntermediateRecordDO record,
                                                      List<HcAdhesive2IntermediateDetailDO> details,
                                                      CellStyle titleStyle,
                                                      CellStyle sectionStyle,
                                                      CellStyle labelStyle,
                                                      CellStyle valueStyle,
                                                      CellStyle headerStyle,
                                                      CellStyle detailStyle) {
        Map<String, Object> extra = parseRoughExtraMap(record.getExtraJson());
        String glueBoardModel = firstNotBlank(record.getGlueBoardModel(), toStringValue(extra.get("glueBoardModel")));
        String glueBoardWidthMm = toStringValue(extra.get("glueBoardWidthMm"));
        String glueBoardAdhesionGf = toStringValue(extra.get("glueBoardAdhesionGf"));
        HcStationFormDO stationForm = resolveAdhesive2StationFormConfig(PRESS_SLOT_INTERMEDIATE_FORM_TYPE, record.getModelCode());
        Map<String, Object> schema = parsePressSlotStationFormSchema(stationForm);
        String formTitle = stationForm == null ? "粘胶2中间品记录表"
                : stripPressSlotDisplayName(firstNotBlank(resolveAdhesive2StationDisplayName(stationForm),
                stationForm.getFormName(), "粘胶2中间品记录表"));
        String thicknessStandard = firstNotBlank(
                toStringValue(schema.get("thicknessStandard")),
                toStringValue(schema.get("intermediateThicknessStandard")),
                ADHESIVE2_INTERMEDIATE_DEFAULT_THICKNESS_STANDARD);
        Row row = sheet.createRow(startRow);
        row.setHeightInPoints(24);
        mergeRegionIfAbsent(sheet, startRow, startRow, 0, 11);
        setExcelCell(row, 0, formTitle, titleStyle);

        int rowIndex = startRow + 1;
        row = sheet.createRow(rowIndex++);
        mergeRegionIfAbsent(sheet, row.getRowNum(), row.getRowNum(), 0, 11);
        setExcelCell(row, 0, "主表信息", sectionStyle);

        row = sheet.createRow(rowIndex++);
        setExcelCell(row, 0, "生产日期", labelStyle);
        mergeRegionIfAbsent(sheet, row.getRowNum(), row.getRowNum(), 1, 2);
        setExcelCell(row, 1, formatDateTimeWithSeconds(record.getRecordDate()), valueStyle);
        setExcelCell(row, 3, "型号", labelStyle);
        mergeRegionIfAbsent(sheet, row.getRowNum(), row.getRowNum(), 4, 5);
        setExcelCell(row, 4, firstNotBlank(record.getModelCode(), ""), valueStyle);
        setExcelCell(row, 6, "料号", labelStyle);
        mergeRegionIfAbsent(sheet, row.getRowNum(), row.getRowNum(), 7, 8);
        setExcelCell(row, 7, firstNotBlank(record.getMaterialCode(), ""), valueStyle);
        setExcelCell(row, 9, "批号", labelStyle);
        mergeRegionIfAbsent(sheet, row.getRowNum(), row.getRowNum(), 10, 11);
        setExcelCell(row, 10, firstNotBlank(record.getBatchNo(), ""), valueStyle);

        row = sheet.createRow(rowIndex++);
        setExcelCell(row, 0, "填写人", labelStyle);
        mergeRegionIfAbsent(sheet, row.getRowNum(), row.getRowNum(), 1, 2);
        setExcelCell(row, 1, firstNotBlank(record.getRecorderName(), ""), valueStyle);
        setExcelCell(row, 3, "填写时间", labelStyle);
        mergeRegionIfAbsent(sheet, row.getRowNum(), row.getRowNum(), 4, 5);
        setExcelCell(row, 4, formatDateTime(firstNotNullDateTime(record.getUpdateTime(), record.getCreateTime())), valueStyle);
        setExcelCell(row, 6, "确认人", labelStyle);
        mergeRegionIfAbsent(sheet, row.getRowNum(), row.getRowNum(), 7, 8);
        setExcelCell(row, 7, firstNotBlank(record.getConfirmerName(), ""), valueStyle);
        setExcelCell(row, 9, "确认时间", labelStyle);
        mergeRegionIfAbsent(sheet, row.getRowNum(), row.getRowNum(), 10, 11);
        setExcelCell(row, 10, "CONFIRMED".equalsIgnoreCase(record.getRecordStatus())
                ? formatDateTime(record.getUpdateTime()) : "", valueStyle);

        row = sheet.createRow(rowIndex++);
        setExcelCell(row, 0, "胶板型号", labelStyle);
        mergeRegionIfAbsent(sheet, row.getRowNum(), row.getRowNum(), 1, 3);
        setExcelCell(row, 1, glueBoardModel, valueStyle);
        setExcelCell(row, 4, "宽幅/MM", labelStyle);
        mergeRegionIfAbsent(sheet, row.getRowNum(), row.getRowNum(), 5, 7);
        setExcelCell(row, 5, glueBoardWidthMm, valueStyle);
        setExcelCell(row, 8, "使用面粘性/gf", labelStyle);
        mergeRegionIfAbsent(sheet, row.getRowNum(), row.getRowNum(), 9, 11);
        setExcelCell(row, 9, glueBoardAdhesionGf, valueStyle);

        rowIndex++;
        rowIndex = writeIntermediateThicknessDetailTable(sheet, rowIndex,
                record.getRecordDate() == null ? null : record.getRecordDate().toLocalDate(),
                toAdhesive2IntermediateExportDetails(details),
                "前段 / 中段 / 后段厚度测量",
                "暂无前段 / 中段 / 后段厚度测量数据",
                thicknessStandard,
                false,
                sectionStyle,
                headerStyle,
                detailStyle);
        return rowIndex;
    }

