    private HcPressSlotProcessParamRespVO.Item toPressSlotProcessParamItem(
            HcPressSlotProcessParamSaveReqVO.Item source,
            int index,
            HcPlanOrderDO planOrder,
            HcPlanOrderOperationDO operation,
            String motherBatchNo,
            LocalDate recordDate) {
        HcPressSlotProcessParamRespVO.Item row = new HcPressSlotProcessParamRespVO.Item();
        row.setSeq(source.getSeq() == null ? index : source.getSeq());
        row.setReportDate(firstNotNullDate(source.getReportDate(), recordDate));
        row.setModelCode(firstNotBlank(source.getModelCode(), planOrder.getModelCode(), planOrder.getModelName()));
        row.setProductionBatchNo(source.getProductionBatchNo());
        row.setMotherBatchNo(normalizePressSlotMiddleBatchNo(firstNotBlank(source.getMotherBatchNo(), motherBatchNo)));
        row.setItemCategory(source.getItemCategory());
        row.setItemName(source.getItemName());
        row.setStandardValue(source.getStandardValue());
        row.setActualValue(source.getActualValue());
        row.setCheckResult(source.getCheckResult());
        row.setAbnormalRemark(source.getAbnormalRemark());
        row.setValueMode(source.getValueMode());
        row.setDualLabel1(source.getDualLabel1());
        row.setDualLabel2(source.getDualLabel2());
        row.setRequiredFlag(source.getRequiredFlag());
        row.setWidthM(source.getWidthM());
        row.setThickness(source.getThickness());
        row.setEnvironmentTemperature(source.getEnvironmentTemperature());
        row.setEnvironmentHumidity(source.getEnvironmentHumidity());
        row.setPressSlotOrder(source.getPressSlotOrder());
        row.setPressSlotSpeed(source.getPressSlotSpeed());
        row.setPressSlotSize(source.getPressSlotSize());
        row.setRollerGap(source.getRollerGap());
        row.setSetTemperature(source.getSetTemperature());
        row.setMeasuredTemperature1(source.getMeasuredTemperature1());
        row.setMeasuredTemperature2(source.getMeasuredTemperature2());
        row.setMeasuredTemperature3(source.getMeasuredTemperature3());
        row.setMeasuredTemperature4(source.getMeasuredTemperature4());
        row.setMeasuredTemperature5(source.getMeasuredTemperature5());
        row.setStartTime(source.getStartTime());
        row.setEndTime(source.getEndTime());
        row.setRecorderName(firstNotBlank(source.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统"));
        row.setConfirmerName(source.getConfirmerName());
        row.setRemark(source.getRemark());
        row.setSourceReportId(source.getSourceReportId());
        if (row.getSourceReportId() == null) {
            HcPressSlotReportDO report = hcPressSlotReportMapper.selectByProductionBatchNo(row.getProductionBatchNo());
            if (report != null && Objects.equals(report.getPlanOperationId(), operation.getId())) {
                row.setSourceReportId(report.getId());
            }
        }
        return row;
    }

    private HcPressSlotProcessParamRespVO buildPressSlotProcessParamResp(HcProcessFormRecordDO record) {
        HcPressSlotProcessParamRespVO resp = new HcPressSlotProcessParamRespVO();
        Map<String, Object> header = parseRoughExtraMap(record.getHeaderDataJson());
        Map<String, Object> context = parseRoughExtraMap(record.getContextJson());
        List<HcPressSlotProcessParamRespVO.Item> items = buildPressSlotProcessParamItems(record);
        resp.setId(record.getId());
        resp.setTemplateId(record.getTemplateId());
        // 历史 Map 中的 LocalDate 曾被序列化为数组，响应统一使用业务日期字符串。
        if ("PRESS_SLOT".equalsIgnoreCase(record.getProcessCode())
                && PRESS_SLOT_PRODUCTION_CHECK_FORM_TYPE.equalsIgnoreCase(record.getFormType())
                && record.getRecordDate() != null) {
            header.put("productionDate", record.getRecordDate().toString());
            header.put("recordDate", record.getRecordDate().toString());
        }
        resp.setHeaderData(header);
        resp.setFaiId(context.get("faiId") == null ? null : Long.valueOf(context.get("faiId").toString()));
        resp.setRuntimeSchema(context.get("runtimeSchema") instanceof Map<?, ?> schema ? (Map<String, Object>) schema : null);
        resp.setPlanId(record.getPlanId());
        resp.setPlanNo(record.getPlanNo());
        resp.setPlanOperationId(record.getPlanOperationId());
        if (PROCESS_CODE_ADHESIVE2.equalsIgnoreCase(record.getProcessCode())) {
            resp.setChangeoverInstructionId(getAdhesive2InspectionChangeoverId(record));
        }
        resp.setFormName(firstNotBlank(record.getTemplateName(),
                PRESS_SLOT_PRODUCTION_CHECK_FORM_TYPE.equalsIgnoreCase(record.getFormType())
                        ? "压槽生产点检表" : "CMP压槽工艺参数表"));
        resp.setFormType(record.getFormType());
        resp.setFormTypeName(record.getFormTypeName());
        resp.setReportDate(record.getRecordDate());
        resp.setModelCode(record.getModelCode());
        resp.setMaterialCode(toStringValue(header.get("materialCode")));
        resp.setMotherBatchNo(normalizePressSlotMiddleBatchNo(firstNotBlank(record.getBatchNo(),
                toStringValue(header.get("motherBatchNo")), toStringValue(header.get("parentProductionBatchNo")))));
        resp.setParentProductionBatchNo(resp.getMotherBatchNo());
        resp.setFirstInspectionSliceNo(toStringValue(header.get("firstInspectionSliceNo")));
        resp.setInspectionScene(toStringValue(header.get("inspectionScene")));
        resp.setSourceExcel(toStringValue(header.get("sourceExcel")));
        resp.setProductionBatchNo(items.stream().map(HcPressSlotProcessParamRespVO.Item::getProductionBatchNo)
                .filter(StrUtil::isNotBlank).findFirst().orElse(firstNotBlank(resp.getFirstInspectionSliceNo(), toStringValue(header.get("batchNo")))));
        resp.setRecorderName(record.getFillUserName());
        resp.setFillUserName(record.getFillUserName());
        resp.setFillTime(record.getFillTime());
        resp.setConfirmUserName(record.getConfirmUserName());
        resp.setConfirmTime(record.getConfirmTime());
        resp.setReportStatus(record.getRecordStatus());
        resp.setRecordStatus(record.getRecordStatus());
        resp.setStatusName(resolvePressSlotFormStatusName(record.getRecordStatus()));
        resp.setRemark(record.getRemark());
        resp.setImportAttachment(findPressSlotImportAttachment(header, context));
        resp.setItems(items);
        return resp;
    }

