    private List<HcPressSlotProcessParamRespVO.Item> buildInitialPressSlotProcessParamItems(Long planOperationId,
                                                                                            String motherBatchNo,
                                                                                            Long excludeRecordId) {
        String normalizedMotherBatchNo = normalizePressSlotMiddleBatchNo(motherBatchNo);
        Set<String> includedSliceNos = collectPressSlotProcessParamIncludedSliceNos(planOperationId, excludeRecordId);
        List<HcPressSlotReportDO> reports = hcPressSlotReportMapper.selectListByPlanOperationId(planOperationId);
        List<HcPressSlotProcessParamRespVO.Item> rows = new ArrayList<>();
        int index = 0;
        for (HcPressSlotReportDO report : reports) {
            String status = StrUtil.blankToDefault(report.getReportStatus(), "");
            if (!"CONFIRMED".equalsIgnoreCase(status)) {
                continue;
            }
            String reportMotherBatchNo = resolvePressSlotReportMotherBatchNo(report);
            if (StrUtil.isNotBlank(normalizedMotherBatchNo) && !StrUtil.equalsIgnoreCase(reportMotherBatchNo, normalizedMotherBatchNo)) {
                continue;
            }
            String sliceNo = report.getProductionBatchNo();
            if (StrUtil.isBlank(sliceNo) || includedSliceNos.contains(StrUtil.trim(sliceNo).toUpperCase())) {
                continue;
            }
            index++;
            HcPressSlotProcessParamRespVO.Item item = new HcPressSlotProcessParamRespVO.Item();
            item.setSeq(index);
            item.setReportDate(report.getReportDate() == null ? LocalDate.now() : report.getReportDate());
            item.setModelCode(report.getModelCode());
            item.setProductionBatchNo(sliceNo);
            item.setMotherBatchNo(reportMotherBatchNo);
            item.setStartTime(formatPressSlotProcessParamTime(report.getStartTime()));
            item.setEndTime(formatPressSlotProcessParamTime(report.getEndTime()));
            item.setRecorderName(firstNotBlank(report.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统"));
            item.setConfirmerName(report.getConfirmerName());
            item.setSourceReportId(report.getId());
            rows.add(item);
        }
        return rows;
    }

    private Set<String> collectPressSlotProcessParamIncludedSliceNos(Long planOperationId, Long excludeRecordId) {
        List<HcProcessFormRecordDO> records = hcProcessFormRecordMapper.selectList(new LambdaQueryWrapperX<HcProcessFormRecordDO>()
                .eq(HcProcessFormRecordDO::getProcessCode, PROCESS_CODE_PRESS_SLOT)
                .eq(HcProcessFormRecordDO::getFormType, PRESS_SLOT_PROCESS_PARAM_FORM_TYPE)
                .eq(HcProcessFormRecordDO::getPlanOperationId, planOperationId)
                .orderByDesc(HcProcessFormRecordDO::getId));
        Set<String> included = new LinkedHashSet<>();
        for (HcProcessFormRecordDO record : records) {
            if (excludeRecordId != null && Objects.equals(record.getId(), excludeRecordId)) {
                continue;
            }
            buildPressSlotProcessParamItems(record).stream()
                    .map(HcPressSlotProcessParamRespVO.Item::getProductionBatchNo)
                    .filter(StrUtil::isNotBlank)
                    .map(value -> StrUtil.trim(value).toUpperCase())
                    .forEach(included::add);
        }
        return included;
    }

    private Sheet resolvePressSlotProcessParamImportSheet(Workbook workbook, DataFormatter formatter) {
        for (int i = 0; i < workbook.getNumberOfSheets(); i++) {
            Sheet sheet = workbook.getSheetAt(i);
            if (findPressSlotProcessParamDynamicHeaderRow(sheet, formatter) >= 0) {
                return sheet;
            }
        }
        return workbook.getNumberOfSheets() == 0 ? null : workbook.getSheetAt(0);
    }

    private int findPressSlotProcessParamDynamicHeaderRow(Sheet sheet, DataFormatter formatter) {
        if (sheet == null) {
            return -1;
        }
        for (int i = 0; i <= sheet.getLastRowNum(); i++) {
            Row row = sheet.getRow(i);
            if (row == null) {
                continue;
            }
            String rowText = "";
            for (int j = 0; j < Math.min(30, Math.max(row.getLastCellNum(), 0)); j++) {
                rowText += "|" + formatter.formatCellValue(row.getCell(j));
            }
            if (StrUtil.contains(rowText, "序号") && StrUtil.contains(rowText, "压槽")) {
                return i;
            }
            if (StrUtil.contains(rowText, "压槽片号")) {
                return i;
            }
        }
        return -1;
    }

    private boolean isPressSlotProcessParamFullListHeader(Row row, DataFormatter formatter) {
        if (row == null) {
            return false;
        }
        String text = "";
        for (int i = 0; i < Math.min(30, Math.max(row.getLastCellNum(), 0)); i++) {
            text += "|" + formatter.formatCellValue(row.getCell(i));
        }
        return StrUtil.contains(text, "序号") && StrUtil.contains(text, "压槽速度");
    }

