    private Integer importPressSlotProductionCheck(HcPlanOrderDO planOrder,
                                                   HcPlanOrderOperationDO operation,
                                                   MultipartFile file,
                                                   Map<String, Object> importAttachment,
                                                   Long recordId,
                                                   String motherBatchNo,
                                                   String productionBatchNo,
                                                   String inspectionScene,
                                                   LocalDate recordDate) throws Exception {
        DataFormatter formatter = new DataFormatter();
        List<HcPressSlotProcessParamSaveReqVO.Item> importedItems = new ArrayList<>();
        try (InputStream inputStream = file.getInputStream(); Workbook workbook = WorkbookFactory.create(inputStream)) {
            Sheet sheet = resolvePressSlotProductionCheckImportSheet(workbook, formatter);
            int headerRowIndex = findPressSlotProductionCheckHeaderRow(sheet, formatter);
            if (headerRowIndex < 0) {
                throw invalidParamException("导入模板未找到压槽生产点检表头");
            }
            Map<String, Integer> columns = buildPressSlotProductionCheckColumnIndex(sheet.getRow(headerRowIndex), formatter);
            for (int i = headerRowIndex + 1; i <= sheet.getLastRowNum(); i++) {
                Row row = sheet.getRow(i);
                if (row == null) {
                    continue;
                }
                HcPressSlotProcessParamSaveReqVO.Item item = buildPressSlotProductionCheckImportItem(row, formatter,
                        columns, importedItems.size() + 1);
                if (StrUtil.isBlank(item.getItemName())) {
                    continue;
                }
                importedItems.add(item);
            }
        }
        if (CollUtil.isEmpty(importedItems)) {
            throw invalidParamException("导入文件未读取到压槽生产点检明细");
        }

        String modelCode = firstNotBlank(planOrder.getModelCode(), planOrder.getModelName());
        String normalizedMotherBatchNo = firstNotBlank(normalizePressSlotMiddleBatchNo(motherBatchNo),
                importedItems.stream().map(HcPressSlotProcessParamSaveReqVO.Item::getMotherBatchNo)
                        .filter(StrUtil::isNotBlank).findFirst().orElse(null),
                resolvePressSlotOperationMotherBatchNo(operation));
        String sliceNo = firstNotBlank(productionBatchNo,
                importedItems.stream().map(HcPressSlotProcessParamSaveReqVO.Item::getProductionBatchNo)
                        .filter(StrUtil::isNotBlank).findFirst().orElse(null));
        HcStationFormDO form = requirePressSlotStationFormConfig(PRESS_SLOT_PRODUCTION_CHECK_FORM_TYPE, modelCode);
        List<HcPressSlotProcessParamSaveReqVO.Item> templateItems = buildPressSlotProductionCheckTemplateReqItems(form, modelCode, sliceNo);
        List<HcPressSlotProcessParamSaveReqVO.Item> items = mergePressSlotProductionCheckImportItems(importedItems,
                templateItems, modelCode, normalizedMotherBatchNo, sliceNo, recordDate);

        HcPressSlotProcessParamSaveReqVO saveReq = new HcPressSlotProcessParamSaveReqVO();
        saveReq.setId(recordId);
        saveReq.setPlanId(planOrder.getId());
        saveReq.setPlanOperationId(operation.getId());
        saveReq.setReportDate(firstNotNullDate(recordDate,
                items.stream().map(HcPressSlotProcessParamSaveReqVO.Item::getReportDate)
                        .filter(Objects::nonNull).findFirst().orElse(null),
                LocalDate.now()));
        saveReq.setModelCode(modelCode);
        saveReq.setMaterialCode(planOrder.getMaterialCode());
        saveReq.setMotherBatchNo(normalizedMotherBatchNo);
        saveReq.setParentProductionBatchNo(normalizedMotherBatchNo);
        saveReq.setProductionBatchNo(sliceNo);
        saveReq.setFirstInspectionSliceNo(sliceNo);
        saveReq.setFormType(PRESS_SLOT_PRODUCTION_CHECK_FORM_TYPE);
        saveReq.setFormTypeName("生产点检");
        saveReq.setInspectionScene(StrUtil.blankToDefault(inspectionScene, PRESS_SLOT_INSPECTION_SAMPLE_CATEGORY_FIRST));
        saveReq.setSourceExcel("11-2-92 CMP软垫（W26P0100）压槽生产点检表.xlsx");
        saveReq.setRecorderName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统"));
        saveReq.setImportAttachment(importAttachment);
        saveReq.setItems(items);
        savePressSlotProcessParamRecord(saveReq, false);
        return items.size();
    }

    private Sheet resolvePressSlotProductionCheckImportSheet(Workbook workbook, DataFormatter formatter) {
        for (int i = 0; i < workbook.getNumberOfSheets(); i++) {
            Sheet sheet = workbook.getSheetAt(i);
            if (findPressSlotProductionCheckHeaderRow(sheet, formatter) >= 0) {
                return sheet;
            }
        }
        return workbook.getNumberOfSheets() == 0 ? null : workbook.getSheetAt(0);
    }

    private int findPressSlotProductionCheckHeaderRow(Sheet sheet, DataFormatter formatter) {
        if (sheet == null) {
            return -1;
        }
        for (int i = 0; i <= sheet.getLastRowNum(); i++) {
            Row row = sheet.getRow(i);
            if (row == null) {
                continue;
            }
            String rowText = "";
            for (int j = 0; j < Math.min(30, Math.max(row.getLastCellNum(), 0)); j++) {
                rowText += "|" + formatter.formatCellValue(row.getCell(j));
            }
            boolean hasItemHeader = StrUtil.contains(rowText, "点检项目")
                    || StrUtil.contains(rowText, "工艺参数项目")
                    || StrUtil.contains(rowText, "项目名称");
            boolean hasValueHeader = StrUtil.contains(rowText, "记录值")
                    || StrUtil.contains(rowText, "实测值")
                    || StrUtil.contains(rowText, "实际值");
            if (hasItemHeader && hasValueHeader) {
                return i;
            }
        }
        return -1;
    }

    private Map<String, Integer> buildPressSlotProductionCheckColumnIndex(Row row, DataFormatter formatter) {
        Map<String, Integer> columns = new LinkedHashMap<>();
        if (row == null) {
            return columns;
        }
        for (int i = 0; i < Math.min(30, Math.max(row.getLastCellNum(), 0)); i++) {
            String header = normalizePressSlotProductionCheckHeader(formatter.formatCellValue(row.getCell(i)));
            if (StrUtil.isBlank(header)) {
                continue;
            }
            if (StrUtil.contains(header, "序号")) {
                columns.put("seq", i);
            } else if (StrUtil.contains(header, "项目类别")
                    || StrUtil.contains(header, "生产环节")
                    || StrUtil.equals(header, "物料")) {
                columns.put("category", i);
            } else if (StrUtil.contains(header, "点检项目")
                    || StrUtil.contains(header, "工艺参数项目")
                    || StrUtil.contains(header, "项目名称")) {
                columns.put("item", i);
            } else if (StrUtil.contains(header, "标准")) {
                columns.put("standard", i);
            } else if (StrUtil.contains(header, "记录值")
                    || StrUtil.contains(header, "实测值")
                    || StrUtil.contains(header, "实际值")) {
                columns.put("actual", i);
            } else if (StrUtil.contains(header, "结果")) {
                columns.put("result", i);
            } else if (StrUtil.contains(header, "异常")) {
                columns.put("remark", i);
            }
        }
        return columns;
    }

    private HcPressSlotProcessParamSaveReqVO.Item buildPressSlotProductionCheckImportItem(Row row,
                                                                                          DataFormatter formatter,
                                                                                          Map<String, Integer> columns,
                                                                                          int index) {
        HcPressSlotProcessParamSaveReqVO.Item item = new HcPressSlotProcessParamSaveReqVO.Item();
        item.setSeq(firstNotNullInteger(parseInteger(readMappedCell(row, columns, "seq", 0, formatter)), index));
        item.setSortNo(item.getSeq());
        item.setItemCategory(firstNotBlank(readMappedCell(row, columns, "category", 1, formatter), "其他"));
        item.setItemName(readMappedCell(row, columns, "item", 2, formatter));
        item.setStandardValue(readMappedCell(row, columns, "standard", 3, formatter));
        item.setActualValue(readMappedCell(row, columns, "actual", 4, formatter));
        item.setCheckResult("OK");
        item.setAbnormalRemark(readMappedCell(row, columns, "remark", columns.containsKey("result") ? 6 : 5, formatter));
        return item;
    }

    private List<HcPressSlotProcessParamSaveReqVO.Item> mergePressSlotProductionCheckImportItems(
            List<HcPressSlotProcessParamSaveReqVO.Item> importedItems,
            List<HcPressSlotProcessParamSaveReqVO.Item> templateItems,
            String modelCode,
            String motherBatchNo,
            String productionBatchNo,
            LocalDate recordDate) {
        Map<Integer, HcPressSlotProcessParamSaveReqVO.Item> templateBySeq = new LinkedHashMap<>();
        Map<String, HcPressSlotProcessParamSaveReqVO.Item> templateByName = new LinkedHashMap<>();
        for (HcPressSlotProcessParamSaveReqVO.Item templateItem : templateItems) {
            Integer seq = firstNotNullInteger(templateItem.getSortNo(), templateItem.getSeq());
            if (seq != null) {
                templateBySeq.put(seq, templateItem);
            }
            templateByName.put(normalizePressSlotProductionCheckMatchKey(templateItem.getItemCategory(), templateItem.getItemName()), templateItem);
        }
        List<HcPressSlotProcessParamSaveReqVO.Item> result = new ArrayList<>();
        int index = 0;
        for (HcPressSlotProcessParamSaveReqVO.Item imported : importedItems) {
            index++;
            HcPressSlotProcessParamSaveReqVO.Item template = templateBySeq.get(imported.getSeq());
            if (template == null) {
                template = templateByName.get(normalizePressSlotProductionCheckMatchKey(imported.getItemCategory(), imported.getItemName()));
            }
            HcPressSlotProcessParamSaveReqVO.Item item = new HcPressSlotProcessParamSaveReqVO.Item();
            Integer seq = firstNotNullInteger(imported.getSeq(), template == null ? null : template.getSeq(), index);
            item.setTemplateItemId(template == null ? null : template.getTemplateItemId());
            item.setFieldKey(template == null ? null : template.getFieldKey());
            item.setSeq(seq);
            item.setSortNo(seq);
            item.setReportDate(firstNotNullDate(imported.getReportDate(), recordDate, LocalDate.now()));
            item.setModelCode(modelCode);
            item.setMotherBatchNo(motherBatchNo);
            item.setProductionBatchNo(productionBatchNo);
            item.setItemCategory(firstNotBlank(imported.getItemCategory(), template == null ? null : template.getItemCategory(), "其他"));
            item.setItemName(firstNotBlank(imported.getItemName(), template == null ? null : template.getItemName()));
            item.setStandardValue(firstNotBlank(imported.getStandardValue(), template == null ? null : template.getStandardValue()));
            item.setActualValue(imported.getActualValue());
            item.setCheckResult(firstNotBlank(imported.getCheckResult(), template == null ? null : template.getCheckResult(), "OK"));
            item.setAbnormalRemark(imported.getAbnormalRemark());
            item.setValueMode(template == null ? null : template.getValueMode());
            item.setDualLabel1(template == null ? null : template.getDualLabel1());
            item.setDualLabel2(template == null ? null : template.getDualLabel2());
            item.setRequiredFlag(template == null ? null : template.getRequiredFlag());
            item.setRecorderName(firstNotBlank(SecurityFrameworkUtils.getLoginUserNickname(), "系统"));
            result.add(item);
        }
        return result;
    }

    private String readMappedCell(Row row, Map<String, Integer> columns, String key, int fallbackIndex, DataFormatter formatter) {
        Integer index = columns.get(key);
        return readCellString(row, index == null ? fallbackIndex : index, formatter);
    }

    private String normalizePressSlotProductionCheckHeader(String text) {
        return StrUtil.trimToEmpty(text).replaceAll("\\s+", "");
    }

    private String normalizePressSlotProductionCheckMatchKey(String category, String itemName) {
        return normalizePressSlotProductionCheckHeader(category) + "|" + normalizePressSlotProductionCheckHeader(itemName);
    }

    private Integer firstNotNullInteger(Integer... values) {
        if (values == null) {
            return null;
        }
        for (Integer value : values) {
            if (value != null) {
                return value;
            }
        }
        return null;
    }

