    private Map<String, Object> findPressSlotImportAttachment(Map<String, Object> header, Map<String, Object> context) {
        for (Map<String, Object> source : List.of(header, context)) {
            Object raw = source.get(PRESS_SLOT_IMPORT_ATTACHMENT_KEY);
            if (raw instanceof Map<?, ?> map && !map.isEmpty()) {
                return copyObjectMap(map);
            }
            raw = source.get("importAttachment");
            if (raw instanceof Map<?, ?> map && !map.isEmpty()) {
                return copyObjectMap(map);
            }
            raw = source.get("attachments");
            if (raw instanceof List<?> list && !list.isEmpty() && list.get(list.size() - 1) instanceof Map<?, ?> map) {
                return copyObjectMap(map);
            }
        }
        return Collections.emptyMap();
    }

    private Map<String, Object> copyObjectMap(Map<?, ?> source) {
        Map<String, Object> result = new LinkedHashMap<>();
        source.forEach((key, value) -> result.put(String.valueOf(key), value));
        return result;
    }

    private String resolvePressSlotOperationMotherBatchNo(HcPlanOrderOperationDO operation) {
        if (operation == null) {
            return null;
        }
        return normalizePressSlotMiddleBatchNo(firstNotBlank(operation.getParentProductionBatchNo(),
                operation.getProductionBatchNo(), operation.getBatchNo()));
    }

    private String formatPressSlotProcessParamTime(LocalDateTime time) {
        return time == null ? "" : time.format(DateTimeFormatter.ofPattern("HH:mm"));
    }

    private Integer parseInteger(String text) {
        if (StrUtil.isBlank(text)) {
            return null;
        }
        try {
            return new BigDecimal(StrUtil.trim(text)).intValue();
        } catch (Exception ignored) {
            return null;
        }
    }

    private Long parseLong(String text) {
        if (StrUtil.isBlank(text)) {
            return null;
        }
        try {
            return new BigDecimal(StrUtil.trim(text)).longValue();
        } catch (Exception ignored) {
            return null;
        }
    }

    private HcPressSlotProcessParamRespVO buildPressSlotProcessParamResp(HcPressSlotReportDO report) {
        HcPressSlotProcessParamRespVO resp = new HcPressSlotProcessParamRespVO();
        resp.setId(report.getId());
        resp.setPlanId(report.getPlanId());
        resp.setPlanNo(report.getPlanNo());
        resp.setPlanOperationId(report.getPlanOperationId());
        resp.setReportDate(report.getReportDate());
        resp.setModelCode(report.getModelCode());
        resp.setParentProductionBatchNo(normalizePressSlotMiddleBatchNo(firstNotBlank(report.getParentProductionBatchNo(),
                report.getSourceProductionBatchNo(), report.getSourceBatchNo())));
        resp.setProductionBatchNo(report.getProductionBatchNo());
        Map<String, Object> extra = parseRoughExtraMap(report.getExtraJson());
        if (Boolean.TRUE.equals(extra.get("faiFirstInspectionSample"))
                || "CHANGEOVER".equalsIgnoreCase(String.valueOf(extra.get("reportType")))) {
            resp.setFirstInspectionSliceNo(report.getProductionBatchNo());
            Object faiJudgment = extra.get("faiJudgment");
            resp.setFirstInspectionResult(firstNotBlank(faiJudgment == null ? null : String.valueOf(faiJudgment), report.getSelfCheck()));
            resp.setInspectionTime(firstNotNullDateTime(report.getConfirmerTime(), report.getEndTime(), report.getRecorderTime()));
        }
        List<HcPressSlotCheckDetailDO> details = hcPressSlotCheckDetailMapper.selectListByReportId(report.getId());
        resp.setTemperature1(resolvePressSlotTemperature(details, 1));
        resp.setTemperature2(resolvePressSlotTemperature(details, 2));
        resp.setTemperature3(resolvePressSlotTemperature(details, 3));
        resp.setTemperature4(resolvePressSlotTemperature(details, 4));
        resp.setTemperature5(resolvePressSlotTemperature(details, 5));
        resp.setRecorderName(report.getRecorderName());
        resp.setRemark(report.getRemark());
        resp.setReportStatus(report.getReportStatus());
        return resp;
    }

    private boolean isPressSlotFirstInspectionSampleReport(HcPressSlotReportDO report) {
        if (report == null || Boolean.TRUE.equals(report.getDeleted())) {
            return false;
        }
        Map<String, Object> extra = parseRoughExtraMap(report.getExtraJson());
        String reportType = StrUtil.trimToEmpty(String.valueOf(extra.get("reportType")));
        String sampleCategory = StrUtil.trimToEmpty(String.valueOf(extra.get("inspectionSampleCategory")));
        return Boolean.TRUE.equals(extra.get("faiFirstInspectionSample"))
                || "CHANGEOVER".equalsIgnoreCase(reportType)
                || PRESS_SLOT_INSPECTION_SAMPLE_CATEGORY_FIRST.equalsIgnoreCase(sampleCategory);
    }

    private String resolvePressSlotTemperature(List<HcPressSlotCheckDetailDO> details, int index) {
        String indexText = String.valueOf(index);
        return details.stream()
                .filter(item -> StrUtil.contains(item.getItemName(), "温度点" + indexText)
                        || StrUtil.contains(item.getItemName(), "温度" + indexText))
                .map(HcPressSlotCheckDetailDO::getActualValue)
                .filter(StrUtil::isNotBlank)
                .findFirst()
                .orElse("");
    }

    private int findPressSlotProcessParamHeaderRow(Sheet sheet, DataFormatter formatter) {
        for (int i = 0; i <= sheet.getLastRowNum(); i++) {
            Row row = sheet.getRow(i);
            if (row == null) {
                continue;
            }
            for (int j = 0; j < Math.min(12, row.getLastCellNum()); j++) {
                if (StrUtil.equals(formatter.formatCellValue(row.getCell(j)), "压槽片号")) {
                    return i;
                }
            }
        }
        return -1;
    }

    private Workbook createPressSlotProcessParamWorkbook() throws Exception {
        InputStream inputStream = HcProcessReportServiceImpl.class.getResourceAsStream(PRESS_SLOT_PROCESS_PARAM_TEMPLATE_RESOURCE);
        if (inputStream == null) {
            return new XSSFWorkbook();
        }
        try (inputStream) {
            return WorkbookFactory.create(inputStream);
        }
    }

    private int createPressSlotProcessParamFallbackHeader(Sheet sheet) {
        Row title = sheet.getRow(0);
        if (title == null) {
            title = sheet.createRow(0);
        }
        setExcelCellValue(title, 0, "CMP压槽工艺参数记录表");
        Row header = sheet.getRow(1);
        if (header == null) {
            header = sheet.createRow(1);
        }
        String[] headers = {"日期", "型号", "批号", "压槽片号", "实测点温度1(℃)", "实测点温度2(℃)",
                "实测点温度3(℃)", "实测点温度4(℃)", "实测点温度5(℃)", "记录人", "备注"};
        for (int i = 0; i < headers.length; i++) {
            setExcelCellValue(header, i, headers[i]);
            sheet.setColumnWidth(i, i <= 3 ? 18 * 256 : 16 * 256);
            sheet.setColumnHidden(i, false);
        }
        for (int i = headers.length; i <= 13; i++) {
            setExcelCellValue(header, i, "");
            sheet.setColumnHidden(i, true);
        }
        return 1;
    }

    private void writePressSlotProcessParamRows(Sheet sheet, int headerRowIndex, List<HcPressSlotProcessParamRespVO> rows) {
        int dataStartRow = headerRowIndex + 1;
        Row header = sheet.getRow(headerRowIndex);
        if (header == null) {
            header = sheet.createRow(headerRowIndex);
        }
        String[] headers = {"日期", "型号", "批号", "压槽片号", "实测点温度1(℃)", "实测点温度2(℃)",
                "实测点温度3(℃)", "实测点温度4(℃)", "实测点温度5(℃)", "记录人", "备注"};
        for (int col = 0; col < headers.length; col++) {
            setExcelCellValue(header, col, headers[col]);
            sheet.setColumnHidden(col, false);
        }
        for (int col = headers.length; col <= 13; col++) {
            setExcelCellValue(header, col, "");
            sheet.setColumnHidden(col, true);
        }
        int footerRow = findPressSlotProcessParamFooterRow(sheet, new DataFormatter(), dataStartRow);
        int templateDataEndRow = footerRow > dataStartRow ? footerRow - 1 : Math.max(dataStartRow, sheet.getLastRowNum());
        int targetEndRow = dataStartRow + Math.max(rows.size(), 1) - 1;
        ensurePressSlotProcessParamRows(sheet, dataStartRow, templateDataEndRow, targetEndRow);
        clearPressSlotProcessParamRows(sheet, dataStartRow, Math.max(templateDataEndRow, targetEndRow));
        for (int i = 0; i < rows.size(); i++) {
            HcPressSlotProcessParamRespVO item = rows.get(i);
            Row row = sheet.getRow(dataStartRow + i);
            if (row == null) {
                row = sheet.createRow(dataStartRow + i);
            }
            setExcelCellValue(row, 0, item.getReportDate() == null ? "" : item.getReportDate().toString());
            setExcelCellValue(row, 1, StrUtil.blankToDefault(item.getModelCode(), ""));
            setExcelCellValue(row, 2, StrUtil.blankToDefault(item.getParentProductionBatchNo(), ""));
            setExcelCellValue(row, 3, StrUtil.blankToDefault(item.getProductionBatchNo(), ""));
            setExcelCellValue(row, 4, StrUtil.blankToDefault(item.getTemperature1(), ""));
            setExcelCellValue(row, 5, StrUtil.blankToDefault(item.getTemperature2(), ""));
            setExcelCellValue(row, 6, StrUtil.blankToDefault(item.getTemperature3(), ""));
            setExcelCellValue(row, 7, StrUtil.blankToDefault(item.getTemperature4(), ""));
            setExcelCellValue(row, 8, StrUtil.blankToDefault(item.getTemperature5(), ""));
            setExcelCellValue(row, 9, StrUtil.blankToDefault(item.getRecorderName(), ""));
            setExcelCellValue(row, 10, StrUtil.blankToDefault(item.getRemark(), ""));
        }
    }

    private int findPressSlotProcessParamFooterRow(Sheet sheet, DataFormatter formatter, int startRow) {
        for (int i = startRow; i <= sheet.getLastRowNum(); i++) {
            Row row = sheet.getRow(i);
            if (StrUtil.contains(readCellString(row, 0, formatter), "制定/修订部门")) {
                return i;
            }
        }
        return -1;
    }

    private void ensurePressSlotProcessParamRows(Sheet sheet, int dataStartRow, int templateDataEndRow, int targetEndRow) {
        if (targetEndRow > templateDataEndRow && templateDataEndRow + 1 <= sheet.getLastRowNum()) {
            sheet.shiftRows(templateDataEndRow + 1, sheet.getLastRowNum(), targetEndRow - templateDataEndRow, true, false);
        }
        Row sourceRow = sheet.getRow(dataStartRow);
        for (int rowIndex = dataStartRow; rowIndex <= targetEndRow; rowIndex++) {
            Row row = sheet.getRow(rowIndex);
            if (row == null) {
                row = sheet.createRow(rowIndex);
            }
            copyPressSlotProcessParamRowStyle(sourceRow, row);
        }
    }

    private void copyPressSlotProcessParamRowStyle(Row sourceRow, Row targetRow) {
        if (sourceRow == null || targetRow == null) {
            return;
        }
        targetRow.setHeight(sourceRow.getHeight());
        for (int col = 0; col <= 13; col++) {
            Cell sourceCell = sourceRow.getCell(col);
            Cell targetCell = targetRow.getCell(col);
            if (targetCell == null) {
                targetCell = targetRow.createCell(col);
            }
            if (sourceCell != null) {
                targetCell.setCellStyle(sourceCell.getCellStyle());
            }
        }
    }

    private void clearPressSlotProcessParamRows(Sheet sheet, int startRow, int endRow) {
        for (int rowIndex = startRow; rowIndex <= endRow; rowIndex++) {
            Row row = sheet.getRow(rowIndex);
            if (row == null) {
                continue;
            }
            for (int col = 0; col <= 13; col++) {
                setExcelCellValue(row, col, "");
            }
        }
    }

    private String readCellString(Row row, int index, DataFormatter formatter) {
        if (row == null || row.getCell(index) == null) {
            return "";
        }
        return StrUtil.trim(formatter.formatCellValue(row.getCell(index)));
    }

    private HcPressSlotReportDO findOrCreatePressSlotReportForProcessParam(HcPlanOrderDO planOrder,
                                                                           HcPlanOrderOperationDO operation,
                                                                           String sliceNo,
                                                                           Row row,
                                                                           DataFormatter formatter) {
        HcPressSlotReportDO report = hcPressSlotReportMapper.selectByProductionBatchNo(sliceNo);
        if (report != null) {
            if (!isPressSlotFirstInspectionSampleReport(report)) {
                throw invalidParamException("工艺参数上报仅允许导入当前母批段首检片");
            }
            HcPressSlotReportDO update = new HcPressSlotReportDO();
            update.setId(report.getId());
            update.setReportDate(parsePressSlotProcessParamDate(readCellString(row, 0, formatter)));
            update.setModelCode(firstNotBlank(readCellString(row, 1, formatter), report.getModelCode()));
            update.setParentProductionBatchNo(firstNotBlank(readCellString(row, 2, formatter), report.getParentProductionBatchNo()));
            update.setRecorderName(firstNotBlank(readCellString(row, 9, formatter), report.getRecorderName()));
            update.setRemark(firstNotBlank(readCellString(row, 10, formatter), report.getRemark()));
            hcPressSlotReportMapper.updateById(update);
            report = hcPressSlotReportMapper.selectById(report.getId());
            return report;
        }
        HcSlittingSliceRecordDO sourceSlice = hcSlittingSliceRecordMapper.selectBySerialNo(sliceNo);
        LocalDate reportDate = parsePressSlotProcessParamDate(readCellString(row, 0, formatter));
        report = HcPressSlotReportDO.builder()
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .operationCode(operation.getOpCode())
                .operationName(operation.getOpName())
                .sourceSlittingSliceId(sourceSlice == null ? 0L : sourceSlice.getId())
                .sourceBatchNo(sourceSlice == null ? null : sourceSlice.getSourceBatchNo())
                .sourceProductionBatchNo(sourceSlice == null ? sliceNo : sourceSlice.getSliceSerialNo())
                .productionBatchNo(sliceNo)
                .parentProductionBatchNo(firstNotBlank(readCellString(row, 2, formatter),
                        sourceSlice == null ? null : sourceSlice.getSourceProductionBatchNo(),
                        sourceSlice == null ? null : sourceSlice.getSourceBatchNo()))
                .modelCode(firstNotBlank(readCellString(row, 1, formatter), planOrder.getModelCode(), planOrder.getModelName()))
                .materialCode(planOrder.getMaterialCode())
                .materialName(planOrder.getMaterialName())
                .reportDate(reportDate == null ? LocalDate.now() : reportDate)
                .inputLength(BigDecimal.ONE)
                .outputLength(BigDecimal.ONE)
                .lossLength(BigDecimal.ZERO)
                .napSampleLength(BigDecimal.ZERO)
                .selfCheck("OK")
                .reportStatus("DRAFT")
                .recorderName(firstNotBlank(readCellString(row, 9, formatter), SecurityFrameworkUtils.getLoginUserNickname(), "系统"))
                .recorderTime(LocalDateTime.now())
                .remark(readCellString(row, 10, formatter))
                .extraJson(buildPressSlotFirstInspectionProcessParamExtra())
                .build();
        report.setRecorderName(recorderNameResolver.resolveForSave(report.getRecorderName()));
        hcPressSlotReportMapper.insert(report);
        return report;
    }

    private HcPressSlotReportDO findOrCreatePressSlotReportForProcessParam(HcPlanOrderDO planOrder,
                                                                           HcPlanOrderOperationDO operation,
                                                                           HcPressSlotProcessParamSaveReqVO reqVO) {
        HcPressSlotReportDO report = reqVO.getId() == null ? null : hcPressSlotReportMapper.selectById(reqVO.getId());
        if (report == null && StrUtil.isNotBlank(reqVO.getProductionBatchNo())) {
            report = hcPressSlotReportMapper.selectByProductionBatchNo(reqVO.getProductionBatchNo());
        }
        if (report != null) {
            if (!Objects.equals(report.getPlanId(), planOrder.getId())
                    || !Objects.equals(report.getPlanOperationId(), operation.getId())) {
                throw invalidParamException("工艺参数记录不属于当前压槽计划");
            }
            if (!isPressSlotFirstInspectionSampleReport(report)) {
                throw invalidParamException("工艺参数上报仅允许填写当前母批段首检片");
            }
            return report;
        }
        HcSlittingSliceRecordDO sourceSlice = hcSlittingSliceRecordMapper.selectBySerialNo(reqVO.getProductionBatchNo());
        report = HcPressSlotReportDO.builder()
                .tenantId(planOrder.getTenantId())
                .planId(planOrder.getId())
                .planNo(planOrder.getPlanNo())
                .planOperationId(operation.getId())
                .operationCode(operation.getOpCode())
                .operationName(operation.getOpName())
                .sourceSlittingSliceId(sourceSlice == null ? null : sourceSlice.getId())
                .sourceBatchNo(sourceSlice == null ? null : sourceSlice.getSourceBatchNo())
                .sourceProductionBatchNo(sourceSlice == null ? reqVO.getProductionBatchNo() : sourceSlice.getSliceSerialNo())
                .productionBatchNo(reqVO.getProductionBatchNo())
                .parentProductionBatchNo(firstNotBlank(reqVO.getParentProductionBatchNo(),
                        sourceSlice == null ? null : sourceSlice.getSourceProductionBatchNo(),
                        sourceSlice == null ? null : sourceSlice.getSourceBatchNo(),
                        normalizePressSlotMiddleBatchNo(reqVO.getProductionBatchNo())))
                .modelCode(firstNotBlank(reqVO.getModelCode(), planOrder.getModelCode(), planOrder.getModelName()))
                .materialCode(planOrder.getMaterialCode())
                .materialName(planOrder.getMaterialName())
                .reportDate(reqVO.getReportDate() == null ? LocalDate.now() : reqVO.getReportDate())
                .inputLength(BigDecimal.ONE)
                .outputLength(BigDecimal.ONE)
                .lossLength(BigDecimal.ZERO)
                .napSampleLength(BigDecimal.ZERO)
                .selfCheck("OK")
                .reportStatus("DRAFT")
                .recorderName(firstNotBlank(reqVO.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname(), "系统"))
                .recorderTime(LocalDateTime.now())
                .remark(reqVO.getRemark())
                .extraJson(buildPressSlotFirstInspectionProcessParamExtra())
                .build();
        report.setRecorderName(recorderNameResolver.resolveForSave(report.getRecorderName()));
        hcPressSlotReportMapper.insert(report);
        return report;
    }

    private String buildPressSlotFirstInspectionProcessParamExtra() {
        Map<String, Object> extra = new LinkedHashMap<>();
        extra.put("reportType", "CHANGEOVER");
        extra.put("reportTypeName", "首检");
        extra.put("faiFirstInspectionSample", true);
        extra.put("inspectionSampleCategory", PRESS_SLOT_INSPECTION_SAMPLE_CATEGORY_FIRST);
        extra.put("inspectionSampleCategoryName", "首检送检");
        return JsonUtils.toJsonString(extra);
    }

    private LocalDate parsePressSlotProcessParamDate(String text) {
        if (StrUtil.isBlank(text)) {
            return LocalDate.now();
        }
        try {
            return LocalDate.parse(text);
        } catch (Exception ignored) {
            try {
                return LocalDate.parse(text, DateTimeFormatter.ofPattern("yyyy/M/d"));
            } catch (Exception ignoredAgain) {
                return LocalDate.now();
            }
        }
    }

