    private List<HcPressSlotIntermediateDetailRespVO> mergeDefaultPressSlotIntermediateDetails(
            List<HcPressSlotIntermediateDetailRespVO> existingDetails) {
        Map<String, HcPressSlotIntermediateDetailRespVO> merged = new LinkedHashMap<>();
        for (HcPressSlotIntermediateDetailRespVO detail : buildDefaultPressSlotIntermediateDetails()) {
            merged.put(detail.getSamplePosition(), detail);
        }
        for (HcPressSlotIntermediateDetailRespVO detail : existingDetails) {
            if ("FIRST".equalsIgnoreCase(detail.getSamplePosition())) {
                continue;
            }
            String key = StrUtil.blankToDefault(detail.getSamplePosition(), "ROW" + detail.getSortNo());
            merged.put(key, detail);
        }
        return new ArrayList<>(merged.values());
    }

