    private List<HcAdhesive2ReportDO> getAdhesive2OperationReports(Long planOperationId) {
        if (planOperationId == null) {
            return Collections.emptyList();
        }
        return hcAdhesive2ReportMapper.selectListByPlanOperationId(planOperationId);
    }

    private List<HcAdhesive2ReportDO> filterAdhesive2ReportsByMotherBatchNo(List<HcAdhesive2ReportDO> reports,
                                                                             String motherBatchNo) {
        String normalizedMotherBatchNo = normalizePressSlotMiddleBatchNo(motherBatchNo);
        if (StrUtil.isBlank(normalizedMotherBatchNo)) {
            return reports;
        }
        return reports.stream()
                .filter(report -> StrUtil.equalsIgnoreCase(resolveAdhesive2MotherSegmentBatchNo(report), normalizedMotherBatchNo))
                .toList();
    }

    private List<HcPressSlotIntermediateDetailRespVO> buildAdhesive2IntermediateDetailsFromMiddleReports(
            List<HcAdhesive2ReportDO> reports) {
        List<HcPressSlotIntermediateDetailReqVO> details = buildDefaultAdhesive2IntermediateDetails().stream()
                .map(this::buildPressSlotIntermediateDetailReq)
                .collect(Collectors.toCollection(ArrayList::new));
        for (HcAdhesive2ReportDO report : reports) {
            String reportType = resolveAdhesive2ReportType(report);
            if (!isPressSlotMiddleLedgerType(reportType)) {
                continue;
            }
            HcPressSlotIntermediateDetailReqVO targetDetail = details.stream()
                    .filter(item -> StrUtil.equalsIgnoreCase(item.getSamplePosition(), reportType))
                    .findFirst()
                    .orElse(null);
            if (targetDetail == null) {
                targetDetail = new HcPressSlotIntermediateDetailReqVO();
                targetDetail.setSamplePosition(reportType);
                targetDetail.setSamplePositionName(getPressSlotIntermediatePositionName(reportType));
                targetDetail.setSortNo(details.size() + 1);
                details.add(targetDetail);
            }
            fillAdhesive2IntermediateDetailFromReport(targetDetail, report, reportType);
        }
        return details.stream()
                .map(this::buildPressSlotIntermediateDetailResp)
                .toList();
    }

    private void fillAdhesive2IntermediateDetailFromReport(HcPressSlotIntermediateDetailReqVO detail,
                                                           HcAdhesive2ReportDO report,
                                                           String reportType) {
        detail.setPressSlotReportId(report.getId());
        detail.setSourceSlittingSliceId(report.getSourcePressSlotReportId());
        detail.setSamplePosition(reportType);
        detail.setSamplePositionName(getPressSlotIntermediatePositionName(reportType));
        detail.setSliceBatchNo(firstNotBlank(report.getProductionBatchNo(), report.getSourceProductionBatchNo()));
        List<HcAdhesive2CheckDetailDO> checkDetails = hcAdhesive2CheckDetailMapper.selectListByReportId(report.getId());
        BigDecimal width = parseDecimalFromText(resolveAdhesive2CheckDetailValue(checkDetails, "宽幅/mm"));
        BigDecimal thickness1 = parseDecimalFromText(firstNotBlank(resolveAdhesive2CheckDetailValue(checkDetails, "100cm厚度/mm"),
                resolveAdhesive2CheckDetailValue(checkDetails, "厚度1/mm")));
        BigDecimal thickness2 = parseDecimalFromText(firstNotBlank(resolveAdhesive2CheckDetailValue(checkDetails, "200cm厚度/mm"),
                resolveAdhesive2CheckDetailValue(checkDetails, "厚度2/mm")));
        BigDecimal thickness3 = parseDecimalFromText(firstNotBlank(resolveAdhesive2CheckDetailValue(checkDetails, "300cm厚度/mm"),
                resolveAdhesive2CheckDetailValue(checkDetails, "厚度3/mm")));
        BigDecimal thickness4 = parseDecimalFromText(firstNotBlank(resolveAdhesive2CheckDetailValue(checkDetails, "400cm厚度/mm"),
                resolveAdhesive2CheckDetailValue(checkDetails, "厚度4/mm")));
        BigDecimal thickness5 = parseDecimalFromText(firstNotBlank(resolveAdhesive2CheckDetailValue(checkDetails, "500cm厚度/mm"),
                resolveAdhesive2CheckDetailValue(checkDetails, "厚度5/mm")));
        BigDecimal thickness6 = parseDecimalFromText(firstNotBlank(resolveAdhesive2CheckDetailValue(checkDetails, "600cm厚度/mm"),
                resolveAdhesive2CheckDetailValue(checkDetails, "厚度6/mm")));
        BigDecimal thickness7 = parseDecimalFromText(firstNotBlank(resolveAdhesive2CheckDetailValue(checkDetails, "700cm厚度/mm"),
                resolveAdhesive2CheckDetailValue(checkDetails, "厚度7/mm")));
        BigDecimal thickness8 = parseDecimalFromText(firstNotBlank(resolveAdhesive2CheckDetailValue(checkDetails, "800cm厚度/mm"),
                resolveAdhesive2CheckDetailValue(checkDetails, "厚度8/mm")));
        BigDecimal thickness9 = parseDecimalFromText(firstNotBlank(resolveAdhesive2CheckDetailValue(checkDetails, "900cm厚度/mm"),
                resolveAdhesive2CheckDetailValue(checkDetails, "厚度9/mm")));
        BigDecimal thickness10 = parseDecimalFromText(firstNotBlank(resolveAdhesive2CheckDetailValue(checkDetails, "1000cm厚度/mm"),
                resolveAdhesive2CheckDetailValue(checkDetails, "厚度10/mm")));
        if (width != null) detail.setWidthMm(width);
        if (thickness1 != null) detail.setThickness1(thickness1);
        if (thickness2 != null) detail.setThickness2(thickness2);
        if (thickness3 != null) detail.setThickness3(thickness3);
        if (thickness4 != null) detail.setThickness4(thickness4);
        if (thickness5 != null) detail.setThickness5(thickness5);
        if (thickness6 != null) detail.setThickness6(thickness6);
        if (thickness7 != null) detail.setThickness7(thickness7);
        if (thickness8 != null) detail.setThickness8(thickness8);
        if (thickness9 != null) detail.setThickness9(thickness9);
        if (thickness10 != null) detail.setThickness10(thickness10);
        detail.setRemark(firstNotBlank(detail.getRemark(), report.getRemark()));
    }

    private PressSlotIntermediateCounter calculateAdhesive2IntermediateCounter(List<HcAdhesive2ReportDO> reports) {
        BigDecimal inputQty = BigDecimal.ZERO;
        BigDecimal outputQty = BigDecimal.ZERO;
        for (HcAdhesive2ReportDO report : reports) {
            BigDecimal input = firstNonNullDecimal(report.getInputLength(), report.getOutputLength(), BigDecimal.ONE);
            inputQty = inputQty.add(zeroIfNull(input));
            String status = StrUtil.blankToDefault(report.getReportStatus(), "DRAFT");
            if ("CONFIRMED".equalsIgnoreCase(status) || "SUBMITTED".equalsIgnoreCase(status)) {
                BigDecimal output = firstNonNullDecimal(report.getOutputLength(), report.getInputLength(), BigDecimal.ONE);
                outputQty = outputQty.add(zeroIfNull(output));
            }
        }
        return new PressSlotIntermediateCounter(inputQty, outputQty);
    }

    private String resolveAdhesive2IntermediateBatchNo(List<HcAdhesive2ReportDO> reports,
                                                       HcPlanOrderOperationDO operation,
                                                       HcPlanOrderDO planOrder) {
        for (HcAdhesive2ReportDO report : reports) {
            String batchNo = firstNotBlank(report.getParentProductionBatchNo(), report.getSourceProductionBatchNo(),
                    report.getSourceBatchNo(), report.getProductionBatchNo());
            if (StrUtil.isNotBlank(batchNo)) {
                return normalizePressSlotMiddleBatchNo(batchNo);
            }
        }
        return normalizePressSlotMiddleBatchNo(firstNotBlank(operation.getParentProductionBatchNo(),
                operation.getProductionBatchNo(), operation.getBatchNo(),
                planOrder.getParentProductionBatchNo(), planOrder.getProductionBatchNo(), planOrder.getBatchNo()));
    }

    private void fillAdhesive2IntermediateRecord(HcAdhesive2IntermediateRecordDO record,
                                                 HcAdhesive2IntermediateSaveReqVO reqVO,
                                                 HcPlanOrderDO planOrder,
                                                 HcPlanOrderOperationDO operation,
                                                 List<HcAdhesive2ReportDO> operationReports,
                                                 PressSlotIntermediateCounter counter) {
        record.setPlanId(planOrder.getId());
        record.setPlanNo(planOrder.getPlanNo());
        record.setPlanOperationId(operation.getId());
        record.setRecordDate(reqVO.getRecordDate() == null ? LocalDateTime.now() : reqVO.getRecordDate());
        record.setModelCode(firstNotBlank(reqVO.getModelCode(), planOrder.getModelCode(), planOrder.getModelName()));
        record.setMaterialCode(firstNotBlank(reqVO.getMaterialCode(), planOrder.getMaterialCode()));
        record.setBatchNo(firstNotBlank(reqVO.getBatchNo(), resolveAdhesive2IntermediateBatchNo(operationReports, operation, planOrder)));
        record.setInputQty(counter.inputQty());
        record.setOutputQty(counter.outputQty());
        Map<String, Object> extra = new LinkedHashMap<>(parseRoughExtraMap(reqVO.getExtraJson()));
        record.setGlueBoardModel(firstNotBlank(reqVO.getGlueBoardModel(), toStringValue(extra.get("glueBoardModel"))));
        if (StrUtil.isNotBlank(reqVO.getGlueBoardWidthMm())) {
            extra.put("glueBoardWidthMm", reqVO.getGlueBoardWidthMm());
        }
        if (StrUtil.isNotBlank(reqVO.getGlueBoardAdhesionGf())) {
            extra.put("glueBoardAdhesionGf", reqVO.getGlueBoardAdhesionGf());
        }
        if (StrUtil.isNotBlank(record.getGlueBoardModel())) {
            extra.put("glueBoardModel", record.getGlueBoardModel());
        }
        writeImportAttachment(extra, reqVO.getImportAttachment());
        record.setFrontSliceNo(reqVO.getFrontSliceNo());
        record.setMiddleSliceNo(reqVO.getMiddleSliceNo());
        record.setEndSliceNo(reqVO.getEndSliceNo());
        record.setRecorderName(firstNotBlank(reqVO.getRecorderName(), SecurityFrameworkUtils.getLoginUserNickname()));
        String recordStatus = firstNotBlank(reqVO.getRecordStatus(), "RECORDED");
        record.setConfirmerName("CONFIRMED".equalsIgnoreCase(recordStatus)
                ? firstNotBlank(reqVO.getConfirmerName(), SecurityFrameworkUtils.getLoginUserNickname())
                : reqVO.getConfirmerName());
        record.setRecordStatus(recordStatus);
        record.setRemark(reqVO.getRemark());
        record.setExtraJson(JsonUtils.toJsonString(extra));
        record.setTenantId(planOrder.getTenantId());
    }

