    private void applyAdhesive2IntermediateStationFormMeta(HcAdhesive2IntermediateRespVO resp, String modelCode) {
        if (resp == null) {
            return;
        }
        HcStationFormDO stationForm = resolveAdhesive2StationFormConfig(PRESS_SLOT_INTERMEDIATE_FORM_TYPE, modelCode);
        Map<String, Object> schema = parsePressSlotStationFormSchema(stationForm);
        String stationFormName = stationForm == null ? ADHESIVE2_INTERMEDIATE_FORM_NAME
                : stripPressSlotDisplayName(firstNotBlank(resolveAdhesive2StationDisplayName(stationForm),
                stationForm.getFormName(), ADHESIVE2_INTERMEDIATE_FORM_NAME));
        resp.setStationFormId(stationForm == null ? null : stationForm.getId());
        resp.setStationFormCode(stationForm == null ? null : stationForm.getFormCode());
        resp.setStationFormName(stationForm == null ? null : stationForm.getFormName());
        resp.setStationFormDisplayName(stationFormName);
        resp.setStationFormSchemaJson(stationForm == null ? null : stationForm.getSchemaJson());
        resp.setStationFormProcessCode(stationForm == null ? null : stationForm.getProcessCode());
        resp.setTemplateCode(stationForm == null ? ADHESIVE2_INTERMEDIATE_FORM_CODE
                : firstNotBlank(stationForm.getFormCode(), ADHESIVE2_INTERMEDIATE_FORM_CODE));
        resp.setTemplateName(stationFormName);
        resp.setSourceExcel(firstNotBlank(
                toStringValue(schema.get("sourceExcel")),
                toStringValue(schema.get("sourceExcelFile"))));
        resp.setSourceSheet(firstNotBlank(
                toStringValue(schema.get("sourceSheet")),
                toStringValue(schema.get("sourceExcelSheet"))));
        String thicknessStandard = firstNotBlank(
                resp.getThicknessStandard(),
                toStringValue(schema.get("thicknessStandard")),
                toStringValue(schema.get("intermediateThicknessStandard")),
                ADHESIVE2_INTERMEDIATE_DEFAULT_THICKNESS_STANDARD);
        resp.setThicknessStandard(thicknessStandard);
        resp.setThicknessHeaderText(firstNotBlank(
                toStringValue(schema.get("thicknessHeaderText")),
                toStringValue(schema.get("thicknessColumnLabel")),
                "厚度/mm (" + thicknessStandard + ")"));
        resp.setThicknessColumnCount(firstNotNullInteger(
                resp.getThicknessColumnCount(),
                parseInteger(toStringValue(schema.get("thicknessColumnCount"))),
                parseInteger(toStringValue(schema.get("thicknessColumns"))),
                ADHESIVE2_INTERMEDIATE_DEFAULT_THICKNESS_COLUMN_COUNT));
        resp.setThicknessIntervalCm(firstNotNullInteger(
                resp.getThicknessIntervalCm(),
                parseInteger(toStringValue(schema.get("thicknessIntervalCm"))),
                parseInteger(toStringValue(schema.get("thicknessMeasureIntervalCm"))),
                ADHESIVE2_INTERMEDIATE_DEFAULT_THICKNESS_INTERVAL_CM));
        resp.setShowGlueBoardModel(readBooleanValue(schema.get("showGlueBoardModel"), true));
    }

    private Boolean readBooleanValue(Object value, Boolean defaultValue) {
        if (value == null) {
            return defaultValue;
        }
        if (value instanceof Boolean) {
            return (Boolean) value;
        }
        String text = StrUtil.trimToEmpty(String.valueOf(value));
        if (StrUtil.isBlank(text)) {
            return defaultValue;
        }
        return "true".equalsIgnoreCase(text) || "1".equals(text) || "Y".equalsIgnoreCase(text)
                || "YES".equalsIgnoreCase(text) || "是".equals(text);
    }

