    private List<HcPressSlotIntermediateDetailRespVO> mergeAdhesive2IntermediateDetails(
            List<HcPressSlotIntermediateDetailRespVO> existingDetails,
            List<HcPressSlotIntermediateDetailRespVO> markedDetails) {
        Map<String, HcPressSlotIntermediateDetailRespVO> merged = new LinkedHashMap<>();
        for (HcPressSlotIntermediateDetailRespVO detail : buildDefaultAdhesive2IntermediateDetails()) {
            merged.put(detail.getSamplePosition(), detail);
        }
        for (HcPressSlotIntermediateDetailRespVO detail : markedDetails == null
                ? List.<HcPressSlotIntermediateDetailRespVO>of() : markedDetails) {
            String key = StrUtil.blankToDefault(detail.getSamplePosition(), "ROW" + detail.getSortNo());
            merged.put(key, mergeAdhesive2IntermediateDetail(merged.get(key), detail));
        }
        for (HcPressSlotIntermediateDetailRespVO detail : existingDetails) {
            String key = StrUtil.blankToDefault(detail.getSamplePosition(), "ROW" + detail.getSortNo());
            merged.put(key, mergeAdhesive2IntermediateDetail(merged.get(key), detail));
        }
        return new ArrayList<>(merged.values());
    }

