    private HcAdhesiveSourceRespVO buildAdhesive2SourceResp(HcPressSlotReportDO source) {
        List<HcAdhesive2ReportDO> reports = hcAdhesive2ReportMapper.selectListBySourcePressSlotReportId(source.getId());
        boolean coaInspectionSubmitted = hasActiveAdhesive2CoaFai(source.getId());
        String downstreamStatus;
        if (coaInspectionSubmitted) {
            downstreamStatus = "COA_INSPECTION";
        } else if (reports.stream().anyMatch(item -> "SUBMITTED".equalsIgnoreCase(item.getReportStatus()))) {
            downstreamStatus = "CONSUMED";
        } else {
            downstreamStatus = reports.isEmpty() ? "AVAILABLE" : "PROCESSING";
        }
        String motherSegmentBatchNo = resolveAdhesive2MotherSegmentBatchNo(source);
        boolean sourceNg = isPressSlotSourceNg(source);
        return HcAdhesiveSourceRespVO.builder()
                .grindingSecondDetailId(source.getId())
                .grindingPlanId(source.getPlanId())
                .grindingPlanNo(source.getPlanNo())
                .grindingPlanOperationId(source.getPlanOperationId())
                .rowUid(String.valueOf(source.getId()))
                .motherBatchNo(motherSegmentBatchNo)
                .productionBatchNo(source.getProductionBatchNo())
                .parentProductionBatchNo(motherSegmentBatchNo)
                .modelCode(source.getModelCode())
                .segmentMark(resolveBatchSegmentMark(motherSegmentBatchNo))
                .processLength(BigDecimal.ONE)
                .lossLength(BigDecimal.ZERO)
                .outputLength(firstNonNullDecimal(source.getOutputLength(), BigDecimal.ONE))
                .napSampleLength(BigDecimal.ZERO)
                .selfCheck(source.getSelfCheck())
                .defectCode(source.getDefectCode())
                .operationName(firstNotBlank(source.getOperationName(), "压槽"))
                .processStage("PRESS_SLOT")
                .productQualityStatus(sourceNg ? PRODUCT_QUALITY_ABNORMAL : QUALITY_STATUS_NORMAL)
                .qualityLockReason(sourceNg ? firstNotBlank(source.getDefectCode(), "压槽自检NG") : null)
                .sourceMenuCode(SOURCE_MENU_CODE_PRESS_SLOT)
                .coaFlag(isPressSlotCoaFlag(source) || coaInspectionSubmitted)
                .extraJson(source.getExtraJson())
                .confirmStatus(source.getReportStatus())
                .confirmedBatchNo(source.getProductionBatchNo())
                .confirmTime(source.getConfirmerTime())
                .downstreamStatus(downstreamStatus)
                .qtime(hcQtimeEvaluationService.evaluatePressSlotToAdhesive2(
                        resolveBatchSegmentCompleteTime(source.getPlanOperationId(),
                                SOURCE_MENU_CODE_PRESS_SLOT_SEGMENT_COMPLETE,
                                motherSegmentBatchNo, source.getEndTime()),
                        resolveEarliestStartTime(reports),
                        firstNotBlank(source.getModelCode(), source.getMaterialCode(), source.getProductionBatchNo())))
                .build();
    }

    private boolean hasActiveAdhesive2CoaFai(Long sourcePressSlotReportId) {
        if (sourcePressSlotReportId == null) {
            return false;
        }
        QmsFaiOrderDO latestCoaFai = qmsFaiOrderMapper.selectOne(new LambdaQueryWrapperX<QmsFaiOrderDO>()
                .eq(QmsFaiOrderDO::getSourceModule, SOURCE_MENU_CODE_ADHESIVE2)
                .eq(QmsFaiOrderDO::getSourceReportId, sourcePressSlotReportId)
                .like(QmsFaiOrderDO::getSourceReportNo, "-COA-")
                .ne(QmsFaiOrderDO::getStatus, FAI_STATUS_CANCELED)
                .orderByDesc(QmsFaiOrderDO::getId)
                .last("LIMIT 1"));
        return latestCoaFai != null;
    }

    private boolean isPressSlotCoaFlag(HcPressSlotReportDO source) {
        if (source == null) {
            return false;
        }
        Object raw = parseRoughExtraMap(source.getExtraJson()).get("coaFlag");
        if (raw instanceof Boolean value) {
            return value;
        }
        String text = StrUtil.trimToEmpty(raw == null ? null : String.valueOf(raw));
        return "Y".equalsIgnoreCase(text) || "TRUE".equalsIgnoreCase(text) || "1".equals(text);
    }

    private String resolveAdhesive2MotherSegmentBatchNo(HcPressSlotReportDO source) {
        String sourceBatchNo = normalizePressSlotMiddleBatchNo(source.getSourceBatchNo());
        if (isSegmentBatchNo(sourceBatchNo)) {
            return sourceBatchNo;
        }
        String parentBatchNo = normalizePressSlotMiddleBatchNo(source.getParentProductionBatchNo());
        if (isSegmentBatchNo(parentBatchNo)) {
            return parentBatchNo;
        }
        String sourceProductionBatchNo = normalizePressSlotMiddleBatchNo(source.getSourceProductionBatchNo());
        if (isSegmentBatchNo(sourceProductionBatchNo)) {
            return sourceProductionBatchNo;
        }
        String productionBatchNo = normalizePressSlotMiddleBatchNo(source.getProductionBatchNo());
        if (isSegmentBatchNo(productionBatchNo)) {
            return productionBatchNo;
        }
        return firstNotBlank(sourceProductionBatchNo, productionBatchNo, parentBatchNo, sourceBatchNo);
    }

    private String resolveAdhesive2MotherSegmentBatchNo(HcAdhesive2ReportDO report) {
        if (report == null) {
            return "";
        }
        String sourceBatchNo = normalizePressSlotMiddleBatchNo(report.getSourceBatchNo());
        if (isSegmentBatchNo(sourceBatchNo)) {
            return sourceBatchNo;
        }
        String parentBatchNo = normalizePressSlotMiddleBatchNo(report.getParentProductionBatchNo());
        if (isSegmentBatchNo(parentBatchNo)) {
            return parentBatchNo;
        }
        String sourceProductionBatchNo = normalizePressSlotMiddleBatchNo(report.getSourceProductionBatchNo());
        if (isSegmentBatchNo(sourceProductionBatchNo)) {
            return sourceProductionBatchNo;
        }
        String productionBatchNo = normalizePressSlotMiddleBatchNo(report.getProductionBatchNo());
        if (isSegmentBatchNo(productionBatchNo)) {
            return productionBatchNo;
        }
        return firstNotBlank(parentBatchNo, sourceBatchNo, sourceProductionBatchNo, productionBatchNo);
    }

    private boolean isSegmentBatchNo(String batchNo) {
        return StrUtil.isNotBlank(batchNo) && batchNo.toUpperCase().matches(".*[PQRS]$");
    }

    private String resolveBatchSegmentMark(String batchNo) {
        String text = StrUtil.trimToEmpty(batchNo).toUpperCase();
        if (StrUtil.isBlank(text)) {
            return "";
        }
        String mark = text.substring(text.length() - 1);
        return "PQRS".contains(mark) ? mark : "";
    }

    private boolean hasAdhesive2TailSelection(HcAdhesive2ReportDO report) {
        return report != null && StrUtil.isNotBlank(report.getActualSizeRule())
                && StrUtil.isNotBlank(report.getActualSizeSuffix());
    }

    private boolean isAdhesive2ReportPrinted(HcAdhesive2ReportDO report) {
        if (report == null) {
            return false;
        }
        Map<String, Object> extra = parseRoughExtraMap(report.getExtraJson());
        String printStatus = StrUtil.trimToEmpty(String.valueOf(extra.get("printStatus")));
        if ("PRINTED".equalsIgnoreCase(printStatus) || "已打印".equals(printStatus)) {
            return true;
        }
        Object printCount = extra.get("printCount");
        if (printCount instanceof Number number) {
            return number.intValue() > 0;
        }
        return NumberUtil.parseInt(String.valueOf(printCount), 0) > 0;
    }

    private String normalizeAdhesive2ActualSizeRule(String actualSizeRule) {
        String normalized = StrUtil.trimToEmpty(actualSizeRule).toUpperCase().replace(" ", "");
        if (normalized.contains("775") || "A".equals(normalized)) {
            return "775mm";
        }
        if (normalized.contains("740") || "B".equals(normalized)) {
            return "740mm";
        }
        return "";
    }

    private String getAdhesive2TailSuffix(String actualSizeRule) {
        return "775mm".equals(normalizeAdhesive2ActualSizeRule(actualSizeRule)) ? "A"
                : "740mm".equals(normalizeAdhesive2ActualSizeRule(actualSizeRule)) ? "B" : "";
    }

    private String buildAdhesive2TailBatchNo(String sourceProductionBatchNo, String actualSizeRule) {
        String suffix = getAdhesive2TailSuffix(actualSizeRule);
        String source = StrUtil.trimToEmpty(sourceProductionBatchNo).toUpperCase();
        if (StrUtil.isBlank(source) || StrUtil.isBlank(suffix)) {
            return "";
        }
        return source.replaceFirst("([PQRS]\\d{3})[AB]$", "$1") + suffix;
    }

