    private HcAdhesiveGlueBoardUsageRespVO buildAdhesiveGlueBoardUsageResp(HcAdhesiveGlueBoardUsageDO usage) {
        HcAdhesiveGlueBoardUsageRespVO resp = new HcAdhesiveGlueBoardUsageRespVO();
        resp.setId(usage.getId());
        resp.setPlanId(usage.getPlanId());
        resp.setPlanNo(usage.getPlanNo());
        resp.setPlanOperationId(usage.getPlanOperationId());
        resp.setOperationCode(usage.getOperationCode());
        resp.setOperationName(usage.getOperationName());
        resp.setEquipmentId(usage.getEquipmentId());
        resp.setEquipmentCode(usage.getEquipmentCode());
        resp.setEquipmentName(usage.getEquipmentName());
        resp.setGlueBoardStockId(usage.getGlueBoardStockId());
        resp.setGlueBoardMaterialCode(usage.getGlueBoardMaterialCode());
        resp.setGlueBoardBatchNo(usage.getGlueBoardBatchNo());
        resp.setStockMeasureMode(usage.getStockMeasureMode());
        resp.setReceiveStartPosition(usage.getReceiveStartPosition());
        resp.setReceiveLength(usage.getReceiveLength());
        resp.setReceiveCount(usage.getReceiveCount());
        resp.setAqcSampleLength(usage.getAqcSampleLength());
        BigDecimal effectiveConsumedLength = resolveGlueBoardConsumedLength(usage);
        BigDecimal effectiveAvailableStart = resolveGlueBoardAvailableStartPosition(usage, effectiveConsumedLength);
        BigDecimal effectiveAvailableLength = resolveGlueBoardAvailableLength(usage, effectiveConsumedLength,
                effectiveAvailableStart);
        resp.setConsumedLength(effectiveConsumedLength);
        resp.setConsumedCount(usage.getConsumedCount());
        resp.setLossLength(usage.getLossLength());
        resp.setLossCount(usage.getLossCount());
        resp.setAvailableStartPosition(effectiveAvailableStart);
        resp.setAvailableLength(effectiveAvailableLength);
        resp.setAvailableCount(usage.getAvailableCount());
        resp.setReturnedStartPosition(firstNonNullDecimal(usage.getReturnedStartPosition(), effectiveAvailableStart).max(effectiveAvailableStart));
        resp.setReturnedLength(usage.getReturnedLength());
        resp.setReturnedCount(usage.getReturnedCount());
        HcAdhesiveGlueBoardStockDO stock = null;
        if (usage.getGlueBoardStockId() != null) {
            stock = hcAdhesiveGlueBoardStockMapper.selectById(usage.getGlueBoardStockId());
            if (stock != null && !Boolean.TRUE.equals(stock.getDeleted())) {
                resp.setGlueBoardModel(stock.getGlueBoardModel());
                QmsFaiOrderDO latestGlueBoardFai = selectLatestGlueBoardFaiForUsage(usage, stock);
                if (latestGlueBoardFai != null) {
                    resp.setInspectionSubmitTime(latestGlueBoardFai.getSubmissionTime());
                    resp.setLatestInspectionId(latestGlueBoardFai.getId());
                    resp.setLatestInspectionNo(latestGlueBoardFai.getFaiNo());
                    resp.setLatestInspectionResult(latestGlueBoardFai.getJudgment());
                } else {
                    resp.setInspectionSubmitTime(null);
                    resp.setLatestInspectionId(null);
                    resp.setLatestInspectionNo(null);
                    resp.setLatestInspectionResult(null);
                }
                resp.setLifetimeMode(stock.getLifetimeMode());
                resp.setLifetimeLimitLength(stock.getLifetimeLimitLength());
                resp.setLifetimeLimitCount(stock.getLifetimeLimitCount());
                resp.setLifeUsedLength(stock.getLifeUsedLength());
                resp.setLifeUsedCount(stock.getLifeUsedCount());
            }
        }
        resp.setUsageStatus(usage.getUsageStatus());
        resp.setQualityStatus(stock != null && !Boolean.TRUE.equals(stock.getDeleted())
                ? stock.getQualityStatus()
                : usage.getQualityStatus());
        resp.setQualityLockStartPosition(usage.getQualityLockStartPosition());
        resp.setQualityLockReason(usage.getQualityLockReason());
        resp.setRecordDate(usage.getRecordDate());
        resp.setRecorderId(usage.getRecorderId());
        resp.setRecorderName(usage.getRecorderName());
        resp.setRecorderTime(usage.getRecorderTime());
        resp.setCreateTime(usage.getCreateTime());
        resp.setUpdateTime(usage.getUpdateTime());
        HcAdhesiveAqcTaskDO latestAqcTask = hcAdhesiveAqcTaskMapper.selectLatestByUsageAndDate(
                usage.getId(), ADHESIVE_AQC_DAILY, usage.getRecordDate());
        resp.setLatestAqcTask(latestAqcTask == null ? null : buildAdhesiveAqcTaskResp(latestAqcTask));
        return resp;
    }

    private QmsFaiOrderDO selectLatestGlueBoardFaiForUsage(HcAdhesiveGlueBoardUsageDO usage,
                                                           HcAdhesiveGlueBoardStockDO stock) {
        String processCategory = resolveGlueBoardFaiProcessCategory(usage);
        if (StrUtil.isBlank(processCategory)) {
            return null;
        }
        String operationNameKeyword = GLUE_BOARD_FAI_PROCESS_ADHESIVE2.equals(processCategory)
                ? GLUE_BOARD_FAI_OPERATION_ADHESIVE2
                : GLUE_BOARD_FAI_OPERATION_ADHESIVE1;
        Long stockId = stock == null ? normalizePositiveId(usage.getGlueBoardStockId()) : stock.getId();
        if (stockId == null) {
            return null;
        }
        return qmsFaiOrderMapper.selectLatestGlueBoardFai(stockId, null, null,
                processCategory, operationNameKeyword);
    }

    private String resolveGlueBoardFaiProcessCategory(HcAdhesiveGlueBoardUsageDO usage) {
        if (usage == null) {
            return null;
        }
        if (isAdhesive2UsageScope(usage.getOperationCode(), usage.getOperationName())) {
            return GLUE_BOARD_FAI_PROCESS_ADHESIVE2;
        }
        if (isAdhesiveUsageScope(usage.getOperationCode(), usage.getOperationName())) {
            return GLUE_BOARD_FAI_PROCESS_ADHESIVE1;
        }
        return null;
    }

