    boolean isGlueBoardUsageAllowedForReport(HcAdhesiveGlueBoardUsageDO usage,
                                             HcPlanOrderOperationDO operation,
                                             String processCode) {
        if (usage == null || operation == null) {
            return false;
        }
        Long usagePlanOperationId = normalizePositiveId(usage.getPlanOperationId());
        if (PROCESS_CODE_ADHESIVE2.equalsIgnoreCase(processCode)) {
            if (!"ACTIVE".equalsIgnoreCase(StrUtil.blankToDefault(usage.getUsageStatus(), ""))
                    || !isGlueBoardUsageInProcessScope(usage, PROCESS_CODE_ADHESIVE2)
                    || !hasBoundEquipment(operation)) {
                return false;
            }
            Long usageEquipmentId = normalizePositiveId(usage.getEquipmentId());
            Long operationEquipmentId = normalizePositiveId(operation.getEquipmentId());
            if (usageEquipmentId != null && operationEquipmentId != null) {
                return Objects.equals(usageEquipmentId, operationEquipmentId);
            }
            if (StrUtil.isNotBlank(usage.getEquipmentCode()) && StrUtil.isNotBlank(operation.getEquipmentCode())) {
                return StrUtil.equalsIgnoreCase(StrUtil.trim(usage.getEquipmentCode()), StrUtil.trim(operation.getEquipmentCode()));
            }
            return false;
        }
        if (Objects.equals(usagePlanOperationId, operation.getId())) {
            return true;
        }
        if (!"ACTIVE".equalsIgnoreCase(StrUtil.blankToDefault(usage.getUsageStatus(), ""))
                || !isGlueBoardUsageInProcessScope(usage, processCode)) {
            return false;
        }
        if (usage.getEquipmentId() != null && operation.getEquipmentId() != null) {
            return Objects.equals(usage.getEquipmentId(), operation.getEquipmentId());
        }
        if (StrUtil.isNotBlank(usage.getEquipmentCode()) && StrUtil.isNotBlank(operation.getEquipmentCode())) {
            return StrUtil.equalsIgnoreCase(StrUtil.trim(usage.getEquipmentCode()), StrUtil.trim(operation.getEquipmentCode()));
        }
        return usagePlanOperationId == null;
    }

    private boolean isGlueBoardUsageInProcessScope(HcAdhesiveGlueBoardUsageDO usage, String processCode) {
        if (usage == null) {
            return false;
        }
        String operationCode = StrUtil.trimToEmpty(usage.getOperationCode());
        String operationName = StrUtil.trimToEmpty(usage.getOperationName());
        if ("ADHESIVE2".equalsIgnoreCase(processCode)) {
            return "ADHESIVE2".equalsIgnoreCase(operationCode)
                    || "OP-ADHESIVE2".equalsIgnoreCase(operationCode)
                    || operationName.contains("粘胶2")
                    || operationName.contains("背胶");
        }
        if ("ADHESIVE".equalsIgnoreCase(processCode)) {
            if (StrUtil.isBlank(operationCode) && StrUtil.isBlank(operationName)
                    && normalizePositiveId(usage.getPlanOperationId()) == null) {
                return true;
            }
            return "ADHESIVE".equalsIgnoreCase(operationCode)
                    || operationName.contains("粘双面胶")
                    || operationName.contains("粘胶1")
                    || operationName.contains("粘胶一");
        }
        return true;
    }

    private HcAdhesiveAqcTaskDO validateReportAqcTask(HcPlanOrderDO planOrder,
                                                      HcPlanOrderOperationDO operation,
                                                      HcGrindingSecondDetailDO sourceDetail,
                                                      HcAdhesiveReportSaveReqVO reqVO,
                                                      String actionText) {
        String motherBatchNo = resolveAdhesiveMotherBatch(sourceDetail, reqVO);
        HcAdhesiveAqcTaskDO task = null;
        Long aqcTaskId = reqVO == null ? null : reqVO.getAqcTaskId();
        if (aqcTaskId != null) {
            task = hcAdhesiveAqcTaskMapper.selectById(aqcTaskId);
        }
        if (task == null) {
            task = selectLatestReportAqcTaskByBatch(operation.getId(), motherBatchNo);
        }
        String batchText = StrUtil.blankToDefault(motherBatchNo, firstNotBlank(
                sourceDetail == null ? null : sourceDetail.getProductionBatchNo(),
                planOrder == null ? null : planOrder.getProductionBatchNo(), "当前母卷"));
        if (task == null || Boolean.TRUE.equals(task.getDeleted())
                || !Objects.equals(task.getPlanOperationId(), operation.getId())) {
            throw invalidParamException("母卷 " + batchText + " 尚未提交粘胶检验，不能" + actionText);
        }
        if (!ADHESIVE_AQC_REPORT.equalsIgnoreCase(StrUtil.blankToDefault(task.getTaskType(), ""))) {
            throw invalidParamException("母卷 " + batchText + " 粘胶检验送检单类型不正确，不能" + actionText);
        }
        if (StrUtil.isNotBlank(motherBatchNo)
                && !isAdhesiveReportAqcBatchMatch(motherBatchNo, task.getGlueBoardBatchNo())) {
            throw invalidParamException("母卷 " + batchText + " 未匹配到对应的粘胶检验送检单，不能" + actionText);
        }
        String taskStatus = StrUtil.trimToEmpty(task.getTaskStatus()).toUpperCase();
        String feedbackResult = StrUtil.trimToEmpty(task.getFeedbackResult()).toUpperCase();
        if ("PASSED".equals(taskStatus) || "OK".equals(taskStatus) || "OK".equals(feedbackResult) || "PASSED".equals(feedbackResult)) {
            return task;
        }
        if ("FAILED".equals(taskStatus) || "REJECTED".equals(taskStatus) || "ABNORMAL".equals(taskStatus)
                || "NG".equals(feedbackResult) || "FAILED".equals(feedbackResult)) {
            throw invalidParamException("母卷 " + batchText + " 粘胶检验异常，请处理后再" + actionText);
        }
        throw invalidParamException("母卷 " + batchText + " 粘胶检验待完成，不能" + actionText);
    }

    private HcAdhesiveAqcTaskDO selectLatestReportAqcTaskByBatch(Long planOperationId, String batchNo) {
        if (planOperationId == null || StrUtil.isBlank(batchNo)) {
            return null;
        }
        return hcAdhesiveAqcTaskMapper.selectListByPlanOperationId(planOperationId)
                .stream()
                .filter(task -> ADHESIVE_AQC_REPORT.equalsIgnoreCase(StrUtil.blankToDefault(task.getTaskType(), "")))
                .filter(task -> isAdhesiveReportAqcBatchMatch(batchNo, task.getGlueBoardBatchNo()))
                .findFirst()
                .orElse(null);
    }

    private String resolveAdhesiveMotherBatch(HcGrindingSecondDetailDO sourceDetail, HcAdhesiveReportSaveReqVO reqVO) {
        String batchNo = firstNotBlank(reqVO == null ? null : reqVO.getSourceBatchNo(),
                sourceDetail == null ? null : sourceDetail.getMotherBatchNo(),
                reqVO == null ? null : reqVO.getParentProductionBatchNo(),
                sourceDetail == null ? null : sourceDetail.getParentProductionBatchNo(),
                reqVO == null ? null : reqVO.getSourceProductionBatchNo(),
                reqVO == null ? null : reqVO.getProductionBatchNo(),
                sourceDetail == null ? null : sourceDetail.getProductionBatchNo(),
                sourceDetail == null ? null : sourceDetail.getConfirmedBatchNo());
        return resolveSlittingMotherBatch(batchNo);
    }

    private HcAdhesiveReportDO resolveAdhesiveConfirmTarget(HcAdhesiveReportDO anchorReport,
                                                            String scannedBatchNo) {
        String motherBatchNo = resolveSlittingMotherBatch(anchorReport);
        return hcAdhesiveReportMapper.selectListByPlanOperationId(anchorReport.getPlanOperationId())
                .stream()
                .filter(item -> isSameSlittingMother(motherBatchNo, item))
                .filter(item -> isAdhesiveReportScanBatchMatch(scannedBatchNo, item))
                .filter(item -> !"SUBMITTED".equalsIgnoreCase(StrUtil.blankToDefault(item.getReportStatus(), "DRAFT")))
                .sorted((left, right) -> {
                    boolean leftUnconfirmed = !"CONFIRMED".equalsIgnoreCase(StrUtil.blankToDefault(left.getReportStatus(), "DRAFT"));
                    boolean rightUnconfirmed = !"CONFIRMED".equalsIgnoreCase(StrUtil.blankToDefault(right.getReportStatus(), "DRAFT"));
                    if (leftUnconfirmed != rightUnconfirmed) {
                        return leftUnconfirmed ? -1 : 1;
                    }
                    return Long.compare(right.getId(), left.getId());
                })
                .findFirst()
                .orElseThrow(() -> invalidParamException("未在当前母卷批次下找到扫码对应的粘胶报工记录"));
    }

    private boolean isAdhesiveReportScanBatchMatch(String scannedBatchNo, HcAdhesiveReportDO report) {
        return isAdhesiveReportExactBatchMatch(scannedBatchNo, report.getProductionBatchNo())
                || isAdhesiveReportExactBatchMatch(scannedBatchNo, report.getSourceProductionBatchNo());
    }

    private boolean isAdhesiveReportExactBatchMatch(String left, String right) {
        String leftText = StrUtil.trimToEmpty(left);
        String rightText = StrUtil.trimToEmpty(right);
        if (StrUtil.isBlank(leftText) || StrUtil.isBlank(rightText)) {
            return false;
        }
        return StrUtil.equalsIgnoreCase(leftText, rightText)
                || StrUtil.equalsIgnoreCase(normalizeSlittingSegmentBatchNo(leftText),
                normalizeSlittingSegmentBatchNo(rightText));
    }

    private boolean isAdhesiveReportAqcBatchMatch(String left, String right) {
        String leftText = StrUtil.trimToEmpty(left);
        String rightText = StrUtil.trimToEmpty(right);
        if (StrUtil.isBlank(leftText) || StrUtil.isBlank(rightText)) {
            return false;
        }
        return StrUtil.equalsIgnoreCase(leftText, rightText)
                || StrUtil.equalsIgnoreCase(normalizeSlittingSegmentBatchNo(leftText),
                normalizeSlittingSegmentBatchNo(rightText))
                || StrUtil.equalsIgnoreCase(resolveSlittingMotherBatch(leftText), resolveSlittingMotherBatch(rightText));
    }

    private void validateGlueBoardLossRange(HcAdhesiveGlueBoardUsageDO usage, BigDecimal startPosition,
                                            BigDecimal length) {
        if (STOCK_MEASURE_COUNT.equals(normalizeStockMeasureMode(usage.getStockMeasureMode(), null))) {
            if (zeroIfNull(length).compareTo(BigDecimal.ZERO) <= 0) {
                throw invalidParamException("辅料异常数量必须大于0");
            }
            return;
        }
        BigDecimal start = zeroIfNull(startPosition);
        BigDecimal lossLength = zeroIfNull(length);
        if (lossLength.compareTo(BigDecimal.ZERO) <= 0) {
            throw invalidParamException("胶板损耗长度必须大于0");
        }
        BigDecimal receiveStart = zeroIfNull(usage.getReceiveStartPosition());
        BigDecimal usableStart = receiveStart.add(zeroIfNull(usage.getAqcSampleLength()));
        BigDecimal receiveEnd = receiveStart.add(zeroIfNull(usage.getReceiveLength()));
        BigDecimal end = start.add(lossLength);
        if (start.compareTo(usableStart) < 0) {
            throw invalidParamException("损耗起位置不能小于AQC首检后可用起位置" + formatDecimal(usableStart) + "m");
        }
        if (end.compareTo(receiveEnd) > 0) {
            throw invalidParamException("损耗结束位置不能超过本次领用终点" + formatDecimal(receiveEnd) + "m");
        }
        List<HcAdhesiveReportDO> reports = hcAdhesiveReportMapper.selectListByGlueBoardUsageId(usage.getId());
        for (HcAdhesiveReportDO report : reports) {
            BigDecimal existedStart = report.getGlueBoardStartPosition();
            BigDecimal existedLength = report.getGlueBoardUseLength();
            if (existedStart == null || existedLength == null) {
                continue;
            }
            BigDecimal existedEnd = existedStart.add(existedLength);
            boolean overlap = start.compareTo(existedEnd) < 0 && end.compareTo(existedStart) > 0;
            if (overlap) {
                throw invalidParamException("损耗区间与已有粘胶报工重叠："
                        + formatDecimal(existedStart) + "-" + formatDecimal(existedEnd) + "m");
            }
        }
        Map<String, Object> extra = parseRoughExtraMap(usage.getExtraJson());
        for (Map<String, Object> record : extractGlueBoardLossRecords(extra)) {
            BigDecimal existedStart = decimalFromObject(record.get("startPosition"));
            BigDecimal existedLength = firstNonNullDecimal(
                    decimalFromObject(record.get("lossLength")),
                    decimalFromObject(record.get("length")));
            if (existedStart == null || existedLength == null) {
                continue;
            }
            BigDecimal existedEnd = existedStart.add(existedLength);
            boolean overlap = start.compareTo(existedEnd) < 0 && end.compareTo(existedStart) > 0;
            if (overlap) {
                throw invalidParamException("损耗区间与已有损耗报备重叠："
                        + formatDecimal(existedStart) + "-" + formatDecimal(existedEnd) + "m");
            }
        }
    }

    /**
     * 胶板已消耗长度由三类独立记录组成：粘胶1报工、粘胶2报工、耗材领用台账消耗。
     * 不能只以报工记录回算，否则会覆盖已登记的台账消耗并导致下一次起米回退。
     */
    private BigDecimal resolveGlueBoardConsumedLength(HcAdhesiveGlueBoardUsageDO usage) {
        if (usage == null || usage.getId() == null
                || STOCK_MEASURE_COUNT.equals(normalizeStockMeasureMode(usage.getStockMeasureMode(), null))) {
            return usage == null ? BigDecimal.ZERO : zeroIfNull(usage.getConsumedLength());
        }
        BigDecimal reportConsumedLength = hcAdhesiveReportMapper.selectListByGlueBoardUsageId(usage.getId())
                .stream()
                .map(HcAdhesiveReportDO::getGlueBoardUseLength)
                .filter(Objects::nonNull)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        reportConsumedLength = reportConsumedLength.add(hcAdhesive2ReportMapper
                .selectListByGlueBoardUsageId(usage.getId())
                .stream()
                .map(HcAdhesive2ReportDO::getGlueBoardUseLength)
                .filter(Objects::nonNull)
                .reduce(BigDecimal.ZERO, BigDecimal::add));
        return reportConsumedLength.add(
                hcToolingConsumableConsumeMapper.sumConsumeQtyByGlueBoardUsageId(usage.getId()));
    }

    private BigDecimal resolveGlueBoardAvailableStartPosition(HcAdhesiveGlueBoardUsageDO usage) {
        return resolveGlueBoardAvailableStartPosition(usage, resolveGlueBoardConsumedLength(usage));
    }

    private BigDecimal resolveGlueBoardAvailableStartPosition(HcAdhesiveGlueBoardUsageDO usage,
                                                              BigDecimal effectiveConsumedLength) {
        if (usage == null) {
            return BigDecimal.ZERO;
        }
        BigDecimal storedAvailableStart = zeroIfNull(usage.getAvailableStartPosition());
        if (STOCK_MEASURE_COUNT.equals(normalizeStockMeasureMode(usage.getStockMeasureMode(), null))) {
            return storedAvailableStart;
        }
        BigDecimal calculatedAvailableStart = zeroIfNull(usage.getReceiveStartPosition())
                .add(zeroIfNull(usage.getAqcSampleLength()))
                .add(zeroIfNull(effectiveConsumedLength))
                .add(zeroIfNull(usage.getLossLength()));
        return storedAvailableStart.compareTo(calculatedAvailableStart) < 0
                ? calculatedAvailableStart : storedAvailableStart;
    }

    private BigDecimal resolveGlueBoardAvailableLength(HcAdhesiveGlueBoardUsageDO usage) {
        BigDecimal effectiveConsumedLength = resolveGlueBoardConsumedLength(usage);
        return resolveGlueBoardAvailableLength(usage, effectiveConsumedLength,
                resolveGlueBoardAvailableStartPosition(usage, effectiveConsumedLength));
    }

    private BigDecimal resolveGlueBoardAvailableLength(HcAdhesiveGlueBoardUsageDO usage,
                                                        BigDecimal effectiveConsumedLength,
                                                        BigDecimal effectiveAvailableStart) {
        if (usage == null) {
            return BigDecimal.ZERO;
        }
        if (STOCK_MEASURE_COUNT.equals(normalizeStockMeasureMode(usage.getStockMeasureMode(), null))) {
            return zeroIfNull(usage.getAvailableLength());
        }
        BigDecimal receiveStart = zeroIfNull(usage.getReceiveStartPosition());
        BigDecimal receiveEnd = receiveStart.add(zeroIfNull(usage.getReceiveLength()));
        BigDecimal calculatedAvailableLength = zeroIfNull(usage.getReceiveLength())
                .subtract(zeroIfNull(usage.getAqcSampleLength()))
                .subtract(zeroIfNull(effectiveConsumedLength))
                .subtract(zeroIfNull(usage.getLossLength()))
                .max(BigDecimal.ZERO);
        BigDecimal storedAvailableLength = usage.getAvailableLength();
        BigDecimal effectiveAvailableLength = storedAvailableLength == null
                ? calculatedAvailableLength
                : storedAvailableLength.min(calculatedAvailableLength);
        BigDecimal maximumAvailableLength = receiveEnd.subtract(zeroIfNull(effectiveAvailableStart))
                .max(BigDecimal.ZERO);
        return effectiveAvailableLength.min(maximumAvailableLength);
    }

    @SuppressWarnings("unchecked")
    private List<Map<String, Object>> extractGlueBoardLossRecords(Map<String, Object> extra) {
        Object raw = extra == null ? null : extra.get("lossRecords");
        if (!(raw instanceof List<?> list)) {
            return new ArrayList<>();
        }
        List<Map<String, Object>> result = new ArrayList<>();
        for (Object item : list) {
            if (item instanceof Map<?, ?> map) {
                result.add(new LinkedHashMap<>((Map<String, Object>) map));
            }
        }
        return result;
    }

    private BigDecimal decimalFromObject(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof BigDecimal decimal) {
            return decimal;
        }
        if (value instanceof Number number) {
            return BigDecimal.valueOf(number.doubleValue());
        }
        String text = String.valueOf(value);
        if (StrUtil.isBlank(text)) {
            return null;
        }
        try {
            return new BigDecimal(text);
        } catch (NumberFormatException ex) {
            return null;
        }
    }

    private void validateGlueBoardRange(HcAdhesiveGlueBoardUsageDO usage, BigDecimal startPosition,
                                        BigDecimal length, Long currentReportId) {
        if (STOCK_MEASURE_COUNT.equals(normalizeStockMeasureMode(usage.getStockMeasureMode(), null))) {
            BigDecimal useCount = zeroIfNull(length);
            if (useCount.compareTo(BigDecimal.ZERO) <= 0) {
                throw invalidParamException("辅料使用数量必须大于0");
            }
            if (QUALITY_STATUS_ABNORMAL.equalsIgnoreCase(StrUtil.blankToDefault(usage.getQualityStatus(), ""))
                    || PRODUCT_QUALITY_LOCKED.equalsIgnoreCase(StrUtil.blankToDefault(usage.getQualityStatus(), ""))) {
                throw invalidParamException("辅料批次存在质量异常或已锁定，不能报工");
            }
            return;
        }
        BigDecimal start = zeroIfNull(startPosition);
        BigDecimal useLength = zeroIfNull(length);
        if (useLength.compareTo(BigDecimal.ZERO) <= 0) {
            throw invalidParamException("胶板使用长度必须大于0");
        }
        BigDecimal receiveStart = zeroIfNull(usage.getReceiveStartPosition());
        BigDecimal usableStart = receiveStart.add(zeroIfNull(usage.getAqcSampleLength()));
        BigDecimal receiveEnd = receiveStart.add(zeroIfNull(usage.getReceiveLength()));
        BigDecimal end = start.add(useLength);
        if (start.compareTo(usableStart) < 0) {
            throw invalidParamException("胶板使用起位置不能小于AQC首检后可用起位置" + formatDecimal(usableStart) + "m");
        }
        if (end.compareTo(receiveEnd) > 0) {
            throw invalidParamException("胶板使用结束位置不能超过本次领用终点" + formatDecimal(receiveEnd) + "m");
        }
        BigDecimal lockStart = usage.getQualityLockStartPosition();
        if (QUALITY_STATUS_ABNORMAL.equalsIgnoreCase(StrUtil.blankToDefault(usage.getQualityStatus(), ""))
                && lockStart != null && end.compareTo(lockStart) > 0) {
            throw invalidParamException("胶板批次从" + formatDecimal(lockStart) + "m起存在AQC异常锁定，不能报工");
        }
        List<HcAdhesiveReportDO> reports = hcAdhesiveReportMapper.selectListByGlueBoardUsageId(usage.getId());
        for (HcAdhesiveReportDO report : reports) {
            if (currentReportId != null && Objects.equals(currentReportId, report.getId())) {
                continue;
            }
            BigDecimal existedStart = report.getGlueBoardStartPosition();
            BigDecimal existedLength = report.getGlueBoardUseLength();
            if (existedStart == null || existedLength == null) {
                continue;
            }
            BigDecimal existedEnd = existedStart.add(existedLength);
            boolean overlap = start.compareTo(existedEnd) < 0 && end.compareTo(existedStart) > 0;
            if (overlap) {
                throw invalidParamException("胶板使用位置与已有粘胶报工重叠："
                        + formatDecimal(existedStart) + "-" + formatDecimal(existedEnd) + "m");
            }
        }
        Map<String, Object> extra = parseRoughExtraMap(usage.getExtraJson());
        for (Map<String, Object> record : extractGlueBoardLossRecords(extra)) {
            BigDecimal existedStart = decimalFromObject(record.get("startPosition"));
            BigDecimal existedLength = firstNonNullDecimal(
                    decimalFromObject(record.get("lossLength")),
                    decimalFromObject(record.get("length")));
            if (existedStart == null || existedLength == null) {
                continue;
            }
            BigDecimal existedEnd = existedStart.add(existedLength);
            boolean overlap = start.compareTo(existedEnd) < 0 && end.compareTo(existedStart) > 0;
            if (overlap) {
                throw invalidParamException("胶板使用位置与已有损耗报备重叠："
                        + formatDecimal(existedStart) + "-" + formatDecimal(existedEnd) + "m");
            }
        }
    }

    private void applyGlueBoardUsageDelta(HcAdhesiveGlueBoardUsageDO usage, BigDecimal length, boolean deduct) {
        BigDecimal delta = zeroIfNull(length);
        if (!deduct || delta.compareTo(BigDecimal.ZERO) <= 0) {
            return;
        }
        if (STOCK_MEASURE_COUNT.equals(normalizeStockMeasureMode(usage.getStockMeasureMode(), null))) {
            return;
        }
        BigDecimal availableLength = resolveGlueBoardAvailableLength(usage);
        if (availableLength.compareTo(delta) < 0) {
            throw invalidParamException("胶板剩余长度不足，当前可用" + formatDecimal(availableLength) + "m");
        }
    }

    private void recalculateGlueBoardUsage(Long glueBoardUsageId) {
        if (glueBoardUsageId == null) {
            return;
        }
        HcAdhesiveGlueBoardUsageDO usage = hcAdhesiveGlueBoardUsageMapper.selectById(glueBoardUsageId);
        if (usage == null || Boolean.TRUE.equals(usage.getDeleted())) {
            return;
        }
        if (STOCK_MEASURE_COUNT.equals(normalizeStockMeasureMode(usage.getStockMeasureMode(), null))) {
            BigDecimal consumedCount = hcAdhesiveReportMapper.selectListByGlueBoardUsageId(glueBoardUsageId)
                    .stream()
                    .map(HcAdhesiveReportDO::getGlueBoardUseLength)
                    .filter(Objects::nonNull)
                    .reduce(BigDecimal.ZERO, BigDecimal::add);
            consumedCount = consumedCount.add(hcAdhesive2ReportMapper.selectListByGlueBoardUsageId(glueBoardUsageId)
                    .stream()
                    .map(HcAdhesive2ReportDO::getGlueBoardUseLength)
                    .filter(Objects::nonNull)
                    .reduce(BigDecimal.ZERO, BigDecimal::add));
            BigDecimal receiveCount = zeroIfNull(usage.getReceiveCount());
            BigDecimal lossCount = zeroIfNull(usage.getLossCount());
            BigDecimal availableCount = receiveCount.subtract(lossCount);
            if (availableCount.compareTo(BigDecimal.ZERO) < 0) {
                throw invalidParamException("辅料异常数量超过本次更换数量");
            }
            hcAdhesiveGlueBoardUsageMapper.updateById(HcAdhesiveGlueBoardUsageDO.builder()
                    .id(usage.getId())
                    .consumedCount(consumedCount)
                    .availableCount(availableCount)
                    .returnedCount(availableCount)
                    .build());
            return;
        }
        BigDecimal consumedLength = resolveGlueBoardConsumedLength(usage);
        BigDecimal receiveStart = zeroIfNull(usage.getReceiveStartPosition());
        BigDecimal aqcLength = zeroIfNull(usage.getAqcSampleLength());
        BigDecimal receiveLength = zeroIfNull(usage.getReceiveLength());
        BigDecimal lossLength = zeroIfNull(usage.getLossLength());
        BigDecimal availableLength = receiveLength.subtract(aqcLength).subtract(consumedLength).subtract(lossLength);
        if (availableLength.compareTo(BigDecimal.ZERO) < 0) {
            throw invalidParamException("胶板使用长度超过本次领用可用长度");
        }
        BigDecimal availableStart = receiveStart.add(aqcLength).add(consumedLength).add(lossLength);
        hcAdhesiveGlueBoardUsageMapper.updateById(HcAdhesiveGlueBoardUsageDO.builder()
                .id(usage.getId())
                .consumedLength(consumedLength)
                .availableStartPosition(availableStart)
                .availableLength(availableLength)
                .returnedStartPosition(availableStart)
                .returnedLength(availableLength)
                .build());
    }

    private void lockAbnormalAdhesiveReports(Long glueBoardUsageId, BigDecimal lockStart, String reason) {
        if (glueBoardUsageId == null || lockStart == null) {
            return;
        }
        List<HcAdhesiveReportDO> reports = hcAdhesiveReportMapper.selectListByGlueBoardUsageId(glueBoardUsageId);
        for (HcAdhesiveReportDO report : reports) {
            BigDecimal reportStart = report.getGlueBoardStartPosition();
            if (reportStart == null || reportStart.compareTo(lockStart) < 0) {
                continue;
            }
            hcAdhesiveReportMapper.updateById(HcAdhesiveReportDO.builder()
                    .id(report.getId())
                    .productQualityStatus(PRODUCT_QUALITY_ABNORMAL)
                    .qualityLockReason(reason)
                    .build());
        }
    }

    private GlueBoardInspectionAbnormalMeta resolveGlueBoardInspectionAbnormalMeta(HcAdhesiveGlueBoardUsageDO usage,
                                                                                  LocalDateTime reportTime) {
        if (usage == null || reportTime == null || normalizePositiveId(usage.getGlueBoardStockId()) == null) {
            return GlueBoardInspectionAbnormalMeta.normal();
        }
        QmsFaiOrderDO latestCompletedOrder = qmsFaiOrderMapper.selectLatestCompletedGlueBoardFaiBefore(
                usage.getGlueBoardStockId(), reportTime);
        if (latestCompletedOrder == null || !"NG".equalsIgnoreCase(latestCompletedOrder.getJudgment())) {
            return GlueBoardInspectionAbnormalMeta.normal();
        }
        return GlueBoardInspectionAbnormalMeta.abnormal(buildGlueBoardInspectionAbnormalReason(latestCompletedOrder));
    }

    private String buildGlueBoardInspectionAbnormalReason(QmsFaiOrderDO ngOrder) {
        if (ngOrder == null || StrUtil.isBlank(ngOrder.getFaiNo())) {
            return "胶板检验不合格";
        }
        return "胶板检验不合格：" + ngOrder.getFaiNo();
    }

    private LocalDate resolveAdhesiveReportDate(HcAdhesiveReportDO report) {
        if (report == null) {
            return null;
        }
        if (report.getReportDate() != null) {
            return report.getReportDate();
        }
        if (report.getStartTime() != null) {
            return report.getStartTime().toLocalDate();
        }
        if (report.getRecorderTime() != null) {
            return report.getRecorderTime().toLocalDate();
        }
        return report.getCreateTime() == null ? null : report.getCreateTime().toLocalDate();
    }

    private LocalDate resolveAdhesive2ReportDate(HcAdhesive2ReportDO report) {
        if (report == null) {
            return null;
        }
        if (report.getReportDate() != null) {
            return report.getReportDate();
        }
        if (report.getStartTime() != null) {
            return report.getStartTime().toLocalDate();
        }
        if (report.getRecorderTime() != null) {
            return report.getRecorderTime().toLocalDate();
        }
        return report.getCreateTime() == null ? null : report.getCreateTime().toLocalDate();
    }

    private boolean isAbnormalAdhesiveProduct(HcAdhesiveReportDO report) {
        String qualityStatus = StrUtil.blankToDefault(report.getProductQualityStatus(), QUALITY_STATUS_NORMAL);
        return PRODUCT_QUALITY_ABNORMAL.equalsIgnoreCase(qualityStatus)
                || PRODUCT_QUALITY_LOCKED.equalsIgnoreCase(qualityStatus);
    }

    private AdhesivePositionRange normalizeAdhesivePositionRange(HcAdhesiveReportSaveReqVO reqVO,
                                                                 BigDecimal inputLength,
                                                                 BigDecimal sourceLength) {
        if (inputLength == null || inputLength.compareTo(BigDecimal.ZERO) <= 0) {
            throw invalidParamException("粘胶加工米数必须大于0");
        }
        BigDecimal startPosition = reqVO.getStartPosition();
        BigDecimal endPosition = reqVO.getEndPosition();
        if (startPosition == null && endPosition == null) {
            startPosition = BigDecimal.ZERO;
            endPosition = inputLength;
        } else if (startPosition == null) {
            startPosition = endPosition.subtract(inputLength);
        } else if (endPosition == null) {
            endPosition = startPosition.add(inputLength);
        }
        if (startPosition.compareTo(BigDecimal.ZERO) < 0) {
            throw invalidParamException("粘胶加工起始位置不能小于0");
        }
        if (endPosition.compareTo(startPosition) <= 0) {
            throw invalidParamException("粘胶加工结束位置必须大于起始位置");
        }
        BigDecimal rangeLength = endPosition.subtract(startPosition);
        if (rangeLength.subtract(inputLength).abs().compareTo(new BigDecimal("0.001")) > 0) {
            throw invalidParamException("粘胶加工米数必须等于结束位置-起始位置");
        }
        if (sourceLength != null && sourceLength.compareTo(BigDecimal.ZERO) > 0
                && endPosition.compareTo(sourceLength) > 0) {
            throw invalidParamException("粘胶加工结束位置不能超出来源可加工长度" + formatDecimal(sourceLength) + "m");
        }
        return new AdhesivePositionRange(startPosition, endPosition);
    }

    private void validateAdhesivePositionNotOverlap(Long sourceGrindingSecondDetailId,
                                                    Long currentReportId,
                                                    AdhesivePositionRange newRange) {
        List<HcAdhesiveReportDO> reports = hcAdhesiveReportMapper.selectListBySourceDetailId(sourceGrindingSecondDetailId);
        for (HcAdhesiveReportDO report : reports) {
            if (currentReportId != null && Objects.equals(currentReportId, report.getId())) {
                continue;
            }
            AdhesivePositionRange existedRange = buildExistingAdhesiveRange(report);
            if (existedRange == null) {
                continue;
            }
            boolean overlap = newRange.start.compareTo(existedRange.end) < 0
                    && newRange.end.compareTo(existedRange.start) > 0;
            if (overlap) {
                String batchNo = firstNotBlank(report.getProductionBatchNo(), report.getSourceProductionBatchNo(), "已有记录");
                throw invalidParamException("粘胶加工位置与已有报工重叠：" + batchNo + " "
                        + formatDecimal(existedRange.start) + "-" + formatDecimal(existedRange.end) + "m");
            }
        }
    }

    private void refreshAdhesiveSourceDownstreamState(Long sourceGrindingSecondDetailId) {
        if (sourceGrindingSecondDetailId == null) {
            return;
        }
        List<HcAdhesiveReportDO> reports = hcAdhesiveReportMapper.selectListBySourceDetailId(sourceGrindingSecondDetailId);
        if (reports.isEmpty()) {
            hcGrindingSecondDetailMapper.clearDownstreamStateById(sourceGrindingSecondDetailId);
            return;
        }
        HcAdhesiveReportDO latestReport = reports.get(reports.size() - 1);
        boolean allSubmitted = reports.stream().allMatch(report -> {
            String status = StrUtil.blankToDefault(report.getReportStatus(), "DRAFT");
            return "SUBMITTED".equalsIgnoreCase(status);
        });
        hcGrindingSecondDetailMapper.updateDownstreamStateWithoutReportId(
                sourceGrindingSecondDetailId,
                allSubmitted ? "CONSUMED" : "PROCESSING",
                latestReport.getPlanId(),
                latestReport.getPlanOperationId());
    }

    private AdhesivePositionRange buildExistingAdhesiveRange(HcAdhesiveReportDO report) {
        BigDecimal inputLength = zeroIfNull(firstNonNullDecimal(report.getInputLength(), report.getOutputLength()));
        BigDecimal startPosition = report.getStartPosition();
        BigDecimal endPosition = report.getEndPosition();
        if (startPosition == null && endPosition == null) {
            if (inputLength.compareTo(BigDecimal.ZERO) <= 0) {
                return null;
            }
            startPosition = BigDecimal.ZERO;
            endPosition = inputLength;
        } else if (startPosition == null) {
            startPosition = endPosition.subtract(inputLength);
        } else if (endPosition == null) {
            endPosition = startPosition.add(inputLength);
        }
        if (endPosition.compareTo(startPosition) <= 0) {
            return null;
        }
        return new AdhesivePositionRange(startPosition, endPosition);
    }

    private HcSlittingSourceRespVO buildSlittingSourceResp(HcAdhesiveReportDO report,
                                                           HcGrindingSecondDetailDO sourceDetail,
                                                           List<HcSlittingSliceRecordDO> slices) {
        return buildSlittingSourceResp(report, sourceDetail, slices, null, false, null);
    }

    private HcSlittingSourceRespVO buildSlittingSourceResp(HcAdhesiveReportDO report,
                                                           HcGrindingSecondDetailDO sourceDetail,
                                                           List<HcSlittingSliceRecordDO> slices,
                                                           HcPlanOrderInventoryLockDO sourceLock,
                                                           boolean restrictToLockQty) {
        return buildSlittingSourceResp(report, sourceDetail, slices, sourceLock, restrictToLockQty, null);
    }

    private HcSlittingSourceRespVO buildSlittingSourceResp(HcAdhesiveReportDO report,
                                                           HcGrindingSecondDetailDO sourceDetail,
                                                           List<HcSlittingSliceRecordDO> slices,
                                                           HcPlanOrderInventoryLockDO sourceLock,
                                                           boolean restrictToLockQty,
                                                           HcPlanOrderOperationDO operation) {
        int confirmedCount = (int) slices.stream()
                .filter(item -> "CONFIRMED".equalsIgnoreCase(item.getScanStatus()))
                .count();
        String segmentBatchNo = resolveSlittingSegmentBatchNo(report, sourceDetail);
        String segmentMark = resolveSlittingSegmentMark(report, sourceDetail);
        BigDecimal outputLength = firstNonNullDecimal(report.getOutputLength(), report.getInputLength());
        BigDecimal motherWetOutputLength = resolveSlittingMotherWetOutputLength(report, sourceDetail);
        BigDecimal availableSourceLength = resolveSlittingAvailableSourceLength(report, outputLength, slices);
        if (sourceLock != null) {
            BigDecimal lockRemainingQty = calculateWipLockRemainingQty(sourceLock);
            availableSourceLength = availableSourceLength.min(lockRemainingQty).max(BigDecimal.ZERO);
            if (restrictToLockQty) {
                outputLength = zeroIfNull(outputLength).min(lockRemainingQty).max(BigDecimal.ZERO);
            }
        }
        BigDecimal sourceStartPosition = sourceDetail == null ? null : sourceDetail.getStartPosition();
        BigDecimal sourceEndPosition = sourceStartPosition == null ? null : sourceStartPosition.add(zeroIfNull(outputLength));
        return HcSlittingSourceRespVO.builder()
                .adhesiveReportId(report.getId())
                .adhesivePlanNo(report.getPlanNo())
                .adhesivePlanOperationId(report.getPlanOperationId())
                .sourceBatchNo(report.getSourceBatchNo())
                .sourceProductionBatchNo(segmentBatchNo)
                .segmentBatchNo(segmentBatchNo)
                .segmentMark(segmentMark)
                .productionBatchNo(report.getProductionBatchNo())
                .adhesiveProductionBatchNo(report.getProductionBatchNo())
                .parentProductionBatchNo(report.getParentProductionBatchNo())
                .materialCode(report.getMaterialCode())
                .materialName(report.getMaterialName())
                .modelCode(report.getModelCode())
                .status(resolveSlittingSourceStatus(report, slices, operation))
                .sourceStartPosition(sourceStartPosition)
                .sourceEndPosition(sourceEndPosition)
                .outputLength(outputLength)
                .motherWetOutputLength(motherWetOutputLength)
                .availableSourceLength(availableSourceLength)
                .sliceCount(slices.size())
                .confirmedSliceCount(confirmedCount)
                .qtime(hcQtimeEvaluationService.evaluateAdhesiveToSlitting(
                        resolveBatchSegmentCompleteTime(report.getPlanOperationId(),
                                SOURCE_MENU_CODE_ADHESIVE_SEGMENT_COMPLETE,
                                firstNotBlank(report.getSourceProductionBatchNo(), segmentBatchNo,
                                        report.getProductionBatchNo()), report.getEndTime()),
                        resolveEarliestCreateTime(slices),
                        firstNotBlank(report.getModelCode(), report.getMaterialCode(), report.getProductionBatchNo())))
                .build();
    }

    private LocalDateTime resolveSlittingSourceCompleteTime(HcAdhesiveReportDO source) {
        if (source == null) {
            return null;
        }
        Object value = parseRoughExtraMap(source.getExtraJson()).get("slittingSourceCompleteTime");
        if (value == null || StrUtil.isBlank(String.valueOf(value))) {
            return null;
        }
        try {
            return LocalDateTime.parse(String.valueOf(value), DATETIME_FORMATTER);
        } catch (RuntimeException ignored) {
            return null;
        }
    }

    /**
     * 优先使用“本段完工”生成的一条批次记录；旧数据没有批次记录时才兼容原片级结束时间。
     */
    private LocalDateTime resolveBatchSegmentCompleteTime(Long planOperationId,
                                                          String sourceMenuCode,
                                                          String batchNo,
                                                          LocalDateTime legacyEndTime) {
        if (planOperationId == null || StrUtil.isBlank(batchNo)) {
            return legacyEndTime;
        }
        HcProcessReportDO batchComplete = hcProcessReportMapper.selectOne(
                new LambdaQueryWrapperX<HcProcessReportDO>()
                        .eq(HcProcessReportDO::getPlanOperationId, planOperationId)
                        .eq(HcProcessReportDO::getSourceMenuCode, sourceMenuCode)
                        .eq(HcProcessReportDO::getBatchNo, batchNo)
                        .eq(HcProcessReportDO::getDeleted, false)
                        .orderByDesc(HcProcessReportDO::getEndTime)
                        .orderByDesc(HcProcessReportDO::getId)
                        .last("LIMIT 1"));
        return batchComplete == null || batchComplete.getEndTime() == null
                ? legacyEndTime : batchComplete.getEndTime();
    }

    private LocalDateTime resolveEarliestCreateTime(List<HcSlittingSliceRecordDO> slices) {
        return slices.stream()
                .map(HcSlittingSliceRecordDO::getCreateTime)
                .filter(Objects::nonNull)
                .min(LocalDateTime::compareTo)
                .orElse(null);
    }

    private LocalDateTime resolveEarliestStartTime(List<? extends Object> reports) {
        return reports.stream()
                .map(report -> {
                    if (report instanceof HcPressSlotReportDO pressSlotReport) {
                        return pressSlotReport.getStartTime();
                    }
                    if (report instanceof HcAdhesive2ReportDO adhesive2Report) {
                        return adhesive2Report.getStartTime();
                    }
                    return null;
                })
                .filter(Objects::nonNull)
                .min(LocalDateTime::compareTo)
                .orElse(null);
    }

    private BigDecimal resolveSlittingMotherWetOutputLength(HcAdhesiveReportDO report,
                                                            HcGrindingSecondDetailDO sourceDetail) {
        String motherBatchNo = resolveSlittingMotherBatch(firstNotBlank(
                report == null ? null : resolveSlittingMotherBatch(report),
                sourceDetail == null ? null : sourceDetail.getMotherBatchNo(),
                sourceDetail == null ? null : sourceDetail.getParentProductionBatchNo(),
                sourceDetail == null ? null : sourceDetail.getProductionBatchNo()));
        if (StrUtil.isBlank(motherBatchNo)) {
            return null;
        }
        List<HcProcessReportDO> wetReports = hcProcessReportMapper.selectList(new LambdaQueryWrapperX<HcProcessReportDO>()
                .eq(HcProcessReportDO::getDeleted, false)
                .eq(HcProcessReportDO::getSourceMenuCode, SOURCE_MENU_CODE_WET)
                .eq(HcProcessReportDO::getReportType, REPORT_TYPE_END)
                .and(wrapper -> wrapper
                        .eq(HcProcessReportDO::getProductionBatchNo, motherBatchNo)
                        .or()
                        .eq(HcProcessReportDO::getBatchNo, motherBatchNo)
                        .or()
                        .eq(HcProcessReportDO::getParentProductionBatchNo, motherBatchNo)
                        .or()
                        .eq(HcProcessReportDO::getParentBatchNo, motherBatchNo))
                .orderByDesc(HcProcessReportDO::getReportDate)
                .orderByDesc(HcProcessReportDO::getId));
        if (CollUtil.isEmpty(wetReports)) {
            return null;
        }
        Map<LocalDate, HcProcessReportDO> latestByReportDate = new LinkedHashMap<>();
        for (HcProcessReportDO wetReport : wetReports) {
            latestByReportDate.putIfAbsent(wetReport.getReportDate(), wetReport);
        }
        BigDecimal totalOutputLength = latestByReportDate.values().stream()
                .map(HcProcessReportDO::getGoodQty)
                .filter(Objects::nonNull)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        return totalOutputLength.compareTo(BigDecimal.ZERO) > 0 ? totalOutputLength : null;
    }

    private List<HcPlanOrderInventoryLockDO> selectActiveSlittingSourceWipLocks(Long planOperationId) {
        if (planOperationId == null) {
            return Collections.emptyList();
        }
        return hcPlanOrderInventoryLockMapper.selectListByPlanOperationId(planOperationId).stream()
                .filter(this::isActivePlanWipLock)
                .filter(lock -> StrUtil.equalsIgnoreCase(SOURCE_TABLE_ADHESIVE_REPORT, lock.getSourceTable()))
                .filter(lock -> lock.getSourceId() != null)
                .toList();
    }

    private Map<Long, HcPlanOrderInventoryLockDO> buildSlittingSourceLockMap(List<HcPlanOrderInventoryLockDO> sourceLocks) {
        if (sourceLocks == null || sourceLocks.isEmpty()) {
            return Collections.emptyMap();
        }
        Map<Long, HcPlanOrderInventoryLockDO> lockMap = new LinkedHashMap<>();
        for (HcPlanOrderInventoryLockDO lock : sourceLocks) {
            Long sourceId = lock.getSourceId();
            if (sourceId == null) {
                continue;
            }
            HcPlanOrderInventoryLockDO existed = lockMap.get(sourceId);
            if (existed == null || calculateWipLockRemainingQty(lock).compareTo(calculateWipLockRemainingQty(existed)) > 0) {
                lockMap.put(sourceId, lock);
            }
        }
        return lockMap;
    }

    private boolean isSlittingSourceProductionBatchMatched(HcAdhesiveReportDO report, String productionBatchNo) {
        if (StrUtil.isBlank(productionBatchNo)) {
            return true;
        }
        return isSameBatch(productionBatchNo, report == null ? null : report.getProductionBatchNo())
                || isSameBatch(productionBatchNo, report == null ? null : report.getSourceProductionBatchNo())
                || isSameBatch(productionBatchNo, report == null ? null : report.getSourceBatchNo())
                || isSameBatch(productionBatchNo, report == null ? null : report.getParentProductionBatchNo());
    }

    private void validateSlittingSourceBelongsToPlanOrLock(HcAdhesiveReportDO sourceReport,
                                                           HcPlanOrderDO planOrder,
                                                           HcPlanOrderInventoryLockDO sourceLock) {
        if (sourceReport == null || planOrder == null) {
            return;
        }
        if (Objects.equals(sourceReport.getPlanId(), planOrder.getId())) {
            return;
        }
        if (isActivePlanWipLock(sourceLock)
                && StrUtil.equalsIgnoreCase(SOURCE_TABLE_ADHESIVE_REPORT, sourceLock.getSourceTable())
                && Objects.equals(sourceReport.getId(), sourceLock.getSourceId())) {
            return;
        }
        throw invalidParamException("当前分切计划未挂接该来源粘胶1中间品，请先在生产计划详情挂接中间边库库存");
    }

    private BigDecimal resolveSlittingAvailableSourceLength(HcAdhesiveReportDO report,
                                                            BigDecimal sourceLength,
                                                            List<HcSlittingSliceRecordDO> slices) {
        BigDecimal storedRemainingLength = report == null ? null : report.getSlittingRemainingLength();
        if (storedRemainingLength != null) {
            return storedRemainingLength.max(BigDecimal.ZERO);
        }
        return calculateSlittingAvailableSourceLength(sourceLength, slices);
    }

    private void initializeSlittingSourceRemainingLengthIfAbsent(HcAdhesiveReportDO sourceReport) {
        if (sourceReport == null || sourceReport.getId() == null || sourceReport.getSlittingRemainingLength() != null) {
            return;
        }
        BigDecimal sourceLength = zeroIfNull(firstNonNullDecimal(sourceReport.getOutputLength(), sourceReport.getInputLength()));
        BigDecimal confirmedUsedLength = hcSlittingSliceRecordMapper.selectListBySourceAdhesiveReportId(sourceReport.getId())
                .stream()
                .filter(slice -> "CONFIRMED".equalsIgnoreCase(StrUtil.blankToDefault(slice.getScanStatus(), "")))
                .map(this::resolveSlittingSliceUsedLength)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal remainingLength = sourceLength.subtract(confirmedUsedLength).max(BigDecimal.ZERO);
        if (hcAdhesiveReportMapper.initializeSlittingRemainingLengthIfAbsent(sourceReport.getId(), remainingLength) > 0) {
            sourceReport.setSlittingRemainingLength(remainingLength);
        }
    }

    private BigDecimal calculateSlittingAvailableSourceLength(BigDecimal sourceLength, List<HcSlittingSliceRecordDO> slices) {
        BigDecimal normalizedSourceLength = zeroIfNull(sourceLength);
        if (normalizedSourceLength.compareTo(BigDecimal.ZERO) <= 0) {
            return BigDecimal.ZERO;
        }
        BigDecimal usedLength = slices == null ? BigDecimal.ZERO : slices.stream()
                .filter(slice -> "CONFIRMED".equalsIgnoreCase(StrUtil.blankToDefault(slice.getScanStatus(), "")))
                .map(this::resolveSlittingSliceUsedLength)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal remainingLength = normalizedSourceLength.subtract(usedLength).max(BigDecimal.ZERO);
        return remainingLength.max(BigDecimal.ZERO);
    }

    private BigDecimal resolveSlittingSliceUsedLength(HcSlittingSliceRecordDO slice) {
        if (slice == null) {
            return BigDecimal.ZERO;
        }
        BigDecimal sliceLength = slice.getSliceLength();
        if (sliceLength != null && sliceLength.compareTo(BigDecimal.ZERO) > 0) {
            return sliceLength;
        }
        BigDecimal startPosition = slice.getStartPosition();
        BigDecimal endPosition = slice.getEndPosition();
        if (startPosition != null && endPosition != null && endPosition.compareTo(startPosition) > 0) {
            return endPosition.subtract(startPosition);
        }
        return BigDecimal.ZERO;
    }

    private String resolveSlittingSourceStatus(HcAdhesiveReportDO report, List<HcSlittingSliceRecordDO> slices) {
        Map<String, Object> extra = parseRoughExtraMap(report == null ? null : report.getExtraJson());
        Object status = extra.get(SLITTING_SOURCE_STATUS_KEY);
        if (status != null && SLITTING_SOURCE_COMPLETED.equalsIgnoreCase(String.valueOf(status))) {
            return SLITTING_SOURCE_COMPLETED;
        }
        return slices == null || slices.isEmpty() ? "PENDING" : "IN_PROGRESS";
    }

    private String resolveSlittingSourceStatus(HcAdhesiveReportDO report,
                                               List<HcSlittingSliceRecordDO> slices,
                                               HcPlanOrderOperationDO operation) {
        String operationStatus = StrUtil.trimToEmpty(operation == null ? null : operation.getOperationStatus()).toUpperCase();
        if (OP_STATUS_PAUSED.equals(operationStatus)) {
            return ADHESIVE_TASK_STATUS_PAUSED;
        }
        if (OP_STATUS_CANCELLED.equals(operationStatus) || "CANCELED".equals(operationStatus)) {
            return ADHESIVE_TASK_STATUS_CANCELLED;
        }
        if (OP_STATUS_FINISHED.equals(operationStatus)) {
            return ADHESIVE_TASK_STATUS_COMPLETED;
        }
        return resolveSlittingSourceStatus(report, slices);
    }

