    private Map<Long, HcPressSlotReportDO> loadSlittingDownstreamFeedbackMap(
            List<HcSlittingSliceRecordDO> records) {
        List<Long> sourceIds = records.stream()
                .map(HcSlittingSliceRecordDO::getId)
                .filter(Objects::nonNull)
                .distinct()
                .toList();
        Map<Long, HcPressSlotReportDO> feedbackMap = new HashMap<>();
        for (HcPressSlotReportDO report : hcPressSlotReportMapper.selectListBySourceSliceIds(sourceIds)) {
            if (report.getSourceSlittingSliceId() == null
                    || !isPreProcessSelfCheckFeedback(report.getSelfCheck(), report.getExtraJson(), PROCESS_CODE_SLITTING)) {
                continue;
            }
            feedbackMap.putIfAbsent(report.getSourceSlittingSliceId(), report);
        }
        return feedbackMap;
    }

