    private Map<Long, String> loadSlittingEditBlockedReasonMap(List<HcSlittingSliceRecordDO> records) {
        List<Long> sourceIds = records.stream()
                .map(HcSlittingSliceRecordDO::getId)
                .filter(Objects::nonNull)
                .distinct()
                .toList();
        Map<Long, String> result = new HashMap<>();
        Map<String, Long> sourceIdByBatchNo = records.stream()
                .filter(record -> record.getId() != null && StrUtil.isNotBlank(record.getSliceSerialNo()))
                .collect(Collectors.toMap(
                        record -> StrUtil.trim(record.getSliceSerialNo()).toUpperCase(),
                        HcSlittingSliceRecordDO::getId,
                        (left, right) -> left));
        for (QmsFaiOrderDO faiOrder : qmsFaiOrderMapper.selectListByProductBatchNos(
                new ArrayList<>(sourceIdByBatchNo.keySet()), SOURCE_MENU_CODE_PRESS_SLOT, PROCESS_CODE_PRESS_SLOT)) {
            Long sourceId = sourceIdByBatchNo.get(StrUtil.trimToEmpty(faiOrder.getProductBatchNo()).toUpperCase());
            if (sourceId != null) {
                result.putIfAbsent(sourceId, buildSlittingInspectionEditBlockedReason(faiOrder));
            }
        }
        for (HcPressSlotReportDO report : hcPressSlotReportMapper.selectListBySourceSliceIds(sourceIds)) {
            if (report.getSourceSlittingSliceId() != null && isDownstreamReportConfirmed(report.getReportStatus())) {
                result.putIfAbsent(report.getSourceSlittingSliceId(), buildSlittingEditBlockedReason(report));
            }
        }
        return result;
    }

    private Map<Long, String> loadPressSlotEditBlockedReasonMap(List<HcPressSlotReportDO> records) {
        List<Long> sourceIds = records.stream()
                .map(HcPressSlotReportDO::getId)
                .filter(Objects::nonNull)
                .distinct()
                .toList();
        Map<Long, String> result = new HashMap<>();
        for (QmsFaiOrderDO faiOrder : qmsFaiOrderMapper.selectListBySourceReportIds(
                sourceIds, SOURCE_MENU_CODE_ADHESIVE2, PROCESS_CODE_ADHESIVE2)) {
            if (faiOrder.getSourceReportId() != null) {
                result.putIfAbsent(faiOrder.getSourceReportId(), buildPressSlotInspectionEditBlockedReason(faiOrder));
            }
        }
        for (HcAdhesive2ReportDO report : hcAdhesive2ReportMapper.selectListBySourcePressSlotReportIds(sourceIds)) {
            if (report.getSourcePressSlotReportId() != null && isDownstreamReportConfirmed(report.getReportStatus())) {
                result.putIfAbsent(report.getSourcePressSlotReportId(), buildPressSlotEditBlockedReason(report));
            }
        }
        return result;
    }

    private Map<Long, String> loadAdhesive2EditBlockedReasonMap(List<HcAdhesive2ReportDO> records) {
        List<Long> sourceIds = records.stream()
                .map(HcAdhesive2ReportDO::getId)
                .filter(Objects::nonNull)
                .distinct()
                .toList();
        Map<Long, String> result = new HashMap<>();
        List<HcCutRoundReportDO> downstreamReports = hcCutRoundReportMapper.selectListBySourceAdhesive2ReportIds(sourceIds);
        Map<Long, HcCutRoundReportDO> downstreamReportById = downstreamReports.stream()
                .filter(report -> report.getId() != null)
                .collect(Collectors.toMap(HcCutRoundReportDO::getId, report -> report, (left, right) -> left));
        for (QmsFqcOrderDO fqcOrder : qmsFqcOrderMapper.selectListBySourceReportIds(
                SOURCE_TYPE_CUT_ROUND, new ArrayList<>(downstreamReportById.keySet()))) {
            HcCutRoundReportDO downstreamReport = downstreamReportById.get(fqcOrder.getSourceReportId());
            if (downstreamReport != null && downstreamReport.getSourceAdhesive2ReportId() != null) {
                result.putIfAbsent(downstreamReport.getSourceAdhesive2ReportId(),
                        buildAdhesive2InspectionEditBlockedReason(fqcOrder, downstreamReport));
            }
        }
        for (HcCutRoundReportDO report : downstreamReports) {
            if (report.getSourceAdhesive2ReportId() != null && isDownstreamReportConfirmed(report.getReportStatus())) {
                result.putIfAbsent(report.getSourceAdhesive2ReportId(), buildAdhesive2EditBlockedReason(report));
            }
        }
        return result;
    }

    private void validateSlittingOverwriteAllowed(HcSlittingSliceRecordDO record) {
        if (record == null || record.getId() == null) {
            return;
        }
        if (StrUtil.isNotBlank(record.getSliceSerialNo())) {
            qmsFaiOrderMapper.selectListByProductBatchNos(
                            Collections.singletonList(StrUtil.trim(record.getSliceSerialNo())),
                            SOURCE_MENU_CODE_PRESS_SLOT, PROCESS_CODE_PRESS_SLOT)
                    .stream()
                    .findFirst()
                    .ifPresent(faiOrder -> {
                        throw invalidParamException(buildSlittingInspectionEditBlockedReason(faiOrder));
                    });
        }
        hcPressSlotReportMapper.selectListBySourceSliceId(record.getId()).stream()
                .filter(report -> isDownstreamReportConfirmed(report.getReportStatus()))
                .findFirst()
                .ifPresent(report -> {
                    throw invalidParamException(buildSlittingEditBlockedReason(report));
                });
    }

    private void validatePressSlotOverwriteAllowed(HcPressSlotReportDO report) {
        if (report == null || report.getId() == null) {
            return;
        }
        qmsFaiOrderMapper.selectListBySourceReportIds(
                        Collections.singletonList(report.getId()), SOURCE_MENU_CODE_ADHESIVE2, PROCESS_CODE_ADHESIVE2)
                .stream()
                .findFirst()
                .ifPresent(faiOrder -> {
                    throw invalidParamException(buildPressSlotInspectionEditBlockedReason(faiOrder));
                });
        hcAdhesive2ReportMapper.selectListBySourcePressSlotReportId(report.getId()).stream()
                .filter(item -> isDownstreamReportConfirmed(item.getReportStatus()))
                .findFirst()
                .ifPresent(item -> {
                    throw invalidParamException(buildPressSlotEditBlockedReason(item));
                });
    }

    private void validateAdhesive2OverwriteAllowed(HcAdhesive2ReportDO report) {
        if (report == null || report.getId() == null) {
            return;
        }
        List<HcCutRoundReportDO> downstreamReports = hcCutRoundReportMapper.selectListBySourceAdhesive2ReportId(report.getId());
        Map<Long, HcCutRoundReportDO> downstreamReportById = downstreamReports.stream()
                .filter(item -> item.getId() != null)
                .collect(Collectors.toMap(HcCutRoundReportDO::getId, item -> item, (left, right) -> left));
        qmsFqcOrderMapper.selectListBySourceReportIds(
                        SOURCE_TYPE_CUT_ROUND, new ArrayList<>(downstreamReportById.keySet()))
                .stream()
                .findFirst()
                .ifPresent(fqcOrder -> {
                    throw invalidParamException(buildAdhesive2InspectionEditBlockedReason(
                            fqcOrder, downstreamReportById.get(fqcOrder.getSourceReportId())));
                });
        downstreamReports.stream()
                .filter(item -> isDownstreamReportConfirmed(item.getReportStatus()))
                .findFirst()
                .ifPresent(item -> {
                    throw invalidParamException(buildAdhesive2EditBlockedReason(item));
                });
    }

    private boolean isDownstreamReportConfirmed(String reportStatus) {
        String normalized = StrUtil.trimToEmpty(reportStatus).toUpperCase();
        return "CONFIRMED".equals(normalized) || "SUBMITTED".equals(normalized);
    }

