    private SlittingSliceSizeRule resolveSlittingGenerateSliceSizeRule(HcSlittingSliceGenerateReqVO reqVO,
                                                                       HcPlanOrderDO planOrder) {
        SlittingSliceSizeRule requestedRule = resolveSlittingSliceSizeRule(reqVO.getSizeCode(), reqVO.getSizeName(), false);
        if (requestedRule != null) {
            return requestedRule;
        }
        return resolveSlittingSliceSizeRule(
                planOrder == null ? null : planOrder.getSizeSpec(),
                planOrder == null ? null : planOrder.getSizeName(),
                true);
    }

    private SlittingSliceSizeRule resolveSlittingConfirmSliceSizeRule(HcSlittingSliceConfirmReqVO reqVO,
                                                                      HcSlittingSliceRecordDO record) {
        SlittingSliceSizeRule requestedRule = resolveSlittingSliceSizeRule(reqVO.getSizeCode(), reqVO.getSizeName(), false);
        if (requestedRule != null) {
            return requestedRule;
        }
        return resolveSlittingSliceSizeRule(
                record == null ? null : record.getSizeCode(),
                record == null ? null : record.getSizeName(),
                true);
    }

    private SlittingSliceSizeRule resolveSlittingSliceSizeRule(String sizeCode,
                                                               String sizeName,
                                                               boolean blankAsUnknown) {
        String text = StrUtil.trimToEmpty(firstNotBlank(sizeCode, sizeName)).toUpperCase();
        if (StrUtil.isBlank(text)) {
            return blankAsUnknown ? SlittingSliceSizeRule.unknown() : null;
        }
        if (isUnknownSlittingSliceSize(text)) {
            return SlittingSliceSizeRule.unknown();
        }
        if ("A".equals(text) || text.contains("775")) {
            return new SlittingSliceSizeRule("775", "775mm", "A");
        }
        if ("B".equals(text) || text.contains("740")) {
            return new SlittingSliceSizeRule("740", "740mm", "B");
        }
        return blankAsUnknown ? SlittingSliceSizeRule.unknown() : null;
    }

    private boolean isUnknownSlittingSliceSize(String text) {
        return "UNKNOWN".equals(text)
                || "UNCERTAIN".equals(text)
                || "NONE".equals(text)
                || "NA".equals(text)
                || "N/A".equals(text)
                || "不确定".equals(text)
                || "空".equals(text);
    }

    private String buildSlittingSliceSerialNo(String baseSliceSerialNo, SlittingSliceSizeRule sizeRule) {
        String baseNo = stripSlittingSizeSuffix(baseSliceSerialNo);
        if (StrUtil.isBlank(baseNo) || sizeRule == null || StrUtil.isBlank(sizeRule.suffix())) {
            return baseNo;
        }
        return baseNo + sizeRule.suffix();
    }

    private String stripSlittingSizeSuffix(String sliceSerialNo) {
        String text = StrUtil.trimToEmpty(sliceSerialNo).toUpperCase();
        if (text.matches(".*[PQRS]\\d{3}[AB]$")) {
            return text.substring(0, text.length() - 1);
        }
        return text;
    }

    private String mergeSlittingSliceAdjustRemark(String remark,
                                                  String originalSliceSerialNo,
                                                  String targetSliceSerialNo) {
        if (StrUtil.equalsIgnoreCase(originalSliceSerialNo, targetSliceSerialNo)) {
            return remark;
        }
        String adjustRemark = firstNotBlank(originalSliceSerialNo, "-")
                + " 调整 为 "
                + firstNotBlank(targetSliceSerialNo, "-");
        if (StrUtil.isBlank(remark)) {
            return adjustRemark;
        }
        if (remark.contains(adjustRemark)) {
            return remark;
        }
        return remark + "；" + adjustRemark;
    }

    private record SlittingSliceSizeRule(String sizeCode, String sizeName, String suffix) {

        private static SlittingSliceSizeRule unknown() {
            return new SlittingSliceSizeRule("UNKNOWN", "不确定", "");
        }
    }

