    private String resolveSlittingSegmentBatchNo(HcAdhesiveReportDO report, HcGrindingSecondDetailDO sourceDetail) {
        String segmentMark = resolveSlittingSegmentMark(report, sourceDetail);
        String motherBatchNo = firstNotBlank(
                report.getSourceBatchNo(),
                sourceDetail == null ? null : sourceDetail.getMotherBatchNo(),
                report.getParentProductionBatchNo(),
                resolveSlittingMotherBatch(firstNotBlank(report.getSourceProductionBatchNo(), report.getProductionBatchNo())));
        if (StrUtil.isNotBlank(motherBatchNo) && isSlittingSegmentMark(segmentMark)) {
            String normalizedMotherBatchNo = normalizeSlittingSegmentBatchNo(motherBatchNo);
            return normalizedMotherBatchNo.matches(".*[PQRS]$")
                    ? normalizedMotherBatchNo
                    : normalizedMotherBatchNo + segmentMark;
        }
        return normalizeSlittingSegmentBatchNo(firstNotBlank(
                report.getSourceProductionBatchNo(),
                report.getProductionBatchNo(),
                sourceDetail == null ? null : sourceDetail.getProductionBatchNo(),
                report.getSourceBatchNo()));
    }

    private String resolveSlittingSegmentMark(HcAdhesiveReportDO report, HcGrindingSecondDetailDO sourceDetail) {
        String detailSegmentMark = sourceDetail == null ? null : sourceDetail.getSegmentMark();
        String segmentMark = StrUtil.trimToEmpty(detailSegmentMark).toUpperCase();
        if (isSlittingSegmentMark(segmentMark)) {
            return segmentMark;
        }
        String segmentBatchNo = normalizeSlittingSegmentBatchNo(firstNotBlank(
                report.getSourceProductionBatchNo(),
                report.getProductionBatchNo(),
                sourceDetail == null ? null : sourceDetail.getProductionBatchNo()));
        if (StrUtil.isNotBlank(segmentBatchNo) && segmentBatchNo.matches(".*[PQRS]$")) {
            return segmentBatchNo.substring(segmentBatchNo.length() - 1);
        }
        return StrUtil.isBlank(segmentMark) ? null : segmentMark;
    }

    private boolean isSlittingSegmentMark(String segmentMark) {
        return StrUtil.isNotBlank(segmentMark) && segmentMark.matches("[PQRS]");
    }

    private int resolveSlittingStartSerialNo(List<HcSlittingSliceRecordDO> allOperationRecords,
                                             String motherBatchNo,
                                             Integer requestedStartSerialNo) {
        if (requestedStartSerialNo != null) {
            if (requestedStartSerialNo <= 0) {
                throw invalidParamException("起始流水号必须大于0");
            }
            return requestedStartSerialNo;
        }
        int maxUsedSerial = allOperationRecords.stream()
                .filter(record -> isSameSlittingMother(motherBatchNo, record))
                .map(record -> extractSlittingSliceSerialNo(record.getSliceSerialNo()))
                .filter(Objects::nonNull)
                .max(Integer::compareTo)
                .orElse(0);
        return maxUsedSerial + 1;
    }

    private String resolveSlittingMotherBatch(HcAdhesiveReportDO report) {
        return StrUtil.blankToDefault(firstNotBlank(report.getSourceBatchNo(), report.getParentProductionBatchNo()),
                resolveSlittingMotherBatch(firstNotBlank(report.getProductionBatchNo(), report.getSourceProductionBatchNo())));
    }

    private String resolveSlittingMotherRollBatchNo(HcSlittingSliceRecordDO record) {
        if (record == null) {
            return null;
        }
        return firstNotBlank(normalizeSlittingSegmentBatchNo(record.getSliceSerialNo()),
                normalizeSlittingSegmentBatchNo(record.getSourceProductionBatchNo()),
                normalizeSlittingSegmentBatchNo(record.getSourceBatchNo()),
                record.getSourceProductionBatchNo(),
                record.getSourceBatchNo());
    }

    private String resolveSlittingMotherBatch(String batchNo) {
        String segmentBatchNo = normalizeSlittingSegmentBatchNo(batchNo);
        if (StrUtil.isBlank(segmentBatchNo)) {
            return "";
        }
        return segmentBatchNo.matches(".*[PQRS]$")
                ? segmentBatchNo.substring(0, segmentBatchNo.length() - 1)
                : segmentBatchNo;
    }

    private boolean isSameSlittingMother(String motherBatchNo, HcAdhesiveReportDO report) {
        if (StrUtil.isBlank(motherBatchNo)) {
            return false;
        }
        String reportMotherBatchNo = resolveSlittingMotherBatch(report);
        return StrUtil.equalsIgnoreCase(motherBatchNo, reportMotherBatchNo);
    }

    private boolean isSameSlittingMother(String motherBatchNo, HcSlittingSliceRecordDO record) {
        if (StrUtil.isBlank(motherBatchNo)) {
            return false;
        }
        String recordMotherBatchNo = resolveSlittingMotherBatch(firstNotBlank(record.getSourceBatchNo(),
                record.getSourceProductionBatchNo(), record.getSliceSerialNo()));
        return StrUtil.equalsIgnoreCase(motherBatchNo, recordMotherBatchNo);
    }

    private String normalizeSlittingSegmentBatchNo(String batchNo) {
        String text = StrUtil.trimToEmpty(batchNo).toUpperCase();
        if (StrUtil.isBlank(text)) {
            return "";
        }
        text = stripSlittingSizeSuffix(text);
        text = text.replaceFirst("-S\\d+$", "");
        text = text.replaceFirst("-J\\d+$", "");
        if (text.matches(".*[PQRS]\\d{3}$")) {
            text = text.substring(0, text.length() - 3);
        }
        return text;
    }

    private Integer extractSlittingSliceSerialNo(String sliceSerialNo) {
        String text = stripSlittingSizeSuffix(sliceSerialNo);
        if (StrUtil.isBlank(text)) {
            return null;
        }
        String oldSerialNo = StrUtil.subAfter(text, "-S", true);
        if (StrUtil.isNotBlank(oldSerialNo) && oldSerialNo.matches("\\d+")) {
            return Integer.valueOf(oldSerialNo);
        }
        if (text.length() >= 3) {
            String suffix = text.substring(text.length() - 3);
            String prefix = text.substring(0, text.length() - 3);
            if (suffix.matches("\\d{3}") && prefix.matches(".*[PQRS]$")) {
                return Integer.valueOf(suffix);
            }
        }
        return null;
    }

