    private void savePressSlotCheckDetails(HcAdhesiveReportSaveReqVO reqVO,
                                           HcPlanOrderDO planOrder,
                                           HcPlanOrderOperationDO operation,
                                           Long reportId) {
        List<HcAdhesiveCheckItemReqVO> checkItems = reqVO.getCheckItems() == null
                ? Collections.emptyList() : reqVO.getCheckItems();
        if (checkItems.isEmpty()) {
            return;
        }
        List<HcPressSlotCheckDetailDO> detailList = new ArrayList<>();
        int index = 0;
        for (HcAdhesiveCheckItemReqVO item : checkItems) {
            index++;
            detailList.add(HcPressSlotCheckDetailDO.builder()
                    .tenantId(planOrder.getTenantId())
                    .pressSlotReportId(reportId)
                    .planId(planOrder.getId())
                    .planNo(planOrder.getPlanNo())
                    .planOperationId(operation.getId())
                    .itemCategory(item.getItemCategory())
                    .itemName(item.getItemName())
                    .standardValue(item.getStandardValue())
                    .actualValue(item.getActualValue())
                    .checkResult(firstNotBlank(item.getCheckResult(), "OK"))
                    .abnormalRemark(item.getAbnormalRemark())
                    .sortNo(item.getSortNo() == null ? index : item.getSortNo())
                    .build());
        }
        hcPressSlotCheckDetailMapper.insertBatch(detailList);
    }

