    private HcAdhesiveReportDO validateAdhesiveReportForIntermediate(Long adhesiveReportId,
                                                                     HcPlanOrderOperationDO operation) {
        if (adhesiveReportId == null) {
            return null;
        }
        HcAdhesiveReportDO adhesiveReport = hcAdhesiveReportMapper.selectById(adhesiveReportId);
        if (adhesiveReport == null || Boolean.TRUE.equals(adhesiveReport.getDeleted())) {
            throw invalidParamException("粘胶报工记录不存在，无法维护中间品记录单");
        }
        if (!Objects.equals(adhesiveReport.getPlanOperationId(), operation.getId())) {
            throw invalidParamException("中间品记录单与当前粘胶工序不一致");
        }
        return adhesiveReport;
    }

    private HcAdhesiveIntermediateRecordDO validateAdhesiveIntermediateRecord(Long recordId) {
        HcAdhesiveIntermediateRecordDO record = hcAdhesiveIntermediateRecordMapper.selectById(recordId);
        if (record == null || Boolean.TRUE.equals(record.getDeleted())) {
            throw invalidParamException("粘胶1中间品记录不存在");
        }
        return record;
    }

    private void readAdhesiveIntermediateHeader(HcAdhesiveIntermediateRecordDO record, Sheet sheet,
                                                DataFormatter formatter) {
        LocalDateTime importedProductionDate = parseIntermediateRecordDateTime(sheet, formatter);
        record.setProductionDate(importedProductionDate != null ? importedProductionDate
                : record.getProductionDate() == null ? LocalDateTime.now() : record.getProductionDate());
        Row modelRow = sheet.getRow(2);
        if (modelRow != null) {
            record.setModelCode(firstNotBlank(extractValueAfterLabel(formatter.formatCellValue(modelRow.getCell(0)), "型号"), record.getModelCode()));
            record.setMaterialCode(firstNotBlank(extractValueAfterLabel(formatter.formatCellValue(modelRow.getCell(3)), "料号"), record.getMaterialCode()));
            record.setBatchNo(firstNotBlank(extractValueAfterLabel(formatter.formatCellValue(modelRow.getCell(5)), "批号"), record.getBatchNo()));
            record.setProcessLength(firstNonNullDecimal(parseExcelDecimal(formatter.formatCellValue(modelRow.getCell(7))), record.getProcessLength()));
        }
        Row widthRow = sheet.getRow(3);
        if (widthRow != null) {
            record.setProductWidthMm(firstNonNullDecimal(parseExcelDecimal(formatter.formatCellValue(widthRow.getCell(0))), record.getProductWidthMm()));
        }
        Row positionRow = sheet.getRow(4);
        if (positionRow != null) {
            String positionText = formatter.formatCellValue(positionRow.getCell(0));
            record.setWidthStart(firstNonNullDecimal(parseExcelDecimal(extractValueAfterLabel(positionText, "开头")), record.getWidthStart()));
            record.setWidthMiddle(firstNonNullDecimal(parseExcelDecimal(extractValueAfterLabel(positionText, "中间")), record.getWidthMiddle()));
            record.setWidthEnd(firstNonNullDecimal(parseExcelDecimal(extractValueAfterLabel(positionText, "结尾")), record.getWidthEnd()));
        }
    }

    private HcAdhesiveIntermediateDetailDO readAdhesiveIntermediateDetail(Row row, DataFormatter formatter, int seq) {
        if (row == null) {
            return null;
        }
        String lengthText = formatter.formatCellValue(row.getCell(0));
        String trimmedLengthText = StrUtil.trim(lengthText);
        if (StrUtil.startWith(trimmedLengthText, "注：")
                || StrUtil.startWith(trimmedLengthText, "制定/修订部门")
                || StrUtil.startWith(trimmedLengthText, "本资料为")) {
            return null;
        }
        BigDecimal length = parseExcelDecimal(lengthText);
        BigDecimal left = parseExcelDecimal(formatter.formatCellValue(row.getCell(1)));
        BigDecimal right = parseExcelDecimal(formatter.formatCellValue(row.getCell(3)));
        String remark = formatter.formatCellValue(row.getCell(5));
        if (length == null && left == null && right == null && StrUtil.isBlank(remark)) {
            return null;
        }
        return HcAdhesiveIntermediateDetailDO.builder()
                .lengthMark(length)
                .leftThickness(left)
                .rightThickness(right)
                .remark(remark)
                .sortNo(seq)
                .build();
    }

    private void writeAdhesiveIntermediateTemplate(Workbook workbook, HcAdhesiveIntermediateRecordDO record,
                                                   List<HcAdhesiveIntermediateDetailDO> details) {
        Sheet templateSheet = workbook.getSheet(ADHESIVE_INTERMEDIATE_TEMPLATE_SHEET);
        if (templateSheet != null) {
            fillAdhesiveIntermediateTemplateSheet(workbook, templateSheet, record, details);
            return;
        }
        Sheet sheet = workbook.createSheet("粘胶1中间品记录表");
        int[] widths = {14, 14, 14, 14, 14, 18, 18, 18, 18};
        for (int i = 0; i < widths.length; i += 1) {
            sheet.setColumnWidth(i, widths[i] * 256);
        }
        int lastDetailRow = Math.max(59, 6 + Math.max(0, details.size() - 1));
        for (int i = 0; i <= lastDetailRow + 3; i += 1) {
            sheet.createRow(i).setHeightInPoints(i == 0 ? 28 : i == 5 ? 42 : 24);
        }
        CellStyle titleStyle = adhesiveIntermediateCellStyle(workbook, true, HorizontalAlignment.CENTER, true, false);
        CellStyle labelStyle = adhesiveIntermediateCellStyle(workbook, true, HorizontalAlignment.CENTER, true, true);
        CellStyle valueStyle = adhesiveIntermediateCellStyle(workbook, false, HorizontalAlignment.LEFT, true, false);
        CellStyle headerStyle = adhesiveIntermediateCellStyle(workbook, true, HorizontalAlignment.CENTER, true, true);
        CellStyle detailStyle = adhesiveIntermediateCellStyle(workbook, false, HorizontalAlignment.CENTER, true, false);
        CellStyle noteStyle = adhesiveIntermediateCellStyle(workbook, false, HorizontalAlignment.LEFT, true, false);

        mergeCell(sheet, 0, 0, 0, 8);
        setExcelCell(sheet.getRow(0), 0, "CMP软垫（W26P0100）粘胶1中间品记录表", titleStyle);
        mergeCell(sheet, 1, 1, 0, 3);
        mergeCell(sheet, 1, 1, 4, 8);
        setExcelCell(sheet.getRow(1), 0, "生产日期：" + formatAdhesiveIntermediateDate(record.getProductionDate()), valueStyle);
        setExcelCell(sheet.getRow(1), 4, "担当：" + firstNotBlank(record.getRecorderName(), "") + "        确认：" + firstNotBlank(record.getConfirmerName(), ""), valueStyle);
        mergeCell(sheet, 2, 2, 0, 2);
        mergeCell(sheet, 2, 2, 3, 4);
        mergeCell(sheet, 2, 2, 5, 6);
        mergeCell(sheet, 2, 2, 7, 8);
        setExcelCell(sheet.getRow(2), 0, "型号：" + firstNotBlank(record.getModelCode(), ""), labelStyle);
        setExcelCell(sheet.getRow(2), 3, "料号：" + firstNotBlank(record.getMaterialCode(), ""), labelStyle);
        setExcelCell(sheet.getRow(2), 5, "批号：" + firstNotBlank(record.getBatchNo(), ""), labelStyle);
        setExcelCell(sheet.getRow(2), 7, "加工米数m：" + toExcelText(record.getProcessLength()), labelStyle);
        mergeCell(sheet, 3, 3, 0, 8);
        setExcelCell(sheet.getRow(3), 0, "产品宽幅mm：" + toExcelText(record.getProductWidthMm()), valueStyle);
        mergeCell(sheet, 4, 4, 0, 8);
        setExcelCell(sheet.getRow(4), 0, "开头：" + toExcelText(record.getWidthStart()) + "                         中间：" + toExcelText(record.getWidthMiddle()) + "                   结尾：" + toExcelText(record.getWidthEnd()), valueStyle);

        mergeCell(sheet, 5, 5, 1, 2);
        mergeCell(sheet, 5, 5, 3, 4);
        mergeCell(sheet, 5, 5, 5, 8);
        setExcelCell(sheet.getRow(5), 0, "长度/m", headerStyle);
        setExcelCell(sheet.getRow(5), 1, "收卷左侧10cm含纸厚度mm\n（XXmm）", headerStyle);
        setExcelCell(sheet.getRow(5), 3, "收卷右侧10cm含纸厚度mm\n（XXmm）", headerStyle);
        setExcelCell(sheet.getRow(5), 5, "备注", headerStyle);
        for (int rowIndex = 6; rowIndex <= lastDetailRow; rowIndex += 1) {
            Row row = sheet.getRow(rowIndex);
            mergeCell(sheet, rowIndex, rowIndex, 1, 2);
            mergeCell(sheet, rowIndex, rowIndex, 3, 4);
            mergeCell(sheet, rowIndex, rowIndex, 5, 8);
            writeAdhesiveIntermediateDetailRow(row, details, rowIndex - 6, detailStyle);
        }
        mergeCell(sheet, lastDetailRow + 1, lastDetailRow + 1, 0, 8);
        mergeCell(sheet, lastDetailRow + 2, lastDetailRow + 2, 0, 8);
        mergeCell(sheet, lastDetailRow + 3, lastDetailRow + 3, 0, 8);
        setExcelCell(sheet.getRow(lastDetailRow + 1), 0, "注：1、此表由员工填写，当班生产时及时记录，班长以上管理人员确认；\n    2、每米测量厚度，记录产品实测值，测量位置为收卷左侧10cm,收卷右侧10cm；\n    3、整卷宽幅需要测量开头，中间，结尾处实测宽幅；", noteStyle);
        setExcelCell(sheet.getRow(lastDetailRow + 2), 0, "制定/修订部门：材料事业部    制定日期：2025.06.12   修订日期：2026.01.23     保管期限：10年 ", noteStyle);
        setExcelCell(sheet.getRow(lastDetailRow + 3), 0, "本资料为安徽禾臣新材料有限公司专有财产，非经许可，不得复制翻印或转交成其它形式使用", noteStyle);
    }

    private void writeAdhesiveIntermediateDetailRow(Row row,
                                                    List<HcAdhesiveIntermediateDetailDO> details,
                                                    int detailIndex, CellStyle style) {
        HcAdhesiveIntermediateDetailDO detail = detailIndex < details.size() ? details.get(detailIndex) : null;
        setExcelCell(row, 0, detail == null ? "" : toExcelText(detail.getLengthMark()), style);
        setExcelCell(row, 1, detail == null ? "" : toExcelText(detail.getLeftThickness()), style);
        setExcelCell(row, 3, detail == null ? "" : toExcelText(detail.getRightThickness()), style);
        setExcelCell(row, 5, detail == null ? "" : detail.getRemark(), style);
    }

    private void fillAdhesiveIntermediateTemplateSheet(Workbook workbook, Sheet sheet,
                                                       HcAdhesiveIntermediateRecordDO record,
                                                       List<HcAdhesiveIntermediateDetailDO> details) {
        int sheetIndex = workbook.getSheetIndex(sheet);
        if (sheetIndex >= 0) {
            workbook.setActiveSheet(sheetIndex);
            workbook.setSelectedTab(sheetIndex);
        }
        List<int[]> detailGroups = detectAdhesiveIntermediateDetailGroups(sheet);
        int detailEndRow = ensureAdhesiveIntermediateTemplateRows(sheet, details, detailGroups);
        setExcelCellValue(sheet, 1, 0, "生产日期：" + formatAdhesiveIntermediateDate(record.getProductionDate()));
        setExcelCellValue(sheet, 1, 4, " 担当：" + firstNotBlank(record.getRecorderName(), "") + "         确认：" + firstNotBlank(record.getConfirmerName(), ""));
        setExcelCellValue(sheet, 2, 0, "型号：" + firstNotBlank(record.getModelCode(), ""));
        setExcelCellValue(sheet, 2, 3, "料号：" + firstNotBlank(record.getMaterialCode(), ""));
        setExcelCellValue(sheet, 2, 5, "批号：" + firstNotBlank(record.getBatchNo(), ""));
        setExcelCellValue(sheet, 2, 7, "加工米数m:" + toExcelText(record.getProcessLength()));
        setExcelCellValue(sheet, 3, 0, "产品宽幅mm：" + toExcelText(record.getProductWidthMm()));
        setExcelCellValue(sheet, 4, 0, "开头：" + toExcelText(record.getWidthStart())
                + "                         中间：" + toExcelText(record.getWidthMiddle())
                + "                   结尾：" + toExcelText(record.getWidthEnd()));
        clearAdhesiveIntermediateTemplateDetails(sheet, detailGroups, detailEndRow);
        writeAdhesiveIntermediateTemplateDetails(sheet, detailGroups, detailEndRow, details);
    }

    private int ensureAdhesiveIntermediateTemplateRows(Sheet sheet, List<HcAdhesiveIntermediateDetailDO> details,
                                                       List<int[]> detailGroups) {
        int groupCount = Math.max(1, detailGroups.size());
        int rowsPerGroup = groupCount > 1
                ? Math.max(ADHESIVE_INTERMEDIATE_TEMPLATE_DETAIL_END_ROW - ADHESIVE_INTERMEDIATE_DETAIL_START_ROW + 1,
                (int) Math.ceil((details == null ? 0D : (double) details.size()) / groupCount))
                : Math.max(ADHESIVE_INTERMEDIATE_TEMPLATE_DETAIL_END_ROW - ADHESIVE_INTERMEDIATE_DETAIL_START_ROW + 1,
                details == null ? 0 : details.size());
        int targetEndRow = ADHESIVE_INTERMEDIATE_DETAIL_START_ROW + rowsPerGroup - 1;
        if (targetEndRow <= ADHESIVE_INTERMEDIATE_TEMPLATE_DETAIL_END_ROW) {
            return ADHESIVE_INTERMEDIATE_TEMPLATE_DETAIL_END_ROW;
        }
        int extraRows = targetEndRow - ADHESIVE_INTERMEDIATE_TEMPLATE_DETAIL_END_ROW;
        int lastRow = sheet.getLastRowNum();
        sheet.shiftRows(ADHESIVE_INTERMEDIATE_FOOTER_START_ROW, lastRow, extraRows, true, false);
        Row sourceRow = sheet.getRow(ADHESIVE_INTERMEDIATE_TEMPLATE_DETAIL_END_ROW);
        for (int rowIndex = ADHESIVE_INTERMEDIATE_TEMPLATE_DETAIL_END_ROW + 1; rowIndex <= targetEndRow; rowIndex += 1) {
            Row row = sheet.getRow(rowIndex);
            if (row == null) {
                row = sheet.createRow(rowIndex);
            }
            if (sourceRow != null) {
                row.setHeight(sourceRow.getHeight());
                short lastCellNum = sourceRow.getLastCellNum();
                for (int col = 0; col < lastCellNum; col += 1) {
                    Cell sourceCell = sourceRow.getCell(col);
                    Cell targetCell = row.getCell(col);
                    if (targetCell == null) {
                        targetCell = row.createCell(col);
                    }
                    if (sourceCell != null) {
                        targetCell.setCellStyle(sourceCell.getCellStyle());
                    }
                    targetCell.setBlank();
                }
                copyMergedRegionsForRow(sheet, ADHESIVE_INTERMEDIATE_TEMPLATE_DETAIL_END_ROW, rowIndex);
            }
        }
        return targetEndRow;
    }

    private List<int[]> detectAdhesiveIntermediateDetailGroups(Sheet sheet) {
        Row headerRow = sheet.getRow(ADHESIVE_INTERMEDIATE_DETAIL_START_ROW - 1);
        if (headerRow == null) {
            return Collections.singletonList(new int[]{0, 1, 3, 5});
        }
        List<Integer> lengthColumns = new ArrayList<>();
        short lastCellNum = headerRow.getLastCellNum();
        for (int col = 0; col < Math.max(lastCellNum, 9); col += 1) {
            if (StrUtil.contains(cellText(headerRow, col), "长度")) {
                lengthColumns.add(col);
            }
        }
        if (lengthColumns.isEmpty()) {
            lengthColumns.add(0);
        }
        List<int[]> groups = new ArrayList<>();
        for (int i = 0; i < lengthColumns.size(); i += 1) {
            int startCol = lengthColumns.get(i);
            int endCol = i + 1 < lengthColumns.size() ? lengthColumns.get(i + 1) - 1 : Math.max(lastCellNum, 9) - 1;
            int leftCol = findHeaderColumn(headerRow, startCol + 1, endCol, "左", "内侧");
            int rightCol = findHeaderColumn(headerRow, startCol + 1, endCol, "右", "外侧");
            int remarkCol = findHeaderColumn(headerRow, startCol + 1, endCol, "备注");
            groups.add(new int[]{
                    startCol,
                    leftCol >= 0 ? leftCol : startCol + 1,
                    rightCol >= 0 ? rightCol : startCol + 3,
                    remarkCol >= 0 ? remarkCol : startCol + 5
            });
        }
        return groups;
    }

    private int findHeaderColumn(Row headerRow, int startCol, int endCol, String... keywords) {
        for (int col = startCol; col <= endCol; col += 1) {
            String text = cellText(headerRow, col);
            for (String keyword : keywords) {
                if (StrUtil.contains(text, keyword)) {
                    return col;
                }
            }
        }
        return -1;
    }

    private void clearAdhesiveIntermediateTemplateDetails(Sheet sheet, List<int[]> detailGroups, int detailEndRow) {
        for (int rowIndex = ADHESIVE_INTERMEDIATE_DETAIL_START_ROW; rowIndex <= detailEndRow; rowIndex += 1) {
            Row row = sheet.getRow(rowIndex);
            if (row == null) {
                continue;
            }
            for (int[] group : detailGroups) {
                setExcelCellValue(row, group[0], "");
                setExcelCellValue(row, group[1], "");
                setExcelCellValue(row, group[2], "");
                setExcelCellValue(row, group[3], "");
            }
        }
    }

    private void writeAdhesiveIntermediateTemplateDetails(Sheet sheet, List<int[]> detailGroups, int detailEndRow,
                                                          List<HcAdhesiveIntermediateDetailDO> details) {
        if (details == null || details.isEmpty()) {
            return;
        }
        int groupCount = Math.max(1, detailGroups.size());
        int rowsPerGroup = groupCount > 1
                ? (int) Math.ceil((double) details.size() / groupCount)
                : details.size();
        int maxRows = detailEndRow - ADHESIVE_INTERMEDIATE_DETAIL_START_ROW + 1;
        for (int detailIndex = 0; detailIndex < details.size(); detailIndex += 1) {
            int groupIndex = groupCount > 1 ? Math.min(groupCount - 1, detailIndex / rowsPerGroup) : 0;
            int rowOffset = groupCount > 1 ? detailIndex % rowsPerGroup : detailIndex;
            if (rowOffset >= maxRows) {
                continue;
            }
            Row row = sheet.getRow(ADHESIVE_INTERMEDIATE_DETAIL_START_ROW + rowOffset);
            if (row == null) {
                row = sheet.createRow(ADHESIVE_INTERMEDIATE_DETAIL_START_ROW + rowOffset);
            }
            HcAdhesiveIntermediateDetailDO detail = details.get(detailIndex);
            int[] group = detailGroups.get(groupIndex);
            setExcelCellValue(row, group[0], toExcelText(detail.getLengthMark()));
            setExcelCellValue(row, group[1], toExcelText(detail.getLeftThickness()));
            setExcelCellValue(row, group[2], toExcelText(detail.getRightThickness()));
            setExcelCellValue(row, group[3], detail.getRemark());
        }
    }

    private void copyMergedRegionsForRow(Sheet sheet, int sourceRowIndex, int targetRowIndex) {
        List<CellRangeAddress> sourceRegions = sheet.getMergedRegions().stream()
                .filter(region -> region.getFirstRow() == sourceRowIndex && region.getLastRow() == sourceRowIndex)
                .map(CellRangeAddress::copy)
                .collect(Collectors.toList());
        for (CellRangeAddress sourceRegion : sourceRegions) {
            CellRangeAddress targetRegion = new CellRangeAddress(targetRowIndex, targetRowIndex,
                    sourceRegion.getFirstColumn(), sourceRegion.getLastColumn());
            if (!hasMergedRegion(sheet, targetRegion)) {
                sheet.addMergedRegion(targetRegion);
            }
        }
    }

    private boolean hasMergedRegion(Sheet sheet, CellRangeAddress targetRegion) {
        return sheet.getMergedRegions().stream().anyMatch(region ->
                region.getFirstRow() == targetRegion.getFirstRow()
                        && region.getLastRow() == targetRegion.getLastRow()
                        && region.getFirstColumn() == targetRegion.getFirstColumn()
                        && region.getLastColumn() == targetRegion.getLastColumn());
    }

    private void mergeRegionIfAbsent(Sheet sheet, int firstRow, int lastRow, int firstCol, int lastCol) {
        CellRangeAddress targetRegion = new CellRangeAddress(firstRow, lastRow, firstCol, lastCol);
        if (!hasMergedRegion(sheet, targetRegion)) {
            sheet.addMergedRegion(targetRegion);
        }
    }

    private String cellText(Row row, int col) {
        if (row == null || row.getCell(col) == null) {
            return "";
        }
        Cell cell = row.getCell(col);
        return cell.getCellType() == org.apache.poi.ss.usermodel.CellType.STRING
                ? StrUtil.blankToDefault(cell.getStringCellValue(), "")
                : StrUtil.blankToDefault(new DataFormatter().formatCellValue(cell), "");
    }

    private void setExcelCellValue(Sheet sheet, int rowIndex, int col, String value) {
        Row row = sheet.getRow(rowIndex);
        if (row == null) {
            row = sheet.createRow(rowIndex);
        }
        setExcelCellValue(row, col, value);
    }

    private void setExcelCellValue(Row row, int col, String value) {
        Cell cell = row.getCell(col);
        if (cell == null) {
            cell = row.createCell(col);
        }
        cell.setCellValue(StrUtil.blankToDefault(value, ""));
    }

    private String formatAdhesiveIntermediateDate(LocalDateTime dateTime) {
        return formatDateTimeWithSeconds(dateTime);
    }

    private CellStyle adhesiveIntermediateCellStyle(Workbook workbook, boolean bold, HorizontalAlignment align,
                                                    boolean border, boolean fill) {
        CellStyle style = workbook.createCellStyle();
        style.setAlignment(align);
        style.setVerticalAlignment(VerticalAlignment.CENTER);
        style.setWrapText(true);
        if (border) {
            style.setBorderTop(BorderStyle.THIN);
            style.setBorderRight(BorderStyle.THIN);
            style.setBorderBottom(BorderStyle.THIN);
            style.setBorderLeft(BorderStyle.THIN);
        }
        if (fill) {
            style.setFillForegroundColor(IndexedColors.GREY_25_PERCENT.getIndex());
            style.setFillPattern(FillPatternType.SOLID_FOREGROUND);
        }
        Font font = workbook.createFont();
        font.setFontName("Microsoft YaHei");
        font.setFontHeightInPoints((short) (bold ? 11 : 10));
        font.setBold(bold);
        style.setFont(font);
        return style;
    }

    private void setExcelCell(Row row, int col, String value, CellStyle style) {
        Cell cell = row.getCell(col);
        if (cell == null) {
            cell = row.createCell(col);
        }
        cell.setCellValue(StrUtil.blankToDefault(value, ""));
        cell.setCellStyle(style);
    }

    private void mergeCell(Sheet sheet, int firstRow, int lastRow, int firstCol, int lastCol) {
        sheet.addMergedRegion(new CellRangeAddress(firstRow, lastRow, firstCol, lastCol));
    }

    private BigDecimal parseExcelDecimal(String value) {
        if (StrUtil.isBlank(value)) {
            return null;
        }
        String normalized = value.replaceAll("[^0-9.\\-]", "");
        if (StrUtil.isBlank(normalized) || ".".equals(normalized) || "-".equals(normalized)) {
            return null;
        }
        try {
            return new BigDecimal(normalized);
        } catch (NumberFormatException ex) {
            return null;
        }
    }

    private String extractValueAfterLabel(String value, String label) {
        if (StrUtil.isBlank(value)) {
            return "";
        }
        String normalized = value.replace("：", ":");
        String prefix = label + ":";
        int index = normalized.indexOf(prefix);
        return index < 0 ? "" : normalized.substring(index + prefix.length()).trim();
    }

    private String toExcelText(BigDecimal value) {
        if (value == null) {
            return "";
        }
        return value.stripTrailingZeros().toPlainString();
    }

    private void fillAdhesiveIntermediateRecord(HcAdhesiveIntermediateRecordDO record,
                                                HcAdhesiveIntermediateSaveReqVO reqVO,
                                                HcPlanOrderDO planOrder,
                                                HcPlanOrderOperationDO operation,
                                                HcAdhesiveReportDO adhesiveReport) {
        record.setPlanId(planOrder.getId());
        record.setPlanNo(planOrder.getPlanNo());
        record.setPlanOperationId(operation.getId());
        record.setAdhesiveReportId(reqVO.getAdhesiveReportId());
        record.setProductionDate(reqVO.getProductionDate() != null ? reqVO.getProductionDate()
                : adhesiveReport == null || adhesiveReport.getReportDate() == null
                ? LocalDateTime.now() : adhesiveReport.getReportDate().atStartOfDay());
        record.setRecordTime(reqVO.getRecordTime() != null ? reqVO.getRecordTime() : LocalDateTime.now());
        record.setModelCode(firstNotBlank(reqVO.getModelCode(),
                adhesiveReport == null ? null : adhesiveReport.getModelCode(),
                planOrder.getModelCode(), planOrder.getModelName()));
        record.setMaterialCode(firstNotBlank(reqVO.getMaterialCode(),
                adhesiveReport == null ? null : adhesiveReport.getMaterialCode(),
                planOrder.getMaterialCode()));
        record.setBatchNo(firstNotBlank(reqVO.getBatchNo(),
                adhesiveReport == null ? null : adhesiveReport.getProductionBatchNo(),
                operation.getProductionBatchNo(), planOrder.getProductionBatchNo(),
                operation.getBatchNo(), planOrder.getBatchNo()));
        record.setProcessLength(firstNonNullDecimal(reqVO.getProcessLength(),
                adhesiveReport == null ? null : adhesiveReport.getOutputLength(),
                adhesiveReport == null ? null : adhesiveReport.getInputLength()));
        record.setProductWidthMm(reqVO.getProductWidthMm());
        record.setWidthStart(reqVO.getWidthStart());
        record.setWidthMiddle(reqVO.getWidthMiddle());
        record.setWidthEnd(reqVO.getWidthEnd());
        record.setRecorderName(reqVO.getRecorderName());
        record.setConfirmerName(reqVO.getConfirmerName());
        record.setRecordStatus(firstNotBlank(reqVO.getRecordStatus(), record.getRecordStatus(), "RECORDED"));
        record.setRemark(reqVO.getRemark());
        record.setExtraJson(reqVO.getExtraJson());
    }

    private String buildAdhesiveIntermediateConfirmExtra(String extraJson,
                                                         String confirmerName,
                                                         LocalDateTime confirmTime) {
        Map<String, Object> extra = parseStationRecordHeaderDataMap(extraJson);
        extra.put("confirmer", confirmerName);
        extra.put("confirmerName", confirmerName);
        extra.put("confirmerTime", formatDateTime(confirmTime));
        extra.put("docStatus", "CONFIRMED");
        extra.put("recordStatus", "CONFIRMED");
        return JsonUtils.toJsonString(extra);
    }

    private HcAdhesiveIntermediateRespVO buildAdhesiveIntermediateResp(HcAdhesiveIntermediateRecordDO record) {
        HcAdhesiveIntermediateRespVO resp = new HcAdhesiveIntermediateRespVO();
        resp.setId(record.getId());
        resp.setPlanId(record.getPlanId());
        resp.setPlanNo(record.getPlanNo());
        resp.setPlanOperationId(record.getPlanOperationId());
        resp.setAdhesiveReportId(record.getAdhesiveReportId());
        resp.setProductionDate(record.getProductionDate());
        resp.setRecordTime(record.getRecordTime());
        resp.setModelCode(record.getModelCode());
        resp.setMaterialCode(record.getMaterialCode());
        resp.setBatchNo(record.getBatchNo());
        resp.setProcessLength(record.getProcessLength());
        resp.setProductWidthMm(record.getProductWidthMm());
        resp.setWidthStart(record.getWidthStart());
        resp.setWidthMiddle(record.getWidthMiddle());
        resp.setWidthEnd(record.getWidthEnd());
        resp.setRecorderName(record.getRecorderName());
        resp.setConfirmerName(record.getConfirmerName());
        resp.setRecordStatus(record.getRecordStatus());
        resp.setRemark(record.getRemark());
        resp.setExtraJson(record.getExtraJson());
        // 历史记录空字段先从所属业务补齐，再使用模板兜底；已有值（包括0）不覆盖。
        if (StrUtil.isBlank(resp.getModelCode()) || StrUtil.isBlank(resp.getMaterialCode())
                || StrUtil.isBlank(resp.getBatchNo()) || resp.getProcessLength() == null) {
            HcPlanOrderDO plan = record.getPlanId() == null ? null : hcPlanOrderMapper.selectById(record.getPlanId());
            HcAdhesiveReportDO report = record.getAdhesiveReportId() == null ? null
                    : hcAdhesiveReportMapper.selectById(record.getAdhesiveReportId());
            resp.setModelCode(firstNotBlank(resp.getModelCode(), report == null ? null : report.getModelCode(),
                    plan == null ? null : firstNotBlank(plan.getModelCode(), plan.getModelName())));
            resp.setMaterialCode(firstNotBlank(resp.getMaterialCode(), report == null ? null : report.getMaterialCode(),
                    plan == null ? null : plan.getMaterialCode()));
            resp.setBatchNo(firstNotBlank(resp.getBatchNo(), report == null ? null : report.getSourceProductionBatchNo(),
                    report == null ? null : report.getProductionBatchNo(), plan == null ? null : plan.getProductionBatchNo()));
            if (resp.getProcessLength() == null && report != null) {
                resp.setProcessLength(firstNonNullDecimal(report.getOutputLength(), report.getInputLength()));
            }
        }
        applyAdhesiveIntermediateTemplate(resp);
        return resp;
    }

    /** 当前模板仅控制展示和空值兜底；不得用预设值生成操作人或确认签核。 */
    private void applyAdhesiveIntermediateTemplate(HcAdhesiveIntermediateRespVO resp) {
        HcStationFormDO form = resolveAdhesiveIntermediateStationFormConfig(resp.getModelCode());
        if (form == null) {
            return;
        }
        resp.setStationFormId(form.getId());
        resp.setStationFormCode(form.getFormCode());
        resp.setStationFormName(resolveAdhesiveIntermediateStationDisplayName(form));
        Map<String, Object> schema = parsePressSlotStationFormSchema(form);
        List<?> configured = schema.get("thicknessLabels") instanceof List<?> labels ? labels : Collections.emptyList();
        List<HcStationFormItemDO> legacy = hcStationFormItemMapper.selectByFormId(form.getId());
        List<String> titles = new ArrayList<>();
        for (int index = 0; index < 2; index++) {
            final int seq = 102 + index;
            String oldTitle = legacy.stream().filter(item -> Objects.equals(item.getItemSeq(), seq))
                    .map(HcStationFormItemDO::getItemName).filter(StrUtil::isNotBlank).findFirst().orElse(null);
            titles.add(firstNotBlank(index < configured.size() ? toStringValue(configured.get(index)) : null,
                    oldTitle, index == 0 ? "收卷左侧10cm含纸厚度mm（XXmm）" : "收卷右侧10cm含纸厚度mm（XXmm）"));
        }
        resp.setThicknessLabels(titles);
        Map<String, Object> preset = parseStationRecordHeaderDataMap(form.getPresetHeaderDataJson());
        Map<String, String> notes = new LinkedHashMap<>();
        List<String> noteKeys = List.of("fillInstructions", "revisionInfo", "copyrightNotice");
        for (int index = 0; index < noteKeys.size(); index++) {
            final int seq = 901 + index;
            String fallback = legacy.stream().filter(item -> Objects.equals(item.getItemSeq(), seq))
                    .map(HcStationFormItemDO::getItemName).filter(StrUtil::isNotBlank).findFirst().orElse("");
            String key = noteKeys.get(index);
            notes.put(key, preset.containsKey(key) ? StrUtil.nullToEmpty(toStringValue(preset.get(key))) : fallback);
        }
        resp.setFormNotes(notes);
        resp.setModelCode(firstNotBlank(resp.getModelCode(), toStringValue(preset.get("modelCode"))));
        resp.setMaterialCode(firstNotBlank(resp.getMaterialCode(), toStringValue(preset.get("materialCode"))));
        resp.setBatchNo(firstNotBlank(resp.getBatchNo(), toStringValue(preset.get("batchNo"))));
        if (resp.getProcessLength() == null) resp.setProcessLength(adhesiveIntermediatePresetNumber(preset, "processLength"));
        if (resp.getProductWidthMm() == null) resp.setProductWidthMm(adhesiveIntermediatePresetNumber(preset, "productWidthMm"));
        if (resp.getWidthStart() == null) resp.setWidthStart(adhesiveIntermediatePresetNumber(preset, "widthStart"));
        if (resp.getWidthMiddle() == null) resp.setWidthMiddle(adhesiveIntermediatePresetNumber(preset, "widthMiddle"));
        if (resp.getWidthEnd() == null) resp.setWidthEnd(adhesiveIntermediatePresetNumber(preset, "widthEnd"));
    }

    private BigDecimal adhesiveIntermediatePresetNumber(Map<String, Object> preset, String key) {
        String value = toStringValue(preset.get(key));
        if (StrUtil.isBlank(value)) return null;
        try {
            BigDecimal number = new BigDecimal(value.trim());
            return number.signum() >= 0 ? number : null;
        } catch (NumberFormatException ignored) {
            return null;
        }
    }

