    private void fillRoughTaskFromGrindingTables(HcRoughReportTaskRespVO task) {
        if (task == null || task.getPlanOperationId() == null) {
            return;
        }
        HcGrindingReportDO latestReport = hcGrindingReportMapper.selectLatestByPlanOperationId(task.getPlanOperationId());
        if (latestReport == null) {
            return;
        }
        task.setProductionDate(latestReport.getReportDate());
        task.setStartTime(firstNonNullDateTime(latestReport.getStartTime(), task.getStartTime()));
        task.setEndTime(firstNonNullDateTime(latestReport.getEndTime(), task.getEndTime()));
        task.setEquipmentId(firstNotNull(latestReport.getEquipmentId(), task.getEquipmentId()));
        task.setEquipmentCode(firstNotBlank(latestReport.getEquipmentCode(), task.getEquipmentCode()));
        task.setEquipmentName(firstNotBlank(latestReport.getEquipmentName(), task.getEquipmentName()));
        task.setGoodQty(firstNonNullDecimal(latestReport.getReportQty(), task.getGoodQty()));
        task.setRecorderName(firstNotBlank(latestReport.getRecorderName(), task.getRecorderName()));
        task.setRecorderTime(firstNonNullDateTime(latestReport.getRecorderTime(), task.getRecorderTime()));
        task.setConfirmerName(firstNotBlank(latestReport.getConfirmerName(), task.getConfirmerName()));
        task.setConfirmerTime(firstNonNullDateTime(latestReport.getConfirmerTime(), task.getConfirmerTime()));
        task.setReportRemark(firstNotBlank(latestReport.getRemark(), task.getReportRemark()));
        task.setExtraJson(buildRoughExtraJsonFromGrindingTables(latestReport));
    }

    private void fillRoughTaskQtime(HcRoughReportTaskRespVO task) {
        if (task == null) {
            return;
        }
        task.setQtime(hcQtimeEvaluationService.evaluateWetToGrinding(
                task.getPreviousEndTime(),
                task.getStartTime(),
                task.getModelCode(),
                task.getMotherModelCode(),
                task.getProductionBatchNo(),
                task.getParentProductionBatchNo(),
                task.getBatchNo()));
    }

    private String buildRoughExtraJsonFromGrindingTables(HcGrindingReportDO report) {
        Map<String, Object> extra = parseRoughExtraMap(report.getUiExtraJson());
        List<HcGrindingFirstDetailDO> firstDetails = hcGrindingFirstDetailMapper.selectListByReportId(report.getId());
        List<HcGrindingSecondDetailDO> secondDetails = hcGrindingSecondDetailMapper.selectListByReportId(report.getId());
        Map<String, String> firstSourceTypeByRowUid = new LinkedHashMap<>();
        for (HcGrindingFirstDetailDO firstDetail : firstDetails) {
            if (StrUtil.isNotBlank(firstDetail.getRowUid())) {
                firstSourceTypeByRowUid.put(firstDetail.getRowUid(), firstDetail.getSourceType());
            }
        }
        Map<Long, String> secondRowUidById = new LinkedHashMap<>();
        for (HcGrindingSecondDetailDO secondDetail : secondDetails) {
            if (secondDetail.getId() != null) {
                secondRowUidById.put(secondDetail.getId(), secondDetail.getRowUid());
            }
        }
        Map<String, Map<String, Object>> secondUiStateByRowUid = buildRoughSecondUiStateMap(extra.get("secondGrindingRowUiStates"));
        extra.put("reportForm", buildRoughReportFormExtra(report, extra.get("reportForm")));
        extra.put("materialUsageRows", buildRoughFirstDetailExtra(firstDetails));
        extra.put("secondGrindingRows", buildRoughSecondDetailExtra(secondDetails, firstSourceTypeByRowUid, secondUiStateByRowUid));
        extra.put("stockLedgerRows", buildRoughStockLedgerExtra(report.getId(), secondRowUidById));
        return JsonUtils.toJsonString(extra);
    }

