    private JsonNode parseRoughExtraRoot(String extraJson) {
        if (StrUtil.isBlank(extraJson)) {
            return null;
        }
        try {
            JsonNode root = JsonUtils.parseTree(extraJson);
            return root != null && root.isObject() ? root : null;
        } catch (RuntimeException ex) {
            return null;
        }
    }

    private Map<String, Object> parseRoughExtraMap(String extraJson) {
        if (StrUtil.isBlank(extraJson)) {
            return new LinkedHashMap<>();
        }
        Map<String, Object> parsed = JsonUtils.parseObjectQuietly(extraJson, new TypeReference<Map<String, Object>>() {});
        return parsed == null ? new LinkedHashMap<>() : new LinkedHashMap<>(parsed);
    }

    private String buildRoughUiExtraJson(HcRoughReportSaveReqVO reqVO) {
        Map<String, Object> extra = parseRoughExtraMap(reqVO.getExtraJson());
        if (extra.isEmpty()) {
            return null;
        }
        Map<String, Map<String, Object>> secondUiStates = buildRoughSecondUiStateMap(extra.get("secondGrindingRowUiStates"));
        secondUiStates.putAll(extractRoughSecondUiStates(extra.get("secondGrindingRows")));
        if (!secondUiStates.isEmpty()) {
            extra.put("secondGrindingRowUiStates", secondUiStates);
        }
        extra.remove("materialUsageRows");
        extra.remove("secondGrindingRows");
        extra.remove("stockLedgerRows");
        return extra.isEmpty() ? null : JsonUtils.toJsonString(extra);
    }

    @SuppressWarnings("unchecked")
    private Map<String, Map<String, Object>> buildRoughSecondUiStateMap(Object rawValue) {
        Map<String, Map<String, Object>> result = new LinkedHashMap<>();
        if (!(rawValue instanceof Map<?, ?> rawMap)) {
            return result;
        }
        for (Map.Entry<?, ?> entry : rawMap.entrySet()) {
            String rowUid = entry.getKey() == null ? "" : String.valueOf(entry.getKey());
            if (StrUtil.isBlank(rowUid) || !(entry.getValue() instanceof Map<?, ?> valueMap)) {
                continue;
            }
            result.put(rowUid, new LinkedHashMap<>((Map<String, Object>) valueMap));
        }
        return result;
    }

    @SuppressWarnings("unchecked")
    private Map<String, Map<String, Object>> extractRoughSecondUiStates(Object rowsValue) {
        Map<String, Map<String, Object>> result = new LinkedHashMap<>();
        if (!(rowsValue instanceof List<?> rows)) {
            return result;
        }
        for (Object rowObj : rows) {
            if (!(rowObj instanceof Map<?, ?> sourceRow)) {
                continue;
            }
            Map<String, Object> row = (Map<String, Object>) sourceRow;
            String rowUid = row.get("id") == null ? "" : String.valueOf(row.get("id"));
            if (StrUtil.isBlank(rowUid)) {
                continue;
            }
            Map<String, Object> state = new LinkedHashMap<>();
            copyRoughSecondUiState(row, state, "printStatus");
            copyRoughSecondUiState(row, state, "printTime");
            copyRoughSecondUiState(row, state, "printCount");
            copyRoughSecondUiState(row, state, "confirmStatus");
            copyRoughSecondUiState(row, state, "confirmTime");
            copyRoughSecondUiState(row, state, "confirmedBatchNo");
            if (!state.isEmpty()) {
                result.put(rowUid, state);
            }
        }
        return result;
    }

    private void copyRoughSecondUiState(Map<String, Object> source, Map<String, Object> target, String key) {
        Object value = source.get(key);
        if (value != null) {
            target.put(key, value);
        }
    }

    private String normalizeRoughSecondConfirmStatus(String status) {
        String value = StrUtil.trimToEmpty(status);
        if (StrUtil.isBlank(value)) {
            return null;
        }
        if ("已确认".equals(value) || "CONFIRMED".equalsIgnoreCase(value)) {
            return "CONFIRMED";
        }
        if ("未确认".equals(value) || "UNCONFIRMED".equalsIgnoreCase(value)) {
            return "UNCONFIRMED";
        }
        return value;
    }

    private String toRoughSecondUiConfirmStatus(String status) {
        String value = StrUtil.trimToEmpty(status);
        if ("CONFIRMED".equalsIgnoreCase(value)) {
            return "已确认";
        }
        if ("UNCONFIRMED".equalsIgnoreCase(value)) {
            return "未确认";
        }
        return value;
    }

    private RoughGrindingAggregate buildRoughAggregate(JsonNode roughRoot,
                                                       String rowField,
                                                       BigDecimal fallbackProcessLength,
                                                       BigDecimal fallbackLossLength,
                                                       BigDecimal fallbackOutputLength,
                                                       BigDecimal fallbackNapSampleLength,
                                                       String fallbackSandpaperBatchNo,
                                                       BigDecimal fallbackSandpaperLife,
                                                       BigDecimal fallbackSandpaperLifeDays) {
        JsonNode rows = roughRoot == null ? null : roughRoot.path(rowField);
        if (rows == null || !rows.isArray() || rows.isEmpty()) {
            return new RoughGrindingAggregate(fallbackProcessLength, fallbackLossLength, fallbackOutputLength,
                    fallbackNapSampleLength, fallbackSandpaperBatchNo, fallbackSandpaperLife, fallbackSandpaperLifeDays);
        }
        BigDecimal processLength = BigDecimal.ZERO;
        BigDecimal lossLength = BigDecimal.ZERO;
        BigDecimal outputLength = BigDecimal.ZERO;
        BigDecimal napSampleLength = BigDecimal.ZERO;
        String lastSandpaperBatchNo = fallbackSandpaperBatchNo;
        BigDecimal lastSandpaperLife = fallbackSandpaperLife;
        BigDecimal lastSandpaperLifeDays = fallbackSandpaperLifeDays;
        for (JsonNode row : rows) {
            processLength = processLength.add(zeroIfNull(readJsonDecimal(row, "processLength")));
            lossLength = lossLength.add(zeroIfNull(readJsonDecimal(row, "lossLength")));
            outputLength = outputLength.add(zeroIfNull(readJsonDecimal(row, "outputLength")));
            napSampleLength = napSampleLength.add(zeroIfNull(readJsonDecimal(row, "napSampleLength")));
            String sandpaperBatchNo = readJsonText(row, "sandpaperBatchNo");
            if (StrUtil.isNotBlank(sandpaperBatchNo)) {
                lastSandpaperBatchNo = sandpaperBatchNo;
            }
            BigDecimal sandpaperLife = readJsonDecimal(row, "sandpaperLife");
            if (sandpaperLife != null) {
                lastSandpaperLife = sandpaperLife;
            }
            BigDecimal sandpaperLifeDays = readJsonDecimal(row, "sandpaperLifeDays");
            if (sandpaperLifeDays != null) {
                lastSandpaperLifeDays = sandpaperLifeDays;
            }
        }
        return new RoughGrindingAggregate(processLength, lossLength, outputLength, napSampleLength,
                lastSandpaperBatchNo, lastSandpaperLife, lastSandpaperLifeDays);
    }

    private BigDecimal readJsonDecimal(JsonNode node, String fieldName) {
        if (node == null) {
            return null;
        }
        JsonNode field = node.path(fieldName);
        if (field.isMissingNode() || field.isNull()) {
            return null;
        }
        if (field.isNumber()) {
            return field.decimalValue();
        }
        String text = field.asText("");
        if (StrUtil.isBlank(text)) {
            return null;
        }
        try {
            return new BigDecimal(text);
        } catch (NumberFormatException ex) {
            return null;
        }
    }

    private LocalDateTime readJsonDateTime(JsonNode node, String fieldName) {
        String text = readJsonText(node, fieldName);
        if (StrUtil.isBlank(text)) {
            return null;
        }
        try {
            return LocalDateTime.parse(text.replace(' ', 'T'));
        } catch (RuntimeException ex) {
            return null;
        }
    }

    private BigDecimal zeroIfNull(BigDecimal value) {
        return value == null ? BigDecimal.ZERO : value;
    }

    private String buildRoughFinishRemark(RoughGrindingAggregate firstAggregate,
                                          RoughGrindingAggregate secondAggregate,
                                          String userRemark) {
        List<String> parts = new ArrayList<>();
        parts.add("磨皮完成");
        parts.add("一次磨皮总数：" + buildRoughAggregateRemark(firstAggregate));
        parts.add("二次磨皮总数：" + buildRoughAggregateRemark(secondAggregate));
        parts.add("报工量：" + formatDecimal(zeroIfNull(secondAggregate == null ? null : secondAggregate.processLength)) + "m");
        if (StrUtil.isNotBlank(userRemark)) {
            parts.add("备注：" + userRemark.trim());
        }
        return String.join("；", parts);
    }

    private String buildAdhesiveFinishRemark(int reportCount,
                                             BigDecimal totalInputLength,
                                             BigDecimal totalLossLength,
                                             BigDecimal totalOutputLength,
                                             BigDecimal totalNapSampleLength,
                                             String userRemark) {
        List<String> parts = new ArrayList<>();
        parts.add("粘双面胶完成");
        parts.add("报工记录：" + reportCount + "条");
        parts.add("加工：" + formatDecimal(totalInputLength) + "m");
        parts.add("损耗：" + formatDecimal(totalLossLength) + "m");
        parts.add("产出：" + formatDecimal(totalOutputLength) + "m");
        parts.add("NAP留样：" + formatDecimal(totalNapSampleLength) + "m");
        if (StrUtil.isNotBlank(userRemark)) {
            parts.add("备注：" + userRemark.trim());
        }
        return String.join("；", parts);
    }

    private String buildRoughAggregateRemark(RoughGrindingAggregate aggregate) {
        return "加工" + formatDecimal(zeroIfNull(aggregate == null ? null : aggregate.processLength)) + "m"
                + "、损耗" + formatDecimal(zeroIfNull(aggregate == null ? null : aggregate.lossLength)) + "m"
                + "、产出" + formatDecimal(zeroIfNull(aggregate == null ? null : aggregate.outputLength)) + "m"
                + "、NAP留样" + formatDecimal(zeroIfNull(aggregate == null ? null : aggregate.napSampleLength)) + "m";
    }

    private String formatDecimal(BigDecimal value) {
        return zeroIfNull(value).stripTrailingZeros().toPlainString();
    }

    private BigDecimal firstNonNullDecimal(BigDecimal... values) {
        if (values == null) {
            return null;
        }
        for (BigDecimal value : values) {
            if (value != null) {
                return value;
            }
        }
        return null;
    }

    @SafeVarargs
    private final <T> T firstNonNull(T... values) {
        if (values == null) {
            return null;
        }
        for (T value : values) {
            if (value != null) {
                return value;
            }
        }
        return null;
    }

