    private List<HcWetPassWorkItemRespVO> buildWetPresetDetails(HcStationFormDO form) {
        if (form == null) {
            return List.of();
        }
        if (StrUtil.isNotBlank(form.getPresetItemsJson())) {
            List<HcWetPassWorkItemRespVO> presetItems = parseWetPresetItems(form.getPresetItemsJson());
            if (!presetItems.isEmpty()) {
                return presetItems;
            }
        }
        if (!isWetSolidSemiForm(form) && !isWetOvenSemiForm(form)) {
            return List.of();
        }
        int totalLength = 600;
        int rowStep = 2;
        if (StrUtil.isNotBlank(form.getSchemaJson())) {
            JsonNode schema = JsonUtils.parseTree(form.getSchemaJson());
            rowStep = Math.max(1, schema.path("rowStep").asInt(2));
            int defaultGeneratedLength = schema.path("defaultGeneratedLength").asInt(0);
            int defaultRowCount = schema.path("defaultRowCount").asInt(300);
            totalLength = defaultGeneratedLength > 0 ? defaultGeneratedLength : rowStep * defaultRowCount;
        }
        int rowCount = Math.max(1, (int) Math.ceil(totalLength / (double) rowStep));
        List<HcWetPassWorkItemRespVO> result = new ArrayList<>();
        for (int index = 0; index < rowCount; index++) {
            HcWetPassWorkItemRespVO item = new HcWetPassWorkItemRespVO();
            item.setItemSeq(index + 1);
            item.setCategory("");
            item.setNode("");
            item.setItem("");
            item.setStandard("");
            item.setValueMode("TEXT");
            item.setDualLabel1("");
            item.setDualLabel2("");
            item.setActualValue("");
            item.setActualValue2("");
            item.setStatus("OK");
            item.setRemark("");
            result.add(item);
        }
        return result;
    }

    private List<HcWetPassWorkItemRespVO> parseWetPresetItems(String presetItemsJson) {
        JsonNode root = JsonUtils.parseTree(presetItemsJson);
        if (root == null || !root.isArray()) {
            return List.of();
        }
        List<HcWetPassWorkItemRespVO> result = new ArrayList<>();
        for (JsonNode itemNode : root) {
            if (itemNode == null || itemNode.isNull()) {
                continue;
            }
            HcWetPassWorkItemRespVO item = new HcWetPassWorkItemRespVO();
            item.setItemSeq(itemNode.path("itemSeq").asInt(0));
            item.setCategory(readJsonText(itemNode, "itemCategory"));
            item.setNode(readJsonText(itemNode, "stepNode"));
            item.setItem(readJsonText(itemNode, "itemName"));
            item.setStandard(readJsonText(itemNode, "standardText"));
            item.setValueMode(readJsonText(itemNode, "valueMode"));
            item.setDualLabel1(readJsonText(itemNode, "dualLabel1"));
            item.setDualLabel2(readJsonText(itemNode, "dualLabel2"));
            item.setActualValue(readJsonText(itemNode, "actualValue"));
            item.setActualValue2(readJsonText(itemNode, "actualValue2"));
            item.setStatus(StrUtil.blankToDefault(readJsonText(itemNode, "defaultResult"), "OK"));
            item.setRemark(readJsonText(itemNode, "remark"));
            result.add(item);
        }
        return result;
    }

    private String readJsonText(JsonNode node, String fieldName) {
        JsonNode field = node.path(fieldName);
        return field.isMissingNode() || field.isNull() ? "" : field.asText("");
    }

    private boolean isWetSolidSemiForm(HcStationFormDO form) {
        return isWetSemiForm(form, "WET_SOLID_SEMI", "wet-solid-semi-v1", "solid");
    }

    private boolean isWetOvenSemiForm(HcStationFormDO form) {
        return isWetSemiForm(form, "WET_OVEN_SEMI", "wet-oven-semi-v1", "oven");
    }

    private boolean isWetSemiForm(HcStationFormDO form,
                                  String codePrefix,
                                  String presetTemplate,
                                  String semiType) {
        if (form == null) {
            return false;
        }
        String formCode = StrUtil.nullToEmpty(form.getFormCode()).toUpperCase();
        if (formCode.equals(codePrefix) || formCode.startsWith(codePrefix + "_")) {
            return true;
        }
        if (StrUtil.isBlank(form.getSchemaJson())) {
            return false;
        }
        JsonNode schema = JsonUtils.parseTree(form.getSchemaJson());
        if (schema == null) {
            return false;
        }
        String schemaPreset = readJsonText(schema, "presetTemplate");
        String schemaVersion = readJsonText(schema, "version");
        String schemaSemiType = readJsonText(schema, "semiType");
        return StrUtil.equalsIgnoreCase(presetTemplate, schemaPreset)
                || StrUtil.equalsIgnoreCase(presetTemplate, schemaVersion)
                || StrUtil.equalsIgnoreCase(semiType, schemaSemiType);
    }

    private String buildSecondGrindingProductionBatchNo(String motherBatchNo, String segmentMark) {
        String baseBatchNo = StrUtil.trimToEmpty(motherBatchNo);
        String segmentCode = StrUtil.trimToEmpty(segmentMark).toUpperCase();
        if (StrUtil.isBlank(baseBatchNo) || StrUtil.isBlank(segmentCode)) {
            return "";
        }
        return baseBatchNo + segmentCode;
    }

    private String buildWetPresetHeaderDataJson(HcStationFormDO form) {
        if (form == null || StrUtil.isBlank(form.getSchemaJson())) {
            return null;
        }
        JsonNode schema = JsonUtils.parseTree(form.getSchemaJson());
        Map<String, Object> header = new LinkedHashMap<>();
        JsonNode headerFields = schema.path("headerFields");
        if (headerFields.isArray()) {
            headerFields.forEach(fieldNode -> {
                if (fieldNode == null || !fieldNode.isTextual()) {
                    return;
                }
                String field = fieldNode.asText();
                if (StrUtil.isBlank(field)) {
                    return;
                }
                header.put(field, "");
            });
        }
        if (WET_FIRST_INSPECTION_FORM_CODE.equals(form.getFormCode())) {
            header.put("status", "PENDING");
            header.putIfAbsent("result", "");
            header.putIfAbsent("inspectionDesc", "");
            header.putIfAbsent("inspectTime", "");
            header.putIfAbsent("inspector", "");
        }
        if (WET_PORE_SELF_CHECK_FORM_CODE.equals(form.getFormCode())) {
            header.put("records", Collections.emptyList());
        }
        if (isWetSolidSemiForm(form) || isWetOvenSemiForm(form)) {
            int rowStep = schema.path("rowStep").asInt(2);
            int defaultGeneratedLength = schema.path("defaultGeneratedLength").asInt(0);
            int defaultRowCount = schema.path("defaultRowCount").asInt(300);
            int generatedLength = defaultGeneratedLength > 0 ? defaultGeneratedLength : rowStep * defaultRowCount;
            header.put("generatedLength", generatedLength);
            header.putIfAbsent("finalResult", "");
            header.putIfAbsent("semiWidth", "");
            if (isWetSolidSemiForm(form)) {
                header.putIfAbsent("poreDevelopment", "");
            }
        }
        return header.isEmpty() ? null : JsonUtils.toJsonString(header);
    }

